insert into public.exercise_instruction_translations (exercise_id, language, instructions)
values
  ('3_4_Sit-Up', 'de', array['Leg dich mit angewinkelten Knien auf den Rücken und klemm deine Füße unter etwas, das sie festhält.', 'Nimm die Hände hinter den Kopf oder seitlich an den Kopf. Dein Rücken liegt auf dem Boden: Das ist die Ausgangsposition.', 'Beuge Hüfte und Wirbelsäule und richte den Oberkörper zu den Knien hin auf.', 'Oben steht dein Oberkörper senkrecht zum Boden. Geh dann wieder nach unten, aber nur drei Viertel des Weges.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('90_90_Hamstring', 'de', array['Leg dich auf den Rücken und streck ein Bein flach auf dem Boden aus.', 'Zieh das andere Bein an, bis Hüfte und Knie jeweils 90 Grad gebeugt sind. Wenn nötig, stütz das Bein mit den Händen. Das ist die Ausgangsposition.', 'Streck dieses Bein gerade nach oben in die Luft und halte oben kurz. Beuge es dann zurück in die Ausgangsposition.', 'Mach 10-20 Wiederholungen und wechsle dann das Bein.']::text[]),
  ('Ab_Crunch_Machine', 'de', array['Stell einen leichten Widerstand ein und setz dich in die Maschine. Schieb die Füße unter die Polster und greif die oberen Griffe. Leg den Trizeps auf die Armpolster, die Ellbogen sind 90 Grad gebeugt. Das ist die Ausgangsposition.', 'Roll den Oberkörper ein und heb gleichzeitig die Beine an. Atme dabei aus. Tipp: Beweg dich langsam und kontrolliert. Lass den Bauch die Arbeit machen und halte Beine und Füße locker.', 'Halte eine Sekunde und geh dann beim Einatmen langsam zurück in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Ab_Roller', 'de', array['Knie dich auf den Boden und nimm den Bauchroller in beide Hände.', 'Setz den Roller vor dir auf dem Boden ab, sodass du auf Händen und Knien bist wie bei einem Liegestütz auf den Knien. Das ist die Ausgangsposition.', 'Roll langsam gerade nach vorn, bis dein Körper lang gestreckt ist. Tipp: Geh so tief, wie du kannst, ohne dass dein Körper den Boden berührt. Atme auf dem Weg nach vorn ein.', 'Halte die Streckung kurz und zieh dich dann beim Ausatmen zurück in die Ausgangsposition. Tipp: Lass dir Zeit und halte den Bauch die ganze Zeit angespannt.']::text[]),
  ('Adductor', 'de', array['Leg dich auf den Bauch und leg ein Bein auf eine Faszienrolle.', 'Dreh das Bein, bis die Innenseite des Oberschenkels auf der Rolle liegt. Gib so viel Gewicht auf die Rolle, wie du aushältst.', 'Lass die Muskeln an der Oberschenkelinnenseite möglichst locker und roll zwischen Hüfte und Knie hin und her. Bleib auf verspannten Stellen 10-30 Sekunden. Mach danach das andere Bein.']::text[]),
  ('Adductor_Groin', 'de', array['Leg dich auf den Rücken und streck die Füße zur Decke.', 'Lass deinen Partner deine Füße oder Knöchel halten. Spreiz die Beine so weit, wie es geht. Das ist die Ausgangsposition.', 'Versuch 10 Sekunden oder länger, die Beine zusammenzudrücken, während dein Partner dagegenhält.', 'Lass dann die Beinmuskeln locker, während dein Partner deine Füße weiter auseinanderdrückt, nur so weit, wie es für dich angenehm ist. Sag deinem Partner rechtzeitig, wenn die Dehnung reicht, damit du dich nicht überdehnst oder verletzt.']::text[]),
  ('Advanced_Kettlebell_Windmill', 'de', array['Bring eine Kettlebell mit einem Arm zur Schulter und drück sie über den Kopf.', 'Halte diesen Arm die ganze Zeit durchgestreckt und schieb das Gesäß zur Seite der gestreckten Kettlebell hinaus. Der freie Arm liegt hinter dem Rücken, die Füße drehst du in einem Winkel von fünfundvierzig Grad vom Arm mit der Kettlebell weg.', 'Geh so tief hinunter, wie du kannst.', 'Halte eine Sekunde und komm auf demselben Weg zurück in die Ausgangsposition.']::text[]),
  ('Air_Bike', 'de', array['Leg dich flach auf den Rücken und drück den unteren Rücken in den Boden. Nimm die Hände neben den Kopf und achte darauf, bei der Übung nicht am Nacken zu ziehen. Heb dann die Schultern an wie beim Crunch.', 'Zieh die Knie hoch, bis die Oberschenkel senkrecht stehen und die Unterschenkel parallel zum Boden sind. Das ist die Ausgangsposition.', 'Tritt jetzt langsam wie beim Radfahren: Das rechte Bein streckst du nach vorn, das linke Knie ziehst du gleichzeitig heran. Atme aus und dreh dich im Crunch zur Seite, bis der rechte Ellbogen nah am linken Knie ist.', 'Atme ein und komm zurück in die Ausgangsposition.', 'Tritt weiter und dreh dich im Crunch zur anderen Seite, sodass der linke Ellbogen nah ans rechte Knie kommt. Atme dabei aus.', 'Wechsle so weiter die Seiten, bis du alle vorgesehenen Wiederholungen pro Seite gemacht hast.']::text[]),
  ('All_Fours_Quad_Stretch', 'de', array['Geh in den Vierfüßlerstand. Heb ein Bein vom Boden und fass den Fuß mit der Hand.', 'Halte den Fuß oder Knöchel mit der Hand fest und lass das Knie ganz gebeugt. So dehnst du Quadrizeps und Hüftbeuger.', 'Konzentrier dich darauf, die Hüfte zu strecken und zum Boden zu schieben. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Alternate_Hammer_Curl', 'de', array['Stell dich aufrecht hin, in jeder Hand eine Kurzhantel, die Arme hängen gestreckt herab. Die Ellbogen bleiben nah am Körper.', 'Dreh die Handflächen zum Körper. Das ist die Ausgangsposition.', 'Halte den Oberarm ruhig, atme aus und beuge die rechte Kurzhantel nach vorn, indem du den Bizeps anspannst. Geh weiter, bis der Bizeps ganz angespannt ist und die Hantel auf Schulterhöhe steht. Spann den Bizeps dort eine Sekunde fest an. Tipp: Nur der Unterarm bewegt sich.', 'Atme ein und senke die Hantel langsam in die Ausgangsposition.', 'Mach dasselbe mit der linken Hand. Beide Seiten zusammen sind eine Wiederholung.', 'Wechsle so weiter die Hände, bis du die vorgesehene Zahl an Wiederholungen gemacht hast.']::text[]),
  ('Alternate_Heel_Touchers', 'de', array['Leg dich auf den Rücken, die Knie gebeugt, die Füße etwa 18-24 Inches auseinander auf dem Boden. Die Arme liegen gestreckt neben dem Körper. Das ist die Ausgangsposition.', 'Atme aus, heb den Oberkörper etwa 3-4 Inches nach vorn oben zur rechten Seite und berühr deine rechte Ferse. Halte die Spannung eine Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition.', 'Atme aus, heb den Oberkörper etwa 3-4 Inches nach vorn oben zur linken Seite und berühr deine linke Ferse. Halte die Spannung eine Sekunde und geh beim Einatmen zurück in die Ausgangsposition. Hast du beide Fersen berührt, zählt das als 1 Wiederholung.', 'Wechsle so weiter die Seiten, bis alle vorgesehenen Wiederholungen gemacht sind.']::text[]),
  ('Alternate_Incline_Dumbbell_Curl', 'de', array['Setz dich auf eine Schrägbank, in jeder Hand eine Kurzhantel, die Arme hängen gestreckt herab. Tipp: Halte die Ellbogen nah am Körper. Das ist die Ausgangsposition.', 'Halte den Oberarm ruhig, atme aus und beuge die rechte Kurzhantel nach vorn, indem du den Bizeps anspannst. Dreh die Hand dabei, bis die Handfläche nach oben zeigt. Geh weiter, bis der Bizeps ganz angespannt ist und die Hantel auf Schulterhöhe steht. Spann den Bizeps dort eine Sekunde fest an. Tipp: Nur der Unterarm bewegt sich.', 'Atme ein und senke die Hantel langsam in die Ausgangsposition.', 'Mach dasselbe mit der linken Hand. Beide Seiten zusammen sind eine Wiederholung.', 'Wechsle so weiter die Hände, bis du die vorgesehene Zahl an Wiederholungen gemacht hast.']::text[]),
  ('Alternate_Leg_Diagonal_Bound', 'de', array['Stell dich bequem hin, einen Fuß etwas vor dem anderen.', 'Drück dich mit dem vorderen Bein ab und reiß das andere Knie nach vorn und so hoch wie möglich, bevor du landest. Versuch, mit jedem Sprung möglichst weit zur Seite zu kommen.', 'Eine Linie auf dem Boden kann dir helfen, die Weite von Seite zu Seite einzuschätzen.', 'Mach das Gleiche noch einmal mit dem anderen Bein.']::text[]),
  ('Alternating_Cable_Shoulder_Press', 'de', array['Stell die Rollen des Kabelzugs ganz nach unten und wähl ein passendes Gewicht.', 'Nimm die Griffe und bring sie auf Schulterhöhe, die Handflächen zeigen nach vorn. Das ist die Ausgangsposition.', 'Halte Kopf und Brust aufrecht, streck einen Ellbogen und drück diese Seite gerade über den Kopf.', 'Halte oben kurz, geh zurück in die Ausgangsposition und mach dasselbe auf der anderen Seite.']::text[]),
  ('Alternating_Deltoid_Raise', 'de', array['Stell dich hin und halte zwei Kurzhanteln seitlich am Körper.', 'Heb die Hanteln mit leicht gebeugten Ellbogen gerade nach vorn bis auf Schulterhöhe. Hol keinen Schwung und schummle nicht.', 'Senke die Hanteln wieder an die Seiten.', 'Bei der nächsten Wiederholung hebst du die Hanteln seitlich an, vom Körper weg bis etwa auf Schulterhöhe.', 'Senke sie wieder in die Ausgangsposition und wechsle weiter zwischen vorn und seitlich.']::text[]),
  ('Alternating_Floor_Press', 'de', array['Leg dich auf den Boden, neben jeder Schulter eine Kettlebell.', 'Bring erst die eine, dann die andere Kettlebell auf der Brust in Position. Greif sie am Griff, die Handflächen zeigen nach vorn.', 'Streck beide Arme, sodass du die Kettlebells über der Brust hältst. Senke dann eine Kettlebell zur Brust und dreh dabei das Handgelenk zur Kettlebell hin, die oben gestreckt bleibt.', 'Drück die Kettlebell wieder hoch und mach dasselbe auf der anderen Seite.']::text[]),
  ('Alternating_Hang_Clean', 'de', array['Stell zwei Kettlebells zwischen deine Füße. Für die Ausgangsposition schiebst du das Gesäß nach hinten und schaust geradeaus.', 'Bring eine Kettlebell zur Schulter, die andere hängt am gestreckten Arm. Dafür streckst du Beine und Hüfte und ziehst die Kettlebell zur Schulter hoch. Dreh dabei das Handgelenk.', 'Lass die Kettlebell von der Schulter in den Hang herab und bring die andere zur Schulter. Mach so weiter.']::text[]),
  ('Alternating_Kettlebell_Press', 'de', array['Bring zwei Kettlebells zu den Schultern. Dafür streckst du Beine und Hüfte und ziehst die Kettlebells zu den Schultern hoch. Dreh dabei die Handgelenke.', 'Streck einen Ellbogen und drück diese Kettlebell gerade über den Kopf. Dreh sie dabei, bis die Handfläche nach vorn zeigt. Die andere Kettlebell bleibt ruhig an der Schulter.', 'Senke die gedrückte Kettlebell in die Ausgangsposition und drück sofort mit dem anderen Arm.']::text[]),
  ('Alternating_Kettlebell_Row', 'de', array['Stell zwei Kettlebells vor deine Füße. Beuge die Knie leicht und schieb das Gesäß so weit wie möglich nach hinten. Beuge dich in die Ausgangsposition vor und greif beide Kettlebells an den Griffen.', 'Zieh eine Kettlebell vom Boden hoch und halte die andere weiter fest. Zieh das Schulterblatt der arbeitenden Seite nach hinten und beuge den Ellbogen, sodass die Kettlebell zum Bauch oder zu den Rippen kommt.', 'Senke die Kettlebell des arbeitenden Arms ab und mach dasselbe mit dem anderen Arm.']::text[]),
  ('Alternating_Renegade_Row', 'de', array['Stell zwei Kettlebells etwa schulterbreit auf den Boden. Geh auf Zehen und Hände wie beim Liegestütz, der Körper ist gerade und gestreckt, und stütz dich dabei auf die Griffe der Kettlebells. Für mehr Halt kannst du die Füße weit auseinanderstellen.', 'Drück eine Kettlebell in den Boden und rudere mit der anderen: Zieh das Schulterblatt der arbeitenden Seite nach hinten, beuge den Ellbogen und zieh die Kettlebell an deine Seite.', 'Stell die Kettlebell wieder ab und rudere mit der anderen Hand. Mach so mehrere Wiederholungen.']::text[]),
  ('Ankle_Circles', 'de', array['Halte dich an etwas Stabilem fest, zum Beispiel an einem Kniebeugenständer.', 'Heb das rechte Bein nur etwa 2 Inches vom Boden und kreise mit dem großen Zeh, als würdest du damit einen großen Kreis zeichnen. Tipp: Ein Kreis zählt als 1 Wiederholung. Atme bei der Bewegung normal weiter.', 'Bist du mit dem rechten Fuß fertig, mach dasselbe mit dem linken Bein.']::text[]),
  ('Ankle_On_The_Knee', 'de', array['Beuge im Liegen die Knie und lass die Füße auf dem Boden stehen.', 'Leg den Knöchel eines Beins auf das Knie des anderen.', 'Fass den Oberschenkel oder das Knie des unteren Beins und zieh beide Beine zur Brust. Lass Nacken und Schultern locker. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Anterior_Tibialis-SMR', 'de', array['Setz dich auf den Boden, die Beine gebeugt, die Füße aufgestellt.', 'Drück mit einem Massagestab oder einem Nudelholz auf die Muskeln an der Außenseite deines Schienbeins. Arbeite dich von knapp unter dem Knie bis über den Knöchel und bleib auf verspannten Stellen 10-30 Sekunden. Mach danach das andere Bein.']::text[]),
  ('Anti-Gravity_Press', 'de', array['Leg eine Langhantel hinter dem Kopfende einer Schrägbank auf den Boden.', 'Leg dich bäuchlings auf die Bank. Nimm die Langhantel im Obergriff vom Boden auf. Beuge die Ellbogen wie bei einem Reverse Curl, bis die Stange nah an der Brust ist. Das ist die Ausgangsposition.', 'Streck die Ellbogen und drück die Stange vor deinem Kopf nach vorn. Die Arme bleiben während der ganzen Bewegung parallel zum Boden.', 'Geh zurück in die Ausgangsposition und wiederhole, bis der Satz fertig ist.']::text[]),
  ('Arm_Circles', 'de', array['Stell dich hin und streck beide Arme gerade zur Seite aus. Sie sind parallel zum Boden und stehen im 90-Grad-Winkel zum Oberkörper. Das ist die Ausgangsposition.', 'Fang langsam an, mit jedem gestreckten Arm Kreise von etwa 1 Fuß Durchmesser zu ziehen. Atme bei der Bewegung normal weiter.', 'Kreise mit gestreckten Armen etwa zehn Sekunden lang weiter. Kreise dann in die andere Richtung.']::text[]),
  ('Arnold_Dumbbell_Press', 'de', array['Setz dich auf eine Bank mit Rückenlehne. Halte zwei Kurzhanteln etwa auf Höhe der oberen Brust vor dir, die Ellbogen gebeugt, die Handflächen zu dir gedreht. Tipp: Die Arme liegen eng am Oberkörper. Die Ausgangsposition sieht aus wie der obere Punkt eines Kurzhantel-Curls.', 'Für die Bewegung hebst du die Hanteln an und drehst dabei die Handflächen, bis sie nach vorn zeigen.', 'Drück weiter, bis deine Arme gestreckt über dem Kopf sind. Atme in diesem Teil aus.', 'Halte oben eine Sekunde, senke dann die Hanteln in die Ausgangsposition und dreh dabei die Handflächen wieder zu dir. Tipp: Der linke Arm dreht gegen den Uhrzeigersinn, der rechte im Uhrzeigersinn. Atme in diesem Teil ein.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Around_The_Worlds', 'de', array['Leg dich auf eine Flachbank, in jeder Hand eine Kurzhantel, die Handflächen zeigen zur Decke. Tipp: Die Arme sind parallel zum Boden und liegen neben den Oberschenkeln. Lass die Ellbogen leicht gebeugt, damit du dich nicht verletzt. Das ist die Ausgangsposition.', 'Führ die Kurzhanteln in einem Halbkreis von den Oberschenkeln bis über den Kopf. Die Arme bleiben dabei die ganze Zeit parallel zum Boden. Atme in diesem Teil ein.', 'Atme aus und führ die Hanteln auf demselben Weg zurück in die Ausgangsposition.']::text[]),
  ('Atlas_Stone_Trainer', 'de', array['Mit diesem Trainingsgerät baust du Kraft für Atlas Stones auf, wenn du keine Steine zur Verfügung hast. Meist ist es aus Hantelstangen-Enden oder schwerem Rohr gebaut.', 'Lade das gewünschte Gewicht auf die Stange. Stell dich breitbeinig über das Gewicht, beuge dich in der Hüfte und schling die Arme um das Gerät.', 'Streck die Hüfte und zieh das Gewicht über die Knie nach oben. Ist es über den Knien, kannst du es auf den Schoß nehmen: Setz dich zurück, leg es auf die Oberschenkel und drück es fest an die Brust.', 'Streck zum Abschluss Hüfte und Knie und heb das Gewicht so hoch wie möglich. Für die nächste Wiederholung kommt es zurück auf den Schoß oder auf den Boden.']::text[]),
  ('Atlas_Stones', 'de', array['Stell dich so hin, dass der Stein zwischen deinen Füßen liegt. Beuge dich in der Hüfte und schling die Arme von oben nach unten um den Stein. Versuch, die Finger unter den Stein zu bekommen. Viele Steine haben unten eine kleine flache Stelle, damit lassen sie sich leichter halten.', 'Zieh den Stein an den Oberkörper und drück dich über die hintere Fußhälfte ab, um ihn vom Boden zu lösen.', 'Ist der Stein an den Knien vorbei, nimm ihn auf den Schoß: Setz dich nach hinten und zieh ihn auf die Oberschenkel.', 'Bleib tief, bring den Stein hoch auf die Brust und greif dabei um, sodass du über den Stein fasst. Steh auf, indem du die Hüfte durchschiebst. Geh nah an die Ablageplattform, lehn dich zurück und streck die Hüfte, um den Stein so hoch wie möglich zu bekommen.']::text[]),
  ('Axle_Deadlift', 'de', array['Tritt an die Stange, bis sie über der Mitte deiner Füße liegt. Die Füße stehen etwa hüftbreit. Beuge dich in der Hüfte, greif die Stange schulterbreit und lass die Schulterblätter nach vorn gleiten. Üblich ist der Kreuzgriff.', 'Stehen Füße und Griff, atme tief ein. Senke dann die Hüfte und beuge die Knie, bis die Schienbeine die Stange berühren. Schau nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drück dich über die Fersen ab, um das Gewicht nach oben zu bewegen.', 'Ist die Stange an den Knien vorbei, zieh sie kräftig nach hinten: Zieh die Schulterblätter zusammen und schieb die Hüfte nach vorn zur Stange.', 'Zum Ablegen beugst du dich in der Hüfte und führst die Stange zum Boden.']::text[]),
  ('Back_Flyes_-_With_Bands', 'de', array['Leg ein Band um einen festen Pfosten, etwa den eines Kniebeugenständers.', 'Greif das Band an den Griffen und geh zurück, bis die Spannung im Band zunimmt.', 'Heb die Arme und streck sie gerade nach vorn. Tipp: Die Arme sind gestreckt, parallel zum Boden und im rechten Winkel zum Oberkörper. Die Füße stehen schulterbreit und fest auf dem Boden. Das ist die Ausgangsposition.', 'Atme aus und führ die Arme zur Seite und nach hinten. Sie bleiben gestreckt und parallel zum Boden. Geh weiter, bis die Arme seitlich ausgestreckt sind.', 'Halte kurz und geh dann beim Einatmen zurück in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Backward_Drag', 'de', array['Belade einen Schlitten mit dem gewünschten Gewicht und befestige daran ein Seil oder Gurte, an denen du dich festhalten kannst.', 'Geh rückwärts über die festgelegte Strecke. Lehn dich zurück und drück dich mit kurzen Schritten aus den Beinen ab, um so schnell wie möglich voranzukommen.']::text[]),
  ('Backward_Medicine_Ball_Throw', 'de', array['Am besten machst du diese Übung zu zweit. Ohne Partner kannst du den Ball werfen und selbst holen oder ihn gegen eine Wand werfen.', 'Stell dich ein paar Meter vor deinen Partner, ihr schaut beide in dieselbe Richtung. Halte den Medizinball zu Beginn zwischen den Beinen.', 'Geh in die Hocke, kehr die Bewegung dann kraftvoll um, streck dich ganz durch und wirf den Ball über deinen Kopf zu deinem Partner.', 'Dein Partner kann dir den Ball zurückrollen. Mach so viele Wiederholungen, wie du möchtest.']::text[]),
  ('Balance_Board', 'de', array['Leg ein Balance Board vor dich auf den Boden.', 'Stell dich darauf und versuch, das Gleichgewicht zu finden.', 'Halte das Gleichgewicht so lange, wie du möchtest.']::text[]),
  ('Ball_Leg_Curl', 'de', array['Leg dich auf dem Boden auf den Rücken und leg die Füße oben auf den Gymnastikball.', 'Richte den Ball so aus, dass bei gestreckten Beinen deine Knöchel auf ihm liegen. Das ist die Ausgangsposition.', 'Heb die Hüfte vom Boden, sodass dein Gewicht auf den Schulterblättern und den Füßen ruht.', 'Beuge die Knie, spann die Beinbeuger an und zieh den Ball so nah zu dir, wie du kannst.', 'Halte kurz und geh zurück in die Ausgangsposition.']::text[]),
  ('Band_Assisted_Pull-Up', 'de', array['Zieh das Band in der Mitte der Klimmzugstange durch sich selbst fest. Mit verschiedenen Bändern bekommst du mehr oder weniger Unterstützung.', 'Zieh das Ende des Bands nach unten und stell ein gebeugtes Knie in die Schlaufe. Achte darauf, dass es nicht herausrutschen kann. Greif die Stange mittelweit bis weit. Das ist die Ausgangsposition.', 'Spann den Latissimus an, beuge die Ellbogen und zieh dich hoch. Führ die Ellbogen dabei an deine Seiten. Zieh dich so hoch, dass die Stange vor dir ist, und versuch, das Kinn über die Stange zu bringen. Schwing nicht und reiß nicht.', 'Halte kurz und geh zurück in die Ausgangsposition.']::text[]),
  ('Band_Good_Morning', 'de', array['Nimm ein 41-Inch-Band und stell dich mit leicht geöffneten Füßen auf ein Ende. Beuge dich in der Hüfte und leg das andere Ende hinter den Nacken. Das ist die Ausgangsposition.', 'Streck mit geraden Beinen die Hüfte, bis du fast senkrecht stehst.', 'Geh wieder hinunter in die Ausgangsposition und achte darauf, dass dein Rücken dabei nicht rund wird.']::text[]),
  ('Band_Good_Morning_Pull_Through', 'de', array['Leg das Band um einen Pfosten. Stell dich ein Stück davon entfernt hin und leg das andere Ende um den Nacken. Mit den Händen kannst du das Band in Position halten.', 'Beuge dich in der Hüfte und schieb das Gesäß so weit wie möglich nach hinten. Mit geradem Rücken beugst du dich bis etwa 90 Grad vor. Die Knie sind nur leicht gebeugt.', 'Schieb die Hüfte durch, richte dich auf und komm so zurück in die Ausgangsposition.']::text[]),
  ('Band_Hip_Adductions', 'de', array['Befestige ein Band an einem stabilen Pfosten oder einem ähnlichen Gegenstand.', 'Stell dich mit der linken Seite zum Pfosten und steig mit dem rechten Fuß in das Band, sodass es um den Knöchel liegt.', 'Stell dich gerade hin und halte dich bei Bedarf am Pfosten fest. Das ist die Ausgangsposition.', 'Heb das rechte Bein mit gestrecktem Knie so weit zur Seite, wie du kannst.', 'Geh zurück in die Ausgangsposition und mach die gewünschte Zahl an Wiederholungen.', 'Wechsle die Seite.']::text[]),
  ('Band_Pull_Apart', 'de', array['Halte das Band mit beiden Händen, die Arme gerade nach vorn gestreckt.', 'Beginn mit einer Reverse-Fly-Bewegung: Führ die Hände seitlich nach außen.', 'Lass die Ellbogen dabei gestreckt und zieh, bis das Band an der Brust ist. Achte darauf, dass die Schultern die ganze Übung über hinten bleiben.', 'Halte am Ende kurz und geh kontrolliert zurück in die Ausgangsposition.']::text[]),
  ('Band_Skull_Crusher', 'de', array['Befestige ein Band unten an einem Rack oder an der Bank. Leg dich so auf die Bank, dass das Band auf einer Linie mit deinem Kopf ist.', 'Greif das Band und heb die Ellbogen, bis die Oberarme senkrecht zum Boden stehen. Bei gebeugten Ellbogen ist das Band über deinem Kopf. Das ist die Ausgangsposition.', 'Lass die Oberarme, wo sie sind, und streck die Ellbogen, bis die Arme gerade sind. Halte oben kurz und geh zurück in die Ausgangsposition.']::text[]),
  ('Barbell_Ab_Rollout', 'de', array['Geh in die Liegestützposition, stütz dich aber nicht auf den Boden, sondern greif eine olympische Langhantel, die auf jeder Seite mit 5-10 lbs beladen ist. Das ist die Ausgangsposition.', 'Halte ein leichtes Hohlkreuz, atme aus, heb die Hüfte und roll die Langhantel zu den Füßen hin. Tipp: Bei der Bewegung kommt das Gesäß nach oben, der Bauch bleibt angespannt und der Rücken behält die ganze Zeit seine Haltung. Auch die Arme bleiben durchgehend senkrecht zum Boden. Sonst trainierst du eher Schultern und Rücken als den Bauch.', 'Spann oben eine Sekunde an und roll die Stange dann beim Einatmen langsam wieder nach vorn in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Barbell_Ab_Rollout_-_On_Knees', 'de', array['Knie dich auf den Boden und halte eine olympische Langhantel, die auf jeder Seite mit 5-10 lbs beladen ist.', 'Setz die Stange vor dir auf dem Boden ab, sodass du auf Händen und Knien bist wie bei einem Liegestütz auf den Knien. Das ist die Ausgangsposition.', 'Roll die Stange langsam gerade nach vorn, bis dein Körper lang gestreckt ist. Tipp: Geh so tief, wie du kannst, ohne dass dein Körper den Boden berührt. Atme auf dem Weg nach vorn ein.', 'Halte die Streckung eine Sekunde und zieh dich dann beim Ausatmen zurück in die Ausgangsposition. Tipp: Lass dir Zeit und halte den Bauch die ganze Zeit angespannt.']::text[]),
  ('Barbell_Bench_Press_-_Medium_Grip', 'de', array['Leg dich rücklings auf eine Flachbank. Greif mittelweit, also so, dass Unterarme und Oberarme in der Mitte der Bewegung einen 90-Grad-Winkel bilden. Heb die Stange aus der Ablage und halte sie mit durchgestreckten Armen gerade über dir. Das ist die Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis sie die Mitte deiner Brust berührt.', 'Halte kurz und drück die Stange dann beim Ausatmen zurück in die Ausgangsposition. Konzentrier dich darauf, mit der Brustmuskulatur zu drücken. Oben streckst du die Arme durch, spannst die Brust an und hältst eine Sekunde, bevor du wieder langsam absenkst. Tipp: Das Absenken dauert im Idealfall etwa doppelt so lang wie das Hochdrücken.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.', 'Leg die Stange nach der letzten Wiederholung zurück in die Ablage.']::text[]),
  ('Barbell_Curl', 'de', array['Stell dich aufrecht hin und halte eine Langhantel schulterbreit. Die Handflächen zeigen nach vorn, die Ellbogen bleiben nah am Körper. Das ist die Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Stange nach vorn, indem du den Bizeps anspannst. Tipp: Nur die Unterarme bewegen sich.', 'Geh weiter, bis der Bizeps ganz angespannt ist und die Stange auf Schulterhöhe steht. Bleib dort eine Sekunde und spann den Bizeps kräftig an.', 'Atme ein und senke die Stange langsam in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Barbell_Curls_Lying_Against_An_Incline', 'de', array['Lehn dich an eine Schrägbank, halte eine Langhantel in den Händen und lass die Arme in einer waagerechten Linie herabhängen. Das ist die Ausgangsposition.', 'Beuge die Stange bei ruhigen Oberarmen so hoch, wie du kannst, und spann den Bizeps an. Atme in diesem Teil aus. Tipp: Nur die Unterarme bewegen sich. Schwing nicht mit den Armen.', 'Spann eine Sekunde an und geh dann beim Einatmen langsam zurück in die Ausgangsposition. Tipp: Geh ganz nach unten.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Barbell_Deadlift', 'de', array['Stell dich vor eine beladene Langhantel.', 'Halte den Rücken so gerade wie möglich, beuge die Knie, lehn dich vor und greif die Stange mittelweit, also schulterbreit, im Obergriff. Hier beginnt die Übung. Tipp: Lässt sich die Stange so schwer halten, nimm den Kreuzgriff oder Zughilfen.', 'Mit der Stange in den Händen atmest du aus und beginnst das Heben, indem du dich mit den Beinen abdrückst und zugleich den Oberkörper aufrichtest. Im Stand schiebst du die Brust heraus und spannst den Rücken an, indem du die Schulterblätter nach hinten ziehst. Stell dir einen Soldaten vor, der strammsteht.', 'Für den Weg zurück beugst du die Knie und neigst zugleich den Oberkörper aus der Taille nach vorn, der Rücken bleibt gerade. Berühren die Scheiben den Boden, bist du wieder in der Ausgangsposition und bereit für die nächste Wiederholung.', 'Mach so viele Wiederholungen, wie dein Programm vorgibt.']::text[]),
  ('Barbell_Full_Squat', 'de', array['Mach diese Übung zur Sicherheit in einem Squat-Rack. Lege die Stange knapp über Schulterhöhe in die Ablage. Stimmt die Höhe und sind die Scheiben aufgelegt, tritt unter die Stange und lege sie hinten auf deine Schultern, etwas unterhalb des Nackens.', 'Greife die Stange links und rechts mit je einer Hand. Hebe sie aus der Ablage, indem du mit den Beinen drückst und zugleich den Oberkörper aufrichtest.', 'Tritt vom Rack zurück. Stelle die Füße schulterbreit in einen mittleren Stand, die Zehen zeigen leicht nach außen. Halte den Kopf die ganze Zeit oben und den Rücken gerade. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam ab: Beuge die Knie und schiebe die Hüfte nach hinten, der Kopf bleibt oben, die Haltung gerade. Geh so tief, bis deine Beinbeuger auf den Waden aufliegen.', 'Atme aus und drücke die Stange nach oben, indem du dich mit der Ferse oder dem Mittelfuß vom Boden abdrückst. Strecke die Beine und die Hüfte, bis du wieder in der Ausgangsposition bist.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Glute_Bridge', 'de', array['Setz dich auf den Boden, eine beladene Langhantel liegt über deinen Beinen. Eine dicke Stange oder ein Polster um die Stange macht die Übung deutlich angenehmer. Rolle die Stange genau über deine Hüfte und lege dich flach auf den Rücken.', 'Beginne die Bewegung, indem du dich über die Fersen abdrückst und die Hüfte senkrecht gegen die Stange nach oben schiebst. Dein Gewicht liegt auf dem oberen Rücken und den Fersen.', 'Strecke die Hüfte so weit wie möglich und kehre dann auf demselben Weg in die Ausgangsposition zurück.']::text[]),
  ('Barbell_Guillotine_Bench_Press', 'de', array['Greife die Stange mittelweit, also so, dass Unterarme und Oberarme in der Mitte der Bewegung einen 90-Grad-Winkel bilden. Hebe die Stange aus der Ablage und halte sie mit durchgestreckten Armen genau über deinem Hals. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam ab, bis sie etwa 1 Inch über deinem Hals ist.', 'Halte eine Sekunde inne, atme dann aus und drücke die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Strecke die Arme durch, spanne die Brust oben fest an, halte eine Sekunde und senke die Stange wieder langsam ab. Der Weg nach unten sollte mindestens doppelt so lange dauern wie der Weg nach oben.', 'Wiederhole die Bewegung für die vorgegebene Anzahl an Wiederholungen.', 'Lege die Stange zum Schluss zurück in die Ablage.']::text[]),
  ('Barbell_Hack_Squat', 'de', array['Stell dich aufrecht hin, die Füße schulterbreit, und halte eine Langhantel mit gestreckten Armen hinter dem Körper. Tipp: Am besten greifst du schulterbreit, die Handflächen zeigen nach hinten. Handgelenkbandagen können dir zu einem besseren Griff verhelfen. Das ist deine Ausgangsposition.', 'Halte Kopf und Blick oben und den Rücken gerade. Atme ein und geh langsam in die Hocke, bis deine Oberschenkel parallel zum Boden sind.', 'Atme aus und komm wieder hoch. Drücke dabei vor allem über die Fersen und spanne die Oberschenkel an.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Hip_Thrust', 'de', array['Setz dich auf den Boden, direkt hinter dir steht eine Bank. Eine beladene Langhantel liegt über deinen Beinen. Eine dicke Stange oder ein Polster um die Stange macht die Übung deutlich angenehmer.', 'Rolle die Stange genau über deine Hüfte. Lehne dich so an die Bank, dass deine Schulterblätter nahe an ihrer Oberkante liegen.', 'Beginne die Bewegung, indem du dich über die Füße abdrückst und die Hüfte senkrecht gegen die Stange nach oben schiebst. Dein Gewicht liegt auf den Schulterblättern und den Füßen. Strecke die Hüfte so weit wie möglich und kehre dann auf demselben Weg in die Ausgangsposition zurück.']::text[]),
  ('Barbell_Incline_Bench_Press_-_Medium_Grip', 'de', array['Lege dich auf eine Schrägbank. Greife die Stange mittelweit, also so, dass Unterarme und Oberarme in der Mitte der Bewegung einen 90-Grad-Winkel bilden. Hebe die Stange aus der Ablage und halte sie mit durchgestreckten Armen genau über dir. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam ab, bis du sie auf der oberen Brust spürst.', 'Halte eine Sekunde inne, atme dann aus und drücke die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Strecke die Arme oben durch, spanne die Brust fest an, halte eine Sekunde und senke die Stange wieder langsam ab. Tipp: Der Weg nach unten sollte mindestens doppelt so lange dauern wie der Weg nach oben.', 'Wiederhole die Bewegung für die vorgegebene Anzahl an Wiederholungen.', 'Lege die Stange zum Schluss zurück in die Ablage.']::text[]),
  ('Barbell_Incline_Shoulder_Raise', 'de', array['Lege dich auf eine Schrägbank. Greife die Stange mittelweit, also etwas weiter als schulterbreit. Hebe sie aus der Ablage und halte sie mit gestreckten Armen genau über dir. Das ist deine Ausgangsposition.', 'Lass die Arme gestreckt, atme aus und schiebe die Stange höher, indem du die Schulterblätter nach vorn führst. Deine Schultern heben sich dabei von der Bank.', 'Atme ein und lass die Stange zurück in die Ausgangsposition sinken.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Lunge', 'de', array['Mach diese Übung zur Sicherheit in einem Squat-Rack. Lege die Stange knapp unter Schulterhöhe in die Ablage. Stimmt die Höhe und sind die Scheiben aufgelegt, tritt unter die Stange und lege sie hinten auf deine Schultern, etwas unterhalb des Nackens.', 'Greife die Stange links und rechts mit je einer Hand. Hebe sie aus der Ablage, indem du mit den Beinen drückst und zugleich den Oberkörper aufrichtest.', 'Tritt vom Rack weg. Mach mit dem rechten Bein einen Schritt nach vorn und senke dich über die Hüfte ab. Der Oberkörper bleibt aufrecht, du hältst das Gleichgewicht. Atme beim Absenken ein. Hinweis: Dein Knie darf beim Absenken nicht über die Zehen hinaus nach vorn wandern, sonst wird das Kniegelenk unnötig belastet.', 'Atme aus und drücke dich vor allem über die Ferse nach oben, zurück in die Ausgangsposition.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen und wechsle dann auf das linke Bein.']::text[]),
  ('Barbell_Rear_Delt_Row', 'de', array['Stell dich aufrecht hin und halte eine Langhantel im weiten Griff, weiter als schulterbreit, und im Obergriff, die Handflächen zeigen zum Körper.', 'Beuge die Knie leicht und beuge dich vor, ohne die natürliche Wölbung deines Rückens aufzugeben. Die Arme hängen mit der Stange vor dir herab. Ist dein Oberkörper parallel zum Boden, drehe die Ellbogen nach außen, weg vom Körper. Tipp: Oberkörper und Arme sollten zusammen wie ein "T" aussehen. Jetzt kannst du mit der Übung beginnen.', 'Halte die Oberarme im rechten Winkel zum Oberkörper. Atme aus und zieh die Langhantel zur oberen Brust, dabei spannst du die hinteren Schultermuskeln an. Tipp: Richtig ausgeführt sieht die Übung aus wie umgekehrtes Bankdrücken. Lass nicht den Bizeps die Arbeit machen. Konzentriere dich auf die hinteren Schultermuskeln, die Arme dienen nur als Haken.', 'Atme ein und kehre langsam in die Anfangsposition zurück.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Rollout_from_Bench', 'de', array['Lege eine beladene Langhantel nahe am Ende einer Bank auf den Boden. Knie dich mit beiden Beinen auf die Bank und greife die Langhantel mittelweit bis eng. Das ist deine Ausgangsposition.', 'Strecke zu Beginn die Hüfte, sodass die Stange langsam nach vorn rollt. Öffne beim Ausrollen die Schultern, bis die Stange über deinem Kopf ist. Achte darauf, dass die Arme während der ganzen Bewegung gestreckt bleiben.', 'Ist die Stange so weit vorn wie möglich, kehre in die Ausgangsposition zurück.']::text[]),
  ('Barbell_Seated_Calf_Raise', 'de', array['Stelle einen Block etwa 12 Inch vor eine Flachbank.', 'Setz dich auf die Bank und stelle die Fußballen auf den Block.', 'Lass dir von jemandem eine Langhantel auf die Oberschenkel legen, etwa 3 Inch oberhalb der Knie, und sie dort festhalten. Das ist deine Ausgangsposition.', 'Atme aus und drücke dich so hoch wie möglich auf die Zehen, dabei spannst du die Waden an.', 'Halte die Spannung eine Sekunde und kehre dann langsam in die Ausgangsposition zurück. Tipp: Dehne die Waden so weit du kannst, dann bringt die Übung am meisten.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Shoulder_Press', 'de', array['Setz dich in einem Squat-Rack auf eine Bank mit Rückenlehne. Lege die Langhantel knapp über Kopfhöhe ab. Fasse sie im Obergriff, die Handflächen zeigen nach vorn.', 'Stimmt die Griffweite, nimm die Langhantel auf und drücke sie über den Kopf, bis die Arme durchgestreckt sind. Halte sie etwa auf Schulterhöhe und leicht vor dem Kopf. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam zu den Schultern ab.', 'Atme aus und drücke die Stange wieder hoch in die Ausgangsposition.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Shrug', 'de', array['Stell dich aufrecht hin, die Füße schulterbreit. Halte eine Langhantel mit beiden Händen im Obergriff vor dem Körper, die Handflächen zeigen zu den Oberschenkeln. Tipp: Die Hände greifen etwas weiter als schulterbreit. Handgelenkbandagen können dir zu einem besseren Griff verhelfen. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Schultern so hoch, wie es geht. Halte die Spannung eine Sekunde. Tipp: Versuche nicht, die Langhantel mit dem Bizeps anzuheben.', 'Atme ein und kehre langsam in die Ausgangsposition zurück.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Shrug_Behind_The_Back', 'de', array['Stell dich aufrecht hin, die Füße schulterbreit. Halte eine Langhantel mit beiden Händen im Obergriff hinter dem Rücken, die Handflächen zeigen nach hinten. Tipp: Die Hände greifen etwas weiter als schulterbreit. Handgelenkbandagen können dir zu einem besseren Griff verhelfen. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Schultern so hoch, wie es geht. Halte die Spannung eine Sekunde. Tipp: Versuche nicht, die Langhantel mit dem Bizeps anzuheben. Die Arme bleiben die ganze Zeit gestreckt.', 'Atme ein und kehre langsam in die Ausgangsposition zurück.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Side_Bend', 'de', array['Stell dich aufrecht hin, die Langhantel liegt hinten auf deinen Schultern, etwas unterhalb des Nackens. Die Füße stehen schulterbreit. Das ist deine Ausgangsposition.', 'Halte den Rücken gerade und den Kopf oben. Atme ein und neige dich so weit wie möglich nach rechts, die Bewegung kommt nur aus der Taille. Halte eine Sekunde, atme aus und richte dich wieder in die Ausgangsposition auf. Tipp: Der Rest des Körpers bleibt ruhig.', 'Mach nun dieselbe Bewegung zur linken Seite. Halte eine Sekunde und richte dich wieder in die Ausgangsposition auf.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Side_Split_Squat', 'de', array['Stell dich aufrecht hin, die Langhantel liegt hinten auf deinen Schultern, etwas unterhalb des Nackens. Stelle die Füße weit auseinander und drehe den Fuß des führenden Beins zur Seite nach außen. Das ist deine Ausgangsposition.', 'Atme ein und senke dich zur Seite des ausgedrehten Fußes ab. Beuge dabei Knie und Hüfte des führenden Beins, das andere Bein bleibt nur leicht gebeugt.', 'Atme aus und strecke Hüfte und Knie des führenden Beins, um in die Ausgangsposition zurückzukehren.', 'Mach die empfohlene Anzahl an Wiederholungen und wiederhole die Bewegung dann mit dem anderen Bein.']::text[]),
  ('Barbell_Squat', 'de', array['Mach diese Übung zur Sicherheit in einem Squat-Rack. Lege die Stange knapp unter Schulterhöhe in die Ablage. Stimmt die Höhe und sind die Scheiben aufgelegt, tritt unter die Stange und lege sie hinten auf deine Schultern, etwas unterhalb des Nackens.', 'Greife die Stange links und rechts mit je einer Hand. Hebe sie aus der Ablage, indem du mit den Beinen drückst und zugleich den Oberkörper aufrichtest.', 'Tritt vom Rack zurück. Stelle die Füße schulterbreit in einen mittleren Stand, die Zehen zeigen leicht nach außen. Halte den Kopf die ganze Zeit oben und den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der mittlere Stand trainiert die Beine insgesamt, du kannst aber jede der drei Standbreiten wählen.', 'Atme ein und senke die Stange langsam ab, indem du Knie und Hüfte beugst. Der Kopf bleibt oben, die Haltung gerade. Geh so tief, bis der Winkel zwischen Oberschenkel und Wade etwas kleiner als 90 Grad ist. Tipp: Bei richtiger Ausführung liegen die Vorderseite der Knie und die Zehen auf einer gedachten senkrechten Linie. Schieben sich die Knie über diese Linie hinaus, also über die Zehen, belastest du das Knie unnötig und die Ausführung ist falsch.', 'Atme aus und drücke die Stange nach oben, indem du dich mit den Fersen vom Boden abdrückst und die Beine streckst, bis du wieder in der Ausgangsposition bist.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Squat_To_A_Bench', 'de', array['Mach diese Übung zur Sicherheit in einem Squat-Rack. Stelle zuerst eine Flachbank oder eine Box hinter dich. Mit der Bank lernst du, die Hüfte nach hinten zu schieben und die richtige Tiefe zu erreichen.', 'Lege dann die Stange auf der Höhe ab, die am besten zu deiner Größe passt. Stimmt die Höhe und sind die Scheiben aufgelegt, tritt unter die Stange und lege sie hinten auf deine Schultern, etwas unterhalb des Nackens.', 'Greife die Stange links und rechts mit je einer Hand. Hebe sie aus der Ablage, indem du mit den Beinen drückst und zugleich den Oberkörper aufrichtest.', 'Tritt vom Rack zurück. Stelle die Füße schulterbreit in einen mittleren Stand, die Zehen zeigen leicht nach außen. Halte den Kopf die ganze Zeit oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der mittlere Stand trainiert die Beine insgesamt, du kannst aber jede der drei Standbreiten wählen.', 'Atme ein und senke die Stange langsam ab: Beuge die Knie und schiebe die Hüfte nach hinten, der Kopf bleibt oben, die Haltung gerade. Geh so tief, bis du die Bank hinter dir leicht berührst. Tipp: Bei richtiger Ausführung liegen die Vorderseite der Knie und die Zehen auf einer gedachten senkrechten Linie. Schieben sich die Knie über diese Linie hinaus, also über die Zehen, belastest du das Knie unnötig und die Ausführung ist falsch.', 'Atme aus und drücke die Stange nach oben, indem du dich mit den Fersen vom Boden abdrückst. Strecke die Beine und die Hüfte, bis du wieder in der Ausgangsposition bist.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Barbell_Step_Ups', 'de', array['Lege eine Langhantel hinten auf deine Schultern, etwas unterhalb des Nackens, und stell dich aufrecht hinter eine erhöhte Plattform, etwa das Podest für den Helfer hinter einer Flachbank. Das ist deine Ausgangsposition.', 'Stelle den rechten Fuß auf die Plattform. Atme aus und steig hinauf, indem du Hüfte und Knie des rechten Beins streckst. Drücke dich vor allem über die Ferse hoch und setze dann auch den linken Fuß auf die Plattform.', 'Atme ein und steig mit dem linken Bein wieder hinunter, indem du Hüfte und Knie des rechten Beins beugst. Stelle dann den rechten Fuß neben den linken, sodass du wieder am Ausgangspunkt stehst.', 'Mach die empfohlene Anzahl an Wiederholungen mit dem rechten Bein und wechsle dann auf das linke.']::text[]),
  ('Barbell_Walking_Lunge', 'de', array['Stell dich hin, die Füße schulterbreit, die Langhantel liegt auf dem oberen Rücken.', 'Mach mit einem Bein einen Schritt nach vorn und beuge beide Knie, sodass die Hüfte absinkt. Geh so tief, bis das hintere Knie fast den Boden berührt. Bleib aufrecht und halte das vordere Knie über dem vorderen Fuß.', 'Drücke dich über die Ferse des vorderen Fußes ab und strecke beide Knie, um wieder hochzukommen.', 'Zieh den hinteren Fuß nach vorn in den nächsten Schritt und mach den Ausfallschritt mit dem anderen Bein.']::text[]),
  ('Battling_Ropes', 'de', array['Du brauchst ein schweres Seil, das in seiner Mitte 15-20 Fuß von dir entfernt befestigt ist. Stell dich mit Blick zur Befestigung hin und nimm in jede Hand ein Ende, die Arme hängen gestreckt an den Seiten. Das ist deine Ausgangsposition.', 'Reiße zu Beginn einen Arm so schnell du kannst auf Schulterhöhe hoch.', 'Während dieser Arm in die Ausgangsposition zurückfällt, hebst du den anderen.', 'Wechsle weiter zwischen links und rechts und schlage die Seile so schnell wie möglich auf und ab.']::text[]),
  ('Bear_Crawl_Sled_Drags', 'de', array['Lege ein Geschirr oder einen locker sitzenden Gewichthebergürtel an und hake die Kette hinten ein, sodass du mit dem Rücken zum Schlitten stehst. Beuge dich hinunter und setze die Hände auf den Boden, der Rücken ist flach, die Knie sind gebeugt. Das ist deine Ausgangsposition.', 'Schiebe dich mit den Beinen an, abwechselnd links und rechts. Mit den Händen hältst du das Gleichgewicht und ziehst mit. Versuche, den Rücken flach zu halten, während du die vorgegebene Strecke zurücklegst.']::text[]),
  ('Behind_Head_Chest_Stretch', 'de', array['Setz dich aufrecht auf den Boden, dein Partner steht hinter dir.', 'Lege die Hände hinter den Kopf und führe die Ellbogen so weit wie möglich nach hinten. Dein Partner hält deine Ellbogen fest. Das ist deine Ausgangsposition.', 'Lass die Hände hinter dem Kopf und versuche 10 Sekunden oder länger, die Ellbogen sanft nach vorn zu ziehen. Dein Partner verhindert, dass sie sich bewegen.', 'Entspanne nun die Muskeln und lass deinen Partner die Ellbogen sanft so weit nach hinten ziehen, wie es für dich angenehm ist. Sag deinem Partner, wann die Dehnung reicht, um Überdehnung oder Verletzungen zu vermeiden.']::text[]),
  ('Bench_Dips', 'de', array['Stelle eine Bank hinter dich. Sie steht quer zu deinem Körper, du schaust von ihr weg. Halte dich mit schulterbreit gesetzten Händen und ganz gestreckten Armen an ihrer Kante fest. Die Beine sind nach vorn gestreckt, in der Hüfte gebeugt und im rechten Winkel zum Oberkörper. Das ist deine Ausgangsposition.', 'Atme ein und senke den Körper langsam ab, indem du die Ellbogen beugst, bis der Winkel zwischen Oberarm und Unterarm etwas kleiner als 90 Grad ist. Tipp: Halte die Ellbogen während der ganzen Bewegung so eng wie möglich. Die Unterarme zeigen immer nach unten.', 'Drücke den Oberkörper mit dem Trizeps wieder hoch, bis du in der Ausgangsposition bist.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Bench_Jump', 'de', array['Stelle eine Box oder Bank 1-2 Fuß vor dich. Stell dich schulterbreit hin. Das ist deine Ausgangsposition.', 'Geh kurz in eine flache Kniebeuge, um Schwung zu holen, und schwinge die Arme nach hinten.', 'Schnelle aus dieser Position hoch: Strecke Hüfte, Knie und Sprunggelenke und spring so hoch du kannst. Schwinge die Arme nach vorn oben.', 'Spring über die Bank und lande mit gebeugten Knien, sodass die Beine den Aufprall abfangen.', 'Dreh dich um, sodass du in die andere Richtung schaust, und spring zurück über die Bank.']::text[]),
  ('Bench_Press_-_Powerlifting', 'de', array['Lege dich auf die Bank, den Kopf wenn möglich über die Stange hinaus. Zieh die Füße unter dich und geh ins Hohlkreuz. Stütze dich an der Stange ab, hebe die Schultern von der Bank, zieh sie zurück und drücke die Schulterblätter zusammen. Presse mit Hilfe der Füße den Trapez in die Bank. Halte diese Körperspannung während der ganzen Bewegung.', 'Egal wie weit du greifst, deine Hände sollten den Ring auf der Stange bedecken. Zieh die Stange aus der Ablage, ohne die Schultern nach vorn zu schieben. Konzentriere dich darauf, die Stange fest zu umschließen und sie auseinanderziehen zu wollen.', 'Senke die Stange zur unteren Brust oder zum oberen Bauch ab. Stange, Handgelenk und Ellbogen bleiben immer auf einer Linie.', 'Halte inne, wenn die Langhantel deinen Oberkörper berührt, und drücke sie dann mit aller Kraft nach oben. Die Ellbogen bleiben eng am Körper, bis die Arme durchgestreckt sind.']::text[]),
  ('Bench_Press_-_With_Bands', 'de', array['Befestige an einer Flachbank ein Band unter dem Bankfuß, der deinem Kopf am nächsten ist.', 'Sitzt das Band fest, nimm beide Griffe und lege dich auf die Bank.', 'Strecke die Arme, sodass du die Griffe schulterbreit vor dir hältst.', 'Drehe in dieser Stellung die Handgelenke nach vorn, bis die Handflächen von dir weg zeigen. Das ist deine Ausgangsposition.', 'Senke die Griffe langsam ab, bis deine Ellbogen einen 90-Grad-Winkel bilden. Behalte dabei jederzeit die volle Kontrolle.', 'Atme aus und drücke die Griffe mit der Brustmuskulatur nach oben. Strecke die Arme oben durch, spanne die Brust fest an, halte eine Sekunde und senke dann langsam ab. Tipp: Der Weg nach unten sollte mindestens doppelt so lange dauern wie der Weg nach oben.', 'Wiederhole die Bewegung so oft, wie dein Trainingsplan es vorgibt.']::text[]),
  ('Bench_Press_with_Chains', 'de', array['Kürze die Führungskette auf die gewünschte Länge. Hänge die Ketten auf die Scheibenaufnahmen der Stange.', 'Lege dich auf die Bank, den Kopf wenn möglich über die Stange hinaus. Zieh die Füße unter dich und geh ins Hohlkreuz. Stütze dich an der Stange ab, hebe die Schultern von der Bank, zieh sie zurück und drücke die Schulterblätter zusammen. Presse mit Hilfe der Füße den Trapez in die Bank. Halte diese Körperspannung während der ganzen Bewegung. Egal wie weit du greifst, deine Hände sollten den Ring auf der Stange bedecken.', 'Zieh die Stange aus der Ablage, ohne die Schultern nach vorn zu schieben. Konzentriere dich darauf, die Stange fest zu umschließen und sie auseinanderziehen zu wollen. Senke die Stange zur unteren Brust oder zum oberen Bauch ab. Stange, Handgelenk und Ellbogen bleiben immer auf einer Linie.', 'Halte inne, wenn die Langhantel deinen Oberkörper berührt, und drücke sie dann mit aller Kraft nach oben. Die Ellbogen bleiben eng am Körper, bis die Arme durchgestreckt sind.']::text[]),
  ('Bench_Sprint', 'de', array['Stell dich auf den Boden und setze einen Fuß auf eine Bank oder Box, die Ferse nahe an der Kante.', 'Drücke dich mit dem Fuß auf der Bank ab und strecke dabei Hüfte und Knie.', 'Lande mit dem anderen Fuß auf der Box, während der erste Fuß zurück an seinen Ausgangspunkt geht.', 'Wechsle weiter von einem Fuß auf den anderen, bis der Satz fertig ist.']::text[]),
  ('Bent-Arm_Barbell_Pullover', 'de', array['Greif eine Langhantel schulterbreit und leg dich auf eine Flachbank.', 'Halte die Stange direkt über der Brust, die Arme leicht gebeugt. Das ist deine Ausgangsposition.', 'Lass die Arme in dieser Beugung und führe das Gewicht beim Einatmen langsam in einem Bogen hinter den Kopf, bis du eine Dehnung in der Brust spürst.', 'Atme dann aus und bring die Langhantel auf demselben Bogen zurück in die Ausgangsposition.', 'Halte das Gewicht dort eine Sekunde und wiederhole die Bewegung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Bent-Arm_Dumbbell_Pullover', 'de', array['Stell eine Kurzhantel hochkant auf eine Flachbank.', 'Achte darauf, dass die Kurzhantel sicher am oberen Ende der Bank steht. Leg dich dann quer über die Bank, sodass dein Körper mit ihr ein Kreuz bildet und nur die Schultern aufliegen. Die Hüfte ist tiefer als die Bank, die Beine sind gebeugt und die Füße stehen fest auf dem Boden. Auch der Kopf liegt nicht auf.', 'Fass die Kurzhantel mit beiden Händen und halte sie direkt über der Brust, die Arme gebeugt. Beide Handflächen drücken von unten gegen eine der Hantelscheiben. Das ist deine Ausgangsposition. Vorsicht: Nimm für diese Übung nur eine Kurzhantel, die fest zusammengebaut ist. Bei lockeren Scheiben kann sie auseinanderfallen und dir ins Gesicht stürzen.', 'Halte die Arme fest in der Beugung und führe das Gewicht beim Einatmen langsam in einem Bogen hinter den Kopf, bis du eine Dehnung in der Brust spürst.', 'Atme dann aus und bring die Kurzhantel auf demselben Bogen zurück in die Ausgangsposition.', 'Halte das Gewicht dort eine Sekunde und wiederhole die Bewegung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Bent-Knee_Hip_Raise', 'de', array['Leg dich flach auf den Rücken, die Arme neben dem Körper.', 'Beuge die Knie auf etwa 75 Grad und hebe die Füße ungefähr 2 Inches vom Boden ab.', 'Zieh die Knie mit dem unteren Bauch zu dir heran und behalte die 75-Grad-Beugung in den Beinen bei. Führe die Bewegung weiter, bis das Becken nach hinten rollt und die Hüfte vom Boden abhebt. Atme dabei aus. Tipp: Am Ende sind deine Knie über der Brust.', 'Spanne den Bauch oben eine Sekunde lang an. Atme dann ein und geh langsam zurück in die Ausgangsposition. Tipp: Führe die Bewegung immer kontrolliert aus.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Bent_Over_Barbell_Row', 'de', array['Halte eine Langhantel im Obergriff, die Handflächen zeigen nach unten. Beuge die Knie leicht und neige den Oberkörper aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Der Rücken bleibt gerade. Tipp: Achte darauf, den Kopf oben zu halten. Die Langhantel hängt direkt vor dir, die Arme stehen senkrecht zum Boden und zum Oberkörper. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig, atme aus und zieh die Langhantel zu dir. Die Ellbogen bleiben eng am Körper, die Unterarme halten das Gewicht nur. Spanne oben die Rückenmuskulatur fest an und halte kurz inne.', 'Atme ein und senke die Langhantel langsam zurück in die Ausgangsposition.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'de', array['Stell dich aufrecht hin, in jeder Hand eine Kurzhantel, vor dir eine Schrägbank.', 'Halte den Rücken gerade mit seiner natürlichen Wölbung und beuge dich vor, bis deine Stirn die Bank berührt. Die Arme hängen senkrecht zum Boden vor dir, die Handflächen zeigen zueinander. Dein Oberkörper ist parallel zum Boden. Das ist deine Ausgangsposition.', 'Der Oberkörper bleibt vorgebeugt und ruhig, die Arme sind gestreckt und nur leicht im Ellbogen gebeugt. Atme aus und hebe die Kurzhanteln gerade zur Seite, bis beide Arme parallel zum Boden sind. Vorsicht: Schwinge nicht mit dem Oberkörper und führe die Arme nicht nach hinten statt zur Seite.', 'Halte die Spannung oben eine Sekunde und senke die Kurzhanteln dann langsam zurück in die Ausgangsposition.', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Bent_Over_Low-Pulley_Side_Lateral', 'de', array['Wähle ein Gewicht und nimm den Griff des unteren Kabelzugs in die rechte Hand.', 'Beuge dich aus der Hüfte vor, bis dein Oberkörper fast parallel zum Boden ist. Die Beine sind leicht gebeugt, die linke Hand liegt unten auf dem linken Oberschenkel. Der rechte Arm hängt von der Schulter vor dir herab, der Ellbogen ist leicht gebeugt. Das ist deine Ausgangsposition.', 'Atme aus und hebe den rechten Arm mit leicht gebeugtem Ellbogen zur Seite, bis er parallel zum Boden und auf einer Linie mit deinem rechten Ohr ist.', 'Atme ein und lass das Gewicht langsam in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen und wiederhole die Bewegung dann mit dem anderen Arm.']::text[]),
  ('Bent_Over_One-Arm_Long_Bar_Row', 'de', array['Belade ein Ende einer olympischen Langhantel. Klemme das andere Ende in eine Ecke zwischen zwei Wänden oder sichere es mit einem schweren Gegenstand am Boden, damit die Langhantel nicht nach hinten rutscht.', 'Beuge dich vor, bis dein Oberkörper so nah wie möglich an der Parallele zum Boden ist. Die Knie bleiben leicht gebeugt.', 'Greife die Stange mit einer Hand direkt hinter den Scheiben auf der beladenen Seite und stütze die andere Hand auf dem Knie ab. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Stange gerade nach oben, bis die Scheiben deine untere Brust berühren. Der Ellbogen bleibt eng am Körper, so arbeitet der Rücken am stärksten. Spanne beim Hochziehen die Rückenmuskulatur an und halte oben eine Sekunde. Tipp: Der Oberkörper darf überhaupt nicht schwingen. Nur der Arm bewegt sich.', 'Senke die Stange langsam in die Ausgangsposition und spüre die Dehnung im Latissimus. Tipp: Die Scheiben sollten den Boden nicht berühren. Für den größten Bewegungsumfang eignen sich kleine Scheiben (25 lb) besser als größere (etwa 35-45 lb).', 'Mach die empfohlene Anzahl an Wiederholungen und wechsle dann den Arm.']::text[]),
  ('Bent_Over_Two-Arm_Long_Bar_Row', 'de', array['Belade ein Ende einer olympischen Langhantel. Klemme das andere Ende in eine Ecke zwischen zwei Wänden oder sichere es mit einem schweren Gegenstand am Boden, damit die Langhantel nicht nach hinten rutscht.', 'Beuge dich vor, bis dein Oberkörper so nah wie möglich an der Parallele zum Boden ist. Die Knie bleiben leicht gebeugt.', 'Greife die Stange mit beiden Händen direkt hinter den Scheiben auf der beladenen Seite. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Stange gerade nach oben, bis die Scheiben deine untere Brust berühren. Die Ellbogen bleiben eng am Körper, so arbeitet der Rücken am stärksten. Spanne beim Hochziehen die Rückenmuskulatur an und halte oben eine Sekunde. Tipp: Du kannst einen Steigbügelgriff oder einen Doppelgriff vom Kabelzug unter das Stangenende haken und daran ziehen.', 'Senke die Stange langsam in die Ausgangsposition und spüre die Dehnung im Latissimus. Tipp: Die Scheiben sollten den Boden nicht berühren. Für den größten Bewegungsumfang eignen sich kleine Scheiben (25 lb) besser als größere (etwa 35-45 lb).', 'Wiederhole die Bewegung für die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Bent_Over_Two-Dumbbell_Row', 'de', array['Nimm in jede Hand eine Kurzhantel, die Handflächen zeigen zum Körper. Beuge die Knie leicht und neige den Oberkörper aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Der Rücken bleibt dabei gerade. Tipp: Halte den Kopf oben. Die Arme hängen senkrecht zum Boden und zum Oberkörper nach unten, die Kurzhanteln direkt vor dir. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig und zieh die Kurzhanteln beim Ausatmen seitlich nach oben. Die Ellbogen bleiben nah am Körper, die Unterarme halten nur die Gewichte und arbeiten sonst nicht mit. Spanne oben die Rückenmuskeln fest an und halte eine Sekunde.', 'Atme ein und lass die Gewichte langsam wieder in die Ausgangsposition sinken.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'de', array['Nimm in jede Hand eine Kurzhantel, die Handflächen zeigen zueinander. Beuge die Knie leicht und neige den Oberkörper aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Der Rücken bleibt dabei gerade. Tipp: Halte den Kopf oben. Die Arme hängen senkrecht zum Boden und zum Oberkörper nach unten, die Kurzhanteln direkt vor dir. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig und zieh die Kurzhanteln beim Ausatmen seitlich nach oben. Zieh dabei die Schulterblätter zusammen. Spanne oben die Rückenmuskeln fest an und halte eine Sekunde.', 'Atme ein und lass die Gewichte langsam wieder in die Ausgangsposition sinken.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Bent_Press', 'de', array['Bring eine Kettlebell mit einem Clean an die Schulter: Strecke Beine und Hüfte, während du die Kettlebell zur Schulter hebst, und lass das Handgelenk dabei mitdrehen. Das ist deine Ausgangsposition.', 'Neige dich zur Seite, weg von der Kettlebell, bis deine freie Hand den Boden berühren kann. Behalte die Kettlebell die ganze Zeit im Blick. Strecke dabei den Ellbogen und drücke das Gewicht senkrecht nach oben, sodass der Arm senkrecht zum Boden bleibt.', 'Richte dich wieder auf, die Kettlebell über dem Kopf. Senke sie zurück an die Schulter und wiederhole das so oft, wie du möchtest.']::text[]),
  ('Bicycling', 'de', array['Setz dich zuerst aufs Rad und stell den Sattel auf deine Körpergröße ein.']::text[]),
  ('Bicycling_Stationary', 'de', array['Setz dich zuerst aufs Rad und stell den Sattel auf deine Körpergröße ein.', 'Wähle im Menü aus, was du möchtest. Manchmal schaltet sich das Gerät erst ein, wenn du in die Pedale trittst. Du kannst manuell fahren oder ein Programm nehmen. Meist lassen sich Alter und Gewicht eingeben, damit das Gerät den Kalorienverbrauch beim Training schätzt. Den Widerstand kannst du während des Trainings jederzeit ändern. Über die Griffe lässt sich dein Puls messen, das hilft dir, bei einer passenden Intensität zu bleiben.']::text[]),
  ('Board_Press', 'de', array['Leg dich auf die Bank und rutsche, wenn es geht, mit dem Kopf über die Stange hinaus. Nimm ein bis fünf miteinander verschraubte Bretter aus 2x6-Holz. Ein Trainingspartner kann sie halten, Bänder können sie fixieren, oder du steckst sie einfach unter dein Shirt.', 'Zieh die Füße unter dich und geh ins Hohlkreuz. Stütze dich an der Stange ab, hebe die Schultern von der Bank und zieh sie zurück, sodass die Schulterblätter zusammengehen. Drücke mit den Füßen den Trapez in die Bank. Halte diese Körperspannung während der ganzen Bewegung.', 'Greif wie beim normalen Bankdrücken oder schulterbreit, um den Trizeps stärker zu belasten. Hebe die Stange aus der Ablage, ohne die Schultern nach vorn zu schieben. Stange, Handgelenk und Ellbogen bleiben immer in einer Linie. Drücke die Stange fest zusammen und versuche, sie auseinanderzuziehen.', 'Senke die Stange auf die Bretter und drücke sie dann mit aller Kraft nach oben. Die Ellbogen bleiben eng am Körper, bis die Arme durchgestreckt sind.']::text[]),
  ('Body-Up', 'de', array['Geh am Boden in den Unterarmstütz: Zehen und Unterarme tragen dein Gewicht, der Rumpf ist gerade. Die Unterarme liegen schulterbreit auseinander. Das ist deine Ausgangsposition.', 'Drücke die Handflächen fest in den Boden und strecke die Ellbogen, um den Körper anzuheben. Der Rumpf bleibt dabei steif.', 'Beuge die Ellbogen und senke die Unterarme langsam wieder auf den Boden.', 'Wiederhole das.']::text[]),
  ('Body_Tricep_Press', 'de', array['Leg eine Stange auf Brusthöhe in ein Rack.', 'Greif die Stange im Stehen schulterbreit und geh ein bis zwei Yards zurück. Die Füße stehen zusammen, die Arme sind gestreckt, du lehnst dich gegen die Stange. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und senke dich zur Stange hin ab.', 'Halte kurz und drücke dich dann durch Strecken der Ellbogen zurück.', 'Wenn das eigene Körpergewicht nicht mehr reicht, leg dir Ketten über die Schultern.']::text[]),
  ('Bodyweight_Flyes', 'de', array['Leg zwei gleich schwer beladene SZ-Stangen nebeneinander auf den Boden. Prüfe, dass sie rollen können.', 'Geh über den Stangen in die Liegestützposition: Zehen und Hände tragen das Gewicht, die Arme sind gestreckt, der Körper ist gerade.', 'Setz die Hände auf die Stangen. Das ist deine Ausgangsposition.', 'Schiebe die Hände langsam und kontrolliert von der Körpermitte nach außen, sodass die Stangen auseinanderrollen. Atme dabei ein.', 'Sind die Stangen so weit auseinander, wie du es schaffst, zieh sie wieder zusammen und komm so in die Ausgangsposition zurück. Atme dabei aus.']::text[]),
  ('Bodyweight_Mid_Row', 'de', array['Greif eine Klimmzugstange mittel bis weit, die Handflächen zeigen von dir weg. Zieh aus dem Hang die Knie zur Brust, lehne dich zurück und bring die Beine auf deine Seite der Stange. Das ist deine Ausgangsposition.', 'Beginne mit gestreckten Armen. Beuge die Ellbogen und zieh die Schulterblätter nach hinten, bis dein Körper so weit oben ist, dass die Beine die Stange berühren.', 'Halte kurz und geh dann zurück in die Ausgangsposition.']::text[]),
  ('Bodyweight_Squat', 'de', array['Stell dich schulterbreit hin. Die Hände kannst du hinter den Kopf nehmen. Das ist deine Ausgangsposition.', 'Beuge Knie und Hüfte und schiebe dabei das Gesäß nach hinten, als wolltest du dich setzen.', 'Geh ganz in die Tiefe, wenn du kannst, und komm dann zügig wieder hoch in die Ausgangsposition. Halte in der Kniebeuge Kopf und Brust oben und drücke die Knie nach außen.']::text[]),
  ('Bodyweight_Walking_Lunge', 'de', array['Stell dich schulterbreit hin, die Hände an den Hüften.', 'Mach mit einem Bein einen Schritt nach vorn und beuge die Knie, sodass die Hüfte sinkt. Geh so tief, bis das hintere Knie fast den Boden berührt. Bleib aufrecht, das vordere Knie bleibt über dem vorderen Fuß.', 'Drücke dich über die Ferse des vorderen Fußes ab und strecke beide Knie, um wieder hochzukommen.', 'Setz den hinteren Fuß nach vorn und mach den Ausfallschritt mit dem anderen Bein.']::text[]),
  ('Bosu_Ball_Cable_Crunch_With_Side_Bends', 'de', array['Befestige an jedem Arm eines Kabelzugs einen normalen Griff und stell beide Rollen ganz nach unten.', 'Nimm einen Balance-Halbball und leg ihn mittig vor den Kabelzug.', 'Leg dich so auf den Halbball, dass sich dein unterer Rücken um ihn wölbt. Dein Po ist nah am Boden, berührt ihn aber nicht.', 'Greif mit beiden Händen nach hinten und fass je einen Griff.', 'Stell die Füße weit auseinander und strecke die Arme gerade nach vorn zwischen die Knie. Die Hände sind auf Kniehöhe.', 'Lass die Arme gestreckt und in einer Linie mit dem schräg nach oben laufenden Kabel. Hebe den Oberkörper mit einem Crunch an, ohne die Arme zu senken oder zu beugen.', 'Halte die Arme starr. Geh langsam zurück in die Ausgangsposition, der Rücken um den Halbball gewölbt, der Bauch lang gestreckt.', 'Wiederhole diesen Ablauf, bis keine Wiederholung mehr geht.', 'Halte dann den Bauch fest und hebe den Oberkörper in eine Brettposition, sodass der Rücken vom Halbball abhebt.', 'Senke die gestreckten Arme an die Seiten. Beuge dich nun abwechselnd zur Seite und greif dabei nach deinen Fersen. Dieser Abschluss trainiert die schrägen Bauchmuskeln.']::text[]),
  ('Bottoms-Up_Clean_From_The_Hang_Position', 'de', array['Stell dich zu Beginn aufrecht hin, eine Kettlebell in einer Hand.', 'Schwinge die Kettlebell kraftvoll nach hinten und kehre die Bewegung genauso kraftvoll um. Drücke den Griff so fest zusammen, wie du kannst, und bring die Kettlebell an die Schulter.']::text[]),
  ('Bottoms_Up', 'de', array['Leg dich mit dem Rücken auf den Boden, die Beine gestreckt, die Arme neben dem Körper. Das ist deine Ausgangsposition.', 'Beuge Hüfte und Knie und zieh die Knie zur Brust. Strecke danach die Beine gerade nach oben, sodass sie senkrecht zum Boden stehen. Kippe das Becken und hebe es an, damit das Gesäß vom Boden abhebt.', 'Halte kurz und geh dann zurück in die Ausgangsposition.']::text[]),
  ('Box_Jump_Multiple_Response', 'de', array['Stell dich locker vor die Box oder Plattform, etwa eine Armlänge entfernt. Die Arme hängen an den Seiten, die Beine sind leicht gebeugt.', 'Hol mit den Armen Schwung für den Absprung und spring nach oben und vorn. Lande mit beiden Füßen gleichzeitig auf der Box oder Plattform.', 'Lass dich sofort wieder fallen oder spring zurück an den Startpunkt und wiederhole den Ablauf.']::text[]),
  ('Box_Skip', 'de', array['Stell mehrere Boxen in einer Reihe auf, jeweils etwa 8 Feet auseinander.', 'Stell dich vor die erste Box, ein Bein etwas hinter dem anderen.', 'Drücke dich mit dem hinteren Bein ab und versuche, mit der Hüfte möglichst hoch zu kommen.', 'Sobald du auf der Box landest, schwinge das andere Bein nach vorn und oben, um Höhe und Weite zu gewinnen, und spring von der Box ab. Lande zwischen den ersten beiden Boxen auf demselben Bein, mit dem du auf der ersten Box gelandet bist.', 'Mach dann einen Schritt zur nächsten Box und wiederhole das.']::text[]),
  ('Box_Squat', 'de', array['Mit der Box kannst du bis zur gewünschten Tiefe beugen und Explosivkraft in der Kniebeuge aufbauen. Stell dich in ein Power Rack, hinter dir eine Box in passender Höhe. Üblich ist eine Höhe, bei der die Oberschenkel parallel zum Boden sind, du kannst aber auch höher oder tiefer trainieren.', 'Tritt unter die Stange und leg sie hinten auf die Schultern. Zieh die Schulterblätter zusammen und dreh die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Hebe die Stange mit festem Hohlkreuz im unteren Rücken aus der Ablage und tritt zurück in Position. Ein breiter Stand belastet Rücken, Gesäß, Adduktoren und Beinbeuger stärker, ein enger Stand mehr den Quadrizeps. Der Blick geht nach vorn.', 'Spanne Rücken, Schultern und Rumpf an. Schiebe Knie und Po nach außen und beginne abzusenken. Geh mit der Hüfte nach hinten, bis du auf der Box sitzt. Die Schienbeine stehen am besten senkrecht zum Boden. Halte auf der Box inne und entspanne die Hüftbeuger. Federe nie von der Box ab.', 'Lass das Gewicht auf den Fersen und drücke Füße und Knie nach außen. Drücke dich von der Box nach oben, der Kopf führt die Bewegung. Geh weiter nach oben und bleib von Kopf bis Fuß angespannt.']::text[]),
  ('Box_Squat_with_Bands', 'de', array['Stell dich in ein Power Rack, hinter dir eine Box in passender Höhe. Häng die Bänder über die Hantelaufnahmen und befestige sie an Bandhaltern, am Rack oder an Kurzhanteln, sodass die Spannung stimmt. Nimmst du Kurzhanteln, sichere sie gegen Verrutschen und achte darauf, dass sie für deine Bänder schwer genug sind. Zusätzliche Scheiben können die Kurzhanteln beschweren. Für mehr Spannung stellst du die Basis am Boden breiter oder legst die Bänder in eine Schlinge. Üblich ist eine Boxhöhe, bei der die Oberschenkel parallel zum Boden sind, du kannst aber auch höher oder tiefer trainieren.', 'Tritt unter die Stange und leg sie hinten auf die Schultern. Zieh die Schulterblätter zusammen und dreh die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Hebe die Stange mit festem Hohlkreuz im unteren Rücken aus der Ablage und tritt zurück in Position. Ein breiter Stand belastet Rücken, Gesäß, Adduktoren und Beinbeuger stärker, ein enger Stand mehr den Quadrizeps. Der Blick geht nach vorn.', 'Spanne Rücken, Schultern und Rumpf an. Schiebe Knie und Po nach außen und beginne abzusenken. Geh mit der Hüfte nach hinten, bis du auf der Box sitzt. Die Schienbeine stehen am besten senkrecht zum Boden. Halte auf der Box inne und entspanne die Hüftbeuger. Federe nie von der Box ab.', 'Lass das Gewicht auf den Fersen und drücke Füße und Knie nach außen. Drücke dich von der Box nach oben, der Kopf führt die Bewegung. Geh weiter nach oben und bleib von Kopf bis Fuß angespannt. Leg die Langhantel vorsichtig zurück in die Ablage.']::text[]),
  ('Box_Squat_with_Chains', 'de', array['Stell dich in ein Power Rack, hinter dir eine Box in passender Höhe. Üblich ist eine Höhe, bei der die Oberschenkel parallel zum Boden sind, du kannst aber auch höher oder tiefer trainieren.', 'Für die Ketten legst du zuerst die Führungskette über die Hantelaufnahmen. Die schwere Kette hängst du mit einem Karabinerhaken ein. Stell die Länge der Führungskette so ein, dass oben in der Bewegung noch ein paar Glieder auf dem Boden liegen.', 'Tritt unter die Stange und leg sie hinten auf die Schultern. Zieh die Schulterblätter zusammen und dreh die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Hebe die Stange mit festem Hohlkreuz im unteren Rücken aus der Ablage und tritt zurück in Position. Ein breiter Stand belastet Rücken, Gesäß, Adduktoren und Beinbeuger stärker, ein enger Stand mehr den Quadrizeps. Der Blick geht nach vorn.', 'Spanne Rücken, Schultern und Rumpf an. Schiebe Knie und Po nach außen und beginne abzusenken. Geh mit der Hüfte nach hinten, bis du auf der Box sitzt. Die Schienbeine stehen am besten senkrecht zum Boden. Halte auf der Box inne und entspanne die Hüftbeuger. Federe nie von der Box ab.', 'Lass das Gewicht auf den Fersen und drücke Füße und Knie nach außen. Drücke dich von der Box nach oben, der Kopf führt die Bewegung. Geh weiter nach oben und bleib von Kopf bis Fuß angespannt.']::text[]),
  ('Brachialis-SMR', 'de', array['Leg dich auf die Seite, den Oberarm auf der Faszienrolle. Der Oberarm liegt ungefähr in einer Linie mit dem Körper, die Außenseite des Bizeps drückt auf die Rolle.', 'Hebe die Hüfte vom Boden, sodass Arm und Füße dein Gewicht tragen. Halte 10-30 Sekunden und wechsle dann die Seite.']::text[]),
  ('Bradford_Rocky_Presses', 'de', array['Setz dich auf eine Bank für Schulterdrücken und halte eine Stange auf Schulterhöhe im Obergriff, die Handflächen zeigen nach vorn. Tipp: Greif weiter als schulterbreit, sodass Unterarm und Oberarm einen 90-Grad-Winkel bilden, wenn die Langhantel unten ist. Das ist deine Ausgangsposition.', 'Hast du die Langhantel richtig gegriffen, drücke sie über den Kopf, bis die Arme durchgestreckt sind.', 'Atme ein und senke die Stange langsam hinter den Kopf.', 'Atme aus und drücke die Stange wieder nach oben in die Ausgangsposition.', 'Atme ein und senke die Stange langsam in die Ausgangsposition. Das ist eine Wiederholung.', 'Wechsle so weiter ab, bis du die empfohlene Zahl an Wiederholungen geschafft hast.']::text[]),
  ('Butt-Ups', 'de', array['Geh in eine Liegestützposition, aber mit den Ellbogen am Boden, gestützt auf die Unterarme. Die Arme sind im 90-Grad-Winkel gebeugt.', 'Mach den Rücken leicht rund, statt ihn ganz gerade zu halten.', 'Schiebe das Gesäß zur Decke und spanne den Bauch fest an, um den Abstand zwischen Brustkorb und Hüfte zu verkleinern. Am Ende bist du in einer hohen Brückenposition. Atme dabei aus.', 'Atme ein und senke dich langsam in die Ausgangsposition. Tipp: Lass den Rücken nicht durchhängen.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Butt_Lift_Bridge', 'de', array['Leg dich flach auf den Rücken, die Hände neben dem Körper, die Knie gebeugt. Die Füße stehen etwa schulterbreit. Das ist deine Ausgangsposition.', 'Drücke dich vor allem über die Fersen ab und hebe die Hüfte vom Boden, der Rücken bleibt gerade. Atme dabei aus und halte oben eine Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition.']::text[]),
  ('Butterfly', 'de', array['Setz dich auf die Maschine, der Rücken liegt flach am Polster.', 'Fass die Griffe. Tipp: Stell die Maschine so ein, dass deine Oberarme parallel zum Boden sind. Das ist deine Ausgangsposition.', 'Führe die Griffe langsam zusammen und spanne die Brust in der Mitte an. Atme dabei aus und halte die Spannung eine Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition, bis die Brustmuskeln ganz gedehnt sind.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Cable_Chest_Press', 'de', array['Stell ein passendes Gewicht ein, setz dich und fass die Griffe. Die Oberarme stehen etwa 45 Grad vom Körper ab, Kopf und Brust sind oben, die Ellbogen ungefähr 90 Grad gebeugt. Das ist deine Ausgangsposition.', 'Strecke die Ellbogen und drücke die Griffe gerade nach vorn zusammen. Die Schulterblätter bleiben dabei nach hinten gezogen.', 'Halte kurz in der vollen Streckung und geh dann zurück in die Ausgangsposition, die Kabel bleiben unter Spannung.', 'Du kannst die Übung auch ohne Kontakt zum Rückenpolster, schräg nach oben oder nach unten oder mit abwechselnden Händen ausführen.']::text[]),
  ('Cable_Crossover', 'de', array['Stell als Vorbereitung beide Rollen hoch ein, über Kopfhöhe, wähle den Widerstand und nimm in jede Hand einen Griff.', 'Tritt nach vorn, vor die gedachte gerade Linie zwischen den beiden Rollen, und zieh die Arme vor dir zusammen. Der Oberkörper ist aus der Taille leicht nach vorn geneigt. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen leicht, um die Bizepssehne zu schonen. Öffne die Arme in einem weiten Bogen gerade zu beiden Seiten, bis du eine Dehnung in der Brust spürst. Atme dabei ein. Tipp: Arme und Oberkörper bleiben die ganze Zeit unverändert, die Bewegung kommt nur aus dem Schultergelenk.', 'Atme aus und führe die Arme zurück in die Ausgangsposition, auf demselben Bogen wie auf dem Hinweg.', 'Halte in der Ausgangsposition eine Sekunde und wiederhole die Bewegung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_Crunch', 'de', array['Knie dich unter eine hohe Rolle, an der ein Seil hängt.', 'Fass das Seil und zieh es herunter, bis deine Hände neben dem Gesicht sind.', 'Beuge die Hüfte leicht und lass das Gewicht den unteren Rücken ins Hohlkreuz ziehen. Das ist deine Ausgangsposition.', 'Die Hüfte bleibt ruhig. Spanne den Bauch an und beuge dich in der Taille, sodass die Ellbogen zur Mitte der Oberschenkel wandern. Atme dabei aus und halte die Spannung eine Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition. Tipp: Halte den Bauch die ganze Bewegung über unter Spannung. Wähle außerdem kein so schweres Gewicht, dass der untere Rücken die Hauptarbeit macht.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Cable_Deadlifts', 'de', array['Schiebe die Rollen an den Türmen ganz nach unten und wähle ein passendes Gewicht. Stell dich genau zwischen die beiden Säulen.', 'Beuge Hüfte und Knie und geh in die Hocke, bis du die Griffe erreichst.', 'Fass die Griffe und beginne aufzustehen. Drücke dich über die Fersen ab und strecke Hüfte und Knie, die Hände hängen an den Seiten. Kopf und Brust bleiben die ganze Bewegung über oben.', 'Stehst du ganz aufrecht, geh zurück in die Ausgangsposition und wiederhole das.']::text[]),
  ('Cable_Hammer_Curls_-_Rope_Attachment', 'de', array['Häng ein Seil an eine tiefe Rolle und stell dich mit Blick zum Gerät etwa 12 Inches davor.', 'Fass das Seil im neutralen Griff, die Handflächen zeigen zueinander. Stell dich gerade hin, behalte die natürliche Wölbung im Rücken und halte den Oberkörper ruhig.', 'Leg die Ellbogen an die Seiten und lass sie dort während der ganzen Bewegung. Tipp: Nur die Unterarme bewegen sich, nicht die Oberarme. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Arme mit dem Bizeps nach oben, bis der Bizeps die Unterarme berührt. Tipp: Die Ellbogen bleiben am Körper, die Oberarme ruhig.', 'Spanne den Bizeps 1 Sekunde lang an und lass das Gewicht dann langsam zurück in die Ausgangslage.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Cable_Hip_Adduction', 'de', array['Stell dich mit Blick nach vorn an eine tiefe Rolle, ein Bein neben der Rolle, das andere weiter weg.', 'Befestige die Fußmanschette am Kabel und am Knöchel des Beins, das neben der Rolle steht.', 'Tritt nun mit weitem Stand vom Gewichtsblock weg und halte dich an der Stange des Geräts fest.', 'Steh auf dem Fuß ohne Manschette, dem äußeren, und lass das Bein mit der Manschette zur tiefen Rolle ziehen. Das ist deine Ausgangsposition.', 'Führe das Bein mit der Manschette mit der Kraft der Oberschenkelinnenseite vor dem äußeren Bein vorbei. Atme dabei aus.', 'Atme ein und geh langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und wiederhole die Bewegung dann mit dem anderen Bein.']::text[]),
  ('Cable_Incline_Pushdown', 'de', array['Leg dich auf eine Schrägbank, mit dem Kopf zu einem hohen Kabelzug mit gerader Stange, den Blick von ihm weg.', 'Greif die gerade Stange über dem Kopf schulterbreit im Obergriff (Handflächen nach unten) und strecke die Arme nach vorn. Die Stange ist etwa 2 Inches von den Oberschenkeln entfernt. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig und führe die Arme in einem Halbkreis zurück, bis die Stange genau über deinem Kopf ist. Atme dabei ein.', 'Geh mit der Kraft des Latissimus langsam zurück in die Ausgangsposition und halte dort die Spannung. Atme bei dieser Bewegung aus.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Cable_Incline_Triceps_Extension', 'de', array['Leg dich auf eine Schrägbank, mit dem Kopf zu einem hohen Kabelzug mit gerader Stange, den Blick von ihm weg.', 'Greif die gerade Stange über dem Kopf eng im Obergriff (Handflächen nach unten), enger als schulterbreit, und halte die Ellbogen nah an den Seiten. Die Oberarme stehen in einem Winkel von etwa 25 Grad zum Boden.', 'Halte die Oberarme ruhig, strecke die Arme und spanne den Trizeps an. Atme dabei aus und halte die Spannung eine Sekunde.', 'Geh langsam zurück in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie empfohlen sind.']::text[]),
  ('Cable_Internal_Rotation', 'de', array['Setz dich seitlich neben eine tiefe Rolle, die Beine nach vorn gestreckt oder gekreuzt, und fass den Einzelgriff mit dem Arm, der dem Kabel am nächsten ist. Tipp: Lässt sich die Rolle in der Höhe verstellen, kannst du stattdessen auf einer Flachbank sitzen.', 'Leg den Ellbogen an die Seite, 90° gebeugt, der Unterarm zeigt zur Rolle. Das ist deine Ausgangsposition.', 'Dreh die Schulter nach innen und zieh den Griff zum Körper, bis der Unterarm quer vor dem Bauch liegt. Die Hand beschreibt dabei einen gedachten Halbkreis. Tipp: Der Unterarm bleibt die ganze Zeit senkrecht zum Oberkörper.', 'Geh langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und wiederhole die Bewegung dann mit dem anderen Arm.']::text[]),
  ('Cable_Iron_Cross', 'de', array['Stell die Rollen hoch ein, wähle den Widerstand und nimm in jede Hand einen Griff.', 'Stell dich genau zwischen die beiden Rollen, die Arme zur Seite gestreckt. Kopf und Brust sind oben, die Arme bilden ein T. Das ist deine Ausgangsposition.', 'Lass die Ellbogen gestreckt und zieh die Arme gerade nach unten an die Seiten.', 'Halte kurz am Punkt der stärksten Anspannung und führe die Arme dann zurück in die Ausgangsposition.', 'Mach so weiter, bis die vorgesehene Zahl an Wiederholungen erreicht ist.']::text[]),
  ('Cable_Judo_Flip', 'de', array['Häng ein Seil an einen Kabelturm und stell die Rolle ganz nach unten. Stell dich seitlich zum Kabel in einen weiten Stand und fass das Seil mit beiden Händen.', 'Dreh den Körper von der Rolle weg und führe das Seil über die Schulter, als würdest du einen Judowurf machen.', 'Verlagere das Gewicht von einem Fuß auf den anderen, während du dich drehst, nach vorn einrollst und das Kabel nach unten ziehst.', 'Geh zurück in die Ausgangsposition und wiederhole das, bis keine Wiederholung mehr geht.', 'Stell dich dann um und mach denselben Ablauf auf der anderen Seite.']::text[]),
  ('Cable_Lying_Triceps_Extension', 'de', array['Leg dich auf eine Flachbank und fasse die gerade Stange am unteren Kabelzug eng im Obergriff. Tipp: Am einfachsten geht es, wenn dir jemand die Stange reicht, sobald du liegst.', 'Streck die Arme aus und bring die Stange über deinen Oberkörper. Arme und Oberkörper bilden einen 90-Grad-Winkel. Das ist deine Ausgangsposition.', 'Senke die Stange, indem du die Ellbogen beugst. Die Oberarme bleiben ruhig, die Ellbogen eng. Geh so weit, bis die Stange leicht deine Stirn berührt. Atme dabei ein.', 'Spann den Trizeps an und drück die Stange zurück in die Ausgangsposition. Atme dabei aus.', 'Halte die Spannung eine Sekunde und wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_One_Arm_Tricep_Extension', 'de', array['Stell dich direkt vor den Gewichtsblock und fasse mit der rechten Hand einen Einzelgriff am oberen Kabelzug im Untergriff (supiniert, die Handfläche zeigt nach oben).', 'Zieh den Griff nach unten, bis Oberarm und Ellbogen fest an der Körperseite liegen. Oberarm und Unterarm bilden einen spitzen Winkel (unter 90 Grad). Den anderen Arm kannst du an der Hüfte lassen, und für mehr Gleichgewicht stellst du ein Bein vor und das andere zurück. Das ist deine Ausgangsposition.', 'Spann den Trizeps an und führe den Griff seitlich nach unten, bis der Arm gestreckt ist. Atme dabei aus. Tipp: Nur der Unterarm bewegt sich. Der Oberarm bleibt die ganze Zeit ruhig.', 'Drück den Trizeps fest zusammen und halte diese Position eine Sekunde.', 'Lass den Griff langsam in die Ausgangsposition zurück.', 'Mach die vorgesehene Zahl an Wiederholungen und führe die Bewegung dann mit dem anderen Arm aus.']::text[]),
  ('Cable_Preacher_Curl', 'de', array['Stell eine Scottbank etwa 2 Fuß vor einen Kabelzug.', 'Befestige eine gerade Stange an der unteren Rolle.', 'Setz dich an die Scottbank, leg Ellbogen und Oberarme fest auf das Polster und lass dir die Stange vom unteren Kabelzug reichen.', 'Fasse die Stange und streck die Arme auf dem Polster ganz aus. Das ist deine Ausgangsposition.', 'Zieh das Gewicht nun zu den Schultern hoch und spann den Bizeps oben kräftig an. Atme dabei aus. Halte oben außerdem eine Sekunde.', 'Senke das Gewicht langsam in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_Rear_Delt_Fly', 'de', array['Stell die Rollen auf die passende Höhe und wähle das Gewicht. Die Rollen sollten über deinem Kopf sein.', 'Fasse den linken Zug mit der rechten Hand und den rechten mit der linken, sodass sich die Seile vor dir kreuzen. Das ist deine Ausgangsposition.', 'Beginne die Bewegung, indem du die Arme nach hinten und außen führst. Die Arme bleiben dabei gestreckt.', 'Halte am Ende der Bewegung kurz und führe die Griffe dann zurück in die Ausgangsposition.']::text[]),
  ('Cable_Reverse_Crunch', 'de', array['Befestige eine Fußschlaufe am unteren Kabelzug und leg eine Matte davor auf den Boden.', 'Setz dich mit den Füßen zur Rolle hin und befestige das Seil an deinen Knöcheln.', 'Leg dich hin, heb die Beine an und beuge die Knie im 90-Grad-Winkel. Beine und Seil sollten auf einer Linie liegen. Wenn nicht, stell die Rolle höher oder tiefer, bis es passt.', 'Nimm die Hände hinter den Kopf, zieh die Knie zum Oberkörper und heb die Hüfte vom Boden.', 'Halte kurz, senke dann die Hüfte langsam und kontrolliert und bring die Beine zurück in den 90-Grad-Winkel vom Anfang. Auch in der Ruheposition sollte dein Bauch noch unter Spannung stehen.', 'Wiederhole die Bewegung bis zum Muskelversagen.']::text[]),
  ('Cable_Rope_Overhead_Triceps_Extension', 'de', array['Befestige ein Seil an der unteren Rolle des Kabelzugs.', 'Fasse das Seil mit beiden Händen im Neutralgriff (die Handflächen zeigen zueinander) und streck die Arme, bis die Hände direkt über deinem Kopf sind. Die Ellbogen bleiben nah am Kopf, die Arme stehen senkrecht zum Boden, die Fingerknöchel zeigen zur Decke. Das ist deine Ausgangsposition.', 'Senke das Seil langsam hinter den Kopf und halte die Oberarme dabei ruhig. Atme ein und halte kurz, wenn der Trizeps ganz gedehnt ist.', 'Spann den Trizeps an und atme aus, um in die Ausgangsposition zurückzukehren.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_Rope_Rear-Delt_Rows', 'de', array['Setz dich an ein Rudergerät mit unterer Rolle, genauso wie beim sitzenden Kabelrudern für den Rücken.', 'Befestige ein Seil an der Rolle und fasse es im Obergriff. Die Arme sind gestreckt und parallel zum Boden, die Ellbogen zeigen nach außen.', 'Halte den unteren Rücken aufrecht und schieb die Hüfte nach hinten, bis die Knie leicht gebeugt sind. Das ist deine Ausgangsposition.', 'Zieh das Seil zur oberen Brust, knapp unter den Hals, und halte die Ellbogen dabei hoch und seitlich. Atme aus und zieh weiter, bis die Ellbogen leicht hinter dem Rücken sind. Tipp: Die Oberarme bleiben während der ganzen Bewegung waagerecht, senkrecht zum Oberkörper und parallel zum Boden.', 'Geh zurück in die Anfangsposition: Arme gestreckt, Schultern nach vorn gedehnt. Atme dabei ein.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_Russian_Twists', 'de', array['Befestige einen normalen Griff und stell die Rolle auf mittlere Höhe.', 'Leg dich quer zum Seil auf einen Gymnastikball und fasse den Griff mit einer Hand. Du solltest etwa eine Armlänge von der Rolle entfernt sein, sodass das Gewicht das Seil spannt.', 'Fasse den Griff mit beiden Händen und streck die Arme ganz über der Brust aus. Deine Hände sollten genau auf Höhe der Rolle sein. Wenn nicht, stell die Rolle höher oder tiefer, bis es passt.', 'Halte die Hüfte oben und den Bauch angespannt. Dreh den Oberkörper eine volle Vierteldrehung von der Rolle weg. Dein Körper bildet vom Kopf bis zu den Knien eine gerade Fläche.', 'Halte kurz und geh langsam und kontrolliert zurück in die Ausgangsposition. Auch in der Ruheposition sollte das Seil noch seitlich ziehen.', 'Wiederhole die Bewegung bis zum Muskelversagen.', 'Wechsle dann die Position und mach denselben Ablauf auf der anderen Seite.']::text[]),
  ('Cable_Seated_Crunch', 'de', array['Setz dich auf eine Flachbank, mit dem Rücken zu einem oberen Kabelzug.', 'Fasse das Seil mit beiden Händen (die Handflächen zeigen zueinander) und halte die Hände fest über beiden Schultern. Tipp: Lass das Gewicht deinen unteren Rücken leicht überstrecken. Das ist deine Ausgangsposition.', 'Die Hüfte bleibt ruhig. Beuge dich in der Taille, sodass die Ellbogen Richtung Hüfte wandern. Atme dabei aus.', 'Atme ein und geh langsam in die Anfangsposition zurück.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_Seated_Lateral_Raise', 'de', array['Stell dich in die Mitte zwischen zwei gegenüberliegende untere Rollen und stell eine Flachbank direkt hinter dich, quer zu dir, sodass die schmale Kante hinter dir ist. Wähle das Gewicht für jede Rolle.', 'Setz dich auf die Kante der Bank hinter dir und stell die Füße vor die Knie.', 'Beuge dich mit geradem Rücken nach vorn und leg den Oberkörper auf die Oberschenkel.', 'Lass dir die Einzelgriffe der Kabelzüge reichen. Wenn das Gewicht gewählt ist, fasse den linken Zug mit der rechten Hand und den rechten mit der linken. Die Seile laufen unter deinen Knien durch, die Arme sind gestreckt, die Handflächen zeigen zueinander, die Ellbogen sind leicht gebeugt. Das ist die Ausgangsposition.', 'Verändere die Armhaltung nicht und heb die Oberarme seitlich an, bis sie parallel zum Boden und auf Schulterhöhe sind. Atme dabei aus und halte die Spannung eine Sekunde.', 'Atme ein und senke die Arme langsam in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen. Tipp: Halte die Oberarme während der ganzen Übung senkrecht zum Oberkörper und die Ellbogen fest in einem Winkel von 10 bis 30 Grad.']::text[]),
  ('Cable_Shoulder_Press', 'de', array['Schieb die Rollen an den Türmen ganz nach unten und wähle ein passendes Gewicht.', 'Stell dich genau zwischen die beiden Türme. Fasse die Griffe und halte sie auf Schulterhöhe, die Handflächen zeigen nach vorn. Das ist deine Ausgangsposition.', 'Halte Kopf und Brust oben, streck die Ellbogen und drück die Griffe gerade über den Kopf.', 'Halte oben kurz, geh zurück in die Ausgangsposition und wiederhole.']::text[]),
  ('Cable_Shrugs', 'de', array['Fasse eine Stange am unteren Kabelzug im Obergriff (die Handflächen zeigen nach unten), schulterbreit oder etwas weiter.', 'Stell dich aufrecht nah an die Rolle und halte die Stange mit gestreckten Armen vor dir. Das ist deine Ausgangsposition.', 'Atme aus und heb die Stange, indem du die Schultern so hoch wie möglich ziehst. Halte die Spannung oben eine Sekunde. Tipp: Die Arme bleiben die ganze Zeit gestreckt. Hilf nicht mit dem Bizeps nach. Nur die Schultern bewegen sich auf und ab.', 'Senke die Stange zurück in die Anfangsposition.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Cable_Wrist_Curl', 'de', array['Stell zuerst eine Flachbank vor einen unteren Kabelzug mit gerader Stange.', 'Fasse die Stange im Untergriff (Handflächen nach oben), eng bis schulterbreit, und nimm sie hoch, bis deine Unterarme oben auf den Oberschenkeln liegen. Die Handgelenke hängen knapp über die Knie hinaus.', 'Beuge zu Beginn die Handgelenke nach oben und atme dabei aus. Halte die Spannung eine Sekunde.', 'Senke die Handgelenke langsam in die Ausgangsposition und atme dabei ein.', 'Die Unterarme bleiben ruhig: Für diese Übung bewegen sich nur die Handgelenke.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Calf-Machine_Shoulder_Shrug', 'de', array['Stell dich so in die Wadenmaschine, dass die Schulterpolster über deinen Schultern sind. Der Oberkörper ist gerade, die Arme hängen locker gestreckt an den Seiten. Das ist deine Ausgangsposition.', 'Atme aus, zieh die Schultern Richtung Ohren und halte die Spannung eine volle Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Calf_Press', 'de', array['Stell den Sitz so ein, dass deine Beine in der Startposition nur leicht gebeugt sind. Die Fußballen stehen fest auf der Plattform.', 'Wähle ein passendes Gewicht und fasse die Griffe. Das ist deine Ausgangsposition.', 'Streck die Beine in den Knien, sodass sich das Gewicht gerade eben vom Stapel hebt. Die Fußgelenke sind ganz gebeugt, die Zehen zeigen nach oben. Drück nun über die Fußballen so weit wie möglich nach unten.', 'Halte kurz, kehre die Bewegung um und wiederhole.']::text[]),
  ('Calf_Press_On_The_Leg_Press_Machine', 'de', array['Setz dich in eine Beinpresse und stell die Füße direkt vor dir auf die Plattform, mittelweit (schulterbreit).', 'Löse die Sicherungen, die die beladene Plattform halten, und drück die Plattform ganz nach oben, bis deine Beine vor dir gestreckt sind, ohne die Knie durchzudrücken. Hinweis: Bei manchen Beinpressen kannst du die Sicherungen für mehr Sicherheit eingerastet lassen. Wenn deine das zulässt, ist das die bessere Art, die Übung zu machen. Oberkörper und Beine bilden genau einen 90-Grad-Winkel. Setz jetzt vorsichtig Zehen und Fußballen auf den unteren Teil der Plattform, die Fersen ragen darüber hinaus. Die Zehen können nach vorn, nach außen oder nach innen zeigen. Das ist deine Ausgangsposition.', 'Atme aus und drück die Plattform weg, indem du die Fersen hebst: Streck die Fußgelenke so weit wie möglich und spann die Waden an. Die Knie bleiben immer ruhig und dürfen sich zu keinem Zeitpunkt beugen. Halte die Spannung eine Sekunde, bevor du wieder absenkst.', 'Atme ein und geh langsam zurück in die Ausgangsposition: Senke die Fersen und beuge die Fußgelenke, bis die Waden gedehnt sind.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Calf_Raise_On_A_Dumbbell', 'de', array['Halt dich für das Gleichgewicht an etwas Stabilem fest und stell dich auf den Griff einer Kurzhantel. Am besten nimmst du eine mit runden Scheiben, damit sie rollt: So musst du mehr arbeiten, um dich zu stabilisieren, und die Übung wird wirksamer.', 'Roll den Fuß etwas nach vorn, sodass die Wade gut gedehnt wird. Das ist deine Ausgangsposition.', 'Drück dich mit der Wade hoch und roll den Fuß dabei über den Griff, bis die Wade ganz gestreckt ist. Atme dabei aus. Spann die Wade oben kräftig an und halte eine Sekunde. Tipp: Roll die Kurzhantel beim Hochgehen etwas nach hinten.', 'Atme ein und roll die Kurzhantel beim Absenken etwas nach vorn, damit die Dehnung besser wird.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Calf_Raises_-_With_Bands', 'de', array['Nimm ein Trainingsband und stell dich mit den Zehen darauf. Achte darauf, dass das Band zwischen Fuß und Arm auf beiden Seiten gleich lang ist.', 'Halte die Griffe des Bands und heb die Arme neben den Kopf, als wolltest du Schulterdrücken machen. Die Handflächen zeigen nach vorn, die Ellbogen sind gebeugt und zeigen zur Seite. So kommt Spannung auf das Band. Das ist deine Ausgangsposition.', 'Lass die Hände an den Schultern, atme aus und geh auf die Zehenspitzen. Spann die Waden oben kräftig an.', 'Halte die Spannung eine Sekunde und geh dann langsam zurück in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Calf_Stretch_Elbows_Against_Wall', 'de', array['Stell dich ein paar Fuß vor eine Wand, das Gesicht zur Wand.', 'Lehn dich an die Wand und stütz dein Gewicht auf die Unterarme.', 'Versuch, die Fersen am Boden zu lassen. Halte 10-20 Sekunden. Gehst du weiter von der Wand weg, wird es schwerer, gehst du näher heran, wird es leichter.']::text[]),
  ('Calf_Stretch_Hands_Against_Wall', 'de', array['Stell dich mehrere Fuß vor eine Wand, das Gesicht zur Wand. Geh in Schrittstellung und setz einen Fuß nach vorn.', 'Lehn dich nach vorn und stütz die Hände an die Wand. Ferse, Hüfte und Kopf bilden eine gerade Linie.', 'Versuch, die Ferse am Boden zu lassen. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Calves-SMR', 'de', array['Setz dich auf den Boden und leg eine Faszienrolle unter deinen Unterschenkel. Das andere Bein kannst du darüberschlagen oder auf den Boden stellen, sodass es einen Teil deines Gewichts trägt. Das ist deine Ausgangsposition.', 'Stütz die Hände neben oder knapp hinter dir auf und drück dich hoch, bis die Hüfte vom Boden abhebt und ein großer Teil deines Gewichts auf der Wade liegt. Roll von unterhalb des Knies bis oberhalb des Knöchels und bleib an verspannten Stellen 10-30 Sekunden. Wiederhole das mit dem anderen Bein.']::text[]),
  ('Car_Deadlift', 'de', array['Das Gerät für diese Disziplin hat meist Griffe für den Neutralgriff, manche haben aber eine gerade Stange, die du wie beim normalen Kreuzheben angehst. Beladen wird es mit einem Fahrzeug oder anderen schweren Dingen wie Traktorreifen oder Fässern.', 'Stell dich mittig zwischen die Griffe, wenn du stark in der Kniebeuge bist, oder ein paar Zoll weiter hinten, wenn deine Stärke das Kreuzheben ist. Die Füße stehen etwa hüftbreit. Beuge dich aus der Hüfte, um die Griffe zu fassen. Wenn Füße und Griff sitzen, atme tief ein, senke dann die Hüfte und beuge die Knie.', 'Schau nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drück dich über die Fersen ab, um das Gewicht anzuheben. Während es hochkommt, zieh die Schulterblätter zusammen und schieb die Hüfte nach vorn.', 'Senke das Gewicht, indem du in der Hüfte beugst und es zum Boden führst.']::text[]),
  ('Car_Drivers', 'de', array['Stell dich aufrecht hin und halte eine Hantelscheibe mit beiden Händen auf 3 und 9 Uhr. Die Handflächen zeigen zueinander, die Arme sind gerade nach vorn gestreckt. Das ist deine Ausgangsposition.', 'Beginne, indem du die Scheibe so weit wie möglich zu einer Seite drehst, so wie du ein Lenkrad einschlagen würdest.', 'Dreh sie dann zurück und ganz zur anderen Seite.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Carioca_Quick_Step', 'de', array['Stell die Füße ein paar Zoll auseinander und nimm den linken Arm in einer lockeren, athletischen Haltung hoch.', 'Mach mit dem rechten Fuß einen schnellen Schritt nach hinten und zieh das Knie hoch.', 'Reiß die Arme wieder hoch, wenn du das rechte Knie anziehst, und achte darauf, dass das Knie gerade nach oben und unten geht. Dreh die Füße nicht ein und schau weiter nach vorn, während du dich zur Seite bewegst.']::text[]),
  ('Cat_Stretch', 'de', array['Geh auf dem Boden in den Vierfüßlerstand.', 'Zieh den Bauch ein und mach Wirbelsäule, unteren Rücken, Schultern und Nacken rund. Lass den Kopf hängen.', 'Halte 15 Sekunden.']::text[]),
  ('Catch_and_Overhead_Throw', 'de', array['Stell dich mit dem Gesicht zu einer Wand oder einem Partner.', 'Nimm den Ball mit beiden Händen hinter den Kopf, dehn dich so weit wie möglich und wirf den Ball kraftvoll nach vorn.', 'Zieh den Wurf ganz durch und sei bereit, den zurückprallenden Ball zu fangen. Wirfst du gegen die Wand, stell dich nah genug heran, um den Abpraller zu fangen, und ziel etwas höher als bei einem Partner.']::text[]),
  ('Chain_Handle_Extension', 'de', array['Für diese Übung brauchst du zwei Kabelzuggriffe, eine Flachbank und Ketten. Häng die Ketten in der Mitte in die Griffe ein und leg dich auf die Flachbank. Deine Ellbogen zeigen gerade nach oben.', 'Streck zuerst die Ellbogen. Die Oberarme bleiben ruhig, die Handgelenke sind proniert.', 'Halte kurz, wenn die Arme durchgestreckt sind, und kehre die Bewegung um, zurück in die Ausgangsposition.']::text[]),
  ('Chain_Press', 'de', array['Verbinde zuerst die Ketten mit den Kabelzuggriffen. Leg dich so auf die Flachbank wie beim Kurzhanteldrücken. Die Handgelenke sind proniert, die Arme stehen senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Senke die Ketten, indem du die Ellbogen beugst. Ein Teil der Kette legt sich dabei auf dem Boden ab.', 'Geh weiter, bis die Ellbogen einen 90-Grad-Winkel bilden, und kehre dann um: Streck die Ellbogen, bis die Arme durchgestreckt sind.']::text[]),
  ('Chair_Leg_Extended_Stretch', 'de', array['Setz dich aufrecht auf einen Stuhl und halt dich seitlich an der Sitzfläche fest.', 'Heb ein Bein, streck dabei das Knie und beuge das Fußgelenk.', 'Führe das Bein langsam so weit wie möglich nach außen, dann zurück zur Mitte und nach unten.', 'Wiederhole das mit dem anderen Bein.']::text[]),
  ('Chair_Lower_Back_Stretch', 'de', array['Setz dich aufrecht auf einen Stuhl.', 'Neig dich zu einer Seite und führe den Arm über den Kopf. Mit der freien Hand kannst du dich am Stuhl festhalten.', 'Halte 10 Sekunden und wiederhole das auf der anderen Seite.']::text[]),
  ('Chair_Squat', 'de', array['Stell die Stange zuerst auf die Höhe ein, die am besten zu deiner Größe passt. Ist sie beladen, tritt darunter und leg sie hinten quer über die Schultern.', 'Fasse die Stange mit den Handflächen nach vorn, entriegle sie und heb sie aus der Ablage, indem du die Beine streckst.', 'Stell die Füße etwa 18 Zoll vor die Stange. Die Beine stehen schulterbreit, die Zehen zeigen leicht nach außen. Schau die ganze Zeit nach vorn und halte die Wirbelsäule neutral oder leicht im Hohlkreuz. Das ist deine Ausgangsposition.', 'Senke die Stange langsam, indem du die Knie beugst. Bleib dabei aufrecht, der Kopf ist oben. Geh so tief, bis der Winkel zwischen Ober- und Unterschenkel kleiner als 90 Grad ist.', 'Atme aus und drück die Stange hoch: Stemm die Fersen in den Boden, streck die Knie und komm zurück in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Zahl an Wiederholungen.']::text[]),
  ('Chair_Upper_Body_Stretch', 'de', array['Setz dich auf die Stuhlkante und fasse die Lehne.', 'Streck die Arme, halte den Rücken gerade und zieh den Oberkörper nach vorn, bis du eine Dehnung spürst. Halte 20-30 Sekunden.']::text[]),
  ('Chest_And_Front_Of_Shoulder_Stretch', 'de', array['Stell dich mit geschlossenen Beinen hin und halte eine Gymnastikstange oder einen Besenstiel.', 'Fasse den Stab etwas weiter als schulterbreit und halte ihn vor dir, die Handflächen zeigen nach unten.', 'Heb den Stab vorsichtig nach oben und hinter den Kopf.']::text[]),
  ('Chest_Push_from_3_point_stance', 'de', array['Beginne im Dreipunktstand: in der Hocke, der Rücken gerade, eine Hand am Boden. Leg den Medizinball direkt vor dich.', 'Mach den ersten Schritt und zieh dabei den Ball zur Brust. Bring beide Hände in Position für den Wurf.', 'Stoß den Ball beim zweiten Schritt explosiv und so fest wie möglich nach vorn.']::text[]),
  ('Chest_Push_multiple_response', 'de', array['Knie dich vor eine Wand oder arbeite mit einem Partner. Halte den Ball mit beiden Händen eng an der Brust.', 'Für den Pass schnellst du mit der Hüfte nach vorn und außen und stößt den Ball so fest wie möglich weg.', 'Zieh die Bewegung durch, lass dich nach vorn fallen und fang dich mit den Händen ab.', 'Komm sofort wieder in die aufrechte Position. Wiederhole das für die gewünschte Zahl an Wiederholungen.']::text[]),
  ('Chest_Push_single_response', 'de', array['Knie dich hin und halte den Medizinball mit beiden Händen eng an der Brust.', 'Für den Pass schnellst du mit der Hüfte nach vorn und außen und stößt den Ball so weit wie möglich weg.', 'Zieh die Bewegung durch, lass dich nach vorn fallen und fang dich mit den Händen ab.']::text[]),
  ('Chest_Push_with_Run_Release', 'de', array['Beginne in athletischer Haltung: Knie gebeugt, Hüfte nach hinten, Rücken gerade. Halte den Medizinball nah an den Beinen. Das ist deine Ausgangsposition.', 'Zieh den Medizinball beim ersten Schritt an die Brust.', 'Stoß den Ball beim zweiten Schritt explosiv nach vorn und sprinte direkt nach dem Loslassen 10 Yards. Wenn du richtig schnell bist, fängst du deinen eigenen Pass!']::text[]),
  ('Chest_Stretch_on_Stability_Ball', 'de', array['Geh neben einem Gymnastikball in den Vierfüßlerstand.', 'Leg den Ellbogen oben auf den Ball, der Arm zeigt zur Seite. Das ist deine Ausgangsposition.', 'Senke den Oberkörper Richtung Boden, der Ellbogen bleibt auf dem Ball. Halte die Dehnung 20-30 Sekunden und wiederhole sie mit dem anderen Arm.']::text[]),
  ('Childs_Pose', 'de', array['Geh in den Vierfüßlerstand und wandere mit den Händen nach vorn.', 'Senke das Gesäß, bis du auf den Fersen sitzt. Lass die Arme beim Zurücksetzen über den Boden schleifen, damit die ganze Wirbelsäule gedehnt wird.', 'Wenn du auf den Fersen sitzt, leg die Hände neben die Füße und entspann dich. "Atme" in den Rücken. Leg die Stirn auf den Boden. Meide diese Position, wenn du Knieprobleme hast.']::text[]),
  ('Chin-Up', 'de', array['Fasse die Klimmzugstange so, dass die Handflächen zu dir zeigen, und greif enger als schulterbreit.', 'Häng mit gestreckten Armen in der gewählten Griffweite an der Stange. Halte den Oberkörper so gerade wie möglich, mach ein leichtes Hohlkreuz und streck die Brust heraus. Das ist deine Ausgangsposition. Tipp: Je gerader der Oberkörper bleibt, desto mehr arbeitet der Bizeps und desto weniger der Rücken.', 'Atme aus und zieh dich hoch, bis dein Kopf etwa auf Höhe der Stange ist. Konzentrier dich darauf, die Bewegung mit dem Bizeps zu machen. Die Ellbogen bleiben nah am Körper. Tipp: Der Oberkörper bleibt in sich ruhig, während er sich nach oben bewegt, nur die Arme arbeiten. Die Unterarme tun nichts weiter, als die Stange zu halten.', 'Spann den Bizeps oben eine Sekunde an und lass dich dann langsam in die Ausgangsposition ab, bis die Arme ganz gestreckt sind. Atme dabei ein.', 'Wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Chin_To_Chest_Stretch', 'de', array['Setz dich auf den Boden.', 'Leg beide Hände an den Hinterkopf, die Finger verschränkt, die Daumen nach unten, die Ellbogen gerade nach vorn. Zieh den Kopf langsam zur Brust. Halte 20-30 Sekunden.']::text[]),
  ('Circus_Bell', 'de', array['Die Circus Bell ist eine übergroße Kurzhantel mit dickem Griff. Stell sie zu Beginn zwischen deine Füße und fasse den Griff mit beiden Händen.', 'Setz die Hantel um: Streck Hüfte und Knie und bring sie so auf die gewünschte Schulter. Lass dabei die zweite Hand los.', 'Achte darauf, dass einer der Hantelköpfe hinter der Schulter liegt, damit du nicht aus dem Gleichgewicht kommst. Um sie über den Kopf zu bringen, geh kurz in die Knie, drück dich dann nach oben ab und streck die Hantel über den Kopf. Lehn dich dabei leicht von ihr weg.', 'Führe die Hantel vorsichtig zurück zum Boden und halte sie dabei so gut wie möglich unter Kontrolle. Am besten machst du diese Disziplin auf einer dicken Gummimatte, damit der Boden keinen Schaden nimmt.']::text[]),
  ('Clean', 'de', array['Die Langhantel liegt nah an den Schienbeinen auf dem Boden. Fasse sie im Obergriff (oder Hakengriff) knapp außerhalb der Beine. Senke die Hüfte: Das Gewicht liegt auf den Fersen, der Rücken ist gerade, der Blick geht nach vorn, die Brust ist oben, die Schultern sind knapp vor der Stange. Das ist deine Ausgangsposition.', 'Beginne den ersten Zug, indem du dich über die Fersen abdrückst und die Knie streckst. Der Rückenwinkel bleibt gleich, die Arme bleiben gestreckt. Führe das Gewicht kontrolliert bis über die Knie.', 'Dann folgt der zweite Zug, aus dem das Umsetzen den größten Teil seiner Beschleunigung holt. Wenn die Stange die Mitte der Oberschenkel erreicht, fang an, die Hüfte zu strecken. Beschleunige wie bei einem Sprung, indem du Hüfte, Knie und Fußgelenke streckst, und bring die Stange mit diesem Tempo nach oben. Aktiv mit den Armen zu ziehen, sollte dafür nicht nötig sein: Am Ende des zweiten Zugs ist der Körper ganz gestreckt und leicht nach hinten geneigt, die Arme sind noch gestreckt.', 'Ist die volle Streckung erreicht, geh in den dritten Zug über: Zieh die Schultern energisch hoch und beuge die Arme, die Ellbogen gehen nach oben und außen. Am höchsten Punkt der Streckung ziehst du dich energisch nach unten und drehst dabei die Ellbogen unter die Stange. Nimm die Stange in der Position der Frontkniebeuge auf. Wie tief, hängt davon ab, wie hoch die Stange am Ende des dritten Zugs war. Die Stange liegt auf den nach vorn geschobenen Schultern und berührt leicht den Hals, die Hände sind locker. Geh weiter nach unten bis in die tiefe Hocke, das hilft beim Aufstehen.', 'Steh sofort wieder auf, indem du dich über die Fersen abdrückst. Der Oberkörper bleibt aufrecht, die Ellbogen bleiben oben. Mach weiter, bis du ganz stehst.']::text[]),
  ('Clean_Deadlift', 'de', array['Stelle dich so hin, dass die Langhantel dicht vor deinen Schienbeinen liegt. Die Füße stehen genau unter der Hüfte und sind leicht nach außen gedreht. Greife die Stange etwa schulterbreit, mit beiden Händen im Obergriff oder im Hakengriff. Gehe zur Stange in die Hocke. Strecke die Wirbelsäule ganz; der Winkel deines Rückens bringt die Schultern vor die Stange, und der Rücken ist dabei so aufrecht wie möglich.', 'Drücke dich zu Beginn mit dem vorderen Teil der Fersen vom Boden ab. Halte den Winkel deines Rückens gleich, während die Stange nach oben wandert. Schiebe die Knie nach außen, damit sie der Stange nicht im Weg sind.', 'Hat die Stange die Knie passiert, beende das Heben: Schiebe die Hüfte zur Stange, bis Hüfte und Knie gestreckt sind.']::text[]),
  ('Clean_Pull', 'de', array['Die Langhantel liegt dicht vor deinen Schienbeinen auf dem Boden. Greife sie knapp außerhalb der Beine im Obergriff oder Hakengriff. Senke die Hüfte und verlagere das Gewicht auf die Fersen. Der Rücken ist gerade, der Blick geht nach vorn, die Brust ist angehoben, die Schultern stehen knapp vor der Stange. Das ist deine Ausgangsposition.', 'Beginne den ersten Zug: Drücke dich über die Fersen ab und strecke die Knie. Der Winkel deines Rückens bleibt gleich, die Arme bleiben gestreckt und die Ellbogen zeigen nach außen. Führe das Gewicht kontrolliert bis über die Knie.', 'Jetzt kommt der zweite Zug, aus dem das Umsetzen den größten Teil seiner Beschleunigung holt. Nähert sich die Stange der Mitte der Oberschenkel, beginne die Hüfte zu strecken. Beschleunige wie bei einem Sprung: Strecke Hüfte, Knie und Sprunggelenke und bringe die Stange mit diesem Tempo nach oben. Mit den Armen musst du nicht aktiv ziehen, um das Gewicht zu beschleunigen. Am Ende des zweiten Zugs ist dein Körper ganz gestreckt und leicht nach hinten geneigt, die Arme sind noch immer gestreckt. Die volle Streckung soll heftig und abrupt sein; halte sie nicht länger als nötig.']::text[]),
  ('Clean_Shrug', 'de', array['Greife die Stange schulterbreit, mit beiden Händen im Obergriff oder im Hakengriff, sodass sie auf Höhe der Oberschenkelmitte hängt. Der Rücken ist gerade und leicht nach vorn geneigt.', 'Ziehe die Schultern zu den Ohren hoch. Meist kannst du hier mehr Gewicht auflegen als beim Umsetzen, lade aber nicht so viel auf, dass die Ausführung langsamer wird.']::text[]),
  ('Clean_and_Jerk', 'de', array['Die Langhantel liegt dicht vor deinen Schienbeinen auf dem Boden. Greife sie knapp außerhalb der Beine im Obergriff oder Hakengriff. Senke die Hüfte und verlagere das Gewicht auf die Fersen. Der Rücken ist gerade, der Blick geht nach vorn, die Brust ist angehoben, die Schultern stehen knapp vor der Stange. Das ist deine Ausgangsposition.', 'Beginne den ersten Zug: Drücke dich über die Fersen ab und strecke die Knie. Der Winkel deines Rückens bleibt gleich, die Arme bleiben gestreckt. Führe das Gewicht kontrolliert bis über die Knie.', 'Jetzt kommt der zweite Zug, aus dem das Umsetzen den größten Teil seiner Beschleunigung holt. Nähert sich die Stange der Mitte der Oberschenkel, beginne die Hüfte zu strecken. Beschleunige wie bei einem Sprung: Strecke Hüfte, Knie und Sprunggelenke und bringe die Stange mit diesem Tempo nach oben. Mit den Armen musst du nicht aktiv ziehen, um das Gewicht zu beschleunigen. Am Ende des zweiten Zugs ist dein Körper ganz gestreckt und leicht nach hinten geneigt, die Arme sind noch immer gestreckt.', 'Sobald du ganz gestreckt bist, gehe in den dritten Zug über: Ziehe die Schultern kräftig hoch und beuge die Arme, die Ellbogen zeigen nach oben und außen. Am höchsten Punkt der Streckung ziehst du dich kräftig nach unten und drehst dabei die Ellbogen unter die Stange. Fange die Stange in der Frontkniebeuge auf; wie tief, hängt davon ab, wie hoch die Stange am Ende des dritten Zugs war. Lege die Stange auf den nach vorn geschobenen Schultern ab, sodass sie den Hals leicht berührt, und lass die Hände locker. Sinke weiter bis in die tiefe Kniebeuge, das erleichtert das Aufstehen.', 'Stehe sofort wieder auf: Drücke dich über die Fersen ab, halte den Oberkörper aufrecht und die Ellbogen oben. Mach weiter, bis du aufrecht stehst.', 'Die zweite Phase ist das Stoßen, es bringt das Gewicht über den Kopf. Du stehst mit der Stange vorn auf den Schultern und beginnst mit dem Dip. Stelle die Füße genau unter die Hüfte und beuge die Knie, ohne die Hüfte nach hinten zu schieben. Gehe nur ein kleines Stück nach unten und kehre die Bewegung so kraftvoll wie möglich um.', 'Drücke dich über die Fersen ab und erzeuge so viel Tempo und Kraft, wie du kannst. Nimm unbedingt den Kopf aus dem Weg, wenn die Stange die Schultern verlässt.', 'In dem Moment, in dem deine Füße den Boden verlassen, bringst du sie so schnell wie möglich in die Fangposition. In dem kurzen Augenblick, in dem die Füße nicht gegen die Plattform drücken, treibt dich dein Druck gegen die Stange nach unten. Setze die Füße im Ausfallschritt auf, einen nach vorn und einen nach hinten. Fange die Stange mit durchgestreckten Armen über dem Kopf auf. Komm zurück in den Stand.']::text[]),
  ('Clean_and_Press', 'de', array['Stelle dich schulterbreit hin, die Knie befinden sich zwischen den Armen. Halte den Rücken flach und beuge Knie und Hüfte so weit, dass du die Stange mit ganz gestreckten Armen greifen kannst, im Obergriff und etwas weiter als schulterbreit. Drehe die Ellbogen nach außen. Die Stange ist dicht an den Schienbeinen. Bringe die Schultern über die Stange oder leicht vor sie. Halte den Rücken flach. Das ist deine Ausgangsposition.', 'Beginne den Zug, indem du die Knie streckst. Schiebe die Hüfte nach vorn und hebe die Schultern im gleichen Tempo, damit der Winkel deines Rückens gleich bleibt. Hebe die Stange weiter gerade nach oben, dicht am Körper.', 'Hat die Stange die Knie passiert, strecke Sprunggelenke, Knie und Hüfte kraftvoll, ähnlich wie bei einem Sprung. Führe die Stange dabei weiter mit den Händen: Ziehe die Schultern hoch und nutze den Schwung der Bewegung, um die Stange so hoch wie möglich zu ziehen. Die Stange bleibt dicht am Körper, die Ellbogen zeigen nach außen.', 'Am höchsten Punkt sollten deine Füße den Boden verlassen, und du beginnst, dich unter die Stange zu ziehen. Wie das genau abläuft, kann sich je nach Gewicht leicht ändern. Gehe in die Kniebeuge, während du dich unter die Stange ziehst.', 'Erreicht die Stange ihre größte Höhe, drehe die Ellbogen um die Stange herum und unter sie. Lege die Stange vorn auf den Schultern ab, halte den Oberkörper aufrecht und beuge Hüfte und Knie, um das Gewicht der Stange abzufangen.', 'Richte dich ganz auf und halte die Stange in der Position nach dem Umsetzen.', 'Lass die Füße, wo sie sind, atme aus und drücke die Stange über den Kopf. Senke die Stange kontrolliert ab.']::text[]),
  ('Clean_from_Blocks', 'de', array['Die Langhantel liegt auf Kisten oder Ständern in der gewünschten Höhe. Greife sie knapp außerhalb der Beine im Obergriff oder Hakengriff. Senke die Hüfte und verlagere das Gewicht auf die Fersen. Der Rücken ist gerade, der Blick geht nach vorn, die Brust ist angehoben, die Schultern stehen knapp vor der Stange. Das ist deine Ausgangsposition.', 'Beginne den ersten Zug: Drücke dich über die Fersen ab und strecke die Knie. Der Winkel deines Rückens bleibt gleich, die Arme bleiben gestreckt und die Ellbogen zeigen nach außen.', 'Sobald du ganz gestreckt bist, gehe in die Fangposition über: Ziehe die Schultern kräftig hoch und beuge die Arme, die Ellbogen zeigen nach oben und außen. Ziehe dich kräftig nach unten und drehe dabei die Ellbogen unter die Stange. Fange die Stange in der Frontkniebeuge auf; wie tief, hängt davon ab, wie hoch die Stange am Ende des dritten Zugs war. Lege die Stange auf den nach vorn geschobenen Schultern ab, sodass sie den Hals leicht berührt, und lass die Hände locker. Sinke weiter bis in die tiefe Kniebeuge, das erleichtert das Aufstehen.', 'Stehe sofort wieder auf: Drücke dich über die Fersen ab, halte den Oberkörper aufrecht und die Ellbogen oben. Mach weiter, bis du aufrecht stehst. Lege das Gewicht für die nächste Wiederholung zurück auf die Kisten.']::text[]),
  ('Clock_Push-Up', 'de', array['Gehe in Bauchlage auf den Boden und stütze dein Gewicht auf Hände und Zehen.', 'Strecke die Arme ganz, die Hände stehen etwa schulterbreit. Halte den Körper während der ganzen Bewegung gerade. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und senke die Brust zum Boden.', 'Kehre unten die Bewegung um: Strecke die Ellbogen und drücke dich so schnell wie möglich hoch, bis du vom Boden abhebst. Versuche, 12-18 inches zu einer Seite zu "springen".', 'Setze beim Beschleunigen nach oben den äußeren Fuß weg von der Richtung, in die du dich bewegst. Drehe den Körper beim Abheben um etwa 30 Grad für die nächste Wiederholung.', 'Komm zurück in die Ausgangsposition und wiederhole die Übung. Arbeite dich einmal ganz im Kreis herum, bis du wieder dort bist, wo du angefangen hast.']::text[]),
  ('Close-Grip_Barbell_Bench_Press', 'de', array['Lege dich auf eine Flachbank. Greife die Stange eng, etwa schulterbreit, hebe sie aus der Ablage und halte sie mit durchgestreckten Armen gerade über dir. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis sie die Mitte deiner Brust berührt. Tipp: Halte die Ellbogen, anders als beim normalen Bankdrücken, die ganze Zeit dicht am Oberkörper, damit der Trizeps so viel wie möglich arbeitet.', 'Halte eine Sekunde inne, atme dann aus und drücke die Stange mit dem Trizeps zurück in die Ausgangsposition. Strecke die Arme oben durch, halte eine Sekunde und senke dann wieder langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.', 'Lege die Stange zum Schluss zurück in die Ablage.']::text[]),
  ('Close-Grip_Dumbbell_Press', 'de', array['Stelle eine Kurzhantel aufrecht auf eine Flachbank.', 'Achte darauf, dass die Kurzhantel sicher oben auf der Bank stehen bleibt. Lege dich quer zur Bank, sodass nur deine Schultern aufliegen. Die Hüfte ist tiefer als die Bank, die Beine sind gebeugt und die Füße stehen fest auf dem Boden.', 'Fasse die Kurzhantel mit beiden Händen und halte sie mit gestreckten Armen gerade über der Brust. Beide Handflächen drücken von unten gegen die Seiten der Kurzhantel. Das ist deine Ausgangsposition.', 'Beginne die Bewegung: Senke die Kurzhantel zur Brust.', 'Strecke die Ellbogen, um in die Ausgangsposition zurückzukommen.']::text[]),
  ('Close-Grip_EZ-Bar_Curl_with_Band', 'de', array['Befestige an jedem Ende der Stange ein Band. Nimm die Stange und stelle einen Fuß auf die Mitte des Bands. Stehe aufrecht und greife die SZ-Stange eng im Untergriff. Die Ellbogen sind dicht am Oberkörper. Das ist deine Ausgangsposition.', 'Halte die Oberarme an ihrem Platz und beuge die Ellbogen für den Curl. Atme aus, während du das Gewicht hebst.', 'Führe die Bewegung fort, bis der Bizeps ganz angespannt ist und die Stange auf Schulterhöhe steht. Bleibe eine Sekunde dort und spanne den Bizeps fest an.', 'Atme ein und senke die Stange langsam in die Ausgangsposition.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Close-Grip_EZ-Bar_Press', 'de', array['Belade eine SZ-Stange mit einem passenden Gewicht und lege dich damit auf eine Flachbank.', 'Hebe die Stange im engen Griff an und halte sie gerade über dem Oberkörper, die Ellbogen nach innen. Die Arme stehen senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange zur unteren Brust. Halte die Ellbogen bei der Bewegung innen.', 'Atme aus und drücke die Stange mit dem Trizeps wieder hoch: Strecke die Ellbogen, bis du zurück in der Ausgangsposition bist.', 'Wiederhole.']::text[]),
  ('Close-Grip_EZ_Bar_Curl', 'de', array['Stehe mit aufrechtem Oberkörper und halte eine SZ-Stange an den inneren, engeren Griffstellen. Die Handflächen zeigen nach vorn und sind durch die Form der Stange leicht nach innen geneigt. Die Ellbogen sind dicht am Oberkörper. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge das Gewicht nach vorn oben, indem du den Bizeps anspannst. Tipp: Nur die Unterarme sollen sich bewegen.', 'Führe die Bewegung fort, bis der Bizeps ganz angespannt ist und die Stange auf Schulterhöhe steht. Bleibe eine Sekunde dort und spanne den Bizeps fest an.', 'Atme ein und senke die Stange langsam in die Ausgangsposition.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Close-Grip_Front_Lat_Pulldown', 'de', array['Setze dich an einen Latzug, an dessen oberer Rolle eine breite Stange hängt. Stelle das Kniepolster der Maschine auf deine Größe ein. Die Polster verhindern, dass der Widerstand an der Stange deinen Körper anhebt.', 'Greife die Stange in der vorgegebenen Griffweite, die Handflächen zeigen nach vorn. Hinweis zu den Griffen: Beim weiten Griff sind deine Hände weiter auseinander als die Schultern. Beim mittleren Griff sind sie so weit auseinander wie die Schultern, beim engen Griff enger als die Schultern.', 'Beide Arme sind vor dir gestreckt und halten die Stange in der gewählten Griffweite. Lehne den Oberkörper um etwa 30 Grad zurück, gehe im unteren Rücken ins Hohlkreuz und strecke die Brust heraus. Das ist deine Ausgangsposition.', 'Atme aus und ziehe die Stange herunter, bis sie die obere Brust berührt; ziehe dafür Schultern und Oberarme nach unten und hinten. Tipp: Konzentriere dich in der voll angespannten Position darauf, die Rückenmuskeln fest anzuspannen. Der Oberkörper soll ruhig bleiben, nur die Arme bewegen sich. Die Unterarme sollen nur die Stange halten und sonst nichts tun; versuche also nicht, die Stange mit ihnen herunterzuziehen.', 'Halte die Anspannung eine Sekunde und drücke dabei die Schulterblätter zusammen. Lass die Stange dann langsam in die Ausgangsposition steigen, in der die Arme ganz gestreckt sind und der Latissimus ganz gedehnt ist. Atme in diesem Teil der Bewegung ein.', 'Wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Close-Grip_Push-Up_off_of_a_Dumbbell', 'de', array['Gehe auf den Boden und setze die Hände auf eine aufrecht stehende Kurzhantel. Stütze dein Gewicht auf Zehen und Hände, halte den Rumpf steif, die Ellbogen innen und die Arme gestreckt. Das ist deine Ausgangsposition.', 'Atme ein und senke den Körper, indem du die Ellbogen beugst. Bleibe gerade; die Hüfte darf weder hochkommen noch durchhängen.', 'Strecke die Ellbogen und drücke dich zurück in die Ausgangsposition. Atme bei diesem Schritt aus.', 'Halte in der angespannten Position kurz inne und wiederhole die Bewegung dann für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Close-Grip_Standing_Barbell_Curl', 'de', array['Nimm eine Langhantel mit beiden Händen, die Handflächen zeigen nach oben und sind ein paar inches auseinander.', 'Stehe mit geradem Oberkörper und erhobenem Kopf. Die Füße stehen etwa schulterbreit, die Ellbogen sind dicht am Oberkörper. Das ist deine Ausgangsposition. Tipp: Oberarme und Ellbogen bleiben während der ganzen Bewegung ruhig.', 'Beuge die Stange im Halbkreis nach oben, bis die Unterarme den Bizeps berühren. Atme in diesem Teil der Bewegung aus und spanne den Bizeps oben eine Sekunde lang fest an. Tipp: Beuge beim Heben nicht den Rücken und hole keinen Schwung. Nur die Unterarme sollen sich bewegen.', 'Atme ein und gehe langsam zurück in die Ausgangsposition.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Cocoons', 'de', array['Lege dich auf dem Boden auf den Rücken. Die Beine sind gestreckt, die Arme hinter dem Kopf ausgestreckt. Das ist deine Ausgangsposition.', 'Ziehe für die Bewegung die Knie zur Brust und kippe das Becken, sodass sich das Gesäß vom Boden hebt. Runde dabei die Wirbelsäule und führe die Arme über den Kopf nach vorn, sodass du gleichzeitig einen Crunch machst.', 'Halte kurz inne und gehe zurück in die Ausgangsposition.']::text[]),
  ('Conans_Wheel', 'de', array['Ist das Gewicht aufgeladen, nimm das Ende des Geräts im Zercher-Griff. Lege die Stange in die Armbeugen und halte dein Handgelenk fest. Versuche, das Gewicht nicht auf den Unterarmen lasten zu lassen.', 'Hebe zuerst das Gewicht vom Boden. Bleibe fest angespannt und aufrecht, während du mit kurzen, schnellen Schritten losgehst. Blicke nach oben und in die Ferne, während du im Kreis gehst. Halte während der Disziplin nicht den Atem an. Gehe weiter, bis du eine oder mehrere ganze Runden geschafft hast.']::text[]),
  ('Concentration_Curls', 'de', array['Setze dich auf eine Flachbank, eine Kurzhantel liegt vor dir zwischen den Beinen. Die Beine sind gespreizt, die Knie gebeugt, die Füße stehen auf dem Boden.', 'Hebe die Kurzhantel mit dem rechten Arm auf. Lege die Rückseite des rechten Oberarms oben an die Innenseite des rechten Oberschenkels. Drehe die Handfläche, bis sie nach vorn zeigt, weg vom Oberschenkel. Tipp: Der Arm ist gestreckt, die Kurzhantel schwebt über dem Boden. Das ist deine Ausgangsposition.', 'Halte den Oberarm ruhig, atme aus und beuge das Gewicht nach vorn oben, indem du den Bizeps anspannst. Nur der Unterarm soll sich bewegen. Führe die Bewegung fort, bis der Bizeps ganz angespannt ist und die Kurzhantel auf Schulterhöhe steht. Tipp: Achte oben darauf, dass der kleine Finger höher ist als der Daumen. Das sorgt für eine gute Kontraktion. Bleibe eine Sekunde in der angespannten Position und spanne den Bizeps fest an.', 'Atme ein und senke die Kurzhantel langsam in die Ausgangsposition. Vorsicht: Hole zu keinem Zeitpunkt Schwung.', 'Wiederhole die empfohlene Zahl an Wiederholungen. Mach dann dasselbe mit dem linken Arm.']::text[]),
  ('Cross-Body_Crunch', 'de', array['Lege dich flach auf den Rücken und beuge die Knie um etwa 60 Grad.', 'Stelle die Füße flach auf den Boden und lege die Hände locker hinter den Kopf. Das ist deine Ausgangsposition.', 'Rolle dich jetzt auf und führe den rechten Ellbogen und die rechte Schulter quer über den Körper; ziehe gleichzeitig das linke Knie zur linken Schulter. Strecke dich mit dem Ellbogen und versuche, das Knie zu berühren. Atme bei dieser Bewegung aus. Tipp: Versuche, die Schulter zum Knie zu bringen und nicht nur den Ellbogen. Entscheidend ist, dass du bei der Bewegung den Bauch anspannst, nicht bloß den Ellbogen bewegst.', 'Atme ein und senke dich zurück in die Ausgangsposition. Wiederhole dann mit dem linken Ellbogen und dem rechten Knie.', 'Wechsle so weiter ab, bis du alle vorgegebenen Wiederholungen gemacht hast.']::text[]),
  ('Cross_Body_Hammer_Curl', 'de', array['Stehe aufrecht mit einer Kurzhantel in jeder Hand. Die Hände hängen seitlich am Körper, die Handflächen zeigen nach innen.', 'Lass die Handflächen nach innen zeigen und verdrehe den Arm nicht. Atme aus und beuge die Kurzhantel der rechten Hand nach oben zur linken Schulter. Berühre die Schulter mit dem oberen Ende der Kurzhantel und halte die Kontraktion eine Sekunde.', 'Atme ein und senke die Kurzhantel langsam auf demselben Weg ab. Mach dann die gleiche Bewegung mit dem linken Arm.', 'Wechsle so weiter ab, bis jeder Arm die empfohlene Zahl an Wiederholungen gemacht hat.']::text[]),
  ('Cross_Over_-_With_Bands', 'de', array['Befestige ein Trainingsband an einem festen Pfosten.', 'Stelle dich mit dem Rücken zum Pfosten, fasse die Griffe an beiden Enden des Bands und gehe so weit nach vorn, dass das Band unter Spannung steht.', 'Hebe die Arme seitlich an, bis sie parallel zum Boden und im rechten Winkel zum Oberkörper sind, sodass Oberkörper und Arme wie der Buchstabe "T" aussehen. Die Handflächen zeigen nach vorn. Die Arme sind gestreckt, die Ellbogen leicht gebeugt. Das ist deine Ausgangsposition.', 'Halte die Arme gestreckt, atme aus und führe sie im Halbkreis nach vorn vor die Brust, während du die Brustmuskeln anspannst. Halte die Kontraktion eine Sekunde.', 'Atme ein und gehe langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Crossover_Reverse_Lunge', 'de', array['Stelle dich mit schulterbreit geöffneten Füßen hin. Das ist deine Ausgangsposition.', 'Mach einen Ausfallschritt nach hinten: Setze einen Fuß zurück und beuge die Hüfte und das vordere Knie. Drehe dabei den Oberkörper über das vordere Bein.', 'Halte kurz inne, gehe zurück in die Ausgangsposition und wiederhole auf der anderen Seite. Wechsle weiter ab.']::text[]),
  ('Crucifix', 'de', array['Beim Crucifix hältst du Gewichte auf Zeit unbewegt seitlich von dir weg. Du kannst die Disziplin mit Kurzhanteln üben, am besten übst du aber mit einem der Geräte, die dabei wirklich verwendet werden, etwa Äxten und Hämmern, denn es fühlt sich anders an.', 'Beginne im Stand und hebe die Arme mit den Geräten in den Händen seitlich an. Die Arme sind parallel zum Boden. Im Wettkampf zeigen dir Kampfrichter oder Sensoren an, wann du unter die Waagerechte sinkst. Halte so lange, wie du kannst. In der Regel sollten die Gewichte so schwer sein, dass du nach 30-60 Sekunden nicht mehr halten kannst.']::text[]),
  ('Crunch_-_Hands_Overhead', 'de', array['Lege dich mit flachem Rücken auf den Boden und beuge die Knie so, dass Beinbeuger und Waden einen Winkel von etwa 60 Grad bilden.', 'Stelle die Füße flach auf den Boden und strecke die Arme über den Kopf, die Handflächen gekreuzt. Das ist deine Ausgangsposition.', 'Rolle den Oberkörper nach vorn auf, bis die Schulterblätter gerade vom Boden abheben. Halte die Arme die ganze Zeit in einer Linie mit Kopf, Nacken und Schultern. Bewege sie aus dieser Linie nicht nach vorn. Atme in diesem Teil der Bewegung aus und halte die Kontraktion eine Sekunde.', 'Atme ein und senke dich langsam in die Ausgangsposition.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Crunch_-_Legs_On_Exercise_Ball', 'de', array['Lege dich flach auf den Rücken, lege die Füße auf einen Gymnastikball und beuge die Knie auf 90 Grad.', 'Setze die Füße drei bis vier inches auseinander und drehe die Zehen nach innen, bis sie sich berühren.', 'Lege die Hände leicht seitlich an den Kopf und halte die Ellbogen innen. Tipp: Verschränke die Finger nicht hinter dem Kopf.', 'Drücke den unteren Rücken in den Boden, um den Bauch besser zu isolieren. Das ist deine Ausgangsposition.', 'Beginne, die Schultern vom Boden abzurollen, und drücke den unteren Rücken weiter so fest wie möglich nach unten. Die Schultern sollen sich nur etwa vier inches vom Boden heben, der untere Rücken bleibt am Boden. Atme in diesem Teil der Bewegung aus. Spanne den Bauch am höchsten Punkt der Kontraktion fest an und halte eine Sekunde. Tipp: Konzentriere dich auf eine langsame, kontrollierte Bewegung. Hole zu keinem Zeitpunkt Schwung.', 'Atme ein und senke dich langsam in die Ausgangsposition.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Crunches', 'de', array['Lege dich flach auf den Rücken, die Füße entweder flach auf dem Boden oder auf einer Bank abgelegt, mit auf 90 Grad gebeugten Knien. Liegen die Füße auf einer Bank, setze sie drei bis vier inches auseinander und drehe die Zehen nach innen, bis sie sich berühren.', 'Lege jetzt die Hände leicht seitlich an den Kopf und halte die Ellbogen innen. Tipp: Verschränke die Finger nicht hinter dem Kopf.', 'Drücke den unteren Rücken in den Boden, um den Bauch besser zu isolieren, und beginne, die Schultern vom Boden abzurollen.', 'Drücke den unteren Rücken weiter so fest wie möglich nach unten, während du den Bauch anspannst und ausatmest. Die Schultern sollen sich nur etwa vier inches vom Boden heben, der untere Rücken bleibt am Boden. Spanne den Bauch oben fest an und halte die Kontraktion eine Sekunde. Tipp: Konzentriere dich auf eine langsame, kontrollierte Bewegung - mit Schwung betrügst du dich nur selbst.', 'Atme nach der einen Sekunde Halten ein und senke dich wieder langsam in die Ausgangsposition.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Cuban_Press', 'de', array['Stehe und halte in jeder Hand eine Kurzhantel im Obergriff. Hebe die Oberarme, bis sie parallel zum Boden sind, und lass die Unterarme in der "Vogelscheuchen"-Haltung nach unten hängen. Das ist deine Ausgangsposition.', 'Drehe zu Beginn der Bewegung die Schultern nach außen, sodass sich der Arm um 180 Grad dreht. Die Oberarme bleiben an ihrem Platz; drehe, bis die Handgelenke genau über den Ellbogen stehen und die Unterarme senkrecht zum Boden sind.', 'Drücke jetzt die Kurzhanteln nach oben: Strecke die Ellbogen, bis die Arme über dem Kopf gestreckt sind.', 'Atme ein und gehe zurück in die Ausgangsposition, indem du die Schritte umgekehrt ausführst.', 'Wiederhole die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dancers_Stretch', 'de', array['Setze dich aufrecht auf den Boden.', 'Schlage das rechte Bein mit gebeugtem Knie über das linke. Das linke Bein bleibt gestreckt am Boden liegen.', 'Lege den linken Arm an das rechte Bein und die rechte Hand auf den Boden.', 'Drehe den Oberkörper nach rechts und halte 10-20 Sekunden. Wechsle die Seite.']::text[]),
  ('Dead_Bug', 'de', array['Lege dich auf den Rücken und strecke die Hände nach oben zur Decke.', 'Bringe Füße, Knie und Hüfte auf 90 Grad.', 'Atme kräftig aus, um den Brustkorb zu senken und den Rücken flach auf den Boden zu drücken; kippe das Becken nach oben und spanne das Gesäß an. Halte diese Position während der ganzen Bewegung. Das ist deine Ausgangsposition.', 'Beginne die Übung, indem du ein Bein ausstreckst: Strecke Knie und Hüfte, bis das Bein knapp über dem Boden ist.', 'Halte Lendenwirbelsäule und Becken bei der Bewegung in ihrer Position, denn dein Rücken wird ins Hohlkreuz gehen wollen.', 'Bleibe angespannt und bringe das arbeitende Bein zurück in die Ausgangsposition.', 'Wiederhole auf der anderen Seite und wechsle ab, bis der Satz beendet ist.']::text[]),
  ('Deadlift_with_Bands', 'de', array['Für das Kreuzheben mit kurzen Bändern legst du sie vor dem Start einfach über die Stange und stellst dich zum Aufbau hinein. Lange Bänder müssen an etwas Stabilem verankert werden, etwa an schweren Kurzhanteln oder einem Rack.', 'Stehen Füße und Griff, atme tief ein, senke dann die Hüfte und beuge die Knie, bis die Schienbeine die Stange berühren. Blicke nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drücke dich über die Fersen ab, um das Gewicht nach oben zu bewegen. Hat die Stange die Knie passiert, ziehe sie kräftig nach hinten: Ziehe die Schulterblätter zusammen, während du die Hüfte nach vorn zur Stange schiebst.', 'Senke die Stange ab, indem du die Hüfte beugst und sie zum Boden führst.']::text[]),
  ('Deadlift_with_Chains', 'de', array['Befestige die Ketten an den Hülsen der Stange oder lege sie einfach mit der Mitte über die Stange, damit das Gewicht beim Heben stärker zunimmt.', 'Tritt so an die Stange, dass sie mittig über deinen Füßen liegt. Die Füße stehen etwa hüftbreit. Beuge dich aus der Hüfte und greife die Stange schulterbreit; lass die Schulterblätter dabei nach vorn gleiten. Üblich ist der Obergriff, bei schwereren Sätzen der Kreuzgriff mit einer Hand oben und einer unten. Stehen Füße und Griff, atme tief ein, senke dann die Hüfte und beuge die Knie, bis die Schienbeine die Stange berühren.', 'Blicke nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drücke dich über die Fersen ab, um das Gewicht nach oben zu bewegen. Hat die Stange die Knie passiert, ziehe sie kräftig nach hinten: Ziehe die Schulterblätter zusammen, während du die Hüfte nach vorn zur Stange schiebst.', 'Senke die Stange ab, indem du die Hüfte beugst und sie zum Boden führst.']::text[]),
  ('Decline_Barbell_Bench_Press', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich langsam auf die Bank zurück.', 'Greife die Stange mittelweit, also so, dass Unterarme und Oberarme in der Mitte der Bewegung einen 90-Grad-Winkel bilden. Hebe sie aus der Ablage und halte sie mit gestreckten, verriegelten Armen gerade über dir. Die Arme stehen senkrecht zum Boden. Das ist deine Ausgangsposition. Tipp: Um die Rotatorenmanschette zu schonen, lass dir die Langhantel am besten von einem Trainingspartner aus der Ablage reichen.', 'Atme ein und senke die Stange langsam, bis du sie an der unteren Brust spürst.', 'Halte eine Sekunde inne, atme dann aus und drücke die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Strecke die Arme durch, spanne die Brust oben eine Sekunde lang an und senke die Stange dann wieder langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mache die vorgegebene Anzahl an Wiederholungen.', 'Lege die Stange zum Schluss wieder in die Ablage.']::text[]),
  ('Decline_Close-Grip_Bench_To_Skull_Crusher', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich langsam auf die Bank zurück.', 'Greife die Stange eng, also etwas schmaler als schulterbreit. Hebe sie aus der Ablage und halte sie mit durchgestreckten Armen und eng geführten Ellbogen gerade über dir. Die Arme stehen senkrecht zum Boden. Das ist deine Ausgangsposition. Tipp: Um die Rotatorenmanschette zu schonen, lass dir die Langhantel am besten von einem Trainingspartner aus der Ablage reichen.', 'Atme ein und senke die Stange zur unteren Brust. Die Ellbogen bleiben dabei eng am Körper.', 'Atme aus und drücke die Stange mit der Kraft des Trizeps wieder nach oben in die Ausgangsposition.', 'Halte die Oberarme ruhig und atme ein, während du die Stange langsam absenkst: Führe die Unterarme in einem Halbkreis zu dir, bis die Stange leicht deine Stirn berührt. Atme in diesem Teil der Bewegung ein.', 'Spanne den Trizeps an und atme aus, um die Stange wieder in die Ausgangsposition zu heben.', 'Wiederhole die Schritte 3-6, bis du die empfohlene Anzahl an Wiederholungen erreicht hast.']::text[]),
  ('Decline_Crunch', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich hin.', 'Lege die Hände locker seitlich an den Kopf, die Ellbogen zeigen nach innen. Tipp: Verschränke die Finger nicht hinter dem Kopf.', 'Drücke den unteren Rücken in die Bank, damit der Bauch isoliert arbeitet, und beginne, die Schultern von der Bank abzurollen.', 'Drücke den unteren Rücken weiter so fest wie möglich nach unten, spanne dabei den Bauch an und atme aus. Die Schultern heben sich nur etwa vier Inch von der Bank, der untere Rücken bleibt liegen. Spanne den Bauch am höchsten Punkt kräftig an und halte die Spannung eine Sekunde. Tipp: Bewege dich langsam und kontrolliert. Mit Schwung betrügst du dich nur selbst.', 'Senke dich nach dieser einen Sekunde langsam wieder in die Ausgangsposition und atme dabei ein.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Decline_Dumbbell_Bench_Press', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich hin, in jeder Hand eine Kurzhantel auf den Oberschenkeln. Die Handflächen zeigen zueinander.', 'Sobald du liegst, bringe die Kurzhanteln schulterbreit vor dich.', 'Drehe dort die Handgelenke nach vorn, bis die Handflächen von dir weg zeigen. Das ist deine Ausgangsposition.', 'Atme aus und senke die Gewichte langsam seitlich ab. Behalte die Kurzhanteln jederzeit voll unter Kontrolle. Tipp: Die Unterarme bleiben während der ganzen Bewegung senkrecht zum Boden.', 'Atme aus und drücke die Kurzhanteln mit der Brustmuskulatur nach oben. Strecke die Arme oben durch, spanne die Brust an, halte eine Sekunde und senke dann langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mache so viele Wiederholungen, wie dein Trainingsplan vorgibt.']::text[]),
  ('Decline_Dumbbell_Flyes', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich hin, in jeder Hand eine Kurzhantel auf den Oberschenkeln. Die Handflächen zeigen zueinander.', 'Sobald du liegst, bringe die Kurzhanteln schulterbreit vor dich. Die Handflächen zeigen zueinander, die Arme sind ganz gestreckt und stehen senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen leicht, um die Bizepssehne zu entlasten, und öffne die Arme in einem weiten Bogen zu beiden Seiten, bis du eine Dehnung in der Brust spürst. Atme in diesem Teil der Bewegung ein. Tipp: Die Arme selbst bleiben die ganze Zeit unverändert, bewegt wird nur im Schultergelenk.', 'Spanne die Brustmuskulatur an und atme aus, während du die Arme zurück in die Ausgangsposition führst. Tipp: Nimm denselben Bogen wie beim Absenken.', 'Halte die angespannte Position eine Sekunde und mache dann die vorgegebene Anzahl an Wiederholungen.']::text[]),
  ('Decline_Dumbbell_Triceps_Extension', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich hin, in jeder Hand eine Kurzhantel auf den Oberschenkeln. Die Handflächen zeigen zueinander.', 'Sobald du liegst, bringe die Kurzhanteln schulterbreit vor dich. Die Handflächen zeigen zueinander, die Arme sind ganz gestreckt und stehen senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig und die Ellbogen eng und atme ein, während du die Kurzhanteln langsam absenkst: Führe die Unterarme in einem Halbkreis zu dir, bis deine Daumen neben den Ohren sind. Atme in diesem Teil der Bewegung ein.', 'Spanne den Trizeps an und atme aus, um die Kurzhanteln wieder in die Ausgangsposition zu heben.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Decline_EZ_Bar_Triceps_Extension', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich langsam auf die Bank zurück.', 'Greife die SZ-Stange eng, also etwas schmaler als schulterbreit. Hebe sie aus der Ablage und halte sie mit durchgestreckten Armen und eng geführten Ellbogen gerade über dir. Die Arme stehen senkrecht zum Boden. Das ist deine Ausgangsposition. Tipp: Um die Rotatorenmanschette zu schonen, lass dir die Stange am besten von einem Trainingspartner aus der Ablage reichen.', 'Halte die Oberarme ruhig und atme ein, während du die Stange langsam absenkst: Führe die Unterarme in einem Halbkreis zu dir, bis die Stange leicht deine Stirn berührt. Atme in diesem Teil der Bewegung ein.', 'Spanne den Trizeps an und atme aus, um die Stange wieder in die Ausgangsposition zu heben.', 'Wiederhole das, bis du die empfohlene Anzahl an Wiederholungen erreicht hast.']::text[]),
  ('Decline_Oblique_Crunch', 'de', array['Fixiere deine Beine am Fußende der Negativbank und lege dich langsam auf die Bank zurück.', 'Hebe den Oberkörper von der Bank, bis er vom Boden aus gemessen etwa 35-45 Grad erreicht.', 'Lege eine Hand neben den Kopf und die andere auf den Oberschenkel. Das ist deine Ausgangsposition.', 'Hebe den Oberkörper von dort langsam an und drehe ihn dabei nach links. Atme aus und rolle dich weiter auf, bis dein rechter Ellbogen das linke Knie berührt. Halte diese angespannte Position eine Sekunde. Tipp: Halte den Bauch fest angespannt und die Bewegung langsam und kontrolliert.', 'Atme ein und senke den Körper langsam wieder in die Ausgangsposition.', 'Wenn du einen Satz mit der empfohlenen Anzahl an Wiederholungen auf der rechten Seite geschafft hast, wechsle zur linken. Tipp: Achte darauf, den Oberkörper wirklich zu drehen und die Anspannung oben zu spüren.']::text[]),
  ('Decline_Push-Up', 'de', array['Lege dich bäuchlings auf den Boden, setze die Hände etwa 36 Inch auseinander auf und stemme den Oberkörper auf gestreckten Armen hoch. Stelle die Füße auf eine Box oder Bank. Das ist deine Ausgangsposition.', 'Atme ein und senke dich ab, bis die Brust fast den Boden berührt.', 'Atme aus, drücke den Oberkörper wieder in die Ausgangsposition und spanne dabei die Brust an.', 'Halte oben in der angespannten Position kurz inne und senke dich dann erneut ab, für so viele Wiederholungen wie nötig.']::text[]),
  ('Decline_Reverse_Crunch', 'de', array['Lege dich rücklings auf eine Negativbank und halte dich mit beiden Händen am oberen Ende der Bank fest. Dein Körper darf aus dieser Position nicht nach unten rutschen.', 'Halte die Beine mit der Kraft des Bauchs parallel zum Boden, Knie und Füße bleiben zusammen. Tipp: Die Beine sind ganz gestreckt, nur die Knie bleiben leicht gebeugt. Das ist deine Ausgangsposition.', 'Atme aus und führe die Beine zum Oberkörper, während du das Becken nach hinten rollst und die Hüfte von der Bank hebst. Am Ende der Bewegung berühren die Knie die Brust.', 'Halte die Spannung eine Sekunde, atme ein und bringe die Beine zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Decline_Smith_Press', 'de', array['Stelle eine Negativbank unter die Multipresse. Hänge die Stange auf eine Höhe, die du im Liegen mit fast gestreckten Armen erreichst. Greife sie im Obergriff weiter als schulterbreit, entriegle sie und halte sie mit gestreckten Armen gerade über dir. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange kontrolliert ab, indem du die Ellbogen beugst, bis sie den Oberkörper leicht berührt.', 'Halte kurz inne, strecke dann die Ellbogen und bringe die Stange zurück in die Ausgangsposition. Atme dabei aus.', 'Mache die vorgegebene Anzahl an Wiederholungen.', 'Verriegle die Stange nach dem Satz wieder in der Halterung.']::text[]),
  ('Deficit_Deadlift', 'de', array['Lege dir eine Plattform oder Hantelscheiben zurecht, auf denen du stehen kannst, meist 1-3 Inch hoch. Stelle dich so an die Stange, dass sie über der Fußmitte liegt. Die Füße stehen etwa hüftbreit. Beuge dich aus der Hüfte vor und greife die Stange schulterbreit, die Schulterblätter dürfen dabei nach vorn gleiten. In der Regel nimmst du den Obergriff, bei schwereren Sätzen den Kreuzgriff.', 'Wenn Füße und Griff sitzen, atme tief ein, senke die Hüfte und beuge die Knie, bis die Schienbeine die Stange berühren. Schaue nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drücke dich über die Fersen ab, um das Gewicht nach oben zu bewegen. Sobald die Stange die Knie passiert hat, ziehe sie kräftig nach hinten: Ziehe die Schulterblätter zusammen und schiebe die Hüfte nach vorn zur Stange.', 'Zum Ablassen beugst du die Hüfte und führst die Stange zum Boden.']::text[]),
  ('Depth_Jump_Leap', 'de', array['Für diese Übung brauchst du zwei Boxen oder Bänke: eine 12 bis 16 Inch hoch, die andere 22 bis 26 Inch hoch.', 'Stelle dich auf eine der beiden Boxen, die Arme an den Seiten, die Füße zusammen und leicht über der Kante. Die andere Box steht etwa zwei oder drei Fuß vor dir und ist dir zugewandt.', 'Lass dich von der ersten Box fallen, lande auf beiden Füßen und springe im selben Moment beidbeinig wieder ab.', 'Stoße dich so kraftvoll wie möglich nach oben und vorn ab und nutze die Arme und die volle Körperstreckung, um auf die höhere Box zu springen. Fange den Aufprall auch hier mit den Beinen ab.']::text[]),
  ('Dip_Machine', 'de', array['Setze dich stabil in die Dip-Maschine, wähle das Gewicht und fasse die Griffe fest.', 'Halte die Ellbogen eng an den Seiten, damit der Trizeps die Hauptarbeit leistet. Die Ellbogen sind im 90-Grad-Winkel gebeugt.', 'Spanne den Trizeps an, atme aus und strecke die Arme nach unten. Tipp: Lass die Arme am tiefsten Punkt ganz leicht gebeugt, damit der Trizeps unter Spannung bleibt.', 'Atme ein und lass die Arme langsam wieder in die Ausgangsposition hochkommen.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Dips_-_Chest_Version', 'de', array['Für diese Übung brauchst du einen Barren. Für die Ausgangsposition stützt du dich mit gestreckten, verriegelten Armen über den Holmen ab.', 'Atme ein und senke dich langsam ab. Der Oberkörper ist dabei etwa 30 Grad nach vorn geneigt, die Ellbogen zeigen leicht nach außen. Gehe so tief, bis du eine leichte Dehnung in der Brust spürst.', 'Sobald du die Dehnung spürst, atme aus und drücke dich mit der Brust zurück in die Ausgangsposition. Tipp: Spanne die Brust am höchsten Punkt eine Sekunde lang an.', 'Mache die vorgegebene Anzahl an Wiederholungen.']::text[]),
  ('Dips_-_Triceps_Version', 'de', array['Für die Ausgangsposition stützt du dich mit fast ganz durchgestreckten Armen über den Holmen ab.', 'Atme ein und senke dich langsam ab. Der Oberkörper bleibt aufrecht, die Ellbogen bleiben nah am Körper. So arbeitet der Trizeps stärker. Gehe so tief, bis Oberarm und Unterarm einen 90-Grad-Winkel bilden.', 'Atme aus und drücke den Oberkörper mit dem Trizeps nach oben, zurück in die Ausgangsposition.', 'Mache die vorgegebene Anzahl an Wiederholungen.']::text[]),
  ('Donkey_Calf_Raises', 'de', array['Für diese Übung brauchst du eine Donkey-Wadenhebe-Maschine. Bringe zuerst den unteren Rücken und die Hüfte unter den gepolsterten Hebel. Das Polster soll im Bereich des Steißbeins aufliegen.', 'Lege beide Arme auf die seitlichen Griffe und stelle die Fußballen auf den Wadenblock, die Fersen ragen über die Kante. Richte die Zehen nach vorn, innen oder außen aus, je nachdem, welchen Bereich du trainieren willst, und strecke die Knie, ohne sie durchzudrücken. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Fersen: Strecke die Sprunggelenke so weit wie möglich und spanne die Waden an. Die Knie bleiben die ganze Zeit ruhig und werden zu keinem Zeitpunkt gebeugt. Halte die angespannte Position eine Sekunde, bevor du wieder absenkst.', 'Atme ein und gehe langsam in die Ausgangsposition zurück: Senke die Fersen und beuge die Sprunggelenke, bis die Waden gedehnt sind.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Double_Kettlebell_Alternating_Hang_Clean', 'de', array['Stelle zwei Kettlebells zwischen deine Füße. Für die Ausgangsposition schiebst du das Gesäß nach hinten und schaust geradeaus.', 'Bringe eine Kettlebell mit einem Clean an die Schulter und halte die andere weiter fest.', 'Senke in einer fließenden Bewegung die obere Kettlebell ab und treibe zugleich die untere nach oben.']::text[]),
  ('Double_Kettlebell_Jerk', 'de', array['Fasse in jeder Hand eine Kettlebell am Griff.', 'Bringe die Kettlebells mit einem Clean an die Schultern: Strecke Beine und Hüfte und ziehe die Gewichte zu den Schultern. Drehe dabei die Handgelenke, sodass die Handflächen nach vorn zeigen. Das ist deine Ausgangsposition.', 'Gehe leicht in die Knie, der Oberkörper bleibt aufrecht.', 'Kehre die Richtung sofort um und drücke dich über die Fersen ab, im Grunde ein Sprung, der Schwung erzeugt.', 'Strecke dabei die Arme und drücke die Kettlebells über den Kopf bis in die volle Streckung. Der Schwung deines Körpers bewegt die Gewichte.', 'Lande im Ausfallschritt, ein Fuß vorn, einer hinten.', 'Halte die Gewichte über dem Kopf, richte dich auf und stelle die Füße zusammen. Senke die Gewichte für die nächste Wiederholung ab.']::text[]),
  ('Double_Kettlebell_Push_Press', 'de', array['Bringe zwei Kettlebells mit einem Clean an die Schultern.', 'Gehe ein paar Inch in die Kniebeuge und kehre die Bewegung schnell um. Nutze den Schwung aus den Beinen, um die Kettlebells über den Kopf zu treiben.', 'Wenn die Arme durchgestreckt sind, senke die Kettlebells zurück an die Schultern und wiederhole.']::text[]),
  ('Double_Kettlebell_Snatch', 'de', array['Stelle zwei Kettlebells hinter deine Füße. Beuge die Knie und setze dich nach hinten, um sie aufzunehmen.', 'Schwinge die Kettlebells kraftvoll zwischen den Beinen durch und kehre die Richtung um.', 'Schiebe die Hüfte durch und bringe die Kettlebells in einer einzigen, ununterbrochenen Bewegung über dem Kopf in die Streckung.']::text[]),
  ('Double_Kettlebell_Windmill', 'de', array['Stelle eine Kettlebell vor deinen vorderen Fuß und bringe mit dem gegenüberliegenden Arm eine zweite per Clean and Press über den Kopf. Für den Clean an die Schulter streckst du Beine und Hüfte und ziehst die Kettlebell zu den Schultern. Drehe dabei das Handgelenk, sodass die Handfläche nach vorn zeigt.', 'Halte die Kettlebell über dem Kopf durchgehend gestreckt und schiebe das Gesäß zur Seite dieser Kettlebell hinaus. Drehe die Füße in einem Winkel von fünfundvierzig Grad vom Arm mit der gestreckten Kettlebell weg.', 'Beuge dich aus der Hüfte zur Seite, das Gesäß herausgeschoben, und neige dich langsam, bis du die Kettlebell vom Boden aufnehmen kannst. Behalte die Kettlebell über deinem Kopf die ganze Zeit im Blick.', 'Halte nach dem Aufnehmen der Kettlebell eine Sekunde inne und kehre die Bewegung dann um, zurück in die Ausgangsposition.']::text[]),
  ('Double_Leg_Butt_Kick', 'de', array['Stelle dich mit leicht gebeugten Knien hin.', 'Gehe schnell ein kurzes Stück in die Hocke, indem du Hüfte und Knie beugst, strecke dich sofort wieder und springe so hoch wie möglich.', 'Ziehe im Aufsteigen die Fersen an, indem du die Knie beugst, und versuche, damit das Gesäß zu berühren.', 'Lande mit nur teilweise gebeugten Knien und fange den Aufprall mit den Beinen ab.']::text[]),
  ('Downward_Facing_Balance', 'de', array['Lege dich bäuchlings auf einen Gymnastikball.', 'Bleibe mit dem Bauch auf dem Ball, wandere mit den Händen auf dem Boden nach vorn und hebe die Beine an. Ellbogen und Knie sind dabei gestreckt.']::text[]),
  ('Drag_Curl', 'de', array['Greife eine Langhantel im Untergriff, die Handflächen zeigen nach vorn, und bringe die Ellbogen nah an den Oberkörper und nach hinten. Das ist deine Ausgangsposition.', 'Atme aus und beuge die Arme, während die Ellbogen hinten bleiben: Du ''ziehst'' die Stange am Oberkörper entlang nach oben, sie bleibt immer in Kontakt mit ihm. Tipp: Die Ellbogen bleiben hier nicht seitlich fixiert, sondern wandern nach hinten. Ziehe außerdem die Schultern nicht hoch.', 'Gehe langsam in die Ausgangsposition zurück. Die Stange bleibt die ganze Zeit am Oberkörper.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Drop_Push', 'de', array['Stelle niedrige Boxen oder andere Plattformen 2-3 Fuß auseinander auf.', 'Gehe zwischen ihnen in die Liegestützposition und stütze dich mit den Händen auf den Boxen ab.', 'Drücke dich mit guter Körperhaltung hoch und lass dich von den Plattformen fallen. Setze die Hände dabei schulterbreit auf und federe die Landung ab, indem du den Aufprall mit den Armen auffängst.']::text[]),
  ('Dumbbell_Alternate_Bicep_Curl', 'de', array['Stehe mit aufrechtem Oberkörper, in jeder Hand eine Kurzhantel, die Arme hängen gestreckt. Die Ellbogen bleiben nah am Oberkörper, die Handflächen zeigen zu den Oberschenkeln.', 'Halte den Oberarm ruhig und beuge den rechten Arm, während du die Handfläche nach vorn drehst. Spanne den Bizeps von dort beim Ausatmen weiter an, bis er ganz angespannt ist und die Kurzhantel auf Schulterhöhe steht. Halte diese Position eine Sekunde und spanne den Bizeps fest an. Tipp: Nur der Unterarm bewegt sich.', 'Atme ein und senke die Kurzhantel langsam in die Ausgangsposition. Tipp: Drehe die Handfläche beim Absenken zurück, bis sie wie am Anfang zum Oberschenkel zeigt.', 'Wiederhole die Bewegung mit der linken Hand. Beides zusammen zählt als eine Wiederholung.', 'Wechsle so weiter ab, bis du die empfohlene Anzahl an Wiederholungen erreicht hast.']::text[]),
  ('Dumbbell_Bench_Press', 'de', array['Lege dich auf eine Flachbank, in jeder Hand eine Kurzhantel auf den Oberschenkeln. Die Handflächen zeigen zueinander.', 'Hilf mit den Oberschenkeln nach und bringe die Kurzhanteln nacheinander hoch, bis du sie schulterbreit vor dir hältst.', 'Drehe dort die Handgelenke nach vorn, bis die Handflächen von dir weg zeigen. Die Kurzhanteln befinden sich knapp neben der Brust, Oberarm und Unterarm bilden einen 90-Grad-Winkel. Behalte die Kurzhanteln jederzeit voll unter Kontrolle. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Kurzhanteln mit der Brust nach oben. Strecke die Arme oben durch, spanne die Brust an, halte eine Sekunde und senke dann langsam ab. Tipp: Im Idealfall dauert das Absenken etwa doppelt so lange wie das Hochdrücken.', 'Mache so viele Wiederholungen, wie dein Trainingsplan vorgibt.']::text[]),
  ('Dumbbell_Bench_Press_with_Neutral_Grip', 'de', array['Nimm in jede Hand eine Kurzhantel und lege dich auf eine Flachbank. Die Füße stehen flach auf dem Boden, die Schulterblätter sind nach hinten gezogen.', 'Halte die Kurzhanteln im Neutralgriff, die Handflächen zeigen zueinander, und beginne mit gestreckten Armen direkt über dir, senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Leite die Bewegung ein, indem du die Ellbogen beugst und die Oberarme zur Seite absenkst. Gehe so tief, bis die Kurzhanteln auf Höhe des Oberkörpers sind.', 'Halte kurz inne, strecke dann die Ellbogen und kehre in die Ausgangsposition zurück.']::text[]),
  ('Dumbbell_Bicep_Curl', 'de', array['Stehe aufrecht, in jeder Hand eine Kurzhantel, die Arme hängen gestreckt. Halte die Ellbogen nah am Oberkörper und drehe die Handflächen nach vorn. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Arme, indem du den Bizeps anspannst. Hebe die Gewichte weiter, bis der Bizeps ganz angespannt ist und die Kurzhanteln auf Schulterhöhe stehen. Halte dort kurz inne und spanne den Bizeps fest an.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Dumbbell_Clean', 'de', array['Stehe schulterbreit, in jeder Hand eine Kurzhantel.', 'Beuge Hüfte und Knie und schiebe die Hüfte nach hinten, bis die Kurzhanteln den Boden erreichen. Das ist deine Ausgangsposition.', 'Leite die Bewegung mit einem explosiven Sprung nach oben ein: Strecke Hüfte, Knie und Sprunggelenke, um die Gewichte zu beschleunigen. Halte die Kurzhanteln im Neutralgriff und lass die Arme gestreckt, bis dein Körper ganz gestreckt ist.', 'Beuge nach der vollen Streckung Hüfte und Knie erneut und fange die Gewichte in der Kniebeuge ab. Lass die Arme beugen und führe die Kurzhanteln an die Schultern.', 'Hast du die Gewichte in der Kniebeuge abgefangen, strecke Hüfte und Knie und stehe auf, die Kurzhanteln auf den Schultern.']::text[]),
  ('Dumbbell_Floor_Press', 'de', array['Lege dich mit Kurzhanteln in den Händen auf den Boden. Die Knie dürfen gebeugt sein. Beginne mit ganz gestreckten Armen, die Gewichte über dir.', 'Senke die Gewichte, bis die Oberarme den Boden berühren. Führst du die Ellbogen eng, betonst du Masse und Kraft des Trizeps; für mehr Brust winkelst du die Arme zur Seite ab.', 'Halte unten kurz inne, strecke dann die Ellbogen und führe die Gewichte oben zusammen.']::text[]),
  ('Dumbbell_Flyes', 'de', array['Lege dich auf eine Flachbank, in jeder Hand eine Kurzhantel auf den Oberschenkeln. Die Handflächen zeigen zueinander.', 'Hilf mit den Oberschenkeln nach und bringe die Kurzhanteln nacheinander hoch, bis du sie schulterbreit vor dir hältst, die Handflächen zueinander. Hebe sie an, als würdest du sie drücken, stoppe aber kurz vor der vollen Streckung und halte dort. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen leicht, um die Bizepssehne zu entlasten, und öffne die Arme in einem weiten Bogen zu beiden Seiten, bis du eine Dehnung in der Brust spürst. Atme in diesem Teil der Bewegung ein. Tipp: Die Arme selbst bleiben die ganze Zeit unverändert, bewegt wird nur im Schultergelenk.', 'Spanne die Brustmuskulatur an und atme aus, während du die Arme zurück in die Ausgangsposition führst. Tipp: Nimm denselben Bogen wie beim Absenken.', 'Halte die angespannte Position eine Sekunde und mache dann die vorgegebene Anzahl an Wiederholungen.']::text[]),
  ('Dumbbell_Incline_Row', 'de', array['Lehne dich nach vorn gegen eine Schrägbank, bereit für den Neutralgriff.', 'Nimm in jede Hand eine Kurzhantel im Neutralgriff und beginne mit gestreckten Armen. Das ist deine Ausgangsposition.', 'Ziehe die Schulterblätter zusammen und beuge die Ellbogen, um die Kurzhanteln seitlich an den Körper zu rudern.', 'Halte am höchsten Punkt kurz inne und gehe dann zurück in die Ausgangsposition.']::text[]),
  ('Dumbbell_Incline_Shoulder_Raise', 'de', array['Setze dich auf eine Schrägbank, in jeder Hand eine Kurzhantel auf den Oberschenkeln.', 'Hebe die Beine an, um die Gewichte mit Schwung an die Schultern zu bringen, und lehne dich zurück. Halte die Kurzhanteln mit gestreckten Armen über den Schultern. Die Arme stehen senkrecht zum Boden, die Handflächen zeigen nach vorn, die Fingerknöchel zur Decke. Das ist deine Ausgangsposition.', 'Halte die Arme gestreckt und verriegelt, atme aus und hebe die Kurzhanteln an, indem du die Schultern von der Bank löst.', 'Atme ein und bringe die Kurzhanteln zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Dumbbell_Lunges', 'de', array['Stehe mit aufrechtem Oberkörper und halte zwei Kurzhanteln seitlich neben dem Körper. Das ist deine Ausgangsposition.', 'Mache mit dem rechten Bein einen Schritt nach vorn, etwa 2 Fuß vor den Fuß, der hinten stehen bleibt, und senke den Oberkörper ab. Bleibe dabei aufrecht und im Gleichgewicht. Atme beim Absenken ein. Hinweis: Das Knie darf beim Absenken nicht über die Zehen hinaus nach vorn wandern, sonst wird das Kniegelenk unnötig belastet. Achte darauf, dass das vordere Schienbein senkrecht zum Boden bleibt.', 'Drücke dich vor allem über die Ferse hoch und kehre beim Ausatmen in die Ausgangsposition zurück.', 'Mache die empfohlene Anzahl an Wiederholungen und wechsle dann zum linken Bein.']::text[]),
  ('Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'de', array['Nimm eine Kurzhantel in eine Hand und lege dich mit der Brust auf eine verstellbare Bank, die leicht schräg gestellt ist, etwa 15 Grad vom Boden aus gemessen. Mit der anderen Hand kannst du dich für mehr Halt am Bein der Bank festhalten.', 'Bringe die Hand mit der Kurzhantel in eine neutrale Stellung, die Handfläche zeigt zum Oberkörper, und halte den Arm gestreckt, den Ellbogen leicht gebeugt. Das ist deine Ausgangsposition.', 'Atme aus und hebe den Arm mit der Kurzhantel zur Seite, bis der Ellbogen auf Schulterhöhe und der Arm ungefähr parallel zum Boden ist. Tipp: Der Arm bleibt während der ganzen Bewegung gestreckt und im rechten Winkel zum Oberkörper. Halte außerdem die Spannung oben eine Sekunde.', 'Atme ein und senke die Kurzhantel langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Dumbbell_Lying_Pronation', 'de', array['Lege dich bäuchlings auf eine Flachbank. Ein Arm hält eine Kurzhantel, die andere Hand liegt angewinkelt auf der Bank, sodass du den Kopf darauf ablegen kannst.', 'Beuge den Ellbogen des Arms mit der Kurzhantel, bis Oberarm und Unterarm einen 90-Grad-Winkel bilden.', 'Hebe den Oberarm an, bis der Unterarm senkrecht zum Boden und der Oberarm im rechten Winkel zum Oberkörper steht. Tipp: Der Oberarm soll parallel zum Boden sein und zugleich einen 90-Grad-Winkel mit dem Oberkörper bilden. Das ist deine Ausgangsposition.', 'Atme aus und drehe den Unterarm nach außen, sodass die Kurzhantel nach vorn angehoben wird. Der 90-Grad-Winkel zwischen Oberarm und Unterarm bleibt erhalten. Führe diese Außenrotation fort, bis der Unterarm parallel zum Boden ist, und halte die Spannung dort eine Sekunde.', 'Atme ein und gehe langsam in die Ausgangsposition zurück.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Dumbbell_Lying_Rear_Lateral_Raise', 'de', array['Stelle eine verstellbare Bank leicht schräg, etwa 15 Grad zum Boden, und lege dich mit der Brust darauf. In jeder Hand hältst du eine Kurzhantel.', 'Lass die Arme gestreckt hängen, die Ellbogen leicht gebeugt, und dreh die Hände in den Neutralgriff, Handflächen zum Körper. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Arme seitlich an, bis die Ellbogen auf Schulterhöhe sind und die Arme ungefähr parallel zum Boden stehen. Tipp: Halte die Arme die ganze Bewegung über gestreckt und im rechten Winkel zum Oberkörper. Halte die Spannung oben eine Sekunde lang.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und wechsle dann zum anderen Arm.']::text[]),
  ('Dumbbell_Lying_Supination', 'de', array['Lege dich seitlich auf eine Flachbank. Eine Hand hält die Kurzhantel, den anderen Arm legst du angewinkelt auf die Bank und stützt den Kopf darauf.', 'Beuge den Ellbogen des Arms mit der Kurzhantel, bis Oberarm und Unterarm einen Winkel von 90 Grad bilden.', 'Hebe den Oberarm an, bis der Unterarm parallel zum Boden und im rechten Winkel zum Oberkörper steht (Tipp: Der Unterarm zeigt dann gerade nach vorn). Der Oberarm liegt ruhig am Oberkörper, parallel zum Boden und immer in einer Linie mit dem Oberkörper. Das ist deine Ausgangsposition.', 'Atme aus und drehe den Unterarm nach außen, sodass die Kurzhantel in einem Halbkreis nach oben wandert. Der Winkel von 90 Grad zwischen Oberarm und Unterarm bleibt dabei erhalten. Dreh weiter, bis der Unterarm zur Decke zeigt, senkrecht zum Boden und zum Oberkörper. Halte die Spannung dort eine Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und wechsle dann den Arm.']::text[]),
  ('Dumbbell_One-Arm_Shoulder_Press', 'de', array['Nimm eine Kurzhantel. Setz dich entweder auf eine Schulterdrückbank oder eine Bank mit Rückenlehne und stelle die Kurzhantel aufrecht auf den Oberschenkel, oder stell dich aufrecht hin.', 'Setze die Kurzhantel auf Schulterhöhe um. Die freie Hand kannst du seitlich ausstrecken, an die Hüfte legen oder dich damit an etwas Festem halten.', 'Dreh das Handgelenk, bis die Handfläche nach vorn zeigt. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Kurzhantel nach oben, bis der Arm ganz gestreckt ist.', 'Halte eine Sekunde inne, atme dann ein und senke sie langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und wechsle dann den Arm.']::text[]),
  ('Dumbbell_One-Arm_Triceps_Extension', 'de', array['Greif dir eine Kurzhantel. Du kannst auf einer Schulterdrückbank oder einer Bank mit Rückenlehne sitzen, die Kurzhantel aufrecht auf dem Oberschenkel, oder aufrecht stehen.', 'Setze die Kurzhantel auf Schulterhöhe um und strecke den Arm dann über den Kopf, sodass der ganze Arm senkrecht zum Boden neben deinem Kopf steht und die Kurzhantel über dir ist. Die freie Hand kannst du seitlich ausstrecken, an die Hüfte legen, damit den Oberarm der Trainingsseite stützen oder dich an etwas Festem halten.', 'Dreh das Handgelenk so, dass die Handfläche nach vorn und der kleine Finger zur Decke zeigt. Das ist deine Ausgangsposition.', 'Halte den Oberarm ruhig und senke die Kurzhantel langsam hinter den Kopf, während du einatmest. Halte inne, sobald der Trizeps ganz gedehnt ist.', 'Atme aus und spanne den Trizeps an, um die Kurzhantel zurück in die Ausgangsposition zu bringen. Tipp: Nur der Unterarm darf sich bewegen. Der Oberarm bleibt die ganze Zeit ruhig neben dem Kopf.', 'Mach die empfohlene Zahl an Wiederholungen und wechsle dann den Arm.']::text[]),
  ('Dumbbell_One-Arm_Upright_Row', 'de', array['Nimm eine Kurzhantel und stell dich aufrecht hin, der Rücken gerade, der Arm vor dem Körper gestreckt und der Ellbogen leicht gebeugt. Das ist deine Ausgangsposition. Tipp: Die Kurzhantel liegt vorn am Oberschenkel, die Handfläche zeigt zum Oberschenkel.', 'Die andere Hand kannst du seitlich ausstrecken, an die Hüfte legen oder dich damit an etwas Festem halten. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Kurzhantel mit der seitlichen Schulter an. Führe sie dabei nah am Körper nach oben, bis sie fast auf Kinnhöhe ist. Tipp: Der Ellbogen führt die Bewegung und bleibt beim Heben immer höher als der Unterarm. Halte den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Kurzhantel langsam zurück in die Ausgangsposition und atme dabei ein.', 'Mach die empfohlene Zahl an Wiederholungen und wechsle dann den Arm.']::text[]),
  ('Dumbbell_Prone_Incline_Curl', 'de', array['Nimm in jede Hand eine Kurzhantel und lege dich bäuchlings auf eine Schrägbank, die Schultern nah am oberen Ende. Die Knie stützt du auf der Sitzfläche ab, oder du stellst die Beine links und rechts neben die Bank.', 'Lass die Arme gestreckt vor dir herabhängen, senkrecht zum Boden.', 'Halte die Ellbogen eng an den Seiten und dreh die Handflächen nach vorn. Das ist deine Ausgangsposition.', 'Spanne den Bizeps an und beuge die Arme, bis sie ganz angewinkelt sind. Atme dabei aus. Nur die Unterarme bewegen sich, die Oberarme bleiben die ganze Zeit ruhig.', 'Senke die Kurzhanteln, bis die Arme wieder ganz gestreckt sind.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dumbbell_Raise', 'de', array['Nimm in jede Hand eine Kurzhantel und stell dich aufrecht hin, der Rücken gerade, die Arme seitlich gestreckt und die Ellbogen leicht gebeugt. Das ist deine Ausgangsposition. Tipp: Die Kurzhanteln sind neben den Oberschenkeln, die Handflächen zeigen nach hinten.', 'Atme aus und hebe die Kurzhanteln mit den seitlichen Schultern an. Führe sie seitlich am Körper nach oben, bis sie fast auf Kinnhöhe sind. Tipp: Die Ellbogen führen die Bewegung und bleiben beim Heben immer höher als die Unterarme. Halte den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Kurzhanteln langsam zurück in die Ausgangsposition und atme dabei ein.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dumbbell_Rear_Lunge', 'de', array['Stell dich mit aufrechtem Oberkörper hin, in jeder Hand eine Kurzhantel neben dem Körper. Das ist deine Ausgangsposition.', 'Mach mit dem rechten Bein einen Schritt nach hinten, etwa zwei Fuß hinter den linken Fuß, und geh nach unten. Der Oberkörper bleibt aufrecht, du hältst das Gleichgewicht. Atme beim Absenken ein. Tipp: Das vordere Knie darf beim Absenken nicht über die Zehen hinaus nach vorn wandern, sonst wird das Kniegelenk unnötig belastet. Das vordere Schienbein bleibt senkrecht zum Boden. Bleib im ganzen Ausfallschritt aufrecht; bewegliche Hüftbeuger sind dafür wichtig. Ein langer Schritt betont den großen Gesäßmuskel, ein kurzer den Quadrizeps.', 'Atme aus, drück dich nach oben und komm zurück in die Ausgangsposition. Tipp: Drück dich über den Fußballen ab, um den Quadrizeps zu betonen. Für das Gesäß drückst du über die Ferse.', 'Wiederhole das Ganze nun mit dem anderen Bein.']::text[]),
  ('Dumbbell_Scaption', 'de', array['Diese Korrekturübung kräftigt die Muskeln, die das Schulterblatt stabilisieren. Halte in jeder Hand ein leichtes Gewicht seitlich am Körper, die Daumen zeigen nach oben.', 'Hebe die Arme nach vorn an, etwa 30 Grad von der Körpermitte nach außen versetzt. Die Arme bleiben während der Bewegung ganz gestreckt.', 'Hebe sie, bis sie parallel zum Boden sind, und senke sie dann zurück in die Ausgangsposition.']::text[]),
  ('Dumbbell_Seated_Box_Jump', 'de', array['Stelle eine Box ein paar Fuß neben eine Bank. Setz dich mit Blick zur Box auf die Bank und halte eine Kurzhantel mit beiden Händen vor der Brust. Das ist deine Ausgangsposition.', 'Stelle die Füße fest auf den Boden, lehne dich nach vorn und spring nach oben und vorn, indem du Hüfte und Knie streckst.', 'Lande mit beiden Füßen auf der Box und fang den Aufprall ab, indem du Hüfte und Knie nachgeben lässt.', 'Steig herunter und setz dich wieder in die Ausgangsposition.']::text[]),
  ('Dumbbell_Seated_One-Leg_Calf_Raise', 'de', array['Lege einen Block auf den Boden, ungefähr 12 Zoll von einer Flachbank entfernt.', 'Setz dich auf die Bank und lege eine Kurzhantel auf den linken Oberschenkel, etwa 3 Zoll oberhalb des Knies.', 'Stelle den linken Fußballen auf den Block. Das ist deine Ausgangsposition.', 'Atme aus und drück dich so hoch wie möglich auf die Zehen, indem du die Wade anspannst. Halte die Spannung eine Sekunde.', 'Geh langsam zurück in die Ausgangsposition und lass die Ferse so tief sinken, wie die Dehnung es erlaubt.', 'Mach die vorgegebene Zahl an Wiederholungen und wiederhole das Ganze dann mit dem rechten Bein.']::text[]),
  ('Dumbbell_Shoulder_Press', 'de', array['Setz dich mit einer Kurzhantel in jeder Hand auf eine Schulterdrückbank oder eine Bank mit Rückenlehne. Stelle die Kurzhanteln aufrecht auf die Oberschenkel.', 'Bring die Kurzhanteln nacheinander auf Schulterhöhe und gib ihnen dabei mit dem Oberschenkel Schwung.', 'Dreh die Handgelenke so, dass beide Handflächen nach vorn zeigen. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Kurzhanteln nach oben, bis sie sich über dem Kopf berühren.', 'Halte oben in der angespannten Position kurz inne, atme dann ein und senke die Gewichte langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dumbbell_Shrug', 'de', array['Stell dich aufrecht hin, die Arme seitlich gestreckt, in jeder Hand eine Kurzhantel, die Handflächen zum Körper.', 'Atme aus und zieh die Schultern so hoch wie möglich, um die Kurzhanteln anzuheben. Halte die Spannung oben eine Sekunde. Tipp: Die Arme bleiben die ganze Zeit gestreckt, und der Bizeps hilft beim Heben nicht mit. Nur die Schultern gehen auf und ab.', 'Lass die Kurzhanteln wieder in die Ausgangsstellung sinken.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dumbbell_Side_Bend', 'de', array['Stell dich aufrecht hin, die Kurzhantel in der linken Hand, Handfläche zum Körper, die rechte Hand an der Taille. Die Füße stehen schulterbreit. Das ist deine Ausgangsposition.', 'Mit geradem Rücken und erhobenem Kopf beugst du dich so weit wie möglich nach rechts, nur aus der Taille heraus. Atme beim Beugen ein. Halte eine Sekunde, atme dann aus und richte dich in die Ausgangsposition auf. Tipp: Der Rest des Körpers bleibt ruhig.', 'Mach die Bewegung nun noch einmal, diesmal zur linken Seite. Halte eine Sekunde und komm zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und nimm die Kurzhantel dann in die andere Hand.']::text[]),
  ('Dumbbell_Squat', 'de', array['Stell dich aufrecht hin, in jeder Hand eine Kurzhantel, die Handflächen zeigen zur Außenseite der Beine.', 'Stell die Füße schulterbreit in einen mittleren Stand, die Zehen zeigen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und halte den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Dieser mittlere Stand trainiert die Beine insgesamt; du kannst stattdessen auch jede der drei Standbreiten wählen.', 'Beuge die Knie und senke den Oberkörper langsam ab, aufrecht und mit erhobenem Kopf. Geh so tief, bis die Oberschenkel parallel zum Boden sind. Tipp: Bei sauberer Ausführung liegt die Vorderseite der Knie auf einer gedachten senkrechten Linie mit den Zehen. Gehen die Knie über diese Linie hinaus, also über die Zehen, wird das Knie unnötig belastet und die Übung ist falsch ausgeführt.', 'Atme aus und richte dich wieder auf, indem du dich vor allem mit den Fersen vom Boden abdrückst und die Beine streckst, bis du zurück in der Ausgangsposition bist.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dumbbell_Squat_To_A_Bench', 'de', array['Stell dich aufrecht vor eine Flachbank, sodass sie hinter dir steht. In jeder Hand hältst du eine Kurzhantel, die Handflächen zeigen zur Außenseite der Beine.', 'Nimm einen mittleren, schulterbreiten Stand ein und dreh die Zehen leicht nach außen. Der Kopf bleibt immer oben, weil dich der Blick nach unten das Gleichgewicht kostet, und der Rücken bleibt gerade. Das ist deine Ausgangsposition. Hinweis: Der mittlere Stand trainiert die Beine insgesamt; jede der drei Standbreiten ist stattdessen ebenfalls möglich.', 'Beuge die Knie und senke den Oberkörper langsam ab, aufrecht und mit erhobenem Kopf. Geh so tief, bis du die Bank hinter dir leicht berührst. Atme in diesem Teil der Bewegung ein. Tipp: Bei sauberer Ausführung liegt die Vorderseite der Knie auf einer gedachten senkrechten Linie mit den Zehen. Gehen die Knie über diese Linie hinaus, also über die Zehen, wird das Knie unnötig belastet und die Übung ist falsch ausgeführt.', 'Atme aus und komm nach oben, indem du dich vor allem mit den Fersen vom Boden abdrückst und die Beine streckst, bis du zurück in der Ausgangsposition bist.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Dumbbell_Step_Ups', 'de', array['Stell dich aufrecht hin, in jeder Hand eine Kurzhantel, die Handflächen zeigen zur Außenseite der Beine.', 'Stelle den rechten Fuß auf die erhöhte Plattform. Steig hinauf, indem du Hüfte und Knie des rechten Beins streckst. Drück dich dabei vor allem über die Ferse nach oben und stelle auch den linken Fuß auf die Plattform. Atme aus, während du die Kraft zum Aufsteigen aufbringst.', 'Atme ein und steig mit dem linken Bein herunter, indem du Hüfte und Knie des rechten Beins beugst. Stelle dann den rechten Fuß neben den linken und steh wieder so wie am Anfang.', 'Mach die empfohlene Zahl an Wiederholungen mit dem rechten Bein und danach mit dem linken.']::text[]),
  ('Dumbbell_Tricep_Extension_-Pronated_Grip', 'de', array['Lege dich auf eine Flachbank und halte zwei Kurzhanteln direkt über den Schultern. Die Arme sind ganz gestreckt und stehen im Winkel von 90 Grad zu Oberkörper und Boden.', 'Die Handflächen zeigen nach vorn, die Ellbogen bleiben eng am Körper. Das ist deine Ausgangsposition.', 'Atme ein und senke die Kurzhanteln langsam, bis sie nah an den Ohren sind. Die Oberarme bleiben ruhig und die Ellbogen eng.', 'Atme aus und drücke das Gewicht mit dem Trizeps zurück in die Ausgangsposition.']::text[]),
  ('Dynamic_Back_Stretch', 'de', array['Stell dich hin, die Füße schulterbreit auseinander. Das ist deine Ausgangsposition.', 'Schwinge die gestreckten Arme 5-10 Mal gerade nach vorn oben. Mach die Bewegung jedes Mal etwas größer, bis die Arme über dem Kopf sind.']::text[]),
  ('Dynamic_Chest_Stretch', 'de', array['Stell dich hin, die Arme gerade nach vorn gestreckt, die Hände aneinander. Das ist deine Ausgangsposition.', 'Halte die Arme gestreckt, führe sie schnell so weit wie möglich nach hinten und wieder zusammen, wie bei einem übertrieben weiten Klatschen. Wiederhole das 5-10 Mal und werde dabei schneller.']::text[]),
  ('EZ-Bar_Curl', 'de', array['Stell dich aufrecht hin und greife eine SZ-Stange an den weiten äußeren Griffstellen. Die Handflächen zeigen nach vorn und sind durch die Form der Stange leicht nach innen geneigt. Die Ellbogen bleiben nah am Oberkörper. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Arme, indem du den Bizeps anspannst. Achte darauf, nur die Unterarme zu bewegen.', 'Hebe das Gewicht weiter, bis der Bizeps ganz angespannt und die Stange auf Schulterhöhe ist. Halte die obere Position einen Moment und spanne den Bizeps fest an.', 'Atme ein und senke die Stange langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('EZ-Bar_Skullcrusher', 'de', array['Nimm die SZ-Stange im engen Griff auf und lege dich auf die Bank. Halte die Stange mit eng geführten Ellbogen, die Arme senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Die Oberarme bleiben ruhig. Senke die Stange, indem du die Ellbogen beugst, und atme dabei ein. Halte inne, sobald die Stange direkt über der Stirn ist.', 'Atme aus und strecke die Ellbogen, um die Stange zurück in die Ausgangsposition zu bringen.', 'Wiederhole die Bewegung.']::text[]),
  ('Elbow_Circles', 'de', array['Setz oder stell dich hin, die Füße leicht auseinander.', 'Lege die Hände auf die Schultern. Die Ellbogen sind auf Schulterhöhe und zeigen nach außen.', 'Beschreibe mit den Ellbogen langsam einen Kreis. Atme aus, wenn der Kreis beginnt, und atme ein, wenn du ihn schließt.']::text[]),
  ('Elbow_to_Knee', 'de', array['Lege dich auf den Boden, beuge das linke Knie und schlage das rechte Bein darüber. Verschränke die Hände hinter dem Kopf; die Schulterblätter liegen zu Beginn auf dem Boden. Das ist deine Ausgangsposition.', 'Runde die Wirbelsäule und dreh den Oberkörper, sodass der linke Ellbogen zum rechten Knie kommt.', 'Geh zurück in die Ausgangsposition, mach die gewünschte Zahl an Wiederholungen und wechsle dann die Seite.']::text[]),
  ('Elbows_Back', 'de', array['Stell dich gerade hin.', 'Lege beide Hände auf den unteren Rücken, die Finger zeigen nach unten, die Ellbogen nach außen.', 'Zieh die Ellbogen nun sanft nach hinten und versuche, sie zusammenzubringen.']::text[]),
  ('Elevated_Back_Lunge', 'de', array['Lege eine Stange auf Schulterhöhe in ein Rack und belade sie mit einem passenden Gewicht. Stelle eine niedrige Plattform hinter dich.', 'Nimm die Stange auf den oberen Rücken und halte den Rücken im Hohlkreuz und fest angespannt. Steig mit beiden Füßen auf die Plattform. Das ist deine Ausgangsposition.', 'Mach zuerst mit einem Bein einen Schritt nach hinten. Beuge Hüfte und Knie und geh nach unten, bis das Knie den Boden berührt.', 'Halte kurz inne und strecke dann Hüfte und Knie, um hochzukommen. Geh ganz zurück in die Ausgangsposition, bevor du das Bein wechselst.']::text[]),
  ('Elevated_Cable_Rows', 'de', array['Besorge dir eine Plattform von etwa 4-6 Zoll Höhe, zum Beispiel ein Aerobic-Stepbrett oder eine Plattform für Wadenheben.', 'Lege sie auf den Sitz der Rudermaschine am Kabelzug.', 'Setz dich darauf und stelle die Füße auf die vordere Plattform oder Querstange der Maschine. Die Knie sind leicht gebeugt und nicht durchgedrückt.', 'Beuge dich vor, ohne die natürliche Haltung des Rückens aufzugeben, und greife den V-Griff.', 'Zieh dich mit gestreckten Armen zurück, bis der Oberkörper im Winkel von 90 Grad zu den Beinen steht. Der Rücken ist leicht im Hohlkreuz, die Brust herausgestreckt. Mit dem Griff vor dir solltest du eine gute Dehnung im Latissimus spüren. Das ist die Ausgangsposition der Übung.', 'Halte den Oberkörper ruhig und zieh den Griff zu dir, die Arme nah am Körper, bis er den Bauch berührt. Atme beim Ziehen aus. Spanne an diesem Punkt die Rückenmuskeln fest an und halte eine Sekunde, dann atme ein und geh langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Elliptical_Trainer', 'de', array['Steig auf den Crosstrainer und wähle im Menü die gewünschte Option. Die meisten Geräte haben eine manuelle Einstellung oder Programme, die du starten kannst. Meist kannst du Alter und Gewicht eingeben, damit das Gerät den Kalorienverbrauch beim Training schätzt. Über die Steigung veränderst du die Intensität des Trainings.', 'Über die Griffe kannst du deine Herzfrequenz verfolgen. So bleibst du leichter bei einer passenden Intensität.']::text[]),
  ('Exercise_Ball_Crunch', 'de', array['Lege dich auf einen Gymnastikball, sodass die Wölbung des unteren Rückens an der Rundung des Balls anliegt. Die Knie sind gebeugt, die Füße stehen fest auf dem Boden. Der obere Teil des Oberkörpers hängt über den Ball hinaus. Halte die Arme neben dem Körper oder verschränke sie vor der Brust. Beide Haltungen schonen den Nacken, anders als die Hände hinter dem Kopf.', 'Senke den Oberkörper in die Dehnung und halte den Nacken die ganze Zeit ruhig. Das ist deine Ausgangsposition.', 'Die Hüfte bleibt ruhig. Spanne den Bauch an, beuge dich in der Taille und rolle Schultern und Rumpf nach oben, bis du eine deutliche Anspannung im Bauch spürst. Liegen die Arme seitlich, gleiten sie einfach an den Beinen entlang nach oben; sind sie verschränkt, bleiben sie auf der Brust. Der untere Rücken behält immer Kontakt zum Ball. Atme bei der Bewegung aus und halte die Spannung eine Sekunde.', 'Atme ein und geh zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Exercise_Ball_Pull-In', 'de', array['Lege einen Gymnastikball in deine Nähe und geh davor in die Liegestützposition, die Hände schulterbreit auf dem Boden.', 'Lege nun die unteren Schienbeine auf den Ball. Tipp: Die Beine sind jetzt ganz gestreckt, die Schienbeine liegen auf dem Ball, und der Oberkörper ist in einer Liegestützhaltung, getragen von den beiden gestreckten Armen. Das ist deine Ausgangsposition.', 'Halte den Rücken völlig gerade und den Oberkörper ruhig. Atme aus und zieh die Knie zur Brust, sodass der Ball unter deinen Fußgelenken nach vorn rollt. Spanne den Bauch an und halte die Position eine Sekunde.', 'Atme ein und strecke die Beine langsam, sodass der Ball in die Ausgangsposition zurückrollt.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Extended_Range_One-Arm_Kettlebell_Floor_Press', 'de', array['Lege dich auf den Boden und bring eine Kettlebell in Position, um sie mit einem Arm zu drücken. Halte sie am Griff. Das Bein auf der Seite des drückenden Arms ist gebeugt, das Knie kreuzt die Körpermitte.', 'Strecke den Ellbogen und führe den Arm zur Körpermitte, um die Kettlebell über den Körper zu drücken. Senke sie zurück in die Ausgangsposition.']::text[]),
  ('External_Rotation', 'de', array['Lege dich seitlich auf eine Flachbank, in einer Hand eine Kurzhantel. Den anderen Arm winkelst du auf der Bank an und legst den Kopf darauf.', 'Beuge den Ellbogen des Arms mit der Kurzhantel auf einen Winkel von 90 Grad zwischen Oberarm und Unterarm. Tipp: Der Arm bleibt parallel zum Oberkörper.', 'Beuge den Ellbogen bei ruhigem Oberarm, sodass der Unterarm parallel zum Boden und im rechten Winkel zum Oberkörper steht (Tipp: Der Unterarm zeigt dann gerade nach vorn). Der Oberarm liegt ruhig am Oberkörper, parallel zum Boden und stets in einer Linie mit dem Oberkörper. Das ist deine Ausgangsposition.', 'Atme aus und dreh den Unterarm nach außen. Die Kurzhantel hebt sich in einem Halbkreis, der Winkel von 90 Grad zwischen Oberarm und Unterarm bleibt bestehen. Dreh so lange weiter, bis der Unterarm zur Decke zeigt, senkrecht zum Boden und zum Oberkörper. Halte die Spannung an diesem Punkt eine Sekunde.', 'Atme ein und senke den Unterarm langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen und wechsle dann zum anderen Arm.']::text[]),
  ('External_Rotation_with_Band', 'de', array['Schlinge das Band fest um einen Pfosten, auf Höhe deines Ellbogens. Stell dich ein paar Fuß entfernt mit der linken Seite zum Band.', 'Greife das Ende des Bands mit der rechten Hand und drücke den Ellbogen fest an deine Seite. Es empfiehlt sich, ein Polster oder eine Faszienrolle mit dem Ellbogen einzuklemmen, damit er sicher an seinem Platz bleibt.', 'Der Oberarm bleibt in dieser Stellung, der Ellbogen ist auf 90 Grad gebeugt, und die Hand liegt quer vor dem Oberkörper. Das ist deine Ausgangsposition.', 'Dreh den Arm wie bei einem Rückhandschlag nach außen und lass den Ellbogen dabei an seinem Platz.', 'Geh so weit, wie du kannst, halte kurz inne und komm zurück in die Ausgangsposition.']::text[]),
  ('External_Rotation_with_Cable', 'de', array['Stelle den Kabelzug auf Ellbogenhöhe ein. Stell dich ein paar Fuß entfernt mit der linken Seite zum Kabelzug.', 'Greife den Griff mit der rechten Hand und drücke den Ellbogen fest an deine Seite. Es empfiehlt sich, ein Polster oder eine Faszienrolle mit dem Ellbogen einzuklemmen, damit er sicher an seinem Platz bleibt.', 'Der Oberarm bleibt in dieser Stellung, der Ellbogen ist auf 90 Grad gebeugt, und die Hand liegt quer vor dem Oberkörper. Das ist deine Ausgangsposition.', 'Dreh den Arm wie bei einem Rückhandschlag nach außen und lass den Ellbogen dabei an seinem Platz.']::text[]),
  ('Face_Pull', 'de', array['Stell dich vor einen hohen Kabelzug, an dem ein Seil oder zwei Griffe hängen. Zieh das Gewicht gerade zum Gesicht und führe die Hände dabei auseinander. Die Oberarme bleiben parallel zum Boden.']::text[]),
  ('Farmers_Walk', 'de', array['Für den Farmer''s Walk gibt es verschiedene Geräte. Hast du keine davon, gehen auch schwere Kurzhanteln oder kurze Stangen. Stell dich zu Beginn zwischen die Gewichte.', 'Greife die Griffe und hebe die Gewichte an, indem du dich über die Fersen hochdrückst. Der Rücken bleibt gerade, der Kopf oben.', 'Geh mit kurzen, schnellen Schritten und vergiss das Atmen nicht. Lege eine festgelegte Strecke, meist 50-100 Fuß, so schnell wie möglich zurück.']::text[]),
  ('Fast_Skipping', 'de', array['Stell dich locker hin, ein Bein leicht nach vorn gestellt. Das ist deine Ausgangsposition.', 'Mach Hopserläufe im Muster Schritt und Hüpfer: rechts-rechts-Schritt, dann links-links-Schritt, und so weiter im Wechsel.', 'Für schnelle Hopserläufe bleibst du nah am Boden, verkürzt die Zeit in der Luft und bewegst dich so schnell wie möglich.']::text[]),
  ('Finger_Curls', 'de', array['Halte eine Langhantel mit beiden Händen, die Handflächen nach oben, die Hände etwa schulterbreit auseinander.', 'Stelle die Füße flach auf den Boden, etwas weiter als schulterbreit. Das ist deine Ausgangsposition.', 'Öffne die Finger und senke die Stange so weit wie möglich. Lass sie die Hände hinabrollen und fang sie mit den letzten Fingergliedern auf.', 'Atme aus und schließe die Hände, um die Stange so hoch wie möglich einzurollen. Halte die Spannung oben.']::text[]),
  ('Flat_Bench_Cable_Flyes', 'de', array['Stelle eine Flachbank so zwischen zwei tiefe Kabelzüge, dass deine Brust im Liegen auf einer Linie mit den Rollen ist.', 'Lege dich flach auf die Bank und lass die Füße auf dem Boden.', 'Lass dir von jemandem die Griffe in beide Hände geben. Jeden Einzelgriff fasst du mit der Handfläche nach oben.', 'Strecke die Arme zur Seite aus, die Ellbogen leicht gebeugt. Tipp: Diese Beugung bleibt während der ganzen Bewegung gleich. Die Arme sind parallel zum Boden. Das ist deine Ausgangsposition.', 'Zieh die Kabel zusammen und führe die Arme in einem Halbkreis vor dir nach oben, bis sich beide Hände oben treffen. Spanne dabei die Brust an und atme aus. Halte die Spannung oben eine Sekunde. Tipp: Bei richtiger Ausführung stehen die Arme oben senkrecht zu Oberkörper und Boden, und die Hände berühren sich über der Brust.', 'Geh langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Flat_Bench_Leg_Pull-In', 'de', array['Lege dich auf eine Flachbank oder eine Trainingsmatte, sodass deine Beine über das Ende hinausragen.', 'Schiebe die Hände mit den Handflächen nach unten unter dein Gesäß oder halte dich seitlich an der Bank fest (auf der Matte liegen die Handflächen neben dir auf dem Boden). Strecke beide Beine gerade aus. Das ist deine Ausgangsposition.', 'Atme aus, beuge die Knie und ziehe die Oberschenkel zur Körpermitte. Führe die Bewegung fort, bis die Knie nah an der Brust sind, und halte die Spannung eine Sekunde.', 'Atme ein und strecke die Beine langsam zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Flat_Bench_Lying_Leg_Raise', 'de', array['Lege dich mit flachem Rücken auf eine Bank, die Beine gestreckt über das Ende hinaus.', 'Schiebe die Hände mit den Handflächen nach unten unter dein Gesäß oder halte dich seitlich an der Bank fest. Das ist deine Ausgangsposition.', 'Halte die Beine so gerade wie möglich, die Knie nur leicht gebeugt und in dieser Stellung fixiert, und hebe sie an, bis sie im 90-Grad-Winkel zum Boden stehen. Atme beim Anheben aus und halte die Spannung oben eine Sekunde.', 'Atme dann ein und senke die Beine langsam wieder in die Ausgangsposition.']::text[]),
  ('Flexor_Incline_Dumbbell_Curls', 'de', array['Greife jede Kurzhantel nah an dem Ende, das weiter von dir entfernt ist, damit mehr Gewicht auf der dir zugewandten Seite liegt. (Das wirkt bei allen Bizepsübungen mit Kurzhanteln gut.) Mache dann einen normalen Schrägbank-Curl, aber halte die Handgelenke so weit wie möglich nach hinten geneigt, um sie zu entlasten.', 'Nimm in jede Hand eine Kurzhantel und setze dich auf eine Schrägbank, die auf 45 Grad eingestellt ist.', 'Lass die Arme seitlich hängen, die Ellbogen nah am Körper. Drehe die Handflächen nach vorn, sodass die Daumen vom Körper weg zeigen. Tipp: Diese Handstellung behältst du die ganze Bewegung über bei; die Hände drehen sich beim Hochführen nicht. Das ist deine Ausgangsposition.', 'Atme aus und beuge beide Arme gleichzeitig, bis der Bizeps vollständig angespannt ist. Tipp: Nicht mit den Armen schwingen und keinen Schwung nutzen; die Bewegung bleibt immer kontrolliert. Halte oben eine Sekunde.', 'Atme ein und kehre langsam in die Ausgangsposition zurück.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Floor_Glute-Ham_Raise', 'de', array['Mache diese Übung mit einem Partner oder klemme die Füße unter etwas Stabiles.', 'Beginne im Kniestand, Oberschenkel und Oberkörper aufrecht. Hast du einen Partner, hält er deine Füße fest, damit du in Position bleibst. Das ist deine Ausgangsposition.', 'Lass dich nach vorn sinken, indem du die Knie streckst. Achte darauf, die Hüfte dabei NICHT zu beugen.', 'Fange dich mit den Händen vor dem Körper ab, wenn du den Boden erreichst. Die Bewegung ist sehr schwer, und vielleicht schaffst du sie nicht ohne Hilfe. Drücke dich mit den Armen leicht vom Boden ab, um leichter in die Ausgangsposition zurückzukommen.']::text[]),
  ('Floor_Press', 'de', array['Stelle die J-Haken auf eine Höhe, aus der du die Stange gut heraus- und wieder ablegen kannst. Lege dich auf den Boden, den Kopf nah am Ende eines Power Racks. Ziehe die Schulterblätter zusammen, halte sie so und hebe die Stange aus den Haken.', 'Senke die Stange zur unteren Brust oder zum oberen Bauch. Greife sie dabei fest und versuche, sie auseinanderzuziehen. Halte die Ellbogen während der ganzen Bewegung nah am Körper. Senke ab, bis die Oberarme den Boden berühren, und pausiere dort, damit das Gewicht weder aufschlägt noch federt.', 'Drücke die Stange so schnell du kannst wieder nach oben. Stange, Handgelenke und Ellbogen bleiben dabei in einer Linie.']::text[]),
  ('Floor_Press_with_Chains', 'de', array['Stelle die J-Haken auf eine Höhe, aus der du die Stange gut heraus- und wieder ablegen kannst. Hänge die Ketten direkt über die Enden der Stange und halte ihre Enden möglichst von den Scheiben fern.', 'Lege dich auf den Boden, den Kopf nah am Ende eines Power Racks. Ziehe die Schulterblätter zusammen, halte sie so und hebe die Stange aus den Haken.', 'Senke die Stange zur unteren Brust oder zum oberen Bauch. Greife sie dabei fest und versuche, sie auseinanderzuziehen. Halte die Ellbogen während der ganzen Bewegung nah am Körper. Senke ab, bis die Oberarme den Boden berühren, und pausiere dort, damit das Gewicht weder aufschlägt noch federt.', 'Drücke die Stange so schnell du kannst wieder nach oben. Stange, Handgelenke und Ellbogen bleiben dabei in einer Linie.']::text[]),
  ('Flutter_Kicks', 'de', array['Lege dich bäuchlings auf eine Flachbank, die Hüfte an der Bankkante. Die Beine sind gestreckt, die Zehen weit über dem Boden; die Arme liegen auf der Bank und greifen die vordere Kante.', 'Spanne Gesäß und Beinbeuger an und hebe die gestreckten Beine auf Hüfthöhe. Das ist deine Ausgangsposition.', 'Beginne, indem du das linke Bein höher hebst als das rechte.', 'Senke dann das linke Bein, während das rechte nach oben geht.', 'Wechsle so weiter ab, als würdest du im Wasser einen Beinschlag machen, bis jedes Bein die empfohlene Anzahl an Wiederholungen geschafft hat. Führe die Bewegung jederzeit kontrolliert aus. Tipp: Atme bei dieser Übung ganz normal.']::text[]),
  ('Foot-SMR', 'de', array['Mit dieser Übung dehnst du die Faszien der Fußmuskulatur. Setze dich hin und ziehe die Schuhe aus. Nimm eine Fußrolle oder etwas Ähnliches, zum Beispiel ein kurzes Stück PVC-Rohr, und stelle einen Fuß mit dem Fußgewölbe darauf. Das ist deine Ausgangsposition.', 'Drücke kräftig nach unten und rolle über das Fußgewölbe. Mache das 10-30 Sekunden lang und wechsle dann den Fuß.']::text[]),
  ('Forward_Drag_with_Press', 'de', array['Befestige eine Kette oder ein Seil mit zwei Griffen am Schlitten. Stelle dich mit dem Rücken zum Schlitten und nimm in jede Hand einen Griff.', 'Beginne mit einem Schritt nach vorn. Lehne dich nach vorn und strecke Beine und Hüfte, um voranzukommen. Halte bei jedem Schritt kurz an und strecke die Ellbogen, sodass du die Hände nach vorn drückst. Gehe dann weiter, bis du wieder in der Startposition bist, bereit für das nächste Drücken.']::text[]),
  ('Frankenstein_Squat', 'de', array['Mit dieser Übung lernst du, wo Stange und Körper beim Umsetzen und bei der Frontkniebeuge hingehören.', 'Lege die Langhantel vorn auf die Schultern, löse den Griff und strecke die Arme nach vorn aus. Schiebe die Schultern nach vorn, sodass sie eine Ablage bilden; die Stange soll den Hals berühren. Nur die Schulterblätter gehen nach vorn: Mache die Brustwirbelsäule nicht rund.', 'Beuge Knie und Hüfte und setze dich zwischen deine Beine. Oberkörper aufrecht, Arme oben, Schultern vorn: So bleibt die Stange an ihrem Platz. Gehe ganz nach unten, bis die Beinbeuger die Waden berühren.', 'Richte dich wieder auf, indem du über den vorderen Teil der Ferse drückst und Knie und Hüfte streckst.']::text[]),
  ('Freehand_Jump_Squat', 'de', array['Verschränke die Arme vor der Brust.', 'Stelle die Füße schulterbreit auf, Kopf oben und Rücken gerade.', 'Atme ein und gehe in die Hocke, bis die Oberschenkel parallel zum Boden sind oder tiefer. Der Rücken bleibt gerade, die Brust oben.', 'Drücke dich nun vor allem über die Fußballen ab und springe so hoch wie möglich gerade nach oben; die Oberschenkel arbeiten wie Federn. Atme beim Sprung aus.', 'Sobald du landest, gehe sofort wieder in die Hocke und springe erneut.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Frog_Hops', 'de', array['Stelle dich hin, nimm die Hände hinter den Kopf und gehe in die Hocke, Oberkörper aufrecht und Kopf oben. Das ist deine Ausgangsposition.', 'Springe mehrere Fuß weit nach vorn, ohne unnötig hoch zu springen. Wenn die Füße aufsetzen, federe die Landung mit den Beinen ab und springe gleich wieder. Mache das 5-10 Mal.']::text[]),
  ('Frog_Sit-Ups', 'de', array['Lege dich mit flachem Rücken auf den Boden oder eine Trainingsmatte, die Beine ausgestreckt.', 'Beuge die Knie und lass sie nach außen fallen, sodass die Außenseiten der Oberschenkel nah am Boden oder an der Matte liegen und die Fußsohlen sich berühren.', 'Drücke beide Sohlen aneinander und ziehe sie so nah wie möglich an dich heran. Die Außenseiten der Oberschenkel bleiben am Boden oder berühren ihn zumindest fast. Tipp: Deine Beine sollen jetzt eine Raute bilden.', 'Kreuze die Arme vor dir, jede Hand an der gegenüberliegenden Schulter. Das ist deine Ausgangsposition.', 'Atme aus, drücke den unteren Rücken flach in den Boden und rolle den Oberkörper nach oben ein. Tipp: Das entspricht dem ersten Viertel eines Sit-ups. Halte oben eine Sekunde.', 'Atme ein und senke dich langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Front_Barbell_Squat', 'de', array['Mache diese Übung zur Sicherheit in einem Kniebeugenständer. Lege die Stange zuerst auf der Höhe ab, die zu deiner Körpergröße passt. Stimmt die Höhe und ist die Stange beladen, führe die Arme von unten an die Stange, die Ellbogen hoch und die Oberarme etwas über der Waagerechten. Lege die Stange oben auf den Deltamuskeln ab, kreuze die Arme und greife die Stange, damit du sie voll unter Kontrolle hast.', 'Hebe die Stange aus der Ablage: Drücke zuerst mit den Beinen und richte gleichzeitig den Oberkörper auf.', 'Tritt vom Ständer zurück. Stelle dich in einen mittleren Stand, die Füße schulterbreit und die Zehen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der hier beschriebene mittlere Stand trainiert die Beine insgesamt; du kannst stattdessen jede der drei Standbreiten wählen.', 'Beuge die Knie und senke die Stange langsam ab, die Haltung gerade und der Kopf oben. Gehe so tief, bis der Winkel zwischen Oberschenkel und Wade etwas kleiner als 90 Grad ist; dann liegen die Oberschenkel unterhalb der Waagerechten. Atme beim Absenken ein. Tipp: Bei richtiger Ausführung liegt die Vorderseite der Knie auf einer gedachten senkrechten Linie mit den Zehen. Schieben sich die Knie über diese Linie hinaus, also vor die Zehen, belastest du das Kniegelenk unnötig, und die Übung ist falsch ausgeführt.', 'Atme aus und hebe die Stange: Drücke dich vor allem über den Mittelfuß vom Boden ab, strecke die Beine und komm zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Front_Barbell_Squat_To_A_Bench', 'de', array['Mache diese Übung zur Sicherheit in einem Kniebeugenständer. Stelle zuerst eine Flachbank hinter dich und lege die Stange auf der Höhe ab, die zu deiner Körpergröße passt. Stimmt die Höhe und ist die Stange beladen, führe die Arme von unten an die Stange, die Ellbogen hoch und die Oberarme etwas über der Waagerechten. Lege die Stange oben auf den Deltamuskeln ab, kreuze die Arme und greife die Stange, damit du sie voll unter Kontrolle hast.', 'Hebe die Stange aus der Ablage: Drücke zuerst mit den Beinen und richte gleichzeitig den Oberkörper auf.', 'Tritt vom Ständer zurück. Stelle dich in einen mittleren Stand, die Füße schulterbreit und die Zehen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der hier beschriebene mittlere Stand trainiert die Beine insgesamt; du kannst stattdessen jede der drei Standbreiten wählen.', 'Beuge die Knie und senke die Stange langsam ab, die Haltung gerade und der Kopf oben. Gehe so tief, bis dein Gesäß die Bank berührt. Atme beim Absenken ein. Tipp: Bei richtiger Ausführung liegt die Vorderseite der Knie auf einer gedachten senkrechten Linie mit den Zehen. Schieben sich die Knie über diese Linie hinaus, also vor die Zehen, belastest du das Kniegelenk unnötig, und die Übung ist falsch ausgeführt.', 'Atme aus und hebe die Stange: Drücke dich vor allem über die Fersen vom Boden ab, strecke die Beine und komm zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Front_Box_Jump', 'de', array['Stelle eine Box in passender Höhe 1-2 Fuß vor dich. Stehe mit schulterbreit aufgestellten Füßen. Das ist deine Ausgangsposition.', 'Gehe kurz leicht in die Knie, um Schwung für den Sprung zu holen, und schwinge die Arme nach hinten.', 'Schnelle aus dieser Position heraus: Strecke Hüfte, Knie und Sprunggelenke und springe so hoch du kannst. Schwinge die Arme nach vorn und oben.', 'Lande mit gebeugten Knien auf der Box und fange den Aufprall mit den Beinen ab. Du kannst von der Box zurück auf den Boden springen, besser steigst du aber ein Bein nach dem anderen herunter.']::text[]),
  ('Front_Cable_Raise', 'de', array['Stelle das Gewicht an einem Kabelzug mit unterer Rolle ein. Nimm den Einhandgriff, der an der unteren Rolle hängt, in die linke Hand.', 'Drehe der Rolle den Rücken zu. Lass den Arm gestreckt nach unten hängen, den Griff vor dem Oberschenkel und die Handfläche zum Oberschenkel gedreht. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig, ohne zu schwingen, und hebe den linken Arm nach vorn. Der Ellbogen ist leicht gebeugt, die Handfläche zeigt durchgehend nach unten. Hebe weiter, bis der Arm etwas über der Waagerechten ist. Atme beim Heben aus und halte oben eine Sekunde inne.', 'Atme ein und senke den Arm langsam in die Ausgangsposition.', 'Hast du mit diesem Arm die empfohlene Anzahl an Wiederholungen gemacht, wechsle die Seite und mache dasselbe mit dem rechten Arm.']::text[]),
  ('Front_Cone_Hops_or_hurdle_hops', 'de', array['Stelle Hütchen oder andere niedrige Hindernisse in einer Reihe auf, jeweils ein paar Fuß auseinander.', 'Stelle dich vor das erste Hütchen, die Füße schulterbreit. Das ist deine Ausgangsposition.', 'Springe beidbeinig über das erste Hütchen und schwinge beim Absprung beide Arme mit.', 'Federe die Landung mit gebeugten Knien ab und springe direkt daraus über das nächste Hütchen.', 'Mache weiter, bis du über alle Hütchen gesprungen bist.']::text[]),
  ('Front_Dumbbell_Raise', 'de', array['Nimm zwei Kurzhanteln und stelle dich mit geradem Oberkörper hin. Halte die Hanteln mit gestreckten Armen vor den Oberschenkeln, die Handflächen zu den Oberschenkeln gedreht. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig, ohne zu schwingen, und hebe die linke Kurzhantel nach vorn. Der Ellbogen ist leicht gebeugt, die Handfläche zeigt durchgehend nach unten. Hebe weiter, bis der Arm etwas über der Waagerechten ist. Atme beim Heben aus und halte oben eine Sekunde inne. Atme nach dieser Pause ein.', 'Senke diese Hantel langsam in die Ausgangsposition und hebe gleichzeitig die rechte Kurzhantel.', 'Wechsle so weiter ab, bis jeder Arm die empfohlene Anzahl an Wiederholungen gemacht hat.']::text[]),
  ('Front_Incline_Dumbbell_Raise', 'de', array['Nimm in jede Hand eine Kurzhantel und setze dich auf eine Schrägbank, die auf einen Winkel zwischen 30 und 60 Grad eingestellt ist. Tipp: Ändere den Winkel von Mal zu Mal, um den Muskel etwas anders zu treffen.', 'Strecke die Arme gerade nach vorn aus, die Handflächen nach unten, die Kurzhanteln etwa 1 Zoll über den Oberschenkeln. Das ist deine Ausgangsposition.', 'Hebe die Kurzhanteln mit durchgestreckten Ellbogen langsam gerade nach oben, bis sie knapp über Schulterhöhe sind. Spanne oben eine Sekunde an und atme beim Heben aus. Tipp: Der Kopf bleibt die ganze Zeit an der Bank angelehnt, die Füße bleiben auf dem Boden.', 'Atme ein und senke die Arme in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Front_Leg_Raises', 'de', array['Stelle dich neben einen Stuhl oder eine andere Stütze und halte dich mit einer Hand daran fest.', 'Schwinge ein Bein nach vorn und halte es dabei gestreckt. Lass es nach unten durchschwingen und weiter nach hinten, so weit es deine Beweglichkeit zulässt. Mache das 5-10 Mal und wechsle dann das Bein.']::text[]),
  ('Front_Plate_Raise', 'de', array['Stehe aufrecht und halte eine Hantelscheibe mit beiden Händen auf 3 und 9 Uhr. Die Handflächen zeigen zueinander. Die Arme sind gestreckt und fixiert, die Ellbogen leicht gebeugt, und die Scheibe hängt vor dir nahe der Taille, so tief es geht. Tipp: Die Arme bleiben während der ganzen Übung in dieser Stellung. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Scheibe langsam an, bis sie knapp über Schulterhöhe ist. Halte die Spannung eine Sekunde. Tipp: Schwinge das Gewicht nicht und beuge die Ellbogen nicht weiter. Auch der Oberkörper bleibt die ganze Bewegung über ruhig.', 'Atme ein und senke die Scheibe langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Front_Raise_And_Pullover', 'de', array['Lege dich auf eine Flachbank und halte eine Langhantel mit den Handflächen nach unten, die Hände etwa 15 Zoll auseinander.', 'Lege die Stange auf den Oberschenkeln ab. Strecke die Arme und fixiere sie mit leicht gebeugten Ellbogen. Das ist deine Ausgangsposition.', 'Atme ein und hebe das Gewicht mit gestreckten Armen in einem Halbkreis an. Führe die Bewegung fort, bis die Stange auf der anderen Seite über deinem Kopf ist. (Tipp: Die Stange legt etwa 180 Grad zurück.) Deine Arme sollen jetzt parallel zum Boden sein, die Handflächen zur Decke gedreht.', 'Atme aus und führe die Langhantel auf demselben Weg zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Front_Squat_Clean_Grip', 'de', array['Lege die Stange zuerst etwas unter Schulterhöhe in einem Ständer ab. Sie ruht oben auf den Deltamuskeln, drückt gegen die Schlüsselbeine und berührt leicht den Hals. Halte sie im Umsetzgriff: Nur die Finger berühren die Stange und helfen, sie an ihrem Platz zu halten.', 'Hebe die Stange aus der Ablage: Drücke zuerst mit den Beinen und richte gleichzeitig den Oberkörper auf. Tritt vom Ständer zurück und stelle dich in einen mittleren Stand, die Füße schulterbreit und die Zehen leicht nach außen. Kopf und Ellbogen bleiben immer oben. Das ist deine Ausgangsposition.', 'Beuge die Knie und setze dich zwischen deine Beine. Gehe so tief, bis die Beinbeuger auf den Waden liegen. Halte die Knie in einer Linie mit den Füßen: Drücke sie beim Beugen bewusst mit den Abduktoren nach außen.', 'Atme aus und hebe die Stange: Drücke dich vor allem über die Ferse oder den Mittelfuß vom Boden ab, strecke die Beine und komm zurück in die Ausgangsposition.']::text[]),
  ('Front_Squats_With_Two_Kettlebells', 'de', array['Setze zwei Kettlebells auf die Schultern um: Strecke Beine und Hüfte, ziehe die Kettlebells zu den Schultern und drehe dabei die Handgelenke.', 'Schaue die ganze Zeit geradeaus. Gehe so tief in die Hocke, wie du kannst, und pausiere unten. Drücke die Knie auf dem Weg nach unten nach außen. Setze dich zwischen deine Beine, der Oberkörper aufrecht, Kopf und Brust oben.', 'Drücke dich über die Fersen wieder nach oben und wiederhole.']::text[]),
  ('Front_Two-Dumbbell_Raise', 'de', array['Nimm zwei Kurzhanteln und stelle dich mit geradem Oberkörper hin. Halte die Hanteln mit gestreckten Armen vor den Oberschenkeln, die Handflächen zu den Oberschenkeln gedreht. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig, ohne zu schwingen, und hebe beide Kurzhanteln nach vorn. Die Ellbogen sind leicht gebeugt, die Handflächen zeigen durchgehend nach unten. Hebe weiter, bis die Arme etwas über der Waagerechten sind. Atme beim Heben aus und halte oben eine Sekunde inne.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Full_Range-Of-Motion_Lat_Pulldown', 'de', array['Stelle dich hin oder setze dich auf eine hohe Bank und fasse zwei Steigbügelgriffe, die an den oberen Rollen hängen. Greife jeweils mit der gegenüberliegenden Hand, sodass sich deine Arme über dir kreuzen und die Handflächen nach vorn zeigen.', 'Brust raus, leichtes Hohlkreuz im unteren Rücken: Ziehe die Griffe nach unten wie bei einem normalen Latzug. Der Bewegungsweg ist hier eher ein Bogen. Drehe die Hände beim Ziehen, sodass die Handflächen unten zueinander zeigen und nicht mehr nach vorn. Kehre langsam in die Ausgangsposition zurück und wiederhole.']::text[]),
  ('Gironda_Sternum_Chins', 'de', array['Fasse die Klimmzugstange schulterbreit im Untergriff.', 'Hänge mit vollständig gestreckten Armen, schiebe die Brust heraus und lehne dich zurück. Tipp: Du bleibst während der ganzen Bewegung zurückgelehnt. Das ist deine Ausgangsposition.', 'Ziehe dich zur Stange hoch. Die Wirbelsäule bleibt durchgehend im Hohlkreuz, der Kopf nach hinten geneigt und so weit wie möglich von der Stange weg. Atme beim Hochziehen aus. Tipp: Im oberen Teil der Bewegung stehen Hüfte und Beine etwa im 45-Grad-Winkel zum Boden.', 'Ziehe weiter, bis dein Schlüsselbein an der Stange vorbei ist und die untere Brust im Bereich des Brustbeins sie berührt. Halte eine Sekunde. Tipp: Am Ende dieses Abschnitts ist dein Kopf parallel zum Boden.', 'Atme ein und lass dich langsam in die Ausgangsposition ab.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Glute_Ham_Raise', 'de', array['Stelle zuerst das Gerät auf deinen Körper ein. Lege dich bäuchlings hinein, die Füße zwischen den Rollen und an der Fußplatte. Die Knie sollen knapp hinter dem Polster liegen.', 'Beginne am tiefsten Punkt der Bewegung. Gehe ins Hohlkreuz, halte es und starte, indem du die Knie beugst. Drücke dabei die Zehen in die Fußplatte. Der Oberkörper bleibt gerade; mache weiter, bis du aufrecht bist.', 'Lass dich kontrolliert in die Ausgangsposition ab.']::text[]),
  ('Glute_Kickback', 'de', array['Knie dich auf den Boden oder eine Trainingsmatte und beuge dich in der Taille nach vorn. Strecke die Arme vor dir aus, im rechten Winkel zum Oberkörper, sodass du in einer knienden Liegestützposition bist, die Hände schulterbreit. Der Blick geht nach vorn. Die Knie sind so gebeugt, dass Beinbeuger und Waden einen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Atme aus und hebe das rechte Bein, bis die Beinbeuger eine Linie mit dem Rücken bilden; das Knie bleibt im 90-Grad-Winkel. Spanne das Gesäß die ganze Bewegung über an und halte oben eine Sekunde. Tipp: Am Ende soll der Oberschenkel parallel zum Boden sein und die Wade senkrecht dazu stehen.', 'Atme ein, geh zurück in die Ausgangsstellung und wiederhole mit dem linken Bein.', 'Wechsle die Beine weiter ab, bis du alle empfohlenen Wiederholungen gemacht hast.']::text[]),
  ('Goblet_Squat', 'de', array['Stehe aufrecht und halte eine leichte Kettlebell an den Hörnern nah vor der Brust. Das ist deine Ausgangsposition.', 'Gehe zwischen deinen Beinen in die Hocke, bis die Beinbeuger auf den Waden liegen. Brust und Kopf bleiben oben, der Rücken gerade.', 'Pausiere unten und drücke die Knie mit den Ellbogen nach außen. Komm zurück in die Ausgangsposition und mache 10-20 Wiederholungen.']::text[]),
  ('Good_Morning', 'de', array['Beginne mit einer Stange, die auf Schulterhöhe im Ständer liegt. Nimm sie hinten quer über die Schultern, wie bei einer Powerlifting-Kniebeuge, nicht oben auf die Schultern. Halte den Rücken fest, die Schulterblätter zusammengezogen und die Knie leicht gebeugt. Tritt vom Ständer zurück.', 'Beuge dich zuerst in der Hüfte: Schiebe sie nach hinten und neige dich vor, bis der Oberkörper fast parallel zum Boden ist. Der Rücken bleibt im Hohlkreuz, die Halswirbelsäule richtig ausgerichtet.', 'Kehre die Bewegung um: Strecke die Hüfte mit der Kraft von Gesäß und Beinbeugern. Mache weiter, bis du wieder in der Ausgangsposition bist.']::text[]),
  ('Good_Morning_off_Pins', 'de', array['Beginne mit einer Stange, die etwa auf Bauchhöhe im Ständer liegt. Beuge dich unter die Stange und nimm sie hinten quer über die Schultern, wie bei einer Powerlifting-Kniebeuge, nicht oben auf die Schultern. Bei richtiger Höhe ist dein vorgebeugter Oberkörper fast parallel zum Boden. Halte den Rücken fest, die Schulterblätter zusammengezogen und die Knie leicht gebeugt. Der Rücken bleibt im Hohlkreuz, die Halswirbelsäule richtig ausgerichtet.', 'Starte die Bewegung, indem du die Hüfte mit Gesäß und Beinbeugern streckst, bis du mit dem Gewicht aufrecht stehst. Senke das Gewicht langsam wieder auf die Ablagestifte und komm so in die Ausgangsposition zurück.']::text[]),
  ('Gorilla_Chin_Crunch', 'de', array['Hänge dich im Untergriff an eine Klimmzugstange, die Handflächen zu dir, die Hände etwas weiter als schulterbreit.', 'Beuge die Knie auf 90 Grad: Die Waden sind parallel zum Boden, die Oberschenkel bleiben senkrecht dazu. Das ist deine Ausgangsposition.', 'Atme aus und ziehe dich hoch, während du zugleich die Knie mit einem Crunch bis auf Brusthöhe anziehst. Höre auf, sobald deine Nase auf Höhe der Stange ist. Tipp: In genau diesem Moment soll auch der Crunch abgeschlossen sein.', 'Beginne langsam einzuatmen und kehre in die Ausgangsposition zurück.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Groin_and_Back_Stretch', 'de', array['Setze dich auf den Boden, die Knie gebeugt, die Füße aneinander.', 'Verschränke die Finger hinter dem Kopf. Das ist deine Ausgangsposition.', 'Rolle den Oberkörper nach unten ein und bringe die Ellbogen an die Innenseiten der Oberschenkel. Halte kurz und komm dann zurück in die Ausgangsposition, Kopf oben und Rücken gerade. Mache 10-20 Wiederholungen.']::text[]),
  ('Groiners', 'de', array['Gehe auf dem Boden in die Liegestützposition. Das ist deine Ausgangsposition.', 'Springe mit beiden Beinen nach vorn, sodass die Füße neben den Händen landen. Halte den Kopf dabei oben.', 'Geh zurück in die Ausgangsposition und wiederhole die Bewegung sofort, insgesamt 10-20 Wiederholungen.']::text[]),
  ('Hack_Squat', 'de', array['Lehne dich mit dem Rücken an das Rückenpolster der Maschine und schiebe die Schultern unter die Schulterpolster.', 'Stelle die Füße etwa schulterbreit auf die Plattform, also in mittlerem Stand, die Zehen leicht nach außen gedreht. Tipp: Halte den Kopf die ganze Zeit oben und den Rücken immer am Polster.', 'Fasse die seitlichen Griffe und löse die Sicherungen (bei den meisten Maschinen drehst du dazu die Griffe von vorn in eine diagonale Stellung).', 'Strecke die Beine, ohne die Knie durchzudrücken. Das ist deine Ausgangsposition. Hinweis: Hier wird der oben beschriebene mittlere Stand verwendet, weil er die Beine insgesamt trainiert, du kannst aber jede der drei Fußstellungen wählen.', 'Beuge die Knie und lass den Schlitten langsam herunter, bleib dabei aufrecht, den Kopf oben und den Rücken durchgehend am Polster. Geh so tief, bis der Winkel zwischen Oberschenkeln und Waden etwas kleiner als 90 Grad ist, dann liegen die Oberschenkel unterhalb der Parallele zum Boden. Atme bei der Abwärtsbewegung ein. Tipp: Bei sauberer Ausführung liegen die Vorderseiten der Knie und die Zehen auf einer gedachten geraden Linie, die senkrecht zur Vorderseite steht. Schieben sich die Knie über diese Linie hinaus, also über die Zehen, werden sie unnötig belastet und die Übung war falsch ausgeführt.', 'Atme aus und drücke den Schlitten wieder hoch, vor allem über die Fersen, bis die Beine wieder gestreckt sind und du in der Ausgangsposition bist.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Hammer_Curls', 'de', array['Stell dich mit aufrechtem Oberkörper hin und halte in jeder Hand eine Kurzhantel, die Arme hängen gestreckt herab. Die Ellbogen bleiben nah am Körper.', 'Dreh die Handflächen zum Körper. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Arme nach vorn, indem du den Bizeps anspannst. Hebe die Gewichte, bis der Bizeps ganz angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Halte oben einen kurzen Moment und spanne den Bizeps fest an. Tipp: Achte darauf, dass die Ellbogen an ihrem Platz bleiben und sich nur die Unterarme bewegen.', 'Atme nach der kurzen Pause ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Hammer_Grip_Incline_DB_Bench_Press', 'de', array['Lehne dich auf einer Schrägbank zurück, in jeder Hand eine Kurzhantel, die auf deinen Oberschenkeln liegt. Die Handflächen zeigen zueinander.', 'Bring die Kurzhanteln mit Schwung aus den Oberschenkeln nach oben, einen Arm nach dem anderen, bis du sie schulterbreit hältst.', 'Halte sie dort im neutralen Griff, die Handflächen zeigen zueinander. Stelle die Ellbogen nach außen, sodass die Oberarme auf einer Linie mit den Schultern liegen (im rechten Winkel zum Oberkörper), und beuge die Ellbogen, bis Ober- und Unterarm einen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Atme ein und senke die Gewichte langsam zur Seite ab. Behalte die Kurzhanteln dabei jederzeit voll unter Kontrolle.', 'Atme aus und drücke die Kurzhanteln mit der Brustmuskulatur nach oben. Strecke die Arme oben ganz durch, halte eine Sekunde und senke dann langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach die vorgegebene Anzahl an Wiederholungen.', 'Wenn du fertig bist, lege die Kurzhanteln wieder auf die Oberschenkel und stelle sie dann auf den Boden. So legst du die Kurzhanteln am sichersten ab.']::text[]),
  ('Hamstring-SMR', 'de', array['Setz dich hin und strecke die Beine über eine Faszienrolle, sodass sie unter der Rückseite der Oberschenkel liegt. Stütze dich mit den Händen neben oder hinter dir ab, um dein Gewicht mitzutragen. Das ist deine Ausgangsposition.', 'Drücke dich mit den Händen hoch, bis die Hüfte vom Boden abhebt, und verlagere dein Gewicht auf der Rolle auf ein Bein. Lass den Beinbeuger dieses Beins locker.', 'Rolle von knapp unter der Hüfte bis knapp über die Kniekehle und bleib an verspannten Stellen 10-30 Sekunden. Wiederhole das mit dem anderen Bein.']::text[]),
  ('Hamstring_Stretch', 'de', array['Leg dich auf den Rücken und strecke ein Bein nach oben, sodass die Hüfte neunzig Grad gebeugt ist. Das andere Bein bleibt flach auf dem Boden.', 'Lege einen Gurt, ein Band oder ein Seil um den Fußballen des gehobenen Beins. Das ist deine Ausgangsposition.', 'Zieh am Gurt, bis du Spannung in Wade und Beinbeuger spürst. Halte die Dehnung 10-30 Sekunden und wiederhole sie mit dem anderen Bein.']::text[]),
  ('Handstand_Push-Ups', 'de', array['Stell dich mit dem Rücken zur Wand, beuge dich in der Hüfte vor und setze beide Hände schulterbreit auf den Boden.', 'Schwing dich mit gestreckten Armen an die Wand hoch. Du stehst jetzt kopfüber, Arme und Beine ganz gestreckt, der ganze Körper so gerade wie möglich. Tipp: Lass dir bei den ersten Versuchen von einer zweiten Person helfen. Schau außerdem mit dem Kopf zur Wand und nicht nach unten.', 'Atme ein und senke dich langsam ab, bis dein Kopf den Boden fast berührt. Tipp: Langsames Absenken ist äußerst wichtig, damit du dich nicht am Kopf verletzt.', 'Atme aus und drücke dich langsam wieder hoch, bis die Ellbogen fast durchgestreckt sind.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Hang_Clean', 'de', array['Fasse die Stange schulterbreit im doppelten Obergriff oder im Hakengriff und lass sie auf Höhe der Oberschenkelmitte hängen. Der Rücken ist gerade und leicht nach vorn geneigt.', 'Strecke Hüfte, Knie und Sprunggelenke explosiv und treibe das Gewicht so nach oben. Zieh dabei die Schultern zu den Ohren.', 'Richte dich sofort auf: Drücke dich über die Fersen hoch, der Oberkörper bleibt aufrecht, die Ellbogen oben. Mach weiter, bis du stehst.']::text[]),
  ('Hang_Clean_-_Below_the_Knees', 'de', array['Fasse die Stange schulterbreit im doppelten Obergriff oder im Hakengriff und lass sie knapp unter den Knien hängen. Der Rücken ist gerade und leicht nach vorn geneigt.', 'Strecke Hüfte, Knie und Sprunggelenke explosiv und treibe das Gewicht so nach oben, zieh dabei die Schultern zu den Ohren. Sobald du ganz gestreckt bist, gehst du in den dritten Zug über: Zieh die Schultern kräftig hoch und beuge die Arme, die Ellbogen gehen nach oben und außen.', 'Am höchsten Punkt der Streckung ziehst du dich kraftvoll nach unten und drehst die Ellbogen unter die Stange. Fange die Stange in der Frontkniebeuge-Position auf; wie tief, hängt davon ab, wie hoch die Stange am Ende des dritten Zugs ist. Die Stange liegt auf den nach vorn geschobenen Schultern und berührt leicht den Hals, die Hände bleiben locker. Geh weiter bis in die tiefe Hocke, das erleichtert das Aufstehen.', 'Richte dich sofort auf: Drücke dich über die Fersen hoch, der Oberkörper bleibt aufrecht, die Ellbogen oben. Mach weiter, bis du stehst.']::text[]),
  ('Hang_Snatch', 'de', array['Fasse die Stange weit, im Obergriff oder im Hakengriff. Die Füße stehen direkt unter der Hüfte, die Fußspitzen zeigen nach außen. Beuge die Knie leicht und neige den Oberkörper nach vorn. Die Wirbelsäule ist ganz gestreckt, der Kopf zeigt nach vorn. Die Stange ist an der Hüfte. Das ist deine Ausgangsposition.', 'Strecke Beine und Hüfte explosiv. Am höchsten Punkt der Streckung ziehst du die Schultern hoch und lässt die Ellbogen zur Seite beugen.', 'Während du die Füße in die Fangposition setzt, ziehst du dich kraftvoll unter die Stange und bringst sie über den Kopf. Fange die Stange so tief wie möglich auf, die Arme über dem Kopf ganz gestreckt.', 'Steh mit dem Gewicht über dem Kopf auf. Bring es danach kontrolliert zurück auf den Boden.']::text[]),
  ('Hang_Snatch_-_Below_Knees', 'de', array['Fasse die Stange weit, im Obergriff oder im Hakengriff. Die Füße stehen direkt unter der Hüfte, die Fußspitzen zeigen nach außen. Beuge die Knie leicht und neige den Oberkörper nach vorn. Die Wirbelsäule ist ganz gestreckt, der Kopf zeigt nach vorn. Die Stange ist knapp unter den Knien. Das ist deine Ausgangsposition.', 'Strecke Beine und Hüfte explosiv. Am höchsten Punkt der Streckung ziehst du die Schultern hoch und lässt die Ellbogen zur Seite beugen.', 'Während du die Füße in die Fangposition setzt, ziehst du dich kraftvoll unter die Stange und bringst sie über den Kopf. Fange die Stange so tief wie möglich auf, die Arme über dem Kopf ganz gestreckt.', 'Steh mit dem Gewicht über dem Kopf auf und bring es dann kontrolliert zurück auf den Boden.']::text[]),
  ('Hanging_Bar_Good_Morning', 'de', array['Hänge eine Stange mit Ketten oder Schlaufen in ein Rack, etwa auf Bauchhöhe.', 'Beuge dich unter die Stange und lege sie auf die Rückseite der Schultern, wie bei einer Power-Kniebeuge, nicht oben auf den Trapez. Bei richtiger Höhe ist dein Oberkörper vorgebeugt fast parallel zum Boden. Halte den Rücken fest, zieh die Schulterblätter zusammen und beuge die Knie leicht. Der Rücken bleibt im Hohlkreuz, die Halswirbelsäule in sauberer Linie.', 'Beginne die Bewegung, indem du die Hüfte mit Gesäß und Beinbeuger streckst, bis du mit dem Gewicht stehst.', 'Senke das Gewicht langsam in die Ausgangsposition, in der es wieder von den Ketten gehalten wird.']::text[]),
  ('Hanging_Leg_Raise', 'de', array['Hänge dich mit ganz gestreckten Armen an eine Klimmzugstange, im weiten oder mittleren Griff. Die Beine hängen gerade nach unten, das Becken ist leicht nach hinten gekippt. Das ist deine Ausgangsposition.', 'Hebe die Beine, bis sie mit dem Oberkörper einen 90-Grad-Winkel bilden. Atme dabei aus und halte die Spannung etwa eine Sekunde.', 'Atme ein und kehre langsam in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Hanging_Pike', 'de', array['Hänge dich mit geschlossenen Beinen und Füßen an eine Klimmzugstange, im Obergriff (Handflächen zeigen von dir weg) und etwas weiter als schulterbreit. Tipp: Mit Handgelenkbandagen kannst du dich leichter an der Stange halten.', 'Beuge die Knie auf 90 Grad und bring die Oberschenkel nach vorn, sodass die Waden senkrecht zum Boden stehen und die Oberschenkel parallel dazu bleiben. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Beine hoch, bis die Schienbeine die Stange über dir fast berühren. Tipp: Versuche, die Beine oben so weit wie möglich zu strecken.', 'Senke die Beine so langsam wie möglich in die Ausgangsposition. Tipp: Vermeide jederzeit Pendeln und Schwung.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Heaving_Snatch_Balance', 'de', array['Mit dieser Übung lernst du das Reißen. Leg dir ein leichtes Gewicht auf die Rückseite der Schultern. Die Füße stehen etwas weiter als hüftbreit, die Fußspitzen nach außen, so wie du auch bei der Kniebeuge stehst.', 'Geh leicht in die Knie und federe wieder hoch, um die Stange kurz zu entlasten. Drücke dich unter die Stange und bring sie über den Kopf, während du in die tiefe Kniebeuge gehst.', 'Steh wieder auf.']::text[]),
  ('Heavy_Bag_Thrust', 'de', array['Für diese Übung brauchst du einen schweren Boxsack. Stell dich aufrecht neben den Sack, in recht weiter Schrittstellung. Lege die Hand etwa auf Brusthöhe an den Sack. Das ist deine Ausgangsposition.', 'Dreh dich in der Taille und stoße den Sack so kräftig wie möglich nach vorn. Führe die Bewegung schnell aus und drücke den Sack vom Körper weg.', 'Fange den zurückschwingenden Sack ab, indem du die Schritte umkehrst.']::text[]),
  ('High_Cable_Curls', 'de', array['Stell dich zwischen zwei hohe Kabelzüge und nimm in jede Hand einen Griff. Halte die Oberarme parallel zum Boden, die Handflächen zeigen zu dir. Das ist deine Ausgangsposition.', 'Zieh die Griffe zu dir, bis sie neben den Ohren sind, spanne dabei den Bizeps an und atme aus. Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Halte die Spannung eine Sekunde und drücke den Bizeps fest zusammen.', 'Führe die Arme langsam in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Hip_Circles_prone', 'de', array['Geh in den Vierfüßlerstand. Hebe in guter Haltung ein gebeugtes Knie vom Boden ab. Das ist deine Ausgangsposition.', 'Lass das Knie gebeugt und drehe den Oberschenkelknochen in einem Bogen, als wolltest du mit dem Knie einen großen Kreis zeichnen.', 'Mach das langsam für einige Wiederholungen und wechsle dann die Seite.']::text[]),
  ('Hip_Extension_with_Bands', 'de', array['Befestige ein Ende des Bands unten an einem Pfosten und das andere an einem Fußgelenk.', 'Stell dich mit dem Gesicht zum Befestigungspunkt des Bands und halte dich am Pfosten fest, um stabil zu stehen.', 'Halte Kopf und Brust oben und führe das Bein mit dem Band so weit wie möglich nach hinten, das Knie bleibt gestreckt.', 'Bring das Bein in die Ausgangsposition zurück.']::text[]),
  ('Hip_Flexion_with_Band', 'de', array['Befestige ein Ende des Bands unten an einem Pfosten und das andere an einem Fußgelenk.', 'Stell dich mit dem Rücken zum Befestigungspunkt des Bands.', 'Halte Kopf und Brust oben, hebe das Knie auf 90 Grad und halte kurz.', 'Bring das Bein in die Ausgangsposition zurück.']::text[]),
  ('Hip_Lift_with_Band', 'de', array['Wähle ein passendes Band, befestige es auf beiden Seiten von dir und leg dich in die Mitte des Racks. Hat dein Rack keine Zapfen, kannst du das Band mit schweren Kurzhanteln oder ähnlichen Gegenständen fixieren; achte nur darauf, dass sie nicht verrutschen.', 'Rück dich so zurecht, dass das Band genau über deiner Hüfte verläuft. Beuge die Knie und stelle die Füße flach auf den Boden. Die Hände liegen auf dem Boden oder halten das Band an seinem Platz.', 'Lass die Schultern am Boden, drücke dich über die Fersen ab und hebe die Hüfte so hoch wie möglich gegen das Band.', 'Halte oben kurz und kehre in die Ausgangsposition zurück.']::text[]),
  ('Hug_A_Ball', 'de', array['Setz dich auf den Boden.', 'Nimm einen Gymnastikball zwischen die gegrätschten Beine und senke die Hüfte zum Boden.', 'Leg die Arme um den Ball, um deinen Körper zu stützen. Stelle die Beine so, dass die Füße flach auf dem Boden stehen und die Knie über den Fußgelenken sind. Halte den Ball gut fest, damit er nicht wegrollt und du nach hinten auf das Gesäß fällst.']::text[]),
  ('Hug_Knees_To_Chest', 'de', array['Leg dich auf den Rücken und zieh beide Knie zur Brust.', 'Fasse mit den Armen unter die Knie, nicht darüber (das würde die Kniegelenke zu stark belasten).', 'Zieh die Knie langsam Richtung Schultern. Das dehnt auch die Gesäßmuskulatur.']::text[]),
  ('Hurdle_Hops', 'de', array['Stelle eine Reihe Hürden oder andere kleine Hindernisse auf, jeweils ein paar Fuß auseinander.', 'Stell dich schulterbreit vor die erste Hürde. Das ist deine Ausgangsposition.', 'Spring beidbeinig über die erste Hürde und schwinge beim Absprung beide Arme mit.', 'Fange die Landung ab, indem du die Knie beugst, und spring aus dem ersten Sprung heraus gleich über die nächste Hürde. Mach weiter, bis du alle Hürden übersprungen hast.']::text[]),
  ('Hyperextensions_Back_Extensions', 'de', array['Leg dich bäuchlings auf eine Hyperextension-Bank und klemme die Fußgelenke fest unter die Fußpolster.', 'Stelle das obere Polster, wenn möglich, so ein, dass die oberen Oberschenkel flach auf dem breiten Polster liegen und du genug Platz hast, dich in der Hüfte ungehindert zu beugen.', 'Halte den Körper gerade und kreuze die Arme vor dir (die bevorzugte Variante) oder nimm sie hinter den Kopf. Das ist deine Ausgangsposition. Tipp: Für mehr Widerstand kannst du vor dir eine Hantelscheibe unter den gekreuzten Armen halten.', 'Beuge dich in der Hüfte langsam so weit wie möglich nach vorn, der Rücken bleibt gerade. Atme dabei ein. Geh weiter, bis du eine gute Dehnung im Beinbeuger spürst und nicht mehr weiterkommst, ohne den Rücken zu runden. Tipp: Mach bei dieser Übung nie einen runden Rücken. Manche kommen weiter herunter als andere; entscheidend ist, dass du so weit gehst, wie dein Körper es ohne Rundrücken zulässt.', 'Atme ein und hebe den Oberkörper langsam in die Anfangsposition. Tipp: Widerstehe der Versuchung, den Rücken über die gerade Linie hinaus zu überstrecken. Schwinge außerdem nie mit dem Oberkörper, um den Rücken vor Verletzungen zu schützen.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Hyperextensions_With_No_Hyperextension_Bench', 'de', array['Lass dir von jemandem die Beine festhalten und rutsche auf einer Flachbank nach vorn, bis deine Hüfte über das Bankende hinausragt. Tipp: Dein ganzer Oberkörper sollte zum Boden hängen. Die Position ist dieselbe wie auf einer Hyperextension-Bank, der Bewegungsumfang ist aber kleiner, weil die Flachbank niedriger ist.', 'Halte den Körper gerade und kreuze die Arme vor dir (die bevorzugte Variante) oder nimm sie hinter den Kopf. Das ist deine Ausgangsposition. Tipp: Für mehr Widerstand kannst du vor dir eine Hantelscheibe unter den gekreuzten Armen halten.', 'Beuge dich in der Hüfte langsam so weit wie möglich nach vorn, der Rücken bleibt gerade. Atme dabei ein. Geh weiter, bis du den Boden fast berührst oder eine gute Dehnung im Beinbeuger spürst, je nachdem, was zuerst eintritt. Tipp: Mach bei dieser Übung nie einen runden Rücken.', 'Atme aus und hebe den Oberkörper langsam in die Anfangsposition. Tipp: Widerstehe der Versuchung, den Rücken über die gerade Linie hinaus zu überstrecken. Schwinge außerdem nie mit dem Oberkörper, um den Rücken vor Verletzungen zu schützen.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('IT_Band_and_Glute_Stretch', 'de', array['Leg dich auf den Boden, lege einen Gürtel, ein Seil oder ein Band um einen Fuß und führe dieses Bein gestreckt über den Körper zur anderen Seite. Das ist deine Ausgangsposition.', 'Der Fuß bleibt vom Boden abgehoben. Zieh am Gürtel und nutze die Spannung, um die Zehen heranzuziehen. Halte 10-20 Sekunden und wiederhole auf der anderen Seite.']::text[]),
  ('Iliotibial_Tract-SMR', 'de', array['Leg dich auf die Seite, das untere Bein liegt zwischen Hüfte und Knie auf einer Faszienrolle. Das andere Bein kannst du vor dir überkreuzen.', 'Gib so viel Gewicht auf das untere Bein, wie du aushältst; es muss den Boden nicht berühren. Achte darauf, dass die Muskeln des gedehnten Beins locker sind.', 'Rolle das Bein von der Hüfte bis zum Knie über die Rolle und bleib an verspannten Stellen 10-30 Sekunden. Wiederhole das mit dem anderen Bein.']::text[]),
  ('Inchworm', 'de', array['Stell dich mit eng zusammenstehenden Füßen hin. Beuge dich mit gestreckten Beinen nach unten und setze die Hände direkt vor dir auf den Boden. Das ist deine Ausgangsposition.', 'Wandere mit den Händen langsam nach vorn, abwechselnd links und rechts. Beuge dich dabei nur in der Hüfte, die Beine bleiben gestreckt.', 'Mach weiter, bis dein Körper in der Liegestützposition parallel zum Boden ist.', 'Lass jetzt die Hände an ihrem Platz und geh mit den Füßen langsam in kurzen Schritten nach, immer nur ein paar Zoll.', 'Geh mit gestreckten Beinen weiter, bis die Füße bei den Händen sind.']::text[]),
  ('Incline_Barbell_Triceps_Extension', 'de', array['Fasse eine Langhantel im Obergriff (Handflächen nach unten), etwas enger als schulterbreit.', 'Lehne dich auf einer Schrägbank zurück, die auf einen Winkel zwischen 45 und 75 Grad eingestellt ist.', 'Bring die Stange mit gestreckten Armen über den Kopf, die Ellbogen eng. Die Arme sind über dem Kopf auf einer Linie mit dem Oberkörper. Das ist deine Ausgangsposition.', 'Senke die Stange in einem Halbkreis hinter den Kopf, bis die Unterarme den Bizeps berühren. Atme dabei ein. Tipp: Halte die Oberarme die ganze Zeit ruhig und nah am Kopf. Nur die Unterarme bewegen sich.', 'Atme aus und spanne den Trizeps an, um in die Ausgangsposition zurückzukehren. Halte die Spannung eine Sekunde.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Incline_Bench_Pull', 'de', array['Nimm in jede Hand eine Kurzhantel und leg dich bäuchlings auf eine Schrägbank, die auf etwa 30 Grad eingestellt ist.', 'Lass die Arme ganz gestreckt seitlich herabhängen, sie zeigen zum Boden.', 'Dreh die Handgelenke in den pronierten Griff (Handflächen nach unten).', 'Stelle jetzt die Ellbogen nach außen. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Kurzhanteln hoch wie bei einem umgekehrten Bankdrücken: Beuge die Ellbogen und hebe die Oberarme, die Unterarme hängen nach unten. Mach weiter, bis die Oberarme auf Höhe des Rückens sind. Tipp: Die Ellbogen gehen zur Seite, oben bilden Oberarme und Oberkörper ein "T". Halte die Spannung oben eine Sekunde.', 'Atme ein und senke langsam in die Ausgangsposition ab.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Incline_Cable_Chest_Press', 'de', array['Stelle ein passendes Gewicht ein, setz dich und fasse die Griffe. Die Oberarme stehen etwa 45 Grad zum Körper, Kopf und Brust sind oben, die Ellbogen etwa 90 Grad gebeugt. Das ist deine Ausgangsposition.', 'Strecke die Ellbogen und drücke die Griffe gerade vor dir zusammen. Halte die Schulterblätter während der Bewegung nach hinten gezogen.', 'Halte kurz in der vollen Streckung und kehre dann in die Ausgangsposition zurück, die Kabel bleiben dabei unter Spannung.']::text[]),
  ('Incline_Cable_Flye', 'de', array['Um in die Ausgangsposition zu kommen, stelle die Rollen auf Bodenhöhe ein (die tiefste Stufe des Kabelzugs, unterhalb deines Oberkörpers).', 'Stelle eine auf 45 Grad eingestellte Schrägbank zwischen die Rollen, wähle auf jeder Seite ein Gewicht und nimm in jede Hand einen Griff.', 'Leg dich mit beiden Griffen auf die Schrägbank und führe die Hände mit gestreckten Armen vor dem Gesicht zusammen. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen leicht, um die Bizepssehne zu schonen, und senke die Arme in weitem Bogen zu beiden Seiten, bis du eine Dehnung in der Brust spürst. Atme in diesem Teil der Bewegung ein. Tipp: Die Arme selbst bleiben die ganze Zeit unverändert; die Bewegung findet nur im Schultergelenk statt.', 'Atme aus, spanne die Brust an und führe die Arme in die Ausgangsposition zurück. Halte die Spannung eine Sekunde. Tipp: Nimm denselben Bogen wie beim Absenken der Gewichte.', 'Mach die vorgegebene Anzahl an Wiederholungen.']::text[]),
  ('Incline_Dumbbell_Bench_With_Palms_Facing_In', 'de', array['Lehne dich auf einer Schrägbank zurück, in jeder Hand eine Kurzhantel, die auf deinen Oberschenkeln liegt. Die Handflächen zeigen zueinander.', 'Bring die Kurzhanteln mit Schwung aus den Oberschenkeln nach oben, einen Arm nach dem anderen, bis du sie schulterbreit hältst.', 'Halte sie dort im neutralen Griff, die Handflächen zeigen zueinander. Stelle die Ellbogen nach außen, sodass die Oberarme auf einer Linie mit den Schultern liegen (im rechten Winkel zum Oberkörper), und beuge die Ellbogen, bis Ober- und Unterarm einen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Atme ein und senke die Gewichte langsam zur Seite ab. Behalte die Kurzhanteln dabei jederzeit voll unter Kontrolle.', 'Atme aus und drücke die Kurzhanteln mit der Brustmuskulatur nach oben. Strecke die Arme oben ganz durch, halte eine Sekunde und senke dann langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach die vorgegebene Anzahl an Wiederholungen.', 'Wenn du fertig bist, lege die Kurzhanteln wieder auf die Oberschenkel und stelle sie dann auf den Boden. So legst du die Kurzhanteln am sichersten ab.']::text[]),
  ('Incline_Dumbbell_Curl', 'de', array['Lehne dich auf einer Schrägbank zurück und halte in jeder Hand eine Kurzhantel, die Arme hängen gestreckt herab. Die Ellbogen bleiben nah am Oberkörper, die Handflächen drehst du nach vorn. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Arme nach vorn, indem du den Bizeps anspannst. Nur die Unterarme bewegen sich. Mach weiter, bis der Bizeps ganz angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Halte die Spannung eine Sekunde.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Incline_Dumbbell_Flyes', 'de', array['Nimm in jede Hand eine Kurzhantel und leg dich auf eine Schrägbank, die auf höchstens 30 Grad eingestellt ist.', 'Strecke die Arme über dir nach oben, die Ellbogen leicht gebeugt.', 'Dreh die Handgelenke, bis die Handflächen zu dir zeigen. Tipp: Die kleinen Finger sollten nebeneinander liegen. Das ist deine Ausgangsposition.', 'Atme ein und senke die Arme langsam zur Seite, sie bleiben dabei gestreckt und du drehst die Handgelenke, bis die Handflächen zueinander zeigen. Tipp: Am Ende der Bewegung sind die Arme seitlich neben dir und die Handflächen zeigen zur Decke.', 'Atme aus und bring die Kurzhanteln auf dem umgekehrten Weg in die Ausgangsposition, dreh dabei die Hände, bis die kleinen Finger wieder nebeneinander liegen. Tipp: Die Bewegung findet nur im Schultergelenk und im Handgelenk statt. Im Ellbogengelenk bewegt sich nichts.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Incline_Dumbbell_Flyes_-_With_A_Twist', 'de', array['Nimm in jede Hand eine Kurzhantel und leg dich auf eine Schrägbank, die auf höchstens 30 Grad eingestellt ist.', 'Strecke die Arme über dir nach oben, die Ellbogen leicht gebeugt.', 'Dreh die Handgelenke, bis die Handflächen zu dir zeigen. Tipp: Die kleinen Finger sollten nebeneinander liegen. Das ist deine Ausgangsposition.', 'Atme ein und senke die Arme langsam zur Seite, sie bleiben dabei gestreckt und du drehst die Handgelenke, bis die Handflächen zueinander zeigen. Tipp: Am Ende der Bewegung sind die Arme seitlich neben dir und die Handflächen zeigen zur Decke.', 'Atme aus und bring die Kurzhanteln auf dem umgekehrten Weg in die Ausgangsposition, dreh dabei die Hände, bis die kleinen Finger wieder nebeneinander liegen. Tipp: Die Bewegung findet nur im Schultergelenk und im Handgelenk statt. Im Ellbogengelenk bewegt sich nichts.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Incline_Dumbbell_Press', 'de', array['Lehne dich auf einer Schrägbank zurück, in jeder Hand eine Kurzhantel, die auf deinen Oberschenkeln liegt. Die Handflächen zeigen zueinander.', 'Hilf dann mit den Oberschenkeln nach und bring die Kurzhanteln nacheinander hoch, bis du sie schulterbreit hältst.', 'Sind die Kurzhanteln schulterbreit oben, dreh die Handgelenke nach vorn, sodass die Handflächen von dir weg zeigen. Das ist deine Ausgangsposition.', 'Behalte die Kurzhanteln jederzeit voll unter Kontrolle. Atme dann aus und drücke sie mit der Brust nach oben.', 'Strecke die Arme oben ganz durch, halte eine Sekunde und senke das Gewicht dann langsam ab. Tipp: Im Idealfall dauert das Absenken etwa doppelt so lange wie das Hochdrücken.', 'Mach die vorgegebene Anzahl an Wiederholungen.', 'Wenn du fertig bist, lege die Kurzhanteln wieder auf die Oberschenkel und stelle sie dann auf den Boden. So gibst du die Kurzhanteln am sichersten aus der Hand.']::text[]),
  ('Incline_Hammer_Curls', 'de', array['Setz dich mit einer Kurzhantel in jeder Hand auf eine Schrägbank. Drücke den Rücken fest gegen die Lehne und stelle die Füße zusammen. Lass die Kurzhanteln im neutralen Griff seitlich gerade herabhängen. Das ist deine Ausgangsposition.', 'Beginne die Bewegung, indem du die Ellbogen beugst, und versuche, die Oberarme ruhig zu halten.', 'Führe die Bewegung bis ganz nach oben, halte kurz und kehre langsam in die Ausgangsposition zurück.']::text[]),
  ('Incline_Inner_Biceps_Curl', 'de', array['Nimm in jede Hand eine Kurzhantel und lehne dich auf einer Schrägbank zurück.', 'Lass die Arme gestreckt neben dem Körper hängen, die Handflächen zeigen nach außen. Das ist deine Ausgangsposition.', 'Atme aus und beuge die Arme nach außen und oben. Die Unterarme bleiben dabei auf einer Linie mit den seitlichen Schultermuskeln. Beuge weiter, bis die Kurzhanteln auf Schulterhöhe seitlich neben den Schultern sind. Tipp: Oben sieht die Bewegung ähnlich aus wie eine doppelte Bizepspose.', 'Halte die Spannung oben eine Sekunde. Atme dann ein und senke die Gewichte langsam auf demselben Weg zurück in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Incline_Push-Up', 'de', array['Stell dich vor eine Bank oder eine stabile Erhöhung. Setze die Hände etwas weiter als schulterbreit auf die Kante.', 'Geh mit den Füßen zurück auf die Fußballen, bis Arme und Körper gestreckt sind. Die Arme stehen im rechten Winkel zum Körper. Beuge die Arme und senke die Brust zur Kante der Bank oder Erhöhung, der Körper bleibt gerade.', 'Drück dich hoch, bis die Arme gestreckt sind. Wiederhole.']::text[]),
  ('Incline_Push-Up_Close-Grip', 'de', array['Stell dich vor die Stange einer Multipresse oder vor eine stabile Erhöhung in passender Höhe.', 'Setze die Hände direkt nebeneinander auf die Stange.', 'Geh mit den Füßen zurück, bis Arme und Körper gestreckt sind. Das ist deine Ausgangsposition.', 'Beuge die Arme und senke die Brust zur Stange. Der Körper bleibt dabei gerade.', 'Strecke die Ellbogen und drück dich zurück in die Ausgangsposition.']::text[]),
  ('Incline_Push-Up_Depth_Jump', 'de', array['Für diese Übung brauchst du eine etwa 12 Zoll hohe Box und zwei dicke Matten oder Aerobic-Stepper.', 'Lege die Stepper knapp außerhalb der Schultern ab. Stell die Füße auf die Box und setze die Hände knapp innerhalb der Stepper auf den Boden, sodass du in einer Liegestützposition mit erhöhten Füßen bist. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und senke den Körper ab, kehre die Bewegung schnell um und drück dich vom Boden ab. Sobald die Hände den Boden verlassen, setze sie auf die Stepper und beuge die Ellbogen, um den Aufprall abzufangen.', 'Wiederhole die Bewegung, um in die Ausgangsposition zurückzukommen.']::text[]),
  ('Incline_Push-Up_Medium', 'de', array['Stell dich vor die Stange einer Multipresse oder vor eine stabile Erhöhung in passender Höhe.', 'Setze die Hände etwa schulterbreit auf die Stange.', 'Geh mit den Füßen zurück, bis Arme und Körper gestreckt sind. Das ist deine Ausgangsposition.', 'Beuge die Arme und senke die Brust zur Stange. Der Körper bleibt dabei gerade.', 'Strecke die Ellbogen und drück dich zurück in die Ausgangsposition.']::text[]),
  ('Incline_Push-Up_Reverse_Grip', 'de', array['Stell dich vor die Stange einer Multipresse oder vor eine stabile Erhöhung in passender Höhe.', 'Setze die Hände etwa schulterbreit auf die Stange, die Handflächen zeigen nach oben.', 'Geh mit den Füßen zurück, bis Arme und Körper gestreckt sind. Das ist deine Ausgangsposition.', 'Beuge die Arme und senke die Brust zur Stange. Der Körper bleibt dabei gerade.', 'Strecke die Ellbogen und drück dich zurück in die Ausgangsposition.']::text[]),
  ('Incline_Push-Up_Wide', 'de', array['Stell dich vor die Stange einer Multipresse oder vor eine stabile Erhöhung in passender Höhe.', 'Setze die Hände weiter als schulterbreit auf die Stange.', 'Geh mit den Füßen zurück, bis Arme und Körper gestreckt sind. Die Arme stehen im rechten Winkel zum Körper. Das ist deine Ausgangsposition.', 'Beuge die Arme und senke die Brust zur Stange. Der Körper bleibt dabei gerade.', 'Strecke die Ellbogen und drück dich zurück in die Ausgangsposition.']::text[]),
  ('Intermediate_Groin_Stretch', 'de', array['Leg dich mit gestreckten Beinen auf den Rücken. Lege einen Gürtel, ein Seil oder ein Band um einen Fuß und führe dieses Bein so weit wie möglich zur Seite. Das ist deine Ausgangsposition.', 'Zieh sanft am Gürtel, bis du Spannung in der Leiste und im Beinbeuger spürst. Halte 10-20 Sekunden und wiederhole auf der anderen Seite.']::text[]),
  ('Intermediate_Hip_Flexor_and_Quad_Stretch', 'de', array['Leg dich bäuchlings auf den Boden, ein Seil, einen Gürtel oder ein Band um einen Fuß gelegt.', 'Beuge am zu dehnenden Bein das Knie und strecke die Hüfte, während du mit beiden Händen am Gürtel ziehst. Knie und Hüfte sollen sich vom Boden lösen, sodass Spannung in den Hüftbeugern und im Quadrizeps entsteht. Halte die Dehnung 10-20 Sekunden und wiederhole mit dem anderen Bein.']::text[]),
  ('Internal_Rotation_with_Band', 'de', array['Schlinge das Band fest um einen Pfosten, auf Höhe deines Ellbogens. Stell dich ein paar Fuß entfernt hin, die rechte Seite zum Band.', 'Greif das Ende des Bandes mit der rechten Hand und drück den Ellbogen fest an deine Seite. Empfohlen wird, ein Polster oder eine Faszienrolle mit dem Ellbogen einzuklemmen, damit er sicher an seinem Platz bleibt.', 'Der Oberarm bleibt fixiert, der Ellbogen ist auf 90 Grad gebeugt und die Hand zeigt vom Oberkörper weg. Das ist deine Ausgangsposition.', 'Drehe den Arm wie bei einer Vorhand nach innen. Der Ellbogen bleibt an seinem Platz.', 'Geh so weit, wie du kannst, halte kurz und kehre in die Ausgangsposition zurück.']::text[]),
  ('Inverted_Row', 'de', array['Lege eine Stange etwa auf Hüfthöhe in ein Rack. Eine Multipresse geht auch.', 'Greif die Stange weiter als schulterbreit und häng dich darunter. Der Körper ist gerade, die Fersen stehen auf dem Boden, die Arme sind ganz gestreckt. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und zieh die Brust zur Stange. Zieh dabei die Schulterblätter zusammen.', 'Halte oben kurz und lass dich in die Ausgangsposition zurück.', 'Wiederhole das so oft, wie du möchtest.']::text[]),
  ('Inverted_Row_with_Straps', 'de', array['Befestige ein Seil oder Schlingentrainer-Gurte an einem Rack oder einem anderen stabilen Gegenstand. Greif die Enden und häng dich in Rückenlage daran. Der Körper ist gerade, die Fersen stehen auf dem Boden, die Arme sind ganz gestreckt. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und zieh die Brust zu den Händen. Zieh dabei die Schulterblätter zusammen.', 'Halte oben kurz und lass dich in die Ausgangsposition zurück.', 'Wiederhole das so oft, wie du möchtest.']::text[]),
  ('Iron_Cross', 'de', array['Stell dich etwa schulterbreit hin, in jeder Hand eine Kurzhantel. Hebe die gestreckten Arme seitlich auf Schulterhöhe, die Handflächen zeigen nach vorn. Das ist deine Ausgangsposition.', 'Beuge Knie und Hüfte und geh in die Kniebeuge. Führe auf dem Weg nach unten die gestreckten Arme vor der Brust zusammen.', 'Stopp, wenn die Oberschenkel etwa parallel zum Boden sind. Der Rücken bleibt gerade, die Brust oben.', 'Drück dich über die Fersen wieder hoch und öffne die Arme zurück zur Seite. Wiederhole.']::text[]),
  ('Iron_Crosses_stretch', 'de', array['Leg dich bäuchlings auf den Boden, die Arme seitlich ausgestreckt, die Handflächen auf den Boden gedrückt. Das ist deine Ausgangsposition.', 'Beuge ein Knie und führe dieses Bein hinter dem Körper zur anderen Seite. Versuche, damit den Boden nahe der gegenüberliegenden Hand zu berühren.', 'Bring das Bein sofort zurück in die Ausgangsposition und wiederhole zügig mit dem anderen Bein. Wechsle 10-20 Wiederholungen lang ab.']::text[]),
  ('Isometric_Chest_Squeezes', 'de', array['Beuge im Sitzen oder Stehen die Arme auf 90 Grad und lege die Handflächen vor der Brust aneinander. Tipp: Die Hände sind offen, Handfläche an Handfläche, und die Finger zeigen nach vorn (im rechten Winkel zum Oberkörper).', 'Drück beide Hände gegeneinander und spanne die Brust an. Beginne mit wenig Spannung und steigere sie langsam. Atme dabei normal weiter.', 'Halte die empfohlene Anzahl an Sekunden.', 'Löse die Spannung dann langsam.', 'Mach die empfohlene Pause und wiederhole.']::text[]),
  ('Isometric_Neck_Exercise_-_Front_And_Back', 'de', array['Halte Kopf und Nacken neutral (normale Haltung, Kopf aufrecht, Blick nach vorn) und lege beide Hände an die Stirnseite deines Kopfes.', 'Drück den Kopf sanft nach vorn und spanne die Nackenmuskeln an, lass aber keine Bewegung des Kopfes zu. Beginne mit wenig Spannung und steigere sie langsam. Atme dabei normal weiter.', 'Halte die empfohlene Anzahl an Sekunden.', 'Löse die Spannung dann langsam.', 'Mach die empfohlene Pause und wiederhole mit den Händen am Hinterkopf.']::text[]),
  ('Isometric_Neck_Exercise_-_Sides', 'de', array['Halte Kopf und Nacken neutral (normale Haltung, Kopf aufrecht, Blick nach vorn) und lege die linke Hand an die linke Seite deines Kopfes.', 'Drück den Kopf sanft nach links und spanne die linken Nackenmuskeln an, lass aber keine Bewegung des Kopfes zu. Beginne mit wenig Spannung und steigere sie langsam. Atme dabei normal weiter.', 'Halte die empfohlene Anzahl an Sekunden.', 'Löse die Spannung dann langsam.', 'Mach die empfohlene Pause und wiederhole mit der rechten Hand an der rechten Seite deines Kopfes.']::text[]),
  ('Isometric_Wipers', 'de', array['Geh in die Liegestützposition: Das Gewicht ruht auf Händen und Zehen, der Körper ist gerade, die Hände stehen etwas weiter als schulterbreit. Das ist deine Ausgangsposition.', 'Verlagere dein Gewicht so weit wie möglich auf eine Seite. Der Ellbogen dieser Seite beugt sich, während du den Körper absenkst.', 'Strecke den gebeugten Arm, drück dich wieder hoch und lass dich dann zur anderen Seite sinken.', 'Wiederhole das so oft, wie du möchtest.']::text[]),
  ('JM_Press', 'de', array['Beginne wie beim engen Bankdrücken: Leg dich auf eine Flachbank und halte eine Langhantel an ganz gestreckten Armen, die Ellbogen innen. Die Arme stehen aber nicht senkrecht zum Oberkörper, sondern die Stange liegt in direkter Linie über der oberen Brust. Das ist deine Ausgangsposition.', 'Senke die Stange aus der Streckung ab wie bei einer liegenden Trizepsstreckung. Atme dabei ein. Auf halbem Weg lässt du die Stange etwa einen Zoll zurückrollen: Führe die Oberarme in Richtung Beine, bis sie senkrecht zum Oberkörper stehen. Tipp: Der Winkel im Ellbogen bleibt gleich, während du die Oberarme nach vorn bringst.', 'Atme aus und drück die Stange mit dem Trizeps wieder hoch, wie beim engen Bankdrücken.', 'Kehre in die Ausgangsposition zurück und beginne von vorn.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Jackknife_Sit-Up', 'de', array['Leg dich flach mit dem Rücken auf den Boden (oder eine Trainingsmatte). Die Arme sind gerade hinter den Kopf gestreckt, die Beine ebenfalls gestreckt. Das ist deine Ausgangsposition.', 'Atme aus, klappe in der Taille zusammen und hebe gleichzeitig Beine und Arme, bis sie sich in der Klappmesser-Position treffen. Tipp: Die Beine sind gestreckt und etwa 35-45 Grad vom Boden angehoben, die Arme sind gestreckt und parallel zu den Beinen. Der Oberkörper hebt vom Boden ab.', 'Atme ein und senke Arme und Beine zurück in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Janda_Sit-Up', 'de', array['Geh auf dem Boden in die normale Sit-up-Position: Knie im Neunzig-Grad-Winkel, Fußsohlen auf dem Boden, Arme vor der Brust gekreuzt oder an den Seiten. Das ist deine Ausgangsposition.', 'Spanne Gesäß und Beinbeuger kräftig an, atme tief ein und komm langsam hoch (zähle dabei auf drei bis sechs Sekunden), während du langsam ausatmest. Tipp: Die Spannung in Gesäß und Beinbeuger ist wichtig, weil sie die Hüftbeuger ausschaltet. Das nennt man reziproke Hemmung: Die Gegenspieler der angespannten Muskeln entspannen sich.', 'Atme ein und geh langsam und kontrolliert zurück in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Jefferson_Squats', 'de', array['Lege eine Langhantel auf den Boden.', 'Stell dich über die Stange, in die Mitte ihrer Länge.', 'Geh mit geradem Rücken in die Knie und greif die Stange vor dir mit der rechten Hand. Der Griff ist neutral, die Handfläche zeigt nach links.', 'Greif die Stange hinter dir mit der linken Hand, ebenfalls im neutralen Griff (Handfläche zeigt nach rechts). Tipp: Achte auf einen gleichmäßigen Griff. Dein Oberkörper steht genau über der Mitte der Stange: Die rechte Hand vorn ist so weit vom Oberkörper entfernt wie die linke Hand hinten.', 'Richte dich mit dem Gewicht gerade auf. Tipp: Die Füße stehen schulterbreit, die Zehen zeigen leicht nach außen.', 'Beuge die Knie und geh mit geradem Rücken in die Hocke, bis die Oberschenkel parallel zum Boden sind. Tipp: Halte den Rücken so senkrecht wie möglich und den Kopf oben. Die Knie sollen nicht über die Zehen hinausgehen. Atme in dieser Phase ein.', 'Drück dich mit den Füßen zurück in die Ausgangsposition. Tipp: Die Stange hängt an den langen Armen, die Ellbogen sind mit leichter Beugung fixiert. Die Arme sind nur Haken, heben sollen sie nicht. Die Arbeit machen die Oberschenkel, nicht die Arme.']::text[]),
  ('Jerk_Balance', 'de', array['Mit dieser Übung lernst du, beim Jerk tief genug unter die Hantel zu kommen. Sie korrigiert außerdem, wenn du dich bei der Bewegung nach hinten verschiebst. Beginne mit der Stange in der Jerk-Position: Schultern vorn, Oberkörper aufrecht, Füße in leichter Schrittstellung.', 'Starte wie bei einem normalen Jerk: Geh mit senkrechtem Oberkörper leicht in die Knie und drück dich kraftvoll wieder hoch. Der Schwung hebt das Gewicht, nicht die Arme.', 'Der hintere Fuß bleibt stehen. Drück dich von ihm ab und schiebe den Körper nach vorn in den vollen Ausfallschritt, während du das Gewicht ausstößt. Richte dich zum Abschluss mit dem Gewicht über dem Kopf auf.']::text[]),
  ('Jerk_Dip_Squat', 'de', array['Diese Übung kräftigt die Dip-Phase des Jerk. Beginne mit der Stange in der Jerk-Position: Die Schultern sind nach vorn geschoben und bilden eine Ablage, die Stange berührt leicht den Hals. Die Füße stehen direkt unter den Hüften und sind so weit ausgedreht, wie es bequem ist.', 'Halte den Oberkörper senkrecht und beuge die Knie. Sie dürfen nach vorn wandern, die Hüfte geht nicht nach hinten. Geh dabei nicht zu tief. Drück dich kraftvoll über die Füße hoch und bring das Gewicht zurück in die Ausgangsposition.']::text[]),
  ('Jogging_Treadmill', 'de', array['Steig auf das Laufband und wähle im Menü die gewünschte Option. Die meisten Laufbänder haben eine manuelle Einstellung, oder du wählst ein Programm. Meist kannst du Alter und Gewicht eingeben, damit der Kalorienverbrauch beim Training geschätzt wird. Über die Steigung veränderst du die Intensität.', 'Laufbänder sind praktisch, gut für Herz und Kreislauf und belasten die Gelenke meist weniger als Joggen im Freien. Eine Person mit 150 lb verbrennt bei 30 Minuten Joggen fast 250 Kalorien, beim Laufen sind es mehr als 450 Kalorien. Achte beim Joggen auf eine gute Haltung und halte dich nur an den Griffen fest, wenn es nötig ist, etwa beim Absteigen oder beim Pulsmessen.']::text[]),
  ('Keg_Load', 'de', array['Stell für das Fassladen die gewünschte Anzahl Fässer in einiger Entfernung von der Ladeplattform auf, üblich sind 30-50 Fuß.', 'Greif den nahen Griff des ersten Fasses und kippe es auf die Seite, damit du die gegenüberliegende Kante des Bodens fassen kannst. Hebe das Fass an die Brust.', 'Je höher du das Fass trägst, desto schneller kommst du in der Regel zur Plattform. Auf die Schulter nehmen ist meist nicht erlaubt. Halte das Fass gut fest. Lauf so schnell wie möglich zur Plattform und lade es auf. Strecke dabei Hüfte, Knie und Sprunggelenke, um es möglichst hoch zu bringen.', 'Geh zurück zum Start, hol das nächste Fass und wiederhole, bis der Durchgang beendet ist.']::text[]),
  ('Kettlebell_Arnold_Press', 'de', array['Setze eine Kettlebell zur Schulter um: Strecke Beine und Hüfte, während du die Kettlebell zur Schulter hochführst. Die Handfläche zeigt nach innen.', 'Schau geradeaus und drück die Kettlebell nach außen und über den Kopf. Drehe dabei das Handgelenk, sodass die Handfläche oben nach vorn zeigt.', 'Führe die Kettlebell zurück in die Ausgangsposition, die Handfläche zeigt wieder nach innen.']::text[]),
  ('Kettlebell_Dead_Clean', 'de', array['Stell die Kettlebell zwischen deine Füße. Für die Ausgangsposition schiebst du den Po nach hinten und schaust geradeaus.', 'Setze die Kettlebell zur Schulter um: Strecke Beine und Hüfte, während du sie hochführst. Das Handgelenk dreht sich dabei mit.', 'Senke die Kettlebell ab. Der Rücken bleibt gerade und der Po hinten, damit der Beinbeuger unter Spannung bleibt.']::text[]),
  ('Kettlebell_Figure_8', 'de', array['Stell eine Kettlebell zwischen deine Beine und nimm einen Stand weiter als schulterbreit ein. Beuge dich vor, indem du den Po nach hinten schiebst. Der Rücken bleibt gerade.', 'Hebe die Kettlebell an und gib sie zwischen den Beinen in die andere Hand. Die annehmende Hand greift von hinten um das Bein. Wechsle so mehrere Wiederholungen hin und her.']::text[]),
  ('Kettlebell_Halo', 'de', array['Stell dich aufrecht hin, die Füße hüftbreit. Halte eine Kettlebell umgedreht an den Hörnern, die Kugel über den Händen und nah an der Brust. Spanne Bauch und Gesäß an, damit der Brustkorb unten bleibt. Das ist deine Ausgangsposition.', 'Die Ellbogen bleiben nah am Kopf. Führe die Kettlebell an einem Ohr vorbei nach oben und hinter den Kopf.', 'Führe den Kreis am anderen Ohr vorbei weiter und zurück nach unten in die Ausgangsposition vor der Brust. Die Kugel bleibt die ganze Zeit nah am Körper.', 'Mach die vorgegebene Anzahl an Kreisen in eine Richtung und dann genauso viele in die andere.', 'Bewege dich langsam und halte Kopf, Hüfte und unteren Rücken ruhig. Geht der untere Rücken ins Hohlkreuz oder entfernt sich die Kugel weit vom Kopf, nimm ein leichteres Gewicht.']::text[]),
  ('Kettlebell_Halo_With_Overhead_Extension', 'de', array['Stell dich aufrecht hin, die Füße hüftbreit. Halte eine Kettlebell umgedreht an den Hörnern, die Kugel über den Händen und nah an der Brust. Spanne Bauch und Gesäß an, damit der Brustkorb unten bleibt. Das ist deine Ausgangsposition.', 'Die Ellbogen bleiben nah am Kopf. Führe die Kettlebell an einem Ohr vorbei nach oben und herum, bis sie hinter dem Kopf ist. Halte hier kurz an.', 'Strecke aus dieser Position die Ellbogen und drück die Kettlebell über den Kopf, bis die Arme gerade sind. Die Oberarme bleiben neben dem Kopf.', 'Beuge die Ellbogen und senke die Kettlebell kontrolliert zurück in die Halteposition hinter dem Kopf.', 'Führe den Kreis am anderen Ohr vorbei weiter und zurück nach unten in die Ausgangsposition vor der Brust. Damit ist eine Wiederholung fertig.', 'Wechsle bei jeder Wiederholung die Richtung des Kreises. Halte Kopf, Hüfte und unteren Rücken die ganze Zeit ruhig. Geht der untere Rücken ins Hohlkreuz oder kommst du nicht über den Kopf, ohne dich zurückzulehnen, nimm ein leichteres Gewicht oder mach Halo und Streckung als getrennte Übungen.']::text[]),
  ('Kettlebell_Hang_Clean', 'de', array['Stell die Kettlebell zwischen deine Füße. Für die Ausgangsposition schiebst du den Po nach hinten und schaust geradeaus.', 'Setze die Kettlebell zur Schulter um: Strecke Beine und Hüfte, während du sie hochführst. Das Handgelenk dreht sich dabei mit.', 'Senke die Kettlebell ab, bis sie zwischen deinen Beinen hängt. Der Beinbeuger bleibt unter Spannung. Halte den Kopf die ganze Zeit oben.']::text[]),
  ('Kettlebell_One-Legged_Deadlift', 'de', array['Halte eine Kettlebell mit einer Hand am Griff. Stell dich auf ein Bein, und zwar auf der Seite der Kettlebell.', 'Das Knie bleibt leicht gebeugt. Mach ein Kreuzheben mit gestrecktem Bein: Beuge dich aus der Hüfte vor und strecke das freie Bein zum Ausgleich nach hinten.', 'Senke die Kettlebell weiter, bis dein Körper parallel zum Boden ist, und richte dich dann wieder auf.']::text[]),
  ('Kettlebell_Overhead_Triceps_Extension', 'de', array['Stell dich hüftbreit hin und halte eine Kettlebell mit beiden Händen an den Hörnern. Drück sie über den Kopf, bis die Arme gestreckt sind. Die Kugel hängt hinter den Händen.', 'Spanne den Bauch an und halte die Oberarme senkrecht und nah am Kopf. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und senke die Kettlebell hinter den Kopf, so weit es die Beweglichkeit deiner Schultern erlaubt, ohne dass die Ellbogen nach außen wandern.', 'Strecke die Ellbogen und drück die Kettlebell zurück in die Ausgangsposition. Die Oberarme bleiben die ganze Zeit ruhig.', 'Halte den Brustkorb unten und geh beim Strecken nicht ins Hohlkreuz.']::text[]),
  ('Kettlebell_Pass_Between_The_Legs', 'de', array['Stell eine Kettlebell zwischen deine Beine und nimm einen bequemen Stand ein. Beuge dich vor, indem du den Po nach hinten schiebst. Der Rücken bleibt gerade.', 'Hebe die Kettlebell an und gib sie zwischen den Beinen in die andere Hand, in der Form eines "W". Wechsle so mehrere Wiederholungen hin und her.']::text[]),
  ('Kettlebell_Pirate_Ships', 'de', array['Stell dich breit hin und halte eine Kettlebell mit beiden Händen. Sie hängt an gestreckten Armen auf Hüfthöhe. Das ist deine Ausgangsposition.', 'Dreh dich zu einer Seite und schwinge die Kettlebell auf Kopfhöhe. Halte oben kurz an.', 'Lass die Kugel fallen, während du dich zur anderen Seite drehst, und bring sie dort wieder auf Kopfhöhe.', 'Wiederhole das so oft, wie du möchtest.']::text[]),
  ('Kettlebell_Pistol_Squat', 'de', array['Nimm eine Kettlebell mit beiden Händen und halte sie an den Hörnern. Hebe ein Bein vom Boden ab, auf dem anderen gehst du in die Hocke.', 'Beuge das Knie und setz dich mit der Hüfte nach hinten ab. Die Kettlebell hältst du vor dir oben.', 'Bleib unten eine Sekunde und kehre die Bewegung um: Drück dich über die Ferse hoch, Kopf und Brust bleiben oben.', 'Geh wieder nach unten und wiederhole.']::text[]),
  ('Kettlebell_Seated_Press', 'de', array['Setz dich auf den Boden und spreize die Beine bequem.', 'Setze eine Kettlebell zur Schulter um.', 'Drück die Kettlebell nach oben und außen, bis der Arm über dem Kopf durchgestreckt ist. Kehre in die Ausgangsposition zurück.']::text[]),
  ('Kettlebell_Seesaw_Press', 'de', array['Setze zwei Kettlebells zu den Schultern um.', 'Drück eine der Kettlebells nach oben.', 'Senke sie ab und drück sofort die andere hoch. Mach auf beiden Seiten gleich viele Wiederholungen.']::text[]),
  ('Kettlebell_Sumo_High_Pull', 'de', array['Stell eine Kettlebell zwischen deinen Füßen auf den Boden. Nimm einen breiten Stand ein und greif die Kettlebell mit beiden Händen. Schiebe die Hüfte so weit wie möglich nach hinten, die Knie sind gebeugt. Brust und Kopf bleiben oben. Das ist deine Ausgangsposition.', 'Strecke Hüfte und Knie und zieh gleichzeitig die Kettlebell zu den Schultern. Die Ellbogen gehen dabei nach oben. Kehre die Bewegung um und geh zurück in die Ausgangsposition.']::text[]),
  ('Kettlebell_Thruster', 'de', array['Setze zwei Kettlebells zu den Schultern um: Strecke Beine und Hüfte, während du die Kettlebells hochziehst, und drehe dabei die Handgelenke. Das ist deine Ausgangsposition.', 'Beuge Hüfte und Knie und geh in die Kniebeuge, die Hüfte sinkt zwischen die Beine. Geh so tief, wie du kannst, mit aufrechtem, geradem Rücken.', 'Kehre unten die Richtung um: Strecke Knie und Hüfte und drück dich über die Fersen hoch. Drück dabei beide Kettlebells über den Kopf, indem du die Arme gerade nach oben streckst. Nutze den Schwung aus der Kniebeuge, um die Gewichte nach oben zu treiben.', 'Bring die Gewichte zu Beginn der nächsten Wiederholung zurück zu den Schultern.']::text[]),
  ('Kettlebell_Turkish_Get-Up_Lunge_style', 'de', array['Leg dich mit dem Rücken auf den Boden und drück eine Kettlebell nach oben, indem du den Ellbogen streckst. Beuge das Knie auf der Seite der Kettlebell.', 'Der Arm mit der Kettlebell bleibt die ganze Zeit durchgestreckt. Dreh dich zur Gegenseite und nimm den freien Arm zu Hilfe, um dich nach vorn in Richtung Ausfallschritt zu bringen. Drück dich mit der freien Hand in den Sitz und komm dann auf ein Knie.', 'Schau zur Kettlebell hoch und steh langsam auf. Kehre die Bewegung bis in die Ausgangsposition um und wiederhole.']::text[]),
  ('Kettlebell_Turkish_Get-Up_Squat_style', 'de', array['Leg dich mit dem Rücken auf den Boden und drück eine Kettlebell nach oben, indem du den Ellbogen streckst. Beuge das Knie auf der Seite der Kettlebell.', 'Der Arm mit der Kettlebell bleibt die ganze Zeit durchgestreckt. Dreh dich zur Gegenseite und nimm den freien Arm zu Hilfe, um dich nach vorn in Richtung Ausfallschritt zu bringen.', 'Drück dich mit der freien Hand in den Sitz und komm dann auf die Füße. Schau zur Kettlebell hoch und steh langsam auf. Kehre die Bewegung bis in die Ausgangsposition um und wiederhole.']::text[]),
  ('Kettlebell_Windmill', 'de', array['Stell eine Kettlebell vor deinen vorderen Fuß, setze sie mit dem gegenüberliegenden Arm um und drück sie über den Kopf. Zum Umsetzen streckst du Beine und Hüfte, während du die Kettlebell zur Schulter ziehst. Drehe dabei das Handgelenk, sodass die Handfläche nach vorn zeigt. Drück sie dann über den Kopf, indem du den Ellbogen streckst.', 'Der Arm mit der Kettlebell bleibt die ganze Zeit durchgestreckt. Schiebe den Po in Richtung der gestreckt gehaltenen Kettlebell hinaus. Drehe die Füße in einem Winkel von fünfundvierzig Grad vom Arm mit der Kettlebell weg. Beuge dich aus der Hüfte zur Seite, der Po geht hinaus, und neige dich langsam, bis die freie Hand den Boden berühren kann. Behalte die Kettlebell über deinem Kopf immer im Blick.', 'Halte eine Sekunde, wenn du den Boden erreicht hast, und kehre die Bewegung bis in die Ausgangsposition um.']::text[]),
  ('Kipping_Muscle_Up', 'de', array['Greif die Ringe im False Grip: Der Handballen liegt oben auf dem Ring.', 'Beginne damit, die Beine leicht nach hinten zu schwingen.', 'Fang diese Bewegung ab, indem du die Beine nach vorn und oben schwingst und Kinn und Brust ruckartig zurücknimmst. Zieh dich dabei mit beiden Armen hoch. Bist du oben im Klimmzug angekommen, zieh die Ringe zu den Achseln und rolle die Schultern nach vorn. Die Ellbogen wandern dabei gerade nach hinten. So bist du in der richtigen Position für den Dip-Teil der Bewegung.', 'Bleib kontrolliert und stabil und strecke die Ellbogen, um die Bewegung abzuschließen.', 'Lass dich vorsichtig wieder zum Boden herunter.']::text[]),
  ('Knee_Across_The_Body', 'de', array['Leg dich auf den Boden, das rechte Bein gestreckt. Beuge das linke Bein und lass es über den Körper sinken. Die rechte Hand hält das Knie in Richtung Boden. (Bist du unbeweglich, muss das Knie den Boden nicht berühren.)', 'Lege den linken Arm bequem neben dich und dreh den Kopf nach links. Stell dir vor, an deinem Steißbein hängt ein Gewicht: Lass das Steißbein zurück zum Boden sinken, während die Brust in die Gegenrichtung strebt. So dehnst du den unteren Rücken. Wechsle die Seite.']::text[]),
  ('Knee_Circles', 'de', array['Stell dich mit geschlossenen Beinen hin, die Hände an der Taille.', 'Kreise mit den Knien und atme dabei normal.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Knee_Hip_Raise_On_Parallel_Bars', 'de', array['Stell dich in die Beinhebe-Station: Leg die Unterarme neben dem Oberkörper auf die Polster und greif die Griffe. Deine Ellbogen sind im 90-Grad-Winkel gebeugt.', 'Halte den Oberkörper gerade, drück den unteren Rücken gegen das Rückenpolster und lass die gestreckten Beine zum Boden hängen. Das ist deine Ausgangsposition.', 'Atme aus und heb die Beine gestreckt an. Stopp, wenn sie etwa parallel zum Boden sind, und halte die Spannung eine Sekunde. Tipp: Arbeite ohne Schwung und ohne zu pendeln.', 'Atme ein und senke die Beine langsam in die Ausgangsposition.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Knee_Tuck_Jump', 'de', array['Stell dich bequem hin, die Knie leicht gebeugt. Halte die Hände auf Brusthöhe vor dich, Handflächen nach unten, die Fingerspitzen berühren sich. Das ist deine Ausgangsposition.', 'Geh schnell in eine Viertelkniebeuge und spring sofort explosiv nach oben. Zieh die Knie zur Brust und versuch, damit deine Handflächen zu berühren.', 'Spring so hoch du kannst und zieh dabei die Knie hoch. Streck die Beine für eine sichere Landung wieder und fang den Aufprall ab, indem du die Knie erneut nachgeben lässt.']::text[]),
  ('Kneeling_Arm_Drill', 'de', array['Mit dieser Übung wird deine Armarbeit beim Laufen effizienter. Knie dich hin, linker Fuß vorn, rechtes Knie am Boden. Drück über die vordere Ferse in den Boden, damit Gesäß und Beinbeuger aktiv bleiben.', 'Beginne mit langen, pendelartigen Armschwüngen. Verkleinere dann den Armwinkel und führe die Arme wie beim Joggen, steigere dich zum Lauf und schließlich zum Sprint.', 'Beschleunige die Hände in der Sprintbewegung nach vorn, sobald sie die Hüfte passieren, damit sie sich so schnell wie möglich bewegen.', 'Wechsle das Knie und wiederhole die Übung.']::text[]),
  ('Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'de', array['Befestige ein Seil am oberen Kabelzug und leg eine Matte davor auf den Boden.', 'Greif das Seil mit beiden Händen und knie dich etwa two feet vom Turm entfernt hin.', 'Führ das Seil hinter den Kopf, sodass deine Hände neben den Ohren sind.', 'Lass die Hände an dieser Stelle, spann den Bauch an und roll dich gegen den Zug des Seils nach unten ein, bis die Ellbogen die Knie erreichen.', 'Halte unten kurz und richte dich langsam und kontrolliert bis in die Ausgangsposition auf.', 'Roll dich wieder genauso nach unten ein. Auf halbem Weg beginnst du, einen Ellbogen zum gegenüberliegenden Knie zu drehen.', 'Halte unten wieder kurz und richte dich langsam und kontrolliert bis in die Ausgangsposition auf.', 'Mach dieselbe Bewegung noch einmal, diesmal mit dem anderen Ellbogen zum gegenüberliegenden Knie.', 'Setz diese Abfolge bis zum Muskelversagen fort.']::text[]),
  ('Kneeling_Cable_Triceps_Extension', 'de', array['Stell eine Bank quer vor einen oberen Kabelzug.', 'Halte eine gerade Stange über dem Kopf, die Handflächen zeigen nach unten, die Hände sind etwa 6 inches auseinander.', 'Dreh der Maschine den Rücken zu und knie dich hin.', 'Leg den Kopf und die Rückseiten der Oberarme auf die Bank. Beuge die Ellbogen, sodass die Unterarme zum oberen Kabelzug zeigen. Das ist deine Ausgangsposition.', 'Atme aus und drück die Stange im Halbkreis von dir weg, bis die Ellbogen durchgestreckt und die Arme parallel zum Boden sind. Die Oberarme bleiben die ganze Zeit dicht am Kopf, die Ellbogen eng. Spann den Trizeps fest an und halte eine Sekunde.', 'Atme ein und geh langsam in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Kneeling_Forearm_Stretch', 'de', array['Knie dich auf eine Matte und setz die Handflächen flach auf, die Finger zeigen nach hinten zu deinen Knien.', 'Lehn dich langsam zurück, die Handflächen bleiben flach am Boden, bis du die Dehnung in Handgelenken und Unterarmen spürst. Halte 20-30 Sekunden.']::text[]),
  ('Kneeling_High_Pulley_Row', 'de', array['Nimm einen Kabelzug, dessen Rolle über Kopfhöhe sitzt, und wähle ein passendes Gewicht. Befestige ein Seil, knie dich a couple of feet entfernt hin und halte das Seil mit gestreckten Armen vor dich. Das ist deine Ausgangsposition.', 'Beginne, indem du die Ellbogen beugst und die Schultern ganz nach hinten ziehst. Zieh das Seil zur oberen Brust, die Ellbogen zeigen nach außen.', 'Halte kurz und geh dann langsam in die Ausgangsposition zurück.']::text[]),
  ('Kneeling_Hip_Flexor', 'de', array['Knie dich auf eine Matte. Stell den rechten Fuß nach vorn, sodass die Sohle flach am Boden steht, und streck das linke Bein nach hinten aus, der Fußrücken liegt am Boden.', 'Verlagere dein Gewicht nach vorn, bis du die Dehnung in der Hüfte spürst. Halte 15 Sekunden und wechsle dann die Seite.']::text[]),
  ('Kneeling_Jump_Squat', 'de', array['Knie dich auf den Boden, eine Langhantel liegt hinten auf deinen Schultern; du kannst die Übung auch nur mit dem Körpergewicht machen. In einem Power Rack lässt sich die Hantel leichter herausheben.', 'Schieb die Hüfte nach hinten, bis dein Gesäß die Füße berührt. Kopf und Brust bleiben oben.', 'Stoß die Hüfte explosiv nach oben, mit so viel Kraft, dass du mit beiden Füßen flach auf dem Boden landest.', 'Führ die Kniebeuge zu Ende: Drück dich über die Fersen ab und streck die Knie, bis du stehst.']::text[]),
  ('Kneeling_Single-Arm_High_Pulley_Row', 'de', array['Befestige einen Einzelgriff am oberen Kabelzug und wähle dein Gewicht.', 'Knie dich vor den Kabelturm und nimm den Griff mit einer Hand, der Arm ist gestreckt. Das ist deine Ausgangsposition.', 'Am Anfang zeigt deine Handfläche nach vorn. Beuge den Ellbogen und zieh das Schulterblatt nach hinten, um das Gewicht zum Oberkörper herunterzuziehen. Dreh dabei das Handgelenk, sodass die Handfläche am Ende der Bewegung zu dir zeigt.', 'Halte kurz und geh dann in die Ausgangsposition zurück.']::text[]),
  ('Kneeling_Squat', 'de', array['Stell die Stange im Power Rack auf die richtige Höhe. Knie dich hinter die Stange; eine Matte als Polster für die Knie kann helfen. Schieb dich unter die Stange und leg sie hinten auf die Schultern. Zieh die Schulterblätter zusammen, die Stange liegt fest am Rücken. Heb das Gewicht aus der Ablage.', 'Schau nach vorn und setz dich nach hinten ab, bis dein Po die Waden berührt.', 'Kehr die Bewegung um und richte den Oberkörper wieder auf.']::text[]),
  ('Landmine_180s', 'de', array['Steck ein Ende der Stange in eine Landmine oder klemm es sicher in eine Raumecke. Belade die Stange mit einem passenden Gewicht.', 'Heb die Stange vom Boden und bring sie mit beiden Händen auf Schulterhöhe, die Arme vor dir gestreckt. Stell dich breit hin. Das ist deine Ausgangsposition.', 'Dreh Rumpf und Hüfte und schwing das Gewicht ganz nach unten zu einer Seite. Die Arme bleiben während der gesamten Übung gestreckt.', 'Kehr die Bewegung um und schwing das Gewicht ganz zur anderen Seite.', 'Wechsle weiter die Seiten, bis der Satz fertig ist.']::text[]),
  ('Landmine_Linear_Jammer', 'de', array['Steck eine Stange in eine Landmine oder, wenn du keine hast, klemm sie sicher in eine Raumecke. Lade ein passendes Gewicht auf und setz den Griffaufsatz auf die Stange.', 'Heb die Stange vom Boden und bring die Griffe an deine Schultern. Das ist deine Ausgangsposition.', 'Geh aus einem athletischen Stand in die Kniebeuge: Beuge die Hüfte und schieb sie nach hinten. Die Arme bleiben gebeugt.', 'Kehr die Bewegung um: Streck Hüfte, Knie und Sprunggelenke kraftvoll und streck gleichzeitig die Ellbogen, bis die Arme gerade sind. Mach das explosiv und komm so kraftvoll wie möglich aus der Kniebeuge in die volle Streckung.', 'Geh in die Ausgangsposition zurück.']::text[]),
  ('Lateral_Bound', 'de', array['Geh in eine halbe Kniebeuge, um 90 Grad zur Bewegungsrichtung gedreht. Das ist deine Ausgangsposition.', 'Lass das vordere Bein eine Ausholbewegung nach innen machen, während du das Gewicht auf das äußere Bein verlagerst.', 'Drück dich sofort ab, streck dich und versuch, so weit wie möglich zur Seite zu springen.', 'Drück dich nach der Landung sofort in die Gegenrichtung ab und komm an deinen Startpunkt zurück.', 'Spring so mehrere Wiederholungen lang hin und her.']::text[]),
  ('Lateral_Box_Jump', 'de', array['Stell dich bequem hin, neben dir steht eine niedrige Box. Das ist deine Ausgangsposition.', 'Geh schnell in eine Viertelkniebeuge, um den Dehnreflex auszulösen, kehr sofort um und spring nach oben und zur Seite.', 'Zieh die Knie so hoch, dass deine Füße sicher über die Kante der Box kommen.', 'Lande in der Mitte der Box und fang den Aufprall mit den Beinen ab.', 'Spring vorsichtig auf der anderen Seite der Box herunter. Mach so mehrere Wiederholungen hin und her.']::text[]),
  ('Lateral_Cone_Hops', 'de', array['Stell mehrere Hütchen in einer Reihe auf, jeweils several feet auseinander.', 'Stell dich neben das erste Hütchen, um 90 Grad zur Bewegungsrichtung gedreht. Das ist deine Ausgangsposition.', 'Leite den Sprung ein, indem du kurz in die Knie gehst und so den Dehnreflex auslöst. Kehr sofort um, drück dich vom Boden ab und spring nach oben und seitlich über das Hütchen.', 'Fang die Landung mit den Beinen ab und federe direkt in den nächsten Sprung. Arbeite dich so die Hütchenreihe entlang.']::text[]),
  ('Lateral_Raise_-_With_Bands', 'de', array['Stell dich so auf ein Trainingsband, dass es bei lang hängenden Armen gerade Spannung bekommt. Fass die Griffe im Obergriff (Handflächen zu den Oberschenkeln), etwas enger als schulterbreit. Die Griffe liegen seitlich an deinen Oberschenkeln. Die Arme sind gestreckt, die Ellbogen leicht gebeugt, der Rücken ist gerade. Das ist deine Ausgangsposition.', 'Atme aus und heb die Griffe mit den seitlichen Schultern zur Seite an. Geh weiter, bis sie etwas über der Waagerechten sind. Tipp: Kipp die Hände beim Anheben leicht, als würdest du Wasser ausgießen, und lass die Arme gestreckt. Halte außerdem den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Griffe langsam in die Ausgangsposition ab und atme dabei ein.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Latissimus_Dorsi-SMR', 'de', array['Leg dich auf den Boden, eine Faszienrolle liegt seitlich unter deinem Rücken, direkt hinter der Achsel. Das ist deine Ausgangsposition.', 'Halte den Arm der bearbeiteten Seite hinter dir und seitlich von dir. Verlagere dein Gewicht auf den Latissimus, der Oberkörper bleibt vom Boden abgehoben. Halte 10-30 Sekunden und wechsle die Seite.']::text[]),
  ('Leg-Over_Floor_Press', 'de', array['Leg dich auf den Boden und halte eine Kettlebell am Griff auf deiner Brust. Leg das Bein der arbeitenden Seite über das andere Bein. Den freien Arm kannst du zur Stütze seitlich ausstrecken.', 'Drück die Kettlebell nach oben, bis der Arm durchgestreckt ist.', 'Senke das Gewicht, bis der Ellbogen den Boden berührt; die Kettlebell bleibt dabei über dem Ellbogen. Mach die gewünschte Anzahl an Wiederholungen.']::text[]),
  ('Leg-Up_Hamstring_Stretch', 'de', array['Leg dich flach auf den Rücken. Beuge ein Knie und stell diesen Fuß flach auf den Boden, damit deine Wirbelsäule stabil liegt.', 'Streck das andere Bein in die Luft. Wenn du verkürzt bist, bekommst du es nicht gerade, und das ist in Ordnung. Streck das Knie, bis die Sohle des angehobenen Fußes zur Decke zeigt oder so nah wie möglich herankommt.', 'Streck die Beine langsam so weit wie möglich und zieh dann das angehobene Bein zur Nase. Wechsle die Seite.']::text[]),
  ('Leg_Extensions', 'de', array['Für diese Übung brauchst du eine Beinstrecker-Maschine. Wähle dein Gewicht, setz dich mit den Beinen unter das Polster (Füße zeigen nach vorn) und halte dich an den seitlichen Griffen fest. Das ist deine Ausgangsposition. Tipp: Stell das Polster so ein, dass es auf dem Unterschenkel liegt, knapp über den Füßen. Ober- und Unterschenkel sollten einen 90-Grad-Winkel bilden. Ist der Winkel kleiner als 90 Grad, steht das Knie über den Zehen, und das belastet das Kniegelenk unnötig. Wenn die Maschine so gebaut ist, such dir eine andere oder hör beim Absenken auf, sobald du den 90-Grad-Winkel erreichst.', 'Atme aus und streck die Beine mit dem Quadrizeps so weit wie möglich. Der restliche Körper bleibt ruhig auf dem Sitz. Halte die angespannte Position eine Sekunde.', 'Atme ein und lass das Gewicht langsam in die Ausgangslage zurück. Geh dabei nicht über die 90-Grad-Grenze hinaus.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Leg_Lift', 'de', array['Stell dich aufrecht hin, die Füße nebeneinander und etwa schulterbreit. Halte dich an etwas Stabilem fest, zum Beispiel an den Seiten eines Squat Racks oder an einer Stuhllehne, um dich zu stützen und das Gleichgewicht zu halten.', 'Heb mit oder ohne Fußgelenkgewicht ein Bein nach hinten an, wie bei einem Beincurl im Stehen, das andere Bein bleibt gestreckt. Atme bei dieser Bewegung aus.', 'Atme ein und bring das angehobene Bein langsam zum Boden zurück.', 'Mach die empfohlene Anzahl an Wiederholungen.', 'Mach die Bewegung danach mit dem anderen Bein.']::text[]),
  ('Leg_Press', 'de', array['Setz dich in eine Beinpresse und stell die Füße direkt vor dir auf die Plattform, in mittlerem, schulterbreitem Stand. Hinweis: Der mittlere Stand trainiert die Beine insgesamt; du kannst auch eine der anderen Fußstellungen wählen.', 'Löse die Sicherungshebel, die die beladene Plattform halten, und drück die Plattform ganz nach oben, bis deine Beine vor dir vollständig gestreckt sind. Tipp: Drück die Knie nicht durch. Oberkörper und Beine sollten einen genauen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Atme ein und lass die Plattform langsam herunter, bis Ober- und Unterschenkel einen 90-Grad-Winkel bilden.', 'Atme aus und drück dich in die Ausgangsposition zurück, vor allem über die Fersen und mit der Kraft des Quadrizeps.', 'Mach die empfohlene Anzahl an Wiederholungen und verriegle die Sicherungen richtig, wenn du fertig bist. Die voll beladene Plattform darf nicht auf dich fallen.']::text[]),
  ('Leg_Pull-In', 'de', array['Leg dich mit gestreckten Beinen auf eine Trainingsmatte. Die Hände liegen mit den Handflächen nach unten neben dir oder unter dem Gesäß. Tipp: Die Hände neben dem Körper sind die bevorzugte Variante. Das ist deine Ausgangsposition.', 'Atme aus, beuge die Knie und zieh die Oberschenkel zur Körpermitte. Geh weiter, bis die Knie etwa auf Brusthöhe sind. Spann dabei den Bauch an und halte oben eine Sekunde. Tipp: Die Unterschenkel (Waden) bleiben während der ganzen Bewegung parallel zum Boden.', 'Atme ein und geh in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Leverage_Chest_Press', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen und stell den Sitz auf deine Größe ein. Zu Beginn der Bewegung sollten die Griffe auf Höhe der unteren oder mittleren Brustmuskeln sein.', 'Heb Brust und Kopf und zieh die Schulterblätter zusammen. Das ist deine Ausgangsposition.', 'Drück die Griffe nach vorn, indem du die Ellbogen streckst.', 'Halte vorn kurz und führ das Gewicht dann bis knapp über die Startposition zurück. Die Muskeln bleiben unter Spannung: Setz das Gewicht erst an den Anschlägen ab, wenn der Satz fertig ist.']::text[]),
  ('Leverage_Deadlift', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen. Stell dich genau zwischen die Griffe. Fass die unteren Griffe so, wie es für dich bequem ist, atme ein und senke die Hüfte. Schau nach vorn und halte die Brust oben. Das ist deine Ausgangsposition.', 'Führ das Gewicht in die Ausgangsposition zurück.']::text[]),
  ('Leverage_Decline_Chest_Press', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen und stell den Sitz auf deine Größe ein. Zu Beginn der Bewegung sollten die Griffe auf Höhe der unteren Brustmuskeln sein. Heb Brust und Kopf und zieh die Schulterblätter zusammen. Das ist deine Ausgangsposition.', 'Drück die Griffe nach vorn, indem du die Ellbogen streckst.', 'Halte vorn kurz und führ das Gewicht dann bis knapp über die Startposition zurück. Die Muskeln bleiben unter Spannung: Setz das Gewicht erst an den Anschlägen ab, wenn der Satz fertig ist.']::text[]),
  ('Leverage_High_Row', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen und stell die Sitzhöhe so ein, dass du die Griffe über dir gerade noch erreichst. Stell das Kniepolster so ein, dass es dich unten hält. Fass die Griffe im Obergriff. Das ist deine Ausgangsposition.', 'Zieh die Griffe zum Oberkörper, beuge dabei die Ellbogen und zieh die Schulterblätter zusammen.', 'Halte unten kurz und lass die Griffe dann langsam in die Ausgangsposition zurück.', 'Bei mehreren Wiederholungen setzt du das Gewicht nicht ganz an den Anschlägen ab, damit die arbeitenden Muskeln unter Spannung bleiben.']::text[]),
  ('Leverage_Incline_Chest_Press', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen und stell den Sitz auf deine Größe ein. Zu Beginn der Bewegung sollten die Griffe auf Höhe der oberen Brustmuskeln sein. Heb Brust und Kopf und zieh die Schulterblätter zusammen. Das ist deine Ausgangsposition.', 'Drück die Griffe nach vorn, indem du die Ellbogen streckst.', 'Halte vorn kurz und führ das Gewicht dann bis knapp über die Startposition zurück. Die Muskeln bleiben unter Spannung: Setz das Gewicht erst an den Anschlägen ab, wenn der Satz fertig ist.']::text[]),
  ('Leverage_Iso_Row', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen und stell die Sitzhöhe so ein, dass die Griffe auf Brusthöhe sind. Fass die Griffe im Neutralgriff oder im Obergriff. Das ist deine Ausgangsposition.', 'Zieh die Griffe zum Oberkörper, beuge dabei die Ellbogen und zieh die Schulterblätter zusammen.', 'Halte am Endpunkt kurz und lass die Griffe dann langsam in die Ausgangsposition zurück. Bei mehreren Wiederholungen setzt du das Gewicht nicht ganz an den Anschlägen ab, damit die arbeitenden Muskeln unter Spannung bleiben.']::text[]),
  ('Leverage_Shoulder_Press', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen und stell den Sitz auf deine Größe ein. Zu Beginn der Bewegung sollten die Griffe etwa auf Höhe der Schulteroberseite sein. Heb Brust und Kopf und fass die Griffe im Obergriff. Das ist deine Ausgangsposition.', 'Drück die Griffe nach oben, indem du die Ellbogen streckst.', 'Halte oben kurz und führ das Gewicht dann bis knapp über die Startposition zurück. Die Muskeln bleiben unter Spannung: Setz das Gewicht erst an den Anschlägen ab, wenn der Satz fertig ist.']::text[]),
  ('Leverage_Shrug', 'de', array['Lade ein passendes Gewicht auf die Aufnahmen. Stell dich genau zwischen die Griffe.', 'Fass die oberen Griffe so, wie es für dich bequem ist, atme ein und senke die Hüfte. Schau nach vorn und halte die Brust oben.', 'Drück die Fersen in den Boden und streck Hüfte und Knie, bis du stehst. Die Arme bleiben die ganze Zeit gestreckt, am Ende sind die Schultern hinten. Das ist deine Ausgangsposition.', 'Heb das Gewicht, indem du die Schultern zu den Ohren ziehst. Beweg dich dabei gerade auf und ab.', 'Halte oben kurz und senke das Gewicht dann in die Ausgangsposition.']::text[]),
  ('Linear_3-Part_Start_Technique', 'de', array['Mit dieser Übung lernst du, aus dem Stand so schnell wie möglich in den Sprint zu beschleunigen. Eine Linie als Startmarke ist hilfreich. Stell dich mit beiden Füßen auf die Linie. Setz den linken Fuß so, dass die Zehen neben dem rechten Knöchel sind. Stell dann den rechten Fuß 4-6 inches hinter den linken.', 'Setz die rechte Hand auf die Linie und bring dann die Nase nah an dein linkes Knie.', 'Geh in die Hocke und lehn dich nach vorn: Der Kopf ist tiefer als die Hüfte, das Gewicht liegt auf dem linken Bein. Das ist deine Ausgangsposition.', 'Heb die linke Hand nach hinten, bis der Arm parallel zum Boden ist und nach hinten zeigt. Starte explosiv, wenn du bereit bist.']::text[]),
  ('Linear_Acceleration_Wall_Drill', 'de', array['Lehn dich in etwa 45 Grad gegen eine Wand. Die Füße stehen zusammen, das Gesäß ist angespannt.', 'Zieh das rechte Knie schnell hoch, halte kurz und stoß den Fuß dann gerade nach unten in den Boden.', 'Wechsle das Bein: Zieh das andere Knie hoch und greif den Boden dann gerade nach unten an.', 'Wiederhole es noch einmal mit dem rechten Bein. Sobald der rechte Fuß aufsetzt, hämmerst du schnelle Schritte heraus, links und rechts im Wechsel, so schnell du kannst.']::text[]),
  ('Linear_Depth_Jump', 'de', array['Du brauchst zwei Boxen oder Bänke, die a few feet auseinanderstehen. Stell dich auf eine Box, mit Blick zur anderen Plattform.', 'Lass dich zum Start sanft auf den Boden zwischen den beiden Plattformen fallen und gib in Knien und Hüfte nach.', 'Kehr die Bewegung explosiv um: Streck Hüfte, Knie und Sprunggelenke und spring auf die andere Plattform.', 'Lande weich und fang den Aufprall mit den Beinen ab.']::text[]),
  ('Log_Lift', 'de', array['Stell dich hin, der Baumstamm liegt vor dir. Fass die Griffe und beginne, den Stamm umzusetzen. Solange du am Anfang des Umsetzens vorgebeugt bist, versuch, den Stamm so hoch wie möglich zu bekommen, und zieh ihn an die Brust. Streck Hüfte und Knie, um ihn hochzubringen und das Umsetzen abzuschließen.', 'Schieb den Kopf nach hinten und schau nach oben, sodass deine Brust eine Ablage für den Stamm bildet. Leite das Drücken mit einem kurzen Absenken ein: Beuge die Knie leicht und kehr die Bewegung um. Dieser Schwungdrücker erzeugt den Schwung, der den Stamm senkrecht in Bewegung bringt. Streck dann die Ellbogen und drück den Stamm über den Kopf. Für die Ausführung gibt es keine strengen Regeln, nimm also die Technik, mit der du am effizientesten bist. Schieb bei jeder Wiederholung den Kopf nach vorn durch, während der Stamm nach oben geht, und schau geradeaus.', 'Mach so viele Wiederholungen wie möglich. Versuch, den Stamm auf dem Weg zurück zum Boden zu kontrollieren.']::text[]),
  ('London_Bridges', 'de', array['Befestige ein Kletterseil an einem hohen Balken oder Querträger. Stell darunter sicher, dass die Stange der Smith-Maschine mit den Sicherungen arretiert ist und sich nicht bewegen kann. Stattdessen geht auch eine standfeste Box.', 'Stell dich auf die Stange und halte mit dem Seil das Gleichgewicht. Das ist deine Ausgangsposition.', 'Lehn dich mit geradem Körper zurück und lass dich langsam herunter, Hand unter Hand am Seil. Geh weiter, bis du senkrecht zum Boden bist.', 'Kehr die Bewegung mit geradem Körper um und hangle dich Hand über Hand in die Ausgangsposition zurück.']::text[]),
  ('Looking_At_Ceiling', 'de', array['Knie dich auf den Boden und fass mit beiden Händen deine Fersen.', 'Schieb das Gesäß nach oben und vorn und nimm den Kopf zurück, um zur Decke zu schauen, sodass dein Rücken ins Hohlkreuz geht.']::text[]),
  ('Low_Cable_Crossover', 'de', array['Zur Vorbereitung stellst du die Rollen auf die untere Position, wählst den Widerstand und nimmst in jede Hand einen Griff.', 'Mach einen Schritt nach vorn, damit die Kabel Spannung bekommen. Die Handflächen zeigen nach vorn, die Hände sind unterhalb der Taille, die Arme gestreckt. Das ist deine Ausgangsposition.', 'Führ die Hände mit leicht gebeugten Armen nach oben und zur Körpermitte. Sie sollten sich vor der Brust treffen, die Handflächen zeigen nach oben.', 'Halte kurz und bring die Arme dann in die Ausgangsposition zurück.']::text[]),
  ('Low_Cable_Triceps_Extension', 'de', array['Wähle dein Gewicht und leg dich mit dem Gesicht nach oben auf die Bank einer Rudermaschine, an der ein Seil befestigt ist. Dein Kopf zeigt zum Seil.', 'Fass die Seilenden von außen, die Handflächen zeigen zueinander (Neutralgriff).', 'Beuge die Ellbogen auf 90 Grad und stell die Oberarme senkrecht (90 Grad) zum Oberkörper. Tipp: Halte die Ellbogen eng. Die Oberarme zeigen zur Decke, die Unterarme zur Rolle über deinem Kopf. Das ist deine Ausgangsposition.', 'Atme aus und streck die Unterarme, bis sie gerade und senkrecht sind. Oberarme und Ellbogen bleiben die ganze Bewegung über ruhig, nur die Unterarme arbeiten. Spann den Trizeps eine Sekunde fest an.', 'Atme ein und geh langsam in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Low_Pulley_Row_To_Neck', 'de', array['Setz dich an einen tiefen Ruderzug mit Seilgriff.', 'Fass die Seilenden mit den Handflächen nach unten. Sitz mit geradem Rücken und leicht gebeugten Knien. Tipp: Der Rücken ist fast ganz senkrecht, die Arme sind vor dir vollständig gestreckt. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig, heb die Ellbogen an und beuge sie, während du das Seil beim Ausatmen zum Hals ziehst. Die Oberarme bleiben die ganze Zeit parallel zum Boden. Tipp: Zieh weiter, bis die Hände fast neben den Ohren sind und die Ellbogen nach außen zeigen, weg vom Körper. Am Ende sind die Unterarme nicht parallel zum Boden, sondern zeigen leicht nach oben.', 'Halte die Spannung etwa eine Sekunde und geh dann beim Einatmen langsam in die Ausgangsposition zurück. Tipp: Auch hier gilt, dass sich der Oberkörper zu keinem Zeitpunkt bewegt.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Lower_Back-SMR', 'de', array['Setz dich hin und leg eine Faszienrolle unter den unteren Rücken. Kreuz die Arme vor dir und schieb die Schultern nach vorn. Das ist deine Ausgangsposition.', 'Heb die Hüfte vom Boden und lehn dich zurück, sodass dein Gewicht auf dem unteren Rücken liegt. Verlagere es dann leicht zu einer Seite: weg von der Wirbelsäule, auf die Muskeln daneben. Roll über den unteren Rücken und bleib auf verspannten Stellen 10-30 Sekunden. Wiederhole das auf der anderen Seite.']::text[]),
  ('Lower_Back_Curl', 'de', array['Leg dich auf den Bauch, die Arme seitlich ausgestreckt. Das ist deine Ausgangsposition.', 'Streck die Wirbelsäule mit der Muskulatur des unteren Rückens und heb die Brust vom Boden ab. Drück dich nicht mit den Armen hoch. Der Kopf bleibt während der Bewegung oben. Mach 10-20 Wiederholungen.']::text[]),
  ('Lunge_Pass_Through', 'de', array['Stell dich mit aufrechtem Oberkörper hin, eine Kettlebell in der rechten Hand. Das ist deine Ausgangsposition.', 'Mach mit dem linken Fuß einen Schritt nach vorn. Beuge Hüfte und Knie und senke den Oberkörper ab, er bleibt dabei aufrecht. Geh herunter, bis das hintere Knie fast den Boden berührt.', 'Gib die Kettlebell im Ausfallschritt unter dem vorderen Bein in die andere Hand.', 'Drück dich über die Ferse ab und komm in die Ausgangsposition zurück.', 'Mach die empfohlene Anzahl an Wiederholungen und wechsle dabei die Beine ab.']::text[]),
  ('Lunge_Sprint', 'de', array['Stell die Stange einer Smith-Maschine auf eine passende Höhe. Geh unter die Stange und leg sie hinten auf die Schultern. Heb sie aus der Halterung und geh in den Ausfallschritt, ein Fuß vorn, einer hinten. Das ist deine Ausgangsposition.', 'Beuge die Knie und senke die Hüfte, bis das hintere Knie fast am Boden ist.', 'Kehr am tiefsten Punkt sofort um. Drück dich explosiv über die Ferse des vorderen Fußes ab, der hintere Fuß gibt nur leichten Druck. Spring hoch und wechsle die Beinstellung.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Lying_Bent_Leg_Groin', 'de', array['Leg dich auf den Rücken, die Knie gebeugt, die Fußsohlen aneinandergedrückt. Lass deinen Partner deine Knie halten. Das ist deine Ausgangsposition.', 'Versuch, die Knie zusammenzudrücken, während dein Partner jede Bewegung verhindert.', 'Entspann nach 10-20 Sekunden die Muskeln, während dein Partner deine Knie sanft zum Boden drückt. Sag deinem Helfer Bescheid, wenn die Dehnung reicht, damit es nicht zu Verletzungen oder Überdehnung kommt.']::text[]),
  ('Lying_Cable_Curl', 'de', array['Befestige eine gerade Stange oder eine SZ-Stange an der unteren Rolle des Kabelzugs. Fasse sie mit beiden Händen schulterbreit im Untergriff, die Handflächen zeigen nach oben.', 'Lege eine Matte vor den Gewichtsblock und lege dich mit dem Rücken darauf. Die Beine sind gestreckt, die Fußsohlen stehen flach am Rahmen des Geräts.', 'Strecke die Arme aus, halte die Ellbogen nah am Körper und beuge die Arme ganz leicht. Das ist deine Ausgangsposition.', 'Atme aus und ziehe die Stange langsam zur Brust, dabei spannst du den Bizeps an. Die Oberarme bewegen sich nicht, die Ellbogen bleiben am Körper.', 'Halte die Spannung oben eine Sekunde und gehe dann langsam in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Cambered_Barbell_Row', 'de', array['Lege eine gekröpfte Stange unter eine Trainingsbank.', 'Lege dich bäuchlings auf die Bank. Fasse die Stange weiter als schulterbreit im Obergriff, die Handflächen zeigen nach unten. Das ist deine Ausgangsposition.', 'Atme aus und ziehe die Stange nach oben, die Ellbogen bleiben nah am Körper. Ziehe zur Brust, wenn du den oberen mittleren Rücken trainieren willst, oder zum Bauch, wenn es dir um den Latissimus geht.', 'Halte oben eine Sekunde, atme dann ein und senke die Stange langsam in die Ausgangsposition.']::text[]),
  ('Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'de', array['Stelle eine Flachbank vor einen hohen Kabelzug oder eine Latzugmaschine.', 'Fasse die gerade Stange etwa schulterbreit im Untergriff, die Handflächen zeigen nach oben.', 'Lege dich auf den Rücken, der Kopf liegt über dem Ende der Bank.', 'Strecke die Arme gerade über den Schultern nach oben. Arme und Oberkörper bilden einen Winkel von 90 Grad, die Ellbogen zeigen nach innen. Das ist deine Ausgangsposition.', 'Atme aus und ziehe die Stange im Halbkreis nach unten, bis sie dein Kinn berührt. Spanne den Bizeps in dieser Endposition eine Sekunde lang an. Tipp: Bei dieser Bewegung arbeiten nur die Unterarme. Die Oberarme bewegen sich zu keinem Zeitpunkt, sie bleiben die ganze Zeit senkrecht.', 'Gehe langsam in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'de', array['Fasse eine Langhantel oder eine SZ-Stange im Obergriff (Handflächen zeigen nach vorn) und lege dich mit dem Rücken auf eine Flachbank, den Kopf nah am Ende der Bank. Tipp: Eine Langhantel fasst du schulterbreit, eine SZ-Stange an den inneren Griffstellen.', 'Strecke die Arme vor dir aus. Führe die Stange dann mit weiter gestreckten Armen langsam im Halbkreis nach hinten, bis sie über deinem Kopf ist. Die Arme sind jetzt über Kopf und parallel zum Boden. Das ist deine Ausgangsposition. Tipp: Die Ellbogen bleiben die ganze Zeit innen.', 'Atme ein und senke die Stange, indem du die Ellbogen beugst. Die Oberarme bewegen sich nicht. Senke weiter, bis die Unterarme senkrecht zum Boden stehen.', 'Atme aus und drücke die Stange im Halbkreis wieder in die Ausgangsposition, bis auch die Unterarme parallel zum Boden sind. Spanne den Trizeps oben eine Sekunde lang kräftig an. Tipp: Auch hier arbeiten nur die Unterarme. Die Oberarme bleiben die ganze Zeit ruhig.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'de', array['Fasse eine Langhantel oder eine SZ-Stange im Obergriff (Handflächen zeigen nach vorn) und lege dich mit dem Rücken auf eine Flachbank, der Kopf ragt über das Ende der Bank hinaus. Tipp: Eine Langhantel fasst du schulterbreit, eine SZ-Stange an den inneren Griffstellen.', 'Strecke die Arme aus und halte die Stange über der Brust. Die Arme stehen senkrecht zum Oberkörper, also im Winkel von 90 Grad. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange im Halbkreis, indem du die Ellbogen beugst. Die Oberarme bewegen sich nicht, die Ellbogen bleiben innen. Senke weiter, bis die Stange dein Kinn leicht berührt.', 'Atme aus und drücke die Stange im Halbkreis wieder in die Ausgangsposition. Spanne den Trizeps oben eine Sekunde lang kräftig an. Tipp: Auch hier arbeiten nur die Unterarme. Die Oberarme bleiben die ganze Zeit ruhig.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Crossover', 'de', array['Lege dich auf den Rücken und strecke die Beine aus.', 'Beuge ein Knie und führe das Bein quer über den Körper, das Knie soll möglichst den Boden berühren. Dein Partner kniet neben dir, drückt mit einer Hand deine Schulter nach unten und führt mit der anderen das überkreuzte Bein. Das ist deine Ausgangsposition.', 'Versuche, das gebeugte Knie vom Boden zu heben, während dein Partner jede tatsächliche Bewegung verhindert.', 'Entspanne das Bein nach 10-20 Sekunden und lass deinen Partner das Knie sanft Richtung Boden drücken. Wiederhole das Ganze auf der anderen Seite.']::text[]),
  ('Lying_Dumbbell_Tricep_Extension', 'de', array['Lege dich auf eine Flachbank und halte zwei Kurzhanteln gerade über dir. Die Arme sind ganz gestreckt und stehen im Winkel von 90 Grad zu Oberkörper und Boden. Die Handflächen zeigen zueinander, die Ellbogen sind eng angelegt. Das ist die Ausgangsposition.', 'Atme ein und senke die Kurzhanteln langsam, bis sie neben deinen Ohren sind. Die Oberarme bewegen sich nicht, die Ellbogen bleiben innen.', 'Atme von dort aus und hebe die Kurzhanteln mit dem Trizeps wieder in die Ausgangsposition. Auch jetzt bleiben die Ellbogen innen und die Oberarme ruhig.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Face_Down_Plate_Neck_Resistance', 'de', array['Lege dich bäuchlings und ganz gestreckt auf eine Flachbank und halte eine Gewichtsscheibe hinter dem Kopf. Tipp: Lege dich so hin, dass die Schultern knapp über das Ende der Bank hinausragen; dann liegen obere Brust, Nacken und Gesicht frei. Das ist deine Ausgangsposition.', 'Halte die Scheibe sicher am Hinterkopf. Atme ein und senke den Kopf langsam, so als würdest du "ja" nicken.', 'Atme aus und hebe den Kopf im Halbkreis wieder in die Ausgangsposition. Halte die Spannung eine Sekunde.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Face_Up_Plate_Neck_Resistance', 'de', array['Lege dich rücklings und ganz gestreckt auf eine Flachbank und halte eine Gewichtsscheibe auf der Stirn. Tipp: Lege dich so hin, dass die Schultern knapp über das Ende der Bank hinausragen; dann liegen Trapez, Nacken und Kopf frei. Das ist deine Ausgangsposition.', 'Halte die Scheibe sicher auf der Stirn. Atme ein und lass den Kopf langsam im Halbkreis nach hinten sinken.', 'Atme aus und hebe den Kopf im Halbkreis wieder in die Ausgangsposition. Halte die Spannung eine Sekunde.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Glute', 'de', array['Lege dich auf den Rücken. Dein Partner kniet neben dir.', 'Beuge ein Bein in der Hüfte und hebe es vom Boden. Drehe das Bein, bis der Fuß über der gegenüberliegenden Hüfte ist und der Unterschenkel quer zum Körper steht. Dein Partner hält Knie und Knöchel in dieser Stellung fest. Das ist deine Ausgangsposition.', 'Versuche, das Bein zu deinem Partner hin zu drücken. Er verhindert, dass es sich tatsächlich bewegt.', 'Entspanne dich nach 10-20 Sekunden ganz und lass deinen Partner Knöchel und Knie sanft Richtung Brust schieben. Sage deinem Helfer, wann die Dehnung reicht, damit du dich nicht verletzt oder überdehnst.']::text[]),
  ('Lying_Hamstring', 'de', array['Lege dich auf den Rücken und strecke die Beine aus. Dein Partner kniet neben dir. Hebe ein Bein Richtung Decke und lass deinen Partner den Knöchel halten. Wenn nötig, stützt er dein Bein mit der Schulter ab. Das ist deine Ausgangsposition.', 'Dein Partner hält das Bein fest. Versuche, das Knie zu beugen, und spanne die Beinbeuger 10-20 Sekunden lang an.', 'Entspanne dann das Bein und lass deinen Partner es sanft Richtung Kopf schieben. Sage deinem Helfer, wann die Dehnung reicht, damit du dich nicht verletzt oder überdehnst. Wechsle danach die Seite.']::text[]),
  ('Lying_High_Bench_Barbell_Curl', 'de', array['Lege dich bäuchlings auf eine hohe Flachbank und halte eine Langhantel im Untergriff (Handflächen zeigen nach oben). Tipp: Eine Langhantel fasst du schulterbreit, eine SZ-Stange an den inneren Griffstellen. Lege dich so hin, dass die obere Brust über dem Ende der Bank ist und die Stange vor dir hängt, die Arme gestreckt und senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Atme aus, spanne den Bizeps an und führe das Gewicht im Halbkreis nach oben. Die Ellbogen bleiben innen, die Oberarme bewegen sich nicht. Halte oben eine Sekunde.', 'Atme ein und gehe langsam in die Ausgangsposition zurück. Tipp: Behalte das Gewicht die ganze Zeit voll unter Kontrolle und hole keinen Schwung. Denke daran, dass bei der ganzen Übung nur die Unterarme arbeiten.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Leg_Curls', 'de', array['Stelle den Hebel der Beinbeugermaschine auf deine Größe ein. Lege dich bäuchlings auf das Gerät, das Polster des Hebels liegt hinten an den Beinen, ein paar Inches unterhalb der Waden. Tipp: Nimm möglichst ein abgewinkeltes Gerät statt eines flachen, weil die abgewinkelte Lage die Beinbeuger besser anspricht.', 'Der Oberkörper liegt flach auf der Bank. Strecke die Beine ganz aus und fasse die seitlichen Griffe des Geräts. Die Zehen zeigen gerade. Das ist deine Ausgangsposition.', 'Atme aus und beuge die Beine so weit nach oben, wie es geht. Die Oberschenkel bleiben auf dem Polster. Halte eine Sekunde, sobald die Muskeln ganz angespannt sind.', 'Atme ein und führe die Beine in die Anfangsstellung zurück. Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Machine_Squat', 'de', array['Stelle die Beinmaschine auf eine Höhe ein, bei der du mit gebeugten Knien hineinkommst und die Oberschenkel etwas tiefer als parallel sind.', 'Wähle das Gewicht und lege dich dann rücklings in die Maschine, die Knie gebeugt und die Oberschenkel etwas tiefer als parallel zur Plattform. Die Knie dürfen nicht über die Zehen hinausragen. Beinbeuger und Waden bilden einen Winkel von etwas weniger als 90 Grad, weil du etwas unterhalb der Parallelen beginnst. Rücken und Kopf liegen an der Maschine an, die Schultern drücken unter die Schulterpolster.', 'Lege die Hände an die Griffe. Stelle die Füße schulterbreit auf, die Fußspitzen leicht nach außen. Das ist deine Ausgangsposition.', 'Atme aus, drücke über die Fußballen und strecke den ganzen Körper, dabei spannst du den Quadrizeps an. Halte diese Endposition eine Sekunde. Tipp: Weil du unterhalb der Parallelen beginnst, darfst du dir mit den Händen auf den Oberschenkeln nach oben helfen, aber nur bei der ersten Wiederholung.', 'Atme ein und gehe langsam in die Hocke. Gehe nicht ganz bis zur Ausgangsposition hinunter, sondern stoppe, wenn die Oberschenkel parallel zur Plattform sind. Beinbeuger und Waden bilden dann einen Winkel von 90 Grad.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_One-Arm_Lateral_Raise', 'de', array['Nimm eine Kurzhantel in eine Hand und lege dich mit der Brust auf eine Flachbank. Mit der freien Hand kannst du dich für mehr Halt an einem Bein der Bank festhalten.', 'Drehe die Hand mit der Kurzhantel in die neutrale Stellung, die Handfläche zeigt zum Körper. Der Arm ist gestreckt, der Ellbogen leicht gebeugt. Das ist deine Ausgangsposition.', 'Atme aus und hebe den Arm mit der Kurzhantel zur Seite, bis der Ellbogen auf Schulterhöhe ist und der Arm etwa parallel zum Boden steht. Tipp: Der Arm bleibt bei der ganzen Bewegung gestreckt und im rechten Winkel zum Oberkörper. Halte außerdem oben eine Sekunde die Spannung.', 'Atme ein und senke die Kurzhantel langsam in die Ausgangsposition.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Prone_Quadriceps', 'de', array['Lege dich bäuchlings auf den Boden. Dein Partner kniet neben dir. Beuge ein Knie und hebe das Bein vom Boden, der Fuß soll möglichst das Gesäß berühren. Dein Partner hält Knie und Knöchel. Das ist deine Ausgangsposition.', 'Versuche, das Knie zu strecken, während dein Partner jede tatsächliche Bewegung verhindert.', 'Entspanne die Muskeln nach 10-20 Sekunden und lass deinen Partner den Fuß sanft Richtung Gesäß schieben. So werden Quadrizeps und Hüftbeuger weiter gedehnt.', 'Wechsle nach 10-20 Sekunden die Seite.']::text[]),
  ('Lying_Rear_Delt_Raise', 'de', array['Nimm in jede Hand eine Kurzhantel und lege dich mit der Brust auf eine Flachbank.', 'Drehe die Hände in die neutrale Stellung, die Handflächen zeigen zum Körper. Die Arme sind gestreckt, die Ellbogen leicht gebeugt. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Arme zur Seite, bis die Ellbogen auf Schulterhöhe sind und die Arme etwa parallel zum Boden stehen. Tipp: Die Arme bleiben bei der ganzen Bewegung gestreckt und im rechten Winkel zum Oberkörper. Halte außerdem oben eine Sekunde die Spannung.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mache die empfohlene Zahl an Wiederholungen und wechsle dann zum anderen Arm.']::text[]),
  ('Lying_Supine_Dumbbell_Curl', 'de', array['Lege dich rücklings auf eine Flachbank, in jeder Hand eine Kurzhantel, die auf den Oberschenkeln liegt.', 'Führe die Kurzhanteln neben den Körper. Die Arme sind gestreckt, die Handflächen zeigen zu den Oberschenkeln (neutraler Griff).', 'Lass die Arme langsam so weit Richtung Boden sinken, wie es geht. Sie bleiben nah am Oberkörper, die Ellbogen innen, gestreckt mit nur leicht gebeugten Ellbogen. Wenn es nicht tiefer geht, fixiere die Oberarme in dieser Stellung. Das ist deine Ausgangsposition.', 'Atme aus und beuge die Arme langsam, dabei drehst du die Handgelenke, bis die Handflächen nach oben zeigen. Beuge weiter, bis der Bizeps ganz angespannt ist, und spanne oben eine Sekunde lang kräftig an. Tipp: Nur die Unterarme arbeiten. Die Oberarme bleiben ruhig und die Ellbogen innen, die ganze Bewegung über.', 'Gehe sehr langsam in die Ausgangsposition zurück.']::text[]),
  ('Lying_T-Bar_Row', 'de', array['Belade die T-Bar-Rudermaschine mit dem gewünschten Gewicht. Stelle die Beinhöhe so ein, dass deine obere Brust am oberen Rand des Polsters liegt. Tipp: Bei manchen Geräten kannst du dich nur auf die Stufe stellen, bei der die obere Brust am oberen Rand des Polsters ist.', 'Lege dich bäuchlings auf das Polster und fasse die Griffe. Handflächen nach unten, nach oben oder zueinander: Das hängt davon ab, welchen Teil des Rückens du betonen willst.', 'Hebe die Stange aus der Ablage und strecke die Arme vor dir aus. Das ist deine Ausgangsposition.', 'Atme aus, ziehe das Gewicht langsam nach oben und spanne oben den Rücken an. Tipp: Die Oberarme bleiben bei der ganzen Bewegung so nah am Oberkörper wie möglich, so arbeitet die Rückenmuskulatur besser. Hebe außerdem den Körper nie vom Polster ab und ziehe das Gewicht nicht mit dem Bizeps hoch.', 'Halte die Spannung oben eine Sekunde, atme dann ein und gehe langsam in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Lying_Triceps_Press', 'de', array['Lege dich auf eine Flachbank, die Füße stehen auf dem Boden. Hinter deinem Kopf liegt eine SZ-Stange (am besten) oder eine gerade Stange auf dem Boden.', 'Greife nach hinten und fasse die Stange mittelweit im Obergriff. Hebe sie über dich, bis die Arme gestreckt sind. Tipp: Die Arme stehen senkrecht zu Oberkörper und Boden, die Ellbogen sind eng angelegt. Das ist die Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis sie deine Stirn leicht berührt. Oberarme und Ellbogen bewegen sich nicht.', 'Atme von dort aus und hebe die Stange mit dem Trizeps wieder in die Ausgangsposition.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Machine_Bench_Press', 'de', array['Setze dich in die Brustpresse und wähle das Gewicht.', 'Tritt auf den Fußhebel des Geräts. Er bringt die Griffe nach vorn, sodass du sie fassen und die Arme ganz strecken kannst.', 'Fasse die Griffe mit den Handflächen nach unten. Hebe die Ellbogen, bis die Oberarme seitlich vom Oberkörper parallel zum Boden sind. Tipp: Weil du die Griffe hältst, zeigen die Unterarme nach vorn. Sind die Griffe vorn und die Arme gestreckt, bist du in der Ausgangsposition.', 'Atme ein und lass die Griffe zu dir zurückkommen.', 'Atme aus und drücke die Griffe von dir weg, dabei spannst du die Brust an. Halte die Spannung eine Sekunde und gehe dann in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.', 'Tritt am Ende wieder auf den Fußhebel und führe die Griffe langsam an ihren Platz zurück.']::text[]),
  ('Machine_Bicep_Curl', 'de', array['Stelle den Sitz auf die passende Höhe ein und wähle dein Gewicht. Lege die Oberarme an die Polster und fasse die Griffe. Das ist deine Ausgangsposition.', 'Beuge die Ellbogen und ziehe die Unterarme zu den Oberarmen.', 'Halte oben kurz inne und senke das Gewicht dann langsam in die Ausgangsposition.', 'Setze das Gewicht erst nach dem letzten Satzdurchgang ganz auf den Anschlägen ab. So bleiben die arbeitenden Muskeln unter Spannung.']::text[]),
  ('Machine_Preacher_Curls', 'de', array['Setze dich an die Scottcurl-Maschine und wähle das Gewicht.', 'Lege die Rückseite der Oberarme (den Trizeps) auf das Polster und fasse die Griffe im Untergriff, die Handflächen zeigen nach oben. Tipp: Halte die Ellbogen innen, wenn du die Arme auf das Polster legst. Das ist deine Ausgangsposition.', 'Atme aus, spanne den Bizeps an und hebe die Griffe. Halte die Spannung oben eine Sekunde. Tipp: Nur die Unterarme arbeiten. Die Oberarme bleiben die ganze Zeit ruhig auf dem Polster.', 'Atme ein und senke die Griffe langsam in die Ausgangsposition.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Machine_Shoulder_Military_Press', 'de', array['Setze dich in die Schulterpresse und wähle das Gewicht.', 'Fasse die Griffe seitlich neben dir. Die Ellbogen sind gebeugt und auf einer Linie mit dem Oberkörper. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Griffe nach oben, bis die Arme ganz gestreckt sind. Halte die Spannung oben eine Sekunde.', 'Atme ein und senke die Griffe langsam in die Ausgangsposition.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Machine_Triceps_Extension', 'de', array['Stelle den Sitz auf die passende Höhe ein und wähle dein Gewicht. Lege die Oberarme an die Polster und fasse die Griffe. Das ist deine Ausgangsposition.', 'Strecke die Ellbogen und bewege die Unterarme von den Oberarmen weg.', 'Halte am Ende der Bewegung kurz inne und lass das Gewicht dann langsam in die Ausgangsposition zurück.', 'Setze das Gewicht erst nach dem letzten Satzdurchgang ganz auf den Anschlägen ab. So bleiben die arbeitenden Muskeln unter Spannung.']::text[]),
  ('Medicine_Ball_Chest_Pass', 'de', array['Für diese Übung brauchst du einen Partner. Hast du keinen, wirfst du gegen eine Wand.', 'Stelle dich deinem Partner gegenüber und halte den Medizinball mit beiden Händen vor dem Oberkörper.', 'Ziehe den Ball zur Brust, kehre die Bewegung dann um und strecke die Ellbogen zum Wurf. Für den Einsatz im Sport kannst du beim Werfen einen Schritt machen.', 'Dein Partner fängt den Ball und wirft ihn zurück.', 'Fange ihn mit beiden Händen auf Brusthöhe.']::text[]),
  ('Medicine_Ball_Full_Twist', 'de', array['Du brauchst einen Medizinball und einen Partner. Stellt euch Rücken an Rücken auf, mit 2-3 Fuß Abstand. Das ist deine Ausgangsposition.', 'Halte den Ball vor dem Rumpf. Öffne die Hüfte und drehe die Schultern, im selben Moment wie dein Partner.', 'Für die volle Drehung dreht ihr euch beide in dieselbe Richtung, zum Beispiel gegen den Uhrzeigersinn.', 'Gib den Ball an deinen Partner weiter. Dann dreht ihr euch beide in die Gegenrichtung und wiederholt den Ablauf.']::text[]),
  ('Medicine_Ball_Scoop_Throw', 'de', array['Gehe mit einem Medizinball in den Händen in die halbe Hocke. Lass die Arme hängen, sodass der Ball nah an den Füßen ist.', 'Schiebe die Hüfte kraftvoll nach vorn, strecke die Beine und springe ab.', 'Schwinge dabei die gestreckten Arme nach oben und über den Kopf und lass den Ball am höchsten Punkt los. Ziel ist, den Ball so weit wie möglich hinter dich zu werfen.']::text[]),
  ('Middle_Back_Shrug', 'de', array['Lege dich bäuchlings auf eine Schrägbank, in jeder Hand eine Kurzhantel. Die Arme hängen ganz gestreckt nach unten und zeigen zum Boden. Die Handflächen zeigen zueinander. Das ist deine Ausgangsposition.', 'Atme aus, ziehe die Schulterblätter zusammen und halte eine volle Sekunde. Tipp: Die Bewegung ist das Gegenteil einer Umarmung, oder so, als würdest du Seitheben für die hintere Schulter ohne Arme machen.', 'Atme ein und kehre in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Middle_Back_Stretch', 'de', array['Stelle dich schulterbreit hin und stütze die Hände in die Hüften.', 'Drehe dich in der Taille, bis du eine Dehnung spürst. Halte sie 10 bis 15 Sekunden und drehe dich dann zur anderen Seite.']::text[]),
  ('Mixed_Grip_Chin', 'de', array['Fasse eine Klimmzugstange etwa 1 Inch weiter als schulterbreit. Eine Handfläche zeigt nach vorn, die andere zu dir. Das ist deine Ausgangsposition.', 'Atme aus und beginne, dich hochzuziehen. Tipp: Auf der Seite, auf der die Handfläche nach oben zeigt, konzentrierst du dich darauf, mit der Rückenmuskulatur zu arbeiten, und hältst den Ellbogen nah am Oberkörper. Auf der Seite, auf der die Handfläche nach vorn zeigt, steht der Ellbogen vom Oberkörper ab, bleibt aber auf einer Linie mit ihm; dort konzentrierst du dich darauf, den Körper mit dem Latissimus hochzuziehen.', 'Halte oben eine Sekunde, atme dann ein und lass dich langsam herunter.', 'Mache die empfohlene Zahl an Wiederholungen.', 'Wechsle im nächsten Satz den Griff. Zeigte die rechte Handfläche zu dir und die linke nach vorn, dann zeigt jetzt die rechte nach vorn und die linke zu dir.']::text[]),
  ('Monster_Walk', 'de', array['Lege ein Band um beide Knöchel und ein zweites um beide Knie. Die Bänder sollen straff sein, wenn die Füße schulterbreit stehen.', 'Gehe zuerst in kurzen Schritten vorwärts, linker und rechter Fuß im Wechsel.', 'Mache nach einigen Schritten das Gegenteil und gehe rückwärts zum Startpunkt.']::text[]),
  ('Mountain_Climbers', 'de', array['Beginne in der Liegestützposition, das Gewicht ruht auf Händen und Zehen. Beuge Knie und Hüfte eines Beins und ziehe es nach vorn, bis das Knie etwa unter der Hüfte ist. Das ist deine Ausgangsposition.', 'Wechsle die Beine explosiv: Strecke das gebeugte Bein nach hinten, bis es gerade ist und auf den Zehen steht, und ziehe den anderen Fuß mit gebeugter Hüfte und gebeugtem Knie nach vorn. Wechsle so 20-30 Sekunden lang ab.']::text[]),
  ('Moving_Claw_Series', 'de', array['Diese Übung bereitet deine Lauftechnik auf bessere Sprints vor. Beuge beim Laufen das Knie und versuche, mit der Ferse ans Gesäß zu kommen, während sich die Hüfte streckt.', 'Spanne den Quadrizeps wieder vor, wenn das Bein nach vorn schwingt, und greife mit dem nächsten Schritt den Boden an.', 'Blocke beim Laufen mit den Armen und stoße sie in einer schnellen 1-2-Bewegung durch.']::text[]),
  ('Muscle_Snatch', 'de', array['Halte eine beladene Langhantel im weiten Griff auf Höhe der Oberschenkelmitte. Die Füße stehen direkt unter der Hüfte, so weit nach außen gedreht wie nötig. Senke die Hüfte, die Brust bleibt oben, der Blick geht nach vorn. Die Schultern sind knapp vor der Stange. Das ist die Ausgangsposition.', 'Beginne den Zug, indem du über den vorderen Teil der Fersen drückst und die Stange hebst. Gehe in den zweiten Zug über: Strecke Hüfte, Knie und Sprunggelenke und treibe die Stange so schnell wie möglich nach oben. Die Stange bleibt nah am Körper.', 'Hebe die Stange weiter bis über den Kopf, ohne die Knie noch einmal zu beugen.']::text[]),
  ('Muscle_Up', 'de', array['Fasse die Ringe im falschen Griff: Der Handballen liegt oben auf dem Ring. Beginne einen Klimmzug, indem du die Ellbogen beugst und seitlich nach unten ziehst.', 'Bist du oben im Klimmzug angekommen, ziehst du die Ringe zu den Achseln und rollst die Schultern nach vorn, sodass die Ellbogen gerade nach hinten wandern. Aus dieser Stellung kannst du in den Dip-Teil der Bewegung übergehen.', 'Bleibe kontrolliert und stabil und strecke die Ellbogen, um die Bewegung abzuschließen.', 'Sei vorsichtig, wenn du dich zum Boden herunterlässt.']::text[]),
  ('Narrow_Stance_Hack_Squats', 'de', array['Lehne den Rücken an das Rückenpolster der Maschine und schiebe die Schultern unter die Schulterpolster.', 'Stelle die Füße eng auf die Plattform, enger als schulterbreit, die Fußspitzen leicht nach außen. Der Abstand der Füße beträgt etwa 3 Inches oder weniger. Tipp: Halte den Kopf die ganze Zeit oben und den Rücken immer am Polster.', 'Lege die Hände an die seitlichen Griffe und löse die Sicherung. Bei den meisten Geräten drehst du dazu die Griffe von der Stellung nach vorn in eine schräge Stellung.', 'Strecke die Beine, ohne die Knie durchzudrücken. Das ist deine Ausgangsposition.', 'Atme ein und senke den Schlitten langsam, indem du die Knie beugst. Bleibe aufrecht, der Kopf oben, der Rücken immer am Polster. Gehe hinunter, bis Oberschenkel und Waden einen Winkel von etwas weniger als 90 Grad bilden; die Oberschenkel sind dann tiefer als parallel zum Boden.', 'Atme aus und hebe den Schlitten: Drücke dich vor allem mit den Fersen ab und strecke die Beine, bis du wieder in der Ausgangsposition bist.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Narrow_Stance_Leg_Press', 'de', array['Setze dich in eine Beinpresse und stelle die Füße direkt vor dir eng auf die Plattform, enger als schulterbreit, die Fußspitzen leicht nach außen. Der Abstand der Füße beträgt etwa 3 Inches oder weniger. Tipp: Halte den Kopf die ganze Zeit oben und den Rücken immer am Polster.', 'Löse die Sicherung, die die beladene Plattform hält, und drücke die Plattform nach oben, bis die Beine vor dir ganz gestreckt sind. Tipp: Drücke die Knie nicht durch. Oberkörper und Beine bilden genau einen Winkel von 90 Grad. Das ist deine Ausgangsposition.', 'Atme ein und senke die Plattform langsam, bis Ober- und Unterschenkel einen Winkel von 90 Grad bilden.', 'Atme aus und kehre in die Ausgangsposition zurück. Drücke dabei vor allem mit den Fersen und arbeite mit dem Quadrizeps.', 'Mache die empfohlene Zahl an Wiederholungen und verriegle am Ende die Sicherung richtig. Die voll beladene Plattform darf nicht auf dich fallen.']::text[]),
  ('Narrow_Stance_Squats', 'de', array['Mach diese Übung zur Sicherheit in einem Squat-Rack. Lege die Stange auf einer Höhe ab, die zu deiner Körpergröße passt, und belade sie. Tritt dann unter die Stange und lege sie auf die Rückseite deiner Schultern, knapp unterhalb des Nackens.', 'Fasse die Stange links und rechts mit beiden Händen. Hebe sie aus der Ablage, indem du dich mit den Beinen hochdrückst und gleichzeitig den Oberkörper aufrichtest.', 'Geh einen Schritt vom Rack weg. Stell die Füße enger als schulterbreit, etwa 3-6 Inches auseinander, die Zehen zeigen leicht nach außen. Halte den Kopf die ganze Zeit oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der hier beschriebene Stand zielt auf eine Entwicklung der gesamten Beinmuskulatur, du kannst aber auch eine andere Standbreite wählen.', 'Beuge die Knie und senke die Stange langsam ab, mit aufrechter Haltung und erhobenem Kopf. Geh so tief, bis der Winkel zwischen Oberschenkeln und Waden etwas kleiner als 90 Grad ist, die Oberschenkel also tiefer als parallel zum Boden stehen. Atme dabei ein. Tipp: Bei sauberer Ausführung bildet die Vorderseite der Knie mit den Zehen eine gedachte gerade Linie, die senkrecht zur Vorderseite steht. Schieben sich die Knie über die Zehen hinaus, belastest du das Knie unnötig und die Ausführung ist falsch.', 'Atme aus und bring die Stange wieder nach oben: Drück dich vor allem mit den Fersen vom Boden ab, strecke die Beine und komm zurück in die Ausgangsposition.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Natural_Glute_Ham_Raise', 'de', array['Nutze das Beinpolster einer Latzugmaschine oder eine Scottbank. Knie dich mit dem Rücken zum Gerät auf den Sitz und klemme die Fußgelenke unter die Polster. Bleib aufrecht und achte auf eine gute Haltung.', 'Das ist deine Ausgangsposition. Lass dich kontrolliert nach vorn ab, bis deine Knie fast ganz gestreckt sind.', 'Zieh dich ebenso kontrolliert wieder hoch in die Ausgangsposition.', 'Schaffst du eine Wiederholung nicht, hilf dir mit einem Band oder einem Partner oder stoß dich von einer Box ab.']::text[]),
  ('Neck-SMR', 'de', array['Nimm einen Massageroller oder ein Nudelholz und halte ihn hinter dem Kopf an deinen Nacken. Drück ihn nicht direkt auf die Wirbelsäule: Dreh ihn leicht, sodass er auf den Muskeln neben der Wirbelsäule liegt. Das ist deine Ausgangsposition.', 'Fang oben am Nacken an und rolle langsam die Nackenmuskeln hinunter. An verspannten Stellen bleibst du 10-30 Sekunden.']::text[]),
  ('Neck_Press', 'de', array['Leg dich mit dem Rücken auf eine Flachbank. Greife die Stange mittelbreit, also so, dass Unterarme und Oberarme in der Mitte der Bewegung einen 90-Grad-Winkel bilden. Hebe die Stange aus der Ablage und halte sie mit durchgestreckten Armen genau über deinem Hals. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam ab, bis du sie am Hals spürst.', 'Halte eine Sekunde, atme dann aus und drück die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Strecke die Arme durch, spanne oben die Brust an, halte eine Sekunde und senke wieder langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach die vorgegebene Anzahl an Wiederholungen.', 'Leg die Stange am Ende zurück in die Ablage.']::text[]),
  ('Oblique_Crunches', 'de', array['Leg dich flach auf den Rücken und drück den unteren Rücken in den Boden. Eine Hand kommt neben den Kopf, die andere liegt seitlich auf dem Boden.', 'Lagere die Füße erhöht auf einer ebenen Fläche.', 'Hebe nun die Schulter auf der Seite an, auf der die Hand am Kopf liegt.', 'Bring Schulter und Oberkörper so weit hoch, bis du dein Knie erreichst. Ein Beispiel: Liegt die rechte Hand am Kopf, kommst du hoch, bis der rechte Ellbogen das linke Knie berührt. Umgekehrt geht es genauso, dann führst du den linken Ellbogen zum rechten Knie.', 'Haben sich Ellbogen und Knie berührt, senke den Oberkörper zurück in die Ausgangsposition.', 'Atme in der exzentrischen Phase (beim Absenken) ein und in der konzentrischen Phase (beim Aufrichten) aus.', 'Wechsle so weiter ab, bis du auf jeder Seite alle empfohlenen Wiederholungen gemacht hast.']::text[]),
  ('Oblique_Crunches_-_On_The_Floor', 'de', array['Leg dich auf die rechte Seite, die Beine liegen übereinander. Beuge die Knie ein wenig.', 'Nimm die linke Hand hinter den Kopf.', 'Führe aus dieser Position den linken Ellbogen nach oben wie bei einem normalen Crunch, nur liegt der Schwerpunkt diesmal auf der schrägen Bauchmuskulatur.', 'Komm so hoch, wie du kannst, halte die Spannung eine Sekunde und senke dich dann langsam in die Ausgangsposition ab.', 'Atme in der exzentrischen Phase (beim Absenken) ein und in der konzentrischen Phase (beim Anheben) aus.']::text[]),
  ('Olympic_Squat', 'de', array['Die Langhantel liegt oben auf dem Trapez. Heb die Brust und schau nach vorn. Stell die Füße hüftbreit auf und dreh sie so weit nach außen, wie du es brauchst.', 'Geh nach unten, indem du die Knie beugst, und schieb die Hüfte dabei so wenig wie möglich nach hinten. Dafür müssen die Knie nach vorn wandern; achte darauf, dass sie in einer Linie mit den Füßen bleiben. Ziel ist ein möglichst aufrechter Oberkörper. Geh ganz hinunter und halte das Gewicht auf dem vorderen Teil der Ferse.', 'Sobald die Oberschenkel die Unterschenkel berühren, kehrst du die Bewegung um und drückst das Gewicht nach oben.']::text[]),
  ('On-Your-Back_Quad_Stretch', 'de', array['Leg dich auf eine Flachbank oder einen Stepper und lass ein Bein und einen Arm seitlich herunterhängen.', 'Beuge das Knie und fasse den Fußrücken. Pass dabei auf, dass du nicht ins Hohlkreuz gehst.', 'Zieh den Bauchnabel zur Wirbelsäule, um neutral zu bleiben. Drück den Fuß nach unten und in die Hand. Für eine zusätzliche Hüftdehnung hebst du die Hüfte des gehaltenen Beins zur Decke.', 'Wechsle die Seite.']::text[]),
  ('On_Your_Side_Quad_Stretch', 'de', array['Leg dich auf die rechte Seite. Winkle das rechte Knie um 90 Grad an und lege es vor dir auf den Boden; das stabilisiert den Oberkörper.', 'Beuge das linke Knie nach hinten und fasse den linken Fuß mit der linken Hand. Um den Hüftbeuger zu dehnen, schiebst du die linke Hüfte nach vorn und drückst den Fuß nach hinten in die Hand. Wechsle die Seite.']::text[]),
  ('One-Arm_Dumbbell_Row', 'de', array['Such dir eine Flachbank und lege auf jede Seite eine Kurzhantel.', 'Setz das rechte Bein auf ein Ende der Bank. Beuge den Oberkörper aus der Taille nach vorn, bis er parallel zum Boden ist, und stütz dich mit der rechten Hand auf dem anderen Ende der Bank ab.', 'Nimm die Kurzhantel mit der linken Hand vom Boden und halte sie, der untere Rücken bleibt gerade. Die Handfläche zeigt zum Oberkörper. Das ist deine Ausgangsposition.', 'Zieh das Gewicht gerade nach oben seitlich an die Brust. Der Oberarm bleibt nah am Körper, der Oberkörper ruhig. Atme dabei aus. Tipp: Konzentriere dich ganz oben darauf, die Rückenmuskeln anzuspannen. Die Kraft soll aus dem Rücken kommen, nicht aus den Armen. Der Oberkörper bleibt ruhig, nur der Arm bewegt sich. Der Unterarm hält nur die Kurzhantel, versuch also nicht, das Gewicht mit ihm hochzuziehen.', 'Senke das Gewicht gerade nach unten in die Ausgangsposition. Atme dabei ein.', 'Mach die angegebene Anzahl an Wiederholungen.', 'Wechsle die Seite und wiederhole alles mit dem anderen Arm.']::text[]),
  ('One-Arm_Flat_Bench_Dumbbell_Flye', 'de', array['Leg dich auf eine Flachbank, eine Kurzhantel in einer Hand auf dem Oberschenkel. Halte sie im neutralen Griff.', 'Gib der Kurzhantel mit dem Oberschenkel Schwung und halte sie mit ganz gestrecktem Arm vor dir. Bleib bei dieser Übung im neutralen Griff. Die freie Hand hält sich seitlich an der Bank fest und gibt dir mehr Halt. Das ist deine Ausgangsposition.', 'Der Ellbogen des arbeitenden Arms ist leicht gebeugt, das schont die Bizepssehne. Führe den Arm in einem weiten Bogen nach außen und unten, bis du eine Dehnung in der Brust spürst. Atme dabei ein. Tipp: Der Arm selbst bleibt während der ganzen Bewegung fixiert; bewegt wird nur das Schultergelenk.', 'Spanne die Brustmuskeln an und atme aus, während du den Arm zurück in die Ausgangsposition bringst. Tipp: Nimm denselben Bogen wie beim Absenken.', 'Halte die Endposition eine Sekunde und mach dann die vorgegebene Anzahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('One-Arm_High-Pulley_Cable_Side_Bends', 'de', array['Befestige einen Standardgriff am Kabelzug und stell die Rolle auf die höchste Position.', 'Stell dich seitlich zum Kabelzug. Greif mit einer Hand nach oben und fasse den Griff im Untergriff.', 'Zieh das Kabel herunter, bis der Ellbogen deine Seite berührt und der Griff neben der Schulter ist.', 'Stell die Füße hüftbreit auf. Lege die freie Hand auf die Hüfte, um den Drehpunkt besser zu spüren.', 'Der Arm bleibt unbewegt. Spanne die schräge Bauchmuskulatur an und bring das Gewicht mit einem seitlichen Crunch nach unten.', 'Ist die Kontraktion am stärksten, lässt du das Gewicht langsam zurück in die Ausgangsposition. Die Gewichte dürfen nie ganz aufliegen; es geht um durchgehende Spannung während des Satzes.', 'Wiederhole bis zum Muskelversagen.', 'Stell dich dann um und mach denselben Ablauf auf der anderen Seite.']::text[]),
  ('One-Arm_Incline_Lateral_Raise', 'de', array['Leg dich seitlich auf eine Schrägbank, eine Kurzhantel in der Hand. Die Schulter drückt gegen die Bank, der Arm liegt quer vor dem Körper, die Handfläche etwa am Bauchnabel.', 'Halte die Kurzhantel im oben liegenden Arm, vor dir ausgestreckt und parallel zum Boden. Das ist deine Ausgangsposition.', 'Mach ein Seitheben und halte die Kurzhantel dabei immer parallel zum Boden. Der Arm geht gerade nach oben, bis er zur Decke zeigt. Tipp: Atme bei dieser Bewegung aus. Halte die Kurzhantel dort eine Sekunde und spüre die Anspannung in der Schulter.', 'Atme ein und senke das Gewicht quer vor dem Körper zurück in die Ausgangsposition.', 'Mach die vorgegebene Anzahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One-Arm_Kettlebell_Clean', 'de', array['Stell eine Kettlebell zwischen deine Füße. Schieb das Gesäß nach hinten, wenn du dich zum Greifen hinunterbeugst, und schau weiter nach vorn.', 'Setz die Kettlebell zur Schulter um: Strecke Beine und Hüfte und führe das Gewicht dabei zur Schulter. Das Handgelenk dreht sich in der Bewegung mit.', 'Bring das Gewicht zurück in die Ausgangsposition.']::text[]),
  ('One-Arm_Kettlebell_Clean_and_Jerk', 'de', array['Fasse eine Kettlebell am Griff.', 'Setz sie zur Schulter um: Strecke Beine und Hüfte und zieh die Kettlebell zur Schulter. Dreh dabei das Handgelenk, sodass die Handfläche nach vorn zeigt.', 'Geh kurz in die Knie und halte den Oberkörper aufrecht.', 'Kehre die Richtung sofort um und drück dich über die Fersen ab, im Grunde ein Sprung, der Schwung erzeugt. Nutze diesen Schwung, um die Kettlebell über den Kopf zu drücken, bis der Arm ganz gestreckt ist.', 'Fang das Gewicht über dem Kopf ab, indem du unter ihm wieder in die Kniebeuge gehst.', 'Richte dich auf, das Gewicht bleibt über dem Kopf. Senke es für die nächste Wiederholung zum Boden ab.']::text[]),
  ('One-Arm_Kettlebell_Floor_Press', 'de', array['Leg dich auf den Boden, eine Kettlebell in einer Hand, der Oberarm liegt auf dem Boden auf. Die Handfläche zeigt nach innen.', 'Drück die Kettlebell gerade zur Decke und dreh dabei das Handgelenk.', 'Senke sie zurück in die Ausgangsposition und wiederhole.']::text[]),
  ('One-Arm_Kettlebell_Jerk', 'de', array['Fasse eine Kettlebell am Griff. Setz sie zur Schulter um: Strecke Beine und Hüfte und zieh die Kettlebell zur Schulter. Dreh dabei das Handgelenk, sodass die Handfläche nach vorn zeigt. Das ist deine Ausgangsposition.', 'Geh kurz in die Knie und halte den Oberkörper aufrecht.', 'Kehre die Richtung sofort um und drück dich über die Fersen ab, im Grunde ein Sprung, der Schwung erzeugt. Nutze diesen Schwung, um die Kettlebell über den Kopf zu drücken, bis der Arm ganz gestreckt ist. Fang das Gewicht über dem Kopf ab, indem du unter ihm wieder in die Kniebeuge gehst. Richte dich auf, das Gewicht bleibt über dem Kopf.', 'Senke das Gewicht für die nächste Wiederholung ab.']::text[]),
  ('One-Arm_Kettlebell_Military_Press_To_The_Side', 'de', array['Setz eine Kettlebell zur Schulter um: Strecke Beine und Hüfte und zieh die Kettlebell zur Schulter. Dreh dabei das Handgelenk, sodass die Handfläche nach innen zeigt. Das ist deine Ausgangsposition.', 'Schau auf die Kettlebell und drück sie nach oben und außen, bis der Arm über dem Kopf ganz gestreckt ist.', 'Senke sie kontrolliert zur Schulter ab und wiederhole. Spanne Latissimus, Gesäß und Bauch kräftig an, das gibt mehr Stabilität und Kraft.']::text[]),
  ('One-Arm_Kettlebell_Para_Press', 'de', array['Setz eine Kettlebell zur Schulter um: Strecke Beine und Hüfte und zieh die Kettlebell zur Schulter. Dreh dabei das Handgelenk, sodass die Handfläche nach vorn zeigt. Das ist deine Ausgangsposition.', 'Halte die Kettlebell mit seitlich abgespreiztem Ellbogen und drück sie nach oben und außen, bis der Arm über dem Kopf ganz gestreckt ist.', 'Senke sie kontrolliert zur Schulter ab und wiederhole. Spanne Latissimus, Gesäß und Bauch kräftig an, das gibt mehr Stabilität und Kraft.']::text[]),
  ('One-Arm_Kettlebell_Push_Press', 'de', array['Fasse eine Kettlebell am Griff. Setz sie zur Schulter um: Strecke Beine und Hüfte und zieh die Kettlebell zur Schulter. Dreh dabei das Handgelenk, sodass die Handfläche nach vorn zeigt. Das ist deine Ausgangsposition.', 'Geh kurz in die Knie und halte den Oberkörper aufrecht.', 'Kehre die Richtung sofort um und drück dich über die Fersen ab, im Grunde ein Sprung, der Schwung erzeugt. Nutze diesen Schwung, um die Kettlebell über den Kopf zu drücken, bis der Arm ganz gestreckt ist. Senke das Gewicht für die nächste Wiederholung ab.']::text[]),
  ('One-Arm_Kettlebell_Row', 'de', array['Stell eine Kettlebell vor deine Füße. Beuge die Knie leicht und schieb das Gesäß so weit wie möglich nach hinten, während du dich in die Ausgangsposition vorbeugst. Fasse die Kettlebell und zieh sie zum Bauch: Das Schulterblatt geht nach hinten, der Ellbogen beugt sich. Der Rücken bleibt gerade. Senke ab und wiederhole.']::text[]),
  ('One-Arm_Kettlebell_Snatch', 'de', array['Stell eine Kettlebell zwischen deine Füße. Beuge die Knie und schieb das Gesäß nach hinten, um in die richtige Ausgangsposition zu kommen.', 'Schau geradeaus und schwing die Kettlebell zwischen den Beinen nach hinten.', 'Kehre die Richtung sofort um und streck Hüfte und Knie kraftvoll durch, sodass die Kettlebell nach oben beschleunigt. Kommt sie auf Schulterhöhe, drehst du die Hand und stößt gerade nach oben; der Schwung trägt das Gewicht, bis der Arm über dem Kopf gestreckt ist.']::text[]),
  ('One-Arm_Kettlebell_Split_Jerk', 'de', array['Fasse eine Kettlebell am Griff. Setz sie zur Schulter um: Strecke Beine und Hüfte und zieh die Kettlebell zur Schulter. Dreh dabei das Handgelenk, sodass die Handfläche nach vorn zeigt. Das ist deine Ausgangsposition.', 'Geh kurz in die Knie und halte den Oberkörper aufrecht.', 'Kehre die Richtung sofort um und drück dich über die Fersen ab, im Grunde ein Sprung, der Schwung erzeugt. Nutze diesen Schwung, um die Kettlebell über den Kopf zu drücken, bis der Arm ganz gestreckt ist.', 'Fang das Gewicht über dem Kopf ab, indem du unter ihm in die Kniebeuge gehst, ein Bein vor dir und eines hinter dir.', 'Richte dich auf, das Gewicht bleibt über dem Kopf, und stell die Füße zusammen. Senke das Gewicht für die nächste Wiederholung ab.']::text[]),
  ('One-Arm_Kettlebell_Split_Snatch', 'de', array['Halte eine Kettlebell mit einer Hand am Griff.', 'Geh in die Hocke und kehre die Bewegung dann um: Strecke erst die Hüfte, dann die Knie und zuletzt die Fußgelenke, um die Kettlebell über den Kopf zu bringen.', 'Ist der Körper ganz gestreckt, gehst du in einen Ausfallschritt und fängst das Gewicht über dem Kopf ab, ein Bein vorn, eines hinten. Streck die Hüfte kraftvoll durch und bring die Kettlebell in einer einzigen, ununterbrochenen Bewegung über dem Kopf in die Streckung.', 'Richte dich mit dem Gewicht über dem Kopf auf und stell die Füße zusammen. Senke das Gewicht ab, um in die Ausgangsposition zurückzukommen.']::text[]),
  ('One-Arm_Kettlebell_Swings', 'de', array['Stell dich etwas weiter als schulterbreit hin, die Kettlebell steht knapp vor dir auf dem Boden. Schieb die Hüfte nach hinten, halte den Rücken gerade und fasse den Griff mit einer Hand.', 'Schwing die Kettlebell zwischen den Beinen nach hinten. Der arbeitende Arm bleibt gestreckt, den freien Arm hältst du zum Ausgleich seitlich.', 'Schieb die Hüfte kraftvoll nach vorn und strecke die Knie, sodass die Kettlebell etwa bis auf Brusthöhe schwingt. Atme aus, während sie steigt.', 'Lass die Kettlebell kontrolliert zwischen die Beine zurückfallen und geh direkt in die nächste Wiederholung. Wechsle nach deinen Wiederholungen den Arm.']::text[]),
  ('One-Arm_Long_Bar_Row', 'de', array['Steck ein Ende einer Stange in eine Landmine-Halterung oder klemm es in eine Ecke, damit es nicht wegrutscht. Lade ein passendes Gewicht auf das freie Ende.', 'Stell dich neben die Stange und greife sie mit einer Hand nah an der Hülse. Richte dich mit der Kraft aus Hüfte und Beinen auf.', 'Beuge die Knie, schieb die Hüfte nach hinten und heb die Brust. Der Arm ist gestreckt. Das ist deine Ausgangsposition.', 'Zieh das Gewicht an deine Seite: Die Schulter geht nach hinten, der Ellbogen beugt sich. Reiß das Gewicht nicht hoch und mogle nicht bei der Bewegung.', 'Halte kurz und geh dann zurück in die Ausgangsposition.']::text[]),
  ('One-Arm_Medicine_Ball_Slam', 'de', array['Stell dich in eine athletische Schrittstellung. Halte einen Medizinball in der Hand auf der Seite des hinteren Beins. Das ist deine Ausgangsposition.', 'Hol mit dem Arm aus und heb den Medizinball über den Kopf. Strecke dabei Hüfte, Knie und Fußgelenke, um Spannung für den Wurf aufzubauen.', 'Am höchsten Punkt der Streckung beugst du Schultern, Wirbelsäule und Hüfte und schmetterst den Ball direkt vor dir hart auf den Boden.', 'Fang den Ball nach dem Aufprall und mach weiter, bis du die gewünschte Anzahl an Wiederholungen erreicht hast.']::text[]),
  ('One-Arm_Open_Palm_Kettlebell_Clean', 'de', array['Stell eine Kettlebell zwischen deine Füße.', 'Fasse den Griff mit einer Hand und heb die Kettlebell schnell hoch. Lass sie sich drehen, sodass die Kugel in deiner offenen Handfläche landet.', 'Wirf die Kettlebell nach vorn von dir weg und fang sie mit einer Hand am Griff.', 'Führe die Kettlebell zum Boden und wiederhole. Trainiere beide Arme.']::text[]),
  ('One-Arm_Overhead_Kettlebell_Squats', 'de', array['Setz eine Kettlebell mit einem Arm um und drück sie hoch: Strecke Beine und Hüfte, zieh die Kettlebell zur Schulter und dreh dabei das Handgelenk. Strecke dann den Ellbogen und drück das Gewicht über den Kopf. Das ist deine Ausgangsposition.', 'Schau geradeaus und halte die Kettlebell mit gestrecktem Arm über dir. Beuge Knie und Hüfte und senke den Oberkörper zwischen die Beine, Kopf und Brust bleiben oben.', 'Halte unten eine Sekunde und drück dich dann über die Fersen wieder nach oben.']::text[]),
  ('One-Arm_Side_Deadlift', 'de', array['Stell dich seitlich neben eine Langhantel, auf Höhe ihrer Mitte. Beuge die Knie und geh so weit nach unten, bis du die Stange erreichst.', 'Greif die Stange so, wie du eine Aktentasche anheben würdest (die Stange liegt seitlich, deshalb zeigt die Handfläche zu dir). Bei viel Gewicht brauchst du eventuell eine Handgelenkbandage. Das ist deine Ausgangsposition.', 'Atme aus und heb die Langhantel mit Hilfe der Beine an. Dein Arm streckt sich dabei ganz, bis du aufrecht stehst.', 'Atme ein und senke die Langhantel langsam wieder ab. Tipp: Beuge beim Absenken die Knie, damit du dich nicht verletzt.', 'Mach die empfohlene Anzahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One-Arm_Side_Laterals', 'de', array['Nimm eine Kurzhantel in eine Hand. Halte dich mit der freien Hand an etwas Stabilem fest, zum Beispiel an einer Schrägbank. Lehne dich zum hebenden Arm hin, weg von der Hand an der Bank, so bleibst du im Gleichgewicht.', 'Steh mit geradem Oberkörper und lass die Kurzhantel am gestreckten Arm seitlich hängen, die Handfläche zeigt zu dir. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig (kein Schwung) und heb die Kurzhantel zur Seite an. Der Ellbogen ist leicht gebeugt, die Hand etwas nach vorn gekippt, als würdest du Wasser in ein Glas gießen. Heb weiter, bis der Arm parallel zum Boden ist. Atme dabei aus und halte oben eine Sekunde.', 'Atme ein und senke die Kurzhantel langsam in die Ausgangsposition ab.', 'Mach die empfohlene Anzahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('One-Legged_Cable_Kickback', 'de', array['Hänge eine Fußmanschette aus Leder an einen tiefen Kabelzug und lege die Manschette um dein Fußgelenk.', 'Stell dich mit dem Gesicht zum Gewichtsblock, etwa zwei Fuß davon entfernt, und halte dich zur Stütze am Stahlrahmen fest.', 'Knie und Hüfte sind leicht gebeugt, der Bauch ist fest. Spanne das Gesäß an und "kicke" das arbeitende Bein beim Ausatmen langsam in einem Halbkreis nach hinten, so hoch es bequem geht. Tipp: Drücke das Gesäß bei voller Streckung eine Sekunde lang zusammen, um die maximale Kontraktion zu erreichen.', 'Führe das arbeitende Bein nun langsam wieder nach vorn und halte dabei gegen den Zug des Kabels, bis du in der Ausgangsposition bist.', 'Mach die empfohlene Anzahl an Wiederholungen.', 'Wechsle das Bein und wiederhole die Bewegung auf der anderen Seite.']::text[]),
  ('One_Arm_Against_Wall', 'de', array['Stell dich hin und lege einen angewinkelten Arm an eine Wand oder einen Türrahmen.', 'Lehne dich langsam zu diesem Arm hin, bis du die Dehnung im Latissimus spürst.']::text[]),
  ('One_Arm_Chin-Up', 'de', array['Lege zuerst ein Handtuch über eine Klimmzugstange.', 'Greife die Stange so, dass die Handfläche zu dir zeigt. Eine Hand hält die Stange, die andere das Handtuch.', 'Lehne den Oberkörper um etwa 30 Grad zurück, geh dabei leicht ins Hohlkreuz und streck die Brust heraus. Das ist deine Ausgangsposition.', 'Zieh Schultern und Oberarme nach unten und hinten und bring dich so weit hoch, bis die Stange die obere Brust berührt. Atme dabei aus. Tipp: Konzentriere dich ganz oben darauf, die Rückenmuskeln anzuspannen. Der Oberkörper bleibt auf dem Weg nach oben starr, nur die Arme bewegen sich. Die Unterarme halten lediglich die Stange und leisten sonst keine Arbeit.', 'Halte oben eine Sekunde, atme dann ein und lass dich langsam in die Ausgangsposition ab, bis die Arme ganz gestreckt sind und der Latissimus voll gedehnt ist.', 'Mach die vorgegebene Anzahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One_Arm_Dumbbell_Bench_Press', 'de', array['Leg dich auf eine Flachbank, eine Kurzhantel in einer Hand auf dem Oberschenkel.', 'Gib der Kurzhantel mit dem Oberschenkel Schwung und bring sie auf Schulterbreite vor dich. Mit der freien Hand hilfst du, sie richtig über dir auszurichten.', 'Ist die Hantel auf Schulterbreite, drehst du das Handgelenk nach vorn, bis die Handfläche von dir weg zeigt. Das ist deine Ausgangsposition.', 'Atme ein und senke das Gewicht langsam zur Seite ab. Behalte die Kurzhantel jederzeit voll unter Kontrolle. Tipp: Am Anfang fällt das Ausbalancieren vielleicht schwer, dann stützt du die Hantel mit der freien Hand. Tu das nur, wenn es nötig ist; sonst bleibt diese Hand ruhig an der Seite.', 'Atme aus und drück die Kurzhantel mit der Brustmuskulatur nach oben. Strecke den Arm oben durch, spanne die Brust an, halte eine Sekunde und senke dann langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach so viele Wiederholungen, wie dein Trainingsplan vorgibt.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One_Arm_Dumbbell_Preacher_Curl', 'de', array['Nimm eine Kurzhantel in die rechte Hand und lege den Oberarm auf das Polster einer Scottbank oder einer Schrägbank. Halte die Kurzhantel auf Schulterhöhe. Das ist deine Ausgangsposition.', 'Atme ein und senke die Kurzhantel langsam ab, bis der Arm gestreckt und der Bizeps voll gedehnt ist.', 'Atme aus und beuge den Arm mit der Kraft des Bizeps, bis der Muskel ganz angespannt ist und die Kurzhantel auf Schulterhöhe steht. Für die volle Kontraktion bringst du den kleinen Finger höher als den Daumen.', 'Spanne den Bizeps oben eine Sekunde lang kräftig an und mach dann die empfohlene Anzahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One_Arm_Floor_Press', 'de', array['Leg dich auf den Boden oder eine Trainingsmatte, der Rücken liegt flach auf. Winkle die Knie an.', 'Lass dir die Stange von einem Partner in eine Hand geben. Zu Beginn ist dein Arm fast ganz gestreckt, ähnlich wie in der Ausgangsposition beim Bankdrücken mit der Langhantel. Hier greifst du allerdings neutral, die Handfläche zeigt zum Oberkörper.', 'Die Hand, die nicht arbeitet, liegt an deiner Seite.', 'Senke die Langhantel zuerst ab, bis der Ellbogen den Boden berührt. Atme dabei ein, denn das ist die exzentrische Phase (das Absenken).', 'Drück die Langhantel dann wieder hoch in die Ausgangsposition. Atme in der konzentrischen Phase (beim Hochdrücken) aus.', 'Mach weiter, bis du deine empfohlenen Wiederholungen geschafft hast.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One_Arm_Lat_Pulldown', 'de', array['Wähle ein passendes Gewicht und stell das Kniepolster so ein, dass es dich unten hält. Fasse den Griff im Obergriff. Das ist deine Ausgangsposition.', 'Zieh den Griff nach unten: Beuge den Ellbogen und drück ihn an deine Seite.', 'Halte unten kurz und führe den Griff dann langsam zurück in die Ausgangsposition.', 'Bei mehreren Wiederholungen lässt du das Gewicht nicht ganz zurück, damit die arbeitenden Muskeln unter Spannung bleiben.']::text[]),
  ('One_Arm_Pronated_Dumbbell_Triceps_Extension', 'de', array['Leg dich flach auf eine Bank und halte eine Kurzhantel am gestreckten Arm, der Arm steht senkrecht zum Körper. Die Übung verlangt den Obergriff, deine Handfläche zeigt also zu den Füßen.', 'Stütze den arbeitenden Arm, indem du die freie Hand auf seinen Bizeps legst.', 'Atme ein und senke die Kurzhantel langsam ab.', 'Spanne dann den Trizeps an und hebe die Kurzhantel wieder nach oben. Atme in der konzentrischen Phase (beim Anheben) aus.', 'Mach weiter, bis du die Wiederholungen deines Satzes geschafft hast.', 'Wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('One_Arm_Supinated_Dumbbell_Triceps_Extension', 'de', array['Leg dich flach auf eine Bank und halte eine Kurzhantel am gestreckten Arm, der Arm steht senkrecht zum Körper. Die Übung verlangt den Untergriff, deine Handfläche zeigt also zu deinem Gesicht.', 'Stütze den arbeitenden Arm, indem du die freie Hand auf seinen Bizeps legst.', 'Atme ein und senke die Kurzhantel langsam ab.', 'Spanne dann den Trizeps an und hebe die Kurzhantel wieder nach oben. Atme in der konzentrischen Phase (beim Anheben) aus.', 'Mach weiter, bis du die Wiederholungen deines Satzes geschafft hast.', 'Wechsle den Arm und wiederhole die Bewegung.', 'Wechsle noch einmal den Arm und wiederhole die Bewegung.']::text[]),
  ('One_Half_Locust', 'de', array['Leg dich bäuchlings auf den Boden.', 'Schieb die linke Hand unter den linken Hüftknochen, um Hüfte und Schambein zu polstern.', 'Beuge das rechte Knie und fasse den Fuß mit der rechten Hand.', 'Hebe den Fuß in die Luft und nimm gleichzeitig die Schultern vom Boden. Das dehnt auch den rechten Hüftbeuger sowie Brust und Schultern. Wechsle die Seite. Macht dein Rücken keine Probleme, kannst du es mit beiden Armen und Beinen zugleich probieren.']::text[]),
  ('One_Handed_Hang', 'de', array['Fasse eine Klimmzugstange mit einer Hand im Obergriff. Die Füße bleiben auf dem Boden oder auf einem Stepper. Lass den größten Teil deines Gewichts an dieser Hand hängen, während die Füße am Boden bleiben. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('One_Knee_To_Chest', 'de', array['Leg dich auf den Boden.', 'Strecke ein Bein gerade aus und zieh das andere Knie zur Brust. Fasse unterhalb des Kniegelenks, um die Kniescheibe zu schonen.', 'Zieh dieses Knie sanft in Richtung Nase.', 'Wechsle die Seite. Gedehnt werden Gesäß und unterer Rücken auf der Seite des angewinkelten Beins und der Hüftbeuger des gestreckten Beins.']::text[]),
  ('One_Leg_Barbell_Squat', 'de', array['Stell dich etwa 2 bis 3 Feet vor eine Flachbank, mit dem Rücken zu ihr. Vor dir liegt eine Langhantel auf dem Boden. Tipp: Die Füße stehen schulterbreit auseinander.', 'Beuge die Knie, fasse die Langhantel im Obergriff weiter als schulterbreit und hebe sie hoch, bis du sie auf der Brust ablegen kannst.', 'Hebe die Langhantel nun über den Kopf und lege sie am Nackenansatz ab. Setz einen Fuß nach hinten, sodass die Zehen auf der Bank liegen. Der andere Fuß bleibt fest vor dir stehen. Halte den Kopf die ganze Zeit oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Tipp: Achte während der Übung auf einen geraden Rücken und eine herausgestreckte Brust.', 'Atme ein und geh auf dem vorderen Bein langsam nach unten, bis der Oberschenkel parallel zum Boden ist. Das Knie steht jetzt über den Zehen, die Brust genau über der Mitte des Oberschenkels.', 'Atme aus und drück dich zurück in die Ausgangsposition: Brust und Hüfte führen, der Quadrizeps spannt an.', 'Mach die empfohlene Anzahl an Wiederholungen.', 'Wechsle das Bein und wiederhole die Bewegung.']::text[]),
  ('Open_Palm_Kettlebell_Clean', 'de', array['Stell eine Kettlebell zwischen deine Füße. Setze sie um: Strecke Beine und Hüfte und bring die Kettlebell dabei in Richtung deiner Schultern.', 'Lass die Kettlebell auf dem Weg nach oben los, damit sie sich dreht und ihre Kugel in deinen Handflächen landet.', 'Lass die Kettlebell vor dir los und fang den Griff mit beiden Händen. Senke sie in die Ausgangsposition ab und wiederhole.']::text[]),
  ('Otis-Up', 'de', array['Fixiere deine Füße und leg dich mit gebeugten Knien rücklings auf den Boden. Halte ein Gewicht mit beiden Händen an der Brust. Das ist deine Ausgangsposition.', 'Beginne, indem du Hüfte und Wirbelsäule beugst, sodass sich dein Oberkörper vom Boden hebt.', 'Drücke das Gewicht im Hochkommen nach oben, sodass es am höchsten Punkt über deinem Kopf ist.', 'Bring das Gewicht zurück zur Brust, während du den Sit-up umkehrst. Geh dabei nicht ganz bis zum Boden hinunter.']::text[]),
  ('Overhead_Cable_Curl', 'de', array['Stelle zuerst auf beiden Seiten des Kabelzugs ein Gewicht ein, mit dem du gut zurechtkommst. Hinweis: Das Gewicht muss auf beiden Seiten gleich sein.', 'Stelle dann die Rollen auf beiden Seiten so ein, dass sie höher als deine Schultern sind.', 'Stell dich in die Mitte zwischen beide Seiten und fasse jeden Griff im Untergriff (Handflächen zur Decke). Die Arme sind ganz gestreckt und parallel zum Boden, die Füße stehen schulterbreit. Dein Körper ist auf einer Linie mit den Griffen. Das ist die Ausgangsposition.', 'Atme aus und spanne den Bizeps auf beiden Seiten langsam an, bis Unterarme und Bizeps sich berühren.', 'Atme ein und führe die Unterarme in die Ausgangsposition zurück. Hinweis: Bei dieser Übung bewegen sich nur die Unterarme, der restliche Körper bleibt ruhig.', 'Mach so viele Wiederholungen, wie dein Programm vorgibt.']::text[]),
  ('Overhead_Lat', 'de', array['Setz dich aufrecht auf den Boden, dein Partner ist hinter dir. Streck einen Arm gerade nach oben und beuge den Ellbogen, als wolltest du mit der Hand deinen Rücken berühren. Dein Partner hält dich an Trizeps und Handgelenk. Das ist deine Ausgangsposition.', 'Versuche, den Oberarm seitlich an den Körper zu ziehen, während dein Partner genau das verhindert.', 'Entspanne den Arm nach 10-20 Sekunden und lass deinen Partner den Latissimus mit sanftem Druck auf den Trizeps weiter dehnen. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Overhead_Slam', 'de', array['Steh schulterbreit und halte einen Medizinball mit beiden Händen. Das ist deine Ausgangsposition.', 'Leite die Ausholbewegung ein: Heb den Ball über den Kopf und streck deinen Körper ganz.', 'Kehre die Bewegung um und schmettere den Ball mit aller Kraft direkt vor dir auf den Boden.', 'Fang den zurückspringenden Ball mit beiden Händen und wiederhole die Bewegung.']::text[]),
  ('Overhead_Squat', 'de', array['Zu Beginn liegt eine Langhantel vor dir auf dem Boden. Stell die Füße weiter als schulterbreit auseinander.', 'Beuge die Knie und fasse die Langhantel im Obergriff (Handflächen zu dir). Die Hände greifen vor dem Anheben weiter als schulterbreit. Wenn du in Position bist, heb die Langhantel an, bis du sie auf der Brust ablegen kannst.', 'Bring die Langhantel über und leicht hinter den Kopf, die Arme sind dabei ganz gestreckt. Halte den Kopf die ganze Zeit oben und den Rücken gerade. Zieh die Schulterblätter zusammen. Das ist deine Ausgangsposition.', 'Atme ein und senke das Gewicht langsam ab, indem du die Knie beugst, bis die Oberschenkel parallel zum Boden sind. Tipp: Ein gerader Rücken während der Übung schützt vor Verletzungen, und die Arme bleiben die ganze Zeit gestreckt über dem Kopf.', 'Atme nun aus und drücke das Gewicht mit Füßen und Beinen zurück in die Ausgangsposition.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Overhead_Stretch', 'de', array['Steh aufrecht, verschränke die Finger und dreh die Handflächen zur Decke. Streck die Arme nach oben und lass die Schultern dabei unten.', 'Für eine Dehnung des ganzen Rumpfes zieh das Steißbein nach unten und halte den Rumpf dabei stabil. Dehne die Muskeln an der Vorder- und an der Rückseite des Rumpfes.']::text[]),
  ('Overhead_Triceps', 'de', array['Setz dich aufrecht auf den Boden, dein Partner ist hinter dir. Streck einen Arm gerade nach oben und beuge den Ellbogen, als wolltest du mit der Hand deinen Rücken berühren. Dein Partner hält dich an Ellbogen und Handgelenk. Das ist deine Ausgangsposition.', 'Versuche, den Arm gerade nach oben zu strecken, während dein Partner genau das verhindert.', 'Entspanne den Arm nach 10-20 Sekunden und lass deinen Partner den Trizeps mit sanftem Druck auf das Handgelenk weiter dehnen. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Pallof_Press', 'de', array['Befestige einen Standardgriff am Kabelturm und stelle das Kabel, wenn möglich, auf Schulterhöhe ein. Sonst reicht auch eine tiefe Rolle.', 'Stell dich seitlich zum Kabel, fasse den Griff mit beiden Händen und geh vom Turm weg. Du stehst etwa eine Armlänge von der Rolle entfernt, das Gewicht hält das Kabel unter Spannung.', 'Die Füße stehen hüftbreit, die Knie sind leicht gebeugt. Halte das Kabel vor der Mitte deiner Brust. Das ist deine Ausgangsposition.', 'Drücke das Kabel von der Brust weg, bis beide Arme ganz gestreckt sind. Dein Rumpf ist fest und angespannt.', 'Halte die Wiederholung einige Sekunden und kehre dann in die Ausgangsposition zurück.', 'Wiederhole das Ganze am Ende des Satzes mit Blick in die andere Richtung.']::text[]),
  ('Pallof_Press_With_Rotation', 'de', array['Befestige einen Standardgriff am Kabelturm und stelle das Kabel auf Schulterhöhe ein.', 'Stell dich seitlich zum Kabel, fasse den Griff mit einer Hand und geh vom Turm weg. Du stehst etwa eine Armlänge von der Rolle entfernt, das Gewicht hält das Kabel unter Spannung. Der ausgestreckte Arm bildet eine Linie mit dem Kabel.', 'Die Füße stehen hüftbreit. Zieh das Kabel an die Brust und greif auch mit der anderen Hand zu. Jetzt sind beide Hände am Griff.', 'Schau nach vorn und drücke das Kabel von der Brust weg. Dein Rumpf ist fest und angespannt.', 'Halte die Hüfte gerade und dreh den Oberkörper von der Rolle weg, bis du eine volle Vierteldrehung erreicht hast.', 'Bleib fest im Stand und lass die Arme gestreckt. Kehre langsam und kontrolliert in die neutrale Position zurück. Die Arme sind vor dir ausgestreckt.', 'Der seitliche Zug fordert weiter deinen Rumpf: Führe die Hände zur Brust und drücke sie sofort wieder bis zur vollen Streckung nach vorn. Das ist eine Wiederholung.', 'Wiederhole bis zum Muskelversagen.', 'Stell dich danach neu auf und mach dieselbe Abfolge von Bewegungen auf der anderen Seite.']::text[]),
  ('Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'de', array['Lege zuerst zwei Kurzhanteln auf eine Seite einer Flachbank.', 'Knie dich mit beiden Knien so hin, dass du zur Flachbank schaust.', 'Fasse beide Kurzhanteln im Obergriff (Handflächen nach unten) und heb sie an, sodass deine Unterarme auf der Flachbank aufliegen. Die Handgelenke hängen über die Kante.', 'Beginne, indem du die Handgelenke nach oben beugst und dabei ausatmest.', 'Atme ein und senke die Handgelenke langsam in die Ausgangsposition.', 'Die Unterarme bleiben ruhig, denn bei dieser Übung bewegt sich nur das Handgelenk.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Palms-Down_Wrist_Curl_Over_A_Bench', 'de', array['Lege zuerst eine Langhantel auf eine Seite einer Flachbank.', 'Knie dich mit beiden Knien so hin, dass du zur Flachbank schaust.', 'Fasse die Langhantel im Obergriff (Handflächen nach unten) und heb sie an, sodass deine Unterarme auf der Flachbank aufliegen. Die Handgelenke hängen über die Kante.', 'Beginne, indem du die Handgelenke nach oben beugst und dabei ausatmest.', 'Atme ein und senke die Handgelenke langsam in die Ausgangsposition.', 'Die Unterarme bleiben ruhig, denn bei dieser Übung bewegt sich nur das Handgelenk.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'de', array['Lege zuerst eine Langhantel auf eine Seite einer Flachbank.', 'Knie dich mit beiden Knien so hin, dass du zur Flachbank schaust.', 'Fasse die Langhantel im Untergriff (Handflächen nach oben) und heb sie an, sodass deine Unterarme auf der Flachbank aufliegen. Die Handgelenke hängen über die Kante.', 'Beginne, indem du die Handgelenke nach oben beugst und dabei ausatmest.', 'Atme ein und senke die Handgelenke langsam in die Ausgangsposition.', 'Die Unterarme bleiben ruhig, denn bei dieser Übung bewegt sich nur das Handgelenk.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'de', array['Lege zuerst zwei Kurzhanteln auf eine Seite einer Flachbank.', 'Knie dich mit beiden Knien so hin, dass du zur Flachbank schaust.', 'Fasse beide Kurzhanteln im Untergriff (Handflächen nach oben) und heb sie an, sodass deine Unterarme auf der Flachbank aufliegen. Die Handgelenke hängen über die Kante.', 'Beginne, indem du die Handgelenke nach oben beugst und dabei ausatmest.', 'Atme ein und senke die Handgelenke langsam in die Ausgangsposition. Achte darauf, in diesem Teil der Übung einzuatmen.', 'Die Unterarme bleiben ruhig, denn bei dieser Übung bewegt sich nur das Handgelenk.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Parallel_Bar_Dip', 'de', array['Stell dich zwischen zwei parallele Holme. Leg auf jeden Holm eine Hand und spring leicht ab, um mit durchgestreckten Armen in die Ausgangsposition zu kommen.', 'Beginne, indem du die Ellbogen beugst, und senke deinen Körper, bis die Arme über 90 Grad hinaus gebeugt sind. Schwing nicht und halte beim Absenken eine gute Haltung.', 'Kehre die Bewegung um: Streck die Ellbogen und drück dich zurück in die Ausgangsposition.', 'Mach die gewünschte Anzahl an Wiederholungen.']::text[]),
  ('Pelvic_Tilt_Into_Bridge', 'de', array['Leg dich hin, die Füße stehen auf dem Boden, die Fersen direkt unter den Knien.', 'Heb nur das Steißbein zur Decke, um den unteren Rücken zu dehnen. (Die ganze Wirbelsäule hebst du noch nicht an.) Zieh den Bauch ein.', 'Für die Brücke heb die ganze Wirbelsäule an, nur der Nacken bleibt liegen.']::text[]),
  ('Peroneals-SMR', 'de', array['Leg dich auf die Seite. Stütze dein Gewicht auf den Unterarm und auf eine Faszienrolle, die unter der Außenseite deines Unterschenkels liegt. Das obere Bein kann auf dem unteren liegen oder vor dir überkreuzt sein. Das ist deine Ausgangsposition.', 'Heb die Hüfte vom Boden und rolle an der Beinseite von unterhalb des Knies bis oberhalb des Knöchels. An verspannten Stellen bleibst du 10-30 Sekunden. Wiederhole mit dem anderen Bein.']::text[]),
  ('Peroneals_Stretch', 'de', array['Setz dich hin und lege einen Gürtel, ein Seil oder ein Band um einen Fuß. Das ist deine Ausgangsposition.', 'Das Bein ist gestreckt, die Ferse ohne Bodenkontakt. Zieh am Gürtel, sodass der Fuß nach innen kippt und seine Innenseite zu dir gezogen wird. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Physioball_Hip_Bridge', 'de', array['Leg dich so auf einen Gymnastikball, dass dein oberer Rücken aufliegt und die Hüfte frei ist. Beide Füße stehen flach auf dem Boden, hüftbreit oder weiter. Das ist deine Ausgangsposition.', 'Beginne, indem du die Hüfte mit Gesäß und Beinbeugern streckst und sie zur Brücke nach oben hebst.', 'Halte am höchsten Punkt kurz und kehre in die Ausgangsposition zurück.']::text[]),
  ('Pin_Presses', 'de', array['Pin Presses nehmen die exzentrische Phase aus dem Bankdrücken und bauen so Startkraft auf. Außerdem kannst du damit einen bestimmten Bewegungsbereich trainieren.', 'Stell die Bank in ein Power Rack. Setze die Pins auf den gewünschten Punkt deines Bewegungsbereichs, ob nur das letzte Stück bis zur Streckung oder einen Zoll über der Brust. Lege die Stange auf die Pins und mach sie bereit zum Heben.', 'Leg dich auf die Bank, die Stange ist direkt über dem Punkt, an dem sie dich beim normalen Bankdrücken berührt. Zieh die Füße unter dich und geh ins Hohlkreuz. Nutze die Stange als Stütze für dein Gewicht, heb die Schultern von der Bank und zieh sie zurück, die Schulterblätter drückst du zusammen. Drücke mit den Füßen deinen Trapez in die Bank. Halte diese feste Körperspannung während der ganzen Bewegung.', 'Greif wie beim normalen Bankdrücken oder schulterbreit, um den Trizeps stärker zu fordern. Stange, Handgelenk und Ellbogen bleiben immer auf einer Linie. Konzentriere dich darauf, die Stange fest zu drücken und sie auseinanderziehen zu wollen.', 'Drücke die Stange mit so viel Kraft wie möglich nach oben. Die Ellbogen bleiben bis zur vollen Streckung eng am Körper.', 'Lege die Stange auf die Pins zurück und mach eine Pause, bevor du die nächste Wiederholung beginnst.']::text[]),
  ('Piriformis-SMR', 'de', array['Setz dich mit dem Gesäß auf eine Faszienrolle. Beuge die Knie und schlag ein Bein über, sodass der Knöchel über dem Knie liegt. Das ist deine Ausgangsposition.', 'Verlagere dein Gewicht zur Seite des übergeschlagenen Beins und rolle über das Gesäß, bis du im oberen Gesäß Spannung spürst. Du kannst die Dehnung unterstützen, indem du das gebeugte Knie mit einer Hand zur Brust ziehst. Halte diese Position 10-30 Sekunden und wechsle dann die Seite.']::text[]),
  ('Plank', 'de', array['Geh in Bauchlage auf den Boden und stütze dein Gewicht auf Zehen und Unterarme. Die Arme sind gebeugt und direkt unter den Schultern.', 'Halte den Körper die ganze Zeit gerade und bleib so lange wie möglich in dieser Position. Schwieriger wird es, wenn du einen Arm oder ein Bein anhebst.']::text[]),
  ('Plate_Pinch', 'de', array['Nimm zwei Hantelscheiben mit breitem Rand und lege sie so aneinander, dass die glatten Seiten nach außen zeigen.', 'Halte beide Scheiben zusammen: Die Finger greifen die Außenseite der einen Scheibe, der Daumen die andere Seite. Das ist die Ausgangsposition.', 'Drücke die Scheiben mit Fingern und Daumen zusammen. Halte so lange, wie du kannst.', 'Mach so viele Sätze, wie dein Programm vorgibt.', 'Wechsle den Arm und wiederhole die Bewegungen.']::text[]),
  ('Plate_Twist', 'de', array['Geh auf den Boden oder eine Trainingsmatte, die Beine ganz gestreckt, der Oberkörper aufrecht. Fasse die Hantelscheibe mit beiden Händen an den Seiten und halte sie mit leicht gebeugten Armen vor dem Bauch.', 'Überkreuze die Beine langsam nahe den Knöcheln und heb sie vom Boden ab. Auch die Knie sind leicht gebeugt. Hinweis: Lehne den Oberkörper etwas zurück, damit du bei der Übung im Gleichgewicht bleibst. Das ist die Ausgangsposition.', 'Führe die Scheibe zur linken Seite und berühre mit ihr den Boden. Atme dabei aus.', 'Komm beim Einatmen in die Ausgangsposition zurück und wiederhole die Bewegung dann zur rechten Körperseite. Tipp: Bewege dich immer langsam und kontrolliert. Ruckartige Bewegungen können den Rücken verletzen.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Platform_Hamstring_Slides', 'de', array['Für diese Bewegung brauchst du einen Holzboden oder etwas Ähnliches. Leg dich mit gestreckten Beinen auf den Rücken. Lege ein Trainingshandtuch oder ein leichtes Gewicht unter deine Ferse. Das ist deine Ausgangsposition.', 'Beginne die Bewegung, indem du das Knie beugst. Das andere Bein bleibt gestreckt.', 'Zieh die Ferse weiter zu dir heran und lass sie dabei über den Boden gleiten.', 'Ist das Knie ganz gebeugt, kehre die Bewegung um und geh in die Ausgangsposition zurück.']::text[]),
  ('Plie_Dumbbell_Squat', 'de', array['Steh aufrecht und halte eine Kurzhantel mit beiden Händen an ihrem unteren Ende. Stell die Beine weiter als schulterbreit auseinander, die Knie leicht gebeugt.', 'Die Zehen zeigen nach außen. Hinweis: Die Arme bleiben während der Übung ruhig. Das ist die Ausgangsposition.', 'Beuge langsam die Knie und geh nach unten, bis die Oberschenkel parallel zum Boden sind. Atme dabei ein, denn das ist der exzentrische Teil der Übung.', 'Drücke dich vor allem über die Fersen zurück in die Ausgangsposition und atme dabei aus.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Plyo_Kettlebell_Pushups', 'de', array['Stell eine Kettlebell auf den Boden. Geh in die Liegestützposition auf die Zehen, eine Hand am Boden, die andere an der Kettlebell, die Ellbogen gestreckt. Das ist deine Ausgangsposition.', 'Beginne, indem du dich mit geradem Rücken so tief wie möglich absenkst.', 'Kehre die Richtung schnell und kraftvoll um und drück dich auf die andere Seite der Kettlebell hinüber, dabei wechselst du die Hand. Senke dich wieder ab und wiederhole die Bewegung hin und her.']::text[]),
  ('Plyo_Push-up', 'de', array['Geh in Bauchlage auf den Boden und stütze dein Gewicht auf Hände und Zehen.', 'Die Arme sind ganz gestreckt, die Hände etwa schulterbreit. Halte den Körper während der ganzen Bewegung gerade. Das ist deine Ausgangsposition.', 'Senke dich ab, indem du die Ellbogen beugst und die Brust zum Boden bringst.', 'Kehre unten die Bewegung um und drück dich durch Strecken der Ellbogen so schnell wie möglich nach oben. Versuche, den Oberkörper so weit hochzudrücken, dass die Hände den Boden verlassen.', 'Kehre in die Ausgangsposition zurück und wiederhole die Übung.', 'Schwieriger wird es, wenn du in der Luft zusätzlich in die Hände klatschst.']::text[]),
  ('Posterior_Tibialis_Stretch', 'de', array['Setz dich hin und lege einen Gürtel, ein Seil oder ein Band um einen Fuß. Das ist deine Ausgangsposition.', 'Das Bein ist gestreckt, die Ferse ohne Bodenkontakt. Zieh am Gürtel, sodass der Fuß nach außen kippt und seine Außenseite zu dir gezogen wird. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Power_Clean', 'de', array['Stell die Füße etwas weiter als schulterbreit auseinander, die Zehen zeigen leicht nach außen.', 'Geh in die Hocke und fasse die Stange im geschlossenen Obergriff. Die Hände greifen etwas weiter als schulterbreit, außerhalb der Knie, die Ellbogen sind ganz gestreckt.', 'Die Stange liegt etwa 1 Zoll vor deinen Schienbeinen, über den Fußballen.', 'Der Rücken ist flach oder leicht im Hohlkreuz, die Brust ist angehoben und herausgestreckt, die Schulterblätter sind zurückgezogen.', 'Halte den Kopf neutral (in Linie mit der Wirbelsäule, weder geneigt noch gedreht) und schau geradeaus. Atme in dieser Phase ein.', 'Atme aus und heb die Stange vom Boden, indem du Hüfte und Knie kraftvoll streckst. Tipp: Der Oberkörper behält seinen Winkel. Beuge dich noch nicht in der Taille und lass die Hüfte nicht vor den Schultern steigen (sonst schiebst du das Gesäß in die Luft und dehnst die Beinbeuger).', 'Die Ellbogen bleiben ganz gestreckt, der Kopf neutral und die Schultern über der Stange.', 'Führe die Stange beim Anheben so dicht wie möglich an den Schienbeinen entlang.', 'Wenn die Stange die Knie passiert, schieb die Hüfte nach vorn und beuge die Knie leicht, damit sie nicht durchgedrückt sind. Tipp: Jetzt sollten deine Oberschenkel an der Stange anliegen.', 'Der Rücken bleibt flach oder leicht im Hohlkreuz, die Ellbogen ganz gestreckt, der Kopf neutral. Tipp: Halte die Luft bis zur nächsten Phase an.', 'Atme ein, streck dann Hüfte und Knie kraftvoll und schnell und geh auf die Zehenspitzen.', 'Halte die Stange so dicht wie möglich am Körper. Tipp: Der Rücken ist flach, die Ellbogen zeigen zur Seite, der Kopf ist neutral. Lass außerdem die Schultern über der Stange und die Arme so lange wie möglich gestreckt.', 'Sind die Gelenke des Unterkörpers ganz gestreckt, zieh die Schultern schnell nach oben, ohne schon die Ellbogen zu beugen. Atme in diesem Teil der Bewegung aus.', 'Wenn die Schultern ihren höchsten Punkt erreichen, beuge die Ellbogen und beginne so, deinen Körper unter die Stange zu ziehen.', 'Zieh mit den Armen weiter, so hoch und so lange es geht. Tipp: Weil diese Phase explosiv ist, ist dein Oberkörper aufrecht oder der Rücken im Hohlkreuz, der Kopf leicht nach hinten geneigt, und die Füße können den Kontakt zum Boden verlieren.', 'Ist der Unterkörper ganz gestreckt und die Stange fast auf ihrer größten Höhe, zieh deinen Körper unter die Stange und dreh die Arme um die Stange herum und unter sie.', 'Beuge gleichzeitig Hüfte und Knie in eine Viertelkniebeuge.', 'Sind die Arme unter der Stange, atme ein und heb dann die Ellbogen, bis die Oberarme parallel zum Boden sind. Lege die Stange vorn auf den Schlüsselbeinen und der vorderen Schultermuskulatur ab.', 'Fang die Stange mit aufrechtem, festem Oberkörper, neutralem Kopf und flach stehenden Füßen. Atme bei dieser Bewegung aus.', 'Steh auf, indem du Hüfte und Knie streckst, bis du ganz aufrecht bist.', 'Zum Absenken lässt du die Muskelspannung in den Armen nach und nach los, sodass die Stange kontrolliert auf die Oberschenkel sinkt. Atme bei dieser Bewegung ein.', 'Beuge gleichzeitig Hüfte und Knie, um den Aufprall der Stange auf den Oberschenkeln abzufedern.', 'Geh mit ganz gestreckten Ellbogen in die Hocke, bis die Stange den Boden berührt.', 'Beginne wieder bei Phase 1 und mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Power_Clean_from_Blocks', 'de', array['Die Langhantel liegt auf Boxen in der gewünschten Höhe. Greif sie knapp außerhalb der Beine. Senke die Hüfte, das Gewicht liegt auf den Fersen, der Rücken ist gerade, der Kopf zeigt nach vorn, die Brust ist oben und die Schultern sind knapp vor der Stange. Das ist deine Ausgangsposition.', 'Beginne den ersten Zug, indem du dich über die Fersen abdrückst und die Knie streckst. Der Winkel des Rückens bleibt gleich, die Arme bleiben gestreckt. Nähert sich die Stange der Mitte der Oberschenkel, beginne die Hüfte zu strecken.', 'Beschleunige wie bei einem Sprung: Streck Hüfte, Knie und Fußgelenke und bring die Stange mit Tempo nach oben. Aktiv mit den Armen zu ziehen sollte dafür nicht nötig sein. Am Ende des zweiten Zugs ist der Körper ganz gestreckt und leicht nach hinten geneigt, die Arme sind noch immer gestreckt.', 'Mit der vollen Streckung gehst du in den dritten Zug über: Zieh die Schultern energisch hoch und beuge die Arme, Ellbogen nach oben und außen. Zieh dich am höchsten Punkt der Streckung so weit unter die Stange, dass du sie auf den Schultern ablegen kannst, und dreh dabei die Ellbogen unter die Stange. Die Stange liegt auf den nach vorn geschobenen Schultern und berührt leicht den Hals, die Hände sind locker.', 'Richte dich sofort auf, indem du dich über die Fersen abdrückst, den Oberkörper aufrecht und die Ellbogen oben hältst. Mach weiter, bis du stehst, und beende die Wiederholung, indem du das Gewicht auf die Boxen zurücklegst.']::text[]),
  ('Power_Jerk', 'de', array['Steh mit dem Gewicht vorn auf den Schultern und beginne mit dem Dip. Die Füße sind direkt unter der Hüfte. Beuge die Knie, ohne die Hüfte nach hinten zu schieben. Geh nur wenig nach unten und kehre die Richtung so kraftvoll wie möglich um.', 'Drück dich über die Fersen ab und erzeuge so viel Tempo und Kraft wie möglich. Nimm unbedingt den Kopf aus dem Weg, wenn die Stange die Schultern verlässt.', 'Sobald die Füße den Boden verlassen, müssen sie so schnell wie möglich in die Fangposition. In dem kurzen Moment, in dem die Füße nicht aktiv gegen die Plattform drücken, treibt dich dein Druck gegen die Stange nach unten. Setze die Füße etwas breiter auf, die Knie sind teilweise gebeugt.', 'Fang die Stange mit durchgestreckten Armen über dem Kopf.', 'Kehre in den Stand zurück.']::text[]),
  ('Power_Partials', 'de', array['Steh mit aufrechtem Oberkörper, in jeder Hand eine Kurzhantel an den lang hängenden Armen. Die Ellbogen sind nah am Oberkörper.', 'Die Handflächen zeigen zum Oberkörper, die Füße stehen etwa schulterbreit. Das ist deine Ausgangsposition.', 'Lass die Arme gestreckt und den Oberkörper ruhig. Heb die Gewichte beim Ausatmen seitlich an, bis sie etwa auf Schulterhöhe sind.', 'Spüre die Kontraktion eine Sekunde lang und senke die Gewichte dann beim Einatmen in die Ausgangsposition ab. Tipp: Lass die Handflächen beim Heben und Senken nach unten zeigen, den kleinen Finger etwas höher. So liegt die Belastung vor allem auf den Schultern.', 'Mach die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Power_Snatch', 'de', array['Zu Beginn liegt eine beladene Langhantel auf dem Boden. Die Stange ist nah an den Schienbeinen oder berührt sie, und du greifst sie weit. Die Füße stehen direkt unter der Hüfte und sind so weit wie nötig nach außen gedreht. Senke die Hüfte, die Brust ist oben, der Blick geht nach vorn. Die Schultern sind knapp vor der Stange. Das ist die Ausgangsposition.', 'Beginne den ersten Zug, indem du dich über den vorderen Teil der Fersen abdrückst und die Stange vom Boden hebst. Der Winkel des Rückens bleibt gleich, bis die Stange die Knie passiert hat.', 'Geh in den zweiten Zug über: Streck Hüfte, Knie und Fußgelenke und treib die Stange so schnell wie möglich nach oben. Die Stange bleibt nah am Körper. Zieh am höchsten Punkt der Streckung die Schultern hoch und lass die Ellbogen zur Seite beugen.', 'Während du die Füße in die etwas breitere Fangposition setzt, zieh dich unter die Stange und bring sie über den Kopf. Du fängst die Stange in einer Teilkniebeuge. Heb sie weiter, bis du sie mit durchgestreckten Armen über dem Kopf hältst.', 'Kehre mit dem Gewicht über dem Kopf in den Stand zurück.']::text[]),
  ('Power_Snatch_from_Blocks', 'de', array['Lege eine beladene Langhantel auf Blöcke oder Ständer in der gewünschten Höhe. Greife die Stange weit. Stell die Füße direkt unter die Hüfte und dreh sie so weit nach außen, wie du es brauchst. Senke die Hüfte, halte die Brust oben und schau nach vorn. Die Schultern liegen knapp vor der Stange, die Ellbogen zeigen nach außen. Das ist die Ausgangsposition.', 'Starte den ersten Zug: Drück dich über den vorderen Teil der Fersen ab und heb die Stange von den Blöcken.', 'Geh in den zweiten Zug über, indem du Hüfte, Knie und Sprunggelenke streckst und die Stange so schnell wie möglich nach oben beschleunigst. Führe sie nah am Körper. Bist du ganz gestreckt, zieh die Schultern hoch und lass die Ellbogen seitlich beugen.', 'Während deine Füße in die Fangposition wandern, zieh dich kraftvoll unter die Stange und bring sie über den Kopf. Die Füße landen knapp außerhalb der Hüfte, so weit ausgedreht wie nötig. Fange die Stange mit ganz gestreckten Armen über dem Kopf, oberhalb einer tiefen Kniebeuge.', 'Halte die Stange über dem vorderen Teil der Fersen, Kopf und Brust bleiben oben, und drück dich über die Fersen in den Stand. Lege das Gewicht vorsichtig auf die Blöcke zurück.']::text[]),
  ('Power_Stairs', 'de', array['Bei den Power Stairs werden Geräte eine Treppe hinaufbewegt. Im Training eignen sich dafür ein Reifen oder eine Kiste.', 'Fass das Gerät mit beiden Händen. Steh breit, Kopf und Brust oben. Drück die Fersen in den Boden und strecke Knie und Hüfte, um das Gewicht vom Boden zu heben.', 'Lehn dich zurück und versuche, das Gewicht auf die Stufe zu schwingen, die meist etwa 16-18" hoch ist. Mit den Beinen darfst du nachhelfen und das Gewicht auf die Stufe schieben.', 'Mach 3-5 Wiederholungen und nimm dann ein schwereres Gewicht. Beweg dich dabei so schnell wie möglich.']::text[]),
  ('Preacher_Curl', 'de', array['Für diese Übung brauchst du eine Scottbank und eine SZ-Stange. Greife die Stange an den engen inneren Griffstellen; am besten reicht sie dir jemand, sonst nimmst du sie von der vorderen Ablage, die die meisten Scottbänke haben. Deine Handflächen zeigen nach vorn und sind durch die Form der Stange leicht nach innen geneigt.', 'Lege die Oberarme und die Brust an das Polster der Bank und halte die Stange auf Schulterhöhe. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis deine Arme gestreckt sind und der Bizeps ganz gedehnt ist.', 'Atme aus und beuge das Gewicht mit dem Bizeps nach oben, bis der Muskel voll angespannt ist und die Stange auf Schulterhöhe liegt. Spanne den Bizeps fest an und halte eine Sekunde.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Preacher_Hammer_Dumbbell_Curl', 'de', array['Nimm in jede Hand eine Kurzhantel, die Handflächen zeigen zueinander (Neutralgriff), und lege beide Oberarme auf das Polster der Scottbank.', 'Atme ein und senke die Kurzhanteln langsam, bis deine Arme gestreckt sind und der Bizeps ganz gedehnt ist.', 'Atme aus und beuge das Gewicht mit dem Bizeps nach oben, bis der Muskel voll angespannt ist und die Kurzhanteln auf Schulterhöhe sind.', 'Spanne den Bizeps oben eine Sekunde lang fest an und wiederhole die Übung dann für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Press_Sit-Up', 'de', array['Lege dich auf eine Bauchbank und lass eine Langhantel auf deiner Brust ruhen. Hake die Beine fest in die Beinhalterung der Bank ein. Das ist die Ausgangsposition.', 'Atme ein und spanne Bauch und Gesäß an. Rolle dann beim Ausatmen den Oberkörper auf wie bei einem Sit-up und drücke gleichzeitig die Langhantel über den Kopf. Tipp: Schieb die Langhantel mit den Armen nach oben, bleib mit der Aufmerksamkeit aber bei der Bauchmuskulatur.', 'Senke den Oberkörper wieder in die Ausgangsposition und führe die Langhantel dabei zurück zum Oberkörper. Atme beim Absenken ein.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Prone_Manual_Hamstring', 'de', array['Für diese Übung brauchst du einen Partner. Lege dich mit gestreckten Beinen auf den Bauch. Dein Partner legt eine Hand an deine Ferse.', 'Beuge das Knie und zieh den Unterschenkel nach oben. Dein Partner hält dagegen, anfangs leicht und im Verlauf der Bewegung immer stärker. Sprecht euch ab, damit der Widerstand passt.', 'Halte oben kurz und führe das Bein dann in die Ausgangsposition zurück, während dein Partner jetzt in die andere Richtung Widerstand gibt.']::text[]),
  ('Prowler_Sprint', 'de', array['Stell den Schlitten auf einen geeigneten Untergrund und belade ihn mit einem passenden Gewicht. Er soll so schwer sein, dass du dich anstrengen musst, aber nicht so schwer, dass du deutlich langsamer wirst.', 'Du kannst die aufrechten oder die tiefen Griffe nehmen. Fass sie mit gestreckten Armen und lehn dich in den Schlitten.', 'Halte eine gute Körperhaltung und drück dich mit kurzen, wechselnden Schritten vom Boden ab. Lauf eine kurze Strecke so schnell du kannst.']::text[]),
  ('Pull_Through', 'de', array['Befestige ein Seil oder einen Griff am unteren Kabelzug und stell dich ein paar Fuß davor. Dreh der Maschine den Rücken zu und steh breit, das Kabel läuft zwischen deinen Beinen.', 'Beuge dich zu Beginn in der Hüfte und greife so weit wie möglich zwischen den Beinen nach hinten. Die Knie bleiben leicht gebeugt. Strecke mit geraden Armen die Hüfte, bis du ganz aufrecht stehst. Zieh nicht mit den Schultern nach oben; die ganze Bewegung kommt aus der Hüfte.']::text[]),
  ('Pullups', 'de', array['Fass die Klimmzugstange mit nach vorn zeigenden Handflächen im vorgesehenen Griff. Hinweis: Beim weiten Griff sind deine Hände weiter auseinander als die Schultern. Beim mittleren Griff sind sie schulterbreit, beim engen Griff enger als schulterbreit.', 'Häng mit gestreckten Armen in der gewählten Griffbreite an der Stange, neige den Oberkörper etwa 30 Grad nach hinten, geh ins Hohlkreuz und schieb die Brust heraus. Das ist deine Ausgangsposition.', 'Zieh Schultern und Oberarme nach unten und hinten und bring den Oberkörper so weit hoch, bis die Stange die obere Brust berührt. Atme in diesem Teil der Bewegung aus. Tipp: Konzentrier dich oben darauf, die Rückenmuskeln fest anzuspannen. Der Oberkörper bleibt auf dem Weg nach oben starr, nur die Arme bewegen sich. Die Unterarme halten nur die Stange und tun sonst nichts.', 'Bleib eine Sekunde oben, beginne dann einzuatmen und lass den Oberkörper langsam in die Ausgangsposition sinken, in der die Arme ganz gestreckt sind und der Latissimus ganz gedehnt ist.', 'Wiederhole die Bewegung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Push-Up_Wide', 'de', array['Setz die Hände weit auseinander und stütz dich auf Händen und Zehenspitzen in der Plank-Position. Die Ellbogen sind gestreckt, der Körper bildet eine Linie. Lass die Hüfte nicht durchhängen. Das ist deine Ausgangsposition.', 'Atme ein und beuge die Ellbogen, sodass die Brust zum Boden sinkt.', 'Strecke die Ellbogen und drück den Oberkörper mit der Brustmuskulatur zurück in die Ausgangsposition. Atme dabei aus.', 'Halte oben kurz die Spannung und wiederhole die Bewegung dann für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Push-Ups_-_Close_Triceps_Position', 'de', array['Lege dich bäuchlings auf den Boden und setz die Hände enger als schulterbreit auf, in der engen Handposition. Halte den Oberkörper mit gestreckten Armen oben.', 'Atme ein und senke dich, bis die Brust fast den Boden berührt.', 'Drück den Oberkörper mit dem Trizeps und einem Teil der Brustmuskulatur zurück in die Ausgangsposition und spanne die Brust an. Atme dabei aus.', 'Halte oben eine Sekunde die Spannung und wiederhole die Bewegung dann für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Push-Ups_With_Feet_Elevated', 'de', array['Lege dich bäuchlings auf den Boden, setz die Hände etwa 36 Zoll auseinander auf und halte den Oberkörper mit gestreckten Armen oben.', 'Stell die Zehenspitzen auf eine Flachbank, damit dein Körper erhöht liegt. Hinweis: Je höher die Bank, desto schwerer wird die Übung.', 'Atme ein und senke dich, bis die Brust fast den Boden berührt.', 'Drück den Oberkörper mit der Brustmuskulatur zurück in die Ausgangsposition und spanne die Brust an. Atme dabei aus.', 'Halte oben eine Sekunde die Spannung und wiederhole die Bewegung dann für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Push-Ups_With_Feet_On_An_Exercise_Ball', 'de', array['Lege dich bäuchlings auf den Boden, setz die Hände etwa 36 Zoll auseinander auf und halte den Oberkörper mit gestreckten Armen oben.', 'Stell die Zehenspitzen auf einen Gymnastikball, damit dein Körper erhöht liegt.', 'Atme ein und senke dich, bis die Brust fast den Boden berührt.', 'Drück den Oberkörper mit der Brustmuskulatur zurück in die Ausgangsposition und spanne die Brust an. Atme dabei aus.', 'Halte oben eine Sekunde die Spannung und wiederhole die Bewegung dann für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Push_Press', 'de', array['Steh etwa hüftbreit und halte die Langhantel vorn auf den Schultern, die Hände etwas weiter als schulterbreit, die Ellbogen leicht vor der Stange.', 'Beuge die Knie ein kleines Stück zu einem kurzen Dip. Der Oberkörper bleibt aufrecht, die Fersen bleiben am Boden.', 'Streck die Beine explosiv und nutze den Schwung, um die Stange über den Kopf zu drücken, bis die Arme ganz gestreckt sind.', 'Senke die Stange kontrolliert auf die Schultern zurück, federe sie mit den Knien ab und wiederhole.']::text[]),
  ('Push_Press_-_Behind_the_Neck', 'de', array['Steh mit der Stange hinten auf den Schultern und beginne mit dem Dip. Die Füße stehen direkt unter der Hüfte; beuge die Knie, ohne die Hüfte nach hinten zu schieben. Geh nur ein kleines Stück nach unten und kehre die Bewegung so explosiv wie möglich um. Drück dich über die Fersen ab, um möglichst viel Tempo und Kraft aufzubauen, und führe die Stange senkrecht nach oben.', 'Nutze diesen Schwung und strecke die Arme, um das Gewicht ganz über den Kopf zu drücken.', 'Kehre in die Ausgangsposition zurück und fange den Aufprall mit den Beinen ab.']::text[]),
  ('Push_Up_to_Side_Plank', 'de', array['Geh auf den Zehenspitzen in die Liegestützposition, die Hände etwas weiter als schulterbreit.', 'Beuge die Ellbogen für einen Liegestütz. Dein Körper bleibt beim Absenken gerade.', 'Mach einen Liegestütz, verlagere beim Hochkommen das Gewicht auf die linke Körperseite und dreh dich zur Seite, während du den rechten Arm zur Decke streckst, in den Seitstütz.', 'Setz den Arm wieder am Boden ab, mach einen weiteren Liegestütz und dreh dich dann zur anderen Seite.', 'Wiederhole die Abfolge im Seitenwechsel für 10 oder mehr Wiederholungen.']::text[]),
  ('Pushups', 'de', array['Geh bäuchlings auf den Boden, setz die Hände etwa 36 Zoll auseinander auf und halte den Oberkörper mit gestreckten Armen oben.', 'Atme dann ein und lass dich sinken, bis die Brust knapp über dem Boden ist.', 'Atme nun aus und drück den Oberkörper wieder in die Ausgangsposition, dabei spannst du die Brust an.', 'Halte oben kurz mit angespannter Brust und senke dich dann erneut, für so viele Wiederholungen wie nötig.']::text[]),
  ('Pushups_Close_and_Wide_Hand_Positions', 'de', array['Lege dich bäuchlings mit geradem Körper hin, die Zehenspitzen am Boden. Für die weite Handposition setzt du die Hände weiter als schulterbreit auf, für die enge Handposition enger als schulterbreit. Halte den Oberkörper mit gestreckten Armen oben.', 'Atme ein und senke dich, bis die Brust fast den Boden berührt.', 'Drück den Oberkörper mit der Brustmuskulatur zurück in die Ausgangsposition und spanne die Brust an. Atme dabei aus.', 'Halte oben eine Sekunde die Spannung und wiederhole die Bewegung dann für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Pyramid', 'de', array['Rolle mit dem Oberkörper nach vorn über den Ball, bis die Hüfte oben auf dem Ball liegt und der höchste Punkt deines Körpers ist.', 'Stütz Hände und Füße auf den Boden. Je nach Größe des Balls, deiner Beweglichkeit und der Länge deiner Arme und Beine können Arme und Beine gestreckt oder leicht gebeugt sein. Die Position baut außerdem stabilisierende Kraft in Rumpf und Schultern auf.']::text[]),
  ('Quad_Stretch', 'de', array['Lege dich auf die Seite. Schlinge einen Gürtel, ein Seil oder ein Band um den Fuß des oberen Beins. Beuge das Knie und strecke die Hüfte, versuche mit dem Fuß das Gesäß zu erreichen und halte den Gürtel mit den Händen. Das ist deine Ausgangsposition.', 'Führe den Gürtel über die Schulter oder über den Kopf und zieh sanft, um die Dehnung im Quadrizeps zu verstärken. Halte 10-20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Quadriceps-SMR', 'de', array['Lege dich bäuchlings auf den Boden und stütz dich auf Hände oder Unterarme. Schieb eine Faszienrolle unter den Quadrizeps eines Beins und halte den Fuß vom Boden weg. Lass das Bein so locker wie möglich. Das ist deine Ausgangsposition.', 'Bring so viel Gewicht auf dieses Bein, wie du aushältst, und rolle von oberhalb des Knies bis unterhalb der Hüfte. Bleib auf verspannten Stellen 10-30 Sekunden. Wechsle die Seite.']::text[]),
  ('Quick_Leap', 'de', array['Für diese Übung brauchst du eine Box.', 'Stell dich mit Blick zur Box 1-2 Fuß vor ihre Kante.', 'Spring aus der Hüfte heraus auf die Box und lande auf beiden Beinen. Achte darauf, mit gebeugten Beinen und flachen Füßen zu landen.', 'Strecke sofort nach der Landung den ganzen Körper und schwing die Arme über den Kopf, um explosiv von der Box abzuspringen. Fange die Landung mit den Beinen ab.']::text[]),
  ('Rack_Delivery', 'de', array['Mit dieser Übung lernst du, die Langhantel in die Rack-Position auf den Schultern zu bringen. Halte eine Stange in der Vogelscheuchen-Position: Oberarme parallel zum Boden, Unterarme hängen nach unten. Nimm den Hakengriff, die Finger liegen über den Daumen.', 'Dreh die Ellbogen um die Stange herum, sodass sie auf den Schultern ankommt. Lockere den Griff, sobald die Ellbogen nach vorn kommen. Schieb die Schultern nach vorn, damit sie eine Ablage für die Stange bilden; die Stange berührt leicht den Hals.', 'Die Stange muss die ganze Zeit nah am Körper bleiben, denn bei höherer Last führt jeder Abstand zu einem ungewollten Aufprall. Wird die Bewegung flüssiger, kannst du Tempo und Last steigern, bevor du weitergehst.']::text[]),
  ('Rack_Pull_with_Bands', 'de', array['Lege die Stange in einem Power Rack auf die Ablagen. Stell die Ablagen auf die gewünschte Höhe: knapp unter den Knien, knapp darüber oder auf Höhe der Oberschenkelmitte. Befestige Bänder am Fuß des Racks oder fixiere sie mit Kurzhanteln und mach das andere Ende an der Stange fest. Eventuell musst du die Bänder durch sich selbst schlingen, damit sie Spannung haben.', 'Geh an der Stange in eine saubere Kreuzheben-Position: Füße unter der Hüfte, Griff schulterbreit, Rücken im Hohlkreuz, Hüfte nach hinten, damit die Beinbeuger arbeiten. Weil das Gewicht meist schwer ist, helfen dir Kreuzgriff, Hakengriff oder Zughilfen beim Halten.', 'Schau nach vorn, strecke Hüfte und Knie und zieh das Gewicht nach oben und hinten bis zur vollen Streckung. Nimm am Ende der Bewegung die Schultern zurück. Lege das Gewicht wieder auf die Ablagen und wiederhole.']::text[]),
  ('Rack_Pulls', 'de', array['Lege die Stange in einem Power Rack auf die Ablagen. Stell die Ablagen auf die gewünschte Höhe: knapp unter den Knien, knapp darüber oder auf Höhe der Oberschenkelmitte. Geh an der Stange in eine saubere Kreuzheben-Position: Füße unter der Hüfte, Griff schulterbreit, Rücken im Hohlkreuz, Hüfte nach hinten, damit die Beinbeuger arbeiten. Weil das Gewicht meist schwer ist, helfen dir Kreuzgriff, Hakengriff oder Zughilfen beim Halten.', 'Schau nach vorn, strecke Hüfte und Knie und zieh das Gewicht nach oben und hinten bis zur vollen Streckung. Nimm am Ende der Bewegung die Schultern zurück.', 'Lege das Gewicht wieder auf die Ablagen und wiederhole.']::text[]),
  ('Rear_Leg_Raises', 'de', array['Geh auf einer Trainingsmatte in den Vierfüßlerstand. Schau nach vorn und beuge die Knie so, dass Beinbeuger und Waden einen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Strecke ein Bein nach oben und hinten, dabei strecken sich Knie und Hüfte. Mach 5-10 Wiederholungen und wechsle dann die Seite.']::text[]),
  ('Recumbent_Bike', 'de', array['Setz dich auf das Rad und stell den Sitz passend zu deiner Körpergröße ein.', 'Wähle im Menü die gewünschte Option. Eventuell musst du erst treten, damit sich das Gerät einschaltet. Du kannst die manuelle Einstellung nutzen oder ein Programm wählen. Meist lassen sich Alter und Gewicht eingeben, um die beim Training verbrannten Kalorien zu schätzen. Den Widerstand kannst du während des Trainings jederzeit ändern. Über die Griffe lässt sich die Herzfrequenz messen, damit du bei einer passenden Intensität bleibst.', 'Liegeräder sind bequem, gut für Herz und Kreislauf und belasten weniger als andere Aktivitäten. Eine Person mit 150 lb verbrennt bei 30 Minuten Radfahren in mäßigem Tempo etwa 230 Kalorien, beim Laufen wären es 450 Kalorien oder mehr.']::text[]),
  ('Return_Push_from_Stance', 'de', array['Für diesen Drill brauchst du einen Partner.', 'Starte in einem athletischen 2- oder 3-Punkt-Stand.', 'Bring dich auf das Signal hin in Position, um den Pass deines Partners anzunehmen.', 'Fange den Medizinball mit beiden Händen und wirf ihn sofort zu deinem Partner zurück.', 'Du kannst den Drill abwandeln, indem du verschiedene Laufwege läufst.']::text[]),
  ('Reverse_Band_Bench_Press', 'de', array['Stell eine Bank in ein Power Rack und bring die Stange auf die richtige Höhe. Befestige Bänder an Bandhaltern oder oben am Rack und achte darauf, dass du richtig unter den Bändern liegen wirst. Mach das andere Ende an der Langhantel fest.', 'Lege dich auf die Bank, zieh die Füße unter dich und geh ins Hohlkreuz. Stütz dich an der Stange ab, heb die Schultern von der Bank und zieh sie zurück, die Schulterblätter drückst du zusammen. Drück mit den Füßen, um den Trapez in die Bank zu pressen. Halte diese Körperspannung während der ganzen Bewegung. Egal wie weit du greifst, deine Hand soll den Ring auf der Stange bedecken.', 'Heb die Stange aus dem Rack, ohne die Schultern nach vorn zu schieben. Drück die Stange fest zusammen und versuche, sie auseinanderzuziehen. Senke sie zur unteren Brust oder zum oberen Bauch. Stange, Handgelenk und Ellbogen bleiben immer in einer Linie.', 'Halte kurz, wenn die Langhantel den Oberkörper berührt, und drück sie dann mit aller Kraft nach oben. Die Ellbogen bleiben bis zur vollen Streckung eng am Körper.']::text[]),
  ('Reverse_Band_Box_Squat', 'de', array['Stell dich in ein Power Rack, hinter dir steht eine Box in passender Höhe. Häng die Bänder an Bandhalter oder oben ans Rack, sodass sie bei der Kniebeuge genau über der Stange sind. Mach das andere Ende an der Stange fest.', 'Geh unter die Stange und lege sie hinten auf die Schultern. Drück die Schulterblätter zusammen und dreh die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Heb die Stange aus dem Rack, mit festem Hohlkreuz im unteren Rücken, und geh einen Schritt zurück in Position. Ein breiterer Stand betont Rücken, Gesäß, Adduktoren und Beinbeuger stärker, ein engerer entwickelt den Quadrizeps mehr. Schau weiter nach vorn.', 'Halte Rücken, Schultern und Rumpf fest und schieb Knie und Po nach außen, wenn du nach unten gehst. Setz dich mit der Hüfte nach hinten, bis du auf der Box sitzt. Im Idealfall stehen die Schienbeine senkrecht zum Boden. Halte auf der Box kurz an und entspanne die Hüftbeuger. Federe niemals von der Box ab.', 'Lass das Gewicht auf den Fersen, drück Füße und Knie nach außen und stoß dich von der Box nach oben ab, der Kopf führt die Bewegung an. Geh weiter nach oben und bleib von Kopf bis Fuß fest. Lege die Langhantel vorsichtig ins Rack zurück.']::text[]),
  ('Reverse_Band_Deadlift', 'de', array['Platziere die Stange in einem Power Rack. Befestige Bänder oben am Rack, an Bandhaltern oder am Rahmen selbst, und mach ihr anderes Ende an der Stange fest.', 'Tritt so an die Stange, dass sie mittig über deinen Füßen liegt. Die Füße stehen etwa hüftbreit. Beuge dich in der Hüfte und greife die Stange schulterbreit, die Schulterblätter dürfen dabei nach vorn gleiten. In der Regel nimmst du den Obergriff, bei schwereren Sätzen den Kreuzgriff.', 'Stehen Füße und Griff, atme tief ein, senke dann die Hüfte und beuge die Knie, bis die Schienbeine die Stange berühren. Schau nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drück dich über die Fersen ab, um das Gewicht nach oben zu bewegen.', 'Ist die Stange an den Knien vorbei, zieh sie kraftvoll nach hinten: Zieh die Schulterblätter zusammen und schieb die Hüfte nach vorn an die Stange.', 'Senke die Stange, indem du dich in der Hüfte beugst, und führe sie zum Boden.']::text[]),
  ('Reverse_Band_Power_Squat', 'de', array['Stell dich in ein Power Rack, Ablagen und Stange sind auf passender Höhe. Belade die Stange und befestige dann Bänder oben am Rack, an Haltern oder am Rahmen selbst. Mach ihr anderes Ende an der Stange fest.', 'Geh unter die Stange und lege sie hinten auf die Schultern. Drück die Schulterblätter zusammen und dreh die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Heb die Stange aus dem Rack, mit festem Hohlkreuz im unteren Rücken, und geh einen Schritt zurück in Position. Steh breit, um Rücken, Gesäß, Adduktoren und Beinbeuger stärker zu betonen.', 'Schau weiter nach vorn. Halte Rücken, Schultern und Rumpf fest und schieb Knie und Po nach außen, wenn du nach unten gehst. Setz dich mit der Hüfte so weit wie möglich nach hinten. Im Idealfall stehen die Schienbeine senkrecht zum Boden. Liegt die Stange tiefer, musst du den Oberkörper stärker vorneigen, damit sie über den Fersen bleibt. Geh so tief, bis du unter die Parallele kommst, das heißt: Die Hüftbeuge liegt auf einer Linie mit der Oberkante des Knies.', 'Lass das Gewicht auf den Fersen, drück Füße und Knie nach außen und stoß dich nach oben, der Kopf führt die Bewegung an. Geh weiter nach oben, von Kopf bis Fuß fest, bis du wieder in der Ausgangsposition bist.']::text[]),
  ('Reverse_Band_Sumo_Deadlift', 'de', array['Lege eine beladene Stange in einem Power Rack auf den Boden. Befestige Bänder oben am Rack, an Haltern oder am Rahmen selbst, und mach das andere Ende an der Langhantel fest.', 'Tritt so an die Stange, dass sie über der Fußmitte verläuft. Stell die Füße sehr weit auseinander, nah an die Scheibenaufnahmen. Beuge dich in der Hüfte und greife die Stange. Die Arme hängen senkrecht unter den Schultern, innerhalb der Beine; möglich sind Obergriff, Kreuzgriff oder Hakengriff. Lass die Schultern locker, das macht deine Arme praktisch länger.', 'Atme ein, senke dann die Hüfte, Blick nach vorn, Brust oben. Drück dich vom Boden ab, als wolltest du die Füße auseinanderschieben, das Gewicht liegt auf der hinteren Fußhälfte. Strecke Hüfte und Knie.', 'Wenn die Stange die Knie passiert, lehn dich zurück und schieb die Hüfte an die Stange, die Schulterblätter ziehst du zusammen.', 'Bring das Gewicht zum Boden zurück, indem du dich in der Hüfte beugst und es auf dem Weg nach unten kontrollierst.']::text[]),
  ('Reverse_Barbell_Curl', 'de', array['Steh aufrecht und halte eine Langhantel schulterbreit, die Ellbogen nah am Körper. Die Handflächen zeigen nach unten (Obergriff). Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig und beuge das Gewicht beim Ausatmen nach oben, indem du den Bizeps anspannst. Nur die Unterarme bewegen sich. Mach weiter, bis der Bizeps voll angespannt ist und die Stange auf Schulterhöhe liegt. Halte dort eine Sekunde und spanne den Muskel fest an.', 'Atme ein und führe die Stange langsam in die Ausgangsposition zurück.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Barbell_Preacher_Curls', 'de', array['Greife eine SZ-Stange schulterbreit im Obergriff, die Handflächen zeigen nach unten (proniert).', 'Lege nun beide Oberarme auf das Polster der Scottbank, die Arme sind gestreckt. Das ist deine Ausgangsposition.', 'Atme aus und beuge das Gewicht mit dem Bizeps nach oben, bis er voll angespannt ist und die Stange auf Schulterhöhe liegt. Spanne den Bizeps oben eine Sekunde lang fest an.', 'Atme ein und senke die Stange langsam, bis die Oberarme gestreckt sind und der Bizeps ganz gedehnt ist.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Cable_Curl', 'de', array['Befestige eine Stange am unteren Kabelzug. Steh aufrecht und greife sie schulterbreit im Obergriff (proniert, Handflächen nach unten). Halte außerdem die Ellbogen nah am Körper. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig und beuge das Gewicht beim Ausatmen nach oben, indem du den Bizeps anspannst. Nur die Unterarme bewegen sich. Mach weiter, bis der Bizeps voll angespannt ist und die Stange auf Schulterhöhe liegt. Halte dort eine Sekunde und spanne den Muskel fest an.', 'Atme ein und führe die Stange langsam in die Ausgangsposition zurück.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Crunch', 'de', array['Lege dich mit gestreckten Beinen auf den Boden, die Arme neben dem Oberkörper, die Handflächen am Boden. Die Arme bleiben während der ganzen Übung ruhig.', 'Heb die Beine, bis die Oberschenkel senkrecht zum Boden stehen; die Füße sind zusammen und parallel zum Boden. Das ist die Ausgangsposition.', 'Atme ein und zieh die Beine zum Oberkörper, dabei rollst du das Becken nach hinten und hebst die Hüfte vom Boden. Am Ende der Bewegung berühren die Knie die Brust.', 'Halte die Spannung eine Sekunde und führe die Beine beim Ausatmen in die Ausgangsposition zurück.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Flyes', 'de', array['Lege dich bäuchlings auf eine Schrägbank, Brust und Bauch drücken gegen das Polster. Halte in jeder Hand eine Kurzhantel, die Handflächen zeigen zueinander (Neutralgriff).', 'Strecke die Arme vor dir aus, sodass sie senkrecht zur Neigung der Bank stehen. Die Beine bleiben ruhig, du drückst die Fußballen in den Boden. Das ist die Ausgangsposition.', 'Behalte die leichte Beugung der Ellbogen bei und führe die Gewichte beim Ausatmen in einem Bogen zur Seite und voneinander weg. Tipp: Zieh die Schulterblätter zusammen, um das Beste aus der Übung herauszuholen.', 'Heb die Arme, bis sie parallel zum Boden sind.', 'Spür die Anspannung und senke die Gewichte beim Einatmen langsam in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Flyes_With_External_Rotation', 'de', array['Stell eine Schrägbank auf einen 30-Grad-Winkel und lege dich bäuchlings darauf, Brust und Bauch drücken gegen das Polster.', 'Halte in jeder Hand eine Kurzhantel, die Handflächen zeigen zum Boden. Die Arme sind vor dir und stehen senkrecht zur Neigung der Bank. Tipp: Die Ellbogen sind leicht gebeugt. Die Beine bleiben ruhig, du drückst die Fußballen in den Boden (die Fersen berühren den Boden nicht). Das ist die Ausgangsposition.', 'Behalte die leichte Beugung der Ellbogen bei und führe die Gewichte beim Ausatmen in einem Bogen nach außen und voneinander weg.', 'Dreh beim Anheben die Handgelenke um 90 Grad nach außen, sodass aus dem Obergriff (proniert, Handflächen nach unten) ein Neutralgriff wird, bei dem die Handflächen zueinander zeigen. Tipp: Zieh die Schulterblätter zusammen, um das Beste aus der Übung herauszuholen.', 'Heb die Arme, bis sie auf Kopfhöhe sind.', 'Spür die Anspannung und senke die Gewichte beim Einatmen langsam in die Ausgangsposition.', 'Wiederhole die Übung für die vorgesehene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Grip_Bent-Over_Rows', 'de', array['Greife eine Langhantel im Untergriff, die Handflächen zeigen nach oben, und stelle dich aufrecht hin.', 'Beuge die Knie leicht und neige den Oberkörper aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Der Rücken bleibt dabei gerade. Tipp: Halte den Kopf oben. Die Langhantel hängt direkt vor dir, deine Arme stehen senkrecht zum Boden und zum Oberkörper. Das ist deine Ausgangsposition.', 'Atme aus und ziehe die Langhantel nach oben, ohne den Oberkörper zu bewegen. Die Ellbogen bleiben eng am Körper, die Unterarme halten das Gewicht nur und leisten sonst keine Arbeit. Spanne oben die Rückenmuskeln fest an und halte eine Sekunde.', 'Atme ein und senke das Gewicht langsam wieder in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Grip_Triceps_Pushdown', 'de', array['Befestige eine Stange, gerade oder SZ, am oberen Kabelzug.', 'Stelle dich mit dem Gesicht zur Stange und greife sie schulterbreit im Untergriff, die Handflächen zeigen nach oben. Ziehe die Stange mit dem Latissimus nach unten, bis deine Arme ganz gestreckt neben dem Körper sind. Tipp: Die Ellbogen liegen seitlich am Körper an, die Füße stehen schulterbreit auseinander. Das ist die Ausgangsposition.', 'Atme ein und lass die Stange langsam nach oben kommen, bis sie auf Brusthöhe ist. Nur die Unterarme bewegen sich. Ellbogen und Oberarme bleiben die ganze Zeit ruhig am Körper.', 'Atme dann aus und drücke die Stange wieder nach unten in die Ausgangsposition. Spanne dabei den Trizeps kräftig an.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Hyperextension', 'de', array['Lege ein passendes Gewicht auf und stelle dann die Füße zwischen die Polster. Lege dich auf das obere Polster, sodass deine Hüfte hinten über die Kante hängt, und halte dich an den Griffen fest, damit du nicht verrutschst.', 'Beginne die Bewegung, indem du die Hüfte beugst und die Beine nach vorn ziehst.', 'Strecke nun die Hüfte und schwinge die Beine nach hinten. Ganz wichtig: Überstrecke die Hüfte dabei nicht, sondern höre kurz vor dem Ende deines vollen Bewegungsumfangs auf.', 'Beuge die Hüfte wieder und ziehe den Schlitten so weit nach vorn, wie du kannst.', 'Mache die gewünschte Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Machine_Flyes', 'de', array['Stelle die Griffe ganz nach hinten. Wähle ein passendes Gewicht und stelle den Sitz so ein, dass die Griffe auf Schulterhöhe sind. Fasse die Griffe so, dass die Handflächen nach innen zeigen. Das ist deine Ausgangsposition.', 'Ziehe die Hände in einem Halbkreis zur Seite und nach hinten und spanne dabei die hintere Schultermuskulatur an.', 'Halte die Arme während der ganzen Bewegung leicht gebeugt. Die gesamte Bewegung kommt aus dem Schultergelenk.', 'Halte hinten kurz inne und führe das Gewicht langsam in die Ausgangsposition zurück.']::text[]),
  ('Reverse_Plate_Curls', 'de', array['Stelle dich aufrecht hin und halte eine Hantelscheibe mit beiden Händen, die Arme ganz gestreckt. Greife im Obergriff, die Handflächen zeigen nach unten: Die Finger liegen auf der rauen Seite der Scheibe, die Daumen auf der glatten. Hinweis: Am besten fasst du die Scheibe auf 11 Uhr und 1 Uhr.', 'Stelle die Füße schulterbreit auseinander und halte die Scheibe nah an der Leiste. Das ist die Ausgangsposition.', 'Atme aus und hebe die Scheibe langsam an, bis Bizeps und Unterarme sich berühren. Die Ellbogen bleiben am Körper, die Oberarme bewegen sich nicht. Die Scheibe sollte jetzt gleichmäßig auf einer Linie mit deinem Oberkörper sein.', 'Spüre die Anspannung eine Sekunde lang, atme dann ein und senke das Gewicht wieder in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Reverse_Triceps_Bench_Press', 'de', array['Lege dich mit dem Rücken auf eine Flachbank. Nimm die Stange im engen Untergriff, etwa schulterbreit, aus der Ablage und halte sie gerade über dir. Die Arme sind durchgestreckt und stehen senkrecht zum Boden. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis du sie auf der Mitte der Brust spürst. Tipp: Anders als beim normalen Bankdrücken bleiben die Ellbogen hier die ganze Zeit nah am Oberkörper, damit der Trizeps möglichst viel arbeitet.', 'Halte eine Sekunde inne, atme dann aus und drücke die Stange mit dem Trizeps zurück in die Ausgangsposition. Strecke die Arme oben durch, halte eine Sekunde und senke dann wieder langsam ab. Tipp: Der Weg nach unten sollte mindestens doppelt so lange dauern wie der Weg nach oben.', 'Mache die vorgegebene Anzahl an Wiederholungen.', 'Lege die Stange am Ende zurück in die Ablage.']::text[]),
  ('Rhomboids-SMR', 'de', array['Lege dich mit dem Rücken auf den Boden. Schiebe eine Faszienrolle unter den oberen Rücken und kreuze die Arme vor dir, sodass die Schultern nach vorn kommen. Das ist deine Ausgangsposition.', 'Hebe die Hüfte vom Boden ab, sodass dein Gewicht auf der Faszienrolle liegt. Verlagere das Gewicht immer auf eine Seite und rolle über den mittleren und oberen Rücken. Bleibe an verspannten Stellen 10-30 Sekunden.']::text[]),
  ('Rickshaw_Carry', 'de', array['Stelle den Rahmen an den Startpunkt und belade ihn mit einem passenden Gewicht. Stelle dich in die Mitte des Rahmens, fasse die Griffe und drücke dich über die Fersen nach oben, um ihn anzuheben. Brust und Kopf bleiben oben, der Rücken gerade.', 'Gehe sofort zügig los, mit schnellen, kontrollierten Schritten. Halte die Brust oben und den Blick nach vorn und atme weiter. Setze den Rahmen am Boden ab, sobald du am Ziel bist.']::text[]),
  ('Rickshaw_Deadlift', 'de', array['Belade den Rahmen mit dem gewünschten Gewicht. Stelle dich mittig zwischen die Griffe, die Füße etwa hüftbreit auseinander. Beuge dich aus der Hüfte nach unten, fasse die Griffe und lass die Schulterblätter dabei nach vorn gleiten.', 'Wenn Stand und Griff sitzen, atme tief ein, senke dann die Hüfte und beuge die Knie. Schaue nach vorn, halte die Brust oben und den Rücken im Hohlkreuz und drücke dich über die Fersen ab, um das Gewicht nach oben zu bewegen. Während es steigt, ziehst du die Schulterblätter zusammen und schiebst die Hüfte nach vorn.', 'Zum Absenken beugst du die Hüfte und führst das Gewicht zum Boden.']::text[]),
  ('Ring_Dips', 'de', array['Fasse in jede Hand einen Ring und springe leicht ab, um mit durchgestreckten Armen in die Ausgangsposition zu kommen.', 'Beuge die Ellbogen und senke den Körper, bis deine Arme über 90 Grad hinaus gebeugt sind. Schwinge nicht und bleibe auf dem ganzen Weg nach unten in guter Haltung.', 'Strecke dann die Ellbogen und drücke dich wieder hoch in die Ausgangsposition.', 'Mache die gewünschte Anzahl an Wiederholungen.']::text[]),
  ('Rocket_Jump', 'de', array['Stelle dich locker hin, die Füße schulterbreit auseinander, die Arme nah am Körper.', 'Gehe zum Start in die halbe Kniebeuge und springe dann explosiv so hoch wie möglich.', 'Strecke den ganzen Körper durch und greife so weit wie möglich über den Kopf. Fange die Landung mit den Beinen ab.']::text[]),
  ('Rocking_Standing_Calf_Raise', 'de', array['Aus Sicherheitsgründen machst du diese Übung am besten in einem Kniebeugenständer. Lege die Stange zuerst auf die Höhe, die am besten zu deiner Größe passt. Wenn die Höhe stimmt und die Stange beladen ist, tritt unter sie und lege sie hinten auf die Schultern, knapp unterhalb des Nackens.', 'Halte die Stange mit beiden Händen, links und rechts, und hebe sie aus der Ablage: Drücke dich mit den Beinen hoch und richte gleichzeitig den Oberkörper auf.', 'Tritt vom Ständer weg und nimm einen mittleren, schulterbreiten Stand ein, die Zehen zeigen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht. Auch der Rücken bleibt gerade, die Knie sind leicht gebeugt und nie durchgedrückt. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Fersen: Strecke die Sprunggelenke so weit wie möglich und spanne die Waden an. Die Knie bleiben die ganze Zeit ruhig. Abgesehen von der leichten Beugung, die du beim Aufstellen eingenommen hast, beugen sie sich zu keinem Zeitpunkt. Halte die Anspannung eine Sekunde, bevor du wieder nach unten gehst.', 'Atme ein und gehe langsam zurück in die Ausgangsposition: Senke die Fersen und beuge die Sprunggelenke, bis die Waden gedehnt sind.', 'Atme nun aus und hebe die Zehen an, indem du die Schienbeinmuskeln vorn am Unterschenkel anspannst.', 'Halte eine Sekunde und senke die Zehen beim Einatmen wieder ab.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Rocky_Pull-Ups_Pulldowns', 'de', array['Fasse die Klimmzugstange weit, die Handflächen zeigen nach vorn.', 'Du hängst mit gestreckten Armen in der gewählten Griffbreite an der Stange. Lehne den Oberkörper nun etwa 30 Grad zurück, gehe im unteren Rücken ins Hohlkreuz und strecke die Brust heraus. Das ist deine Ausgangsposition.', 'Ziehe dich hoch, bis die Stange die obere Brust berührt, indem du Schultern und Oberarme nach unten und hinten führst. Atme bei diesem Teil der Bewegung aus. Tipp: Konzentriere dich am höchsten Punkt darauf, die Rückenmuskeln fest anzuspannen. Der Oberkörper bleibt auf seinem Weg in sich ruhig, nur die Arme bewegen sich. Die Unterarme halten nur die Stange und leisten sonst keine Arbeit.', 'Halte die Anspannung eine Sekunde, atme dann ein und lass dich langsam in die Ausgangsposition hinab, bis die Arme ganz gestreckt sind und der Latissimus voll gedehnt ist.', 'Wiederhole nun dieselbe Bewegung, aber halte den Oberkörper diesmal beim Hochziehen gerade, sodass die Stange den Nacken berührt und nicht die obere Brust. Tipp: Neige den Kopf leicht nach vorn, das hilft dir, diesen Teil der Übung sauber auszuführen.', 'Wenn du wieder unten in der Ausgangsposition bist, wiederhole die Übung so oft, wie dein Trainingsplan es vorgibt.']::text[]),
  ('Romanian_Deadlift', 'de', array['Lege eine Langhantel vor dir auf den Boden und greife sie im Obergriff, Handflächen nach unten, etwas weiter als schulterbreit. Tipp: Je nach Gewicht brauchst du vielleicht Handgelenkbandagen und außerdem eine erhöhte Plattform, die einen größeren Bewegungsumfang erlaubt.', 'Beuge die Knie leicht. Die Schienbeine stehen senkrecht, die Hüfte ist hinten, der Rücken gerade. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Stange aus der Hüfte an. Rücken und Arme bleiben dabei die ganze Zeit vollständig gestreckt. Tipp: Bewege dich nicht schnell, sondern gleichmäßig und kontrolliert.', 'Wenn du ganz aufrecht stehst, senke die Stange, indem du die Hüfte nach hinten schiebst. Anders als bei der Kniebeuge beugst du die Knie nur leicht. Tipp: Atme zu Beginn der Bewegung tief ein und halte die Brust oben. Halte beim Absenken die Luft an und atme aus, wenn du die Bewegung abschließt.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Romanian_Deadlift_from_Deficit', 'de', array['Stelle dich hin und halte eine Stange mit gestreckten Armen vor dir. Wenn du dich auf eine erhöhte Plattform stellst, wird der Bewegungsumfang größer.', 'Beuge zuerst die Knie leicht und dann die Hüfte: Schiebe den Po so weit wie möglich nach hinten und senke den Oberkörper so tief, wie deine Beweglichkeit es zulässt. Der Rücken bleibt die ganze Zeit vollständig gestreckt, die Stange bleibt an den Beinen. Wenn du es richtig machst, spürst du eine starke Spannung im Beinbeuger.', 'Kehre die Bewegung um und komme zurück in die Ausgangsposition.']::text[]),
  ('Rope_Climb', 'de', array['Fasse das Seil mit beiden Händen über dem Kopf. Ziehe daran nach unten und springe leicht ab.', 'Wickle das Seil um ein Bein und klemme es zwischen den Füßen ein. Greife mit den Armen so hoch wie möglich und halte das Seil fest.', 'Löse die Füße vom Seil, ziehe dich mit den Armen hoch und bringe die Knie zur Brust.', 'Klemme das Seil wieder mit den Füßen ein, richte dich auf und greife erneut weit oben nach. Mache so weiter, bis du am oberen Ende des Seils bist.', 'Zum Herunterkommen lockerst du den Halt der Füße am Seil und gleitest nach unten, indem du Hand unter Hand nachgreifst.']::text[]),
  ('Rope_Crunch', 'de', array['Knie dich 1-2 Fuß vor einen Kabelzug, an dem ein Seil befestigt ist.', 'Wähle ein passendes Gewicht, greife über den Kopf und fasse das Seil mit beiden Händen. In der Ausgangsposition ist dein Oberkörper aufrecht.', 'Runde nun die Wirbelsäule ein und ziehe das Kabel nach unten. Versuche dabei, den Brustkorb zu den Beinen zu bringen.', 'Halte unten kurz inne und kehre dann langsam in die Ausgangsposition zurück.', 'Du kannst die Übung auch mit Drehung oder zur Seite machen, um die schrägen Bauchmuskeln zu trainieren.']::text[]),
  ('Rope_Jumping', 'de', array['Nimm in jede Hand ein Ende des Seils. Das Seil liegt hinter dir auf dem Boden. Hebe die Arme und schwinge das Seil über den Kopf nach vorn unten. Springe darüber, sobald es den Boden erreicht. Suche dir ein Schwungtempo, das du durchhalten kannst. Für Abwechslung sorgen verschiedene Geschwindigkeiten und Techniken.', 'Seilspringen macht Spaß, fordert deine Koordination und kostet viel Energie. Eine Person mit 150 lb verbrennt in 30 Minuten Seilspringen etwa 350 Kalorien, beim Laufen sind es zum Vergleich über 450 Kalorien.']::text[]),
  ('Rope_Straight-Arm_Pulldown', 'de', array['Befestige ein Seil am oberen Kabelzug und wähle dein Gewicht. Stelle dich ein paar Fuß vom Kabelzug entfernt in Schrittstellung hin und fasse das Seil mit beiden Händen. Neige dich mit geradem Rücken aus der Hüfte nach vorn, die Arme sind vor dir nach oben gestreckt. Das ist deine Ausgangsposition.', 'Lass die Arme gestreckt und ziehe das Seil aus den Schultern heraus nach unten bis zu den Oberschenkeln.', 'Halte unten kurz inne und spanne den Latissimus fest an.', 'Gehe zurück in die Ausgangsposition, ohne das Gewicht ganz auf dem Gewichtsblock abzulegen.']::text[]),
  ('Round_The_World_Shoulder_Stretch', 'de', array['Stelle dich aufrecht hin, die Beine geschlossen, und halte eine Gymnastikstange oder einen Besenstiel.', 'Halte den Stab hinter der Hüfte und greife weiter als schulterbreit. Die Handflächen zeigen nach unten, die Daumen nach außen.', 'Hebe die Arme langsam hinter dem Kopf nach oben. Erzwinge nichts, wenn es schwer wird, weiter zu heben.']::text[]),
  ('Rowing_Stationary', 'de', array['Setze dich auf das Rudergerät. Achte darauf, dass die Fersen bequem unten an den Fußstützen anliegen und die Riemen festgezogen sind. Wähle das gewünschte Programm, falls das Gerät welche anbietet. Sitze aufrecht und beuge dich aus der Hüfte nach vorn.', 'Das Rudern besteht aus drei Bewegungsphasen. In der ersten kommst du auf dem Gerät nach vorn: Die Knie sind gebeugt und an der Brust, der Oberkörper ist bei guter Haltung leicht nach vorn geneigt. Drücke dich dann von den Fußstützen ab und strecke die Beine, während du die Hände zum oberen Bauch ziehst und die Schultern nach hinten nimmst. Arbeite vor allem mit Bein- und Hüftmuskeln, um den Rücken nicht zu überlasten.', 'In der Erholungsphase streckst du einfach die Arme, beugst die Knie und bringst den Körper wieder nach vorn. So gehst du zurück in die erste Phase.']::text[]),
  ('Runners_Stretch', 'de', array['Am leichtesten kommst du aus dem Stand in diese Dehnung: Stelle ein Bein nach hinten und senke den Oberkörper langsam zum Boden.', 'Die vordere Ferse bleibt am Boden. Hebt sie ab, schiebe das andere Bein weiter nach hinten.', 'Setze die Hände links und rechts vom vorderen Bein auf. Um mehr aus der Dehnung herauszuholen, drücke den Po zur Decke und senke ihn dann nach und nach wieder zum Boden. So dehnst du den Hüftbeuger des hinteren Beins sowie Beinbeuger und Gesäß des vorderen.']::text[]),
  ('Running_Treadmill', 'de', array['Steige auf das Laufband und wähle im Menü die gewünschte Option. Die meisten Laufbänder haben eine manuelle Einstellung, oder du wählst ein Programm aus. Meist kannst du Alter und Gewicht eingeben, damit das Gerät schätzt, wie viele Kalorien du beim Training verbrennst. Über die Steigung veränderst du die Intensität des Trainings.', 'Laufbänder sind praktisch, gut für Herz und Kreislauf und belasten die Gelenke meist weniger als das Laufen im Freien. Eine Person mit 150 lb verbrennt über 450 Kalorien, wenn sie 30 Minuten lang mit 8 Meilen pro Stunde läuft. Achte beim Laufen auf eine gute Haltung und halte dich nur an den Griffen fest, wenn es nötig ist, zum Beispiel beim Absteigen oder beim Pulsmessen.']::text[]),
  ('Russian_Twist', 'de', array['Lege dich mit gebeugten Knien auf den Boden. Klemme die Füße unter etwas, das sich nicht bewegt, oder lass sie von einem Partner festhalten.', 'Hebe den Oberkörper an, bis er mit den Oberschenkeln ein gedachtes V bildet. Strecke die Arme ganz nach vorn, senkrecht zum Oberkörper, und verschränke die Hände. Das ist die Ausgangsposition.', 'Atme aus und drehe den Oberkörper nach rechts, bis die Arme parallel zum Boden sind.', 'Halte die Anspannung eine Sekunde und komme beim Ausatmen zurück in die Ausgangsposition. Drehe dich nun zur anderen Seite, genauso wie zuvor nach rechts.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Sandbag_Load', 'de', array['Um Sandsäcke oder andere Gegenstände zu verladen, legst du sie in einiger Entfernung von der Ladeplattform ab, üblich sind 50 Fuß.', 'Hebe zuerst den Sandsack an. Sandsäcke sind äußerst unhandlich, und wie du sie hebst, hängt vom jeweiligen Sack ab. Umfasse ihn so weit wie möglich und strecke Hüfte und Knie, um ihn weit nach oben zu ziehen. Ihn auf die Schulter zu nehmen, ist meist nicht erlaubt.', 'Laufe so schnell wie möglich zur Plattform und lade den Sack auf: Strecke Hüfte, Knie und Sprunggelenke, um ihn so hoch wie möglich zu bringen. Lege ihn auf die Plattform und achte darauf, dass er nicht herunterfällt.', 'Laufe zurück zum Start, hole den nächsten Sandsack und wiederhole das, bis der Durchgang beendet ist.']::text[]),
  ('Scapular_Pull-Up', 'de', array['Fasse eine Klimmzugstange im Obergriff.', 'Hebe dich aus dem Hang ein paar Zoll an, ohne die Arme einzusetzen. Dazu ziehst du den Schultergürtel nach unten, wie bei einem umgekehrten Schulterheben.', 'Halte am Ende der Bewegung kurz inne und kehre dann langsam in die Ausgangsposition zurück, bevor du weitere Wiederholungen machst.']::text[]),
  ('Scissor_Kick', 'de', array['Lege dich hin und drücke den Rücken auf den Boden. Eine Trainingsmatte ist möglich, aber nicht nötig. Strecke die Arme ganz zur Seite aus, die Handflächen zeigen nach unten. Hinweis: Die Arme bleiben die ganze Zeit ruhig liegen.', 'Hebe die Beine mit leicht gebeugten Knien an, bis die Fersen etwa 6 Zoll über dem Boden sind. Das ist die Ausgangsposition.', 'Hebe nun das linke Bein bis auf etwa 45 Grad an und senke gleichzeitig das rechte, bis die Ferse etwa 2-3 Zoll über dem Boden ist.', 'Wechsle: Hebe das rechte Bein und senke das linke. Denke bei dieser Übung daran, weiterzuatmen.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Scissors_Jump', 'de', array['Gehe in den Ausfallschritt: Ein Fuß steht vorn, das Knie ist gebeugt, das hintere Knie berührt fast den Boden.', 'Achte darauf, dass das vordere Knie über der Fußmitte steht. Drücke dich mit beiden Beinen ab und springe so hoch wie möglich. Schwinge die Arme mit, um mehr Höhe zu gewinnen.', 'Wechsle am höchsten Punkt des Sprungs die Beine: Das vordere geht nach hinten, das hintere nach vorn.', 'Fange die Landung mit den Beinen ab, indem du wieder in den Ausfallschritt gehst, und wiederhole.']::text[]),
  ('Seated_Band_Hamstring_Curl', 'de', array['Befestige ein Band knapp über dem Boden und stelle eine Bank ein paar Fuß davon entfernt auf.', 'Setze dich auf die Bank und lege das Band hinter die Knöchel. Die Beine sind zu Beginn gestreckt. Das ist deine Ausgangsposition.', 'Beuge die Knie und ziehe die Füße zur Bank. Vielleicht musst du dich leicht zurücklehnen, damit die Füße nicht auf den Boden stoßen.', 'Halte am Ende der Bewegung kurz inne und kehre dann langsam in die Ausgangsposition zurück.']::text[]),
  ('Seated_Barbell_Military_Press', 'de', array['Setze dich auf eine Bank für Schulterdrücken, die Stange liegt hinter deinem Kopf. Lass dir die Stange von einem Trainingspartner anreichen, das schont die Rotatorenmanschette, oder nimm sie selbst vorsichtig im Obergriff auf, die Handflächen zeigen nach vorn. Tipp: Greife weiter als schulterbreit, sodass Unterarm und Oberarm beim Absenken der Langhantel einen 90-Grad-Winkel bilden.', 'Wenn du die Langhantel in der richtigen Griffbreite hältst, hebe sie über den Kopf und strecke die Arme durch. Halte sie etwa auf Schulterhöhe und leicht vor dem Kopf. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam zum Schlüsselbein.', 'Atme aus und drücke die Stange wieder nach oben in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Barbell_Twist', 'de', array['Setze dich ans Ende einer Flachbank und lege eine Langhantel auf die Oberschenkel. Die Füße stehen schulterbreit auseinander.', 'Greife die Stange mit den Handflächen nach unten, die Hände weiter als schulterbreit auseinander. Hebe die Langhantel über den Kopf, bis die Arme ganz gestreckt sind.', 'Senke die Langhantel nun hinter den Kopf, bis sie unten am Nackenansatz aufliegt. Das ist die Ausgangsposition.', 'Halte Füße und Kopf ruhig und drehe die Taille von einer Seite zur anderen, sodass du die Anspannung in den schrägen Bauchmuskeln spürst. Drehe dich nur so weit, wie deine Taille es zulässt. Wer zu weit dehnt oder dreht, kann sich verletzen. Tipp: Bewege dich langsam und kontrolliert.', 'Denke daran, beim Drehen zur Seite auszuatmen und auf dem Weg zurück in die Ausgangsposition einzuatmen.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'de', array['Setze dich ans Ende einer Flachbank und halte eine Kurzhantel in einer Hand im Neutralgriff, die Handfläche zeigt zu dir.', 'Beuge die Knie leicht und neige den Oberkörper mit geradem Rücken aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Halte den Kopf oben.', 'Der Oberarm mit der Kurzhantel liegt nah am Oberkörper und auf einer Linie mit ihm: Er ist angehoben, bis er parallel zum Boden ist, der Unterarm zeigt zum Boden, die Hand hält das Gewicht. Tipp: Unterarm und Oberarm sollten einen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Atme aus und hebe das Gewicht mit dem Trizeps an, ohne den Oberarm zu bewegen, bis der Unterarm parallel zum Boden und der ganze Arm gestreckt ist. Wie bei vielen anderen Armübungen bewegt sich nur der Unterarm.', 'Halte die Anspannung oben eine Sekunde, atme dann ein und senke die Kurzhantel langsam in die Ausgangsposition.', 'Mache die vorgegebene Anzahl an Wiederholungen.', 'Wechsle den Arm und mache die Übung noch einmal.']::text[]),
  ('Seated_Bent-Over_Rear_Delt_Raise', 'de', array['Lege zwei Kurzhanteln so vor eine Flachbank, dass sie nach vorn zeigen.', 'Setze dich mit geschlossenen Beinen ans Ende der Bank. Die Kurzhanteln liegen hinter deinen Waden.', 'Beuge dich mit geradem Rücken aus der Hüfte nach vorn und nimm die Kurzhanteln auf. Die Handflächen zeigen dabei zueinander. Das ist deine Ausgangsposition.', 'Der Oberkörper bleibt vorgebeugt und ruhig, die Ellbogen sind leicht gebeugt. Hebe die Kurzhanteln gerade zur Seite, bis beide Arme parallel zum Boden sind. Atme beim Anheben aus. Hinweis: Schwinge nicht mit dem Oberkörper und führe die Arme nicht nach hinten statt zur Seite.', 'Halte die Anspannung oben eine Sekunde und senke die Kurzhanteln dann langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'de', array['Setze dich ans Ende einer Flachbank und halte in jeder Hand eine Kurzhantel im Neutralgriff, die Handflächen zeigen zu dir.', 'Beuge die Knie ein wenig und neige den Oberkörper aus der Hüfte nach vorn, der Rücken bleibt gerade, bis er fast parallel zum Boden ist. Halte den Kopf oben.', 'Die Oberarme liegen nah am Oberkörper und auf einer Linie mit ihm: Sie sind angehoben, bis sie parallel zum Boden sind, die Unterarme zeigen zum Boden, die Hände halten die Gewichte. Tipp: Unterarme und Oberarme sollten einen 90-Grad-Winkel bilden. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Gewichte mit dem Trizeps an, während die Oberarme ruhig bleiben, bis die Unterarme parallel zum Boden und die Arme ganz gestreckt sind. Wie bei vielen anderen Armübungen bewegen sich nur die Unterarme.', 'Halte die Anspannung oben eine Sekunde, atme dann ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mache die vorgegebene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Biceps', 'de', array['Setze dich mit gebeugten Knien auf den Boden, dein Partner steht hinter dir. Strecke die Arme gerade nach hinten, die Handflächen zeigen zueinander, und lass deinen Partner deine Handgelenke halten. Das ist die Ausgangsposition.', 'Versuche, die Ellbogen zu beugen, während dein Partner jede tatsächliche Bewegung verhindert.', 'Entspanne die Arme nach 10-20 Sekunden und lass deinen Partner die Handgelenke sanft nach oben ziehen, um den Bizeps zu dehnen. Sage deinem Partner, wann die Dehnung reicht, damit du dich nicht verletzt oder überdehnst.']::text[]),
  ('Seated_Cable_Rows', 'de', array['Für diese Übung brauchst du ein Rudergerät mit tiefem Kabelzug und einem V-Griff. Hinweis: Mit dem V-Griff hältst du im Neutralgriff, die Handflächen zeigen zueinander. Setze dich zuerst auf das Gerät und stelle die Füße auf die vordere Plattform oder die Querstange. Die Knie sind leicht gebeugt und nicht durchgedrückt.', 'Beuge dich vor, behalte dabei die natürliche Haltung des Rückens bei und fasse den V-Griff.', 'Ziehe dich mit gestreckten Armen zurück, bis dein Oberkörper im 90-Grad-Winkel zu den Beinen steht. Der Rücken ist leicht im Hohlkreuz, die Brust herausgestreckt. Während du den Griff vor dir hältst, solltest du eine gute Dehnung im Latissimus spüren. Das ist die Ausgangsposition der Übung.', 'Halte den Oberkörper ruhig und ziehe den Griff zu dir, bis er den Bauch berührt. Die Arme bleiben dabei nah am Körper. Atme bei dieser Bewegung aus. Spanne an diesem Punkt die Rückenmuskeln kräftig an. Halte die Anspannung eine Sekunde und gehe beim Einatmen langsam zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Cable_Shoulder_Press', 'de', array['Stelle ein passendes Gewicht ein, setze dich und fasse die Griffe. Die Oberarme stehen etwa 90 Grad zum Körper, Kopf und Brust sind oben. Auch die Ellbogen sind etwa 90 Grad gebeugt. Das ist deine Ausgangsposition.', 'Strecke nun die Ellbogen und drücke die Griffe über dem Kopf zusammen.', 'Halte oben kurz inne und führe die Griffe zurück in die Ausgangsposition. Achte darauf, dass die Kabel unter Spannung bleiben.', 'Du kannst die Bewegung auch ausführen, ohne den Rücken anzulehnen, und dabei die Hände abwechseln.']::text[]),
  ('Seated_Calf_Raise', 'de', array['Setze dich an die Maschine und stelle die Zehen auf den unteren Teil der Plattform, sodass die Fersen überstehen. Richte die Zehen so aus, wie du möchtest: nach vorn, nach innen oder nach außen.', 'Schiebe die unteren Oberschenkel unter das Polster des Hebels. Es muss auf die Höhe deiner Oberschenkel eingestellt sein. Lege dann die Hände oben auf das Polster, damit es nicht nach vorn rutscht.', 'Hebe den Hebel leicht an, indem du die Fersen nach oben drückst, und löse die Sicherung. Das ist deine Ausgangsposition.', 'Atme ein und senke die Fersen langsam, indem du die Sprunggelenke beugst, bis die Waden ganz gedehnt sind.', 'Atme aus und hebe die Fersen so hoch wie möglich: Strecke die Sprunggelenke und spanne die Waden an. Halte die Anspannung oben eine Sekunde.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Calf_Stretch', 'de', array['Setz dich aufrecht auf eine Trainingsmatte.', 'Beuge ein Knie und stelle diesen Fuß auf den Boden, damit dein Oberkörper stabil bleibt.', 'Strecke das andere Bein aus und beuge das Fußgelenk.', 'Zieh die Zehen zu dir heran, mit einem Band, einem Handtuch oder mit der Hand, wenn du so weit kommst. Halte 10 bis 20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Seated_Close-Grip_Concentration_Barbell_Curl', 'de', array['Setz dich auf eine Flachbank. Vor dir, zwischen deinen Beinen, liegt eine Langhantel oder SZ-Stange. Die Beine sind gespreizt, die Knie gebeugt, die Füße stehen auf dem Boden.', 'Hebe die Stange mit den Armen an und lege die Rückseiten deiner Oberarme auf die Innenseiten der Oberschenkel, etwa dreieinhalb Inches hinter der Vorderseite des Knies. Für diese Übung brauchst du einen Untergriff (supiniert), enger als schulterbreit. Tipp: Deine Arme sind auf ganzer Länge gestreckt und die Stange schwebt über dem Boden. Das ist deine Ausgangsposition.', 'Atme aus und curle das Gewicht nach vorn, indem du den Bizeps anspannst. Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Führe die Bewegung fort, bis der Bizeps vollständig angespannt ist und das Gewicht auf Schulterhöhe ist. Halte oben eine Sekunde und spanne den Bizeps dabei fest an.', 'Atme ein und führe die Stange langsam in die Ausgangsposition zurück. Tipp: Hole zu keinem Zeitpunkt Schwung.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Dumbbell_Curl', 'de', array['Setz dich auf eine Flachbank, in jeder Hand eine Kurzhantel, die Arme hängen lang nach unten. Die Ellbogen bleiben nah am Oberkörper.', 'Drehe die Handflächen so, dass sie zum Oberkörper zeigen. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig und curle die Gewichte nach oben. Sobald die Kurzhanteln an den Oberschenkeln vorbei sind, drehst du die Handgelenke ein, sodass die Handflächen am Ende der Bewegung nach vorn zeigen. Atme dabei aus, spanne den Bizeps an und bewege nur die Unterarme. Führe die Bewegung fort, bis der Bizeps vollständig angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Halte oben eine Sekunde und spanne den Bizeps dabei fest an.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition. Drehe die Handgelenke dabei wieder in den neutralen Griff.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Dumbbell_Inner_Biceps_Curl', 'de', array['Setz dich ans Ende einer Flachbank, in jeder Hand eine Kurzhantel, die Arme hängen lang nach unten. Die Ellbogen bleiben nah am Oberkörper.', 'Drehe die Handflächen nach innen in eine neutrale Stellung. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig und curle die Kurzhanteln nach außen und oben. Drehe die Handflächen beim Heben nach außen und halte die Unterarme auf einer Linie mit dem äußeren Deltamuskel.', 'Tipp: Nur die Unterarme bewegen sich. Führe die Bewegung fort, bis der Bizeps vollständig angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Halte oben eine Sekunde und spanne den Bizeps dabei fest an.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition. Denk daran, die Arme beim Absenken zu drehen, damit du wieder im neutralen Griff ankommst.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Dumbbell_Palms-Down_Wrist_Curl', 'de', array['Lege zuerst zwei Kurzhanteln vor einer Flachbank auf den Boden.', 'Setz dich auf die Kante der Bank, die Beine etwa schulterbreit auseinander. Die Füße bleiben auf dem Boden.', 'Nimm beide Kurzhanteln auf und hebe sie so weit an, dass deine Unterarme auf den Oberschenkeln liegen und die Handflächen nach unten zeigen. Die Handgelenke hängen über die Kante der Oberschenkel hinaus.', 'Beginne damit, die Handgelenke nach oben zu beugen, und atme dabei aus.', 'Atme ein und senke die Handgelenke langsam in die Ausgangsposition. Achte darauf, in diesem Teil der Übung einzuatmen. Tipp: Die Unterarme bleiben ruhig, denn für diese Übung müssen sich nur die Handgelenke bewegen.', 'Mache die empfohlene Anzahl an Wiederholungen.', 'Wenn du fertig bist, legst du die Kurzhanteln einfach auf dem Boden ab.']::text[]),
  ('Seated_Dumbbell_Palms-Up_Wrist_Curl', 'de', array['Lege zuerst zwei Kurzhanteln vor einer Flachbank auf den Boden.', 'Setz dich auf die Kante der Bank, die Beine etwa schulterbreit auseinander. Die Füße bleiben auf dem Boden.', 'Nimm beide Kurzhanteln auf und hebe sie so weit an, dass deine Unterarme auf den Oberschenkeln liegen und die Handflächen nach oben zeigen. Die Handgelenke hängen über die Kante der Oberschenkel hinaus.', 'Beginne damit, die Handgelenke nach oben zu beugen, und atme dabei aus.', 'Atme ein und senke die Handgelenke langsam in die Ausgangsposition. Achte darauf, in diesem Teil der Übung einzuatmen. Tipp: Die Unterarme bleiben ruhig, denn für diese Übung müssen sich nur die Handgelenke bewegen.', 'Mache die empfohlene Anzahl an Wiederholungen.', 'Wenn du fertig bist, legst du die Kurzhanteln einfach auf dem Boden ab.']::text[]),
  ('Seated_Dumbbell_Press', 'de', array['Nimm zwei Kurzhanteln und setz dich auf eine Military-Press-Bank oder eine Universalbank mit Rückenlehne. Stelle die Kurzhanteln dabei aufrecht auf deine Oberschenkel.', 'Bringe die Kurzhanteln nacheinander nach oben: Gib jeder mit dem Oberschenkel Schwung, bis sie seitlich auf Schulterhöhe ist.', 'Drehe die Handgelenke, sodass die Handflächen nach vorn zeigen. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Kurzhanteln nach oben, bis sie sich oben berühren.', 'Halte eine Sekunde, atme dann ein und senke die Gewichte langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Flat_Bench_Leg_Pull-In', 'de', array['Setz dich auf eine Bank und halte dich mit den Händen an ihren Seiten fest. Strecke die Beine vor dir aus, etwas unterhalb der Parallelen, und lehne den Oberkörper in einem Winkel von etwa 45 Grad zur Bank zurück. Das ist deine Ausgangsposition.', 'Zieh die Knie zu dir heran und bringe gleichzeitig den Oberkörper näher an sie. Atme bei dieser Bewegung aus.', 'Halte eine Sekunde, atme dann ein und geh zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Floor_Hamstring_Stretch', 'de', array['Setz dich auf eine Matte und strecke das rechte Bein nach vorn aus. Beuge das linke Bein und lege den Fuß an die Innenseite deines rechten Oberschenkels.', 'Beuge dich aus der Hüfte nach vorn und greife in Richtung Fußgelenk, bis du die Dehnung im Beinbeuger spürst. Halte 15 Sekunden und wiederhole das Ganze mit der anderen Seite.']::text[]),
  ('Seated_Front_Deltoid', 'de', array['Setz dich mit gebeugten Beinen aufrecht auf den Boden, dein Partner steht hinter dir. Strecke die Arme gerade zur Seite aus, die Handflächen zeigen zum Boden. Versuche, die Arme so weit wie möglich nach hinten zu führen, während dein Partner deine Handgelenke hält. Das ist deine Ausgangsposition.', 'Versuche 10-20 Sekunden lang, die Arme mit gestreckten Ellbogen nach vorn zu bewegen. Dein Partner hält sanft dagegen, sodass keine tatsächliche Bewegung entsteht.', 'Entspanne nun die Muskeln und lass deinen Partner die Dehnung in Schultern und Brust behutsam verstärken. Halte 10 bis 20 Sekunden.']::text[]),
  ('Seated_Glute', 'de', array['Setz dich mit gebeugten Knien hin und lege ein Fußgelenk über das gegenüberliegende Knie. Dein Partner steht hinter dir. Lehne dich nach vorn, während dein Partner deine Schultern mit den Händen stützt. Das ist deine Ausgangsposition.', 'Versuche 10-20 Sekunden lang, den Oberkörper nach hinten zu drücken. Dein Partner verhindert dabei, dass sich dein Oberkörper tatsächlich bewegt.', 'Entspanne nun die Muskeln. Dein Partner verstärkt die Dehnung, indem er deinen Oberkörper 10-20 Sekunden lang sanft nach vorn schiebt.']::text[]),
  ('Seated_Good_Mornings', 'de', array['Stelle eine Box in ein Power Rack und bringe die Sicherheitsstreben auf eine passende Höhe. Tritt unter die Stange und lege sie hinten auf die Schultern, nicht oben auf den Trapez. Zieh die Schulterblätter zusammen und drehe die Ellbogen nach vorn, als wolltest du die Stange um deine Schultern biegen.', 'Hebe die Stange aus der Ablage und spanne den unteren Rücken dabei fest ins Hohlkreuz. Der Blick bleibt nach vorn gerichtet. Halte Rücken, Schultern und Rumpf fest und schiebe Knie und Po nach außen, während du dich absenkst. Setz dich mit der Hüfte nach hinten, bis du auf der Box sitzt. Das ist deine Ausgangsposition.', 'Halte die Stange fest und beuge dich aus der Hüfte so weit wie möglich nach vorn. Wenn die Streben auf der Höhe der Parallelen liegen, bist du abgesichert, falls du scheiterst, und weißt außerdem, wann du stoppen musst.', 'Halte knapp über den Streben kurz inne und kehre die Bewegung um, bis dein Oberkörper wieder aufrecht ist.']::text[]),
  ('Seated_Hamstring', 'de', array['Setz dich mit gestreckten Beinen hin, dein Partner stellt sich hinter dich. Lehne dich nach vorn, während dein Partner deine Schultern mit den Händen stützt. Das ist deine Ausgangsposition.', 'Versuche 10-20 Sekunden lang, den Oberkörper nach hinten zu drücken. Dein Partner verhindert dabei, dass sich dein Oberkörper tatsächlich bewegt.', 'Entspanne nun die Muskeln. Dein Partner verstärkt die Dehnung, indem er deinen Oberkörper 10-20 Sekunden lang sanft nach vorn schiebt.']::text[]),
  ('Seated_Hamstring_and_Calf_Stretch', 'de', array['Lege einen Gürtel, ein Seil oder ein Band als Schlaufe um einen Fuß. Setz dich mit beiden Beinen gestreckt hin. Das ist deine Ausgangsposition.', 'Lehne dich leicht nach vorn und zieh am Gürtel, sodass die Zehen dieses Fußes zu dir kommen. Halte 10-20 Sekunden und wiederhole es dann mit dem anderen Bein.']::text[]),
  ('Seated_Head_Harness_Neck_Resistance', 'de', array['Lege ein Nackengeschirr am Ende einer Flachbank auf den Boden. Wähle die Gewichte und setz dich dann ans Ende der Bank, die Füße weiter als schulterbreit auseinander. Die Zehen zeigen nach außen.', 'Beuge den Oberkörper langsam nach vorn, bis er fast parallel zum Boden ist. Lege das Nackengeschirr mit beiden Händen sicher um deinen Kopf. Tipp: Die Gewichte bleiben dabei auf dem Boden liegen, damit der Nacken nicht belastet wird. Greife nun das Gewicht mit beiden Händen und richte den Oberkörper auf, bis er fast senkrecht zum Boden steht. Hinweis: Kopf und Oberkörper müssen bei dieser Übung leicht nach vorn geneigt sein.', 'Lege jetzt beide Hände auf die Knie. Das ist die Ausgangsposition.', 'Atme ein und senke den Kopf langsam, bis dein Kinn den oberen Teil der Brust berührt.', 'Atme aus und führe den Nacken zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Leg_Curl', 'de', array['Stelle den Hebel der Maschine auf deine Körpergröße ein und setz dich mit dem Rücken an das Rückenpolster.', 'Lege die Rückseite der Unterschenkel auf den gepolsterten Hebel, nur wenige Inches unterhalb der Waden, und fixiere das Schenkelpolster knapp über den Knien auf deinen Oberschenkeln. Greife die seitlichen Griffe, richte die Zehen gerade aus (die beiden anderen Fußstellungen gehen ebenfalls) und achte darauf, dass die Beine vor dir ganz gestreckt sind. Das ist deine Ausgangsposition.', 'Atme aus und beuge die Knie, um den Hebel so weit wie möglich zur Rückseite deiner Oberschenkel zu ziehen. Der Oberkörper bleibt die ganze Zeit ruhig. Halte die Anspannung eine Sekunde.', 'Atme ein und geh langsam zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Leg_Tucks', 'de', array['Setz dich auf eine Bank und greife mit den Händen ihre Seiten. Die Beine sind nach vorn gestreckt, etwas unterhalb der Parallelen, und der Oberkörper ist in einem Winkel von etwa 45 Grad zur Bank nach hinten geneigt. Das ist deine Ausgangsposition.', 'Zieh die Knie an und führe den Oberkörper zugleich auf sie zu. Atme dabei aus.', 'Halte eine Sekunde, atme dann ein und kehre in die Ausgangsposition zurück.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'de', array['Setz dich mit einer Kurzhantel in der rechten Hand auf eine Flachbank.', 'Stelle die Füße flach auf den Boden, etwas weiter als schulterbreit auseinander.', 'Lehne dich nach vorn und lege den rechten Unterarm auf den oberen rechten Oberschenkel, die Handfläche zeigt nach unten. Tipp: Die Rückseite des Handgelenks soll auf dem Knie liegen. Das ist deine Ausgangsposition.', 'Atme ein und lass die Kurzhantel so tief wie möglich sinken. Halte sie dabei fest im Griff.', 'Atme nun aus und beuge das Handgelenk mit der Kurzhantel so weit wie möglich nach oben, indem du den Unterarm anspannst. Halte die Anspannung eine Sekunde, bevor du wieder absenkst. Tipp: Die Bewegung soll allein aus dem Handgelenk kommen.', 'Mache die empfohlene Anzahl an Wiederholungen, wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'de', array['Setz dich mit einer Kurzhantel in der rechten Hand auf eine Flachbank.', 'Stelle die Füße flach auf den Boden, etwas weiter als schulterbreit auseinander.', 'Lehne dich nach vorn und lege den rechten Unterarm auf den oberen rechten Oberschenkel, die Handfläche zeigt nach oben. Tipp: Die Vorderseite des Handgelenks soll auf dem Knie liegen. Das ist deine Ausgangsposition.', 'Atme ein und lass die Kurzhantel so tief wie möglich sinken. Halte sie dabei fest im Griff.', 'Atme nun aus und beuge das Handgelenk mit der Kurzhantel so weit wie möglich nach oben, indem du den Unterarm anspannst. Halte die Anspannung eine Sekunde, bevor du wieder absenkst. Tipp: Die Bewegung soll allein aus dem Handgelenk kommen.', 'Mache die empfohlene Anzahl an Wiederholungen, wechsle den Arm und wiederhole die Bewegung.']::text[]),
  ('Seated_One-arm_Cable_Pulley_Rows', 'de', array['Setz dich für die Ausgangsposition zuerst an die Maschine und stelle die Füße auf die vordere Plattform oder Querstange. Die Knie sind leicht gebeugt, nicht durchgedrückt.', 'Beuge dich vor, ohne die natürliche Haltung des Rückens aufzugeben, und greife den Einzelgriff mit der linken Hand, die Handfläche zeigt nach unten.', 'Zieh mit gestrecktem Arm zurück, bis dein Oberkörper im 90-Grad-Winkel zu den Beinen steht. Der Rücken ist leicht im Hohlkreuz, die Brust herausgestreckt. Du solltest eine deutliche Dehnung im Latissimus spüren, während du den Griff vor dir hältst. Der rechte Arm kann an der Taille bleiben. Das ist die Ausgangsposition.', 'Halte den Oberkörper ruhig und zieh den Griff zum Körper, der Arm bleibt dicht am Oberkörper. Drehe dabei das Handgelenk, sodass die Hand auf Höhe des Bauchs in neutraler Stellung ist (Handfläche zum Oberkörper). Atme bei dieser Bewegung aus. Spanne an diesem Punkt die Rückenmuskeln kräftig an.', 'Halte die Anspannung eine Sekunde, atme dann ein und geh langsam in die Ausgangsstellung zurück. Tipp: Drehe das Handgelenk auch auf dem Rückweg, damit die Handfläche am Ende wieder nach unten zeigt.', 'Mache die empfohlene Anzahl an Wiederholungen und führe die Bewegung danach mit der rechten Hand aus.']::text[]),
  ('Seated_Overhead_Stretch', 'de', array['Setz dich mit geradem Rücken auf eine Trainingsmatte.', 'Lege die Fußsohlen aneinander, die Füße liegen sechs bis acht Inches vor deiner Hüfte.', 'Stütze eine Hand neben dir auf den Boden und lege die andere hinter den Kopf.', 'Hebe den Ellbogen zur Decke und neige den Oberkörper dabei zur anderen Seite. Halte 10 bis 20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Seated_Palm-Up_Barbell_Wrist_Curl', 'de', array['Greife eine Langhantel mit beiden Händen, die Handflächen zeigen nach oben, die Hände sind etwa schulterbreit auseinander.', 'Stelle die Füße flach auf den Boden, etwas weiter als schulterbreit auseinander.', 'Lehne dich nach vorn und lege die Unterarme auf die oberen Oberschenkel, die Handflächen zeigen nach oben. Tipp: Die Vorderseiten der Handgelenke sollen auf den Knien liegen. Das ist deine Ausgangsposition.', 'Atme ein und lass die Stange so tief wie möglich sinken. Halte sie dabei fest im Griff.', 'Atme nun aus und beuge die Handgelenke mit der Stange so weit wie möglich nach oben, indem du die Unterarme anspannst. Halte die Anspannung oben eine Sekunde. Tipp: Es bewegen sich nur die Handgelenke.']::text[]),
  ('Seated_Palms-Down_Barbell_Wrist_Curl', 'de', array['Greife eine Langhantel mit beiden Händen, die Handflächen zeigen nach unten, die Hände sind etwa schulterbreit auseinander.', 'Stelle die Füße flach auf den Boden, etwas weiter als schulterbreit auseinander.', 'Lehne dich nach vorn und lege die Unterarme auf die oberen Oberschenkel, die Handflächen zeigen nach unten. Tipp: Die Rückseiten der Handgelenke sollen auf den Knien liegen. Das ist deine Ausgangsposition.', 'Atme ein und lass die Stange so tief wie möglich sinken. Halte sie dabei fest im Griff.', 'Atme nun aus und beuge die Handgelenke mit der Stange so weit wie möglich nach oben, indem du die Unterarme anspannst. Halte die Anspannung oben eine Sekunde. Tipp: Es bewegen sich nur die Handgelenke.']::text[]),
  ('Seated_Side_Lateral_Raise', 'de', array['Nimm zwei Kurzhanteln und setz dich ans Ende einer Flachbank, die Füße stehen fest auf dem Boden. Die Arme hängen gestreckt an den Seiten nach unten, die Handflächen zeigen nach innen. Das ist deine Ausgangsposition.', 'Halte den Oberkörper ruhig, ohne Schwung, und hebe die Kurzhanteln seitlich an. Die Ellbogen sind leicht gebeugt und die Hände etwas nach vorn gekippt, als würdest du Wasser in ein Glas gießen. Hebe weiter, bis deine Arme parallel zum Boden sind. Atme beim Heben aus und halte oben eine Sekunde.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Triceps_Press', 'de', array['Setz dich auf eine Bank mit Rückenlehne, greife eine Kurzhantel mit beiden Händen und halte sie mit gestreckten Armen über dem Kopf. Tipp: Besser ist es, wenn dir jemand die Hantel reicht, vor allem wenn sie sehr schwer ist. Das Gewicht liegt in deinen Handflächen, die Daumen umschließen es. Die Handflächen zeigen nach innen. Das ist deine Ausgangsposition.', 'Halte die Oberarme nah am Kopf (Ellbogen nach innen) und senkrecht zum Boden. Senke das Gewicht in einem Halbkreis hinter den Kopf, bis die Unterarme den Bizeps berühren. Tipp: Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Atme bei diesem Schritt ein.', 'Hebe die Kurzhantel mit der Kraft des Trizeps zurück in die Ausgangsposition. Atme bei diesem Schritt aus.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'de', array['Stelle eine Bank vor einen tiefen Kabelzug, an dem eine gerade Stange oder eine SZ-Stange befestigt ist.', 'Rücke die Bank so weit weg, dass der Gewichtsblock angehoben wird und das Kabel unter Spannung steht, wenn du den Griff auf deine Oberschenkel bringst.', 'Greife den Griff nun schulterbreit mit beiden Händen, die Handflächen zeigen nach oben.', 'Geh zurück und setz dich auf die Bank. Die Füße stehen etwa schulterbreit auseinander fest auf dem Boden.', 'Lehne dich nach vorn und lege die Unterarme auf die Oberschenkel, die Rückseiten der Handgelenke liegen über den Knien. Das ist deine Ausgangsposition.', 'Atme ein und lass die Stange so tief wie möglich sinken. Halte sie dabei fest im Griff.', 'Beuge die Handgelenke mit der Stange nun so weit wie möglich nach oben, indem du die Unterarme anspannst. Tipp: Es bewegen sich nur die Handgelenke, nicht die Unterarme.', 'Halte die Anspannung oben eine Sekunde, atme dann ein und geh zurück in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('See-Saw_Press_Alternating_Side_Press', 'de', array['Nimm in jede Hand eine Kurzhantel und stell dich aufrecht hin.', 'Bringe die Kurzhanteln mit einem Clean (Umsetzen) auf Brust- bzw. Schulterhöhe und drehe die Handgelenke dann so, dass die Handflächen zu dir zeigen, als würdest du gleich eine Arnold Press machen. Das ist deine Ausgangsposition.', 'Strecke nun den linken Arm über den Kopf und drehe das Handgelenk auf dem Weg nach oben, sodass die Handfläche nach vorn zeigt. Die Ellbogen wandern beim Heben nach außen. Gleichzeitig beugst du dich aus der Hüfte zur Gegenseite. Tipp: Richtig ausgeführt sieht es aus, als wolltest du mit dem linken Arm etwas erreichen, das über der rechten Seite deines Körpers liegt. Atme bei dieser Bewegung aus.', 'Atme ein, sobald du oben angekommen bist. Dann beginnst du, mit dem Gewicht ganz gestreckt über dem Kopf und zur rechten Seite gebeugt, die Bewegung zur linken Seite.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Shotgun_Row', 'de', array['Befestige einen Einzelgriff an einem tiefen Kabelzug.', 'Wähle das passende Gewicht und stell dich ein paar Feet entfernt in einen weiten Ausfallschritt. Der Arm ist gestreckt, die Schulter nach vorn geschoben. Das ist deine Ausgangsposition.', 'Führe die Bewegung aus, indem du die Schulter zurückziehst und den Ellbogen beugst. Supiniere das Handgelenk beim Ziehen, sodass sich die Handfläche unterwegs nach oben dreht.', 'Halte kurz inne und kehre dann in die Ausgangsposition zurück.']::text[]),
  ('Shoulder_Circles', 'de', array['Die Schultern sind entspannt, die Arme hängen locker an den Seiten (oder liegen im Schoß, wenn du sitzt). Rolle die Schultern sanft nach vorn, oben, hinten und unten.', 'Wechsle die Richtung. Du kannst die Schultern abwechselnd oder beide gleichzeitig kreisen lassen.']::text[]),
  ('Shoulder_Press_-_With_Bands', 'de', array['Stell dich zu Beginn so auf ein Trainingsband, dass es bei gestreckten Armen gerade unter Spannung kommt. Greife die Griffe und hebe sie an, bis die Hände links und rechts auf Schulterhöhe sind.', 'Drehe die Handgelenke, sodass die Handflächen nach vorn zeigen. Die Ellbogen sind gebeugt, Ober- und Unterarme liegen auf einer Linie mit dem Oberkörper. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Griffe nach oben, bis die Arme über dem Kopf ganz gestreckt sind.']::text[]),
  ('Shoulder_Raise', 'de', array['Lass die Arme entspannt an den Seiten hängen, zieh die Schultern in Richtung Ohren hoch und senke sie wieder.']::text[]),
  ('Shoulder_Stretch', 'de', array['Führe den linken Arm quer vor den Körper und halte ihn gestreckt.']::text[]),
  ('Side-Lying_Floor_Stretch', 'de', array['Leg dich zuerst auf die linke Seite und beuge das linke Knie vor dir, um den Oberkörper zu stabilisieren (nutze auch deine Bauchmuskeln, um dich aufrecht zu halten).', 'Strecke das rechte Bein und setze den rechten Fuß hinter dem linken auf den Boden. Strecke den rechten Arm über den Kopf und zieh sanft am rechten Handgelenk, um die gesamte rechte Körperseite zu dehnen. Wechsle die Seite.']::text[]),
  ('Side_Bridge', 'de', array['Leg dich auf die Seite, die Beine gestreckt übereinander. Stütze dich auf den unteren Unterarm, der Ellbogen liegt direkt unter der Schulter.', 'Spanne den Bauch an und hebe die Hüfte vom Boden, bis dein Körper von Kopf bis Fuß eine gerade Linie bildet.', 'Halte diese Position und atme gleichmäßig weiter. Die Hüfte darf weder absinken noch sich verdrehen.', 'Senke die Hüfte auf den Boden und wiederhole die Übung auf der anderen Seite.']::text[]),
  ('Side_Hop-Sprint', 'de', array['Stell dich seitlich neben einen Kegel oder eine Hürde.', 'Beginne den Drill mit einem seitlichen Sprung über das Hindernis. Federe direkt aus der Landung ab und spring zurück an deinen Startpunkt.', 'Spring die vorgegebene Anzahl an Wiederholungen so schnell wie möglich. Zum Abschluss sprintest du eine kurze Strecke, sobald du den letzten Sprung gelandet hast.']::text[]),
  ('Side_Jackknife', 'de', array['Leg dich auf die Seite, die Beine gestreckt übereinander. Lege den unteren Arm vor dir auf den Boden und die obere Hand hinter den Kopf.', 'Atme aus und hebe das obere Bein zur Decke. Richte gleichzeitig den Oberkörper seitlich auf und führe den Ellbogen zum Bein.', 'Halte die Anspannung im seitlichen Bauch einen Moment, atme dann ein und senke Bein und Oberkörper kontrolliert ab.', 'Mache die empfohlene Anzahl an Wiederholungen und wechsle dann die Seite.']::text[]),
  ('Side_Lateral_Raise', 'de', array['Nimm zwei Kurzhanteln und stell dich mit geradem Oberkörper hin. Die Kurzhanteln hängen mit gestreckten Armen an deinen Seiten, die Handflächen zeigen zu dir. Das ist deine Ausgangsposition.', 'Der Oberkörper bleibt ruhig (kein Schwung), während du die Kurzhanteln seitlich anhebst. Beuge die Ellbogen leicht und kippe die Hände etwas nach vorn, als würdest du Wasser in ein Glas gießen. Hebe weiter, bis deine Arme parallel zum Boden sind. Atme beim Heben aus und halte oben eine Sekunde.', 'Atme ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Side_Laterals_to_Front_Raise', 'de', array['Stell dich hin und halte zwei Kurzhanteln an deinen Seiten. Das ist deine Ausgangsposition.', 'Hebe die Gewichte mit leicht gebeugten Ellbogen gerade vor dir bis auf Schulterhöhe. Hole dabei keinen Schwung und mogle nicht.', 'Führe die Gewichte am obersten Punkt vor dir nach außen, die Arme bleiben gestreckt.', 'Senke die Gewichte kontrolliert ab.', 'Hebe die Gewichte bei der nächsten Wiederholung erst vor dir auf Schulterhöhe und führe sie dann seitlich nach außen.', 'Senke die Gewichte in die Ausgangsposition.']::text[]),
  ('Side_Leg_Raises', 'de', array['Stell dich neben einen Stuhl, an dem du dich zur Unterstützung festhalten kannst. Steh auf einem Bein. Das ist deine Ausgangsposition.', 'Hebe das andere Bein gestreckt so weit wie möglich zur Seite und schwing es wieder nach unten, sodass es das Standbein kreuzt.', 'Wiederhole dieses Schwingen 5-10 Mal und vergrößere dabei den Bewegungsumfang.']::text[]),
  ('Side_Lying_Groin_Stretch', 'de', array['Leg dich zu Beginn auf die rechte Seite und beuge das rechte Knie vor dir, damit dein Oberkörper stabil liegt.', 'Stütze den Kopf auf die rechte Hand oder Schulter. Hebe das linke Bein an und halte es in der Kniekehle (leichter) oder am Fuß (schwerer).', 'Zieh das linke Knie zur linken Schulter und drücke gleichzeitig den Fuß oder das Knie nach unten in Richtung Boden. Um die Dehnung zu verstärken, streckst du das linke Bein. Wechsle die Seite.']::text[]),
  ('Side_Neck_Stretch', 'de', array['Neige den Kopf mit entspannten Schultern sanft zu einer Schulter.', 'Unterstütze die Dehnung, indem du seitlich leicht am Kopf ziehst.']::text[]),
  ('Side_Standing_Long_Jump', 'de', array['Stell dich hüftbreit in eine athletische Haltung. Kopf und Brust sind aufgerichtet, Knie und Hüfte leicht gebeugt. Das ist deine Ausgangsposition.', 'Lehne dich nach rechts und strecke Hüfte, Knie und Fußgelenke, um abzuspringen. Leite die Bewegung mit einem Armblock ein und spring so weit nach rechts, wie du kannst.', 'Lande mit Blick in dieselbe Richtung, die Füße hüftbreit auseinander, und fange den Aufprall mit dem Unterkörper ab.']::text[]),
  ('Side_To_Side_Chins', 'de', array['Greife die Klimmzugstange weit, die Handflächen zeigen nach vorn.', 'Du hängst mit gestreckten Armen im weiten Griff an der Stange. Neige den Oberkörper um etwa 30 Grad nach hinten, geh mit dem unteren Rücken ins Hohlkreuz und streck die Brust heraus. Das ist deine Ausgangsposition.', 'Zieh den Oberkörper nach oben und lehne dich dabei zur linken Seite, bis die Stange fast die obere Brust berührt. Schultern und Oberarme ziehst du dafür nach unten und hinten. Atme in diesem Teil der Bewegung aus. Tipp: Konzentriere dich darauf, die Rückenmuskeln fest anzuspannen, sobald du ganz oben bist. Der Oberkörper bleibt auf seinem Weg in sich ruhig (kein Schwung), nur die Arme arbeiten. Die Unterarme halten lediglich die Stange und leisten sonst keine Arbeit.', 'Halte die Anspannung eine Sekunde und atme ein, während du in die Ausgangsposition zurückgehst.', 'Zieh den Oberkörper nun nach oben und lehne dich dabei zur rechten Seite, bis die Stange fast die obere Brust berührt. Schultern und Oberarme ziehst du dafür nach unten und hinten. Atme in diesem Teil der Bewegung aus. Tipp: Konzentriere dich darauf, die Rückenmuskeln fest anzuspannen, sobald du ganz oben bist. Der Oberkörper bleibt auf seinem Weg in sich ruhig, nur die Arme arbeiten. Die Unterarme halten lediglich die Stange und leisten sonst keine Arbeit.', 'Halte die Anspannung eine Sekunde und atme ein, während du in die Ausgangsposition zurückgehst.', 'Wiederhole die Schritte 3-6, bis du die vorgegebene Anzahl an Wiederholungen für jede Seite geschafft hast.']::text[]),
  ('Side_Wrist_Pull', 'de', array['Diese Dehnung klappt am besten im Stehen. Führe den linken Arm über die Körpermitte und fasse das linke Handgelenk mit der rechten Hand, unten auf Hüfthöhe. Beginne die Dehnung mit gebeugtem linken Arm.', 'Strecke den Arm langsam, zieh daran und hebe ihn bis auf Schulterhöhe. Die Dehnung soll im Rücken entstehen, nicht in den Schultern. Zieh nicht zu stark am Schultergelenk. Wechsle die Seite.']::text[]),
  ('Side_to_Side_Box_Shuffle', 'de', array['Stell dich seitlich an die Box und setze den linken Fuß auf ihre Mitte.', 'Spring zum Start nach oben und hinüber auf die andere Seite der Box. Du landest mit dem rechten Fuß auf der Box und dem linken auf dem Boden. Schwing die Arme mit, um die Bewegung zu unterstützen.', 'Wechsle so immer weiter von einer Seite der Box zur anderen.']::text[]),
  ('Single-Arm_Cable_Crossover', 'de', array['Stell beide Rollen des Kabelzugs nach oben, wähle den Widerstand und nimm in jede Hand einen Griff.', 'Geh einen Schritt nach vorn vor die beiden Rollen, die Arme vor dir gestreckt, die Hände zusammen. Lehn dich nach vorn, Kopf und Brust aufrecht, die Füße in Schrittstellung. Das ist deine Ausgangsposition.', 'Lass den linken Arm, wo er ist, und öffne den rechten Arm zur Seite, der Ellbogen bleibt leicht gebeugt. Am Ende steht der rechte Arm etwa auf Schulterhöhe im rechten Winkel zum Körper.', 'Zieh die Hand zurück zur Körpermitte und bring den Arm so wieder in die Ausgangsposition.', 'Halte dort eine Sekunde und wiederhole die Bewegung mit der anderen Seite. Wechsle weiter ab, bis du die vorgesehene Zahl an Wiederholungen erreicht hast.']::text[]),
  ('Single-Arm_Linear_Jammer', 'de', array['Steck eine Stange in eine Landmine-Halterung oder klemme sie sicher in eine Ecke. Lade ein passendes Gewicht auf.', 'Hebe die Stange vom Boden und bring sie mit einer Hand oder beiden an die Schultern. Stell dich breit hin. Das ist deine Ausgangsposition.', 'Strecke den Ellbogen und drück das Gewicht nach oben. Arbeite explosiv und strecke Hüfte und Knie ganz durch, um möglichst viel Kraft zu entwickeln.', 'Kehre in die Ausgangsposition zurück.']::text[]),
  ('Single-Arm_Push-Up', 'de', array['Leg dich bäuchlings auf den Boden. Stütz dich so hoch, dass dein Gewicht auf den Zehen und einem Arm liegt. Der arbeitende Arm ist ganz gestreckt, die Hand direkt unter der Schulter. Die Beine sind gestreckt; für mehr Standfläche kannst du die Füße weiter auseinanderstellen als beim normalen Liegestütz.', 'Halte den Körper sauber in Linie und leg die freie Hand auf den Rücken. Das ist deine Ausgangsposition.', 'Beuge den Ellbogen und senke dich ab, bis du den Boden berührst.', 'Geh langsam nach unten und strecke dann den Arm, um wieder in die Ausgangsposition zu kommen.']::text[]),
  ('Single-Cone_Sprint_Drill', 'de', array['Diese Übung schult schnelle Füße. Du brauchst nur ein Hütchen. Stell dich neben das Hütchen, ein Arm vorn, ein Arm hinten.', 'Mach so schnell wie möglich kurze, hackende Schritte und arbeite mit den Armen mit. Umkreise das Hütchen mit hohen Knien und kräftiger Fußarbeit.', 'Mach nach drei Runden um das Hütchen eine Pause.']::text[]),
  ('Single-Leg_High_Box_Squat', 'de', array['Stell eine Box in ein Rack. Befestige darüber ein Band oder ein Seil.', 'Stell dich vor die Box und steig hinauf, bis du ganz aufrecht stehst; das andere Bein bleibt frei in der Luft. Halte dich am Band fest, um das Gleichgewicht zu halten.', 'Steig mit demselben Bein weiter auf und ab und wechsle erst dann die Seite.']::text[]),
  ('Single-Leg_Hop_Progression', 'de', array['Stell vor dir eine Reihe Hütchen auf. Steh locker und im Gleichgewicht auf einem Bein und hebe das Knie des anderen Beins an. Das ist deine Ausgangsposition.', 'Hüpf nach vorn über das Hütchen; Absprung und Landung erfolgen auf demselben Bein.', 'Hole vor jedem Sprung kurz Schwung nach unten und hüpf so von Hütchen zu Hütchen.', 'Dreh am Ende um und hüpf auf dem anderen Bein zurück.']::text[]),
  ('Single-Leg_Lateral_Hop', 'de', array['Stell dich seitlich neben ein Hütchen oder eine Hürde. Für die Ausgangsposition stehst du auf einem Bein, das Knie leicht gebeugt.', 'Hole kurz Schwung nach unten und hüpf seitlich über das Hütchen.', 'Lande auf dem Sprungbein und federe sofort wieder ab, zurück in die Ausgangsposition.', 'Hüpf weiter hin und her.']::text[]),
  ('Single-Leg_Leg_Extension', 'de', array['Setz dich in die Maschine und stell sie passend für dich ein. Das Polster liegt am unteren Schienbein an, berührt aber nicht das Sprunggelenk. Verstelle den Sitz so, dass der Drehpunkt der Maschine auf Höhe deines Knies liegt. Wähle ein Gewicht, das zu deinem Können passt.', 'Bleib aufrecht sitzen, strecke ein Bein ganz durch und halte oben kurz.', 'Senke das Bein in die Ausgangsposition, ohne das Gewicht abzulegen, damit die Spannung im Muskel bleibt.', 'Mach so viele Wiederholungen, wie du dir vorgenommen hast.']::text[]),
  ('Single-Leg_Stride_Jump', 'de', array['Stell dich seitlich neben eine Box und setze den inneren Fuß darauf, nah an der Kante.', 'Schwing die Arme nach oben, drück dich über das Bein auf der Box ab und spring so hoch wie möglich. Versuche, das andere Knie nach oben zu reißen.', 'Lande in derselben Stellung wie am Anfang und fang den Aufprall mit dem inneren Bein ab.']::text[]),
  ('Single_Dumbbell_Raise', 'de', array['Stell dich breitbeinig hin und halte eine Kurzhantel mit beiden Händen. Greife sie dabei am Hantelkopf statt am Griff. Die Arme sind gestreckt und hängen vor der Taille. Das ist deine Ausgangsposition.', 'Hebe das Gewicht mit gestreckten Armen bis über Schulterhöhe. Oberkörper und Hüfte bleiben während der ganzen Bewegung ruhig.', 'Geh zurück in die Ausgangsposition und mache die empfohlene Anzahl an Wiederholungen.']::text[]),
  ('Single_Leg_Butt_Kick', 'de', array['Stell dich auf ein Bein und hebe das andere Knie gebeugt an. Das ist deine Ausgangsposition.', 'Hole kurz Schwung nach unten und spring nach oben ab, indem du Hüfte, Knie und Sprunggelenk des Standbeins streckst.', 'Beuge sofort das Knie und versuche, mit der Ferse des Sprungbeins dein Gesäß zu berühren.', 'Bring das Bein leicht gebeugt wieder unter die Hüfte und lande. Das andere Bein bleibt während der ganzen Übung ungefähr in derselben Haltung.']::text[]),
  ('Single_Leg_Glute_Bridge', 'de', array['Leg dich auf den Rücken, die Knie gebeugt, die Fußsohlen auf dem Boden.', 'Hebe ein Bein vom Boden ab und zieh das Knie zur Brust. Das ist deine Ausgangsposition.', 'Drück dich über die Ferse des Standbeins ab und schiebe die Hüfte nach oben, sodass sich dein Gesäß vom Boden löst.', 'Streck die Hüfte so weit wie möglich, halte kurz und senke dich dann in die Ausgangsposition ab.']::text[]),
  ('Single_Leg_Push-off', 'de', array['Stell dich auf den Boden und setze einen Fuß auf die Box, die Ferse nah an der Kante.', 'Drück dich mit dem Fuß auf der Box ab und strecke Hüfte und Knie, um so hoch wie möglich zu kommen.', 'Lande mit demselben Fuß auf der Box und setze den anderen Fuß wieder dort auf, wo er am Anfang stand.']::text[]),
  ('Sit-Up', 'de', array['Leg dich auf den Boden, die Knie gebeugt. Klemm die Füße unter etwas, das sich nicht bewegt, oder lass sie von einem Partner festhalten.', 'Nimm die Hände hinter den Kopf und verschränke die Finger. Das ist die Ausgangsposition.', 'Richte den Oberkörper auf, bis er mit den Oberschenkeln ein V bildet. Atme dabei aus.', 'Spüre die Anspannung eine Sekunde lang und senke den Oberkörper dann beim Einatmen in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Sit_Squats', 'de', array['Stell die Füße schulterbreit auseinander. Das ist deine Ausgangsposition.', 'Beuge Knie und Hüfte und schiebe die Hüfte nach hinten, als wolltest du dich setzen.', 'Geh nur ein Stück weit in die Hocke, nicht bis zur Waagerechten, und kehre die Bewegung dann zügig um, bis du wieder in der Ausgangsposition bist. Mach 5-10 Wiederholungen.']::text[]),
  ('Skating', 'de', array['Rollschuhlaufen macht Spaß und kann Herz-Kreislauf-Fitness und Muskelausdauer verbessern. Es verlangt ein recht gutes Gleichgewicht und gute Koordination. Lerne zuerst die Grundlagen, auch Kurvenfahren und Bremsen, und trage Schutzausrüstung, um Verletzungen zu vermeiden.', 'Lauf 30 Minuten am Stück in einem angenehmen Tempo. Wenn du deine Ausdauer stärker fordern willst, lauf in Intervallen: von je fünf Minuten zwei Minuten schnell, die übrigen drei zur Erholung. Ein Mensch mit 150 lb Körpergewicht verbrennt bei angenehmem Tempo in 30 Minuten etwa 175 Kalorien, ähnlich wie beim zügigen Gehen.']::text[]),
  ('Sled_Drag_-_Harness', 'de', array['Lade das gewünschte Gewicht auf den Schlitten und befestige den Zuggurt. Du kannst an Griffen ziehen, ein Geschirr tragen oder den Gurt an einem Gewichthebergürtel einhängen.', 'Ob vorwärts oder rückwärts: Lehn dich in die Laufrichtung und bewege dich voran, indem du Hüfte und Knie streckst.']::text[]),
  ('Sled_Overhead_Backward_Walk', 'de', array['Befestige zwei Griffe mit einem Seil oder einer Kette an einem Schlitten. Lade ein leichtes Gewicht auf.', 'Stell dich mit dem Gesicht zum Schlitten und geh rückwärts, bis das Seil leicht gespannt ist. Halte die Hände direkt über dem Kopf, die Ellbogen gestreckt. Das ist deine Ausgangsposition.', 'Geh rückwärts und lass die Arme über dem Kopf. Vermeide ruckartige Bewegungen.']::text[]),
  ('Sled_Overhead_Triceps_Extension', 'de', array['Befestige zwei Griffe mit einer Kette oder einem Seil an einem Schlitten. Lade ein passendes Gewicht auf.', 'Dreh dem Schlitten den Rücken zu und geh von ihm weg, bis das Seil gespannt ist. Hebe die Hände über den Kopf, halte sie zusammen, die Handflächen zeigen zueinander. Die Ellbogen sind gebeugt und zeigen nach oben. Das ist deine Ausgangsposition.', 'Strecke die Arme im Ellbogen. Die Oberarme bleiben in ihrer Stellung, damit der Trizeps allein arbeitet.', 'Sind die Arme ganz gestreckt, geh einen Schritt nach vorn, bis das Seil wieder gespannt ist. Für mehr Stabilität kannst du in Schrittstellung stehen.']::text[]),
  ('Sled_Push', 'de', array['Lade das gewünschte Gewicht auf den Schiebeschlitten.', 'Nimm eine athletische Haltung ein, fass die Griffe und lehn dich mit ganz gestreckten Armen gegen den Schlitten. Schiebe ihn so schnell wie möglich und achte darauf, Hüfte und Knie zu strecken; das kräftigt deine hintere Muskelkette.']::text[]),
  ('Sled_Reverse_Flye', 'de', array['Befestige zwei Griffe mit einem Seil oder einer Kette an einem Schlitten. Lade ein leichtes Gewicht auf.', 'Stell dich mit dem Gesicht zum Schlitten und geh rückwärts, bis das Seil leicht gespannt ist. Halte beide Griffe mit gestreckten Armen etwa auf Hüfthöhe. Beuge die Knie leicht, Brust und Kopf bleiben oben. Das ist deine Ausgangsposition.', 'Zieh die Griffe mit gestreckten Ellbogen nach oben und auseinander: ein Reverse Fly mit leichter Außenrotation. Die Handflächen zeigen dabei nach vorn.', 'Kehre in die Ausgangsposition zurück und geh ein paar Schritte rückwärts, bis das Seil wieder gespannt ist.']::text[]),
  ('Sled_Row', 'de', array['Befestige zwei Griffe mit einem Seil oder einer Kette an einem Schlitten. Lade ein passendes Gewicht auf. Stell dich mit dem Gesicht zum Schlitten und geh rückwärts, bis das Seil leicht gespannt ist.', 'Nimm in jede Hand einen Griff, beuge die Knie leicht, halte Kopf und Brust oben und beginne mit gestreckten Armen.', 'Beuge die Ellbogen, zieh die Schulterblätter zusammen und hol den Schlitten so zu dir heran.', 'Geh ein, zwei Schritte zurück, bis das Seil wieder gespannt ist, und wiederhole.']::text[]),
  ('Sledgehammer_Swings', 'de', array['Für diese Übung brauchst du einen Reifen und einen Vorschlaghammer. Stell dich in Schrittstellung etwa zwei Fuß vor den Reifen. Fass den Hammer.', 'Als Rechtshänder greifst du mit der linken Hand das Ende des Stiels, die rechte Hand sitzt weiter oben, näher am Hammerkopf.', 'Beim Ausholen gleitet die rechte Hand zum Kopf hin; beim Schlag nach unten rutscht sie den Stiel hinab zur linken Hand. Schlag den Hammer so fest du kannst auf den Reifen. Fang den Rückprall des Hammers kontrolliert ab.', 'Wiederhole das Ganze auf der anderen Seite.']::text[]),
  ('Smith_Incline_Shoulder_Raise', 'de', array['Stell eine Schrägbank unter die Multipresse. Häng die Stange so hoch ein, dass du sie im Liegen mit fast gestreckten Armen erreichst. Lade dein Gewicht auf, leg dich auf die Schrägbank und achte darauf, dass deine Schultern genau unter der Stange liegen.', 'Fass die Stange schulterbreit im Obergriff (Handflächen nach vorn), hebe sie aus der Halterung und halte sie mit leicht gebeugten Ellbogen gerade über dir. Das ist deine Ausgangsposition.', 'Atme aus und schiebe die Stange nach oben, bis deine Arme ganz gestreckt sind. Hinweis: Die Anspannung solltest du rund um die Schultern spüren.', 'Halte eine Sekunde und senke die Stange dann beim Einatmen in die Ausgangsposition.', 'Mach die vorgesehene Zahl an Wiederholungen.', 'Häng die Stange danach wieder in die Halterung.']::text[]),
  ('Smith_Machine_Behind_the_Back_Shrug', 'de', array['Stell die Stange auf Oberschenkelhöhe ein und lade ein passendes Gewicht auf.', 'Stell dich so hin, dass die Stange hinter dir ist, fass sie schulterbreit im Obergriff und hake sie aus. Du stehst aufrecht, Kopf und Brust oben, die Arme gestreckt. Das ist deine Ausgangsposition.', 'Zieh die Schultern gerade nach oben. Arme und Handgelenke beugst du dabei nicht.', 'Halte kurz und senke das Gewicht dann in die Ausgangsposition.', 'Mach die gewünschte Zahl an Wiederholungen und hake die Stange danach wieder ein.']::text[]),
  ('Smith_Machine_Bench_Press', 'de', array['Stell eine Flachbank unter die Multipresse. Häng die Stange so hoch ein, dass du sie im Liegen mit fast gestreckten Armen erreichst. Lade dein Gewicht auf und leg dich auf die Bank. Fass die Stange im Obergriff, breiter als schulterbreit, entriegle sie und halte sie mit durchgestreckten Armen gerade über dir. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis du sie auf der Mitte der Brust spürst.', 'Halte eine Sekunde, atme dann aus und drück die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Streck die Arme oben durch, halte eine Sekunde und senke dann wieder langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach die vorgesehene Zahl an Wiederholungen.', 'Verriegle die Stange danach wieder in der Halterung.']::text[]),
  ('Smith_Machine_Bent_Over_Row', 'de', array['Stell die Stange der Multipresse auf eine Höhe etwa 2 Inch unter deinen Knien ein.', 'Beuge die Knie leicht und neig den Oberkörper aus der Hüfte nach vorn, mit geradem Rücken, bis er fast parallel zum Boden ist. Tipp: Halte den Kopf oben.', 'Fass die Stange im Obergriff (proniert) und entriegle sie. Lass sie direkt vor dir hängen; die gestreckten Arme stehen senkrecht zum Boden und zum Oberkörper. Das ist deine Ausgangsposition.', 'Der Oberkörper bleibt ruhig. Atme aus und zieh die Stange hoch, die Ellbogen nah am Körper; die Unterarme halten nur das Gewicht und leisten sonst keine Arbeit. Spann oben die Rückenmuskeln fest an und halte eine Sekunde.', 'Senke das Gewicht beim Einatmen langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Machine_Calf_Raise', 'de', array['Leg einen Block oder eine Hantelscheibe unter die Stange der Multipresse. Stell die Stange passend zu deiner Körpergröße ein. Wenn die Höhe stimmt und die Stange beladen ist, steig mit den Fußballen auf die Scheiben und leg die Stange hinten auf deine Schultern.', 'Fass die Stange mit beiden Händen, die Handflächen zeigen nach vorn. Dreh die Stange, um sie auszuhaken. Das ist deine Ausgangsposition.', 'Drück dich über die Fußballen ab und hebe die Fersen so hoch wie möglich; spann die Waden oben fest an. Die Knie bleiben gestreckt. Halte die Position eine Sekunde, bevor du wieder absenkst.', 'Atme ein und senke die Fersen langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Machine_Close-Grip_Bench_Press', 'de', array['Stell eine Flachbank unter die Multipresse. Häng die Stange so hoch ein, dass du sie im Liegen mit fast gestreckten Armen erreichst. Lade dein Gewicht auf und leg dich auf die Bank. Fass die Stange eng im Obergriff (Handflächen nach vorn), etwa schulterbreit, entriegle sie und halte sie mit durchgestreckten Armen gerade über dir. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis du sie auf der Mitte der Brust spürst. Tipp: Anders als beim normalen Bankdrücken bleiben die Ellbogen die ganze Zeit nah am Oberkörper, damit der Trizeps möglichst viel arbeitet.', 'Halte eine Sekunde, atme dann aus und drück die Stange mit dem Trizeps zurück in die Ausgangsposition. Streck die Arme oben durch, halte eine Sekunde und senke dann wieder langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach die vorgesehene Zahl an Wiederholungen.', 'Verriegle die Stange danach wieder in der Halterung.']::text[]),
  ('Smith_Machine_Decline_Press', 'de', array['Stell eine Negativbank so in das Rack, dass die Stange über deiner Brust liegt. Lade ein passendes Gewicht auf und leg dich auf die Bank.', 'Dreh die Stange, um sie auszuhaken, und strecke die Arme ganz. Der Rücken ist leicht im Hohlkreuz, die Schulterblätter sind zusammengezogen. Das ist deine Ausgangsposition.', 'Beuge die Arme und senke die Stange zur Brust.', 'Halte kurz und strecke dann die Arme, um das Gewicht zurück in die Ausgangsposition zu drücken.', 'Wenn du die gewünschte Zahl an Wiederholungen geschafft hast, dreh die Stange und hake sie ein.']::text[]),
  ('Smith_Machine_Hang_Power_Clean', 'de', array['Stell die Stange auf Kniehöhe ein und lade ein passendes Gewicht auf.', 'Fass die Stange im Obergriff, etwas breiter als schulterbreit, und hake sie aus der Maschine aus. Die Arme sind ganz gestreckt, Kopf und Brust oben. Die Ellbogen zeigen nach außen, die Schultern sind hinten und unten. Schiebe die Hüfte nach hinten, sodass die Spannung auf den Beinbeugern liegt. Das ist deine Ausgangsposition.', 'Strecke Hüfte und Knie kraftvoll und beschleunige die Stange. Die Arme bleiben in dieser Phase gerade.', 'Bist du ganz gestreckt, beuge Hüfte und Knie erneut, um tiefer unter die Stange zu kommen.', 'Jetzt dürfen sich die Arme beugen: Dreh die Ellbogen um die Stange herum und nimm sie auf den Schultern auf.', 'Strecke Hüfte und Knie und richte dich mit der Stange auf den Schultern ganz auf. Damit ist die Bewegung abgeschlossen.']::text[]),
  ('Smith_Machine_Hip_Raise', 'de', array['Stell eine Bank in das Rack und lade ein passendes Gewicht auf die Stange. Leg dich auf die Bank und setze die Fußsohlen gegen die Stange. Entriegle die Stange und strecke die Beine; nimm dafür wenn nötig die Hände zu Hilfe. Für mehr Halt greifst du die Seiten der Multipresse. Das ist deine Ausgangsposition.', 'Kipp das Becken und runde die Wirbelsäule, sodass sich die Hüfte von der Bank hebt. Die Knie bleiben die ganze Bewegung über leicht gebeugt.', 'Halte kurz und leg die Hüfte dann wieder auf die Bank.', 'Mach so viele Wiederholungen, wie du dir vorgenommen hast.']::text[]),
  ('Smith_Machine_Incline_Bench_Press', 'de', array['Stell eine Schrägbank unter die Multipresse. Häng die Stange so hoch ein, dass du sie im Liegen mit fast gestreckten Armen erreichst. Lade dein Gewicht auf, leg dich auf die Schrägbank und achte darauf, dass deine obere Brust in einer Linie mit der Stange liegt. Fass die Stange im Obergriff (Handflächen nach vorn), breiter als schulterbreit, entriegle sie und halte sie mit durchgestreckten Armen gerade über dir. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis du sie auf der oberen Brust spürst.', 'Halte eine Sekunde, atme dann aus und drück die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Streck die Arme oben durch, halte eine Sekunde und senke dann wieder langsam ab. Tipp: Das Absenken sollte mindestens doppelt so lange dauern wie das Hochdrücken.', 'Mach die vorgesehene Zahl an Wiederholungen.', 'Häng die Stange danach wieder in die Halterung.']::text[]),
  ('Smith_Machine_Leg_Press', 'de', array['Stell die Stange einer Multipresse ein paar Fuß über dem Boden ein. Achte darauf, dass sie auf den Sicherheitsablagen liegt. Lade ein passendes Gewicht auf und leg dich unter die Stange. Setze die Fußmitte an die Stange und zieh die Knie zur Brust. Das ist deine Ausgangsposition.', 'Drück über die Füße und schiebe die Stange nach oben, indem du Hüfte und Knie streckst. Drück die Knie nicht ganz durch.', 'Halte oben kurz und kehre dann in die Ausgangsposition zurück.']::text[]),
  ('Smith_Machine_One-Arm_Upright_Row', 'de', array['Stell die Stange auf Oberschenkelhöhe ein und lade ein passendes Gewicht auf.', 'Fass die Stange weit, hake das Gewicht aus und nimm die Hand, die nicht arbeitet, von der Stange. Du stehst aufrecht, der Arm ist gestreckt, Kopf und Brust sind oben. Das ist deine Ausgangsposition.', 'Beuge den Ellbogen und hebe den Oberarm, der Ellbogen zeigt nach außen. Geh so weit, bis der Oberarm parallel zum Boden ist.', 'Halte kurz und senke das Gewicht dann in die Ausgangsposition.', 'Mach die gewünschte Zahl an Wiederholungen und hake die Stange danach wieder ein.']::text[]),
  ('Smith_Machine_Overhead_Shoulder_Press', 'de', array['Stell eine Flachbank, besser noch eine Bank mit Rückenlehne, unter eine Multipresse. Häng die Stange so hoch ein, dass du im Sitzen die Arme fast ganz strecken musst, um sie zu erreichen.', 'Stimmt die Höhe, setz dich etwas hinter die Stange, sodass eine gedachte gerade Linie von deiner Nasenspitze zur Stange führt. Die Füße bleiben ruhig stehen. Fass die Stange mit den Handflächen nach vorn, entriegle sie und drück sie hoch, bis deine Arme ganz gestreckt sind. Das ist die Ausgangsposition.', 'Atme ein und senke die Stange langsam bis auf Kinnhöhe.', 'Atme aus und drück die Stange mit den Schultern zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Machine_Pistol_Squat', 'de', array['Stell die Stange zuerst passend zu deiner Körpergröße ein. Tritt darunter und leg sie hinten quer über deine Schultern.', 'Fass die Stange mit den Handflächen nach vorn, entriegle sie und hebe sie aus der Halterung, indem du die Beine streckst.', 'Setze einen Fuß etwa 12 Inch vor die Stange. Strecke das andere Bein nach vorn aus und halte es über dem Boden. Schau die ganze Zeit nach vorn und halte die Wirbelsäule neutral oder leicht im Hohlkreuz. Das ist deine Ausgangsposition.', 'Bleib sauber in der Haltung und senke dich ab, indem du Knie und Hüfte beugst, so tief es deine Beweglichkeit zulässt.', 'Halte unten kurz, drück dich dann über die Ferse ab und strecke Knie und Hüfte, bis du wieder in der Ausgangsposition bist.']::text[]),
  ('Smith_Machine_Reverse_Calf_Raises', 'de', array['Stell die Stange der Multipresse auf deine Körpergröße ein und leg eine erhöhte Plattform genau darunter.', 'Stell dich so auf die Plattform, dass die Fersen fest darauf stehen und die Fußballen über die Kante hinausragen. Die Zehen zeigen nach vorn, die Füße stehen schulterbreit.', 'Behalte diese Fußstellung bei, geh mit den Schultern unter die Stange und drück sie hoch, indem du Hüfte und Knie streckst, bis du aufrecht stehst. Die Knie bleiben leicht gebeugt und werden nie durchgedrückt. Das ist deine Ausgangsposition. Tipp: Die Stange auf dem Rücken dient nur dem Gleichgewicht.', 'Atme aus und hebe die Fußballen, indem du die Zehen so hoch wie möglich ziehst und die Waden anspannst. Die Knie bleiben die ganze Zeit ruhig und beugen sich zu keinem Zeitpunkt. Halte die Position eine Sekunde, bevor du wieder absenkst.', 'Atme ein und senke Fußballen und Zehen langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Machine_Squat', 'de', array['Stell die Stange zuerst passend zu deiner Körpergröße ein. Wenn die Höhe stimmt und die Stange beladen ist, tritt darunter und leg sie hinten auf deine Schultern, knapp unterhalb des Nackens.', 'Halte die Stange links und rechts mit je einer Hand, die Handflächen nach vorn, entriegle sie und hebe sie aus der Halterung: Drück mit den Beinen und richte gleichzeitig den Oberkörper auf.', 'Stell die Füße schulterbreit in einen mittleren Stand, die Zehen leicht nach außen. Halte den Kopf die ganze Zeit oben und den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der mittlere Stand, der hier beschrieben ist, trainiert die Beine insgesamt; du kannst aber jede der drei Standbreiten wählen.', 'Beuge die Knie und senke die Stange langsam, aufrecht und mit erhobenem Kopf. Geh so tief, bis der Winkel zwischen Oberschenkel und Wade etwas kleiner als 90 Grad ist; dann liegen die Oberschenkel unterhalb der Parallele zum Boden. Atme bei diesem Teil ein. Tipp: Bei sauberer Ausführung bildet die Vorderseite der Knie mit den Zehen eine gedachte gerade Linie, die senkrecht zur Vorderseite steht. Ragen die Knie über diese Linie, also über die Zehen hinaus, belastest du die Knie unnötig und die Übung ist falsch ausgeführt.', 'Atme aus und bring die Stange nach oben: Drück die Fersen in den Boden und strecke die Beine, bis du wieder in der Ausgangsposition bist.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Machine_Stiff-Legged_Deadlift', 'de', array['Stell die Stange der Multipresse etwa auf die Mitte deiner Oberschenkel ein. Wenn die Höhe stimmt und die Stange beladen ist, fass sie schulterbreit im pronierten Griff (Handflächen nach vorn). Bei viel Gewicht brauchst du vielleicht Handgelenkbandagen.', 'Hebe die Stange an, indem du die Arme ganz streckst; der Rücken bleibt gerade. Steh aufrecht, die Füße schulterbreit oder enger, die Knie leicht gebeugt. Das ist deine Ausgangsposition.', 'Die Knie bleiben unbewegt. Beuge dich mit geradem Rücken aus der Hüfte vor und senke die Stange bis über die Fußrücken. Geh weiter vor, als wolltest du etwas vom Boden aufheben, bis du eine Dehnung in den Beinbeugern spürst. Atme dabei aus.', 'Sobald du die Dehnung spürst, richte den Oberkörper wieder auf, indem du Hüfte und Taille streckst, bis du in der Ausgangsposition bist. Atme dabei ein.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Machine_Upright_Row', 'de', array['Stell die Stange der Multipresse etwa auf die Mitte deiner Oberschenkel ein. Wenn die Höhe stimmt und die Stange beladen ist, fass sie schulterbreit im pronierten Griff (Handflächen nach vorn). Bei viel Gewicht brauchst du vielleicht Handgelenkbandagen.', 'Hebe die Stange an und strecke die Arme ganz, der Rücken bleibt gerade. Die Ellbogen sind leicht gebeugt. Das ist die Ausgangsposition.', 'Atme aus und zieh die Stange mit den seitlichen Schultern nach oben, nah am Körper entlang, bis sie fast dein Kinn berührt. Tipp: Die Ellbogen führen die Bewegung und sind beim Heben immer höher als die Unterarme. Halte außerdem den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Stange langsam in die Ausgangsposition. Atme dabei ein.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Smith_Single-Leg_Split_Squat', 'de', array['Stelle eine Flachbank 2-3 Fuß hinter die Multipresse. Bringe die Stange auf die Höhe, die zu deiner Körpergröße passt. Ist die Höhe eingestellt und die Stange beladen, tritt darunter und lege sie quer auf deine hintere Schulterpartie, etwas unterhalb des Nackens.', 'Fasse die Stange auf beiden Seiten mit nach vorn zeigenden Handflächen, entriegle sie und hebe sie aus der Ablage: Drücke dich zuerst mit den Beinen hoch und richte dabei gleichzeitig den Oberkörper auf.', 'Setze einen Fuß leicht nach vorn unter die Stange, strecke das andere Bein nach hinten und lege den Fußrücken auf die Bank. Das ist deine Ausgangsposition.', 'Beuge das Knie und senke die Stange langsam ab; bleib dabei aufrecht und halte den Kopf oben. Geh so weit hinunter, bis der Winkel zwischen Oberschenkel und Wade etwas kleiner als 90 Grad ist, der Oberschenkel also tiefer als parallel zum Boden steht. Atme in diesem Teil der Bewegung ein. Tipp: Bei richtiger Ausführung bildet die Vorderseite des Knies mit den Zehen eine gedachte gerade Linie, die senkrecht zur Vorderseite steht. Schiebt sich das Knie über diese Linie hinaus, also über die Zehen, wird es unnötig belastet und die Übung ist falsch ausgeführt.', 'Atme aus und bringe die Stange wieder nach oben: Drücke dich vor allem mit der Ferse vom Boden ab, strecke das Bein und kehre in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.', 'Wechsle das Bein und wiederhole die Bewegung.']::text[]),
  ('Snatch', 'de', array['Stell dich schulterbreit hin. Die Langhantel liegt direkt über der Stelle, an der die Zehen in den übrigen Fuß übergehen.', 'Beuge die Knie und greife die Stange mit flachem Rücken, die Handflächen nach unten und die Hände weiter als schulterbreit. Senke die Hüfte und lass den Körper sinken, als wolltest du dich auf einen Stuhl setzen. Das ist deine Ausgangsposition.', 'Drücke mit den Füßen gegen den Boden, als wäre er eine bewegliche Plattform, und beginne im selben Moment, die Langhantel dicht an den Beinen anzuheben.', 'Erreicht die Stange die Mitte der Oberschenkel, drücke dich mit den Beinen vom Boden ab und strecke den Körper explosiv ganz durch.', 'Zieh die Schultern wie beim Schulterheben nach hinten oben, während die Stange steigt. Führe die Ellbogen dabei seitlich nach außen und halte sie so lange wie möglich über der Stange.', 'Sobald die Langhantel hoch genug ist, um sie zu kontrollieren, bringst du deinen Körper sehr schnell und kraftvoll unter sie: Lass dich in die Hocke fallen, sperre dabei die Arme und halte die Langhantel über dem Kopf.', 'Schließe die Bewegung ab, indem du aus der Hocke aufstehst. Am Ende stehen beide Füße auf einer Linie und die Arme halten die Langhantel ganz gestreckt über dem Kopf.']::text[]),
  ('Snatch_Balance', 'de', array['Stell die Füße in die Zugposition. Die Stange liegt quer auf der hinteren Schulterpartie, die Hände fassen im weiten Reißgriff.', 'Gib der Stange mit einem kurzen, abrupten Beugen und Strecken der Knie einen Impuls nach oben und drücke dich energisch unter sie, während die Füße in die Fangposition wechseln.', 'Fange die Stange mit gesperrten Armen über dem Kopf, nahe am tiefsten Punkt der Hocke. Der Oberkörper bleibt senkrecht, die Hüfte sinkt zwischen die Beine.', 'Geh weiter bis in die volle Tiefe und steh dann wieder auf. Setze das Gewicht vorsichtig ab.']::text[]),
  ('Snatch_Deadlift', 'de', array['Diese Übung kräftigt den ersten Zug beim Reißen. Die Langhantel liegt auf der Plattform; fasse sie im weiten Reißgriff. Die Füße stehen direkt unter der Hüfte, die Fußspitzen zeigen nach außen. Geh zur Stange in die Hocke, den Rücken vollständig gestreckt und den Kopf nach vorn gerichtet.', 'Leite die Bewegung ein, indem du dich über die Fersen abdrückst und die Hüfte hebst. Der Rückenwinkel bleibt gleich, bis die Stange an den Knien vorbei ist.', 'Schiebe dann die Hüfte nach vorn zur Stange und lehne dich zurück. Führe die Bewegung umgekehrt aus, um die Stange wieder auf der Plattform abzulegen.']::text[]),
  ('Snatch_Pull', 'de', array['Die Langhantel liegt nah an den Schienbeinen auf dem Boden; fasse sie im weiten Reißgriff. Senke die Hüfte, das Gewicht auf den Fersen, den Rücken gerade, den Kopf nach vorn gerichtet, die Brust oben und die Schultern knapp vor der Stange. Das ist deine Ausgangsposition.', 'Starte den ersten Zug, indem du dich über die Fersen abdrückst und die Knie streckst. Der Rückenwinkel bleibt gleich und die Arme bleiben gestreckt. Führe das Gewicht kontrolliert bis über die Knie.', 'Jetzt folgt der zweite Zug, aus dem der größte Teil der Beschleunigung kommt. Nähert sich die Stange der Mitte der Oberschenkel, beginnst du die Hüfte zu strecken. Beschleunige wie bei einem Sprung: Strecke Hüfte, Knie und Sprunggelenke und bringe die Stange mit Tempo nach oben.', 'Aktiv mit den Armen ziehen musst du nicht, um das Gewicht zu beschleunigen; am Ende des zweiten Zugs ist der Körper ganz gestreckt und leicht nach hinten gelehnt. Die volle Streckung soll heftig und abrupt kommen; halte sie nicht länger als nötig.']::text[]),
  ('Snatch_Shrug', 'de', array['Greife weit und lass die Stange auf Höhe der Oberschenkelmitte hängen. Möglich sind Hakengriff oder Obergriff. Der Rücken ist gerade und leicht nach vorn geneigt.', 'Zieh die Schultern zu den Ohren hoch. Diese Übung verträgt meist mehr Gewicht als das Reißen, lade aber nicht so viel auf, dass die Ausführung langsamer wird.']::text[]),
  ('Snatch_from_Blocks', 'de', array['Lege eine beladene Langhantel auf Blöcke oder Ständer in der gewünschten Höhe. Greife die Stange weit. Die Füße stehen direkt unter der Hüfte und sind so weit wie nötig nach außen gedreht. Senke die Hüfte, heb die Brust und schau nach vorn. Die Schultern befinden sich knapp vor der Stange, die Ellbogen zeigen nach außen. Das ist die Ausgangsposition.', 'Starte den ersten Zug, indem du dich über den vorderen Teil der Fersen abdrückst und die Stange von den Blöcken hebst.', 'Geh in den zweiten Zug über: Strecke Hüfte, Knie und Sprunggelenke und treibe die Stange so schnell wie möglich nach oben. Sie bleibt dabei nah am Körper. Am höchsten Punkt der Streckung ziehst du die Schultern hoch und lässt die Ellbogen zur Seite hin beugen.', 'Während die Füße in die Fangposition wechseln, ziehst du dich kraftvoll unter die Stange und bringst sie über den Kopf. Die Füße landen knapp außerhalb der Hüfte, so weit wie nötig nach außen gedreht. Fange die Stange so tief wie möglich, die Arme über dem Kopf ganz gestreckt.', 'Halte die Stange über dem vorderen Teil der Fersen, Kopf und Brust oben, und drücke dich über die Fersen in den Stand. Lege das Gewicht vorsichtig auf die Blöcke zurück.']::text[]),
  ('Speed_Band_Overhead_Triceps', 'de', array['Befestige für diese Übung ein Band am Boden. Du kannst es zum Beispiel am Fuß einer Schrägbank verankern und dich über die Bank stellen. Alternativ stellst du dich einfach auf das Band.', 'Zieh das Band zunächst hinter den Kopf und halte es im Obergriff, die Ellbogen zeigen nach oben. Das ist deine Ausgangsposition.', 'Strecke nun die Ellbogen, bis die Arme gerade sind, und achte darauf, dass die Oberarme an ihrem Platz bleiben.', 'Halte kurz und kehre dann in die Ausgangsposition zurück.']::text[]),
  ('Speed_Box_Squat', 'de', array['Bringe Bänder an der Stange an, die in Bodennähe sicher verankert sind. Für genug Spannung musst du die Bänder eventuell in einer Schlinge festziehen.', 'Nimm eine Box in passender Höhe. Lade so viel Gewicht auf, dass es noch anstrengend ist, aber nicht so viel, dass das Tempo leidet. In der Regel sind das 50-70% deines Maximums für eine Wiederholung.', 'Lege die Stange auf den oberen Rücken, zieh die Schulterblätter zusammen, geh ins Hohlkreuz und spanne alles von Kopf bis Fuß an. Das ist die Ausgangsposition.', 'Hebe die Stange aus der Ablage und stell dich vor die Box. Schiebe die Hüfte nach hinten, bis du auf der Box sitzt. Senke dich kontrolliert ab und lass dich nicht auf die Fläche fallen.', 'Halte kurz und stoße dich dann explosiv von der Box ab, indem du Hüfte und Knie streckst.']::text[]),
  ('Speed_Squats', 'de', array['Aus Sicherheitsgründen machst du diese Übung am besten in einem Kniebeugenständer. Lege die Stange zuerst auf die Ablage, die zu deiner Körpergröße passt. Ist die Höhe eingestellt und die Stange beladen, tritt darunter und lege sie quer auf deine hintere Schulterpartie, etwas unterhalb des Nackens.', 'Fasse die Stange auf beiden Seiten und hebe sie aus der Ablage: Drücke dich zuerst mit den Beinen hoch und richte dabei gleichzeitig den Oberkörper auf.', 'Tritt von der Ablage zurück und stell dich mittelweit, etwa schulterbreit, hin; die Fußspitzen zeigen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Hier wird der mittlere Stand verwendet, der die Beine insgesamt entwickelt; du kannst aber jede der drei Standbreiten wählen.', 'Beuge die Knie und senke die Stange ab; bleib dabei aufrecht und halte den Kopf oben. Geh so weit hinunter, bis der Winkel zwischen Oberschenkeln und Waden etwas kleiner als 90 Grad ist, die Oberschenkel also tiefer als parallel zum Boden stehen. Atme in diesem Teil der Bewegung ein. Tipp: Bei richtiger Ausführung bildet die Vorderseite der Knie mit den Zehen eine gedachte gerade Linie, die senkrecht zur Vorderseite steht. Schieben sich die Knie über diese Linie hinaus, also über die Zehen, wird das Knie unnötig belastet und die Übung ist falsch ausgeführt.', 'Atme aus und bringe die Stange so schnell wie möglich und ohne Schwung nach oben: Drücke dich vor allem mit den Fersen vom Boden ab, strecke die Beine und kehre in die Ausgangsposition zurück. Hinweis: Führe diese Übung so schnell wie möglich aus, aber ohne die saubere Technik aufzugeben und ohne Schwung zu holen.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Spell_Caster', 'de', array['Nimm in jede Hand eine Kurzhantel im Obergriff. Stell dich breit hin, Hüfte und Knie gestreckt. Das ist deine Ausgangsposition.', 'Drehe zu Beginn den Oberkörper und zieh beide Kurzhanteln auf eine Seite neben die Hüfte.', 'Halte die Arme gestreckt und die Kurzhanteln parallel zum Boden, drehe den Oberkörper und schwinge die Gewichte auf die andere Seite.', 'Wechsle weiter ab und drehe von einer Seite zur anderen, bis der Satz beendet ist.']::text[]),
  ('Spider_Crawl', 'de', array['Leg dich bäuchlings auf den Boden. Stütze dich auf Hände und Zehen, die Füße zusammen, der Körper gerade. Die Arme sind auf 90 Grad gebeugt. Das ist deine Ausgangsposition.', 'Hebe zu Beginn einen Fuß vom Boden. Drehe das Bein nach außen und führe das Knie so weit wie möglich nach vorn zum Ellbogen.', 'Bringe das Bein in die Ausgangsposition zurück und wiederhole das Ganze auf der anderen Seite.']::text[]),
  ('Spider_Curl', 'de', array['Lege die Stange auf den Teil der Scott-Bank, auf dem du sonst sitzt. Richte sie so aus, dass sie im Gleichgewicht liegt und nicht herunterfällt.', 'Geh auf die Vorderseite der Scott-Bank, also dorthin, wo sonst die Arme liegen, und lehne dich in 45 Grad Schräglage dagegen; Oberkörper und Bauch drücken gegen diese Vorderseite.', 'Stell die Füße, besonders die Zehen, fest auf den Boden und lege die Oberarme auf das Polster an der Innenseite der Scott-Bank.', 'Greife die Stange im Untergriff, die Handflächen zeigen nach oben, die Hände etwa schulterbreit oder etwas enger.', 'Hebe die Stange langsam an und atme dabei aus. Halte die angespannte Position eine Sekunde und spanne den Bizeps fest an.', 'Atme ein und führe die Stange langsam in die Ausgangsposition zurück.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Spinal_Stretch', 'de', array['Setz dich mit geradem Rücken auf einen Stuhl, die Füße stehen fest auf dem Boden.', 'Verschränke die Finger hinter dem Kopf, die Ellbogen zeigen nach außen, das Kinn ist gesenkt.', 'Drehe den Oberkörper etwa 3-mal so weit du kannst zu einer Seite. Beuge dich danach nach vorn und drehe den Rumpf so, dass dein Ellbogen an der Innenseite des Knies in Richtung Boden geht.', 'Richte dich wieder auf und wiederhole alles zur anderen Seite.']::text[]),
  ('Split_Clean', 'de', array['Die Langhantel liegt nah an den Schienbeinen auf dem Boden; fasse sie im Obergriff knapp außerhalb der Beine. Senke die Hüfte, das Gewicht auf den Fersen, den Rücken gerade, den Kopf nach vorn gerichtet, die Brust oben und die Schultern knapp vor der Stange. Das ist deine Ausgangsposition.', 'Starte den ersten Zug, indem du dich über die Fersen abdrückst und die Knie streckst. Der Rückenwinkel bleibt gleich und die Arme bleiben gestreckt. Führe das Gewicht kontrolliert bis über die Knie.', 'Jetzt folgt der zweite Zug, aus dem beim Umsetzen der größte Teil der Beschleunigung kommt. Nähert sich die Stange der Mitte der Oberschenkel, beginnst du die Hüfte zu strecken. Beschleunige wie bei einem Sprung: Strecke Hüfte, Knie und Sprunggelenke und bringe die Stange mit Tempo nach oben. Aktiv mit den Armen ziehen musst du nicht, um das Gewicht zu beschleunigen; am Ende des zweiten Zugs ist der Körper ganz gestreckt und leicht nach hinten gelehnt, die Arme sind noch immer gestreckt.', 'Ist die volle Streckung erreicht, gehst du in den dritten Zug über: Zieh die Schultern energisch hoch und beuge die Arme, die Ellbogen nach oben und außen. Am höchsten Punkt der Streckung ziehst du dich entschlossen nach unten und drehst dabei die Ellbogen unter die Stange.', 'Fange die Stange im Ausfallschritt und setze dabei energisch einen Fuß nach vorn und einen nach hinten. Die Stange liegt auf den nach vorn geschobenen Schultern und berührt leicht den Hals, die Hände sind locker. Sinke weiter bis in die tiefste Position; das erleichtert das Aufstehen.', 'Steh sofort wieder auf: Drücke dich über die Fersen ab, der Oberkörper bleibt aufrecht, die Ellbogen bleiben oben. Bringe beim Aufstehen die Füße zusammen.']::text[]),
  ('Split_Jerk', 'de', array['Du stehst, das Gewicht liegt vorn auf den Schultern. Beginne mit dem Auftakt: Die Füße stehen direkt unter der Hüfte, beuge die Knie, ohne die Hüfte nach hinten zu schieben.', 'Geh nur ein kleines Stück hinunter und kehre die Richtung so kraftvoll wie möglich um. Drücke dich über die Fersen ab, um möglichst viel Tempo und Kraft zu erzeugen, und nimm den Kopf aus dem Weg, wenn die Stange die Schultern verlässt. In dem Moment, in dem die Füße vom Boden abheben, müssen sie so schnell wie möglich in die Fangposition.', 'In dem kurzen Augenblick, in dem die Füße nicht aktiv gegen die Plattform drücken, schiebt dich dein Druck gegen die Stange nach unten. Setze die Füße in den Ausfallschritt, einen nach vorn und einen nach hinten, die Knie leicht gebeugt. Fange die Stange mit gesperrten Armen über dem Kopf.', 'Komm wieder in den Stand und stell die Füße zusammen.']::text[]),
  ('Split_Jump', 'de', array['Geh in den Ausfallschritt: ein Fuß vorn mit gebeugtem Knie, das hintere Knie berührt fast den Boden.', 'Achte darauf, dass das vordere Knie über der Mittellinie des Fußes steht.', 'Strecke beide Beine und spring so hoch du kannst; schwinge die Arme mit, um Höhe zu gewinnen.', 'Führe die Füße im Sprung zusammen und bringe sie bei der Landung wieder an ihre ursprünglichen Plätze.', 'Fange den Aufprall ab, indem du in die Ausgangsposition zurücksinkst.']::text[]),
  ('Split_Snatch', 'de', array['Eine beladene Langhantel liegt auf dem Boden, nah an den Schienbeinen oder direkt an ihnen; greife sie weit. Die Füße stehen direkt unter der Hüfte und sind so weit wie nötig nach außen gedreht. Senke die Hüfte, heb die Brust und schau nach vorn. Die Schultern befinden sich knapp vor der Stange. Das ist die Ausgangsposition.', 'Starte den ersten Zug, indem du dich über den vorderen Teil der Fersen abdrückst und die Stange vom Boden hebst. Der Rückenwinkel bleibt gleich, bis die Stange an den Knien vorbei ist.', 'Geh in den zweiten Zug über: Strecke Hüfte, Knie und Sprunggelenke und treibe die Stange so schnell wie möglich nach oben. Sie bleibt dabei nah am Körper. Am höchsten Punkt der Streckung ziehst du die Schultern hoch und lässt die Ellbogen zur Seite hin beugen.', 'Während die Füße in die Fangposition wechseln, ziehst du dich kraftvoll unter die Stange und bringst sie über den Kopf. Setze die Füße energisch in den Ausfallschritt, einen nach vorn und einen nach hinten. Fange die Stange so tief wie möglich, die Arme über dem Kopf ganz gestreckt.', 'Halte die Stange über dem vorderen Teil der Fersen, Kopf und Brust oben, drücke dich über die Fersen in den Stand und stell dabei die Füße zusammen.', 'Lege das Gewicht vorsichtig auf den Boden zurück.']::text[]),
  ('Split_Squat_with_Dumbbells', 'de', array['Stell dich in Schrittstellung: der hintere Fuß steht erhöht, der vordere Fuß vorn.', 'Nimm in jede Hand eine Kurzhantel und lass sie seitlich hängen. Das ist deine Ausgangsposition.', 'Geh nun hinunter: Beuge Knie und Hüfte und senke den Körper ab. Bleib während der ganzen Bewegung in guter Haltung. Das vordere Knie bleibt dabei in einer Linie mit dem Fuß.', 'Drücke dich am tiefsten Punkt über die Ferse ab, strecke Knie und Hüfte und kehre in die Ausgangsposition zurück.']::text[]),
  ('Split_Squats', 'de', array['Beginne im Stand. Spring in die Schrittstellung, ein Bein vorn und eins hinten; beuge dabei die Knie und senke die Hüfte leicht.', 'Kehre beim Absinken sofort die Richtung um: Steh wieder auf, spring ab und wechsle die Stellung der Beine. Wiederhole das 5-10 Mal pro Bein.']::text[]),
  ('Squat_Jerk', 'de', array['Du stehst, das Gewicht liegt vorn auf den Schultern. Beginne mit dem Auftakt: Die Füße stehen direkt unter der Hüfte, beuge die Knie, ohne die Hüfte nach hinten zu schieben. Geh nur ein kleines Stück hinunter und kehre die Richtung so kraftvoll wie möglich um. Drücke dich über die Fersen ab, um möglichst viel Tempo und Kraft zu erzeugen, und nimm den Kopf aus dem Weg, wenn die Stange die Schultern verlässt.', 'In dem Moment, in dem die Füße vom Boden abheben, müssen sie so schnell wie möglich in die Fangposition. In dem kurzen Augenblick, in dem die Füße nicht aktiv gegen die Plattform drücken, schiebt dich dein Druck gegen die Stange nach unten. Setze die Füße energisch knapp außerhalb der Hüfte auf, so weit wie nötig nach außen gedreht. Fange die Stange in der tiefen Hocke, die Arme über dem Kopf ganz gestreckt.', 'Halte die Stange über dem vorderen Teil der Fersen, Kopf und Brust oben, und drücke dich über die Fersen in den Stand. Lege das Gewicht vorsichtig auf den Boden zurück.']::text[]),
  ('Squat_with_Bands', 'de', array['Hänge die Bänder an die Hantelaufnahmen der Stange und befestige sie an Bandhaken, am Ständer oder an Kurzhanteln, sodass die Spannung passt.', 'Tritt unter die Stange und lege sie quer auf die hintere Schulterpartie. Zieh die Schulterblätter zusammen und drehe die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Hebe die Stange mit festem Hohlkreuz im unteren Rücken aus der Ablage und tritt zurück in Position. Ein breiter Stand belastet Rücken, Gesäß, Adduktoren und Beinbeuger stärker. Der Kopf bleibt nach vorn gerichtet.', 'Halte Rücken, Schultern und Rumpf fest, schiebe Knie und Po nach außen und beginne abzusinken. Setz dich mit der Hüfte so weit wie möglich nach hinten. Im Idealfall stehen die Schienbeine senkrecht zum Boden. Liegt die Stange tiefer, muss sich der Oberkörper stärker neigen, damit sie über den Fersen bleibt. Geh hinunter, bis du unter die Parallele kommst, das heißt: Die Hüftfalte liegt auf einer Höhe mit der Oberkante des Knies.', 'Lass das Gewicht auf den Fersen, schiebe Füße und Knie nach außen und drücke dich nach oben; der Kopf führt die Bewegung an. Bleib von Kopf bis Fuß angespannt und steig weiter, bis du wieder in der Ausgangsposition bist.']::text[]),
  ('Squat_with_Chains', 'de', array['Zum Anbringen der Ketten legst du zuerst die Führungskette als Schlaufe über die Hantelaufnahmen der Stange. Die schwere Kette hängst du mit einem Karabinerhaken ein. Stelle die Länge der Führungskette so ein, dass am höchsten Punkt der Bewegung noch ein paar Glieder auf dem Boden liegen.', 'Tritt unter die Stange und lege sie quer auf die hintere Schulterpartie. Zieh die Schulterblätter zusammen und drehe die Ellbogen nach vorn, als wolltest du die Stange über die Schultern biegen. Hebe die Stange mit festem Hohlkreuz im unteren Rücken aus der Ablage und tritt zurück in Position. Ein breiter Stand belastet Rücken, Gesäß, Adduktoren und Beinbeuger stärker. Der Kopf bleibt nach vorn gerichtet.', 'Halte Rücken, Schultern und Rumpf fest, schiebe Knie und Po nach außen und beginne abzusinken. Setz dich mit der Hüfte so weit wie möglich nach hinten. Im Idealfall stehen die Schienbeine senkrecht zum Boden. Liegt die Stange tiefer, muss sich der Oberkörper stärker neigen, damit sie über den Fersen bleibt. Geh hinunter, bis du unter die Parallele kommst, das heißt: Die Hüftfalte liegt auf einer Höhe mit der Oberkante des Knies.', 'Lass das Gewicht auf den Fersen, schiebe Füße und Knie nach außen und drücke dich nach oben; der Kopf führt die Bewegung an. Bleib von Kopf bis Fuß angespannt und steig weiter, bis du wieder in der Ausgangsposition bist.']::text[]),
  ('Squat_with_Plate_Movers', 'de', array['Lege die Stange zuerst knapp unter Schulterhöhe in die Ablage. Lege eine Hantelscheibe ein paar Fuß hinter dem Ständer auf den Boden. Ist die Stange beladen, tritt darunter und lege sie quer auf die hintere Schulterpartie.', 'Fasse die Stange mit beiden Händen und hebe sie aus der Ablage: Drücke dich zuerst mit den Beinen hoch und richte gleichzeitig den Oberkörper auf.', 'Tritt vom Ständer zurück und stell dich breit hin, die Fußspitzen leicht nach außen, ein Fuß auf der Hantelscheibe. Halte den Kopf immer oben. Das ist deine Ausgangsposition.', 'Beuge Knie und Hüfte und senke die Stange langsam ab. Geh hinunter, bis der Winkel zwischen Oberschenkeln und Waden etwas kleiner als 90 Grad ist.', 'Atme aus und hebe die Stange an: Drücke dich mit den Fersen vom Boden ab und strecke Hüfte und Knie.', 'Mach am höchsten Punkt einen Seitschritt, sodass deine Füße auf der anderen Seite der Scheibe zusammenkommen.', 'Schiebe die Hantelscheibe mit dem inneren Fuß über den Boden dorthin, wo du gerade gestanden hast.', 'Stell den inneren Fuß auf die Hantelscheibe und nimm für die nächste Wiederholung einen breiten Stand ein.']::text[]),
  ('Squats_-_With_Bands', 'de', array['Achte zuerst darauf, dass das Band gleichmäßig auf die linke und rechte Körperseite verteilt ist. Fasse dazu beide Enden des Bands mit den Händen und stell beide Füße auf die Mitte des Bands. Die Füße stehen schulterbreit auseinander.', 'Halte das Band auf beiden Seiten gleich hoch. Fasse im Obergriff, die Handflächen zeigen nach vorn, und halte die Griffe neben dem Gesicht. Das ist die Ausgangsposition.', 'Beuge langsam die Knie und geh hinunter, bis die Oberschenkel parallel zum Boden sind; atme dabei aus.', 'Drücke dich über die Fersen wieder hoch in die Ausgangsposition und atme dabei aus.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Stairmaster', 'de', array['Steig auf den Stepper und wähle im Menü die gewünschte Option. Du kannst das Gerät manuell einstellen oder ein Programm laufen lassen. Meist lassen sich Alter und Gewicht eingeben, damit der Kalorienverbrauch beim Training geschätzt wird.', 'Bewege die Beine in gleichmäßigem Rhythmus auf und ab und tritt die Pedale nach unten, aber nicht ganz bis zum Boden. Es empfiehlt sich, die Griffe festzuhalten, damit du nicht fällst. Über die Griffe lässt sich auch die Herzfrequenz messen; das hilft dir, bei einer passenden Intensität zu bleiben.', 'Stepper sind praktisch, gut für Herz und Kreislauf und belasten die Gelenke meist weniger als Laufen im Freien. Sie sind in der Regel deutlich anstrengender als andere Cardiogeräte. Eine Person mit 150 lb verbrennt in 30 Minuten typischerweise mehr als 300 Kalorien, beim Gehen sind es etwa 175 Kalorien.']::text[]),
  ('Standing_Alternating_Dumbbell_Press', 'de', array['Stell dich hin und nimm in jede Hand eine Kurzhantel. Hebe die Kurzhanteln auf Schulterhöhe, die Handflächen zeigen nach vorn, die Ellbogen nach außen. Das ist deine Ausgangsposition.', 'Strecke einen Arm und drücke die Kurzhantel gerade nach oben; die andere Hand bleibt an ihrem Platz. Lehne dich dabei nicht zur Seite und reiße das Gewicht nicht hoch.', 'Halte kurz und bringe das Gewicht dann in die Ausgangsposition zurück.', 'Wiederhole das auf der anderen Seite und wechsle die Arme weiter ab.']::text[]),
  ('Standing_Barbell_Calf_Raise', 'de', array['Aus Sicherheitsgründen machst du diese Übung am besten in einem Kniebeugenständer. Lege die Stange zuerst auf die Ablage, die zu deiner Körpergröße passt. Ist die Höhe eingestellt und die Stange beladen, tritt darunter und lege sie auf deine hintere Schulterpartie, etwas unterhalb des Nackens.', 'Fasse die Stange auf beiden Seiten und hebe sie aus der Ablage: Drücke dich zuerst mit den Beinen hoch und richte dabei gleichzeitig den Oberkörper auf.', 'Tritt von der Ablage zurück und stell dich mittelweit, etwa schulterbreit, hin; die Fußspitzen zeigen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Die Knie bleiben leicht gebeugt und werden nie durchgedrückt. Das ist deine Ausgangsposition. Tipp: Für einen größeren Bewegungsumfang kannst du die Fußballen auch auf einen Holzblock stellen. Sei dabei aber vorsichtig, denn diese Variante verlangt mehr Gleichgewicht und einen stabilen Block.', 'Atme aus und hebe die Fersen, indem du die Sprunggelenke so weit wie möglich streckst und die Waden anspannst. Das Knie bleibt die ganze Zeit unbewegt und wird zu keinem Zeitpunkt gebeugt. Halte die angespannte Position eine Sekunde, bevor du wieder hinuntergehst.', 'Atme ein und kehre langsam in die Ausgangsposition zurück: Senke die Fersen und beuge die Sprunggelenke, bis die Waden gedehnt sind.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Barbell_Press_Behind_Neck', 'de', array['Diese Übung machst du am besten in einem Kniebeugenständer, weil du die Stange dort leichter aufnehmen kannst. Lege die Stange zuerst auf die Ablage, die zu deiner Körpergröße passt. Ist die Höhe eingestellt und die Stange beladen, tritt darunter und lege sie quer auf deine hintere Schulterpartie, etwas unterhalb des Nackens.', 'Fasse die Stange auf beiden Seiten und hebe sie aus der Ablage: Drücke dich zuerst mit den Beinen hoch und richte dabei gleichzeitig den Oberkörper auf.', 'Tritt von der Ablage zurück und stell dich mittelweit, etwa schulterbreit, hin; die Fußspitzen zeigen leicht nach außen. Der Rücken bleibt während der Übung gerade. Das ist deine Ausgangsposition.', 'Atme aus und drücke die Langhantel über den Kopf, bis die Arme ganz gestreckt sind.', 'Halte die Spannung eine Sekunde, atme ein und senke die Langhantel zurück in die Ausgangsposition.', 'Mache die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'de', array['Nimm eine Kurzhantel in eine Hand, die Handfläche zeigt zum Körper. Beuge die Knie leicht und neige den Oberkörper aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Der Rücken bleibt gerade, der Kopf oben.', 'Halte den Oberarm eng am Oberkörper und parallel zum Boden. Der Unterarm zeigt mit dem Gewicht in der Hand senkrecht nach unten. Tipp: Zwischen Unterarm und Oberarm liegt ein Winkel von 90 Grad. Das ist deine Ausgangsposition.', 'Lass den Oberarm ruhig und atme aus, während du das Gewicht mit dem Trizeps anhebst, bis der Unterarm parallel zum Boden und der ganze Arm gestreckt ist. Wie bei vielen Armübungen bewegt sich nur der Unterarm.', 'Halte die Spannung oben eine Sekunde. Atme dann ein und senke die Kurzhantel langsam in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorgibt.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'de', array['Nimm in jede Hand eine Kurzhantel, die Handflächen zeigen zum Körper. Beuge die Knie leicht und neige den Oberkörper aus der Hüfte nach vorn, bis er fast parallel zum Boden ist. Der Rücken bleibt gerade, der Kopf oben. Halte die Oberarme eng am Oberkörper und parallel zum Boden. Die Unterarme zeigen mit den Gewichten in den Händen senkrecht nach unten. Tipp: Zwischen Unterarmen und Oberarmen liegt ein Winkel von 90 Grad. Das ist deine Ausgangsposition.', 'Lass die Oberarme ruhig und atme aus, während du die Gewichte mit dem Trizeps anhebst, bis die Unterarme parallel zum Boden und beide Arme ganz gestreckt sind. Wie bei vielen Armübungen bewegen sich nur die Unterarme.', 'Halte die Spannung oben eine Sekunde. Atme dann ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorgibt.']::text[]),
  ('Standing_Biceps_Cable_Curl', 'de', array['Hänge eine Curlstange am unteren Kabelzug ein und stell dich aufrecht hin. Greif die Stange schulterbreit, die Ellbogen liegen eng am Oberkörper, die Handflächen zeigen nach oben (Untergriff). Das ist deine Ausgangsposition.', 'Atme aus und beuge die Arme, indem du den Bizeps anspannst. Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Zieh weiter, bis der Bizeps voll angespannt ist und die Stange auf Schulterhöhe liegt. Halte dort eine Sekunde und spanne den Muskel fest an.', 'Atme ein und führe die Stange langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Biceps_Stretch', 'de', array['Verschränke die Hände hinter dem Rücken, Handfläche an Handfläche. Strecke die Arme und drehe sie dann so, dass die Handflächen nach unten zeigen.', 'Hebe die Arme an und halte, sobald du die Dehnung im Bizeps spürst.']::text[]),
  ('Standing_Bradford_Press', 'de', array['Lege eine beladene Stange auf Schulterhöhe in eine Ablage. Greif sie schulterbreit im Obergriff und lege sie vorn auf deinen Schultern ab. Das ist deine Ausgangsposition.', 'Strecke zu Beginn die Ellbogen und drücke die Stange über den Kopf. Drück die Ellbogen nicht ganz durch, während du das Gewicht hinter den Kopf führst.', 'Senke die Stange hinter dem Kopf ab, bis deine Ellbogen einen rechten Winkel bilden.', 'Strecke die Ellbogen und drücke die Stange wieder über den Kopf.', 'Senke die Stange vorn in die Ausgangsposition.', 'Wechsle so zwischen vorn und hinten, bis du die empfohlene Zahl an Wiederholungen geschafft hast.']::text[]),
  ('Standing_Cable_Chest_Press', 'de', array['Stelle beide Rollen auf Brusthöhe und wähle ein passendes Gewicht. Nimm in jede Hand einen Griff und stell dich ein bis zwei Fuß vor die Kabel. Für mehr Stabilität kannst du einen Fuß vor den anderen setzen.', 'Bring die Oberarme in einen 90-Grad-Winkel und zieh die Schulterblätter zusammen. Das ist deine Ausgangsposition.', 'Halte den restlichen Körper ruhig und strecke die Ellbogen, um die Griffe nach vorn zu drücken, bis sie vor dir zusammenkommen.', 'Halte am Ende der Bewegung kurz inne und kehre in die Ausgangsposition zurück.']::text[]),
  ('Standing_Cable_Lift', 'de', array['Hänge einen Standardgriff am Kabelturm ein und stelle die Rolle auf die unterste Position.', 'Stell dich seitlich zum Kabelzug, nimm den Griff mit einer Hand und tritt vom Turm weg. Du stehst etwa eine Armlänge von der Rolle entfernt, das Kabel ist durch das Gewicht gespannt. Dein gestreckter Arm bildet eine Linie mit dem Kabel.', 'Stell die Füße schulterbreit auf, geh in die Hocke und fass den Griff mit beiden Händen. Die Arme bleiben ganz gestreckt.', 'Zieh den Griff in einer einzigen Bewegung nach oben und quer über den Körper, bis deine Arme über dem Kopf ganz gestreckt sind.', 'Halte den Rücken gerade und die Arme nah am Körper. Dreh dabei den hinteren Fuß mit und strecke die Beine, damit du den vollen Bewegungsumfang nutzt.', 'Hol erst die Arme zurück, dann den Körper. Kehre langsam und kontrolliert in die neutrale Position zurück.', 'Wiederhole bis zum Muskelversagen.', 'Stell dich danach andersherum auf und führe dieselbe Bewegungsfolge auf der anderen Seite aus.']::text[]),
  ('Standing_Cable_Wood_Chop', 'de', array['Hänge einen Standardgriff am Kabelturm ein und stelle die Rolle auf die oberste Position.', 'Stell dich seitlich zum Kabelzug, nimm den Griff mit einer Hand und tritt vom Turm weg. Du stehst etwa eine Armlänge von der Rolle entfernt, das Kabel ist durch das Gewicht gespannt. Dein gestreckter Arm bildet eine Linie mit dem Kabel.', 'Stell die Füße schulterbreit auf, greif mit der anderen Hand nach oben und fass den Griff mit beiden Händen. Die Arme bleiben ganz gestreckt.', 'Zieh den Griff in einer einzigen Bewegung nach unten und quer über den Körper bis zum vorderen Knie. Dreh dabei den Oberkörper mit.', 'Halte Rücken und Arme gerade und den Rumpf fest. Dreh dabei den hinteren Fuß mit und beuge die Knie, damit du den vollen Bewegungsumfang nutzt.', 'Bleib in deinem Stand und lass die Arme gestreckt. Kehre langsam und kontrolliert in die neutrale Position zurück.', 'Wiederhole bis zum Muskelversagen.', 'Stell dich danach andersherum auf und führe dieselbe Bewegungsfolge auf der anderen Seite aus.']::text[]),
  ('Standing_Calf_Raises', 'de', array['Stelle den gepolsterten Hebel der Wadenmaschine auf deine Körpergröße ein.', 'Geh mit den Schultern unter die Polster und richte die Zehen nach vorn (oder wähle eine der beiden anderen Fußstellungen). Die Fußballen stehen fest auf dem Wadenblock, die Fersen ragen darüber hinaus. Drücke den Hebel hoch, indem du Hüfte und Knie streckst, bis du aufrecht stehst. Die Knie bleiben leicht gebeugt und werden nie durchgedrückt. Die Zehen können nach vorn, nach außen oder nach innen zeigen. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Fersen so hoch wie möglich: Strecke die Sprunggelenke und spanne die Waden an. Die Knie bleiben die ganze Zeit ruhig und dürfen sich zu keinem Zeitpunkt beugen. Halte oben eine Sekunde, bevor du wieder absenkst.', 'Atme ein und geh langsam in die Ausgangsposition zurück: Beuge die Sprunggelenke und senke die Fersen, bis die Waden gedehnt sind.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Concentration_Curl', 'de', array['Nimm eine Kurzhantel in die Hand, mit der du arbeitest, und beuge dich nach vorn. Lass den Arbeitsarm senkrecht zum Boden hängen, der Ellbogen zeigt nach außen. Das ist deine Ausgangsposition.', 'Beuge den Ellbogen und curle das Gewicht nach oben, der Oberarm bleibt ruhig. Spanne oben den Bizeps an und halte kurz.', 'Senke die Kurzhantel wieder in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorgibt.']::text[]),
  ('Standing_Dumbbell_Calf_Raise', 'de', array['Stell dich aufrecht hin und halte zwei Kurzhanteln seitlich neben dem Körper. Stell die Fußballen auf ein festes, stabiles Holzbrett (etwa 2-3 Inch hoch), sodass die Fersen überstehen und den Boden berühren. Das ist deine Ausgangsposition.', 'Richte die Zehen gerade nach vorn (trainiert alle Anteile gleichmäßig), nach innen (betont den äußeren Kopf) oder nach außen (betont den inneren Kopf). Atme aus und hebe die Fersen vom Boden, indem du die Waden anspannst. Halte die Spannung oben eine Sekunde.', 'Atme ein und senke die Fersen langsam in die Ausgangsposition.', 'Wiederhole so oft wie empfohlen.']::text[]),
  ('Standing_Dumbbell_Press', 'de', array['Stell dich schulterbreit hin und nimm in jede Hand eine Kurzhantel. Bring die Kurzhanteln auf Kopfhöhe, die Ellbogen zeigen nach außen und sind etwa 90 Grad gebeugt. Das ist deine Ausgangsposition.', 'Arbeite sauber: kein Schwung aus den Beinen, kein Zurücklehnen. Strecke die Ellbogen und drücke die Gewichte nach oben, bis sie direkt über deinem Kopf zusammenkommen.', 'Halte kurz und führe die Gewichte langsam in die Ausgangsposition zurück.']::text[]),
  ('Standing_Dumbbell_Reverse_Curl', 'de', array['Stell dich aufrecht hin und halte in jeder Hand eine Kurzhantel im Obergriff (Handflächen nach unten). Die Arme sind ganz gestreckt, die Füße stehen schulterbreit. Das ist die Ausgangsposition.', 'Atme aus und beuge die Arme, indem du den Bizeps anspannst. Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Zieh weiter, bis der Bizeps voll angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Halte dort eine Sekunde und spanne den Muskel fest an.', 'Atme ein und führe die Kurzhanteln langsam zurück in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'de', array['Halte die Kurzhanteln vor den Oberschenkeln, die Handflächen zeigen zu den Oberschenkeln.', 'Lass die Arme gestreckt, nur die Ellbogen sind leicht gebeugt, und fixiere diesen Winkel. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Kurzhanteln in einem Halbkreis an, bis sie mit langen Armen über dem Kopf sind.', 'Atme ein und geh langsam auf demselben Weg in die Ausgangsposition zurück.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Dumbbell_Triceps_Extension', 'de', array['Stell dich hin und halte eine Kurzhantel mit beiden Händen, die Füße stehen etwa schulterbreit. Fass die Kurzhantel mit beiden Händen und hebe sie langsam über den Kopf, bis beide Arme ganz gestreckt sind.', 'Das Gewicht liegt in deinen Handflächen, die Daumen umschließen es. Die Handflächen zeigen nach oben zur Decke. Das ist deine Ausgangsposition.', 'Halte die Oberarme nah am Kopf, die Ellbogen eng und senkrecht zum Boden. Senke das Gewicht in einem Halbkreis hinter den Kopf, bis die Unterarme den Bizeps berühren. Tipp: Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Atme bei diesem Schritt ein.', 'Hebe die Kurzhantel mit dem Trizeps zurück in die Ausgangsposition. Atme bei diesem Schritt aus.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Dumbbell_Upright_Row', 'de', array['Nimm in jede Hand eine Kurzhantel im Obergriff (Handflächen nach vorn), die Hände etwas enger als schulterbreit. Die Kurzhanteln liegen vorn auf den Oberschenkeln. Die Arme sind lang und in den Ellbogen leicht gebeugt, der Rücken ist gerade. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Kurzhanteln mit den seitlichen Schultern an. Führe sie nah am Körper nach oben und lass die Ellbogen die Bewegung anführen. Zieh, bis sie fast dein Kinn berühren. Tipp: Die Ellbogen führen die Bewegung. Beim Anheben sind sie immer höher als die Unterarme. Halte außerdem den Oberkörper ruhig und halte oben eine Sekunde.', 'Senke die Kurzhanteln langsam in die Ausgangsposition. Atme in diesem Teil der Bewegung ein.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Elevated_Quad_Stretch', 'de', array['Stell dich mit dem Rücken zu einer Bank oder Stufe, etwa zwei bis drei Fuß davor.', 'Hebe ein Bein nach hinten und lege den Fuß auf der Stufe ab, entweder mit dem Spann oder mit dem Fußballen, je nachdem, was dir angenehmer ist.', 'Lass das Knie des Standbeins leicht gebeugt und schieb es nicht über die Zehen hinaus. Wechsle die Seite.']::text[]),
  ('Standing_Front_Barbell_Raise_Over_Head', 'de', array['Stell dich aufrecht hin und nimm eine Langhantel in die Hände. Greif die Stange mit den Handflächen nach unten und enger als schulterbreit.', 'Die Füße stehen schulterbreit, die Ellbogen sind leicht gebeugt. Das ist die Ausgangsposition.', 'Atme aus und hebe die Langhantel an, bis sie direkt über deinem Kopf ist. Lass die Ellbogen bei jeder Wiederholung leicht gebeugt.', 'Sobald du die Anspannung spürst, atme ein und senke die Langhantel wieder in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Gastrocnemius_Calf_Stretch', 'de', array['Stell die rechte Ferse mit gestrecktem Knie auf eine Stufe, beuge dich nach vorn und fass die rechten Zehen mit der rechten Hand. Das linke Knie ist leicht gebeugt, der Rücken gerade.', 'Trage dein Gewicht auf dem linken Bein und lege die linke Hand auf den linken Oberschenkel.', 'Zieh die rechten Zehen in Richtung Knie, bis du die Dehnung in der Wade spürst.']::text[]),
  ('Standing_Hamstring_and_Calf_Stretch', 'de', array['Lege einen Gürtel, ein Band oder ein Seil um einen Fuß. Stell dich hin und setze diesen Fuß nach vorn.', 'Beuge das hintere Bein, das vordere bleibt gestreckt. Hebe nun die Zehen des vorderen Fußes vom Boden und lehne dich nach vorn.', 'Zieh mit dem Gürtel am Vorderfuß, um die Dehnung in der Wade zu verstärken. Halte 10-20 Sekunden und wiederhole mit dem anderen Fuß.']::text[]),
  ('Standing_Hip_Circles', 'de', array['Stell dich auf ein Bein und halte dich an einer senkrechten Stütze fest.', 'Hebe das Knie des freien Beins auf 90 Grad. Das ist deine Ausgangsposition.', 'Öffne die Hüfte so weit wie möglich und versuche, mit dem Knie einen großen Kreis zu beschreiben.', 'Mach einige langsame Wiederholungen und wiederhole dann auf der anderen Seite.']::text[]),
  ('Standing_Hip_Flexors', 'de', array['Stell dich aufrecht hin, die Wirbelsäule senkrecht, den linken Fuß leicht vor dem rechten.', 'Beuge beide Knie, hebe die hintere Ferse vom Boden und schiebe die rechte Hüfte nach vorn. Eine gründliche, tiefe Dehnung erreichst du in dieser Haltung allerdings nicht, weil der Hüftbeuger kaum loslassen kann, während du auf ihm stehst. Wechsle die Seite.']::text[]),
  ('Standing_Inner-Biceps_Curl', 'de', array['Stell dich hin und halte in jeder Hand eine Kurzhantel an langen Armen. Die Ellbogen liegen eng am Oberkörper. Die Beine stehen etwa schulterbreit auseinander.', 'Dreh die Handflächen nach innen in eine neutrale Stellung. Das ist deine Ausgangsposition.', 'Atme aus und curle die Gewichte nach außen oben, indem du den Bizeps anspannst. Die Oberarme bleiben ruhig. Dreh die Handgelenke dabei so, dass du oben im Untergriff ankommst (Handflächen nach oben).', 'Nur die Unterarme bewegen sich. Zieh weiter, bis der Bizeps voll angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Tipp: Halte die Unterarme in einer Linie mit dem äußeren Teil der Schultermuskeln.', 'Halte diese Position eine Sekunde und spanne den Bizeps fest an.', 'Atme ein und führe die Kurzhanteln langsam in die Ausgangsposition zurück. Dreh die Handgelenke beim Absenken wieder zurück, damit du im neutralen Griff ankommst.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Lateral_Stretch', 'de', array['Stell dich etwas breiter als hüftbreit hin, die Knie leicht gebeugt.', 'Lege die rechte Hand auf die rechte Hüfte, um die Wirbelsäule zu stützen.', 'Hebe den linken Arm senkrecht nach oben und lege die linke Hand hinter den Kopf. Lass sie dort, während du den Oberkörper nach rechts neigst.', 'Verteile dein Gewicht gleichmäßig auf beide Beine (sink nicht in die linke Hüfte). Wechsle die Seite.']::text[]),
  ('Standing_Leg_Curl', 'de', array['Stelle den Hebel der Maschine auf deine Körpergröße ein. Lehne dich mit Blick nach vorn in die Maschine, der Oberkörper ist in der Hüfte etwa 30-45 Grad gebeugt (in geneigter Haltung arbeiten die Beinbeuger besser). Das Polster des Hebels liegt hinten am rechten Bein, einige Inch unterhalb der Wade, die Vorderseite des rechten Beins liegt am Polster der Maschine.', 'Bleib nach vorn gebeugt, achte darauf, dass dein Bein ganz gestreckt ist, und greif die seitlichen Griffe der Maschine. Die Zehen zeigen gerade. Das ist deine Ausgangsposition.', 'Atme aus und beuge das rechte Bein so weit wie möglich nach oben, ohne den Oberschenkel vom Polster zu lösen. Halte die volle Anspannung eine Sekunde.', 'Atme ein und führe das Bein in die Ausgangsposition zurück. Mach die empfohlene Zahl an Wiederholungen.', 'Führe die Übung nun mit dem linken Bein aus.']::text[]),
  ('Standing_Long_Jump', 'de', array['Am besten machst du diese Übung in Sand oder auf einem anderen weichen Untergrund zum Landen. Sorge dafür, dass du die Weite messen kannst. Stell dich schulterbreit in eine halbe Hocke.', 'Hol mit den Armen kräftig Schwung, federe mit den Beinen kurz ab und spring so weit nach vorn, wie du kannst.', 'Versuche, mit den Füßen vor dem Körper zu landen, und strecke die Beine dabei so weit wie möglich nach vorn.', 'Miss die Strecke vom Startpunkt bis zum Landepunkt und halte deine Ergebnisse fest.']::text[]),
  ('Standing_Low-Pulley_Deltoid_Raise', 'de', array['Stell dich rechts neben einen tiefen Kabelzug. Greif mit der linken Hand quer vor dem Körper einen Einzelgriff am unteren Kabelzug im Obergriff (Handfläche nach unten). Der Arm ruht vor dir. Halte dich mit der rechten Hand an der Maschine fest, das gibt dir mehr Halt und Gleichgewicht.', 'Achte darauf, dass dein Rücken aufrecht ist und die Füße schulterbreit stehen. Das ist die Ausgangsposition.', 'Atme aus und führe die linke Hand quer vor dem Körper nach außen, bis sie auf Schulterhöhe ist.', 'Spüre oben eine Sekunde lang die Anspannung. Atme dann ein und senke den Griff langsam in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('Standing_Low-Pulley_One-Arm_Triceps_Extension', 'de', array['Stell dich neben den unteren Kabelzug und nimm einen Einzelgriff in die linke Hand. Dreh dich von der Maschine weg und halte den Griff mit gestrecktem Arm seitlich am Körper. Hebe den Griff nun mit beiden Händen direkt über den Kopf, die Handfläche zeigt nach vorn. Der Oberarm steht ganz senkrecht (im rechten Winkel zum Boden). Lege die rechte Hand an den linken Ellbogen, um ihn ruhig zu halten. Das ist die Ausgangsposition.', 'Halte den Oberarm nah am Kopf (Ellbogen eng) und senkrecht zum Boden. Senke das Gewicht in einem Halbkreis hinter den Kopf, bis der Unterarm den Bizeps berührt. Tipp: Der Oberarm bleibt ruhig, nur der Unterarm bewegt sich. Atme bei diesem Schritt ein.', 'Hebe den Griff mit dem Trizeps zurück in die Ausgangsposition. Atme bei diesem Schritt aus.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('Standing_Military_Press', 'de', array['Lege eine Langhantel etwa auf Brusthöhe in ein Kniebeugenrack. Wenn das Gewicht aufgelegt ist, greif die Stange im Obergriff (Handflächen nach vorn), die Hände weiter als schulterbreit.', 'Beuge die Knie leicht und nimm die Langhantel auf das Schlüsselbein. Hebe sie heraus, sodass sie auf der Brust aufliegt. Geh einen Schritt zurück und stell die Füße schulterbreit auf.', 'Wenn du die Stange in der richtigen Griffweite hältst, drücke sie über den Kopf, bis die Arme durchgestreckt sind. Halte sie etwa über den Schultern und leicht vor dem Kopf. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam bis zum Schlüsselbein.', 'Atme aus und drücke die Stange wieder nach oben in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Olympic_Plate_Hand_Squeeze', 'de', array['Stell dich aufrecht hin und halte in jeder Hand eine Hantelscheibe am Rand, die Arme lang, im neutralen Griff (Handflächen nach innen). Die Füße stehen schulterbreit. Das ist deine Ausgangsposition.', 'Lass die Scheiben absinken, bis die Finger fast gestreckt sind, das Gewicht aber noch halten können. Atme dabei ein.', 'Atme nun aus und schließe die Hände, um die Scheiben wieder in die Ausgangsposition zu heben.', 'Mach so viele Wiederholungen, wie dein Programm vorschreibt.']::text[]),
  ('Standing_One-Arm_Cable_Curl', 'de', array['Stell dich neben den unteren Kabelzug und nimm einen Einzelgriff. Geh so weit von der Maschine weg, dass dein Arm das Gewicht trägt.', 'Der Oberarm bleibt ruhig und senkrecht zum Boden, der Ellbogen eng am Körper, die Handfläche zeigt nach vorn. Lege die Hand des anderen Arms an die Taille. So hältst du das Gleichgewicht.', 'Atme aus und curle den Griff langsam nach oben, bis der Unterarm den Bizeps berührt. Der Oberarm bleibt dabei ruhig. Tipp: Nur der Unterarm bewegt sich.', 'Halte die Anspannung und drücke den Bizeps fest zusammen. Atme dann ein und senke den Griff in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wechsle den Arm und führe die Übung mit dem anderen aus.']::text[]),
  ('Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'de', array['Stell dich hinter eine Schrägbank, dorthin, wo ein Trainingspartner zum Absichern stehen würde. Halte eine Kurzhantel in einer Hand und lege den Arm im Untergriff (Handfläche nach oben) über die Schrägbank.', 'Stütze die freie Hand an der Ecke oder Seite der Schrägbank ab. Die Brust drückt gegen den oberen Teil der Lehne, die Füße stehen in weitem Stand fest auf dem Boden. Das ist die Ausgangsposition.', 'Atme aus und curle die Kurzhantel nach oben, indem du den Bizeps anspannst. Der Oberarm bleibt ruhig, nur der Unterarm bewegt sich. Zieh weiter, bis der Bizeps voll angespannt ist und die Kurzhantel auf Schulterhöhe ist. Halte dort eine Sekunde.', 'Atme ein und führe die Kurzhantel langsam in die Ausgangsposition zurück.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wechsle den Arm und führe die Übung mit dem anderen aus.']::text[]),
  ('Standing_One-Arm_Dumbbell_Triceps_Extension', 'de', array['Stell dich hin und halte eine Kurzhantel in einer Hand, die Füße stehen etwa schulterbreit. Strecke den Arm mit der Kurzhantel ganz über den Kopf. Tipp: Der kleine Finger zeigt zur Decke, die Handfläche nach vorn. Die Kurzhantel ist über deinem Kopf.', 'Das ist deine Ausgangsposition.', 'Halte den Oberarm nah am Kopf (Ellbogen eng) und senkrecht zum Boden. Senke das Gewicht in einem Halbkreis hinter den Kopf, bis der Unterarm den Bizeps berührt. Tipp: Der Oberarm bleibt ruhig, nur der Unterarm bewegt sich. Atme bei diesem Schritt ein.', 'Hebe die Kurzhantel mit dem Trizeps zurück in die Ausgangsposition. Atme bei diesem Schritt aus.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('Standing_Overhead_Barbell_Triceps_Extension', 'de', array['Stell dich hin und halte eine Langhantel oder SZ-Stange im Obergriff (Handflächen nach vorn), die Hände enger als schulterbreit. Die Füße stehen etwa schulterbreit.', 'Hebe die Stange nun über den Kopf, bis die Arme ganz gestreckt sind. Halte die Ellbogen eng. Das ist deine Ausgangsposition.', 'Halte die Oberarme nah am Kopf, die Ellbogen eng und senkrecht zum Boden. Senke das Gewicht in einem Halbkreis hinter den Kopf, bis die Unterarme den Bizeps berühren. Tipp: Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Atme bei diesem Schritt ein.', 'Hebe die Stange mit dem Trizeps zurück in die Ausgangsposition. Atme bei diesem Schritt aus.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Palm-In_One-Arm_Dumbbell_Press', 'de', array['Halte eine Kurzhantel in einer Hand im neutralen Griff, der Arm hängt gestreckt an der Seite. Halte dich mit dem anderen Arm an einer Schrägbank fest, um das Gleichgewicht zu halten.', 'Die Füße stehen schulterbreit. Hebe die Kurzhantel nun langsam an, bis dein Arm einen 90-Grad-Winkel bildet. Hinweis: Der Unterarm steht senkrecht zum Boden. Behalte den neutralen Griff während der ganzen Übung bei.', 'Drücke die Kurzhantel langsam nach oben, bis der Arm ganz gestreckt ist. Das ist die Ausgangsposition.', 'Atme ein und senke das Gewicht, bis der Arm wieder einen 90-Grad-Winkel bildet.', 'Spüre eine Sekunde lang die Anspannung. Atme dann aus und drücke das Gewicht wieder in Richtung Ausgangsposition. Halte dich weiter an der Schrägbank fest und lass die Füße stehen, damit du während der Übung im Gleichgewicht bleibst.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wechsle den Arm und wiederhole die Übung.']::text[]),
  ('Standing_Palms-In_Dumbbell_Press', 'de', array['Halte in jeder Hand eine Kurzhantel im neutralen Griff, die Arme hängen gestreckt an den Seiten. Die Füße stehen schulterbreit. Hebe die Kurzhanteln nun langsam an, bis deine Arme einen 90-Grad-Winkel bilden. Hinweis: Die Unterarme stehen senkrecht zum Boden. Das ist die Ausgangsposition.', 'Behalte den neutralen Griff während der ganzen Übung bei. Drücke die Kurzhanteln langsam nach oben, bis die Arme ganz gestreckt sind.', 'Atme ein und senke die Gewichte, bis die Arme wieder einen 90-Grad-Winkel bilden.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'de', array['Stell dich aufrecht hin und halte eine Langhantel mit langen Armen hinter dem Gesäß, im Obergriff (die Handflächen zeigen nach hinten, vom Gesäß weg), die Hände schulterbreit.', 'Schau geradeaus, die Füße stehen schulterbreit. Das ist die Ausgangsposition.', 'Atme aus und hebe die Langhantel langsam an, indem du die Handgelenke in einem Halbkreis zur Decke hin beugst. Hinweis: Bei dieser Übung bewegen sich nur die Handgelenke.', 'Halte die Anspannung eine Sekunde. Atme dann ein und senke die Langhantel in die Ausgangsposition.', 'Mach die empfohlene Zahl an Wiederholungen.', 'Wenn du fertig bist, beuge die Knie und lege die Langhantel im Kniebeugenrack oder auf dem Boden ab. Tipp: Am einfachsten nimmst du sie aus einem Kniebeugenrack auf oder lässt sie dir von einem Partner reichen.']::text[]),
  ('Standing_Pelvic_Tilt', 'de', array['Stell die Füße hüftbreit auf.', 'Beuge die Knie leicht, damit sie locker und federnd bleiben.', 'Wenn du magst, bewege das Becken ein paarmal vor und zurück, bevor du das Steißbein für diese Dehnung vorn hältst.']::text[]),
  ('Standing_Rope_Crunch', 'de', array['Hänge ein Seil am oberen Kabelzug ein und wähle ein passendes Gewicht.', 'Stell dich mit dem Rücken zum Kabelturm. Nimm das Seil mit beiden Händen über die Schultern und halte es an der oberen Brust. Das ist deine Ausgangsposition.', 'Runde die Wirbelsäule ein und crunche das Gewicht so weit nach unten, wie du kannst.', 'Halte die stärkste Anspannung einen Moment und kehre dann in die Ausgangsposition zurück.']::text[]),
  ('Standing_Soleus_And_Achilles_Stretch', 'de', array['Stell die Füße hüftbreit auf, einen Fuß leicht vor den anderen.', 'Beuge beide Knie und lass die hintere Ferse am Boden. Wechsle die Seite.']::text[]),
  ('Standing_Toe_Touches', 'de', array['Stell dich so hin, dass du vor und hinter dir etwas Platz hast.', 'Beuge dich mit gestreckten Beinen aus der Hüfte nach vorn, bis du loslassen kannst und der Oberkörper vor dir herabhängt. Lass Arme und Hände locker hängen. Halte 10 bis 20 Sekunden.']::text[]),
  ('Standing_Towel_Triceps_Extension', 'de', array['Stell dich schulterbreit hin und halte ein Ende eines Handtuchs mit beiden Händen, die Arme ganz über den Kopf gestreckt. Die Ellbogen zeigen nach innen, die Arme stehen senkrecht zum Boden, die Handflächen zeigen zueinander. Das ist deine Ausgangsposition.', 'Sag deinem Partner oder deiner Partnerin Bescheid, damit er oder sie das andere Ende des Handtuchs greift und Widerstand gibt. Halte die Oberarme dicht am Kopf (Ellbogen innen) und senkrecht zum Boden und senke das Handtuch im Halbkreis hinter den Kopf, bis die Unterarme den Bizeps berühren. Tipp: Die Oberarme bleiben ruhig, nur die Unterarme bewegen sich. Atme dabei ein.', 'Zieh das Handtuch mit der Kraft des Trizeps wieder nach oben in die Ausgangsposition. Atme dabei aus.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Standing_Two-Arm_Overhead_Throw', 'de', array['Stell dich schulterbreit hin und halte einen Medizinball mit beiden Händen. Führe den Ball zu Beginn weit hinter den Kopf, beuge dabei leicht die Knie und lehne dich zurück.', 'Schleudere den Ball mit voller Wucht nach vorn. Beuge dich dabei in der Hüfte und setze den ganzen Körper ein.', 'Wirf den Ball einem Partner zu oder gegen eine Wand und fang ihn auf, wenn er zurückprallt.']::text[]),
  ('Star_Jump', 'de', array['Steh locker da, die Füße schulterbreit, die Arme dicht am Körper.', 'Geh zum Start in die halbe Kniebeuge und spring dann explosiv so hoch wie möglich. Streck den ganzen Körper und spreize Beine und Arme vom Körper weg.', 'Zieh Arme und Beine bei der Landung wieder heran und fang den Aufprall mit den Beinen ab.']::text[]),
  ('Step-up_with_Knee_Raise', 'de', array['Stell dich mit geschlossenen Füßen vor eine Box oder Bank in passender Höhe. Das ist deine Ausgangsposition.', 'Setz zum Start den linken Fuß oben auf die Bank. Strecke Hüfte und Knie des vorderen Beins, bis du auf der Box stehst. Während du auf dem linken Bein stehst, beuge rechtes Knie und rechte Hüfte und zieh das Knie so hoch, wie du kannst.', 'Steig auf demselben Weg wieder von der Box herunter und wiederhole den Ablauf mit dem anderen Bein.']::text[]),
  ('Step_Mill', 'de', array['Steig auf den Stepmill und wähle im Menü, was du möchtest: eine manuelle Einstellung oder ein fertiges Programm. Meist kannst du Alter und Gewicht eingeben, damit das Gerät den Kalorienverbrauch schätzt. Pass auf, dass du beim Treppensteigen nicht stolperst. Am besten hältst du dich an den Griffen fest, damit du nicht stürzt.', 'Ein Stepmill ist praktisch, trainiert Herz und Kreislauf und belastet die Gelenke meist weniger als Laufen im Freien, bei ähnlichem Kalorienverbrauch. Er ist in der Regel deutlich anstrengender als andere Cardiogeräte. Wer 150 lb wiegt, verbrennt in 30 Minuten meist über 300 Kalorien, beim Gehen sind es etwa 175.']::text[]),
  ('Stiff-Legged_Barbell_Deadlift', 'de', array['Greif eine Stange im Obergriff, die Handflächen zeigen nach unten. Bei viel Gewicht brauchst du vielleicht Handgelenkbandagen.', 'Steh mit geradem Oberkörper, die Füße schulterbreit oder enger. Die Knie sind leicht gebeugt. Das ist deine Ausgangsposition.', 'Lass die Knie unbewegt und den Rücken gerade und beuge dich in der Hüfte, bis die Langhantel knapp über den Füßen ist. Geh weiter nach vorn, als wolltest du etwas vom Boden aufheben, bis du die Dehnung in den Beinbeugern spürst. Atme dabei ein.', 'Strecke die Hüfte und richte den Oberkörper wieder auf, bis du in der Ausgangsposition bist. Atme dabei aus.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Stiff-Legged_Dumbbell_Deadlift', 'de', array['Nimm zwei Kurzhanteln und lass sie mit gestreckten Armen seitlich am Körper hängen.', 'Steh mit geradem Oberkörper, die Füße schulterbreit oder enger. Die Knie sind leicht gebeugt. Das ist deine Ausgangsposition.', 'Lass die Knie unbewegt und den Rücken gerade und beuge dich in der Taille, bis die Kurzhanteln knapp über den Füßen sind. Geh weiter nach vorn, als wolltest du etwas vom Boden aufheben, bis du die Dehnung in den Beinbeugern spürst. Atme dabei aus.', 'Strecke Hüfte und Taille und richte den Oberkörper wieder auf, bis du in der Ausgangsposition bist. Atme dabei ein.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Stiff_Leg_Barbell_Good_Morning', 'de', array['Mach diese Übung aus Sicherheitsgründen am besten in einem Squat Rack. Lege die Stange zuerst in der Höhe ab, die am besten zu deiner Größe passt. Stimmt die Höhe und ist die Stange beladen, geh unter die Stange und leg sie quer auf die hintere Schulterpartie, knapp unterhalb des Nackens.', 'Fass die Stange links und rechts mit je einer Hand. Heb sie aus der Ablage, indem du mit den Beinen drückst und gleichzeitig den Oberkörper aufrichtest.', 'Tritt vom Rack weg und stell die Füße schulterbreit in einen mittleren Stand. Halte den Kopf die ganze Zeit oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und halte den Rücken gerade. Das ist deine Ausgangsposition.', 'Die Beine bleiben ruhig. Atme ein und beuge dich in der Hüfte nach vorn. Senke den Oberkörper, bis er parallel zum Boden ist.', 'Atme aus und bring die Stange wieder nach oben, indem du den Oberkörper in die Ausgangsposition aufrichtest.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Stomach_Vacuum', 'de', array['Steh aufrecht, die Füße schulterbreit auseinander, und leg die Hände an die Hüften. Das ist deine Ausgangsposition.', 'Atme langsam so viel Luft ein, wie du kannst. Atme dann so weit wie möglich aus, zieh dabei den Bauch so weit wie möglich ein und halte diese Position. Stell dir vor, dein Nabel berührt die Wirbelsäule.', 'Eine isometrische Kontraktion dauert etwa 20 Sekunden. Versuch, in diesen 20 Sekunden normal zu atmen. Atme dann ein und lass den Bauch in die Ausgangsposition zurück.', 'Wenn du die Übung beherrschst, versuch sie länger als 20 Sekunden zu halten. Tipp: Du kannst dich nach und nach auf 40-60 Sekunden steigern.', 'Wiederhole die Übung für die empfohlene Zahl an Sätzen.']::text[]),
  ('Straight-Arm_Dumbbell_Pullover', 'de', array['Stell eine Kurzhantel hochkant auf eine Flachbank.', 'Achte darauf, dass die Kurzhantel sicher oben auf der Bank steht. Leg dich dann quer zur Bank, sodass Oberkörper und Bank ein Kreuz bilden und nur die Schultern aufliegen. Die Hüfte ist tiefer als die Bank, die Beine sind gebeugt, die Füße stehen fest auf dem Boden. Auch der Kopf ragt über die Bank hinaus.', 'Fass die Kurzhantel mit beiden Händen und halte sie mit gestreckten Armen gerade über der Brust. Beide Handflächen drücken von unten gegen eine der Hantelseiten. Das ist deine Ausgangsposition. Vorsicht: Prüfe immer, ob die Kurzhantel für diese Übung fest sitzt. Bei lockeren Scheiben kann sie auseinanderfallen und dir aufs Gesicht fallen.', 'Halte die Arme gestreckt, atme ein und senke das Gewicht langsam im Bogen hinter den Kopf, bis du die Dehnung in der Brust spürst.', 'Führe die Kurzhantel von dort auf demselben Bogen zurück in die Ausgangsposition und atme dabei aus.', 'Halte das Gewicht eine Sekunde in der Ausgangsposition und wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Straight-Arm_Pulldown', 'de', array['Fass die breite Stange am oberen Zug einer Latzugmaschine im Obergriff (Handflächen nach unten), breiter als die Schultern. Geh dann etwa two feet zurück.', 'Neig den Oberkörper aus der Taille um etwa 30 Grad nach vorn. Die Arme sind vor dir ganz gestreckt, die Ellbogen leicht gebeugt. Sind die Arme nicht ganz gestreckt, geh noch ein Stück zurück, bis sie es sind. Sind die Arme gestreckt und der Oberkörper leicht geneigt, spann den Latissimus an; dann kann es losgehen.', 'Lass die Arme gestreckt und zieh die Stange mit dem Latissimus nach unten, bis die Hände neben den Oberschenkeln sind. Atme dabei aus.', 'Geh mit weiterhin gestreckten Armen in die Ausgangsposition zurück und atme dabei ein.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Straight_Bar_Bench_Mid_Rows', 'de', array['Leg eine beladene Langhantel auf das Ende einer Bank. Stell dich hinter der Stange auf die Bank und fass sie mittelweit im Obergriff. Schieb die Hüfte nach hinten, heb die Brust und halte die Wirbelsäule neutral. Das ist deine Ausgangsposition.', 'Zieh die Schulterblätter zusammen und beuge die Ellbogen, um die Stange zum Oberkörper zu rudern. Bewege dich kontrolliert und ohne Ruck.', 'Halte kurz inne und senke die Stange dann langsam in die Ausgangsposition. Achte darauf, ganz nach unten zu gehen.']::text[]),
  ('Straight_Raises_on_Incline_Bench', 'de', array['Leg eine Stange hinter dem Kopfende einer Schrägbank auf den Boden.', 'Leg dich bäuchlings auf die Bank. Nimm die Langhantel im Obergriff mit gestreckten Armen vom Boden auf und lass sie gerade nach unten hängen. Das ist deine Ausgangsposition.', 'Heb die Langhantel nun nach vorn vor den Kopf, die Arme bleiben gestreckt.', 'Kehr in die Ausgangsposition zurück.']::text[]),
  ('Stride_Jump_Crossover', 'de', array['Stell dich seitlich neben eine Box und setz den Fuß, der ihr näher ist, oben auf, dicht an der Kante.', 'Schwing die Arme nach oben, drück dich mit dem oberen Bein ab und spring so hoch wie möglich. Versuch, das andere Knie nach oben zu reißen.', 'Lande auf der anderen Seite der Box, spiegelverkehrt zur Startstellung: Der Fuß, der anfangs auf der Box stand, ist jetzt am Boden, der andere steht auf der Box.', 'Wiederhole die Bewegung und spring zurück auf die erste Seite.']::text[]),
  ('Sumo_Deadlift', 'de', array['Die beladene Stange liegt am Boden. Tritt so an sie heran, dass sie über der Fußmitte verläuft. Stell die Füße sehr weit auseinander, nahe an die Verschlüsse. Beuge dich in der Hüfte und greif die Stange. Die Arme hängen senkrecht unter den Schultern, zwischen den Beinen; möglich sind Obergriff, Kreuzgriff oder Hakengriff. Lass die Schultern locker, das macht deine Arme faktisch länger.', 'Atme ein, senke dann die Hüfte, Blick nach vorn, Brust raus. Drück dich in den Boden und schieb die Füße auseinander, das Gewicht liegt auf der hinteren Fußhälfte. Strecke Hüfte und Knie.', 'Sobald die Stange an den Knien vorbei ist, lehn dich zurück, schieb die Hüfte gegen die Stange und zieh die Schulterblätter zusammen.', 'Beuge dich in der Hüfte, um das Gewicht wieder abzulegen, und führe es auf dem Weg nach unten kontrolliert.']::text[]),
  ('Sumo_Deadlift_with_Bands', 'de', array['Für Kreuzheben mit kurzen Bändern legst du sie vor dem Start über die Stange und steigst beim Aufstellen hinein. Achte darauf, dass sie unter der hinteren Fußhälfte liegen, genau dort, wo du dich in den Boden drückst.', 'Die beladene Stange liegt am Boden. Tritt so an sie heran, dass sie über der Fußmitte verläuft. Stell die Füße sehr weit auseinander, nahe an die Verschlüsse. Beuge dich in der Hüfte und greif die Stange. Die Arme hängen senkrecht unter den Schultern, zwischen den Beinen; möglich sind Obergriff, Kreuzgriff oder Hakengriff.', 'Atme ein, senke dann die Hüfte, Blick nach vorn, Brust raus. Drück dich in den Boden und schieb die Füße auseinander, das Gewicht liegt auf der hinteren Fußhälfte. Strecke Hüfte und Knie.', 'Sobald die Stange an den Knien vorbei ist, lehn dich zurück, schieb die Hüfte gegen die Stange und zieh die Schulterblätter zusammen.', 'Beuge dich in der Hüfte, um das Gewicht wieder abzulegen, und führe es auf dem Weg nach unten kontrolliert.']::text[]),
  ('Sumo_Deadlift_with_Chains', 'de', array['Befestige die Ketten an den Hülsen der Stange oder häng sie einfach mit der Mitte über die Stange, damit das Gewicht beim Heben stärker zunimmt. Halte die Kettenenden möglichst von den Scheiben fern, damit du sie beim Ablassen nicht triffst.', 'Die beladene Stange liegt am Boden. Tritt so an sie heran, dass sie über der Fußmitte verläuft. Stell die Füße sehr weit auseinander, nahe an die Verschlüsse. Beuge dich in der Hüfte und greif die Stange. Die Arme hängen senkrecht unter den Schultern, zwischen den Beinen; möglich sind Obergriff, Kreuzgriff oder Hakengriff. Lass die Schultern locker, das macht deine Arme faktisch länger.', 'Atme ein, senke dann die Hüfte, Blick nach vorn, Brust raus. Drück dich in den Boden und schieb die Füße auseinander, das Gewicht liegt auf der hinteren Fußhälfte. Strecke Hüfte und Knie.', 'Sobald die Stange an den Knien vorbei ist, lehn dich zurück, schieb die Hüfte gegen die Stange und zieh die Schulterblätter zusammen.', 'Beuge dich in der Hüfte, um das Gewicht wieder abzulegen, und führe es auf dem Weg nach unten kontrolliert.']::text[]),
  ('Superman', 'de', array['Leg dich gestreckt in Bauchlage auf den Boden oder eine Matte. Die Arme sind nach vorn ganz ausgestreckt. Das ist deine Ausgangsposition.', 'Heb Arme, Beine und Brust gleichzeitig vom Boden ab und halte die Spannung 2 Sekunden. Tipp: Spann den unteren Rücken fest an, dann bringt die Übung am meisten. Denk daran, beim Anheben auszuatmen. Hinweis: In der gehaltenen Position solltest du aussehen wie Superman im Flug.', 'Atme ein und senke Arme, Beine und Brust langsam zurück in die Ausgangsposition.', 'Wiederhole die Übung so oft, wie dein Programm es vorgibt.']::text[]),
  ('Supine_Chest_Throw', 'de', array['Diese Übung eignet sich gut für Brustpässe, wenn dir ein Partner oder eine ausreichend stabile Wand fehlt. Leg dich mit gebeugten Knien auf den Rücken.', 'Der Ball liegt zu Beginn auf der Brust, beide Hände halten ihn von unten.', 'Stoß explosiv nach oben, strecke die Ellbogen und wirf den Ball senkrecht über dir so hoch wie möglich.', 'Fang den Ball mit beiden Händen, wenn er herunterkommt.']::text[]),
  ('Supine_One-Arm_Overhead_Throw', 'de', array['Leg dich mit gebeugten Knien auf den Rücken. Halte den Ball in einer Hand und streck den Arm ganz hinter den Kopf. Das ist deine Ausgangsposition.', 'Leite die Bewegung aus der Schulter ein: Richte dich auf und wirf den Ball gerade nach vorn, so weit du kannst.', 'Wirf den Ball einem Partner zu oder lass ihn von einer Wand abprallen.']::text[]),
  ('Supine_Two-Arm_Overhead_Throw', 'de', array['Leg dich mit gebeugten Knien auf den Rücken.', 'Halte den Ball mit beiden Händen und streck die Arme ganz hinter den Kopf. Das ist deine Ausgangsposition.', 'Leite die Bewegung aus den Schultern ein: Richte dich auf und wirf den Ball gerade nach vorn, so weit du kannst.', 'Wirf den Ball einem Partner zu oder lass ihn von einer Wand abprallen.']::text[]),
  ('Suspended_Fallout', 'de', array['Stell die Gurte so ein, dass die Griffe in passender Höhe hängen, unterhalb der Taille.', 'Beginne im Stand und fass die Griffe. Lehn dich in die Gurte, bis du in einer schrägen Liegestützposition bist. Das ist deine Ausgangsposition.', 'Lehn dich mit gestreckten Armen weiter in die Schlingen, sodass dein Körper dem Boden näher kommt. Lass die Schultern sich öffnen, sodass die Arme nach oben und über den Kopf wandern.', 'Halte die Wirbelsäule neutral und den übrigen Körper gerade; nur die Schultergelenke dürfen sich bewegen.', 'Halte am Punkt der stärksten Kontraktion kurz inne und kehr dann in die Ausgangsposition zurück.']::text[]),
  ('Suspended_Push-Up', 'de', array['Befestige deine Schlingen sicher oben an einem Rack oder einem anderen Gegenstand.', 'Lehn dich in die Gurte, nimm in jede Hand einen Griff und geh in die Liegestützposition. Bei ganz gestreckten Armen und guter Haltung solltest du so parallel zum Boden sein, wie du es schaffst.', 'Halte den Rumpf gerade und fest und senke dich langsam ab, indem du die Ellbogen beugst.', 'Geh weiter, bis die Ellbogen über 90 Grad hinaus gebeugt sind. Halte kurz inne und streck die Arme dann, um in die Ausgangsposition zurückzukommen.']::text[]),
  ('Suspended_Reverse_Crunch', 'de', array['Befestige ein Paar Schlingen so, dass die Griffe etwa a foot über dem Boden hängen. Geh mit dem Rücken zum Rack in die Liegestützposition.', 'Steck die Füße in die Griffe. Halte den Körper gerade und lass die Hüfte nicht durchhängen. Das ist deine Ausgangsposition.', 'Beuge zum Start Knie und Hüfte und zieh die Knie zum Oberkörper. Kipp dabei das Becken nach vorn und lass die Wirbelsäule rund werden.', 'Kehr am höchsten Punkt der kontrollierten Bewegung in die Ausgangsposition zurück.']::text[]),
  ('Suspended_Row', 'de', array['Häng die Gurte etwa auf Brusthöhe auf. Nimm in jede Hand einen Griff und lehn dich zurück. Der Körper bleibt gerade, Kopf und Brust oben, die Arme sind ganz gestreckt. Das ist deine Ausgangsposition.', 'Leite die Bewegung ein, indem du die Ellbogen beugst. Schieb dabei die Schulterblätter nach vorn (Protraktion).', 'Halte am Ende der Bewegung inne und kehr dann in die Ausgangsposition zurück.']::text[]),
  ('Suspended_Split_Squat', 'de', array['Häng die Gurte so auf, dass die Griffe 18-30 inches über dem Boden sind.', 'Stell dich mit dem Rücken zur Aufhängung und setz den hinteren Fuß in den Griff hinter dir. Blick nach vorn, Brust raus, das Knie leicht gebeugt. Das ist deine Ausgangsposition.', 'Beuge Knie und Hüfte und senke dich zum Boden ab. Das Gewicht bleibt auf der Ferse, die Haltung hältst du über die ganze Übung.', 'Kehr die Bewegung am tiefsten Punkt um: Strecke Hüfte und Knie und komm in die Ausgangsposition zurück.']::text[]),
  ('Svend_Press', 'de', array['Beginne im Stand.', 'Drück zwei leichte Scheiben mit den Händen zusammen. Halte sie zusammengepresst dicht vor der Brust, damit die Brustmuskeln isometrisch anspannen. Die Finger zeigen nach vorn. Das ist deine Ausgangsposition.', 'Press die Scheiben weiter zwischen den Handflächen zusammen und streck die Arme kontrolliert gerade nach vorn.', 'Halte am Ende der Bewegung inne und kehr dann langsam in die Ausgangsposition zurück.']::text[]),
  ('T-Bar_Row_with_Handle', 'de', array['Steck eine Stange in eine Landmine oder klemm sie in eine Ecke, damit sie nicht wegrutscht. Belade dein Ende mit einem passenden Gewicht.', 'Stell dich über die Stange und leg einen Doppel-D-Rudergriff direkt neben dem Verschluss um sie. Richte dich mit Hüfte und Beinen in den Stand auf.', 'Nimm einen breiten Stand ein, Hüfte nach hinten, Brust raus. Die Arme sind gestreckt. Das ist deine Ausgangsposition.', 'Zieh die Schulterblätter zusammen und beuge die Ellbogen, um das Gewicht zum oberen Bauch zu ziehen. Reiß nicht am Gewicht und schummle nicht.', 'Halte kurz inne und kehr dann in die Ausgangsposition zurück.']::text[]),
  ('Tate_Press', 'de', array['Leg dich auf eine Flachbank, in jeder Hand eine Kurzhantel, abgelegt auf den Oberschenkeln. Die Handflächen zeigen zueinander.', 'Nimm die Oberschenkel zu Hilfe und bring die Kurzhanteln nacheinander, Arm für Arm, nach oben, bis du sie schulterbreit vor dir hältst. Hinweis: Wenn du die Kurzhanteln vor dir hältst, müssen die Arme weiter als schulterbreit auseinander sein, im Obergriff mit den Handflächen nach vorn. Lass die Ellbogen nach außen zeigen. Das ist deine Ausgangsposition.', 'Die Oberarme bleiben ruhig. Atme ein und führe die Kurzhanteln langsam im Halbkreis nach innen und unten, bis sie die obere Brust berühren. Behalte die Kurzhanteln jederzeit voll unter Kontrolle, bewege die Oberarme nicht und leg die Hanteln nicht auf der Brust ab.', 'Atme aus und drück die Kurzhanteln mit dem Trizeps auf demselben Halbkreis in umgekehrter Richtung nach oben. Versuch, die Hanteln dabei zusammenzuhalten. Streck die Arme in der kontrahierten Position ganz durch, halte eine Sekunde und geh dann wieder langsam nach unten. Tipp: Der Weg nach unten sollte mindestens doppelt so lange dauern wie der Weg nach oben.', 'Wiederhole die Bewegung so oft, wie dein Trainingsprogramm es vorgibt.']::text[]),
  ('The_Straddle', 'de', array['Setz dich aufrecht hin. Streck die Beine in V-Form vor dir aus.', 'Leg die Hände auf den Boden und beuge dich so weit wie möglich vor. Halte 10 bis 20 Sekunden.']::text[]),
  ('Thigh_Abductor', 'de', array['Setz dich in die Abduktorenmaschine und wähle ein Gewicht, mit dem du gut zurechtkommst. Wenn die Beine richtig liegen, fass die Griffe an beiden Seiten. Der ganze Oberkörper bleibt von der Taille aufwärts ruhig. Das ist deine Ausgangsposition.', 'Atme aus und drück die Beine langsam gegen die Maschine, sodass sie auseinandergehen.', 'Spür die Kontraktion eine Sekunde lang, atme dann ein und führe die Beine zurück in die Ausgangsposition. Hinweis: Denk daran, den Oberkörper ruhig zu halten, um Verletzungen zu vermeiden.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Thigh_Adductor', 'de', array['Setz dich in die Adduktorenmaschine und wähle ein Gewicht, mit dem du gut zurechtkommst. Wenn die Beine richtig an den Beinpolstern der Maschine liegen, fass die Griffe an beiden Seiten. Der ganze Oberkörper bleibt von der Taille aufwärts ruhig. Das ist deine Ausgangsposition.', 'Atme aus und drück die Beine langsam gegen die Maschine, sodass sie zusammengehen.', 'Spür die Kontraktion eine Sekunde lang, atme dann ein und führe die Beine zurück in die Ausgangsposition. Hinweis: Denk daran, den Oberkörper ruhig zu halten und schnelle, ruckartige Bewegungen zu vermeiden, um Verletzungen vorzubeugen.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Tire_Flip', 'de', array['Greif den Reifen unten an der Lauffläche und stell die Füße ein Stück zurück. Die Brust drückt gegen den Reifen.', 'Strecke Hüfte, Knie und Sprunggelenke, um den Reifen anzuheben, und drück dabei in den Reifen hinein und nach oben.', 'Hat der Reifen einen Winkel von 45 Grad erreicht, mach einen Schritt vor und stoß ein Knie in den Reifen. Greif dabei an den oberen Teil des Reifens um und stoß ihn mit aller Kraft nach vorn, um die Drehung zu beenden. Wiederhole das nach Bedarf.']::text[]),
  ('Toe_Touchers', 'de', array['Leg dich auf den Boden oder eine Matte, der Rücken ist fest an den Boden gedrückt. Die Arme liegen seitlich am Körper, die Handflächen zeigen nach unten.', 'Die Beine berühren sich. Heb sie langsam an, bis sie fast senkrecht zum Boden stehen, die Knie leicht gebeugt. Die Fußsohlen sind parallel zum Boden.', 'Streck die Arme ganz aus, in einem Winkel von 45 Grad zum Boden. Das ist deine Ausgangsposition.', 'Der untere Rücken bleibt am Boden. Heb den Oberkörper langsam an und versuch, mit den Händen die Zehen zu berühren. Denk daran, in diesem Teil der Übung auszuatmen.', 'Atme ein und senke Oberkörper und Arme langsam zurück in die Ausgangsposition. Die Arme bleiben gestreckt und zeigen zu den Zehen.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Torso_Rotation', 'de', array['Steh aufrecht und halte einen Gymnastikball mit beiden Händen. Streck die Arme, sodass der Ball gerade vor dir ist. Das ist deine Ausgangsposition.', 'Dreh den Oberkörper zu einer Seite und folge dem Ball dabei mit dem Blick. Dreh dich dann in die Gegenrichtung zurück. Mach 10-20 Wiederholungen.']::text[]),
  ('Trail_Running_Walking', 'de', array['Laufen oder Wandern auf Trails bringt Blut und Herz fast sofort in Schwung. Sorg für gute Schuhe. Bergauf ziehen dich die Muskeln in Waden und Gesäß nach oben, bergab fangen Knie, Gelenke und Knöchel den Großteil der Stöße ab. Mach bergab kleinere Schritte, lass die Knie gebeugt, um den Aufprall zu mindern, und werde langsamer, damit du nicht stürzt.', 'Wer 150 lb wiegt, kann in 30 Minuten Bergaufgehen über 200 Kalorien verbrennen, auf ebener Strecke sind es 175. Beim Laufen auf dem Trail kann eine Person mit 150 lb in 30 Minuten deutlich über 500 Kalorien verbrennen.']::text[]),
  ('Trap_Bar_Deadlift', 'de', array['Belade eine Trap Bar, auch Hex Bar genannt, mit einem passenden Gewicht; sie liegt am Boden. Stell dich in die Mitte des Geräts und fass beide Griffe.', 'Senke die Hüfte, schau nach vorn und halte die Brust oben.', 'Drück dich zum Start über die Fersen ab und strecke Hüfte und Knie. Der Rücken darf zu keinem Zeitpunkt rund werden.', 'Ist die Bewegung abgeschlossen, lass das Gewicht kontrolliert zurück auf den Boden.']::text[]),
  ('Tricep_Dumbbell_Kickback', 'de', array['Nimm in jede Hand eine Kurzhantel, die Handflächen zeigen zum Körper. Halte den Rücken gerade, beuge leicht die Knie und neig dich aus der Taille nach vorn, bis der Oberkörper fast parallel zum Boden ist. Der Kopf bleibt oben. Die Oberarme liegen dicht am Oberkörper und parallel zum Boden, die Unterarme zeigen mit den Gewichten zum Boden. Unterarm und Oberarm bilden einen Winkel von 90 Grad. Das ist deine Ausgangsposition.', 'Die Oberarme bleiben ruhig. Atme aus und heb die Gewichte mit dem Trizeps, bis die Arme ganz gestreckt sind. Konzentrier dich darauf, den Unterarm zu bewegen.', 'Halte in der oberen Kontraktion kurz inne, atme dann ein und senke die Kurzhanteln langsam in die Ausgangsposition.', 'Wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Tricep_Side_Stretch', 'de', array['Führe den rechten Arm quer vor dem Körper über die linke Schulter. Halte den Ellbogen mit der linken Hand, bis du die Dehnung im Trizeps spürst. Wiederhole das dann mit dem anderen Arm.']::text[]),
  ('Triceps_Overhead_Extension_with_Rope', 'de', array['Befestige ein Seil an einem tiefen Kabelzug. Wähle ein passendes Gewicht, fass das Seil mit beiden Händen und dreh dem Kabelzug den Rücken zu.', 'Bring die Hände hinter den Kopf, die Ellbogen zeigen gerade nach oben. Zu Beginn sind die Ellbogen gebeugt. Für mehr Stabilität kannst du in Schrittstellung stehen und dich leicht von der Maschine weglehnen. Das ist deine Ausgangsposition.', 'Strecke die Ellbogen und heb die Hände über den Kopf, die Oberarme bleiben dabei an ihrem Platz.', 'Spann den Trizeps am höchsten Punkt fest an und senke das Gewicht langsam in die Ausgangsposition.']::text[]),
  ('Triceps_Pushdown', 'de', array['Befestige eine gerade oder gewinkelte Stange an einem hohen Kabelzug und fass sie schulterbreit im Obergriff, die Handflächen nach unten.', 'Steh aufrecht mit geradem Oberkörper, nur ganz leicht nach vorn geneigt. Bring die Oberarme dicht an den Körper, senkrecht zum Boden. Die Unterarme zeigen mit der Stange nach oben zur Rolle. Das ist deine Ausgangsposition.', 'Drück die Stange mit dem Trizeps nach unten, bis sie die Vorderseite der Oberschenkel berührt und die Arme ganz gestreckt senkrecht zum Boden stehen. Die Oberarme bleiben die ganze Zeit unbewegt am Oberkörper, nur die Unterarme bewegen sich. Atme dabei aus.', 'Halte die Kontraktion eine Sekunde und führe die Stange dann langsam nach oben zum Ausgangspunkt. Atme dabei ein.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Triceps_Pushdown_-_Rope_Attachment', 'de', array['Befestige ein Seil an einem hohen Kabelzug und fass es im Neutralgriff, die Handflächen zeigen zueinander.', 'Steh aufrecht mit geradem Oberkörper, nur ganz leicht nach vorn geneigt. Bring die Oberarme dicht an den Körper, senkrecht zum Boden. Die Unterarme zeigen mit dem Seil nach oben zur Rolle, die Handflächen zueinander. Das ist deine Ausgangsposition.', 'Drück das Seil mit dem Trizeps nach unten und führe dabei jedes Seilende neben den Oberschenkel. Am Ende sind die Arme ganz gestreckt und stehen senkrecht zum Boden. Die Oberarme bleiben die ganze Zeit unbewegt am Oberkörper, nur die Unterarme bewegen sich. Atme dabei aus.', 'Halte die Kontraktion eine Sekunde und führe das Seil dann langsam nach oben zum Ausgangspunkt. Atme dabei ein.', 'Wiederhole die Übung für die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Triceps_Pushdown_-_V-Bar_Attachment', 'de', array['Hänge einen V-Griff an die obere Rolle des Kabelzugs. Fasse ihn schulterbreit im Obergriff, die Handflächen zeigen nach unten.', 'Stell dich aufrecht hin, der Oberkörper ist gerade und nur ganz leicht nach vorn geneigt. Lege die Oberarme eng an den Körper, sodass sie senkrecht zum Boden stehen. Die Unterarme halten den Griff und zeigen nach oben zur Rolle, die Daumen liegen höher als die kleinen Finger. Das ist deine Ausgangsposition.', 'Drücke den Griff mit dem Trizeps nach unten, bis er die Vorderseite deiner Oberschenkel berührt und die Arme ganz gestreckt senkrecht zum Boden stehen. Die Oberarme bleiben die ganze Zeit ruhig am Oberkörper, nur die Unterarme bewegen sich. Atme dabei aus.', 'Halte die Spannung eine Sekunde und lass den V-Griff dann langsam wieder nach oben in die Ausgangsposition. Atme dabei ein.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Triceps_Stretch', 'de', array['Führe eine Hand hinter den Kopf, greife mit der anderen den Ellbogen und ziehe sanft daran. Halte 10 bis 20 Sekunden und wechsle dann die Seite.']::text[]),
  ('Tuck_Crunch', 'de', array['Lege dich auf den Boden oder auf eine Trainingsmatte und drücke den Rücken flach auf die Unterlage. Die Arme liegen neben dem Körper, die Handflächen zeigen nach unten.', 'Kreuze die Beine, indem du einen Knöchel um den anderen legst. Hebe sie langsam in die Luft, bis die Oberschenkel senkrecht zum Boden stehen und die Knie leicht gebeugt sind. Hinweis: Parallel zum Boden sind Knie und Zehen, nicht die Oberschenkel.', 'Nimm die Arme vom Boden und kreuze sie so, dass sie auf der Brust ruhen. Das ist die Ausgangsposition.', 'Der untere Rücken bleibt fest am Boden, während du den Oberkörper langsam anhebst. Denk daran, in diesem Teil der Übung auszuatmen.', 'Atme ein und senke den Oberkörper langsam wieder in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Two-Arm_Dumbbell_Preacher_Curl', 'de', array['Nimm in jede Hand eine Kurzhantel und lege die Oberarme oben auf das Polster einer Scottbank oder auf eine Schrägbank. Halte die Kurzhanteln in Schulterbreite. Das ist deine Ausgangsposition.', 'Atme ein und senke die Kurzhanteln langsam, bis die Oberarme gestreckt sind und der Bizeps ganz gedehnt ist.', 'Atme aus und beuge die Arme mit der Kraft des Bizeps, bis er ganz angespannt ist und die Kurzhanteln auf Schulterhöhe sind.', 'Spanne den Bizeps oben eine Sekunde lang kräftig an. Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Two-Arm_Kettlebell_Clean', 'de', array['Stelle zwei Kettlebells zwischen deine Füße. Für die Ausgangsposition schiebst du das Gesäß nach hinten und schaust geradeaus.', 'Bring die Kettlebells mit einem Clean an die Schultern: Strecke Beine und Hüfte, während du die Kettlebells zu den Schultern hebst, und drehe dabei die Handgelenke.', 'Senke die Kettlebells wieder in die Ausgangsposition und wiederhole.']::text[]),
  ('Two-Arm_Kettlebell_Jerk', 'de', array['Bring zwei Kettlebells mit einem Clean an die Schultern: Strecke Beine und Hüfte, während die Kettlebells zu den Schultern schwingen, und drehe dabei die Handgelenke, bis die Handflächen nach vorn zeigen. Geh ein paar Inches in die Kniebeuge und kehre die Bewegung schnell um, sodass du beide Kettlebells über den Kopf stößt. Gleich nach diesem ersten Stoß gehst du noch einmal in die Kniebeuge und bringst dich unter die Kettlebells. Sind die Arme durchgestreckt, richte dich ganz auf, um die Übung abzuschließen.']::text[]),
  ('Two-Arm_Kettlebell_Military_Press', 'de', array['Bring zwei Kettlebells mit einem Clean an die Schultern: Strecke Beine und Hüfte, während die Kettlebells zu den Schultern schwingen, und drehe dabei die Handgelenke, bis die Handflächen nach vorn zeigen.', 'Drücke die Kettlebells nach oben und außen. Sobald sie an deinem Kopf vorbei sind, lehne dich in die Gewichte hinein, sodass die Kettlebells hinter dem Kopf stehen. Spanne Latissimus, Gesäß und Bauch an, um stabiler zu stehen.']::text[]),
  ('Two-Arm_Kettlebell_Row', 'de', array['Stelle zwei Kettlebells vor deine Füße. Beuge die Knie leicht und schiebe das Gesäß so weit wie möglich nach hinten, während du dich in die Ausgangsposition vorbeugst.', 'Greife beide Kettlebells und ziehe sie zum Bauch: Beuge dabei die Ellbogen und zieh die Schulterblätter zurück. Der Rücken bleibt gerade. Senke die Gewichte und wiederhole.']::text[]),
  ('Underhand_Cable_Pulldowns', 'de', array['Setz dich an eine Latzugmaschine, an deren oberer Rolle eine breite Stange hängt. Stelle das Kniepolster auf deine Größe ein. Die Polster verhindern, dass der Widerstand an der Stange deinen Körper anhebt.', 'Fasse die Latzugstange im Untergriff (supinierter Griff), die Handflächen zeigen zu deinem Oberkörper. Die Hände liegen enger als schulterbreit.', 'Beide Arme sind vor dir gestreckt und halten die Stange in dieser Griffweite. Lehne den Oberkörper nun etwa 30 Grad zurück, geh dabei im unteren Rücken ins Hohlkreuz und streck die Brust heraus. Das ist deine Ausgangsposition.', 'Atme aus und ziehe die Stange nach unten, bis sie die obere Brust berührt. Führe dafür Schultern und Oberarme nach unten und hinten. Tipp: Konzentriere dich am Punkt der vollen Anspannung darauf, die Rückenmuskeln zusammenzuziehen, und halte die Ellbogen nah am Körper. Der Oberkörper bleibt ruhig, während die Stange zu dir kommt, nur die Arme bewegen sich. Die Unterarme sollen nichts weiter tun, als die Stange zu halten.', 'Bleib eine Sekunde in der Anspannung. Atme dann ein und lass die Stange langsam in die Ausgangsposition zurück, in der die Arme ganz gestreckt sind und der Latissimus voll gedehnt ist.', 'Wiederhole die Bewegung so oft, wie dein Plan vorgibt.']::text[]),
  ('Upper_Back-Leg_Grab', 'de', array['Beuge dich im Sitzen nach vorn und umfasse deine Oberschenkel mit beiden Armen von unten.', 'Lass die Knie zusammen und die Beine ausgestreckt, während du die Brust zu den Knien senkst. Du kannst auch den mittleren Rücken dehnen: Zieh dafür den Rücken von den Knien weg, während du sie umarmst.']::text[]),
  ('Upper_Back_Stretch', 'de', array['Verschränke die Finger, die Daumen zeigen nach unten. Schiebe die Hände nach vorn und mach dabei die Schultern rund.']::text[]),
  ('Upright_Barbell_Row', 'de', array['Fasse eine Langhantel im Obergriff, etwas enger als schulterbreit. Die Stange liegt oben auf deinen Oberschenkeln, die Arme sind gestreckt, die Ellbogen leicht gebeugt. Auch der Rücken ist gerade. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Stange mit den seitlichen Schultern an, die Ellbogen gehen dabei nach oben und zur Seite. Führe die Stange beim Heben nah am Körper. Hebe weiter, bis sie fast dein Kinn berührt. Tipp: Die Ellbogen führen die Bewegung an und sind immer höher als die Unterarme. Halte den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Stange langsam wieder in die Ausgangsposition. Atme in diesem Teil der Bewegung ein.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Upright_Cable_Row', 'de', array['Fasse eine gerade Stange, die an der unteren Rolle des Kabelzugs hängt, im pronierten Griff (Handflächen zu den Oberschenkeln), etwas enger als schulterbreit. Die Stange liegt oben auf deinen Oberschenkeln. Die Arme sind gestreckt, die Ellbogen leicht gebeugt, und der Rücken ist gerade. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Stange mit den seitlichen Schultern an. Führe sie auf dem Weg nach oben nah am Körper. Hebe weiter, bis sie fast dein Kinn berührt. Tipp: Die Ellbogen führen die Bewegung an. Während du die Stange hebst, sind sie immer höher als die Unterarme. Halte außerdem den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Stange langsam wieder in die Ausgangsposition. Atme in diesem Teil der Bewegung ein.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Upright_Row_-_With_Bands', 'de', array['Stell dich so auf ein Trainingsband, dass es bei lang hängenden Armen gerade zu spannen beginnt. Fasse die Griffe im pronierten Griff (Handflächen zu den Oberschenkeln), etwas enger als schulterbreit. Die Griffe liegen oben auf deinen Oberschenkeln. Die Arme sind gestreckt, die Ellbogen leicht gebeugt, und der Rücken ist gerade. Das ist deine Ausgangsposition.', 'Atme aus und hebe die Griffe mit den seitlichen Schultern an. Führe sie auf dem Weg nach oben nah am Körper. Hebe weiter, bis sie fast dein Kinn berühren. Tipp: Die Ellbogen führen die Bewegung an. Während du die Griffe hebst, sind die Ellbogen immer höher als die Unterarme. Halte außerdem den Oberkörper ruhig und mach oben eine Sekunde Pause.', 'Senke die Griffe langsam wieder in die Ausgangsposition. Atme in diesem Teil der Bewegung ein.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Upward_Stretch', 'de', array['Strecke beide Hände gerade über den Kopf, die Handflächen liegen aneinander.', 'Schiebe die Hände langsam nach oben und hinten und halte den Rücken dabei gerade.']::text[]),
  ('V-Bar_Pulldown', 'de', array['Setz dich an eine Latzugmaschine, an deren oberer Rolle ein V-Griff hängt.', 'Stelle das Kniepolster auf deine Größe ein. Die Polster verhindern, dass der Widerstand am Griff deinen Körper anhebt.', 'Fasse den V-Griff im neutralen Griff, die Handflächen zeigen zueinander. Streck die Brust heraus und lehne dich leicht zurück (etwa 30 Grad), damit der Latissimus besser arbeitet. Das ist deine Ausgangsposition.', 'Ziehe den Griff mit dem Latissimus nach unten und zieh dabei die Schulterblätter zusammen. Zieh weiter, bis deine Brust den V-Griff fast berührt. Atme bei dieser Bewegung aus. Tipp: Der Oberkörper bleibt während der ganzen Bewegung ruhig.', 'Halte die Anspannung eine Sekunde, atme dann ein und lass den Griff langsam in die Ausgangsposition zurück.', 'Mach die Zahl an Wiederholungen, die dein Plan vorgibt.']::text[]),
  ('V-Bar_Pullup', 'de', array['Lege die Mitte des V-Griffs über die Mitte der Klimmzugstange (vorausgesetzt, deine Klimmzugstation hat keine Griffe für den neutralen Griff). Die Griffe des V-Griffs zeigen nach unten, sodass du dich an ihnen unter die Klimmzugstange hängen kannst.', 'Liegt der V-Griff sicher, fasse ihn auf beiden Seiten und häng dich daran. Streck die Brust heraus und lehne dich leicht zurück, damit der Latissimus besser arbeitet. Das ist deine Ausgangsposition.', 'Ziehe den Oberkörper mit dem Latissimus nach oben und neige den Kopf dabei leicht zurück, damit du nicht gegen die Klimmzugstange stößt. Zieh weiter, bis deine Brust den V-Griff fast berührt. Atme bei dieser Bewegung aus.', 'Halte die Anspannung eine Sekunde, atme dann ein und senke den Körper langsam in die Ausgangsposition.', 'Mach die Zahl an Wiederholungen, die dein Plan vorgibt.']::text[]),
  ('Vertical_Swing', 'de', array['Halte eine Kurzhantel mit beiden Händen und lass sie an langen Armen zwischen den Beinen hängen. Der Rücken ist gerade, der Kopf oben.', 'Schwinge die Kurzhantel zwischen den Beinen nach hinten: Beuge dich dabei in der Hüfte und geh leicht in die Knie.', 'Kehre die Bewegung kraftvoll um. Strecke Hüfte, Knie und Sprunggelenke, um dich nach oben abzudrücken, und schwinge die Kurzhantel über den Kopf.', 'Fang die Landung mit den Beinen ab und zieh die Kurzhantel an den Oberkörper, bevor du die nächste Wiederholung beginnst.']::text[]),
  ('Walking_Treadmill', 'de', array['Steig auf das Laufband und wähle im Menü die gewünschte Option. Die meisten Laufbänder haben eine manuelle Einstellung, oder du lässt ein Programm laufen. Meist kannst du Alter und Gewicht eingeben, damit das Gerät schätzt, wie viele Kalorien du beim Training verbrauchst. Über die Steigung veränderst du die Intensität der Einheit.', 'Ein Laufband ist praktisch, trainiert Herz und Kreislauf und belastet die Gelenke meist weniger als Gehen im Freien. Geh in mäßigem bis zügigem Tempo, nicht gemütlich. Weil Gehen eine Aktivität mit geringerer Intensität ist, verbrennt es weniger Kalorien als manche andere Aktivität, bringt aber trotzdem viel. Eine Person mit 150 lb verbraucht etwa 175 Kalorien, wenn sie 30 Minuten mit 4 Meilen pro Stunde geht; beim Laufen mit doppeltem Tempo sind es 450 Kalorien. Achte beim Gehen auf eine gute Haltung und halte dich nur an den Griffen fest, wenn es nötig ist, etwa beim Absteigen oder wenn du deinen Puls misst.']::text[]),
  ('Weighted_Ball_Hyperextension', 'de', array['Lege dich bäuchlings auf einen Gymnastikball, sodass dein Oberkörper auf dem Ball aufliegt und parallel zum Boden ist. Drücke die Fußballen in den Boden, das hilft dir, das Gleichgewicht zu halten. Halte eine Hantelscheibe unter dem Kinn oder hinter dem Nacken. Das ist die Ausgangsposition.', 'Hebe den Oberkörper langsam an, indem du dich in der Taille und im unteren Rücken aufrichtest. Denk daran, bei dieser Bewegung auszuatmen.', 'Halte die Spannung im unteren Rücken eine Sekunde, atme dann ein und senke den Oberkörper wieder in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Programm vorgibt.']::text[]),
  ('Weighted_Ball_Side_Bend', 'de', array['Lege dich mit der linken Seite des Oberkörpers (Taille, Hüfte und Schulter) auf einen Gymnastikball.', 'Die Füße stehen auf dem Boden, die Beine sind gekreuzt und hängen vom Ball herab. Halte mit der rechten Hand eine Hantelscheibe direkt an die rechte Seite deines Kopfes. Tipp: Achte darauf, dass die glatte Seite der Scheibe am Kopf anliegt.', 'Lege den linken Arm quer über den Oberkörper, die Handfläche liegt auf den schrägen Bauchmuskeln. Linker Unterarm und Oberarm bilden einen rechten Winkel. Das ist die Ausgangsposition.', 'Atme aus und hebe die Seite des Oberkörpers an, indem du dich in der Taille seitlich beugst.', 'Halte die Spannung eine Sekunde, atme dann ein und senke dich langsam in die Ausgangsposition zurück.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.', 'Wechsle die Seite und wiederhole die Übung.']::text[]),
  ('Weighted_Bench_Dip', 'de', array['Für diese Übung brauchst du zwei Bänke: eine hinter deinem Rücken und eine vor dir. Beide stehen quer zu deinem Körper. Stütz dich auf die Kante der hinteren Bank, die Hände nah am Körper und schulterbreit auseinander. Die Arme sind ganz gestreckt.', 'Die Beine streckst du nach vorn und legst sie auf die andere Bank. Sie sind parallel zum Boden, dein Oberkörper steht senkrecht dazu. Lass dir von deinem Partner die Kurzhantel auf den Schoß legen. Hinweis: Am besten machst du diese Übung mit einem Partner, denn ohne Hilfe ist es schwierig, das Gewicht auf den Schoß zu bekommen, und du kannst dich dabei verletzen. Das ist deine Ausgangsposition.', 'Atme ein und senke den Körper langsam, indem du die Ellbogen beugst, bis der Winkel zwischen Oberarm und Unterarm etwas kleiner als 90 Grad ist. Tipp: Halte die Ellbogen während der ganzen Bewegung so eng wie möglich. Die Unterarme zeigen immer nach unten.', 'Atme aus und drücke den Oberkörper mit dem Trizeps wieder nach oben in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Weighted_Crunches', 'de', array['Lege dich flach auf den Rücken. Die Füße stehen flach auf dem Boden oder liegen auf einer Bank, die Knie sind im 90-Grad-Winkel gebeugt.', 'Halte ein Gewicht an die Brust oder mit gestreckten Armen über dem Oberkörper. Das ist deine Ausgangsposition.', 'Atme nun aus und rolle die Schultern langsam vom Boden auf. Sie heben sich etwa 4 Inches vom Boden, der untere Rücken bleibt liegen.', 'Spanne am höchsten Punkt die Bauchmuskeln an und halte kurz inne.', 'Atme dann ein und senke dich langsam in die Ausgangsposition zurück.']::text[]),
  ('Weighted_Jump_Squat', 'de', array['Lege eine leicht beladene Langhantel hinten auf deine Schultern. Du kannst für diese Übung auch eine Gewichtsweste, einen Sandsack oder einen anderen Widerstand nehmen.', 'Das Gewicht soll so leicht sein, dass es dich nicht merklich bremst. Die Füße stehen etwas weiter als schulterbreit, Kopf und Brust sind oben. Das ist deine Ausgangsposition.', 'Hol mit einer Gegenbewegung Schwung: Geh ein Stück in die Kniebeuge, kehre sofort um und spring explosiv vom Boden ab, indem du Hüfte, Knie und Sprunggelenke streckst. Behalte während des ganzen Sprungs eine gute Haltung.', 'Fang den Aufprall bei der Landung mit den Beinen ab.']::text[]),
  ('Weighted_Pull_Ups', 'de', array['Hänge ein Gewicht an einen Dip-Gürtel und schnalle ihn um deine Taille. Fasse die Klimmzugstange so, dass die Handflächen nach vorn zeigen. Für einen mittleren Griff liegen die Hände schulterbreit auseinander. Beide Arme sind vor dir gestreckt und halten die Stange in der gewählten Griffweite.', 'Lehne den Oberkörper etwa 30 Grad zurück, geh im unteren Rücken ins Hohlkreuz und streck die Brust heraus. Das ist deine Ausgangsposition.', 'Atme nun aus und ziehe den Oberkörper nach oben, bis dein Kopf über den Händen ist. Konzentriere dich darauf, die Schulterblätter nach hinten und unten zu ziehen, wenn du oben in der Anspannung ankommst.', 'Bleib einen kurzen Moment oben in der Anspannung, atme dann ein und senke den Oberkörper langsam in die Ausgangsposition: Arme gestreckt, Latissimus voll gedehnt.']::text[]),
  ('Weighted_Sissy_Squat', 'de', array['Stell dich aufrecht hin, die Füße schulterbreit, die Zehen angehoben. Halte dich mit einer Hand am Holm eines Kniebeugenständers fest und drücke mit dem anderen Arm eine Hantelscheibe oben an die Brust. Das ist deine Ausgangsposition.', 'Während du dich mit dem einen Arm festhältst, beugst du die Knie und senkst den Oberkörper langsam zum Boden, indem du Becken und Knie nach vorn schiebst. Atme beim Absenken ein und stoppe, wenn Ober- und Unterschenkel fast einen 90-Grad-Winkel bilden. Halte die Dehnung eine Sekunde.', 'Nach dieser einen Sekunde bringst du den Oberkörper mit der Oberschenkelmuskulatur wieder in die Ausgangsposition. Atme auf dem Weg nach oben aus.', 'Wiederhole so oft, wie dein Plan vorsieht.']::text[]),
  ('Weighted_Sit-Ups_-_With_Bands', 'de', array['Befestige zuerst die Bänder um den Fuß der Negativbank. Lege die Griffe zur Innenseite der Bank, damit du im Liegen beide erreichst.', 'Schiebe die Beine in die Halterung der Negativbank, bis sie fest sitzen. Greife nun mit beiden Händen nach den Bändern und fasse die Griffe im pronierten Griff (Handflächen nach vorn). Bring sie in die Nähe des Schlüsselbeins und drehe die Handgelenke in den neutralen Griff (Handflächen zum Oberkörper). Hinweis: Die Arme bleiben während der ganzen Übung unbewegt. Das ist die Ausgangsposition.', 'Atme aus und richte den Oberkörper auf, bis er senkrecht zum Boden steht. Halte die Spannung eine Sekunde, atme dann ein und senke den Oberkörper wieder in die Ausgangsposition.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Weighted_Squat', 'de', array['Stelle zuerst zwei Flachbänke schulterbreit auseinander. Steig darauf und lege dir den Gewichtsgürtel um die Taille, mit so viel Gewicht, wie für dich angenehm ist. Achte darauf, dass die Zehen nach außen zeigen.', 'Stehst du aufrecht und das Gewicht hängt zwischen deinen Beinen, lass die Arme ganz gestreckt seitlich am Körper. Das ist die Ausgangsposition.', 'Beuge nun die Knie und bleib dabei aufrecht, den Kopf oben. Geh tiefer, bis der Winkel zwischen Oberschenkeln und Waden etwas kleiner als 90 Grad ist (dann liegen die Oberschenkel tiefer als parallel zum Boden). Atme in diesem Teil der Bewegung ein. Tipp: Bei richtiger Ausführung bildet die Vorderseite der Knie mit den Zehen eine gedachte gerade Linie, die senkrecht zur Vorderseite steht. Ragen die Knie über diese Linie hinaus (über die Zehen), wird das Knie unnötig belastet und die Übung ist falsch ausgeführt.', 'Komm wieder hoch, indem du dich vor allem mit den Fußballen von der Fläche der Flachbank abdrückst, die Beine streckst und in die Ausgangsposition zurückkehrst. Atme in diesem Teil der Übung aus.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Wide-Grip_Barbell_Bench_Press', 'de', array['Lege dich auf eine Flachbank, die Füße stehen fest auf dem Boden. Fasse die Stange weit im pronierten Griff (Handflächen nach vorn), jede Hand etwa 3 Inches außerhalb der Schulterbreite. Hebe sie aus der Ablage und halte sie mit durchgestreckten Armen gerade über dir. Die Stange steht quer zum Oberkörper und senkrecht über dem Boden. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis du sie auf der mittleren Brust spürst.', 'Mach eine Sekunde Pause, atme dann aus und drücke die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Strecke die Arme durch, spanne die Brust in dieser Position eine Sekunde lang an und beginne dann wieder langsam abzusenken. Tipp: Das Absenken soll mindestens doppelt so lange dauern wie das Hochdrücken.', 'Wiederhole die Bewegung so oft, wie dein Plan vorgibt.']::text[]),
  ('Wide-Grip_Decline_Barbell_Bench_Press', 'de', array['Lege dich auf eine Negativbank, die Füße sind vorn an der Bank sicher eingehakt. Fasse die Stange weit im pronierten Griff (Handflächen nach vorn), jede Hand etwa 3 Inches außerhalb der Schulterbreite. Hebe sie aus der Ablage und halte sie mit durchgestreckten Armen gerade über dir. Die Stange steht quer zum Oberkörper und senkrecht über dem Boden. Das ist deine Ausgangsposition.', 'Atme ein und senke die Stange langsam, bis du sie auf der unteren Brust spürst.', 'Mach eine Sekunde Pause, atme dann aus und drücke die Stange mit der Brustmuskulatur zurück in die Ausgangsposition. Strecke die Arme durch, spanne die Brust in dieser Position eine Sekunde lang an und beginne dann wieder langsam abzusenken. Tipp: Das Absenken soll mindestens doppelt so lange dauern wie das Hochdrücken.', 'Wiederhole die Bewegung so oft, wie dein Plan vorgibt.']::text[]),
  ('Wide-Grip_Decline_Barbell_Pullover', 'de', array['Lege dich auf eine Negativbank, beide Beine sind sicher eingehakt. Greife hinter dem Kopf nach der Langhantel und fasse sie im pronierten Griff (Handflächen nach außen). Achte darauf, bei dieser Übung weiter als schulterbreit zu greifen. Hebe die Langhantel langsam mit den Armen vom Boden.', 'In der richtigen Position sind deine Arme ganz gestreckt und stehen senkrecht zum Boden. Das ist die Ausgangsposition.', 'Führe die Langhantel nun in einem Halbkreis wieder nach hinten unten, als wolltest du sie auf dem Boden ablegen, stoppe aber, wenn die Arme parallel zum Boden sind. Tipp: Lass die Arme die ganze Zeit ganz gestreckt. Die Bewegung kommt nur aus dem Schultergelenk. Atme in diesem Teil der Bewegung ein.', 'Atme aus und bring die Langhantel nach oben, bis du wieder in der Ausgangsposition bist. Denk daran, die Langhantel jederzeit voll unter Kontrolle zu halten.', 'Wiederhole die Bewegung so oft, wie dein Trainingsprogramm vorgibt.', 'Bist du mit dem Satz fertig, senke die Langhantel langsam ab, bis sie auf Höhe deines Kopfes ist, und lass sie los.']::text[]),
  ('Wide-Grip_Lat_Pulldown', 'de', array['Setz dich an eine Latzugmaschine, an deren oberer Rolle eine breite Stange hängt. Stelle unbedingt das Kniepolster auf deine Größe ein. Die Polster verhindern, dass der Widerstand an der Stange deinen Körper anhebt.', 'Fasse die Stange in der vorgegebenen Griffweite, die Handflächen zeigen nach vorn. Hinweis zu den Griffen: Beim weiten Griff liegen die Hände weiter als schulterbreit auseinander. Beim mittleren Griff entspricht der Abstand deiner Schulterbreite, beim engen Griff ist er kleiner als die Schulterbreite.', 'Beide Arme sind vor dir gestreckt und halten die Stange in der gewählten Griffweite. Lehne den Oberkörper nun etwa 30 Grad zurück, geh dabei im unteren Rücken ins Hohlkreuz und streck die Brust heraus. Das ist deine Ausgangsposition.', 'Atme aus und bring die Stange nach unten, bis sie die obere Brust berührt. Führe dafür Schultern und Oberarme nach unten und hinten. Tipp: Konzentriere dich am Punkt der vollen Anspannung darauf, die Rückenmuskeln zusammenzuziehen. Der Oberkörper bleibt ruhig, nur die Arme bewegen sich. Die Unterarme sollen nichts weiter tun, als die Stange zu halten; versuche also nicht, die Stange mit den Unterarmen herunterzuziehen.', 'Zieh in der Anspannung eine Sekunde lang die Schulterblätter zusammen und lass die Stange dann langsam in die Ausgangsposition zurück, in der die Arme ganz gestreckt sind und der Latissimus voll gedehnt ist. Atme in diesem Teil der Bewegung ein.', 'Wiederhole die Bewegung so oft, wie dein Plan vorgibt.']::text[]),
  ('Wide-Grip_Pulldown_Behind_The_Neck', 'de', array['Hänge eine breite Stange an die obere Rolle des Latzugs und setz dich hin. Stelle das Kniepolster auf deine Größe ein. Das Polster verhindert, dass dich das Gewicht an der Stange vom Sitz hebt.', 'Fasse die Stange in der vorgegebenen Griffweite, die Handflächen zeigen nach vorn. Hinweis: Beim weiten Griff sind die Hände weiter auseinander als die Schultern. Beim mittleren Griff sind sie schulterbreit, beim engen Griff enger als schulterbreit.', 'Halte die Stange mit gestreckten Armen in der gewählten Griffweite und neige Oberkörper und Kopf nach vorn. Stell dir eine Linie von der Mitte der Stange bis zu deinem Nacken vor. Das ist deine Ausgangsposition.', 'Atme aus und zieh die Stange herunter, bis sie den Nacken berührt. Führe dazu Schultern und Oberarme nach unten und hinten. Tipp: Spanne die Rückenmuskeln bewusst an, sobald die Stange ganz unten ist. Der Oberkörper bleibt ruhig, nur die Arme bewegen sich. Die Unterarme halten die Stange und sonst nichts. Zieh also nicht mit den Unterarmen.', 'Bleib eine Sekunde unten und drücke die Schulterblätter zusammen. Lass die Stange dann langsam nach oben und atme dabei ein, bis die Arme ganz gestreckt sind und der Latissimus voll gedehnt ist. Damit bist du wieder in der Ausgangsposition.', 'Wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Wide-Grip_Rear_Pull-Up', 'de', array['Fasse die Klimmzugstange im weiten Griff, die Handflächen zeigen nach vorn.', 'Häng dich mit gestreckten Armen an die Stange und bring Oberkörper und Kopf nach vorn, sodass du dir eine Linie von der Stange bis zu deinem Nacken vorstellen kannst. Das ist deine Ausgangsposition.', 'Zieh dich hoch, bis die Stange knapp hinter deinem Nacken ist. Führe dazu Schultern und Oberarme nach unten und hinten und neige den Kopf leicht nach vorn. Atme bei diesem Teil aus. Tipp: Spanne die Rückenmuskeln bewusst an, sobald du ganz oben bist. Der Oberkörper bleibt auf seinem Weg nach oben starr, nur die Arme arbeiten. Die Unterarme halten die Stange und sonst nichts.', 'Bleib eine Sekunde oben. Atme dann ein und lass dich langsam ab, bis die Arme ganz gestreckt sind und der Latissimus voll gedehnt ist. Damit bist du wieder in der Ausgangsposition.', 'Wiederhole die Bewegung für die vorgegebene Zahl an Wiederholungen.']::text[]),
  ('Wide-Grip_Standing_Barbell_Curl', 'de', array['Stell dich mit aufrechtem Oberkörper hin und fasse die Langhantel weit außen am Griffbereich. Die Handflächen zeigen nach vorn. Die Ellbogen bleiben nah am Körper. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Arme: Spanne den Bizeps an und führe die Stange nach vorn oben. Tipp: Nur die Unterarme bewegen sich.', 'Beuge weiter, bis die Stange auf Schulterhöhe ist und der Bizeps voll angespannt ist. Halte diese Position eine Sekunde und spanne den Bizeps kräftig an.', 'Atme ein und lass die Stange langsam in die Ausgangsposition sinken.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Wide_Stance_Barbell_Squat', 'de', array['Zur Sicherheit machst du diese Übung am besten in einem Kniebeugenständer. Lege die Stange zuerst auf die Höhe der Ablage, die am besten zu deiner Größe passt. Stimmt die Höhe und ist die Stange beladen, tritt unter sie und lege sie quer auf die Rückseite deiner Schultern, knapp unterhalb des Nackens.', 'Fasse die Stange mit beiden Händen links und rechts und hebe sie aus der Ablage: Drücke zuerst mit den Beinen und richte gleichzeitig den Oberkörper auf.', 'Tritt von der Ablage weg und stell die Füße weiter als schulterbreit auf, die Zehen zeigen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und lass den Rücken gerade. Das ist deine Ausgangsposition.', 'Senke die Stange langsam, indem du die Knie beugst und dabei aufrecht bleibst, den Kopf oben. Geh tiefer, bis der Winkel zwischen Oberschenkeln und Waden etwas kleiner als 90 Grad ist (dann liegen die Oberschenkel tiefer als parallel zum Boden). Atme in diesem Teil der Bewegung ein. Tipp: Bei richtiger Ausführung bildet die Vorderseite der Knie mit den Zehen eine gedachte gerade Linie, die senkrecht zur Vorderseite steht. Ragen die Knie über diese Linie hinaus (über die Zehen), wird das Knie unnötig belastet und die Übung ist falsch ausgeführt.', 'Atme aus und bring die Stange wieder nach oben: Drücke dich mit den Fersen vom Boden ab, strecke die Beine und kehre in die Ausgangsposition zurück.', 'Mach so viele Wiederholungen, wie dein Plan vorsieht.']::text[]),
  ('Wide_Stance_Stiff_Legs', 'de', array['Am Anfang liegt eine beladene Langhantel auf dem Boden. Stell dich breit hin und beuge dich in der Hüfte vor, um die Stange zu greifen. Die Hüfte ist so weit hinten wie möglich, die Beine sind fast gestreckt. Der Rücken bleibt gerade, Kopf und Brust sind oben. Das ist deine Ausgangsposition.', 'Leite die Bewegung aus der Hüfte ein: Schiebe sie nach vorn und lass die Arme gerade hängen. Mach weiter, bis du ganz aufrecht stehst, und bring das Gewicht dann langsam in die Ausgangsposition zurück. Bei den folgenden Wiederholungen muss das Gewicht den Boden nicht berühren.']::text[]),
  ('Wind_Sprints', 'de', array['Häng dich im Obergriff an eine Klimmzugstange. Arme und Beine sind gestreckt. Das ist deine Ausgangsposition.', 'Zieh zuerst ein Knie schnell so hoch, wie es geht. Schwinge dabei weder mit dem Körper noch mit den Beinen.', 'Führe das Bein sofort wieder in die Ausgangsposition. Zieh gleichzeitig das andere Knie so hoch wie möglich.', 'Wechsle die Beine weiter ab, bis der Satz zu Ende ist.']::text[]),
  ('Windmills', 'de', array['Leg dich auf den Rücken, die Beine gerade und die Arme zu beiden Seiten ausgestreckt. Das ist deine Ausgangsposition.', 'Heb ein Bein und führe es schnell über den Körper zur anderen Seite. Versuche, mit dem Fuß den Boden nahe der gegenüberliegenden Hand zu berühren.', 'Geh zurück in die Ausgangsposition und mach dasselbe mit dem anderen Bein. Wechsle die Seiten für 10-20 Wiederholungen ab.']::text[]),
  ('Worlds_Greatest_Stretch', 'de', array['Diese Dehnung hat drei Teile. Mach zuerst einen Ausfallschritt nach vorn: Der vordere Fuß steht ganz auf dem Boden, der hintere auf den Zehen. Beuge beide Knie und geh tief, bis das hintere Knie den Boden fast berührt. Der Oberkörper bleibt aufrecht. Halte diese Position 10-20 Sekunden.', 'Bring jetzt den Arm auf der Seite des vorderen Beins zum Boden, der Ellbogen liegt neben dem Fuß. Setz die andere Hand parallel zum vorderen Bein auf den Boden. Sie stützt dich bei diesem Teil der Dehnung.', 'Setz nach 10-20 Sekunden die Hände links und rechts neben den vorderen Fuß. Heb die Zehen dieses Fußes vom Boden und streck das Bein. Dafür musst du das hintere Bein vielleicht etwas umsetzen. Halte 10-20 Sekunden und wiederhole dann den ganzen Ablauf auf der anderen Seite.']::text[]),
  ('Wrist_Circles', 'de', array['Stell dich aufrecht hin, die Füße schulterbreit auseinander. Heb die Arme seitlich an, bis sie gestreckt sind, auf Schulterhöhe liegen und parallel zum Boden verlaufen. Tipp: Oberkörper und Arme bilden zusammen ein "T". Die Handflächen zeigen nach unten. Das ist deine Ausgangsposition.', 'Halte den ganzen Körper ruhig und bewege nur die Handgelenke: Lass beide nach vorn kreisen. Tipp: Stell dir vor, du malst Kreise und deine Hände sind der Pinsel. Atme während der Übung normal weiter.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Wrist_Roller', 'de', array['Stell dich aufrecht hin und fasse einen Handgelenkroller im Obergriff, die Handflächen zeigen nach unten. Die Füße stehen schulterbreit auseinander.', 'Heb beide Arme langsam nach vorn, bis sie gestreckt und parallel zum Boden sind. Hinweis: Achte darauf, dass das Seil nicht um die Rolle gewickelt ist. Bis auf die Unterarme bleibt der ganze Körper ruhig. Das ist deine Ausgangsposition.', 'Dreh die Handgelenke abwechselnd nach oben. So wickelt sich das Seil um die Rolle, und das Gewicht steigt bis zur Stange.', 'Ist das Gewicht an der Stange angekommen, dreh die Handgelenke nach unten und lass das Gewicht langsam ab, bis es wieder in der Ausgangsposition ist.', 'Mach so viele Wiederholungen, wie dein Plan vorgibt.']::text[]),
  ('Wrist_Rotations_with_Straight_Bar', 'de', array['Fasse eine Langhantel mit beiden Händen, die Handflächen zeigen nach unten, die Hände sind etwa schulterbreit auseinander. Das ist deine Ausgangsposition.', 'Streck abwechselnd das eine und das andere Handgelenk, als würdest du eine Zeitung aufrollen. Wechsle so lange hin und her, bis nichts mehr geht.', 'Dreh die Bewegung um: Beuge die Handgelenke und rolle in die Gegenrichtung. Wechsle auch hier die Hände ab, bis nichts mehr geht.']::text[]),
  ('Yoke_Walk', 'de', array['Für diese Übung nimmt man meist ein Yoke-Gestell, manchmal aber auch einen Kühlschrank oder einen anderen schweren Gegenstand.', 'Leg dir das Gestell zuerst quer über den hinteren Teil der Schultern. Schau nach vorn, geh ins Hohlkreuz und drück dich über die Fersen hoch, um das Yoke anzuheben.', 'Geh so schnell wie möglich los, mit kurzen, schnellen Schritten. Du kannst die seitlichen Pfosten des Yokes fassen, damit es ruhig bleibt und nicht verrutscht. Leg die vorgegebene Strecke, meist 75-100 Fuß, so schnell zurück, wie du kannst.']::text[]),
  ('Zercher_Squats', 'de', array['Mach diese Übung zur Sicherheit am besten in einem Kniebeugenständer. Leg die Stange zuerst auf die Höhe, die am besten zu deiner Größe passt: irgendwo oberhalb der Taille und unterhalb der Brust. Stimmt die Höhe und ist die Stange beladen, verschränke die Hände und nimm die Stange in die Armbeuge, zwischen Unterarm und Oberarm.', 'Heb die Stange an, sodass sie auf deinen Unterarmen liegt. Hältst du sie richtig, sieht es aus, als hättest du die Arme verschränkt und eine Stange läge quer darüber.', 'Tritt vom Ständer weg und stell die Füße schulterbreit in einen mittleren Stand, die Zehen zeigen leicht nach außen. Halte den Kopf immer oben, denn der Blick nach unten bringt dich aus dem Gleichgewicht, und halte den Rücken gerade. Das ist deine Ausgangsposition. Hinweis: Der hier beschriebene mittlere Stand trainiert die Beine insgesamt, du kannst aber jeden der drei Stände wählen.', 'Beuge die Knie und senke so die Stange. Bleib dabei aufrecht, den Kopf oben. Geh so tief, bis der Winkel zwischen Oberschenkel und Wade etwas kleiner als 90 Grad ist. An diesem Punkt liegen die Oberschenkel tiefer als parallel zum Boden. Atme bei diesem Teil ein. Tipp: Bei richtiger Ausführung liegen die Vorderseite der Knie und die Zehen auf einer gedachten geraden Linie, die senkrecht zur Vorderseite steht. Ragen die Knie über diese Linie hinaus, also über die Zehen, belastest du das Knie unnötig und führst die Übung falsch aus.', 'Atme aus und bring die Stange wieder nach oben: Drück dich vor allem mit den Fußballen vom Boden ab und streck die Beine, bis du wieder in der Ausgangsposition bist.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Zottman_Curl', 'de', array['Stell dich mit aufrechtem Oberkörper hin, in jeder Hand eine Kurzhantel, die Arme hängen gestreckt herab. Die Ellbogen bleiben nah am Körper.', 'Achte darauf, dass die Handflächen zueinander zeigen. Das ist deine Ausgangsposition.', 'Halte die Oberarme ruhig, atme aus und beuge die Arme, indem du den Bizeps anspannst. Nur die Unterarme bewegen sich. Dreh dabei die Handgelenke, bis du im supinierten Griff bist, die Handflächen nach oben. Beuge weiter, bis die Kurzhanteln auf Schulterhöhe sind und der Bizeps voll angespannt ist.', 'Halte diese Position eine Sekunde und spanne den Bizeps fest an.', 'Dreh oben die Handgelenke, bis du im pronierten Griff bist, die Handflächen nach unten. Der Daumen liegt dabei höher als der kleine Finger.', 'Lass die Kurzhanteln in diesem pronierten Griff langsam sinken.', 'Kommen die Kurzhanteln in die Nähe der Oberschenkel, dreh die Handgelenke zurück in den neutralen Griff, die Handflächen zum Körper.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('Zottman_Preacher_Curl', 'de', array['Nimm in jede Hand eine Kurzhantel und leg die Oberarme auf das Polster der Scottbank oder einer Schrägbank. Die Ellbogen sind gebeugt, die Kurzhanteln auf Schulterhöhe. Die Handflächen zeigen nach unten. Das ist deine Ausgangsposition.', 'Atme ein und lass die Kurzhanteln langsam sinken, die Handflächen weiter nach unten, bis die Arme gestreckt sind und der Bizeps voll gedehnt ist.', 'Dreh am tiefsten Punkt der Bewegung die Handgelenke, sodass die Handflächen nach oben zeigen.', 'Atme aus und beuge die Arme mit der Kraft des Bizeps, bis er voll angespannt ist und die Kurzhanteln auf Schulterhöhe sind. Denk auch hier daran: Für die volle Anspannung muss der kleine Finger höher liegen als der Daumen.', 'Spanne den Bizeps oben eine Sekunde lang kräftig an und dreh dann die Handgelenke, bis die Handflächen wieder nach unten zeigen.', 'Mach die empfohlene Zahl an Wiederholungen.']::text[]),
  ('3_4_Sit-Up', 'tr', array['Dizlerin bükülü olacak şekilde sırtüstü yere uzan ve ayaklarını bir yere sabitle.', 'Ellerini başının arkasına ya da yanlarına koy. Sırtın yerdeyken başlangıç pozisyonundasın.', 'Kalçandan ve omurgandan bükülerek gövdeni dizlerine doğru kaldır.', 'En üstte gövden yere dik olsun. Sonra geri in, ama yolun yalnızca dörtte üçü kadar.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('90_90_Hamstring', 'tr', array['Sırtüstü uzan ve bir bacağını yerde dümdüz uzat.', 'Diğer bacağını, kalçan ve dizin 90 derece bükülene kadar yukarı çek. Gerekirse bacağını ellerinle destekle. Bu, başlangıç pozisyonun.', 'O bacağı havaya doğru dümdüz uzat ve üstte kısa bir an bekle. Sonra bacağını başlangıç pozisyonuna geri bük.', '10-20 tekrar yap, ardından bacak değiştir.']::text[]),
  ('Ab_Crunch_Machine', 'tr', array['Hafif bir direnç seç ve makineye otur. Ayaklarını pedlerin altına yerleştir, üstteki tutamakları kavra. Trisepslerini kol pedlerine yasla, dirseklerin 90 derece bükülü olsun. Bu, başlangıç pozisyonun.', 'Gövdeni öne doğru kıvırırken aynı anda bacaklarını yukarı kaldır. Bunu yaparken nefes ver. İpucu: Yavaş ve kontrollü hareket et. Ağırlığı karın kaslarınla hareket ettirmeye odaklan, bacaklarını ve ayaklarını gevşek bırak.', 'Bir saniye bekle, sonra nefes alarak yavaşça başlangıç pozisyonuna dön.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('Ab_Roller', 'tr', array['Karın tekerleğini iki elinle tut ve yere diz çök.', 'Tekerleği önünde yere koy; dizler üzerinde şınav pozisyonundaki gibi ellerin ve dizlerin üzerinde dur. Bu, başlangıç pozisyonun.', 'Tekerleği yavaşça dümdüz ileri sür ve vücudun düz bir çizgi olana kadar uzan. İpucu: Vücudun yere değmeden inebildiğin kadar in. Hareketin bu kısmında nefes al.', 'Uzanmış pozisyonda kısa bir an bekle, sonra nefes vererek kendini başlangıç pozisyonuna geri çek. İpucu: Yavaş git ve karnını hep sıkı tut.']::text[]),
  ('Adductor', 'tr', array['Yüzüstü uzan ve bir bacağını foam roller''ın üzerine koy.', 'Bacağını, iç uyluğun foam roller''a değecek şekilde çevir. Dayanabildiğin kadar ağırlığını roller''a ver.', 'İç uyluk kaslarını gevşetmeye çalışarak kalçan ile dizin arasında ileri geri yuvarlan. Gergin noktalarda 10-30 saniye bekle. Sonra diğer bacağınla tekrarla.']::text[]),
  ('Adductor_Groin', 'tr', array['Sırtüstü uzan ve ayaklarını tavana doğru kaldır.', 'Partnerin ayaklarını ya da ayak bileklerini tutsun. Bacaklarını açabildiğin kadar iki yana aç. Bu, başlangıç pozisyonun.', 'Partnerin engel olurken 10 saniye ya da daha uzun süre bacaklarını birbirine doğru sıkmaya çalış.', 'Şimdi bacak kaslarını gevşet; partnerin ayaklarını senin için rahat olduğu kadar iki yana itsin. Aşırı esnemeyi ya da sakatlanmayı önlemek için esneme yeterli olduğunda partnerine mutlaka söyle.']::text[]),
  ('Advanced_Kettlebell_Windmill', 'tr', array['Bir kettlebell''i tek kolla omzuna al ve başının üstüne it.', 'Kolunu hep kilitli tut ve kalçanı, yukarıda kilitli duran kettlebell''in olduğu tarafa doğru dışarı it. Boştaki kolunu sırtının arkasında tut, ayaklarını kettlebell''i tutan koldan kırk beş derece dışa çevir.', 'İnebildiğin kadar aşağı in.', 'Bir saniye bekle ve aynı yoldan başlangıç pozisyonuna dön.']::text[]),
  ('Air_Bike', 'tr', array['Yere sırtüstü uzan ve belini yere bastır. Ellerini başının iki yanına koy, ama hareket sırasında boynunu zorlamamaya dikkat et. Şimdi omuzlarını mekik pozisyonuna kaldır.', 'Dizlerini, uylukların yere dik ve alt bacakların yere paralel olana kadar yukarı çek. Bu, başlangıç pozisyonun.', 'Şimdi yavaşça bisiklet çevirir gibi hareket et: sağ bacağını ileri uzatırken aynı anda sol dizini kendine çek. Nefes verirken yana doğru kıvrıl ve sağ dirseğini sol dizine yaklaştır.', 'Nefes alarak ilk pozisyona dön.', 'Bacaklarını çevirmeye devam ederken karşı tarafa kıvrıl, sol dirseğini sağ dizine yaklaştır ve nefes ver.', 'Her taraf için önerilen tekrarlar bitene kadar böyle sırayla devam et.']::text[]),
  ('All_Fours_Quad_Stretch', 'tr', array['Ellerinin ve dizlerinin üzerinde dur, sonra bir bacağını yerden kaldır ve ayağını elinle tut.', 'Ayağını ya da ayak bileğini elinle tutarken dizini tamamen bükülü bırak; böylece ön bacak kasların ve kalça bükücülerin esner.', 'Kalçanı açmaya ve yere doğru itmeye odaklan. 10-20 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Alternate_Hammer_Curl', 'tr', array['Gövden dik şekilde ayakta dur, iki elinde birer dambıl olsun ve kolların aşağı doğru uzansın. Dirseklerin gövdene yakın dursun.', 'Avuç içlerin gövdene baksın. Bu, başlangıç pozisyonun.', 'Üst kolunu sabit tut, nefes verirken bisepsini kasarak sağ dambılı öne doğru kaldır. Bisepsin tamamen kasılana ve dambıl omuz hizasına gelene kadar devam et. Bu noktada bisepsini sıkarak bir saniye bekle. İpucu: Yalnızca ön kol hareket etmeli.', 'Nefes alırken dambılı yavaşça başlangıç pozisyonuna indir.', 'Aynı hareketi sol elinle yap. İkisi birlikte bir tekrar eder.', 'Önerilen tekrar sayısı bitene kadar böyle sırayla devam et.']::text[]),
  ('Alternate_Heel_Touchers', 'tr', array['Yere sırtüstü uzan; dizlerin bükülü, ayakların yerde ve aralarında yaklaşık 18-24 inç olsun. Kollarını gövdenin yanında uzat. Bu, başlangıç pozisyonun.', 'Nefes verirken gövdeni yaklaşık 3-4 inç öne ve yukarı, sağ tarafa doğru kıvır ve sağ topuğuna dokun. Kasılmayı bir saniye tut.', 'Şimdi nefes alarak yavaşça başlangıç pozisyonuna dön.', 'Nefes verirken gövdeni yaklaşık 3-4 inç öne ve yukarı, sol tarafa doğru kıvır ve sol topuğuna dokun; kasılmayı bir saniye tut. Sonra nefes alarak başlangıç pozisyonuna dön. İki topuğa da dokunduğunda bu 1 tekrar sayılır.', 'Programdaki bütün tekrarlar bitene kadar böyle taraf değiştirerek devam et.']::text[]),
  ('Alternate_Incline_Dumbbell_Curl', 'tr', array['Eğimli bir sehpaya otur, iki elinde birer dambıl olsun ve kolların aşağı doğru uzansın. İpucu: Dirseklerini gövdene yakın tut. Bu, başlangıç pozisyonun.', 'Üst kolunu sabit tut, nefes verirken bisepsini kasarak sağ dambılı öne doğru kaldır. Kaldırırken elini, avuç için yukarı bakacak şekilde çevir. Bisepsin tamamen kasılana ve dambıl omuz hizasına gelene kadar devam et. Bu noktada bisepsini sıkarak bir saniye bekle. İpucu: Yalnızca ön kol hareket etmeli.', 'Nefes alırken dambılı yavaşça başlangıç pozisyonuna indir.', 'Aynı hareketi sol elinle yap. İkisi birlikte bir tekrar eder.', 'Önerilen tekrar sayısı bitene kadar böyle sırayla devam et.']::text[]),
  ('Alternate_Leg_Diagonal_Bound', 'tr', array['Bir ayağın diğerinin biraz önünde olacak şekilde rahat bir duruş al.', 'Öndeki bacağınla yeri iterek başla; yere inmeden önce diğer dizini öne ve olabildiğince yukarı sür. Her sıçrayışta yana doğru olabildiğince fazla mesafe almaya çalış.', 'Bir yandan öbür yana aldığın mesafeyi ölçmek için yerdeki bir çizgiden yararlanabilirsin.', 'Aynı sırayı diğer bacağınla tekrarla.']::text[]),
  ('Alternating_Cable_Shoulder_Press', 'tr', array['Kablo makaralarını kulenin en altına al ve uygun bir ağırlık seç.', 'Tutamakları kavra ve avuç içlerin öne bakacak şekilde omuz hizasında tut. Bu, başlangıç pozisyonun.', 'Başını ve göğsünü dik tut, bir dirseğini açarak o tarafı doğrudan başının üstüne it.', 'Üstte kısa bir an bekle, başlangıç pozisyonuna dön ve diğer tarafla tekrarla.']::text[]),
  ('Alternating_Deltoid_Raise', 'tr', array['Ayakta dur ve bir çift dambılı gövdenin iki yanında tut.', 'Dirseklerin hafif bükülü olsun; dambılları tam önünde omuz hizasına kadar kaldır. Sallanma ve hile yapma.', 'Dambılları yanlarına geri indir.', 'Sonraki tekrarda dambılları yana doğru aç ve yaklaşık omuz hizasına kadar kaldır.', 'Dambılları başlangıç pozisyonuna indir ve bir öne, bir yana kaldırarak devam et.']::text[]),
  ('Alternating_Floor_Press', 'tr', array['Yere sırtüstü uzan, omuzlarının yanında iki kettlebell olsun.', 'Önce birini, sonra diğerini göğsünün üzerinde yerine al. Kettlebell''leri saplarından, avuç içlerin öne bakacak şekilde kavra.', 'İki kolunu da uzat; kettlebell''ler göğsünün üstünde dursun. Birini göğsüne indir ve bileğini, yukarıda kilitli duran kettlebell''e doğru çevir.', 'Kettlebell''i yukarı it ve diğer tarafla tekrarla.']::text[]),
  ('Alternating_Hang_Clean', 'tr', array['İki kettlebell''i ayaklarının arasına koy. Başlangıç pozisyonu için kalçanı geriye it ve tam karşıya bak.', 'Bir kettlebell''i omzuna al, diğeri uzanmış kolunda asılı kalsın. Omuza almak için bacaklarını ve kalçanı açarken kettlebell''i omzuna doğru çek. Bunu yaparken bileğini çevir.', 'Omzundaki kettlebell''i asılı pozisyona indir ve diğerini omzuna al. Böyle devam et.']::text[]),
  ('Alternating_Kettlebell_Press', 'tr', array['İki kettlebell''i omuzlarına al. Bunun için bacaklarını ve kalçanı açarken kettlebell''leri omuzlarına doğru çek. Bunu yaparken bileklerini çevir.', 'Bir dirseğini açarak o kettlebell''i doğrudan başının üstüne it; iterken avuç için öne bakacak şekilde çevir. Diğer kettlebell yerinde sabit kalsın.', 'İttiğin kettlebell''i başlangıç pozisyonuna indir ve hemen diğer kolunla it.']::text[]),
  ('Alternating_Kettlebell_Row', 'tr', array['İki kettlebell''i ayaklarının önüne koy. Dizlerini hafifçe bük ve kalçanı olabildiğince geriye it. Başlangıç pozisyonu için öne eğilirken iki kettlebell''i de saplarından kavra.', 'Diğerini bırakmadan bir kettlebell''i yerden çek. Çalışan taraftaki kürek kemiğini geriye al, dirseğini bük ve kettlebell''i karnına ya da kaburgalarına doğru getir.', 'Çalışan koldaki kettlebell''i indir ve diğer kolunla tekrarla.']::text[]),
  ('Alternating_Renegade_Row', 'tr', array['İki kettlebell''i yaklaşık omuz genişliğinde aralıkla yere koy. Şınav çeker gibi ayak parmaklarının ve ellerinin üzerinde dur; vücudun düz ve gergin olsun, gövdeni kettlebell''lerin saplarıyla destekle. Denge için ayaklarını geniş açman gerekebilir.', 'Bir kettlebell''i yere bastır, diğerini kendine çek: çalışan taraftaki kürek kemiğini geriye al, dirseğini bük ve kettlebell''i gövdenin yanına getir.', 'Sonra kettlebell''i yere indir ve diğer elindekiyle devam et. Birkaç tekrar yap.']::text[]),
  ('Ankle_Circles', 'tr', array['Squat sehpası gibi sağlam bir şeye tutun.', 'Sağ bacağını yerden yalnızca 2 inç kadar kaldır ve başparmağınla daire çiz. Onunla büyük bir daire çizdiğini düşün. İpucu: Bir daire 1 tekrar eder. Hareket sırasında normal nefes al.', 'Sağ ayağınla bitirince aynısını sol bacağınla yap.']::text[]),
  ('Ankle_On_The_Knee', 'tr', array['Sırtüstü yatarken dizlerini bük, ayakların yerde kalsın.', 'Bir bacağının ayak bileğini diğer dizinin üzerine koy.', 'Alttaki bacağın uyluğunu ya da dizini kavra ve iki bacağını göğsüne çek. Boynunu ve omuzlarını gevşet. 10-20 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Anterior_Tibialis-SMR', 'tr', array['Bacakların bükülü, ayakların yerde olacak şekilde yere otur.', 'Bir masaj çubuğu ya da oklava ile kaval kemiğinin dış tarafındaki kaslara baskı uygula. Dizin hemen altından ayak bileğinin üstüne kadar çalış, gergin noktalarda 10-30 saniye bekle. Diğer bacağınla tekrarla.']::text[]),
  ('Anti-Gravity_Press', 'tr', array['Bir halteri eğimli sehpanın baş tarafının arkasına, yere koy.', 'Sehpaya yüzüstü uzan. Halteri üstten tutuşla yerden al. Ters curl yapar gibi dirseklerini bükerek barı göğsüne yaklaştır. Bu, başlangıç pozisyonun.', 'Dirseklerini açarak halteri başının önüne doğru it. Hareket boyunca kolların yere paralel kalsın.', 'Başlangıç pozisyonuna dön ve set bitene kadar tekrarla.']::text[]),
  ('Arm_Circles', 'tr', array['Ayakta dur ve kollarını iki yana dümdüz aç. Kolların yere paralel, gövdene dik (90 derecelik açıyla) olsun. Bu, başlangıç pozisyonun.', 'Açık duran her kolunla yavaşça, çapı yaklaşık 1 fit olan daireler çizmeye başla. Hareket sırasında normal nefes al.', 'Kolların açıkken yaklaşık on saniye daire çizmeye devam et. Sonra ters yöne çevir.']::text[]),
  ('Arnold_Dumbbell_Press', 'tr', array['Sırt destekli bir sehpaya otur. İki dambılı önünde, yaklaşık üst göğüs hizasında tut; dirseklerin bükülü, avuç içlerin sana dönük olsun. İpucu: Kolların gövdenin hemen yanında dursun. Başlangıç pozisyonu, dambıl curl hareketinin en üst noktasına benzemeli.', 'Harekete geçmek için dambılları kaldır ve kaldırırken avuç içlerini öne bakana kadar çevir.', 'Kolların başının üstünde dümdüz olana kadar itmeye devam et. Hareketin bu kısmında nefes ver.', 'Üstte bir saniye bekle, sonra avuç içlerini kendine doğru çevirerek dambılları ilk pozisyona indir. İpucu: Sol kol saat yönünün tersine, sağ kol saat yönünde döner. Hareketin bu kısmında nefes al.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('Around_The_Worlds', 'tr', array['Düz bir sehpaya sırtüstü uzan, iki elinde birer dambıl olsun ve avuç içlerin tavana baksın. İpucu: Kolların yere paralel ve uyluklarının yanında dursun. Sakatlanmamak için dirseklerini hafif bükülü tut. Bu, başlangıç pozisyonun.', 'Şimdi dambılları yarım daire çizerek uyluklarının yanından başının üstüne götür. Hareketin tamamında kolların yere paralel kalsın. Bu kısımda nefes al.', 'Nefes verirken aynı yoldan geri gelerek ağırlıkları başlangıç pozisyonuna getir.']::text[]),
  ('Atlas_Stone_Trainer', 'tr', array['Bu alet, elinin altında taş yokken Atlas taşı kuvvetini geliştirmene yarar. Genellikle bar uçlarından ya da ağır borudan yapılır.', 'İstediğin ağırlığı bara tak. Ağırlığı iki bacağının arasına al, kalçandan eğil ve kollarını aletin çevresine sar.', 'Kalçanı açarak ağırlığı dizlerinin üstüne kadar çek. Ağırlık dizlerini geçince kucağına alabilirsin: geriye otur, onu uyluklarına yasla ve göğsüne sıkıca bastır.', 'Hareketi bitirmek için kalçanı ve dizlerini aç, ağırlığı olabildiğince yukarı kaldır. Sonraki tekrar için ağırlığı kucağına ya da yere indirebilirsin.']::text[]),
  ('Atlas_Stones', 'tr', array['Taş ayaklarının arasında olacak şekilde dur. Kalçandan eğil, kollarını taşa yukarıdan aşağı sar ve parmaklarını taşın altına sokmaya çalış. Çoğu taşın altında küçük düz bir bölüm olur; bu, taşı tutmayı kolaylaştırır.', 'Taşı gövdene doğru çek ve ayaklarının arka yarısından iterek onu yerden kaldır.', 'Taş dizlerini geçince kucağına al: geriye otur ve taşı uyluklarının üstüne çek.', 'Alçakta kal, taşı göğsünün üstüne doğru yukarı al ve tutuşunu değiştirerek taşın üzerinden uzan. Kalçanı öne sürerek ayağa kalk. Yükleme platformuna yaklaş, geriye yaslan ve taşı olabildiğince yükseğe çıkarmak için kalçanı aç.']::text[]),
  ('Axle_Deadlift', 'tr', array['Bar ayaklarının ortasının üstüne gelene kadar bara yaklaş. Ayakların yaklaşık kalça genişliğinde açık olsun. Kalçandan eğil, barı omuz genişliğinde kavra ve kürek kemiklerinin öne gelmesine izin ver. Genellikle karışık tutuş (bir el üstten, bir el alttan) kullanılır.', 'Ayakların ve tutuşun hazır olunca derin bir nefes al. Sonra kalçanı indir ve kaval kemiklerin bara değene kadar dizlerini bük. Karşıya bak, göğsünü yukarıda ve belini çukur tut, topuklarından iterek ağırlığı yukarı doğru hareket ettir.', 'Bar dizlerini geçince onu sertçe geriye çek: kürek kemiklerini birbirine yaklaştır ve kalçanı öne, bara doğru sür.', 'Barı indirmek için kalçandan eğil ve onu yere kadar yönlendir.']::text[]),
  ('Back_Flyes_-_With_Bands', 'tr', array['Lastik bandı squat sehpasının direği gibi sabit bir direğin çevresinden geçir.', 'Bandı tutamaklarından kavra ve banttaki gerginlik artana kadar geri çekil.', 'Kollarını kaldır ve tam önüne doğru uzat. İpucu: Kolların düz, yere paralel ve gövdene dik olsun. Ayakların omuz genişliğinde açık, yere sağlam bassın. Bu, başlangıç pozisyonun.', 'Nefes verirken kollarını iki yana ve geriye doğru aç. Kolların düz ve yere paralel kalsın. Kolların iki yanına tam açılana kadar devam et.', 'Kısa bir an bekle, sonra nefes alarak ilk pozisyona dön.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('Backward_Drag', 'tr', array['Kızağa istediğin ağırlığı yükle ve tutabileceğin bir ip ya da kayış bağla.', 'Belirlenen mesafe boyunca geri geri yürü. Geriye yaslan, bacaklarınla iterek kısa adımlar at ve olabildiğince hızlı ilerle.']::text[]),
  ('Backward_Medicine_Ball_Throw', 'tr', array['Bu egzersiz en iyi bir partnerle yapılır. Partnerin yoksa topu atıp kendin geri alabilir ya da duvara atabilirsin.', 'Partnerinin birkaç metre önünde dur; ikiniz de aynı yöne bakın. Başlarken sağlık topunu bacaklarının arasında tut.', 'Çömel, sonra hareketi güçlü bir şekilde tersine çevir, tamamen doğrul ve topu başının üzerinden partnerine at.', 'Partnerin topu sana geri yuvarlayabilir. İstediğin sayıda tekrar yap.']::text[]),
  ('Balance_Board', 'tr', array['Bir denge tahtasını önüne, yere koy.', 'Üzerine çık ve dengeni bulmaya çalış.', 'Dengeni istediğin kadar koru.']::text[]),
  ('Ball_Leg_Curl', 'tr', array['Yere sırtüstü uzan ve ayaklarını pilates topunun üstüne koy.', 'Topu, bacakların düzken ayak bileklerin topun üstünde kalacak şekilde yerleştir. Bu, başlangıç pozisyonun.', 'Kalçanı yerden kaldır; ağırlığın kürek kemiklerinde ve ayaklarında olsun.', 'Dizlerini bük, arka bacak kaslarını kasarak topu kendine olabildiğince yaklaştır.', 'Kısa bir an bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Band_Assisted_Pull-Up', 'tr', array['Bandı barfiks barının ortasına, kendi içinden geçirip sıkarak bağla. Farklı bantlarla desteğin miktarını değiştirebilirsin.', 'Bandın ucunu aşağı çek ve bükülü bir dizini halkanın içine yerleştir; kaymayacağından emin ol. Barı orta ile geniş arası bir tutuşla kavra. Bu, başlangıç pozisyonun.', 'Kanat kaslarını kasıp dirseklerini bükerek kendini yukarı çek. Dirseklerini gövdenin yanlarına doğru sür. Bar önünde kalacak şekilde çekil ve çeneni barın üstüne çıkarmaya çalış. Sallanma ve ani hareket yapma.', 'Kısa bir an bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Band_Good_Morning', 'tr', array['41 inçlik bir lastik bant al, ayaklarını biraz açarak bir ucuna bas. Kalçandan eğil ve bandın diğer ucunu boynunun arkasına geçir. Bu, başlangıç pozisyonun.', 'Bacaklarını düz tutarak kalçanı aç ve neredeyse dik duruşa gel.', 'Başlangıç pozisyonuna geri inerken sırtını yuvarlamadığından emin ol.']::text[]),
  ('Band_Good_Morning_Pull_Through', 'tr', array['Bandı bir direğin çevresinden geçir. Biraz uzakta dur ve diğer ucunu boynuna geçir. Bandı yerinde tutmak için ellerinden yararlanabilirsin.', 'Kalçandan eğilerek başla ve kalçanı olabildiğince geriye it. Sırtını düz tut ve yaklaşık 90 dereceye kadar öne eğil. Dizlerin yalnızca hafif bükülü olsun.', 'Kalçanı öne sürerek doğrul ve ayakta, başlangıç pozisyonuna dön.']::text[]),
  ('Band_Hip_Adductions', 'tr', array['Bir lastik bandı sağlam bir direğe ya da benzer bir nesneye bağla.', 'Sol yanın direğe dönük dur ve sağ ayağını bandın içinden geçirip bandı ayak bileğine yerleştir.', 'Dik dur, gerekirse direğe tutun. Bu, başlangıç pozisyonun.', 'Dizini düz tutarak sağ bacağını yana doğru kaldırabildiğin kadar kaldır.', 'Başlangıç pozisyonuna dön ve istediğin tekrar sayısı kadar yap.', 'Taraf değiştir.']::text[]),
  ('Band_Pull_Apart', 'tr', array['Bandı iki elinle tut, kolların tam önünde dümdüz uzanmış olsun.', 'Harekete ters fly yapar gibi başla: ellerini iki yana doğru aç.', 'Hareket boyunca dirseklerini düz tut ve bandı göğsüne getir. Egzersiz sırasında omuzlarının geride kaldığından emin ol.', 'Hareketin sonunda kısa bir an bekle ve kontrollü şekilde başlangıç pozisyonuna dön.']::text[]),
  ('Band_Skull_Crusher', 'tr', array['Bir lastik bandı sehpaya ya da bir kafesin alt kısmına sabitle. Sehpaya, bant başınla aynı hizada olacak şekilde uzan.', 'Bandı kavra ve dirseklerini, üst kolların yere dik olana kadar kaldır. Dirseklerin bükülüyken bant başının üstünde olmalı. Bu, başlangıç pozisyonun.', 'Üst kollarını yerinde tutarak dirseklerini aç ve kollarını düzleştir. Hareketin tepesinde kısa bir an bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Barbell_Ab_Rollout', 'tr', array['Şınav pozisyonu al, ama ellerini yere koymak yerine her iki yanına 5-10 lbs takılmış bir olimpik halteri kavra. Bu, başlangıç pozisyonun.', 'Sırtında hafif bir kavis bırak, nefes verirken kalçanı kaldır ve halteri ayaklarına doğru yuvarla. İpucu: Hareket sırasında kalçan yukarı çıkmalı, karnın sıkı kalmalı ve sırtının duruşu hiç bozulmamalı. Kolların da hareket boyunca yere dik kalmalı. Yoksa karnından çok omuzlarını ve sırtını çalıştırırsın.', 'Üstte bir saniye kasılı kal, sonra nefes alırken halteri yavaşça yeniden öne, başlangıç pozisyonuna yuvarla.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('Barbell_Ab_Rollout_-_On_Knees', 'tr', array['Her iki yanına 5-10 lbs takılmış bir olimpik halteri tut ve yere diz çök.', 'Halteri önünde yere koy; dizler üzerinde şınav pozisyonundaki gibi ellerin ve dizlerin üzerinde dur. Bu, başlangıç pozisyonun.', 'Halteri yavaşça dümdüz ileri yuvarla ve vücudun düz bir çizgi olana kadar uzan. İpucu: Vücudun yere değmeden inebildiğin kadar in. Hareketin bu kısmında nefes al.', 'Uzanmış pozisyonda bir saniye bekle, sonra nefes vererek kendini başlangıç pozisyonuna geri çek. İpucu: Yavaş git ve karnını hep sıkı tut.']::text[]),
  ('Barbell_Bench_Press_-_Medium_Grip', 'tr', array['Düz bir sehpaya sırtüstü uzan. Orta genişlikte bir tutuş al; yani hareketin ortasında ön kolların ile üst kolların arasında 90 derecelik açı oluşturan bir tutuş. Barı askıdan kaldır ve kolların kilitli halde tam üstünde tut. Bu, başlangıç pozisyonun.', 'Nefes al ve barı göğsünün ortasına değene kadar yavaşça indir.', 'Kısa bir an bekle, sonra nefes verirken barı başlangıç pozisyonuna it. Barı göğüs kaslarınla itmeye odaklan. Üstte kollarını kilitle, göğsünü sık, bir saniye bekle ve yeniden yavaşça inmeye başla. İpucu: İdeal olarak ağırlığı indirmek, kaldırmanın yaklaşık iki katı sürmeli.', 'Programındaki tekrar sayısı kadar devam et.', 'Bitirince barı askıya geri koy.']::text[]),
  ('Barbell_Curl', 'tr', array['Gövden dik şekilde ayakta dur ve halteri omuz genişliğinde tut. Avuç içlerin öne baksın, dirseklerin gövdene yakın dursun. Bu, başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes verirken bisepslerini kasarak barı öne doğru kaldır. İpucu: Yalnızca ön kollar hareket etmeli.', 'Bisepslerin tamamen kasılana ve bar omuz hizasına gelene kadar devam et. Bu noktada bir saniye bekle ve bisepslerini iyice sık.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('Barbell_Curls_Lying_Against_An_Incline', 'tr', array['Eğimli bir sehpaya yaslan, ellerinde bir halter olsun ve kolların yatay bir çizgide aşağı sarksın. Bu, başlangıç pozisyonun.', 'Üst kollarını sabit tutarak barı kaldırabildiğin kadar yukarı kaldır ve bisepslerini sık. Hareketin bu kısmında nefes ver. İpucu: Yalnızca ön kollar hareket etmeli. Kollarını sallama.', 'Bir saniye kasılı kal, sonra nefes alırken yavaşça başlangıç pozisyonuna dön. İpucu: Sonuna kadar indiğinden emin ol.', 'Programındaki tekrar sayısı kadar devam et.']::text[]),
  ('Barbell_Deadlift', 'tr', array['Ağırlık takılı bir halterin önünde dur.', 'Sırtını olabildiğince düz tut, dizlerini bük, öne eğil ve barı orta genişlikte (omuz genişliğinde), üstten tutuşla kavra. Egzersiz bu pozisyondan başlar. İpucu: Barı bu tutuşla tutmak zor geliyorsa karışık tutuş ya da bilek kayışı kullan.', 'Barı tutarken nefes ver ve kaldırışa bacaklarınla iterek başla; aynı anda gövdeni dik konuma getir. Dik durduğunda göğsünü öne çıkar ve kürek kemiklerini geriye alarak sırtını kas. Hazır olda duran bir askeri gözünün önüne getir.', 'Geri inmek için dizlerini bük ve aynı anda gövdeni belden öne eğ; sırtın düz kalsın. Bardaki plakalar yere değdiğinde yeniden başlangıç pozisyonundasın ve sonraki tekrara hazırsın.', 'Programda yazan tekrar sayısını tamamla.']::text[]),
  ('Barbell_Full_Squat', 'tr', array['Güvenlik için bu egzersizi squat rack içinde yap. Barı omuz hizasının biraz üstünde askıya yerleştir. Yükseklik doğruysa ve plakalar takılıysa barın altına gir ve barı omuzlarının arkasına, boynunun biraz altına oturt.', 'Barı iki yanından birer elinle kavra. Bacaklarınla iterken gövdeni de dikleştirerek barı askıdan kaldır.', 'Rack''ten geriye doğru bir adım at. Ayaklarını omuz genişliğinde, orta bir duruşla yerleştir, ayak uçların hafifçe dışa baksın. Başını hep yukarıda, sırtını düz tut. Bu senin başlangıç pozisyonun.', 'Nefes al ve barı yavaşça indir: dizlerini bük, kalçanı geriye doğru götür, başın yukarıda ve duruşun dik kalsın. Arka bacakların baldırlarına değene kadar in.', 'Nefes ver ve topuğunla ya da ayağının ortasıyla yeri iterek barı yukarı kaldır. Bacaklarını ve kalçanı açarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Glute_Bridge', 'tr', array['Yere otur, plaka takılı halter bacaklarının üzerinde dursun. Kalın bir bar ya da bara sarılı bir ped bu egzersizdeki rahatsızlığı epey azaltır. Barı tam kalçanın üstüne gelene kadar yuvarla ve sırtüstü yere uzan.', 'Harekete topuklarınla iterek başla ve kalçanı bara karşı dikey olarak yukarı kaldır. Ağırlığını üst sırtın ve topukların taşır.', 'Kalçanı kaldırabildiğin kadar kaldır, sonra aynı yoldan başlangıç pozisyonuna in.']::text[]),
  ('Barbell_Guillotine_Bench_Press', 'tr', array['Barı orta genişlikte tut, yani hareketin ortasında ön kolunla üst kolun arasında 90 derecelik açı oluşacak şekilde. Barı askıdan al ve kolların kilitli halde tam boynunun üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes al ve barı boynuna yaklaşık 1 inç kalana kadar yavaşça indir.', 'Bir saniye bekle, sonra nefes ver ve barı göğüs kaslarınla iterek başlangıç pozisyonuna çıkar. Kollarını kilitle, yukarıda göğsünü sık, bir saniye tut ve yeniden yavaşça inmeye başla. İniş, çıkışın en az iki katı kadar sürmeli.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Bitirdiğinde barı askıya geri koy.']::text[]),
  ('Barbell_Hack_Squat', 'tr', array['Ayakların omuz genişliğinde, dik dur ve halteri kolların tam uzanmış halde arkanda tut. İpucu: En iyisi barı omuz genişliğinde, avuç içlerin arkaya bakacak şekilde tutmak. Daha sağlam bir tutuş için bilek sargısı kullanabilirsin. Bu senin başlangıç pozisyonun.', 'Başını ve bakışını yukarıda, sırtını düz tut. Nefes al ve üst bacakların yere paralel olana kadar yavaşça çömel.', 'Nefes ver ve yukarı kalk. Kalkarken en çok topuklarınla it ve üst bacaklarını sık.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Hip_Thrust', 'tr', array['Yere otur, hemen arkanda bir sehpa olsun. Plaka takılı halter bacaklarının üzerinde dursun. Kalın bir bar ya da bara sarılı bir ped bu egzersizdeki rahatsızlığı epey azaltır.', 'Barı tam kalçanın üstüne gelene kadar yuvarla. Sehpaya yaslan, kürek kemiklerin sehpanın üst kenarına yakın olsun.', 'Harekete ayaklarınla iterek başla ve kalçanı bara karşı dikey olarak yukarı kaldır. Ağırlığını kürek kemiklerin ve ayakların taşır. Kalçanı kaldırabildiğin kadar kaldır, sonra aynı yoldan başlangıç pozisyonuna in.']::text[]),
  ('Barbell_Incline_Bench_Press_-_Medium_Grip', 'tr', array['Eğimli sehpaya uzan. Barı orta genişlikte tut, yani hareketin ortasında ön kolunla üst kolun arasında 90 derecelik açı oluşacak şekilde. Barı askıdan al ve kolların kilitli halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes al ve barı üst göğsünde hissedene kadar yavaşça indir.', 'Bir saniye bekle, sonra nefes ver ve barı göğüs kaslarınla iterek başlangıç pozisyonuna çıkar. Yukarıda kollarını kilitle, göğsünü sık, bir saniye tut ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Bitirdiğinde barı askıya geri koy.']::text[]),
  ('Barbell_Incline_Shoulder_Raise', 'tr', array['Eğimli sehpaya uzan. Barı orta genişlikte, yani omuz genişliğinden biraz daha açık tut. Barı askıdan al ve kolların düz halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Kollarını düz tutarak nefes ver ve kürek kemiklerini öne doğru iterek barı yükselt. Bu sırada omuzların sehpadan kalkar.', 'Nefes al ve barı başlangıç pozisyonuna geri indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Lunge', 'tr', array['Güvenlik için bu egzersizi squat rack içinde yap. Barı omuz hizasının biraz altında askıya yerleştir. Yükseklik doğruysa ve plakalar takılıysa barın altına gir ve barı omuzlarının arkasına, boynunun biraz altına oturt.', 'Barı iki yanından birer elinle kavra. Bacaklarınla iterken gövdeni de dikleştirerek barı askıdan kaldır.', 'Rack''ten uzaklaş. Sağ bacağınla öne bir adım at ve kalçandan aşağı doğru çök. Gövden dik kalsın, dengeni koru. İnerken nefes al. Not: İnerken dizin ayak parmaklarının önüne geçmesin, yoksa diz eklemine gereksiz yük biner.', 'Nefes ver ve en çok topuğunla iterek başlangıç pozisyonuna kalk.', 'Hareketi önerilen tekrar sayısı kadar yap, sonra sol bacağınla tekrarla.']::text[]),
  ('Barbell_Rear_Delt_Row', 'tr', array['Dik dur ve halteri geniş, yani omuz genişliğinden daha açık ve üstten bir tutuşla kavra, avuç içlerin vücuduna baksın.', 'Dizlerini hafifçe bük ve sırtının doğal kavsini bozmadan öne eğil. Kolların barla birlikte önünde aşağı sarksın. Gövden yere paralel olunca dirseklerini dışa, vücudundan uzağa doğru aç. İpucu: Gövden ve kolların birlikte "T" harfine benzemeli. Artık egzersize başlamaya hazırsın.', 'Üst kollarını gövdene dik tut. Nefes ver ve arka omuz kaslarını sıkarak halteri üst göğsüne doğru çek. İpucu: Doğru yapıldığında bu hareket ters çevrilmiş bir bench press''e benzer. İşi bisepsine yaptırma. Arka omuz kaslarına odaklan, kolların yalnızca birer kanca görevi görsün.', 'Nefes al ve yavaşça ilk pozisyona dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Rollout_from_Bench', 'tr', array['Plaka takılı bir halteri bir sehpanın ucuna yakın yere koy. İki bacağınla sehpanın üzerinde diz çök ve halteri orta ile dar arası bir genişlikte tut. Bu senin başlangıç pozisyonun.', 'Başlamak için kalçanı açarak barı yavaşça öne yuvarla. Yuvarlarken omuzlarını aç ki bar başının üstüne gelsin. Hareket boyunca kollarının düz kalmasına dikkat et.', 'Bar gidebildiği kadar öne gidince başlangıç pozisyonuna dön.']::text[]),
  ('Barbell_Seated_Calf_Raise', 'tr', array['Düz bir sehpanın yaklaşık 12 inç önüne bir blok koy.', 'Sehpaya otur ve ayaklarının parmak kökü kısmını bloğun üzerine yerleştir.', 'Birinden halteri üst bacaklarının üzerine, dizlerinin yaklaşık 3 inç yukarısına koymasını ve orada tutmasını iste. Bu senin başlangıç pozisyonun.', 'Nefes ver ve baldırlarını sıkarak parmak uçlarında yükselebildiğin kadar yüksel.', 'Kasılmayı bir saniye tut, sonra yavaşça başlangıç pozisyonuna dön. İpucu: En yüksek verimi almak için baldırlarını esnetebildiğin kadar esnet.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Shoulder_Press', 'tr', array['Squat rack içinde, sırt destekli bir sehpaya otur. Halteri başının biraz üstündeki bir yüksekliğe yerleştir. Halteri üstten tutuşla kavra, avuç içlerin öne baksın.', 'Tutuş genişliğin doğruysa halteri al ve kollarını kilitleyerek başının üzerine kaldır. Barı yaklaşık omuz hizasında ve başının biraz önünde tut. Bu senin başlangıç pozisyonun.', 'Nefes al ve barı yavaşça omuzlarına indir.', 'Nefes ver ve barı yeniden başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Shrug', 'tr', array['Ayakların omuz genişliğinde, dik dur. Halteri iki elinle önünde, üstten tutuşla kavra, avuç içlerin üst bacaklarına baksın. İpucu: Ellerin omuz genişliğinden biraz daha açık olsun. Daha sağlam bir tutuş için bilek sargısı kullanabilirsin. Bu senin başlangıç pozisyonun.', 'Nefes ver ve omuzlarını çıkabildiği kadar yukarı çek. Kasılmayı bir saniye tut. İpucu: Halteri bisepsinle kaldırmaya çalışma.', 'Nefes al ve yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Shrug_Behind_The_Back', 'tr', array['Ayakların omuz genişliğinde, dik dur. Halteri iki elinle sırtının arkasında, üstten tutuşla kavra, avuç içlerin arkaya baksın. İpucu: Ellerin omuz genişliğinden biraz daha açık olsun. Daha sağlam bir tutuş için bilek sargısı kullanabilirsin. Bu senin başlangıç pozisyonun.', 'Nefes ver ve omuzlarını çıkabildiği kadar yukarı çek. Kasılmayı bir saniye tut. İpucu: Halteri bisepsinle kaldırmaya çalışma. Kolların hareket boyunca gergin ve düz kalsın.', 'Nefes al ve yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Side_Bend', 'tr', array['Dik dur, halter omuzlarının arkasında, boynunun biraz altında dursun. Ayaklarını omuz genişliğinde aç. Bu senin başlangıç pozisyonun.', 'Sırtını düz, başını yukarıda tut. Nefes al ve yalnızca belinden bükülerek sağa doğru eğilebildiğin kadar eğil. Bir saniye tut, sonra nefes vererek başlangıç pozisyonuna doğrul. İpucu: Vücudunun geri kalanı sabit kalsın.', 'Şimdi aynı hareketi sola eğilerek yap. Bir saniye tut ve başlangıç pozisyonuna doğrul.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Side_Split_Squat', 'tr', array['Dik dur, halter omuzlarının arkasında, boynunun biraz altında dursun. Ayaklarını geniş aç ve öndeki bacağının ayağını yana, dışa doğru çevir. Bu senin başlangıç pozisyonun.', 'Nefes al ve dışa çevirdiğin ayağın tarafına doğru alçal. Bunu yaparken öndeki bacağının dizini ve kalçasını bük, diğer bacağın yalnızca hafifçe bükülü kalsın.', 'Nefes ver ve öndeki bacağının kalçasını ve dizini açarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamlayınca hareketi diğer bacağınla tekrarla.']::text[]),
  ('Barbell_Squat', 'tr', array['Güvenlik için bu egzersizi squat rack içinde yap. Barı omuz hizasının biraz altında askıya yerleştir. Yükseklik doğruysa ve plakalar takılıysa barın altına gir ve barı omuzlarının arkasına, boynunun biraz altına oturt.', 'Barı iki yanından birer elinle kavra. Bacaklarınla iterken gövdeni de dikleştirerek barı askıdan kaldır.', 'Rack''ten geriye doğru bir adım at. Ayaklarını omuz genişliğinde, orta bir duruşla yerleştir, ayak uçların hafifçe dışa baksın. Başını hep yukarıda, sırtını düz tut. Bu senin başlangıç pozisyonun. Not: Buradaki orta duruş bacakları bütün olarak çalıştırır, ama üç squat duruşundan istediğini seçebilirsin.', 'Nefes al ve dizlerini ve kalçanı bükerek barı yavaşça indir. Başın yukarıda, duruşun dik kalsın. Üst bacağınla baldırın arasındaki açı 90 derecenin biraz altına düşene kadar in. İpucu: Hareket doğruysa dizlerinin ön yüzü ile ayak parmakların hayali, dikey bir çizgi üzerinde durur. Dizlerin bu çizgiyi, yani ayak parmaklarını geçerse dizine gereksiz yük bindirirsin ve hareket yanlış olur.', 'Nefes ver, topuklarınla yeri iterek barı kaldır ve bacaklarını düzelterek başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Squat_To_A_Bench', 'tr', array['Güvenlik için bu egzersizi squat rack içinde yap. Önce arkana düz bir sehpa ya da bir kasa koy. Sehpa, kalçanı geriye götürmeyi ve doğru derinliğe inmeyi öğrenmene yarar.', 'Sonra barı boyuna en uygun yükseklikte askıya yerleştir. Yükseklik doğruysa ve plakalar takılıysa barın altına gir ve barı omuzlarının arkasına, boynunun biraz altına oturt.', 'Barı iki yanından birer elinle kavra. Bacaklarınla iterken gövdeni de dikleştirerek barı askıdan kaldır.', 'Rack''ten geriye doğru bir adım at. Ayaklarını omuz genişliğinde, orta bir duruşla yerleştir, ayak uçların hafifçe dışa baksın. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar, sırtın da düz kalsın. Bu senin başlangıç pozisyonun. Not: Buradaki orta duruş bacakları bütün olarak çalıştırır, ama üç squat duruşundan istediğini seçebilirsin.', 'Nefes al ve barı yavaşça indir: dizlerini bük, kalçanı geriye götür, başın yukarıda ve duruşun dik kalsın. Arkandaki sehpaya hafifçe değene kadar in. İpucu: Hareket doğruysa dizlerinin ön yüzü ile ayak parmakların hayali, dikey bir çizgi üzerinde durur. Dizlerin bu çizgiyi, yani ayak parmaklarını geçerse dizine gereksiz yük bindirirsin ve hareket yanlış olur.', 'Nefes ver ve topuklarınla yeri iterek barı kaldır. Bacaklarını ve kalçanı açarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Barbell_Step_Ups', 'tr', array['Halteri omuzlarının arkasına, boynunun biraz altına yerleştir ve yükseltilmiş bir platformun arkasında dik dur, örneğin düz sehpanın arkasındaki yardımcı basamağı gibi. Bu senin başlangıç pozisyonun.', 'Sağ ayağını platforma koy. Nefes ver ve sağ bacağının kalçasını ve dizini açarak platforma çık. Vücudunu en çok topuğunla iterek kaldır, sonra sol ayağını da platforma koy.', 'Nefes al ve sağ bacağının kalçasını ve dizini bükerek sol bacağınla aşağı in. Ardından sağ ayağını sol ayağının yanına koy ve ilk duruşuna dön.', 'Önerilen tekrar sayısını sağ bacağınla tamamla, sonra sol bacağınla yap.']::text[]),
  ('Barbell_Walking_Lunge', 'tr', array['Ayakların omuz genişliğinde, halter üst sırtında olacak şekilde ayakta dur.', 'Bir bacağınla öne adım at ve iki dizini bükerek kalçanı indir. Arkadaki dizin neredeyse yere değene kadar alçal. Gövden dik kalsın, öndeki dizin öndeki ayağının üzerinde dursun.', 'Öndeki ayağının topuğuyla it ve iki dizini de açarak yukarı kalk.', 'Arkadaki ayağını öne atarak yeni adıma geç ve lunge''ı diğer bacağınla yap.']::text[]),
  ('Battling_Ropes', 'tr', array['Bu egzersiz için ortasından, senden 15-20 fit uzakta sabitlenmiş ağır bir halat gerekir. Halatın sabitlendiği yere dönük dur ve kolların yanlarında uzanmış halde her eline bir ucu al. Bu senin başlangıç pozisyonun.', 'Harekete bir kolunu olabildiğince hızlı biçimde omuz hizasına kaldırarak başla.', 'O kol başlangıç pozisyonuna düşerken diğer kolunu kaldır.', 'Sol ve sağ kolunu sırayla çalıştırmayı sürdür, halatları olabildiğince hızlı yukarı aşağı savur.']::text[]),
  ('Bear_Crawl_Sled_Drags', 'tr', array['Bir koşum takımı ya da bol bir ağırlık kemeri tak ve zinciri arkasına bağla, böylece sırtın kızağa dönük olur. Eğil ve ellerini yere koy, sırtın düz, dizlerin bükülü olsun. Bu senin başlangıç pozisyonun.', 'Bacaklarınla, sırayla sol ve sağ iterek başla. Ellerinle dengeni koru ve çekmeye yardım et. Belirlenen mesafeyi giderken sırtını düz tutmaya çalış.']::text[]),
  ('Behind_Head_Chest_Stretch', 'tr', array['Yere dik otur, partnerin arkanda dursun.', 'Ellerini başının arkasına koy ve dirseklerini gidebildiği kadar geriye it. Partnerin dirseklerini tutsun. Bu senin başlangıç pozisyonun.', 'Ellerin başının arkasındayken 10 saniye ya da daha uzun süre dirseklerini nazikçe öne çekmeye çalış. Partnerin dirseklerinin hareket etmesine izin vermesin.', 'Şimdi kaslarını gevşet ve partnerin dirseklerini sana rahat gelen yere kadar nazikçe geriye çeksin. Aşırı esnemeyi ya da sakatlanmayı önlemek için esnemenin yettiği anı partnerine mutlaka söyle.']::text[]),
  ('Bench_Dips', 'tr', array['Arkana bir sehpa koy. Sehpa vücuduna dik dursun, sen de ona sırtını dön. Ellerin omuz genişliğinde, kolların tam düz halde sehpanın kenarından tutun. Bacaklarını öne uzat, belinden bükül, bacakların gövdene dik olsun. Bu senin başlangıç pozisyonun.', 'Nefes al ve dirseklerini bükerek vücudunu yavaşça indir, üst kolunla ön kolun arasındaki açı 90 derecenin biraz altına düşene kadar. İpucu: Hareket boyunca dirseklerini olabildiğince yakın tut. Ön kolların hep aşağıyı göstersin.', 'Triseps kaslarınla gövdeni yeniden yukarı iterek başlangıç pozisyonuna çık.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Bench_Jump', 'tr', array['Bir kasayı ya da sehpayı 1-2 fit önüne koy. Ayakların omuz genişliğinde dur. Bu senin başlangıç pozisyonun.', 'Sıçramaya hazırlanmak için hafifçe çömel ve kollarını geriye savur.', 'Bu pozisyondan yaylanarak çık: kalçanı, dizlerini ve ayak bileklerini açarak sıçrayabildiğin kadar yükseğe sıçra. Kollarını öne ve yukarı savur.', 'Sehpanın üzerinden atla ve dizlerin bükülü yere in, darbeyi bacaklarınla karşıla.', 'Arkanı dönüp ters yöne bak ve sehpanın üzerinden geri atla.']::text[]),
  ('Bench_Press_-_Powerlifting', 'tr', array['Sehpaya uzan, mümkünse başın barın ötesine geçsin. Ayaklarını altına doğru çek ve sırtına kavis ver. Bardan destek alarak omuzlarını sehpadan kaldır, geriye çek ve kürek kemiklerini birbirine sıkıştır. Ayaklarınla iterek trapez kaslarını sehpaya bastır. Bu sıkı vücut pozisyonunu hareket boyunca koru.', 'Tutuşun ne kadar geniş olursa olsun ellerin bardaki halka işaretini kapatmalı. Omuzlarını öne kaydırmadan barı askıdan çek. Barı sıkmaya ve iki yana ayırmaya çalışır gibi çekmeye odaklan.', 'Barı alt göğsüne ya da üst karnına indir. Bar, bilek ve dirsek her an aynı hizada kalsın.', 'Halter gövdene değince dur, sonra barı var gücünle yukarı it. Kolların kilitlenene kadar dirseklerin içe yakın kalsın.']::text[]),
  ('Bench_Press_-_With_Bands', 'tr', array['Düz bir sehpada, başına en yakın sehpa ayağının altına bir lastik bant sabitle.', 'Bant sağlamca oturunca iki tutamağı da al ve sehpaya uzan.', 'Kollarını uzat ve tutamakları önünde, omuz genişliğinde tut.', 'Omuz genişliğindeyken bileklerini öne çevir, avuç içlerin senden uzağa baksın. Bu senin başlangıç pozisyonun.', 'Tutamakları dirseklerin 90 derecelik açı yapana kadar yavaşça indir. Kontrolü hiçbir an bırakma.', 'Nefes ver ve tutamakları göğüs kaslarınla yukarı it. Yukarıda kollarını kilitle, göğsünü sık, bir saniye tut ve yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Hareketi antrenman programının belirlediği tekrar sayısı kadar yap.']::text[]),
  ('Bench_Press_with_Chains', 'tr', array['Kılavuz zinciri istediğin uzunluğa kısalt. Zincirleri barın plaka takılan uçlarına as.', 'Sehpaya uzan, mümkünse başın barın ötesine geçsin. Ayaklarını altına doğru çek ve sırtına kavis ver. Bardan destek alarak omuzlarını sehpadan kaldır, geriye çek ve kürek kemiklerini birbirine sıkıştır. Ayaklarınla iterek trapez kaslarını sehpaya bastır. Bu sıkı vücut pozisyonunu hareket boyunca koru. Tutuşun ne kadar geniş olursa olsun ellerin bardaki halka işaretini kapatmalı.', 'Omuzlarını öne kaydırmadan barı askıdan çek. Barı sıkmaya ve iki yana ayırmaya çalışır gibi çekmeye odaklan. Barı alt göğsüne ya da üst karnına indir. Bar, bilek ve dirsek her an aynı hizada kalsın.', 'Halter gövdene değince dur, sonra barı var gücünle yukarı it. Kolların kilitlenene kadar dirseklerin içe yakın kalsın.']::text[]),
  ('Bench_Sprint', 'tr', array['Yerde dur ve bir ayağını, topuğun kenara yakın olacak şekilde bir sehpanın ya da kasanın üzerine koy.', 'Sehpanın üzerindeki ayağınla it, kalçanı ve dizini aç.', 'Diğer ayağınla kasanın üzerine in, ilk ayağın ise yerdeki başlangıç yerine dönsün.', 'Seti bitirene kadar ayak değiştirmeyi sürdür.']::text[]),
  ('Bent-Arm_Barbell_Pullover', 'tr', array['Halteri omuz genişliğinde tut ve düz bir sehpaya uzan.', 'Barı kolların bükülü olarak göğsünün tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Kollarındaki bükülmeyi bozmadan, nefes alırken ağırlığı bir yay çizerek yavaşça başının arkasına indir; göğsünde gerilme hissedene kadar devam et.', 'O noktada nefes ver ve halteri indirdiğin yayın üzerinden başlangıç pozisyonuna geri getir.', 'Ağırlığı başlangıçta bir saniye tut, sonra hareketi belirlenen tekrar sayısı kadar yinele.']::text[]),
  ('Bent-Arm_Dumbbell_Pullover', 'tr', array['Bir dambılı düz bir sehpanın üstüne dik olarak koy.', 'Dambılın sehpanın üst ucunda sağlam durduğundan emin ol. Sonra sehpaya enine uzan; gövden sehpayla bir artı işareti oluştursun ve yalnızca omuzların sehpaya değsin. Kalçan sehpadan aşağıda, bacakların bükülü, ayakların yere sağlam basıyor olsun. Başın da sehpanın dışında kalır.', 'Dambılı iki elinle kavra ve kolların bükülü olarak göğsünün tam üstünde tut. İki avucun da dambılın bir ucundaki plakanın alt yüzüne bastırsın. Bu senin başlangıç pozisyonun. Dikkat: Bu egzersizde yalnızca sağlam takılmış bir dambıl kullan. Plakaları gevşek bir dambıl dağılıp yüzüne düşebilir.', 'Kollarını bükülü pozisyonda kilitle ve nefes alırken ağırlığı bir yay çizerek yavaşça başının arkasına indir; göğsünde gerilme hissedene kadar devam et.', 'O noktada nefes ver ve dambılı indirdiğin yayın üzerinden başlangıç pozisyonuna geri getir.', 'Ağırlığı başlangıçta bir saniye tut, sonra hareketi belirlenen tekrar sayısı kadar yinele.']::text[]),
  ('Bent-Knee_Hip_Raise', 'tr', array['Yere sırtüstü uzan, kolların vücudunun yanında dursun.', 'Dizlerini yaklaşık 75 derece bük ve ayaklarını yerden 2 inç kadar kaldır.', 'Bacaklarındaki 75 derecelik bükülmeyi koruyarak alt karın kaslarınla dizlerini kendine doğru çek. Leğen kemiğin geriye yuvarlanıp kalçan yerden kalkana kadar devam et. Bu bölümde nefes ver. İpucu: Hareketin sonunda dizlerin göğsünün üstünde olur.', 'En üstte karnını bir saniye sık, sonra nefes alırken yavaşça başlangıç pozisyonuna dön. İpucu: Hareketi her an kontrollü yap.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Bent_Over_Barbell_Row', 'tr', array['Halteri üstten tutuşla kavra, avuç içlerin aşağı baksın. Dizlerini hafifçe bük ve belinden bükülerek gövdeni öne eğ, sırtın düz kalsın, gövden yere neredeyse paralel olana kadar in. İpucu: Başını yukarıda tutmaya dikkat et. Halter tam önünde sarksın, kolların yere ve gövdene dik olsun. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut, nefes ver ve halteri kendine doğru çek. Dirseklerin vücuduna yakın kalsın, ön kolların yalnızca ağırlığı tutsun. En üstte sırt kaslarını sık ve kısa bir an bekle.', 'Sonra nefes al ve halteri yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'tr', array['Her elinde bir dambıl, önünde eğimli bir sehpa olacak şekilde dik dur.', 'Sırtını düz tutup doğal kavsini koruyarak alnın önündeki sehpaya değene kadar öne eğil. Kolların yere dik olarak önünde sarksın, avuç içlerin birbirine baksın. Gövden yere paralel olsun. Bu senin başlangıç pozisyonun.', 'Gövden öne eğik ve sabit, kolların dirseklerden hafifçe bükülü ama düz kalsın. Nefes ver ve dambılları iki kolun da yere paralel olana kadar dümdüz yana kaldır. Dikkat: Gövdeni sallama ve kollarını yana değil de geriye götürme.', 'Yukarıda kasılmayı bir saniye tut, sonra dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Bent_Over_Low-Pulley_Side_Lateral', 'tr', array['Bir ağırlık seç ve alt makaranın tutamağını sağ elinle tut.', 'Gövden yere neredeyse paralel olana kadar belinden öne eğil. Bacakların hafifçe bükülü olsun, sol elini sol üst bacağının alt kısmına koy. Sağ kolun omzundan önüne doğru sarksın, dirseğin hafifçe bükülü olsun. Bu senin başlangıç pozisyonun.', 'Nefes ver ve sağ kolunu, dirseğin hafifçe bükülü halde, yere paralel ve sağ kulağınla aynı hizada olana kadar yana kaldır.', 'Nefes al ve ağırlığı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla, sonra hareketi diğer kolunla tekrarla.']::text[]),
  ('Bent_Over_One-Arm_Long_Bar_Row', 'tr', array['Olimpik bir halterin bir ucuna ağırlık tak. Diğer ucunu iki duvarın birleştiği köşeye yerleştir ya da yere ağır bir cisim koy ki halter geriye kaymasın.', 'Gövden yere olabildiğince paralel olana kadar öne eğil, dizlerin hafifçe bükülü kalsın.', 'Şimdi barı tek elinle, ağırlık taktığın uçta plakaların hemen arkasından tut ve diğer elini dizine koy. Bu senin başlangıç pozisyonun.', 'Nefes ver ve barı dümdüz yukarı çek, plakalar alt göğsüne değene kadar. Sırtın en çok çalışsın diye dirseğin içte kalsın. Ağırlığı kaldırırken sırt kaslarını sık ve en üstte bir saniye tut. İpucu: Gövden hiç sallanmasın. Yalnızca kolun hareket etsin.', 'Barı yavaşça başlangıç pozisyonuna indir ve kanat kaslarında iyi bir esneme hisset. İpucu: Plakalar yere değmesin. En iyi hareket açıklığı için büyük plakalar (örneğin 35-45 lb) yerine küçük plakalar (25 lb) daha uygundur.', 'Önerilen tekrar sayısını tamamla ve kol değiştir.']::text[]),
  ('Bent_Over_Two-Arm_Long_Bar_Row', 'tr', array['Olimpik bir halterin bir ucuna ağırlık tak. Diğer ucunu iki duvarın birleştiği köşeye yerleştir ya da yere ağır bir cisim koy ki halter geriye kaymasın.', 'Gövden yere olabildiğince paralel olana kadar öne eğil, dizlerin hafifçe bükülü kalsın.', 'Şimdi barı iki elinle, ağırlık taktığın uçta plakaların hemen arkasından tut. Bu senin başlangıç pozisyonun.', 'Nefes ver ve barı dümdüz yukarı çek, plakalar alt göğsüne değene kadar. Sırtın en çok çalışsın diye dirseklerin içte kalsın. Ağırlığı kaldırırken sırt kaslarını sık ve en üstte bir saniye tut. İpucu: Kablo istasyonunun üzengi tutamağını ya da çift tutamaklı aparatını barın ucunun altına takıp oradan çekebilirsin.', 'Barı yavaşça başlangıç pozisyonuna indir ve kanat kaslarında iyi bir esneme hisset. İpucu: Plakalar yere değmesin. En iyi hareket açıklığı için büyük plakalar (örneğin 35-45 lb) yerine küçük plakalar (25 lb) daha uygundur.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Bent_Over_Two-Dumbbell_Row', 'tr', array['İki eline birer dambıl al, avuç içlerin gövdene baksın. Dizlerini hafifçe bük ve belden öne eğil; sırtını düz tutarak gövden yere neredeyse paralel olana kadar in. İpucu: Başını yukarıda tut. Kolların yere ve gövdene dik şekilde aşağı sarksın, dambıllar tam önünde dursun. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut ve nefes verirken dambılları yanlarına doğru çek. Dirseklerin vücuduna yakın kalsın; ön kolların ağırlığı tutmak dışında kuvvet uygulamasın. En üstte sırt kaslarını sık ve bir saniye bekle.', 'Nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'tr', array['İki eline birer dambıl al, avuç içlerin birbirine baksın. Dizlerini hafifçe bük ve belden öne eğil; sırtını düz tutarak gövden yere neredeyse paralel olana kadar in. İpucu: Başını yukarıda tut. Kolların yere ve gövdene dik şekilde aşağı sarksın, dambıllar tam önünde dursun. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut ve nefes verirken dambılları yanlarına doğru çek, kürek kemiklerini birbirine yaklaştır. En üstte sırt kaslarını sık ve bir saniye bekle.', 'Nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Bent_Press', 'tr', array['Kettlebell''i clean hareketiyle omzuna al: Bacaklarını ve kalçanı açarken kettlebell''i omzuna doğru kaldır, bu sırada bileğin dönsün. Bu senin başlangıç pozisyonun.', 'Kettlebell''in olmadığı tarafa doğru yana eğil ve boş elin yere değebilecek duruma gelene kadar devam et. Gözünü kettlebell''den ayırma. Eğilirken dirseğini açarak ağırlığı dik olarak yukarı it; kolun yere dik kalsın.', 'Kettlebell başının üstündeyken yeniden dikleş. Kettlebell''i omzuna indir ve istediğin tekrar sayısı kadar yinele.']::text[]),
  ('Bicycling', 'tr', array['Başlamak için bisiklete otur ve seleyi boyuna göre ayarla.']::text[]),
  ('Bicycling_Stationary', 'tr', array['Başlamak için bisiklete otur ve seleyi boyuna göre ayarla.', 'Menüden istediğin seçeneği seç. Cihazın açılması için pedal çevirmeye başlaman gerekebilir. Manuel ayarı kullanabilir ya da bir program seçebilirsin. Çoğu cihazda yaşını ve kilonu girerek egzersizde yaktığın kaloriyi tahmin ettirebilirsin. Direnç seviyesini antrenman boyunca değiştirebilirsin. Tutma kolları nabzını izlemene yarar; böylece uygun yoğunlukta kalırsın.']::text[]),
  ('Board_Press', 'tr', array['Sehpaya uzan; mümkünse başın barın ilerisine geçsin. 2x6 keresteden yapılmış bir ila beş tahta birbirine vidalanır. Tahtaları bir antrenman arkadaşın tutabilir, lastik bantla sabitleyebilir ya da tişörtünün altına sokabilirsin.', 'Ayaklarını altına doğru çek ve sırtını kavislendir. Ağırlığını bara vererek omuzlarını sehpadan kaldır ve geriye çek, kürek kemiklerini birbirine sıkıştır. Ayaklarınla iterek trapezini sehpaya bastır. Bu sıkı duruşu hareket boyunca koru.', 'Normal bench press tutuşuyla ya da trisepse yüklenmek için omuz genişliğinde tut. Omuzlarını öne kaydırmadan barı askıdan al. Bar, bilek ve dirsek her zaman aynı hizada kalsın. Barı sıkıca kavra ve iki yana ayırmaya çalışır gibi çek.', 'Barı tahtalara indir, sonra olabildiğince güçlü şekilde yukarı it. Kolların tam açılana kadar dirseklerin gövdene yakın kalsın.']::text[]),
  ('Body-Up', 'tr', array['Yerde plank pozisyonu al: Ağırlığını ayak parmakların ve ön kolların taşısın, gövden düz olsun. Ön kolların omuz genişliğinde açık dursun. Bu senin başlangıç pozisyonun.', 'Avuçlarını yere sıkıca bastır ve dirseklerini açarak vücudunu yukarı kaldır. Hareket sırasında gövden kaskatı kalsın.', 'Dirseklerini bükerek ön kollarını yavaşça yeniden yere indir.', 'Tekrarla.']::text[]),
  ('Body_Tricep_Press', 'tr', array['Bir barı askıya göğüs hizasında yerleştir.', 'Ayakta barı omuz genişliğinde tut ve bir iki yarda geri çekil. Ayakların bitişik, kolların düz olsun; bara yaslanmış olursun. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükerek gövdeni bara doğru indir.', 'Kısa bir an bekle, sonra dirseklerini açarak geri dön.', 'Vücut ağırlığı yetmemeye başlayınca omuzlarına zincir atarak zorlaştır.']::text[]),
  ('Bodyweight_Flyes', 'tr', array['Eşit ağırlık takılı iki EZ barı yere yan yana koy. Yuvarlanabildiklerinden emin ol.', 'Barların üstünde şınav pozisyonu al: Ağırlığın ayak parmaklarında ve ellerinde, kolların düz, vücudun dümdüz olsun.', 'Ellerini barların üstüne koy. Bu senin başlangıç pozisyonun.', 'Yavaş ve kontrollü bir hareketle ellerini vücudunun orta hattından dışa doğru kaydır, barlar birbirinden uzaklaşsın. Bu bölümde nefes al.', 'Barları açabildiğin kadar açtıktan sonra yeniden birbirine çekerek başlangıç pozisyonuna dön. Bunu yaparken nefes ver.']::text[]),
  ('Bodyweight_Mid_Row', 'tr', array['Barfiks demirini orta ya da geniş tutuşla kavra, avuç içlerin senden öteye baksın. Asılı dururken dizlerini göğsüne çek, geriye yaslan ve bacaklarını demirin kendi tarafına geçir. Bu senin başlangıç pozisyonun.', 'Kolların düzken başla. Dirseklerini bük ve kürek kemiklerini geriye çekerek vücudunu, bacakların demire değene kadar yukarı kaldır.', 'Kısa bir an bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Bodyweight_Squat', 'tr', array['Ayaklarını omuz genişliğinde açarak dur. Ellerini başının arkasına koyabilirsin. Bu senin başlangıç pozisyonun.', 'Dizlerini ve kalçanı bükerek harekete başla; kalçanı oturur gibi geriye ver.', 'Yapabiliyorsan en derine kadar in ve hızla geri dönerek başlangıç pozisyonuna çık. Çömelirken başını ve göğsünü yukarıda tut, dizlerini dışa doğru it.']::text[]),
  ('Bodyweight_Walking_Lunge', 'tr', array['Ayakların omuz genişliğinde açık, ellerin belinde olacak şekilde ayakta dur.', 'Bir bacağınla öne adım at ve dizlerini bükerek kalçanı indir. Arka dizin neredeyse yere değene kadar alçal. Gövden dik kalsın, ön dizin ön ayağının üstünde dursun.', 'Öndeki ayağının topuğundan it ve iki dizini de açarak yeniden yüksel.', 'Arka ayağınla öne adım at ve lunge''ı diğer bacakla yap.']::text[]),
  ('Bosu_Ball_Cable_Crunch_With_Side_Bends', 'tr', array['Kablo makinesinin her iki koluna standart birer tutamak tak ve makaraları en alt konuma getir.', 'Bir denge yarım topu al ve kablo makinesinin önüne, tam ortaya yerleştir.', 'Yarım topa, belin topun üstünde kavis yapacak şekilde uzan. Kalçan yere yakın olsun ama değmesin.', 'İki elinle geriye uzan ve kabloların tutamaklarını birer birer kavra.', 'Ayaklarını geniş aç, kollarını dizlerinin arasından öne doğru dümdüz uzat. Ellerin diz hizasında olsun.', 'Kollarını düz ve kablonun yukarı doğru açısıyla aynı hizada tut. Kollarını indirmeden ve bükmeden gövdeni crunch hareketiyle kaldır.', 'Kollarını gergin tutmayı sürdür. Sırtın yarım topun üstünde kavisli, karın kasların uzamış olarak yavaşça başlangıç pozisyonuna in.', 'Aynı hareket dizisini tükenene kadar tekrarla.', 'Tükendiğinde karnını sıkı tut ve gövdeni plank pozisyonuna kaldır; sırtın yarım toptan ayrılsın.', 'Kollarını düz tutarak yanlarına indir. Sırayla sağa ve sola yana eğilmeye başla, topuklarına uzan. Bu bitiriş hareketi yan karın kaslarını çalıştırır.']::text[]),
  ('Bottoms-Up_Clean_From_The_Hang_Position', 'tr', array['Egzersize bir elinde kettlebell ile dik durarak başla.', 'Kettlebell''i güçlü bir şekilde geriye savur, sonra hareketi aynı güçle tersine çevir. Kettlebell''in sapını olabildiğince sert sık ve kettlebell''i omzuna kaldır.']::text[]),
  ('Bottoms_Up', 'tr', array['Yere sırtüstü uzan. Bacakların düz, kolların yanında olsun. Bu senin başlangıç pozisyonun.', 'Kalçanı ve dizlerini bükerek dizlerini göğsüne doğru çek. Ardından bacaklarını yere dik olacak şekilde tam yukarı uzat. Leğen kemiğini döndürüp kaldırarak kalçanı yerden ayır.', 'Kısa bir an bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Box_Jump_Multiple_Response', 'tr', array['Kutunun ya da platformun karşısında, yaklaşık bir kol boyu uzakta rahat bir duruş al. Kolların yanlarında aşağıda, bacakların hafif bükülü olsun.', 'İlk hamlede kollarından destek alarak yukarı ve öne sıçra; iki ayağınla aynı anda kutunun ya da platformun üstüne in.', 'Hemen kendini bırak ya da geriye sıçrayarak başladığın yere dön, sonra diziyi tekrarla.']::text[]),
  ('Box_Skip', 'tr', array['Aralarında yaklaşık 8 feet olacak şekilde sıraya dizilmiş birkaç kutu gerekir.', 'İlk kutuya dönük dur, bir bacağın diğerinin biraz gerisinde olsun.', 'Arka bacağınla it ve kalçanla olabildiğince yükselmeye çalış.', 'Kutuya iner inmez diğer bacağını öne ve yukarı savurarak yükseklik ve mesafe kazan, kutudan sıçra. İlk iki kutunun arasına, ilk kutuya indiğin bacakla in.', 'Sonra bir adımla sıradaki kutuya geç ve tekrarla.']::text[]),
  ('Box_Squat', 'tr', array['Kutu, squat''ta istediğin derinliğe inmeni ve patlayıcı kuvvet geliştirmeni sağlar. Power rack içinde, arkanda uygun yükseklikte bir kutuyla başla. Genellikle üst bacakların yere paralel olduğu bir kutu yüksekliği seçilir, ama istersen daha yüksek ya da daha alçak da çalışabilirsin.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sıkıştır ve dirseklerini öne çevir; barı omuzlarının üstünde bükmeye çalışır gibi yap. Belinde sıkı bir kavis oluşturarak barı askıdan al ve geri adım atıp yerini al. Sırt, kalça, addüktörler ve arka bacağa daha çok yüklenmek için ayaklarını geniş, ön bacağı daha çok geliştirmek için dar aç. Başın öne baksın.', 'Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışa iterek inmeye başla. Kutuya oturana kadar kalçanı geriye ver. En iyisi kaval kemiklerinin yere dik olmasıdır. Kutuya ulaşınca dur ve kalça bükücü kaslarını gevşet. Kutudan asla sekerek kalkma.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve harekete başınla öncülük ederek kutudan yukarı doğru yüksel. Baştan ayağa sıkı kalarak yükselmeyi sürdür.']::text[]),
  ('Box_Squat_with_Bands', 'tr', array['Power rack içinde, arkanda uygun yükseklikte bir kutuyla başla. Lastik bantları barın plaka takılan uçlarına geçir ve uygun gerginlik oluşacak şekilde bant pimlerine, rack''e ya da dambıllara bağla. Dambıl kullanıyorsan yerinden oynamayacak şekilde sabitle. Dambılların kullandığın bantlar için yeterince ağır olduğundan da emin ol. Dambılları yerinde tutmak için üstlerine ek plaka koyabilirsin. Daha fazla gerginlik gerekirse yerdeki tabanı genişlet ya da bantları boğarak bağla. Genellikle üst bacakların yere paralel olduğu bir kutu yüksekliği seçilir, ama istersen daha yüksek ya da daha alçak da çalışabilirsin.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sıkıştır ve dirseklerini öne çevir; barı omuzlarının üstünde bükmeye çalışır gibi yap. Belinde sıkı bir kavis oluşturarak barı askıdan al ve geri adım atıp yerini al. Sırt, kalça, addüktörler ve arka bacağa daha çok yüklenmek için ayaklarını geniş, ön bacağı daha çok geliştirmek için dar aç. Başın öne baksın.', 'Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışa iterek inmeye başla. Kutuya oturana kadar kalçanı geriye ver. En iyisi kaval kemiklerinin yere dik olmasıdır. Kutuya ulaşınca dur ve kalça bükücü kaslarını gevşet. Kutudan asla sekerek kalkma.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve harekete başınla öncülük ederek kutudan yukarı doğru yüksel. Baştan ayağa sıkı kalarak yükselmeyi sürdür. Halteri askıya dikkatle geri koy.']::text[]),
  ('Box_Squat_with_Chains', 'tr', array['Power rack içinde, arkanda uygun yükseklikte bir kutuyla başla. Genellikle üst bacakların yere paralel olduğu bir kutu yüksekliği seçilir, ama istersen daha yüksek ya da daha alçak da çalışabilirsin.', 'Zincirleri kurmak için önce kılavuz zinciri barın plaka takılan uçlarına geçir. Ağır zinciri bir karabinayla tak. Kılavuz zincirin boyunu, hareketin en üst noktasında birkaç halka hâlâ yerde kalacak şekilde ayarla.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sıkıştır ve dirseklerini öne çevir; barı omuzlarının üstünde bükmeye çalışır gibi yap. Belinde sıkı bir kavis oluşturarak barı askıdan al ve geri adım atıp yerini al. Sırt, kalça, addüktörler ve arka bacağa daha çok yüklenmek için ayaklarını geniş, ön bacağı daha çok geliştirmek için dar aç. Başın öne baksın.', 'Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışa iterek inmeye başla. Kutuya oturana kadar kalçanı geriye ver. En iyisi kaval kemiklerinin yere dik olmasıdır. Kutuya ulaşınca dur ve kalça bükücü kaslarını gevşet. Kutudan asla sekerek kalkma.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve harekete başınla öncülük ederek kutudan yukarı doğru yüksel. Baştan ayağa sıkı kalarak yükselmeyi sürdür.']::text[]),
  ('Brachialis-SMR', 'tr', array['Yan yat ve üst kolunu foam roller''a daya. Üst kolun aşağı yukarı vücudunla aynı hizada olsun, bisepsin dış yanı foam roller''a bastırsın.', 'Kalçanı yerden kaldır; ağırlığını kolun ve ayakların taşısın. 10-30 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Bradford_Rocky_Presses', 'tr', array['Military press sehpasına otur ve barı omuz hizasında pronasyon tutuşuyla (avuç içleri öne bakar) tut. İpucu: Tutuşun omuz genişliğinden geniş olsun; halter aşağı indiğinde ön kolunla üst kolun arasında 90 derecelik bir açı oluşsun. Bu senin başlangıç pozisyonun.', 'Halteri doğru tutuşla kavradıktan sonra kollarını kilitleyerek barı başının üstüne kaldır.', 'Şimdi nefes alırken barı yavaşça başının arkasına indir.', 'Nefes verirken barı yeniden yukarı, başlangıç pozisyonuna kaldır.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir. Bu bir tekrardır.', 'Önerilen tekrar sayısını tamamlayana kadar bu şekilde dönüşümlü devam et.']::text[]),
  ('Butt-Ups', 'tr', array['Şınav pozisyonuna geç, ama dirseklerin yerde olsun ve ön kollarına dayan. Kolların 90 derecelik açıyla bükülü olmalı.', 'Sırtını dümdüz tutmak yerine hafifçe dışa doğru kamburlaştır.', 'Kalçanı tavana doğru kaldır; karnını sıkıca kasarak göğüs kafesinle kalçan arasındaki mesafeyi kapat. Sonunda yüksek bir köprü pozisyonuna gelmiş olursun. Bu bölümde nefes ver.', 'Nefes alırken yavaşça başlangıç pozisyonuna in. İpucu: Sırtının aşağı doğru çökmesine izin verme.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Butt_Lift_Bridge', 'tr', array['Yere sırtüstü uzan; ellerin yanında, dizlerin bükülü olsun. Ayaklarını yaklaşık omuz genişliğinde yerleştir. Bu senin başlangıç pozisyonun.', 'Ağırlıklı olarak topuklarından iterek kalçanı yerden kaldır, sırtın düz kalsın. Bu bölümde nefes ver ve en üstte bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.']::text[]),
  ('Butterfly', 'tr', array['Makineye otur, sırtın yastığa düz yaslansın.', 'Tutamakları kavra. İpucu: Üst kolların yere paralel olmalı; makineyi buna göre ayarla. Bu senin başlangıç pozisyonun.', 'Göğsünü ortada sıkarak tutamakları yavaşça birbirine yaklaştır. Bu bölümde nefes ver ve kasılmayı bir saniye tut.', 'Nefes alırken, göğüs kasların tam gerilene kadar yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cable_Chest_Press', 'tr', array['Ağırlığı uygun bir düzeye ayarla, otur ve tutamakları kavra. Üst kolların gövdenle yaklaşık 45 derece yapsın, başın ve göğsün yukarıda olsun. Dirseklerin 90 derece kadar bükülü olmalı. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak tutamakları tam önünde birbirine doğru it. Hareket boyunca kürek kemiklerini geride tut.', 'Kolların tam açıkken kısa bir an bekle, sonra kablolardaki gerginliği koruyarak başlangıç pozisyonuna dön.', 'Bu hareketi sırtını yastıktan ayırarak, yukarı ya da aşağı eğimle veya elleri sırayla kullanarak da yapabilirsin.']::text[]),
  ('Cable_Crossover', 'tr', array['Başlangıç pozisyonuna hazırlanmak için makaraları yüksek konuma (başının üstüne) al, kullanacağın direnci seç ve iki eline birer tutamak al.', 'İki makara arasındaki hayali düz çizginin önüne doğru bir adım at ve kollarını önünde birleştir. Gövden belden hafifçe öne eğik olsun. Bu senin başlangıç pozisyonun.', 'Biseps tendonunu zorlamamak için dirseklerini hafifçe bük. Kollarını geniş bir yay çizerek iki yana dümdüz aç; göğsünde gerilme hissedene kadar devam et. Bu bölümde nefes al. İpucu: Hareket boyunca kolların ve gövden sabit kalmalı; hareket yalnızca omuz ekleminden gelmeli.', 'Nefes verirken kollarını başlangıç pozisyonuna geri getir. Açarken izlediğin yayın aynısını kullan.', 'Başlangıç pozisyonunda bir saniye bekle ve hareketi belirlenen tekrar sayısı kadar yinele.']::text[]),
  ('Cable_Crunch', 'tr', array['İp aparatı takılı yüksek bir makaranın altında diz çök.', 'İp aparatını kavra ve ellerin yüzünün yanına gelene kadar aşağı çek.', 'Kalçanı hafifçe bük ve ağırlığın belini aşırı kavislendirmesine izin ver. Bu senin başlangıç pozisyonun.', 'Kalçan sabitken karnını kasarak belden bükül; dirseklerin üst bacaklarının ortasına doğru gitsin. Bu bölümde nefes ver ve kasılmayı bir saniye tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön. İpucu: Hareket boyunca karın kaslarındaki gerginliği hiç bırakma. Ayrıca işin çoğunu belin yapacağı kadar ağır bir yük seçme.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cable_Deadlifts', 'tr', array['Kabloları kulelerin en altına indir ve uygun bir ağırlık seç. İki direğin tam ortasında dur.', 'Başlamak için kalçanı ve dizlerini bükerek tutamaklara uzanabileceğin kadar çömel.', 'Tutamakları kavradıktan sonra yükselmeye başla. Topuklarından iterek kalçanı ve dizlerini aç, ellerin yanlarında sarksın. Hareket boyunca başını ve göğsünü yukarıda tut.', 'Tam dik duruşa geldikten sonra başlangıç pozisyonuna dön ve tekrarla.']::text[]),
  ('Cable_Hammer_Curls_-_Rope_Attachment', 'tr', array['Alçak makaraya ip aparatı tak ve yüzün makineye dönük, yaklaşık 12 inç uzağında dur.', 'İpi nötr tutuşla (avuç içleri içe bakar) kavra ve dik dur; sırtının doğal kavsini koru, gövdeni sabit tut.', 'Dirseklerini yanlarına yapıştır ve hareket boyunca orada sabit tut. İpucu: Yalnızca ön kolların hareket etmeli, üst kolların değil. Bu senin başlangıç pozisyonun.', 'Nefes verirken biseps kaslarınla kollarını yukarı çek; bisepsin ön koluna değene kadar devam et. İpucu: Dirseklerini içeride, üst kollarını sabit tutmayı unutma.', 'Bisepsini sıkarak 1 saniye kasılı kal, sonra ağırlığı yavaşça ilk konumuna indirmeye başla.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cable_Hip_Adduction', 'tr', array['Alçak bir makaranın yanında yüzün öne dönük dur; bir bacağın makaranın yanında, diğeri uzakta olsun.', 'Ayak bilekliğini kabloya ve makaranın yanındaki bacağının bileğine tak.', 'Şimdi ağırlık bloğundan uzaklaşarak geniş bir duruş al ve makara sisteminin tutunma barını kavra.', 'Bileklik takılı olmayan ayağının (uzaktaki ayak) üstünde dur ve bileklikli bacağının alçak makaraya doğru çekilmesine izin ver. Bu senin başlangıç pozisyonun.', 'Şimdi iç bacak kaslarını kullanarak bileklikli bacağını uzaktaki bacağının önünden geçir. Bu bölümde nefes ver.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap, sonra aynı hareketi diğer bacakla yinele.']::text[]),
  ('Cable_Incline_Pushdown', 'tr', array['Düz bar aparatı takılı yüksek makaralı bir makineye sırtın dönük olacak şekilde eğimli sehpaya uzan.', 'Düz barı başının üstünden, omuz genişliğinde pronasyon tutuşuyla (üstten; avuç içleri aşağı bakar) kavra ve kollarını önüne doğru uzat. Bar üst bacaklarından 2 inç kadar uzakta olsun. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tutarak kollarını yarım daire çizerek geriye kaldır; bar tam başının üstüne gelene kadar devam et. Bu bölümde nefes al.', 'Kanat kaslarını kullanarak yavaşça başlangıç pozisyonuna dön ve oraya varınca kasılmayı tut. Bu hareketi yaparken nefes ver.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cable_Incline_Triceps_Extension', 'tr', array['Düz bar aparatı takılı yüksek makaralı bir makineye sırtın dönük olacak şekilde eğimli sehpaya uzan.', 'Düz barı başının üstünden, dar (omuz genişliğinden dar) pronasyon tutuşuyla (üstten; avuç içleri aşağı bakar) kavra ve dirseklerini yanlarına yakın tut. Üst kolların yere göre yaklaşık 25 derecelik bir açı yapmalı.', 'Üst kollarını sabit tutarak triseps kaslarını kas ve kollarını aç. Bu bölümde nefes ver ve kasılmayı bir saniye tut.', 'Yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cable_Internal_Rotation', 'tr', array['Alçak bir makaranın yanına yan dönerek otur (bacakların öne uzanmış ya da bağdaş kurmuş olabilir) ve tek el tutamağını kabloya yakın kolunla kavra. İpucu: Makaranın yüksekliği ayarlanabiliyorsa bunun yerine düz bir sehpaya oturabilirsin.', 'Dirseğini 90° bükülü olarak yanına daya, ön kolun makarayı göstersin. Bu senin başlangıç pozisyonun.', 'Omzunu içe döndürerek tutamağı vücuduna doğru çek; ön kolun karnının önüne gelene kadar devam et. Elin hayali bir yarım daire çizer. İpucu: Ön kolun her an gövdene dik olmalı.', 'Yavaşça ilk pozisyona dön.', 'Önerilen tekrar sayısı kadar yap, sonra hareketi diğer kolla yinele.']::text[]),
  ('Cable_Iron_Cross', 'tr', array['Önce makaraları yüksek konuma al, kullanacağın direnci seç ve iki eline birer tutamak al.', 'İki makaranın tam ortasında, kolların yanlara açık olarak dur. Başın ve göğsün yukarıda olsun, kolların bir T harfi oluştursun. Bu senin başlangıç pozisyonun.', 'Dirseklerini düz tutarak kollarını dosdoğru yanlarına çek.', 'Kasılmanın en güçlü olduğu noktada kısa bir an bekle, sonra kollarını başlangıç pozisyonuna geri götür.', 'Hareketi belirlenen tekrar sayısı kadar sürdür.']::text[]),
  ('Cable_Judo_Flip', 'tr', array['Bir kablo kulesine ip aparatı tak ve makarayı en alt konuma getir. Kabloya yan dönüp ayaklarını geniş açarak dur ve ipi iki elinle kavra.', 'Gövdeni makaradan öteye doğru döndür ve judoda rakibini omzundan atar gibi ipi omzunun üstünden geçir.', 'Dönüp öne doğru kıvrılırken ağırlığını bir ayağından diğerine aktar ve kabloyu aşağı çek.', 'Başlangıç pozisyonuna dön ve tükenene kadar tekrarla.', 'Sonra yerini değiştir ve aynı hareket dizisini diğer tarafta yap.']::text[]),
  ('Cable_Lying_Triceps_Extension', 'tr', array['Düz sehpaya uzan ve alt makaraya bağlı düz barı dar bir üstten tutuşla kavra. İpucu: En kolayı, sen uzandıktan sonra birinin barı sana vermesidir.', 'Kollarını uzat ve barı gövdenin üzerine getir. Kolların ile gövden arasında 90 derecelik bir açı olsun. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükerek barı indir; üst kolların sabit, dirseklerin içeride kalsın. Bar alnına hafifçe değene kadar in. Bu sırada nefes al.', 'Trisepsini sıkarak barı başlangıç pozisyonuna geri kaldır. Bu sırada nefes ver.', 'Kasılı pozisyonda bir saniye bekle ve önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Cable_One_Arm_Tricep_Extension', 'tr', array['Ağırlık bloğunun tam önünde dur ve üst makaraya bağlı tekli tutamağı sağ elinle alttan tutuşla (supine; avuç içi yukarı bakar) kavra.', 'Tutamağı aşağı çek; üst kolun ve dirseğin gövdenin yanına sabitlensin. Üst kolun ile ön kolun arasında dar bir açı (90 dereceden küçük) olsun. Diğer kolunu belinde tutabilir, daha iyi denge için bir bacağını öne, diğerini geriye alabilirsin. Bu senin başlangıç pozisyonun.', 'Trisepsini kasarak tutamağı, kolun düzleşene kadar yanına doğru indir. Bu sırada nefes ver. İpucu: Yalnızca ön kol hareket etsin. Üst kol hep sabit kalsın.', 'Trisepsini sık ve bu kasılı pozisyonda bir saniye kal.', 'Tutamağı yavaşça başlangıç pozisyonuna döndür.', 'Önerilen tekrar sayısını tamamla, sonra aynı hareketi diğer kolunla yap.']::text[]),
  ('Cable_Preacher_Curl', 'tr', array['Scott sehpasını kablo makinesinin yaklaşık 2 feet önüne yerleştir.', 'Alt makaraya düz bir bar tak.', 'Scott sehpasına otur, dirseklerini ve üst kollarını yastığın üstüne sıkıca yerleştir ve birinden alt makaradaki barı sana vermesini iste.', 'Barı kavra ve kollarını yastığın üzerinde tamamen uzat. Bu senin başlangıç pozisyonun.', 'Şimdi ağırlığı omuzlarına doğru çek ve hareketin tepesinde bisepsini güçlü biçimde sık. Çekerken nefes ver. Tepede ayrıca bir saniye bekle.', 'Ağırlığı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Cable_Rear_Delt_Fly', 'tr', array['Makaraları uygun yüksekliğe getir ve ağırlığı ayarla. Makaralar başının üstünde olmalı.', 'Sol makarayı sağ elinle, sağ makarayı sol elinle tut; kablolar önünde çaprazlansın. Bu senin başlangıç pozisyonun.', 'Harekete kollarını geriye ve dışa doğru açarak başla; hareket boyunca kolların düz kalsın.', 'Hareketin sonunda kısa bir an dur, sonra tutamakları başlangıç pozisyonuna geri getir.']::text[]),
  ('Cable_Reverse_Crunch', 'tr', array['Alt makara kablosuna bir ayak bileği bandı tak ve önüne yere bir mat ser.', 'Ayakların makaraya dönük olacak şekilde otur ve kabloyu ayak bileklerine bağla.', 'Sırtüstü uzan, bacaklarını kaldır ve dizlerini 90 derece bük. Bacakların ile kablo aynı hizada olmalı. Değilse hizalanana kadar makarayı yukarı ya da aşağı al.', 'Ellerini başının arkasına koy, dizlerini gövdene doğru çek ve kalçanı yerden kaldır.', 'Kısa bir an dur, sonra kalçanı yavaş ve kontrollü biçimde indir, bacaklarını baştaki 90 derecelik açıya geri getir. Dinlenme pozisyonunda da karın kaslarında gerginlik kalmalı.', 'Aynı hareketi tükenene kadar tekrarla.']::text[]),
  ('Cable_Rope_Overhead_Triceps_Extension', 'tr', array['Kablo makinesinin alt makarasına bir halat tak.', 'Halatı iki elinle nötr tutuşla (avuç içleri birbirine bakar) kavra ve ellerin başının tam üstüne gelecek şekilde kollarını uzat. Dirseklerin başına yakın dursun, kolların yere dik olsun, parmak eklemlerin tavanı göstersin. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tutarak halatı yavaşça başının arkasına indir. Bu sırada nefes al ve trisepsin tamamen gerildiğinde dur.', 'Nefes verirken trisepsini kasarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Cable_Rope_Rear-Delt_Rows', 'tr', array['Alt makaralı kürek istasyonuna, sırt için oturarak kablo kürek çekerken oturduğun gibi otur.', 'Makaraya bir halat tak ve üstten tutuşla kavra. Kolların uzanmış ve yere paralel, dirseklerin dışa açık olsun.', 'Belini dik tut ve dizlerin hafifçe bükülene kadar kalçanı geriye kaydır. Bu senin başlangıç pozisyonun.', 'Halatı üst göğsüne, boynunun hemen altına doğru çek; dirseklerin yukarıda ve yanlara açık kalsın. Nefes vererek dirseklerin sırtının biraz gerisine geçene kadar çekmeyi sürdür. İpucu: Hareket boyunca üst kolların yatay, gövdeye dik ve yere paralel kalsın.', 'Kolların uzanmış, omuzların öne doğru gerilmiş olduğu ilk pozisyona dön. Bu sırada nefes al.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Cable_Russian_Twists', 'tr', array['Standart bir tutamak tak ve makarayı orta yüksekliğe ayarla.', 'Pilates topuna kabloya dik gelecek şekilde uzan ve tutamağı tek elinle tut. Makaradan yaklaşık bir kol boyu uzakta ol; ağırlık kabloyu gergin tutsun.', 'Tutamağı iki elinle kavra ve kollarını göğsünün üzerinde tamamen uzat. Ellerin makarayla tam aynı hizada olmalı. Değilse hizalanana kadar makarayı yukarı ya da aşağı al.', 'Kalçanı yukarıda, karnını sıkı tut. Gövdeni makaradan uzağa doğru tam bir çeyrek tur döndür. Vücudun baştan dizlere kadar düz olmalı.', 'Kısa bir an dur, sonra yavaş ve kontrollü biçimde başlangıç pozisyonuna dön. Dinlenme pozisyonunda da kablo yandan çekmeye devam etmeli.', 'Aynı hareketi tükenene kadar tekrarla.', 'Sonra yerini değiştir ve aynı hareket dizisini diğer tarafta yap.']::text[]),
  ('Cable_Seated_Crunch', 'tr', array['Sırtın üst makaraya dönük olacak şekilde düz sehpaya otur.', 'Halatı iki elinle (avuç içleri birbirine bakar) kavra ve ellerini iki omzunun üzerinde sıkıca tut. İpucu: Ağırlığın belini hafifçe geriye doğru germesine izin ver. Bu senin başlangıç pozisyonun.', 'Kalçanı sabit tut ve belinden bükül; dirseklerin kalçana doğru gitsin. Bu sırada nefes ver.', 'Nefes alırken yavaşça ilk pozisyona dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Cable_Seated_Lateral_Raise', 'tr', array['Karşılıklı duran iki alt makaranın ortasında dur ve hemen arkana, sana dik gelecek şekilde bir düz sehpa koy; sehpanın dar kenarı arkanda olsun. Her makara için ağırlığı seç.', 'Arkandaki sehpanın ucuna otur; ayakların dizlerinin önünde dursun.', 'Sırtını düz tutarak öne eğil ve gövdeni uyluklarına yasla.', 'Birinden makaralara bağlı tekli tutamakları sana vermesini iste. Ağırlığı seçtikten sonra sol makarayı sağ elinle, sağ makarayı sol elinle tut. Kablolar dizlerinin altından geçsin; kolların uzanmış, avuç içlerin birbirine dönük, dirseklerin hafif bükük olsun. Bu başlangıç pozisyonu.', 'Kollarının duruşunu bozmadan üst kollarını yanlara doğru, yere paralel ve omuz hizasına gelene kadar kaldır. Hareket sırasında nefes ver ve kasılmayı bir saniye tut.', 'Nefes alırken kollarını yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar tekrarla. İpucu: Egzersiz boyunca üst kollarını gövdene dik, dirseklerini de sabit bir açıda (10 ila 30 derece) tut.']::text[]),
  ('Cable_Shoulder_Press', 'tr', array['Makaraları kulelerin en altına indir ve uygun bir ağırlık seç.', 'İki kulenin tam ortasında dur. Tutamakları kavra ve avuç içlerin öne bakacak şekilde omuz hizasında tut. Bu senin başlangıç pozisyonun.', 'Başını ve göğsünü dik tut, dirseklerini açarak tutamakları dümdüz başının üstüne it.', 'Tepede kısa bir an durduktan sonra başlangıç pozisyonuna dön ve tekrarla.']::text[]),
  ('Cable_Shrugs', 'tr', array['Alt makaraya bağlı barı omuz genişliğinde ya da biraz daha geniş, üstten tutuşla (avuç içleri aşağı bakar) kavra.', 'Makaranın yakınında dik dur; barı, kolların önünde uzanmış halde tut. Bu senin başlangıç pozisyonun.', 'Nefes verirken omuzlarını olabildiğince yukarı çekerek barı kaldır. Tepede kasılmayı bir saniye tut. İpucu: Kolların hep düz kalsın. Barı kaldırmak için bisepsinden yardım alma. Yalnızca omuzların yukarı aşağı hareket etsin.', 'Barı ilk pozisyona geri indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Cable_Wrist_Curl', 'tr', array['Önce, düz bar takılı bir alt makaranın önüne düz bir sehpa yerleştir.', 'Barı dar ile omuz genişliği arasında, alttan tutuşla (avuç içleri yukarı) kavra ve ön kolların uyluklarının üstüne yaslanacak şekilde kaldır. Bileklerin dizlerinin hemen ötesinde sarkmalı.', 'Nefes vererek bileklerini yukarı doğru bükerek başla. Kasılmayı bir saniye tut.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir.', 'Ön kolların sabit kalsın; bu egzersizde hareket etmesi gereken tek yer bileklerin.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Calf-Machine_Shoulder_Shrug', 'tr', array['Baldır makinesine, omuz yastıkları omuzlarının üstüne gelecek şekilde yerleş. Gövden düz, kolların yanlarında doğal biçimde uzanmış olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken omuzlarını kulaklarına doğru kaldır ve kasılmayı tam bir saniye tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Calf_Press', 'tr', array['Koltuğu, başlangıçta bacakların yalnızca hafifçe bükük olacak şekilde ayarla. Ayak parmak köklerin platforma sağlam bassın.', 'Uygun bir ağırlık seç ve tutamakları kavra. Bu senin başlangıç pozisyonun.', 'Dizlerini açarak bacaklarını düzleştir; ağırlık bloktan ancak azıcık kalksın. Ayak bileğin tamamen bükülü, parmak uçların yukarı dönük olmalı. Hareketi, ayak parmak köklerinle olabildiğince aşağı doğru iterek yap.', 'Kısa bir duraklamadan sonra hareketi tersine çevir ve tekrarla.']::text[]),
  ('Calf_Press_On_The_Leg_Press_Machine', 'tr', array['Leg press makinesine otur ve ayaklarını tam önündeki platforma orta genişlikte (omuz genişliğinde) yerleştir.', 'Ağırlıklı platformu yerinde tutan emniyet kollarını aç ve platformu, bacakların dizlerini kilitlemeden önünde tamamen uzanana kadar yukarı it. Not: Bazı leg press makinelerinde daha fazla güvenlik için emniyet kollarını takılı bırakabilirsin. Makinen buna izin veriyorsa egzersizi bu şekilde yapman tercih edilir. Gövden ile bacakların tam 90 derecelik bir açı yapmalı. Şimdi parmak uçlarını ve ayak parmak köklerini dikkatle platformun alt kısmına yerleştir; topukların dışarıda kalsın. Parmak uçların öne, dışa ya da içe bakabilir. Bu senin başlangıç pozisyonun.', 'Nefes verirken topuklarını kaldırarak platformu it: ayak bileklerini olabildiğince yükseğe uzat ve baldırını kas. Dizlerin her zaman sabit kalsın, hiçbir an bükülmesin. Aşağı inmeye başlamadan önce kasılı pozisyonu bir saniye tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön: ayak bileklerini bükerek topuklarını baldırların gerilene kadar indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Calf_Raise_On_A_Dumbbell', 'tr', array['Denge için sağlam bir yere tutun ve bir dambılın sapına bas. Mümkünse yuvarlak plakalı bir dambıl seç; yuvarlandığı için dengeni sağlamak için daha çok çalışırsın, bu da egzersizi daha etkili kılar.', 'Şimdi ayağını hafifçe öne yuvarla; baldırın iyice gerilsin. Bu senin başlangıç pozisyonun.', 'Ayağını sapın üstünden yuvarlarken baldırınla yüksel ve tam uzanmaya ulaş. Hareket sırasında nefes ver. Tepede baldırını güçlü biçimde kas ve bir saniye bekle. İpucu: Yükselirken dambılı hafifçe geriye yuvarla.', 'Şimdi nefes al ve inerken daha iyi gerilmek için dambılı hafifçe öne yuvarla.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Calf_Raises_-_With_Bands', 'tr', array['Bir lastik bant al ve parmak uçlarınla üzerine bas; bandın ayak ile kol arasındaki uzunluğu iki tarafta da aynı olsun.', 'Bandın tutamaklarını tutarken kollarını, omuz press yapmaya hazırlanır gibi başının yanlarına kaldır. Avuç içlerin öne baksın, dirseklerin bükük ve yanlara açık olsun. Bu hareket bandı gerer. Bu senin başlangıç pozisyonun.', 'Ellerini omuzlarının yanında tutarak nefes verirken parmak uçlarında yüksel ve tepede baldırlarını güçlü biçimde kas.', 'Bir saniye kasılı kaldıktan sonra yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Calf_Stretch_Elbows_Against_Wall', 'tr', array['Bir duvarın birkaç feet uzağında, yüzün duvara dönük dur.', 'Duvara yaslan ve ağırlığını ön kollarına ver.', 'Topuklarını yerde tutmaya çalış. 10-20 saniye bekle. Duvardan uzaklaşırsan hareket zorlaşır, yaklaşırsan kolaylaşır.']::text[]),
  ('Calf_Stretch_Hands_Against_Wall', 'tr', array['Bir duvarın birkaç feet uzağında, yüzün duvara dönük dur. Bir ayağını öne alarak adımlı bir duruşa geç.', 'Öne eğil ve ellerini duvara daya; topuğun, kalçan ve başın düz bir çizgide olsun.', 'Topuğunu yerde tutmaya çalış. 10-20 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Calves-SMR', 'tr', array['Yere otur ve alt bacağının altına bir foam roller yerleştir. Diğer bacağını bunun üstüne atabilir ya da yere basıp ağırlığının bir kısmını ona verebilirsin. Bu senin başlangıç pozisyonun.', 'Ellerini yanına ya da hemen arkana koy ve yere bastırarak kalçanı kaldır; ağırlığının büyük kısmı baldır kasına binsin. Dizin altından ayak bileğinin üstüne kadar yuvarlan, gergin noktalarda 10-30 saniye dur. Diğer bacak için tekrarla.']::text[]),
  ('Car_Deadlift', 'tr', array['Bu yarışma düzeneğinde genellikle nötr tutuşlu kollar bulunur; bazılarında ise normal deadlift gibi kaldırabileceğin düz bir bar vardır. Düzenek bir araçla ya da traktör lastiği, fıçı gibi başka ağır nesnelerle yüklenebilir.', 'Squat''ın güçlüyse kolların tam ortasında, deadlift''in güçlüyse birkaç inç geride dur. Ayakların yaklaşık kalça genişliğinde açık olsun. Kolları kavramak için kalçadan eğil. Ayakların ve tutuşun hazır olunca derin bir nefes al, sonra kalçanı indir ve dizlerini bük.', 'Başın dik, ileriye bak; göğsünü yukarıda, sırtını kavisli tut ve topuklarından iterek ağırlığı kaldırmaya başla. Ağırlık yükselirken kürek kemiklerini birbirine çek ve kalçanı öne it.', 'Ağırlığı indirmek için kalçadan eğil ve onu yere kadar yönlendir.']::text[]),
  ('Car_Drivers', 'tr', array['Ayakta dik dururken bir halter plakasını iki elinle saat 3 ve 9 konumlarından tut. Avuç içlerin birbirine baksın, kolların önünde dümdüz uzansın. Bu senin başlangıç pozisyonun.', 'Harekete plakayı bir yana olabildiğince çevirerek başla; direksiyonu bir yana kırar gibi çevir.', 'Hareketi tersine çevir ve plakayı karşı yana sonuna kadar döndür.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Carioca_Quick_Step', 'tr', array['Ayakların birkaç inç açık, sol kolun rahat ve atletik bir duruşta yukarıda olacak şekilde başla.', 'Sağ ayağınla arkadan hızlı bir adım at ve dizini yukarı çek.', 'Sağ dizini çekerken kollarını hızla yeniden yukarı savur; dizinin dümdüz yukarı ve aşağı gittiğinden emin ol. Hareket ederken ayaklarını döndürme ve yana doğru ilerlerken ileriye bakmayı sürdür.']::text[]),
  ('Cat_Stretch', 'tr', array['Yerde ellerinin ve dizlerinin üzerine gel.', 'Karnını içeri çek; omurganı, belini, omuzlarını ve boynunu yuvarla, başını serbest bırak.', '15 saniye bekle.']::text[]),
  ('Catch_and_Overhead_Throw', 'tr', array['Bir duvara ya da bir partnere dönük, ayakta dur.', 'Topu iki elinle başının arkasına götür, olabildiğince geril ve topu güçlü biçimde öne fırlat.', 'Atışı sonuna kadar tamamla ve geri seken topu karşılamaya hazır ol. Duvara atıyorsan seken topu yakalayabileceğin kadar yakın dur ve partnerle çalışırken nişan alacağın yerden biraz daha yükseğe nişan al.']::text[]),
  ('Chain_Handle_Extension', 'tr', array['Bu egzersiz için iki kablo tutamağı, düz bir sehpa ve zincirler gerekir. Zincirleri ortalarından tutamaklara tak ve düz sehpaya uzan. Dirseklerin dümdüz yukarıyı göstersin.', 'Üst kolunu sabit, bileklerini pronasyonda tutarak dirseklerini açmaya başla.', 'Kolların tam açıldığında dur ve hareketi tersine çevirerek başlangıç pozisyonuna dön.']::text[]),
  ('Chain_Press', 'tr', array['Önce zincirleri kablo tutamaklarına bağla. Düz sehpaya dambıl press''teki gibi uzan. Bileklerin pronasyonda, kolların yere dik olsun. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükerek zincirleri indir; zincirin bir kısmı yere binsin.', 'Dirseğin 90 derecelik açı yapana kadar devam et, sonra dirseklerini tam açılana kadar düzleştirerek hareketi tersine çevir.']::text[]),
  ('Chair_Leg_Extended_Stretch', 'tr', array['Bir sandalyede dik otur ve oturma yerini yanlarından tut.', 'Bir bacağını kaldır; kaldırırken dizini düzleştir ve ayak bileğini bük.', 'O bacağını yavaşça, gidebildiği kadar dışa aç, sonra ortaya geri getir ve indir.', 'Diğer bacağınla tekrarla.']::text[]),
  ('Chair_Lower_Back_Stretch', 'tr', array['Bir sandalyeye dik otur.', 'Kolunu başının üzerinden uzatarak bir yana eğil. Boştaki elinle sandalyeye tutunabilirsin.', '10 saniye bekle ve diğer tarafta tekrarla.']::text[]),
  ('Chair_Squat', 'tr', array['Başlamak için önce barı boyuna en uygun konuma ayarla. Bar yüklendikten sonra altına gir ve onu omuzlarının arkasına yerleştir.', 'Barı avuç içlerin öne bakacak şekilde tut, kilidini aç ve bacaklarını düzleştirerek askıdan kaldır.', 'Ayaklarını barın yaklaşık 18 inç önüne al. Bacaklarını omuz genişliğinde aç, parmak uçların hafifçe dışa baksın. Hep ileriye bak ve omurganı nötr ya da hafif kavisli tut. Bu senin başlangıç pozisyonun.', 'Duruşunu dik, başını yukarıda tutarak dizlerini bük ve barı yavaşça indir. Üst bacak ile alt bacak arasındaki açı 90 derecenin altına inene kadar devam et.', 'Nefes verirken barı kaldırmaya başla: topuklarınla yeri it, dizlerini düzleştir ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Chair_Upper_Body_Stretch', 'tr', array['Bir sandalyenin ucuna otur ve arkalığını kavra.', 'Sırtını düz tutarak kollarını düzleştir ve bir gerilme hissedene kadar üst gövdeni öne çek. 20-30 saniye bekle.']::text[]),
  ('Chest_And_Front_Of_Shoulder_Stretch', 'tr', array['Bacakların bitişik, elinde bir egzersiz çubuğu ya da süpürge sapıyla ayakta dur.', 'Çubuğu omuz genişliğinden biraz daha geniş tut ve avuç içlerin aşağı bakacak şekilde önünde taşı.', 'Çubuğu dikkatle yukarı kaldır ve başının arkasına götür.']::text[]),
  ('Chest_Push_from_3_point_stance', 'tr', array['Üç nokta duruşunda başla: çömel, sırtın düz, bir elin yerde olsun. Sağlık topunu tam önüne koy.', 'İlk adımını atarken topu göğsüne çek ve iki elini atışa hazır konuma getir.', 'İkinci adımı atarken topu patlayıcı biçimde, olabildiğince sert öne fırlat.']::text[]),
  ('Chest_Push_multiple_response', 'tr', array['Bir duvara dönük diz çök ya da bir partnerle çalış. Topu iki elinle göğsüne sıkıca bastırarak tut.', 'Pası, kalçanı patlayıcı biçimde öne ve dışa sürerken topu olabildiğince sert iterek at.', 'Hareketi öne doğru düşerek tamamla ve ellerinle kendini karşıla.', 'Hemen dik pozisyona dön. İstediğin tekrar sayısı kadar tekrarla.']::text[]),
  ('Chest_Push_single_response', 'tr', array['Diz çök ve sağlık topunu iki elinle göğsüne sıkıca bastırarak tut.', 'Pası, kalçanı patlayıcı biçimde öne ve dışa sürerken topu olabildiğince uzağa iterek at.', 'Hareketi öne doğru düşerek tamamla ve ellerinle kendini karşıla.']::text[]),
  ('Chest_Push_with_Run_Release', 'tr', array['Atletik duruşta başla: dizler bükük, kalça geride, sırt düz. Sağlık topunu bacaklarının yakınında tut. Bu senin başlangıç pozisyonun.', 'İlk adımını atarken sağlık topunu göğsüne çek.', 'İkinci adımda topu patlayıcı biçimde öne it ve bırakır bırakmaz 10 yard sprint at. Gerçekten hızlıysan kendi pasını yakalayabilirsin!']::text[]),
  ('Chest_Stretch_on_Stability_Ball', 'tr', array['Bir pilates topunun yanında ellerinin ve dizlerinin üzerine gel.', 'Dirseğini topun üstüne koy; kolun yana açık dursun. Bu senin başlangıç pozisyonun.', 'Dirseğin topun üstünde kalırken gövdeni yere doğru indir. Germeyi 20-30 saniye tut ve diğer kolunla tekrarla.']::text[]),
  ('Childs_Pose', 'tr', array['Ellerinin ve dizlerinin üzerine gel, ellerini öne doğru yürüt.', 'Kalçanı indirip topuklarının üzerine otur. Geriye otururken kollarının yerde sürüklenmesine izin ver; böylece bütün omurgan gerilir.', 'Topuklarına yerleşince ellerini ayaklarının yanına getir ve gevşe. Sırtına doğru "nefes al". Alnını yere daya. Diz sorunun varsa bu pozisyondan kaçın.']::text[]),
  ('Chin-Up', 'tr', array['Barfiks barını avuç içlerin gövdene bakacak şekilde, omuz genişliğinden dar bir tutuşla kavra.', 'Seçtiğin tutuş genişliğinde barı tutarak iki kolun uzanmış halde asıl. Gövdeni olabildiğince düz tut, belinde bir kavis oluştur ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun. İpucu: Gövdeyi olabildiğince düz tutmak bisepsi en çok, sırtı en az çalıştırır.', 'Nefes verirken başın yaklaşık bar hizasına gelene kadar gövdeni yukarı çek. Hareketi biseps kaslarınla yapmaya odaklan. Dirseklerin vücuduna yakın kalsın. İpucu: Üst gövden yükselirken kendi içinde sabit kalsın, yalnızca kolların hareket etsin. Ön kolların barı tutmaktan başka iş yapmasın.', 'Kasılı pozisyonda bisepsini bir saniye sıktıktan sonra gövdeni yavaşça, kolların tamamen uzandığı başlangıç pozisyonuna indir. Bu sırada nefes al.', 'Bu hareketi belirlenen tekrar sayısı kadar tekrarla.']::text[]),
  ('Chin_To_Chest_Stretch', 'tr', array['Yere otur.', 'İki elini başının arkasına koy; parmakların kenetli, başparmakların aşağıya, dirseklerin dümdüz ileriye baksın. Başını yavaşça göğsüne doğru çek. 20-30 saniye bekle.']::text[]),
  ('Circus_Bell', 'tr', array['Circus bell, kalın saplı, çok büyük bir dambıldır. Dambıl ayaklarının arasındayken başla ve sapı iki elinle kavra.', 'Kalçanı ve dizlerini açarak dambılı istediğin omza al (clean); bu sırada diğer elini bırak.', 'Dengeni kaybetmemek için dambıl başlarından birinin omzunun arkasına geçtiğinden emin ol. Başının üstüne kaldırmak için dizlerini bükerek hafifçe çök, sonra yukarı doğru it ve dambılı başının üstüne uzat; bunu yaparken ondan hafifçe uzağa yaslan.', 'Dambılı olabildiğince kontrol altında tutarak dikkatle yere geri indir. Zemine zarar vermemek için bu hareketi kalın bir kauçuk matın üzerinde yapmak en iyisidir.']::text[]),
  ('Clean', 'tr', array['Halter yerde, kaval kemiklerine yakınken bacaklarının hemen dışından üstten tutuşla (ya da kanca tutuşla) kavra. Ağırlığın topuklarında, sırtın düz, başın öne dönük, göğsün yukarıda ve omuzların barın biraz önünde olacak şekilde kalçanı indir. Bu senin başlangıç pozisyonun.', 'İlk çekişe topuklarından iterek ve dizlerini açarak başla. Sırtının açısı aynı kalsın, kolların düz dursun. Ağırlığı kontrollü biçimde dizlerinin üstüne kadar taşı.', 'Sırada ikinci çekiş var; clean''in asıl ivme kaynağı budur. Bar uyluğun ortasına yaklaşırken kalçanı açmaya başla. Zıplar gibi bir hareketle kalçanı, dizlerini ve ayak bileklerini açarak hızlan ve barı bu hızla yukarı taşı. Ağırlığı hızlandırmak için kollarınla ayrıca çekmen gerekmemeli: ikinci çekişin sonunda vücudun tamamen uzanmış ve hafifçe geriye yaslanmış, kolların hâlâ düz olmalı.', 'Tam uzanmaya ulaşınca üçüncü çekişe geç: omuzlarını sertçe silk ve dirseklerin yukarıda ve dışa açık olacak şekilde kollarını bük. Uzanmanın en üst noktasında kendini sertçe aşağı çek ve bu sırada dirseklerini barın altına döndür. Barı ön squat pozisyonunda karşıla; ne kadar derin olacağı, üçüncü çekişin sonunda barın yüksekliğine bağlıdır. Bar öne çıkmış omuzlarına otursun, boğazına hafifçe değsin, ellerin gevşek olsun. Squat''ın en alt pozisyonuna kadar inmeye devam et; bu, toparlanmana yardım eder.', 'Gövden dik, dirseklerin yukarıda, topuklarından iterek hemen toparlan. Ayakta dik duruncaya kadar devam et.']::text[]),
  ('Clean_Deadlift', 'tr', array['Halter kaval kemiklerine yakınken ayakta dur. Ayakların tam kalçanın altında ve hafifçe dışa dönük olsun. Barı yaklaşık omuz genişliğinde, iki elinle üstten tutuşla ya da kanca tutuşuyla kavra. Bara doğru çömel. Omurgan tamamen düz ve gergin olsun; sırtının açısı omuzlarını barın önüne getirsin, sırtın da olabildiğince dik dursun.', 'Topuklarının ön kısmıyla yeri iterek başla. Bar yukarı çıkarken sırtının açısını aynı tut. Dizlerini yanlara aç ki barın yolunda durmasınlar.', 'Bar dizlerini geçince kaldırışı tamamla: kalçan ve dizlerin düz olana kadar kalçanı bara doğru it.']::text[]),
  ('Clean_Pull', 'tr', array['Halter yerde, kaval kemiklerine yakın dursun. Barı bacaklarının hemen dışından üstten tutuşla ya da kanca tutuşuyla kavra. Kalçanı indir ve ağırlığını topuklarına ver. Sırtın düz, başın karşıya dönük, göğsün yukarıda olsun; omuzların barın biraz önünde dursun. Bu senin başlangıç pozisyonun.', 'İlk çekişe başla: topuklarından güç al ve dizlerini aç. Sırtının açısı değişmesin, kolların düz kalsın ve dirseklerin dışa baksın. Ağırlığı kontrollü biçimde dizlerinin üstüne kadar getir.', 'Şimdi ikinci çekiş geliyor; clean hızının çoğunu buradan alır. Bar uyluğun ortasına yaklaşınca kalçanı açmaya başla. Zıplar gibi hızlan: kalçanı, dizlerini ve ayak bileklerini aç, barı bu hızla yukarı taşı. Ağırlığı hızlandırmak için kollarınla ayrıca çekmen gerekmemeli. İkinci çekişin sonunda vücudun tamamen açılmış ve hafifçe geriye yatmış, kolların ise hâlâ düz olmalı. Tam açılma sert ve ani olsun; onu gereğinden uzun sürdürme.']::text[]),
  ('Clean_Shrug', 'tr', array['Barı omuz genişliğinde, iki elinle üstten tutuşla ya da kanca tutuşuyla kavra; bar uyluğunun ortası hizasında asılı dursun. Sırtın düz ve hafifçe öne eğik olsun.', 'Omuzlarını kulaklarına doğru silk. Bu harekete çoğunlukla clean''den daha fazla ağırlık takabilirsin, ama hareketi yavaşlatacak kadar yükleme.']::text[]),
  ('Clean_and_Jerk', 'tr', array['Halter yerde, kaval kemiklerine yakın dursun. Barı bacaklarının hemen dışından üstten tutuşla ya da kanca tutuşuyla kavra. Kalçanı indir ve ağırlığını topuklarına ver. Sırtın düz, başın karşıya dönük, göğsün yukarıda olsun; omuzların barın biraz önünde dursun. Bu senin başlangıç pozisyonun.', 'İlk çekişe başla: topuklarından güç al ve dizlerini aç. Sırtının açısı değişmesin, kolların düz kalsın. Ağırlığı kontrollü biçimde dizlerinin üstüne kadar getir.', 'Şimdi ikinci çekiş geliyor; clean hızının çoğunu buradan alır. Bar uyluğun ortasına yaklaşınca kalçanı açmaya başla. Zıplar gibi hızlan: kalçanı, dizlerini ve ayak bileklerini aç, barı bu hızla yukarı taşı. Ağırlığı hızlandırmak için kollarınla ayrıca çekmen gerekmemeli. İkinci çekişin sonunda vücudun tamamen açılmış ve hafifçe geriye yatmış, kolların ise hâlâ düz olmalı.', 'Tam açıldığın anda üçüncü çekişe geç: omuzlarını sertçe silk ve kollarını bük, dirseklerin yukarı ve dışa baksın. Açılmanın en yüksek noktasında kendini sertçe aşağı çek ve bu sırada dirseklerini barın altına döndür. Barı önde squat pozisyonunda karşıla; ne kadar derine ineceğin, üçüncü çekişin sonunda barın ne kadar yükseldiğine bağlıdır. Barı öne itilmiş omuzlarına yerleştir, boğazına hafifçe değsin, ellerin gevşek olsun. Squatın en alt noktasına kadar inmeye devam et; bu, kalkışı kolaylaştırır.', 'Hemen kalk: topuklarından it, gövdeni dik, dirseklerini yukarıda tut. Ayakta dik durana kadar devam et.', 'İkinci aşama jerk''tir; ağırlığı başının üstüne çıkarır. Bar omuzlarının ön tarafında dururken ayaktasın ve hafif bir çöküşle başlarsın. Ayaklarını tam kalçanın altına al ve dizlerini bük, ama kalçanı geriye götürme. Yalnızca biraz in ve hareketi olabildiğince güçlü biçimde tersine çevir.', 'Topuklarından it ve olabildiğince çok hız ve kuvvet üret. Bar omuzlarından ayrılırken başını mutlaka yolundan çek.', 'Ayakların yerden kesildiği anda onları olabildiğince çabuk karşılama pozisyonuna getir. Ayakların platformu itmediği o kısa anda, barı yukarı itme çaban seni aşağı iter. Ayaklarını bir öne bir arkaya aç. Barı başının üstünde, kolların kilitli olarak karşıla. Ayakta duruşa dön.']::text[]),
  ('Clean_and_Press', 'tr', array['Ayaklarını omuz genişliğinde aç, dizlerin kollarının arasında kalsın. Sırtını düz tut ve dizlerinle kalçanı, barı kolların tamamen düzken tutabileceğin kadar bük; barı omuz genişliğinden biraz geniş, üstten tutuşla kavra. Dirseklerini yanlara çevir. Bar kaval kemiklerine yakın olsun. Omuzlarını barın üstüne ya da biraz önüne getir. Sırtını düz konuma sabitle. Bu senin başlangıç pozisyonun.', 'Dizlerini açarak barı çekmeye başla. Kalçanı öne getir ve omuzlarını aynı hızda kaldır ki sırtının açısı değişmesin. Barı vücuduna yakın tutarak dümdüz yukarı kaldırmaya devam et.', 'Bar dizini geçince ayak bileklerini, dizlerini ve kalçanı zıplar gibi güçle aç. Bu sırada barı ellerinle yönlendirmeyi sürdür: omuzlarını silk ve hareketin ivmesinden yararlanarak barı olabildiğince yükseğe çek. Bar vücuduna yakın ilerlesin, dirseklerin dışa baksın.', 'En yüksek noktada ayakların yerden kesilmeli ve kendini barın altına çekmeye başlamalısın. Bunun nasıl olacağı, kullandığın ağırlığa göre biraz değişebilir. Kendini barın altına çekerken squat pozisyonuna in.', 'Bar en yüksek noktasına varınca dirseklerini barın çevresinden dolaştırıp altına döndür. Barı omuzlarının ön tarafına yerleştir, gövdeni dik tut ve barın ağırlığını karşılamak için kalçanı ve dizlerini bük.', 'Barı clean pozisyonunda tutarak tamamen doğrul.', 'Ayaklarını oynatmadan nefes ver ve barı başının üstüne it. Barı kontrollü biçimde indir.']::text[]),
  ('Clean_from_Blocks', 'tr', array['Halter istediğin yükseklikteki kasaların ya da sehpaların üstünde dursun. Barı bacaklarının hemen dışından üstten tutuşla ya da kanca tutuşuyla kavra. Kalçanı indir ve ağırlığını topuklarına ver. Sırtın düz, başın karşıya dönük, göğsün yukarıda olsun; omuzların barın biraz önünde dursun. Bu senin başlangıç pozisyonun.', 'İlk çekişe başla: topuklarından güç al ve dizlerini aç. Sırtının açısı değişmesin, kolların düz kalsın ve dirseklerin dışa baksın.', 'Tam açıldığın anda karşılama pozisyonuna geç: omuzlarını sertçe silk ve kollarını bük, dirseklerin yukarı ve dışa baksın. Kendini sertçe aşağı çek ve bu sırada dirseklerini barın altına döndür. Barı önde squat pozisyonunda karşıla; ne kadar derine ineceğin, üçüncü çekişin sonunda barın ne kadar yükseldiğine bağlıdır. Barı öne itilmiş omuzlarına yerleştir, boğazına hafifçe değsin, ellerin gevşek olsun. Squatın en alt noktasına kadar inmeye devam et; bu, kalkışı kolaylaştırır.', 'Hemen kalk: topuklarından it, gövdeni dik, dirseklerini yukarıda tut. Ayakta dik durana kadar devam et. Sonraki tekrar için ağırlığı kasalara geri koy.']::text[]),
  ('Clock_Push-Up', 'tr', array['Yerde yüzüstü pozisyona geç ve ağırlığını ellerinle ayak parmaklarının üstünde taşı.', 'Kollarını tamamen düzleştir, ellerin yaklaşık omuz genişliğinde olsun. Hareket boyunca vücudunu düz tut. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükerek in ve göğsünü yere yaklaştır.', 'En altta hareketi tersine çevir: dirseklerini açarak kendini olabildiğince hızlı it ve yerden havalan. Bir yana doğru 12-18 inç "zıplamaya" çalış.', 'Yukarı doğru hızlanırken dış ayağını gittiğin yönden uzağa taşı. Yerden ayrılırken sonraki tekrar için vücudunu yaklaşık 30 derece çevir.', 'Başlangıç pozisyonuna dön ve hareketi tekrarla. Başladığın noktaya gelene kadar tam bir tur dön.']::text[]),
  ('Close-Grip_Barbell_Bench_Press', 'tr', array['Düz bir sehpaya sırtüstü uzan. Barı dar tutuşla, yaklaşık omuz genişliğinde kavra, askıdan kaldır ve kolların kilitli halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes al ve barı göğsünün ortasına değene kadar yavaşça indir. İpucu: Normal bench press''ten farklı olarak dirseklerini her zaman gövdene yakın tut; böylece triseps en çok çalışır.', 'Bir saniye bekle, sonra nefes ver ve barı triseps kaslarınla iterek başlangıç pozisyonuna getir. Yukarıda kollarını kilitle, bir saniye tut ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Bitirince barı askıya geri koy.']::text[]),
  ('Close-Grip_Dumbbell_Press', 'tr', array['Bir dambılı düz sehpanın üstüne dik koy.', 'Dambılın sehpanın üstünde sağlam durduğundan emin ol. Sehpaya dik açıyla, yalnızca omuzların yüzeyde olacak şekilde uzan. Kalçan sehpadan aşağıda, bacakların bükülü, ayakların yere sağlam basıyor olsun.', 'Dambılı iki elinle kavra ve kolların uzanmış halde tam göğsünün üstünde tut. İki avucun da dambılın yanlarına alttan bastırsın. Bu senin başlangıç pozisyonun.', 'Harekete dambılı göğsüne indirerek başla.', 'Dirseklerini açarak başlangıç pozisyonuna dön.']::text[]),
  ('Close-Grip_EZ-Bar_Curl_with_Band', 'tr', array['Barın iki ucuna birer bant tak. Barı al ve bir ayağınla bandın ortasına bas. Dik dur ve EZ barı dar, alttan tutuşla kavra. Dirseklerin gövdene yakın olsun. Bu senin başlangıç pozisyonun.', 'Üst kollarını yerinde tut ve curl için dirseklerini bük. Ağırlığı kaldırırken nefes ver.', 'Bisepsin tamamen kasılana ve bar omuz hizasına gelene kadar devam et. Orada bir saniye kal ve bisepsini sıkıca sık.', 'Nefes al ve barı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Close-Grip_EZ-Bar_Press', 'tr', array['EZ bara uygun bir ağırlık tak ve onunla düz bir sehpaya uzan.', 'Barı dar tutuşla kaldır ve dirseklerin içte olacak şekilde tam gövdenin üstünde tut. Kolların yere dik olsun. Bu senin başlangıç pozisyonun.', 'Nefes al ve barı alt göğsüne indir. Hareket boyunca dirseklerini içte tut.', 'Nefes ver ve barı trisepsinle yukarı it: dirseklerini açarak başlangıç pozisyonuna dön.', 'Tekrarla.']::text[]),
  ('Close-Grip_EZ_Bar_Curl', 'tr', array['Gövden dik halde ayakta dur ve EZ barı içteki dar tutuş yerlerinden kavra. Avuçların öne baksın; barın biçimi yüzünden hafifçe içe eğik olurlar. Dirseklerin gövdene yakın olsun. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve bisepsini kasarak ağırlığı öne doğru kaldır. İpucu: Yalnızca ön kolların hareket etmeli.', 'Bisepsin tamamen kasılana ve bar omuz hizasına gelene kadar devam et. Orada bir saniye kal ve bisepsini sıkıca sık.', 'Nefes al ve barı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Close-Grip_Front_Lat_Pulldown', 'tr', array['Üst makarasına geniş bar takılı bir lat pulldown makinesine otur. Makinenin diz yastığını boyuna göre ayarla. Bu yastıklar, bardaki direncin vücudunu kaldırmasını engeller.', 'Barı avuçların öne bakacak şekilde, belirlenen tutuşla kavra. Tutuşlar üzerine not: Geniş tutuşta ellerin omuz genişliğinden daha açık olmalı. Orta tutuşta omuz genişliğinde, dar tutuşta ise omuz genişliğinden dar olmalı.', 'İki kolun önünde uzanmış ve barı seçtiğin tutuş genişliğinde tutarken gövdeni yaklaşık 30 derece geriye yatır, belini çukurlaştır ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun.', 'Nefes ver ve barı üst göğsüne değene kadar indir; bunun için omuzlarını ve üst kollarını aşağı ve geriye çek. İpucu: Tam kasılı pozisyona gelince sırt kaslarını sıkmaya odaklan. Üst gövden sabit kalmalı, yalnızca kolların hareket etmeli. Ön kolların barı tutmaktan başka iş yapmamalı; bu yüzden barı ön kollarınla çekmeye çalışma.', 'Kürek kemiklerini birbirine sıkarak kasılı pozisyonda bir saniye kal. Sonra barı yavaşça başlangıç pozisyonuna bırak; orada kolların tamamen uzanmış, kanat kasların tamamen gerilmiş olur. Hareketin bu bölümünde nefes al.', 'Bu hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Close-Grip_Push-Up_off_of_a_Dumbbell', 'tr', array['Yere uzan ve ellerini dik duran bir dambılın üstüne koy. Ağırlığını ayak parmaklarınla ellerinde taşı; gövden sert, dirseklerin içte, kolların düz olsun. Bu senin başlangıç pozisyonun.', 'Nefes al ve dirseklerinin bükülmesine izin vererek vücudunu indir. Vücudun düz kalsın; kalçan ne yükselsin ne sarksın.', 'Dirseklerini açarak kendini başlangıç pozisyonuna geri it. Bu adımda nefes ver.', 'Kasılı pozisyonda kısa bir süre bekle, sonra hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Close-Grip_Standing_Barbell_Curl', 'tr', array['Halteri iki elinle, avuçların yukarı bakacak ve aralarında birkaç inç olacak şekilde tut.', 'Gövden düz, başın yukarıda ayakta dur. Ayakların yaklaşık omuz genişliğinde, dirseklerin gövdene yakın olsun. Bu senin başlangıç pozisyonun. İpucu: Hareket boyunca üst kolların ve dirseklerin sabit kalır.', 'Barı, ön kolların bisepsine değene kadar yarım daire çizerek yukarı kaldır. Hareketin bu bölümünde nefes ver ve en üstte bisepsini bir saniye sıkıca kas. İpucu: Ağırlığı kaldırırken sırtını bükme ve sallanma. Yalnızca ön kolların hareket etmeli.', 'Nefes al ve yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cocoons', 'tr', array['Yere sırtüstü uzan. Bacakların düz, kolların başının gerisine uzanmış olsun. Bu senin başlangıç pozisyonun.', 'Hareket için dizlerini göğsüne çek ve leğen kemiğini döndürerek kalçanı yerden kaldır. Bu sırada omurganı yuvarla ve kollarını başının üstünden öne getir; böylece aynı anda bir crunch yaparsın.', 'Kısa bir süre bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Conans_Wheel', 'tr', array['Ağırlık takılınca aletin ucunu zercher tutuşuyla al. Barı dirseklerinin iç kıvrımına yerleştir ve bileğini tut. Ağırlığın ön kollarına binmemesine çalış.', 'Önce ağırlığı yerden kaldır. Kısa ve hızlı adımlarla yürümeye başlarken vücudunu sıkı ve dik tut. Daire çizerek dönerken yukarıya ve uzağa bak. Bu disiplin sırasında nefesini tutma. Bir ya da daha fazla tam tur tamamlayana kadar yürümeye devam et.']::text[]),
  ('Concentration_Curls', 'tr', array['Düz bir sehpaya otur; önünde, bacaklarının arasında bir dambıl olsun. Bacakların açık, dizlerin bükülü, ayakların yerde olsun.', 'Dambılı sağ kolunla al. Sağ üst kolunun arkasını sağ uyluğunun iç tarafının üstüne yasla. Avucunu, uyluğundan uzağa, öne bakana kadar çevir. İpucu: Kolun uzanmış, dambıl da yerden yukarıda olmalı. Bu senin başlangıç pozisyonun.', 'Üst kolunu sabit tut, nefes ver ve bisepsini kasarak ağırlığı öne doğru kaldır. Yalnızca ön kolun hareket etmeli. Bisepsin tamamen kasılana ve dambıl omuz hizasına gelene kadar devam et. İpucu: Hareketin en üstünde serçe parmağının başparmağından yukarıda olmasına dikkat et. Bu, iyi bir kasılma sağlar. Kasılı pozisyonda bir saniye kal ve bisepsini sık.', 'Nefes al ve dambılı yavaşça başlangıç pozisyonuna indir. Dikkat: Hiçbir anda sallanma.', 'Önerilen tekrar sayısı kadar yap. Sonra hareketi sol kolunla tekrarla.']::text[]),
  ('Cross-Body_Crunch', 'tr', array['Sırtüstü dümdüz uzan ve dizlerini yaklaşık 60 derece bük.', 'Ayak tabanlarını yere bas ve ellerini gevşekçe başının arkasına koy. Bu senin başlangıç pozisyonun.', 'Şimdi gövdeni yuvarlayarak kalk ve sağ dirseğinle sağ omzunu vücudunun karşı tarafına götür; aynı anda sol dizini sol omzuna doğru çek. Dirseğinle uzan ve dizine değmeye çalış. Bu hareket sırasında nefes ver. İpucu: Yalnızca dirseğini değil, omzunu dizine doğru getirmeye çalış. Önemli olan dirseği oynatmak değil, hareket boyunca karın kaslarını kasmaktır.', 'Nefes al ve başlangıç pozisyonuna in. Sonra sol dirseğin ve sağ dizinle tekrarla.', 'Belirlenen bütün tekrarlar bitene kadar bu şekilde sırayla devam et.']::text[]),
  ('Cross_Body_Hammer_Curl', 'tr', array['Her elinde bir dambılla dik dur. Ellerin yanlarında aşağıda, avuçların içe dönük olsun.', 'Avuçların içe dönük kalsın ve kolunu çevirme. Nefes ver ve sağ elindeki dambılı sol omzuna doğru kaldır. Dambılın üst ucunu omzuna değdir ve kasılmayı bir saniye tut.', 'Nefes al ve dambılı aynı yoldan yavaşça indir. Sonra aynı hareketi sol kolunla yap.', 'Her kol önerilen tekrar sayısını tamamlayana kadar bu şekilde sırayla devam et.']::text[]),
  ('Cross_Over_-_With_Bands', 'tr', array['Bir egzersiz bandını sabit bir direğe bağla.', 'Sırtını direğe dön, bandın iki ucundaki tutamakları kavra ve bant gerilene kadar öne adım at.', 'Kollarını yanlara, yere paralel ve gövdene dik olacak şekilde kaldır; gövden ve kolların "T" harfine benzesin. Avuçların öne baksın. Kolların uzanmış, dirseklerin hafifçe bükülü olsun. Bu senin başlangıç pozisyonun.', 'Kollarını düz tut, nefes ver ve göğüs kaslarını kasarak kollarını yarım daire çizerek öne, göğsünün önüne getir. Kasılmayı bir saniye tut.', 'Nefes al ve yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Crossover_Reverse_Lunge', 'tr', array['Ayakların omuz genişliğinde açık dur. Bu senin başlangıç pozisyonun.', 'Geriye lunge yap: bir ayağını geriye at ve kalçanla öndeki dizini bük. Bu sırada gövdeni öndeki bacağının üstüne doğru çevir.', 'Kısa bir süre bekle, başlangıç pozisyonuna dön ve diğer tarafta tekrarla. Sırayla devam et.']::text[]),
  ('Crucifix', 'tr', array['Crucifix''te ağırlıkları süreye karşı yanlarda hareketsiz tutarsın. Bu disiplini dambılla çalışabilirsin, ama en iyisi balta ve çekiç gibi gerçekten kullanılan aletlerden biriyle çalışmaktır, çünkü hissi farklıdır.', 'Ayakta başla ve aletler elindeyken kollarını yanlara kaldır. Kolların yere paralel olsun. Yarışmada paralelin altına düştüğünü hakemler ya da sensörler bildirir. Tutabildiğin kadar uzun tut. Genelde ağırlıklar, 30-60 saniyede tükeneceğin kadar ağır olmalı.']::text[]),
  ('Crunch_-_Hands_Overhead', 'tr', array['Sırtın düz halde yere uzan ve dizlerini, arka bacak ile baldır arasında yaklaşık 60 derecelik açı olacak şekilde bük.', 'Ayak tabanlarını yere bas ve kollarını, avuçların üst üste çapraz halde başının üstüne uzat. Bu senin başlangıç pozisyonun.', 'Üst gövdeni öne doğru yuvarla ve kürek kemiklerini yerden biraz kaldır. Kollarını her zaman başın, boynun ve omuzlarınla aynı hizada tut. Onları bu hizadan öne götürme. Hareketin bu bölümünde nefes ver ve kasılmayı bir saniye tut.', 'Nefes al ve yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Crunch_-_Legs_On_Exercise_Ball', 'tr', array['Sırtüstü dümdüz uzan, ayaklarını bir pilates topunun üstüne koy ve dizlerini 90 derece bük.', 'Ayaklarını üç dört inç aralıkla yerleştir ve parmak uçlarını birbirine değecek şekilde içe çevir.', 'Ellerini hafifçe başının iki yanına koy ve dirseklerini içte tut. İpucu: Parmaklarını başının arkasında kenetleme.', 'Karın kaslarını daha iyi izole etmek için belinin çukurunu yere bastır. Bu senin başlangıç pozisyonun.', 'Omuzlarını yerden yuvarlayarak kaldırmaya başla ve belini olabildiğince güçlü biçimde yere bastırmayı sürdür. Omuzların yerden yalnızca dört inç kadar kalkmalı, belin yerde kalmalı. Hareketin bu bölümünde nefes ver. Kasılmanın en üstünde karın kaslarını sıkıca sık ve bir saniye tut. İpucu: Yavaş ve kontrollü harekete odaklan. Hiçbir anda ivmeden yararlanma.', 'Nefes al ve yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Crunches', 'tr', array['Sırtüstü dümdüz uzan; ayakların ya yere bassın ya da dizlerin 90 derece bükülü halde bir sehpanın üstünde dursun. Ayakların sehpadaysa onları üç dört inç aralıkla yerleştir ve parmak uçlarını birbirine değecek şekilde içe çevir.', 'Şimdi ellerini hafifçe başının iki yanına koy ve dirseklerini içte tut. İpucu: Parmaklarını başının arkasında kenetleme.', 'Karın kaslarını daha iyi izole etmek için belinin çukurunu yere bastır ve omuzlarını yerden yuvarlayarak kaldırmaya başla.', 'Karın kaslarını kasıp nefes verirken belini olabildiğince güçlü biçimde yere bastırmayı sürdür. Omuzların yerden yalnızca dört inç kadar kalkmalı, belin yerde kalmalı. Hareketin en üstünde karın kaslarını sıkıca kas ve kasılmayı bir saniye tut. İpucu: Yavaş ve kontrollü harekete odaklan - ivme kullanarak kendini kandırma.', 'Bir saniyelik kasılmadan sonra nefes al ve yeniden yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Cuban_Press', 'tr', array['Ayakta dur ve her eline üstten tutuşla bir dambıl al. Üst kollarını yere paralel olana kadar kaldır, ön kolların "korkuluk" pozisyonunda aşağı sarksın. Bu senin başlangıç pozisyonun.', 'Harekete başlamak için omuzlarını dışa döndür; kol 180 derece dönsün. Üst kollarını yerinde tut ve bileklerin tam dirseklerinin üstüne gelene, ön kolların yere dik olana kadar döndür.', 'Şimdi dambılları yukarı it: dirseklerini aç ve kollarını başının üstünde düzleştir.', 'Nefes al ve adımları tersten yaparak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Dancers_Stretch', 'tr', array['Yerde dik otur.', 'Sağ bacağını, dizin bükülü halde sol bacağının üstünden çaprazla. Sol bacağın düz ve yerde kalsın.', 'Sol kolunu sağ bacağına, sağ elini yere koy.', 'Üst gövdeni sağa çevir ve 10-20 saniye tut. Taraf değiştir.']::text[]),
  ('Dead_Bug', 'tr', array['Sırtüstü uzan ve ellerini yukarı, tavana doğru uzat.', 'Ayaklarını, dizlerini ve kalçanı 90 dereceye getir.', 'Göğüs kafesini indirmek ve sırtını yere yapıştırmak için güçlü bir nefes ver; leğen kemiğini yukarı döndür ve kalça kaslarını sık. Hareket boyunca bu pozisyonu koru. Bu senin başlangıç pozisyonun.', 'Egzersize bir bacağını uzatarak başla: dizini ve kalçanı aç, bacağın yerin hemen üstüne gelsin.', 'Hareket sırasında belinin ve leğen kemiğinin konumunu koru, çünkü sırtın kavis yapmak isteyecek.', 'Sıkı kal ve çalışan bacağını başlangıç pozisyonuna geri getir.', 'Karşı tarafta tekrarla ve set bitene kadar sırayla devam et.']::text[]),
  ('Deadlift_with_Bands', 'tr', array['Kısa bantlarla deadlift için başlamadan önce bantları barın üstünden geçir ve yerini alırken içlerine bas. Uzun bantların ağır dambıllar ya da bir rack gibi sağlam bir yere sabitlenmesi gerekir.', 'Ayakların ve tutuşun hazır olunca derin bir nefes al, sonra kalçanı indir ve kaval kemiklerin bara değene kadar dizlerini bük. Karşıya bak, göğsünü yukarıda ve sırtını kavisli tut, ağırlığı yukarı taşımak için topuklarından itmeye başla. Bar dizlerini geçince barı sertçe geriye çek: kalçanı öne, bara doğru iterken kürek kemiklerini birbirine yaklaştır.', 'Barı indirmek için kalçadan bükül ve barı yere kadar yönlendir.']::text[]),
  ('Deadlift_with_Chains', 'tr', array['Zincirleri barın kovanlarına tak ya da ortalarından barın üstüne at; böylece kaldırdıkça ağırlık daha çok artar.', 'Bara, ayaklarının tam ortasının üstünde kalacak şekilde yaklaş. Ayakların yaklaşık kalça genişliğinde olsun. Kalçadan bükül ve barı omuz genişliğinde kavra; kürek kemiklerinin öne kaymasına izin ver. Genelde üstten tutuş, ağır setlerde ise bir el üstten bir el alttan karışık tutuş kullanılır. Ayakların ve tutuşun hazır olunca derin bir nefes al, sonra kalçanı indir ve kaval kemiklerin bara değene kadar dizlerini bük.', 'Karşıya bak, göğsünü yukarıda ve sırtını kavisli tut, ağırlığı yukarı taşımak için topuklarından itmeye başla. Bar dizlerini geçince barı sertçe geriye çek: kalçanı öne, bara doğru iterken kürek kemiklerini birbirine yaklaştır.', 'Barı indirmek için kalçadan bükül ve barı yere kadar yönlendir.']::text[]),
  ('Decline_Barbell_Bench_Press', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve yavaşça sehpaya uzan.', 'Barı orta genişlikte tut; yani hareketin ortasında ön kolların ile üst kolların arasında 90 derecelik açı oluşacak şekilde. Barı askıdan al ve kolların kilitli halde tam üstünde tut. Kolların yere dik olsun. Bu senin başlangıç pozisyonun. İpucu: Rotator manşetini korumak için halteri askıdan alırken bir yardımcıdan destek iste.', 'Nefes alırken barı alt göğsünde hissedene kadar yavaşça indir.', 'Bir saniye bekle, sonra nefes verirken barı göğüs kaslarınla iterek başlangıç pozisyonuna getir. Kollarını kilitle, yukarıda göğsünü bir saniye sık ve yeniden yavaşça inmeye başla. İpucu: İniş, kalkışın en az iki katı kadar sürmeli.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Bitirdiğinde barı askıya geri yerleştir.']::text[]),
  ('Decline_Close-Grip_Bench_To_Skull_Crusher', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve yavaşça sehpaya uzan.', 'Barı dar tut; yani omuz genişliğinden biraz daha dar. Barı askıdan al, kolların kilitli ve dirseklerin içeride olacak şekilde tam üstünde tut. Kolların yere dik olsun. Bu senin başlangıç pozisyonun. İpucu: Rotator manşetini korumak için halteri askıdan alırken bir yardımcıdan destek iste.', 'Nefes alırken barı alt göğsüne indir. Hareket boyunca dirseklerini içeride tut.', 'Nefes verirken barı triseps gücüyle iterek başlangıç pozisyonuna geri çıkar.', 'Üst kollarını sabit tut ve nefes alırken barı yavaşça indir: ön kollarını yarım daire çizerek kendine doğru getir, bar alnına hafifçe değene kadar devam et. Hareketin bu bölümünde nefes al.', 'Trisepsini kasıp nefes vererek barı başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısına ulaşana kadar 3-6. adımları tekrarla.']::text[]),
  ('Decline_Crunch', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve sırtüstü uzan.', 'Ellerini başının iki yanına hafifçe koy, dirseklerin içeride kalsın. İpucu: Parmaklarını başının arkasında kenetleme.', 'Karın kaslarını daha iyi izole etmek için belinin çukurunu sehpaya bastır ve omuzlarını sehpadan yuvarlayarak kaldırmaya başla.', 'Karın kaslarını kasıp nefes verirken belini olabildiğince güçlü biçimde aşağı bastırmayı sürdür. Omuzların sehpadan yalnızca dört inç kadar kalksın, belin sehpada kalsın. Hareketin tepesinde karnını sertçe sık ve bir saniye öyle kal. İpucu: Yavaş ve kontrollü hareket et. İvme kullanırsan yalnızca kendini kandırırsın.', 'Bir saniyelik kasılmadan sonra nefes alarak yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Decline_Dumbbell_Bench_Press', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve iki elinde birer dambıl, uyluklarının üstünde dururken uzan. Avuç içlerin birbirine baksın.', 'Uzandıktan sonra dambılları omuz genişliğinde önüne getir.', 'Orada bileklerini öne doğru çevir, avuç içlerin senden uzağa baksın. Bu senin başlangıç pozisyonun.', 'Nefes verirken ağırlıkları yavaşça yanlarına indir. Dambıllar her an tam kontrolünde olsun. İpucu: Hareket boyunca ön kolların hep yere dik kalmalı.', 'Nefes verirken dambılları göğüs kaslarınla yukarı it. Yukarıda kollarını kilitle, göğsünü sık, bir saniye bekle ve yavaşça inmeye başla. İpucu: İniş, kalkışın en az iki katı kadar sürmeli.', 'Hareketi antrenman programında belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Decline_Dumbbell_Flyes', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve iki elinde birer dambıl, uyluklarının üstünde dururken uzan. Avuç içlerin birbirine baksın.', 'Uzandıktan sonra dambılları omuz genişliğinde önüne getir. Avuç içlerin birbirine baksın, kolların tam gergin ve yere dik olsun. Bu senin başlangıç pozisyonun.', 'Biseps tendonuna yük binmemesi için dirseklerini hafifçe bük ve kollarını geniş bir yay çizerek iki yana aç; göğsünde gerilme hissedene kadar in. Hareketin bu bölümünde nefes al. İpucu: Hareket boyunca kolların biçimi değişmez; hareket yalnızca omuz ekleminden gelir.', 'Göğüs kaslarını sıkıp nefes verirken kollarını başlangıç pozisyonuna geri getir. İpucu: Ağırlıkları indirirken çizdiğin yayın aynısını izle.', 'Kasılı pozisyonda bir saniye bekle ve hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Decline_Dumbbell_Triceps_Extension', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve iki elinde birer dambıl, uyluklarının üstünde dururken uzan. Avuç içlerin birbirine baksın.', 'Uzandıktan sonra dambılları omuz genişliğinde önüne getir. Avuç içlerin birbirine baksın, kolların tam gergin ve yere dik olsun. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit, dirseklerini içeride tut ve nefes alırken dambılları yavaşça indir: ön kollarını yarım daire çizerek kendine doğru getir, başparmakların kulaklarının yanına gelene kadar devam et. Hareketin bu bölümünde nefes al.', 'Trisepsini kasıp nefes vererek dambılları başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Decline_EZ_Bar_Triceps_Extension', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve yavaşça sehpaya uzan.', 'EZ barı dar tut; yani omuz genişliğinden biraz daha dar. Barı askıdan al, kolların kilitli ve dirseklerin içeride olacak şekilde tam üstünde tut. Kolların yere dik olsun. Bu senin başlangıç pozisyonun. İpucu: Rotator manşetini korumak için barı askıdan alırken bir yardımcıdan destek iste.', 'Üst kollarını sabit tut ve nefes alırken barı yavaşça indir: ön kollarını yarım daire çizerek kendine doğru getir, bar alnına hafifçe değene kadar devam et. Hareketin bu bölümünde nefes al.', 'Trisepsini kasıp nefes vererek barı başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısına ulaşana kadar devam et.']::text[]),
  ('Decline_Oblique_Crunch', 'tr', array['Bacaklarını negatif eğimli sehpanın ucundaki desteklere sabitle ve yavaşça sehpaya uzan.', 'Üst gövdeni sehpadan kaldır; gövden yerden ölçüldüğünde yaklaşık 35-45 derecede olsun.', 'Bir elini başının yanına, diğerini uyluğuna koy. Bu senin başlangıç pozisyonun.', 'Bu pozisyondan üst gövdeni yavaşça kaldırırken gövdeni sola çevir. Nefes vererek, sağ dirseğin sol dizine değene kadar kıvrılmaya devam et. Bu kasılı pozisyonda bir saniye kal. İpucu: Karnını sıkı tut, hareketi yavaş ve kontrollü yap.', 'Nefes alırken gövdeni yavaşça başlangıç pozisyonuna indir.', 'Sağ tarafta önerilen tekrar sayısıyla bir seti bitirince sol tarafa geç. İpucu: Gövdeni gerçekten döndürmeye ve yukarıdayken kasılmayı hissetmeye odaklan.']::text[]),
  ('Decline_Push-Up', 'tr', array['Yere yüzüstü uzan, ellerini yaklaşık 36 inç arayla yere koy ve gövdeni kolların düz olacak şekilde yukarıda tut. Ayaklarını bir kasanın ya da sehpanın üstüne çıkar. Bu senin başlangıç pozisyonun.', 'Nefes alırken göğsün neredeyse yere değene kadar aşağı in.', 'Nefes ver ve göğsünü sıkarak üst gövdeni başlangıç pozisyonuna geri it.', 'Yukarıdaki kasılı pozisyonda kısa bir an bekle, sonra yeniden inmeye başla ve gerektiği kadar tekrar yap.']::text[]),
  ('Decline_Reverse_Crunch', 'tr', array['Negatif eğimli sehpaya sırtüstü uzan ve iki elinle sehpanın üst ucuna tutun. Vücudunun bu pozisyondan aşağı kaymasına izin verme.', 'Karın kaslarının gücüyle bacaklarını yere paralel tut; dizlerin ve ayakların bitişik olsun. İpucu: Bacakların tam uzanmış, dizlerin ise hafifçe bükük olmalı. Bu senin başlangıç pozisyonun.', 'Nefes verirken bacaklarını gövdene doğru çek; bu sırada leğen kemiğini geriye yuvarla ve kalçanı sehpadan kaldır. Hareketin sonunda dizlerin göğsüne değer.', 'Kasılmayı bir saniye tut, sonra nefes alarak bacaklarını başlangıç pozisyonuna götür.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Decline_Smith_Press', 'tr', array['Smith makinesinin altına negatif eğimli bir sehpa yerleştir. Barı, uzanmışken kolların neredeyse tam gergin halde yetişebileceğin bir yüksekliğe ayarla. Omuz genişliğinden daha geniş, üstten bir tutuşla barın kilidini aç ve kolların düz halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken dirseklerini bükerek barı kontrollü biçimde indir; bar gövdene hafifçe değsin.', 'Kısa bir an bekle, sonra dirseklerini düzelterek barı başlangıç pozisyonuna getir ve bu sırada nefes ver.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Set bitince barı yeniden askıya kilitle.']::text[]),
  ('Deficit_Deadlift', 'tr', array['Üstünde durabileceğin, genellikle 1-3 inç yüksekliğinde bir platform ya da ağırlık plakaları hazırla. Bara yaklaş; bar ayaklarının ortasının üstüne gelsin. Ayakların yaklaşık kalça genişliğinde açık olsun. Kalçadan eğil ve barı omuz genişliğinde tut; kürek kemiklerinin öne açılmasına izin ver. Genellikle üstten tutuş, ağır setlerde ise karışık tutuş kullanılır.', 'Ayakların ve tutuşun hazır olunca derin bir nefes al, kalçanı indir ve kaval kemiklerin bara değene kadar dizlerini bük. Başınla karşıya bak, göğsünü yukarıda ve sırtını kavisli tut, topuklarından iterek ağırlığı yukarı kaldırmaya başla. Bar dizlerini geçince onu sertçe geriye çek: kürek kemiklerini birbirine yaklaştır ve kalçanı öne, bara doğru it.', 'Kalçadan eğilerek barı yere doğru yönlendir ve indir.']::text[]),
  ('Depth_Jump_Leap', 'tr', array['Bu çalışma için iki kasa ya da sehpa gerekir: biri 12-16 inç, diğeri 22-26 inç yüksekliğinde.', 'Kasalardan birinin üstünde dur; kolların yanlarında, ayakların bitişik ve kenardan biraz taşmış olsun. Diğer kasayı yaklaşık iki ya da üç fit önüne, sana bakacak şekilde yerleştir.', 'İlk kasadan kendini bırak, iki ayağınla yere in ve aynı anda iki ayağınla yeniden sıçra.', 'Olabildiğince güçlü biçimde yukarı ve ileri doğru fırla; kollarını ve vücudunun tam açılmasını kullanarak yüksek kasanın üstüne atla. Darbeyi yine bacaklarınla karşıla.']::text[]),
  ('Dip_Machine', 'tr', array['Dip makinesine sağlam biçimde otur, ağırlığı seç ve tutamakları sıkıca kavra.', 'Yükü trisepse vermek için dirseklerini yanlarında, gövdene yakın tut. Dirseklerin 90 derecelik açıyla bükülü olsun.', 'Trisepsini kasıp nefes verirken kollarını aşağı doğru uzat. İpucu: Hareketin en altında kollarını hafifçe bükük bırak ki triseps üzerindeki gerilim sürsün.', 'Nefes alırken kollarının yavaşça başlangıç pozisyonuna yükselmesine izin ver.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Dips_-_Chest_Version', 'tr', array['Bu hareket için paralel barlara ihtiyacın var. Başlangıç pozisyonuna geçmek için kolların düz ve kilitli halde vücudunu barların üstünde tut.', 'Nefes alırken yavaşça in; gövden yaklaşık 30 derece öne eğik, dirseklerin hafifçe dışa açık olsun. Göğsünde hafif bir gerilme hissedene kadar devam et.', 'Gerilmeyi hissedince nefes ver ve göğüs kaslarınla vücudunu başlangıç pozisyonuna geri kaldır. İpucu: Hareketin tepesinde göğsünü bir saniye sıkmayı unutma.', 'Hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Dips_-_Triceps_Version', 'tr', array['Başlangıç pozisyonuna geçmek için kolların neredeyse kilitli ve düz halde vücudunu barların üstünde tut.', 'Nefes al ve yavaşça aşağı in. Gövden dik, dirseklerin vücuduna yakın kalsın. Böylece triseps daha çok çalışır. Üst kolunla ön kolun arasında 90 derecelik açı oluşana kadar in.', 'Nefes ver ve trisepsinle gövdeni yukarı iterek başlangıç pozisyonuna dön.', 'Hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Donkey_Calf_Raises', 'tr', array['Bu hareket için donkey calf raise makinesine ihtiyacın var. Önce belini ve kalçanı makinenin yastıklı kolunun altına yerleştir. Yastığa değen yer kuyruk sokumu bölgen olmalı.', 'İki kolunu yan tutamaklara koy, ayaklarının ön tabanını baldır basamağına yerleştir; topukların boşta kalsın. Çalıştırmak istediğin bölgeye göre ayak parmaklarını öne, içe ya da dışa çevir ve dizlerini kilitlemeden düzelt. Bu senin başlangıç pozisyonun.', 'Nefes verirken topuklarını kaldır: ayak bileklerini olabildiğince yükseğe uzat ve baldırını kas. Dizlerin her an sabit kalsın, hiçbir aşamada bükülmesin. İnmeye başlamadan önce kasılı pozisyonda bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön: topuklarını indir, ayak bileklerini baldırların gerilene kadar bük.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Double_Kettlebell_Alternating_Hang_Clean', 'tr', array['İki kettlebell''i ayaklarının arasına koy. Başlangıç pozisyonu için kalçanı geriye it ve dümdüz karşıya bak.', 'Kettlebell''lerden birini clean ile omzuna al, diğerini bırakmadan tut.', 'Akıcı tek bir hareketle üstteki kettlebell''i indirirken alttakini yukarı sür.']::text[]),
  ('Double_Kettlebell_Jerk', 'tr', array['Her eline birer kettlebell al ve sapından tut.', 'Kettlebell''leri clean ile omuzlarına al: bacaklarını ve kalçanı açarken ağırlıkları omuzlarına doğru çek. Bu sırada bileklerini çevir, avuç içlerin öne baksın. Bu senin başlangıç pozisyonun.', 'Gövdeni dik tutarak dizlerini bük ve hafifçe çök.', 'Hemen yön değiştir ve topuklarından it; aslında ivme kazanmak için zıplıyorsun.', 'Aynı anda kollarını uzatarak kettlebell''leri baş üstünde kilitlenene kadar it; ağırlıkları vücudunun ivmesi taşısın.', 'Ayaklarını yere bir öne bir arkaya açık biçimde indir.', 'Ağırlıklar baş üstündeyken doğrul ve ayaklarını birleştir. Sonraki tekrar için ağırlıkları indir.']::text[]),
  ('Double_Kettlebell_Push_Press', 'tr', array['İki kettlebell''i clean ile omuzlarına al.', 'Birkaç inç kadar çök ve hareketi hızla tersine çevir. Bacaklardan gelen ivmeyle kettlebell''leri baş üstüne sür.', 'Kolların kilitlenince kettlebell''leri omuzlarına indir ve tekrarla.']::text[]),
  ('Double_Kettlebell_Snatch', 'tr', array['İki kettlebell''i ayaklarının arkasına koy. Dizlerini bük ve geriye oturarak kettlebell''leri al.', 'Kettlebell''leri güçlü biçimde bacaklarının arasından savur ve yönü tersine çevir.', 'Kalçanı öne sür ve kettlebell''leri kesintisiz tek bir hareketle baş üstünde kilitle.']::text[]),
  ('Double_Kettlebell_Windmill', 'tr', array['Bir kettlebell''i öndeki ayağının önüne koy, diğer kettlebell''i karşı kolunla clean and press yaparak baş üstüne çıkar. Clean için bacaklarını ve kalçanı açarken kettlebell''i omuzlarına doğru çek. Bu sırada bileğini çevir, avuç için öne baksın.', 'Baş üstündeki kettlebell''i hep kilitli tut ve kalçanı o kettlebell''in olduğu yöne doğru dışarı it. Ayaklarını, kettlebell''i kilitli tutan koldan uzağa kırk beş derecelik açıyla çevir.', 'Kalçanı dışarı vererek kalçadan bir yana eğil ve yerdeki kettlebell''i alabilecek kadar yavaşça yat. Gözlerini hep başının üstünde tuttuğun kettlebell''den ayırma.', 'Kettlebell''i yerden aldıktan sonra bir saniye bekle ve hareketi tersine çevirerek başlangıç pozisyonuna dön.']::text[]),
  ('Double_Leg_Butt_Kick', 'tr', array['Dizlerin hafifçe bükük halde ayakta dur.', 'Kalçanı ve dizlerini bükerek hızla az bir miktar çök, hemen ardından açılıp olabildiğince yükseğe zıpla.', 'Yükselirken dizlerini bükerek topuklarını çek ve kalçana değdirmeye çalış.', 'Dizlerin yalnızca biraz bükük halde yere in ve darbeyi bacaklarınla karşıla.']::text[]),
  ('Downward_Facing_Balance', 'tr', array['Bir pilates topunun üstüne yüzüstü uzan.', 'Karnın topun üstündeyken ellerinle yerde öne doğru yürü ve bacaklarını kaldır; dirseklerin ve dizlerin düz olsun.']::text[]),
  ('Drag_Curl', 'tr', array['Halteri alttan tutuşla, avuç içlerin öne bakacak şekilde kavra; dirseklerini gövdene yaklaştır ve geriye al. Bu senin başlangıç pozisyonun.', 'Nefes verirken barı yukarı kıvır; dirseklerin geride kalsın ve barı gövdene değdirerek yukarı ''sürükle''. İpucu: Burada dirseklerini yanlarına sabitlemiyorsun, onları geriye götürüyorsun. Omuzlarını da kaldırma.', 'Bar hep gövdene değerken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Drop_Push', 'tr', array['Alçak kasaları ya da başka platformları 2-3 fit arayla yerleştir.', 'Aralarında şınav pozisyonuna geç ve ellerini kasaların üstüne koyarak kendini taşı.', 'Duruşunu bozmadan kendini yukarı it ve platformlardan düş; ellerini omuz genişliğine getir ve darbeyi kollarınla emerek inişi yumuşat.']::text[]),
  ('Dumbbell_Alternate_Bicep_Curl', 'tr', array['Gövden dik halde ayakta dur, iki elinde birer dambıl, kolların aşağı uzanmış olsun. Dirseklerin gövdene yakın, avuç içlerin uyluklarına dönük olsun.', 'Üst kolunu sabit tutarak sağdaki ağırlığı kıvır ve avuç içini öne bakana kadar çevir. Buradan nefes verirken bisepsini kasmayı sürdür; biseps tam kasılana ve dambıl omuz hizasına gelene kadar devam et. Bisepsini sıkarak kasılı pozisyonda bir saniye bekle. İpucu: Yalnızca ön kol hareket etmeli.', 'Nefes alırken dambılı yavaşça başlangıç pozisyonuna indir. İpucu: İnerken avuç içini yeniden başlangıçtaki gibi uyluğuna bakacak şekilde çevirmeyi unutma.', 'Aynı hareketi sol elinle yap. İkisi birlikte bir tekrar eder.', 'Önerilen tekrar sayısına ulaşana kadar bu şekilde sırayla devam et.']::text[]),
  ('Dumbbell_Bench_Press', 'tr', array['Düz sehpaya uzan; iki elinde birer dambıl, uyluklarının üstünde dursun. Avuç içlerin birbirine baksın.', 'Uyluklarından destek alarak dambılları birer birer kaldır ve omuz genişliğinde önünde tut.', 'Orada bileklerini öne doğru çevir, avuç içlerin senden uzağa baksın. Dambıllar göğsünün hemen yanlarında dursun, üst kolunla ön kolun 90 derecelik açı yapsın. Dambıllar her an tam kontrolünde olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılları göğsünle yukarı it. Yukarıda kollarını kilitle, göğsünü sık, bir saniye bekle ve yavaşça inmeye başla. İpucu: İdeali, ağırlığı indirmenin kaldırmanın yaklaşık iki katı kadar sürmesidir.', 'Hareketi antrenman programında belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Dumbbell_Bench_Press_with_Neutral_Grip', 'tr', array['Her eline birer dambıl al ve düz sehpaya sırtüstü uzan. Ayak tabanların yere tam bassın, kürek kemiklerin geriye çekili olsun.', 'Nötr tutuşu koru, avuç içlerin birbirine baksın; kolların tam üstünde, yere dik ve gergin halde başla. Bu senin başlangıç pozisyonun.', 'Harekete dirseklerini bükerek ve üst kollarını yana indirerek başla. Dambıllar gövde hizana gelene kadar in.', 'Bir an bekle, sonra dirseklerini düzelt ve başlangıç pozisyonuna dön.']::text[]),
  ('Dumbbell_Bicep_Curl', 'tr', array['Dik dur, iki elinde birer dambıl, kolların aşağı uzanmış olsun. Dirseklerini gövdene yakın tut ve avuç içlerini öne bakana kadar çevir. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve bisepsini kasarak ağırlıkları kıvır. Biseps tam kasılana ve dambıllar omuz hizasına gelene kadar kaldırmayı sürdür. Bisepsini sıkarak kasılı pozisyonda kısa bir an bekle.', 'Nefes al ve dambılları yavaşça başlangıç pozisyonuna indirmeye başla.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Dumbbell_Clean', 'tr', array['Ayakların omuz genişliğinde açık, iki elinde birer dambılla ayakta dur.', 'Kalçanı ve dizlerini bük, kalçanı geriye iterek dambıllar yere ulaşana kadar ağırlıkları indir. Bu senin başlangıç pozisyonun.', 'Hareketi başlatmak için patlayıcı biçimde yukarı sıçra: kalçanı, dizlerini ve ayak bileklerini açarak ağırlıkları yukarı doğru hızlandır. Dambılları nötr tutuşla tut ve vücudun tam açılana kadar kollarını düz bırak.', 'Tam açıldıktan sonra kalçanı ve dizlerini yeniden bük ve ağırlığı squat pozisyonunda karşıla. Kollarının bükülmesine izin ver, dambılları omuzlarına yönlendir.', 'Ağırlığı squat pozisyonunda karşıladıktan sonra kalçanı ve dizlerini aç; dambıllar omuzlarındayken ayakta bitir.']::text[]),
  ('Dumbbell_Floor_Press', 'tr', array['Ellerinde dambıllarla yere uzan. Dizlerin bükülü olabilir. Kolların tam gergin, ağırlıklar üstündeyken başla.', 'Üst kolların yere değene kadar ağırlıkları indir. Triseps hacmini ve gücünü öne çıkarmak için dirseklerini gövdene yakın tut, göğse odaklanmak için kollarını yana aç.', 'Altta bir an bekle, sonra dirseklerini düzelterek ağırlıkları yukarıda bir araya getir.']::text[]),
  ('Dumbbell_Flyes', 'tr', array['Düz sehpaya uzan; iki elinde birer dambıl, uyluklarının üstünde dursun. Avuç içlerin birbirine baksın.', 'Uyluklarından destek alarak dambılları birer birer kaldır ve avuç içlerin birbirine bakarken omuz genişliğinde önünde tut. Dambılları press yapar gibi yukarı çıkar, ama kolların kilitlenmeden hemen önce dur ve orada tut. Bu senin başlangıç pozisyonun.', 'Biseps tendonuna yük binmemesi için dirseklerini hafifçe bük ve kollarını geniş bir yay çizerek iki yana aç; göğsünde gerilme hissedene kadar in. Hareketin bu bölümünde nefes al. İpucu: Hareket boyunca kolların biçimi değişmez; hareket yalnızca omuz ekleminden gelir.', 'Göğüs kaslarını sıkıp nefes verirken kollarını başlangıç pozisyonuna geri getir. İpucu: Ağırlıkları indirirken çizdiğin yayın aynısını izle.', 'Kasılı pozisyonda bir saniye bekle ve hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Dumbbell_Incline_Row', 'tr', array['Nötr tutuşa hazır biçimde, eğimli sehpaya göğsünle yaslan.', 'Her eline nötr tutuşla birer dambıl al ve kolların düz halde başla. Bu senin başlangıç pozisyonun.', 'Kürek kemiklerini geriye çek ve dirseklerini bükerek dambılları yanlarına doğru çek.', 'Hareketin tepesinde bir an bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Dumbbell_Incline_Shoulder_Raise', 'tr', array['Eğimli sehpaya otur; iki elinde birer dambıl, uyluklarının üstünde dursun.', 'Bacaklarını kaldırıp ağırlıkları omuzlarına doğru fırlat ve arkana yaslan. Dambılları kolların düz halde omuzlarının üstünde tut. Kolların yere dik, avuç içlerin öne, parmak eklemlerin tavana dönük olsun. Bu senin başlangıç pozisyonun.', 'Kollarını düz ve kilitli tutarak nefes ver ve omuzlarını sehpadan kaldırıp dambılları yükselt.', 'Nefes alırken dambılları başlangıç pozisyonuna geri getir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Dumbbell_Lunges', 'tr', array['Gövden dik halde ayakta dur, iki dambılı yanlarında tut. Bu senin başlangıç pozisyonun.', 'Sağ bacağınla öne adım at; ayağın, arkada sabit kalan ayaktan yaklaşık 2 fit ileride olsun. Gövdeni dik tutup dengeni koruyarak üst gövdeni indir. İnerken nefes al. Not: İnerken dizinin ayak parmaklarını geçip öne gitmesine izin verme; bu, diz eklemine gereksiz yük bindirir. Öndeki kaval kemiğinin yere dik kalmasına dikkat et.', 'Ağırlıklı olarak topuğundan iterek yüksel ve nefes verirken başlangıç pozisyonuna dön.', 'Hareketi önerilen tekrar sayısı kadar yap, sonra sol bacağınla uygula.']::text[]),
  ('Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'tr', array['Bir elinde dambıl varken, hafif eğim verilmiş (yerden ölçüldüğünde yaklaşık 15 derece) ayarlanabilir bir sehpaya göğsün aşağıda olacak şekilde uzan. Denge için diğer elinle sehpanın ayağına tutunabilirsin.', 'Dambılı tutan elini nötr konuma getir, avuç için gövdene baksın; kolunu dirseğin hafifçe bükük halde uzatılmış tut. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambıllı kolunu yana kaldır; dirseğin omuz hizasına gelsin ve kolun yere aşağı yukarı paralel olsun. İpucu: Hareket boyunca kolunu uzatılmış ve gövdene dik tut. Ayrıca tepede kasılmayı bir saniye koru.', 'Nefes alırken dambılı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Dumbbell_Lying_Pronation', 'tr', array['Düz sehpaya yüzüstü uzan. Bir kolunla dambıl tut, diğer elini başını yaslayabileceğin şekilde katlayıp sehpanın üstüne koy.', 'Dambılı tutan kolunun dirseğini bük; üst kolunla ön kolun arasında 90 derecelik açı oluşsun.', 'Üst kolunu kaldır; ön kolun yere dik, üst kolun gövdene dik olsun. İpucu: Üst kolun yere paralel olmalı ve gövdenle de 90 derecelik açı yapmalı. Bu senin başlangıç pozisyonun.', 'Nefes verirken ön kolunu dışa doğru döndür ve dambılı öne doğru kaldır; üst kolunla ön kolun arasındaki 90 derecelik bükülmeyi koru. Bu dış rotasyonu ön kolun yere paralel olana kadar sürdür ve orada kasılmayı bir saniye tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Dumbbell_Lying_Rear_Lateral_Raise', 'tr', array['Ayarlanabilir bir sehpayı hafif eğime, yerden yaklaşık 15 dereceye getir. İki elinde birer dambıl ile göğsün sehpaya gelecek şekilde uzan.', 'Kollarını uzat, dirseklerini hafifçe bük ve ellerini nötr tutuşa getir, avuç içlerin gövdene baksın. Bu senin başlangıç pozisyonun.', 'Nefes verirken kollarını yanlara kaldır. Dirseklerin omuz hizasına gelsin, kolların yere aşağı yukarı paralel olsun. İpucu: Hareket boyunca kollarını uzatılmış ve gövdene dik tut. Tepe noktasında kasılmayı bir saniye koru.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla, sonra diğer kola geç.']::text[]),
  ('Dumbbell_Lying_Supination', 'tr', array['Düz bir sehpaya yan yat. Bir elinde dambıl tut, diğer kolunu sehpanın üstünde bük ve başını ona yasla.', 'Dambılı tutan kolun dirseğini bük; üst kolunla ön kolun arasında 90 derecelik açı oluşsun.', 'Üst kolunu kaldır; ön kolun yere paralel, gövdene dik olsun (İpucu: Ön kolun böylece tam önüne doğru uzanır). Üst kolun gövdenin yanında sabit durur, yere paralel kalır ve her an gövdenle aynı hizadadır. Bu senin başlangıç pozisyonun.', 'Nefes verirken ön kolunu dışa doğru döndür; dambıl yarım daire çizerek yukarı çıksın. Üst kolla ön kol arasındaki 90 derecelik açıyı bozma. Ön kolun tavanı gösterip yere ve gövdene dik gelene kadar döndürmeye devam et. Bu noktada kasılmayı bir saniye tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla, sonra kol değiştir.']::text[]),
  ('Dumbbell_One-Arm_Shoulder_Press', 'tr', array['Bir dambıl al. İstersen omuz pres sehpasına ya da sırt destekli bir sehpaya otur ve dambılı dik şekilde uyluğunun üstüne koy, istersen dik dur.', 'Dambılı silkerek omuz hizasına getir. Boştaki elini yana doğru uzatabilir, beline koyabilir ya da sabit bir yere tutunabilirsin.', 'Bileğini çevir, avuç için öne baksın. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılı yukarı it, kolun tamamen düzleşsin.', 'Bir saniye bekle, sonra nefes alırken yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısını tamamla, sonra kol değiştir.']::text[]),
  ('Dumbbell_One-Arm_Triceps_Extension', 'tr', array['Eline bir dambıl al. Omuz pres sehpasına ya da sırt destekli bir sehpaya oturup dambılı dik şekilde uyluğuna koyabilir ya da ayakta dik durabilirsin.', 'Dambılı silkerek omuz hizasına getir, ardından kolunu başının üstüne uzat. Kolun tamamı yere dik ve başının yanında, dambıl ise tam üstünde olsun. Boştaki elini yana uzatabilir, beline koyabilir, dambılı tutan üst kolu destekleyebilir ya da sabit bir yere tutunabilirsin.', 'Bileğini çevir; avuç için öne, serçe parmağın tavana baksın. Bu senin başlangıç pozisyonun.', 'Üst kolunu sabit tutarak dambılı yavaşça başının arkasına indir ve bu sırada nefes al. Triseps tamamen gerildiğinde dur.', 'Nefes verirken trisepsi kasarak başlangıç pozisyonuna dön. İpucu: Yalnızca ön kol hareket etmeli. Üst kol her an başının yanında sabit kalır.', 'Önerilen tekrar sayısını tamamla, sonra kol değiştir.']::text[]),
  ('Dumbbell_One-Arm_Upright_Row', 'tr', array['Bir dambıl al ve sırtın düz şekilde dik dur. Kolun önünde uzatılmış, dirseğin hafif bükük olsun. Bu senin başlangıç pozisyonun. İpucu: Dambıl uyluğunun ön yüzüne yaslansın, avuç için uyluğuna baksın.', 'Diğer elini yana uzatabilir, beline koyabilir ya da sabit bir yere tutunabilirsin. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılı omzunun yan kısmıyla kaldır. Yukarı çıkarken dambılı vücuduna yakın tut ve neredeyse çene hizasına gelene kadar kaldır. İpucu: Hareketi dirseğin yönlendirsin; kaldırırken dirseğin hep ön kolundan yukarıda olsun. Gövdeni sabit tut ve tepe noktasında bir saniye bekle.', 'Dambılı yavaşça başlangıç pozisyonuna indir ve bu sırada nefes al.', 'Önerilen tekrar sayısını tamamla, sonra kol değiştir.']::text[]),
  ('Dumbbell_Prone_Incline_Curl', 'tr', array['İki eline birer dambıl al ve eğimli sehpaya yüzüstü uzan; omuzların sehpanın üst ucuna yakın olsun. Dizlerini oturma yerine dayayabilir ya da bacaklarını sehpanın iki yanına açabilirsin.', 'Kollarını önünde serbestçe sarkıt; yere dik dursunlar.', 'Dirseklerini gövdene yakın tut ve avuç içlerini öne çevir. Bu senin başlangıç pozisyonun.', 'Bisepsi kasarak dambılları kaldır, kolların tamamen bükülsün. Bu sırada nefes ver ve yalnızca ön kollarını oynat. Üst kollar her an sabit kalır.', 'Dambılları kolların tamamen düzleşene kadar indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Dumbbell_Raise', 'tr', array['İki eline birer dambıl al ve sırtın düz şekilde dik dur. Kolların yanlarında uzatılmış, dirseklerin hafif bükük olsun. Bu senin başlangıç pozisyonun. İpucu: Dambıllar uyluklarının yanında dursun, avuç içlerin arkaya baksın.', 'Nefes verirken dambılları omuzlarının yan kısmıyla kaldır. Yukarı çıkarken dambıllar vücudunun yanında kalsın ve neredeyse çene hizasına gelene kadar kaldır. İpucu: Hareketi dirseklerin yönlendirsin; kaldırırken dirseklerin hep ön kollarından yukarıda olsun. Gövdeni sabit tut ve tepe noktasında bir saniye bekle.', 'Dambılları yavaşça başlangıç pozisyonuna indir ve bu sırada nefes al.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Dumbbell_Rear_Lunge', 'tr', array['Gövden dik şekilde dur, iki elinde birer dambıl yanlarında olsun. Bu senin başlangıç pozisyonun.', 'Sağ bacağınla geriye, sol ayağından yaklaşık iki fit uzağa adım at ve vücudunu aşağı indir. Gövden dik kalsın, dengeni koru. İnerken nefes al. İpucu: İnerken öndeki dizinin ayak parmaklarını geçmesine izin verme; bu, diz eklemine gereksiz yük bindirir. Öndeki kaval kemiğin yere dik kalsın. Hamle boyunca gövdeni dik tut; bunun için esnek kalça fleksörleri önemlidir. Uzun adım gluteus maximusu, kısa adım ön bacağı öne çıkarır.', 'Nefes verirken kendini yukarı it ve başlangıç pozisyonuna dön. İpucu: Ön bacağı vurgulamak için ayağının ön tabanıyla it. Kalçaya odaklanmak için topuklarınla bastır.', 'Şimdi aynısını diğer bacakla yap.']::text[]),
  ('Dumbbell_Scaption', 'tr', array['Bu düzeltici egzersiz, kürek kemiğini sabitleyen kasları güçlendirir. İki elinde birer hafif ağırlıkla kollarını yanlarında sarkıt, başparmakların yukarı baksın.', 'Kollarını öne doğru, orta hattan yaklaşık 30 derece dışa açarak kaldırmaya başla. Hareket boyunca kolların tamamen düz olsun.', 'Kolların yere paralel olana kadar devam et, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Dumbbell_Seated_Box_Jump', 'tr', array['Bir kasayı sehpanın birkaç fit yanına yerleştir. Yüzün kasaya dönük şekilde sehpaya otur ve bir dambılı iki elinle göğsünde tut. Bu senin başlangıç pozisyonun.', 'Ayaklarını yere sağlam bas, öne eğil ve kalçanla dizlerini açarak yukarı ve ileri sıçra.', 'İki ayağınla kasanın üstüne in; kalçanı ve dizlerini bükerek darbeyi yumuşat.', 'Kasadan in ve başlangıç pozisyonuna dön.']::text[]),
  ('Dumbbell_Seated_One-Leg_Calf_Raise', 'tr', array['Yere, düz bir sehpadan yaklaşık 12 inç uzağa bir blok koy.', 'Sehpaya otur ve bir dambılı sol uyluğunun üstüne, dizinin yaklaşık 3 inç yukarısına yerleştir.', 'Sol ayağının ön tabanını bloğa bas. Bu senin başlangıç pozisyonun.', 'Nefes verirken baldırını kasarak parmak ucunda yükselebildiğin kadar yüksel. Kasılmayı bir saniye tut.', 'Yavaşça başlangıç pozisyonuna dön ve topuğunu esneyebildiği kadar aşağı indir.', 'Sana verilen tekrar sayısını tamamla, sonra aynısını sağ bacakla yap.']::text[]),
  ('Dumbbell_Shoulder_Press', 'tr', array['İki elinde birer dambıl ile omuz pres sehpasına ya da sırt destekli bir sehpaya otur. Dambılları dik şekilde uyluklarının üstüne koy.', 'Dambılları birer birer omuz hizasına kaldır; yerlerine getirirken uyluklarınla itiş ver.', 'Bileklerini çevir, avuç içlerin öne baksın. Bu senin başlangıç pozisyonun.', 'Nefes ver ve dambılları tepede birbirine değene kadar yukarı it.', 'Tepedeki kasılı pozisyonda kısa bir an bekle, sonra nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Dumbbell_Shrug', 'tr', array['Dik dur; kolların yanlarında uzatılmış, iki elinde birer dambıl, avuç içlerin gövdene dönük olsun.', 'Nefes verirken omuzlarını çıkabildiği kadar yukarı çekerek dambılları kaldır. Tepede kasılmayı bir saniye tut. İpucu: Kolların her an düz kalsın, dambılları kaldırmak için bisepsten yardım alma. Yalnızca omuzlar aşağı yukarı hareket eder.', 'Dambılları ilk konumlarına indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Dumbbell_Side_Bend', 'tr', array['Dik dur; sol elinde bir dambıl tut, avuç için gövdene baksın, sağ elini beline koy. Ayaklarını omuz genişliğinde aç. Bu senin başlangıç pozisyonun.', 'Sırtın düz, başın dik şekilde yalnızca belinden sağa doğru eğilebildiğin kadar eğil. Eğilirken nefes al. Bir saniye bekle, sonra nefes vererek başlangıç pozisyonuna doğrul. İpucu: Vücudunun geri kalanı sabit kalsın.', 'Şimdi aynı hareketi bu kez sola eğilerek yap. Bir saniye bekle ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla, sonra dambılı diğer eline al.']::text[]),
  ('Dumbbell_Squat', 'tr', array['Dik dur; iki elinde birer dambıl olsun, avuç içlerin bacaklarının yan tarafına baksın.', 'Ayaklarını omuz genişliğinde, orta bir duruşla yerleştir ve parmak uçlarını hafifçe dışa çevir. Başını hep dik tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Bu senin başlangıç pozisyonun. Not: Bu orta duruş bacakları bütün olarak çalıştırır; istersen üç duruş genişliğinden herhangi birini seçebilirsin.', 'Dizlerini bükerek gövdeni yavaşça indir; duruşun dik, başın yukarıda kalsın. Uylukların yere paralel olana kadar in. İpucu: Hareket doğru yapıldığında dizlerinin ön yüzü ayak parmaklarınla aynı hayali dikey çizgide kalır. Dizlerin bu çizgiyi, yani ayak parmaklarını geçerse dize gereksiz yük biner ve hareket yanlış yapılmış olur.', 'Nefes verirken ağırlıklı olarak topuklarınla yeri iterek yüksel; bacaklarını düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Dumbbell_Squat_To_A_Bench', 'tr', array['Arkanda düz bir sehpa olacak şekilde dik dur; iki elinde birer dambıl olsun, avuç içlerin bacaklarının yan tarafına baksın.', 'Omuz genişliğinde orta bir duruş al, parmak uçların hafifçe dışa baksın. Başın hep yukarıda olsun, çünkü aşağı bakınca dengen kaçar; sırtın da düz kalsın. Bu senin başlangıç pozisyonun. Not: Orta duruş bacakları bütün olarak geliştirir; onun yerine üç duruş genişliğinden herhangi biri de kullanılabilir.', 'Dizlerini bükerek gövdeni yavaşça indir; duruşun dik, başın yukarıda kalsın. Arkandaki sehpaya hafifçe değene kadar in. Hareketin bu bölümünde nefes al. İpucu: Hareket doğru yapıldığında dizlerinin ön yüzü ayak parmaklarınla aynı hayali dikey çizgide kalır. Dizlerin bu çizgiyi, yani ayak parmaklarını geçerse dize gereksiz yük biner ve hareket yanlış yapılmış olur.', 'Nefes verirken ağırlıklı olarak topuklarınla yeri iterek kalk; bacaklarını düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Dumbbell_Step_Ups', 'tr', array['Dik dur; iki elinde birer dambıl olsun, avuç içlerin bacaklarının yan tarafına baksın.', 'Sağ ayağını yükseltilmiş platforma koy. Sağ bacağının kalçasını ve dizini açarak platforma çık. Vücudunu kaldırırken ağırlıklı olarak topuğunu kullan ve sol ayağını da platforma bas. Yukarı çıkmak için güç harcarken nefes ver.', 'Nefes alırken sağ bacağının kalçasını ve dizini bükerek sol bacağınla aşağı in. Sağ ayağını sol ayağının yanına koyarak baştaki duruşuna dön.', 'Önerilen tekrar sayısını sağ bacakla tamamla, sonra sol bacakla yap.']::text[]),
  ('Dumbbell_Tricep_Extension_-Pronated_Grip', 'tr', array['Düz bir sehpaya uzan ve iki dambılı tam omuzlarının üstünde tut. Kolların tamamen düz olsun, gövdenle ve yerle 90 derecelik açı yapsın.', 'Avuç içlerin öne baksın, dirseklerin içe dönük kalsın. Bu senin başlangıç pozisyonun.', 'Nefes al ve dambılları kulaklarının yakınına gelene kadar yavaşça indir. Üst kollarını sabit, dirseklerini içte tut.', 'Sonra nefes ver ve trisepsinle ağırlığı başlangıç pozisyonuna geri it.']::text[]),
  ('Dynamic_Back_Stretch', 'tr', array['Ayaklarını omuz genişliğinde açarak ayakta dur. Bu senin başlangıç pozisyonun.', 'Kollarını düz tutarak önünden yukarı doğru 5-10 kez savur. Her seferinde hareket açıklığını biraz artır; sonunda kolların başının üstüne çıksın.']::text[]),
  ('Dynamic_Chest_Stretch', 'tr', array['Ayakta dur; kollarını tam önüne uzat, ellerini birleştir. Bu senin başlangıç pozisyonun.', 'Kollarını düz tutarak hızla gidebildiği kadar geriye aç ve yeniden birleştir; abartılı bir alkış hareketi gibi. 5-10 kez tekrarla ve giderek hızlan.']::text[]),
  ('EZ-Bar_Curl', 'tr', array['Dik dur ve EZ barı dıştaki geniş tutuş yerlerinden kavra. Avuç içlerin öne baksın; barın şekli yüzünden hafifçe içe eğik dururlar. Dirseklerini gövdene yakın tut. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve bisepsi kasarak ağırlığı öne doğru kaldır. Yalnızca ön kollarını oynatmaya odaklan.', 'Biseps tamamen kasılana ve bar omuz hizasına gelene kadar kaldırmaya devam et. Tepedeki kasılı pozisyonu bir an koru ve bisepsi sık.', 'Sonra nefes al ve barı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('EZ-Bar_Skullcrusher', 'tr', array['EZ barı dar tutuşla kaldır ve sehpaya uzan; barı dirseklerin içe dönük şekilde tut. Kolların yere dik olsun. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tutarak dirseklerini bük ve barı indir. Bu sırada nefes al. Bar tam alnının üstüne geldiğinde dur.', 'Nefes verirken dirseklerini açarak barı başlangıç pozisyonuna kaldır.', 'Hareketi tekrarla.']::text[]),
  ('Elbow_Circles', 'tr', array['Ayaklarını hafifçe açarak otur ya da ayakta dur.', 'Ellerini omuzlarına koy; dirseklerin omuz hizasında olsun ve dışa baksın.', 'Dirseklerinle yavaşça bir daire çiz. Daireye başlarken nefes ver, daireyi tamamlarken nefes al.']::text[]),
  ('Elbow_to_Knee', 'tr', array['Yere uzan, sol dizini bük ve sağ bacağını onun üstüne at. Ellerini başının arkasında kenetle; başlangıçta kürek kemiklerin yerde olsun. Bu senin başlangıç pozisyonun.', 'Omurganı büküp gövdeni döndürerek sol dirseğini sağ dizine götür.', 'Başlangıç pozisyonuna dön, istediğin tekrar sayısını tamamla ve sonra taraf değiştir.']::text[]),
  ('Elbows_Back', 'tr', array['Dimdik ayakta dur.', 'İki elini beline koy; parmakların aşağıyı göstersin, dirseklerin dışa açık olsun.', 'Sonra dirseklerini nazikçe geriye çek ve birbirine değdirmeye çalış.']::text[]),
  ('Elevated_Back_Lunge', 'tr', array['Bir barı sehpaya omuz hizasında yerleştir ve uygun ağırlıkla yükle. Arkana alçak, yükseltilmiş bir platform koy.', 'Barı sırtının üst kısmına al; sırtın kavisli ve sıkı kalsın. İki ayağınla platforma çık. Bu senin başlangıç pozisyonun.', 'Bir bacağınla geriye adım atarak başla. Kalçanı ve dizlerini bükerek dizin yere değene kadar in.', 'Kısa bir an dur, sonra kalçanı ve dizlerini açarak yüksel. Bacak değiştirmeden önce tam olarak başlangıç pozisyonuna dön.']::text[]),
  ('Elevated_Cable_Rows', 'tr', array['Yaklaşık 4-6 inç yüksekliğinde bir platform bul; aerobik stepi ya da baldır kaldırma platformu olabilir.', 'Platformu kablolu kürek makinesinin oturağına koy.', 'Makineye otur ve ayaklarını öndeki platforma ya da çapraz çubuğa bas. Dizlerin kilitli değil, hafifçe bükük olsun.', 'Sırtının doğal hizasını koruyarak öne eğil ve V tutamağı kavra.', 'Kolların düz şekilde geriye çekil; gövden bacaklarınla 90 derecelik açı yapsın. Sırtın hafif kavisli, göğsün dışarıda olsun. Tutamak önündeyken kanat kaslarında iyi bir gerilme hissetmelisin. Bu, egzersizin başlangıç pozisyonu.', 'Gövdeni sabit tutarak tutamağı kendine doğru çek; kolların gövdene yakın kalsın ve tutamak karnına değsin. Çekerken nefes ver. Bu noktada sırt kaslarını iyice sık, kasılmayı bir saniye tut, sonra nefes alarak yavaşça ilk konuma dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Elliptical_Trainer', 'tr', array['Önce eliptik bisiklete çık ve menüden istediğin seçeneği belirle. Çoğu alette manuel ayar vardır ya da çalıştırmak için bir program seçebilirsin. Genellikle yaşını ve kilonu girerek egzersizde yaktığın kalorinin tahmin edilmesini sağlayabilirsin. Antrenmanın yoğunluğunu değiştirmek için eğimi ayarla.', 'Tutamakları nabzını izlemek için kullanabilirsin; bu, uygun yoğunlukta kalmana yardım eder.']::text[]),
  ('Exercise_Ball_Crunch', 'tr', array['Pilates topuna sırtüstü uzan; bel çukurun topun yuvarlak yüzeyine otursun. Dizlerin bükük, ayakların yere sağlam basıyor olsun. Gövdenin üst kısmı topun üstünden sarksın. Kollarını ya vücudunun yanında tut ya da göğsünde çaprazla; bu iki konum, elleri başın arkasına koymanın aksine boynu zorlamaz.', 'Gövdeni gerilme pozisyonuna indir ve boynunu her an sabit tut. Bu senin başlangıç pozisyonun.', 'Kalçan sabitken karın kaslarını kasarak belinden bükül; omuzlarını ve gövdeni, karnında iyi bir kasılma hissedene kadar yukarı kıvır. Kolların yandaysa bacaklarının yanından yukarı kayar, çaprazsa göğsünde kalır. Belin toptan hiç ayrılmasın. Hareket sırasında nefes ver ve kasılmayı bir saniye tut.', 'Nefes alırken başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Exercise_Ball_Pull-In', 'tr', array['Yakınına bir pilates topu koy ve topun önünde yere, şınav pozisyonuna geç; ellerin omuz genişliğinde yerde olsun.', 'Şimdi kaval kemiklerinin alt kısmını topun üstüne yerleştir. İpucu: Bu noktada bacakların tamamen düz, kaval kemiklerin topun üstünde olmalı; üst bedenin ise önünde düz duran iki kolunun taşıdığı şınav benzeri bir pozisyonda durmalı. Bu senin başlangıç pozisyonun.', 'Sırtını dümdüz, üst bedenini sabit tut. Nefes verirken dizlerini göğsüne çek; top ayak bileklerinin altında öne yuvarlansın. Karnını sık ve bu pozisyonu bir saniye koru.', 'Nefes alırken bacaklarını yavaşça düzelt ve topu başlangıç pozisyonuna geri yuvarla.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Extended_Range_One-Arm_Kettlebell_Floor_Press', 'tr', array['Yere uzan ve tek kolla itmek üzere bir kettlebell hazırla. Kettlebell''i sapından tut. İttiğin taraftaki bacağını bük; dizin vücudunun orta hattının öbür yanına geçsin.', 'Dirseğini açıp kolunu içe doğru getirerek kettlebell''i vücudunun üstüne it. Başlangıç pozisyonuna dön.']::text[]),
  ('External_Rotation', 'tr', array['Bir elinde dambıl ile düz bir sehpaya yan yat. Diğer kolunu sehpanın üstünde katla ve başını üstüne koy.', 'Dambılı tutan kolun dirseğini, üst kolla ön kol arasında 90 derecelik açı olacak şekilde bük. İpucu: Kolunu gövdene paralel tut.', 'Üst kolunu sabit tutarak dirseğini bük. Böylece ön kolun yere paralel, gövdene dik olur (İpucu: Ön kolun tam önüne doğru uzanır). Üst kolun gövdenin yanında sabit kalır, yere paralel durur ve hep gövdenle aynı hizadadır. Bu senin başlangıç pozisyonun.', 'Nefes verirken ön kolunu dışa çevir; dambıl yarım daire çizerek yükselsin, üst kolla ön kol arasındaki 90 derecelik açı korunsun. Ön kolun tavana dönüp yere ve gövdene dik olana kadar çevirmeyi sürdür. Orada kasılmayı bir saniye tut.', 'Nefes alırken ön kolunu yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla, sonra diğer kola geç.']::text[]),
  ('External_Rotation_with_Band', 'tr', array['Lastik bandı bir direğe boğarak bağla; bant dirseğinle aynı yükseklikte olsun. Sol yanın banda dönük şekilde birkaç fit uzakta dur.', 'Bandın ucunu sağ elinle kavra ve dirseğini gövdenin yanına sıkıca bastır. Dirseğin yerinden oynamasın diye dirseğinle bir ped ya da foam roller sıkıştırman önerilir.', 'Üst kolun yerindeyken dirseğin 90 derece bükük olsun, elin gövdenin önünden karşı tarafa uzansın. Bu senin başlangıç pozisyonun.', 'Dirseğini yerinden oynatmadan kolunu, ters vuruş yapar gibi dışa döndür.', 'Gidebildiğin kadar git, kısa bir an dur ve başlangıç pozisyonuna dön.']::text[]),
  ('External_Rotation_with_Cable', 'tr', array['Kabloyu dirseğinle aynı yüksekliğe ayarla. Sol yanın kabloya dönük şekilde birkaç fit uzakta dur.', 'Tutamağı sağ elinle kavra ve dirseğini gövdenin yanına sıkıca bastır. Dirseğin yerinden oynamasın diye dirseğinle bir ped ya da foam roller sıkıştırman önerilir.', 'Üst kolun yerindeyken dirseğin 90 derece bükük olsun, elin gövdenin önünden karşı tarafa uzansın. Bu senin başlangıç pozisyonun.', 'Dirseğini yerinden oynatmadan kolunu, ters vuruş yapar gibi dışa döndür.']::text[]),
  ('Face_Pull', 'tr', array['Halat ya da çift tutamak takılı yüksek bir makaranın karşısına geç. Ağırlığı doğrudan yüzüne doğru çek ve çekerken ellerini birbirinden ayır. Üst kolların yere paralel kalsın.']::text[]),
  ('Farmers_Walk', 'tr', array['Çiftçi yürüyüşü için çeşitli ekipmanlar kullanılabilir. Bunlar yoksa ağır dambıllar ya da kısa barlarla da yapabilirsin. Ekipmanların arasında durarak başla.', 'Tutamakları kavra ve topuklarından güç alarak ağırlıkları kaldır; sırtın düz, başın dik olsun.', 'Kısa ve hızlı adımlarla yürü, nefes almayı unutma. Belirlenen mesafeyi, genellikle 50-100 fit, olabildiğince hızlı geç.']::text[]),
  ('Fast_Skipping', 'tr', array['Bir bacağın hafifçe önde, rahat bir duruşla başla. Bu senin başlangıç pozisyonun.', 'Adım-sek düzeniyle sek: sağ-sağ-adım, sonra sol-sol-adım diye iki taraf arasında dönüşümlü devam et.', 'Hızlı sekmek için yere yakın kal, havada geçen süreyi kısalt ve olabildiğince hızlı ilerle.']::text[]),
  ('Finger_Curls', 'tr', array['Bir halteri iki elinle, avuç içlerin yukarı bakacak şekilde tut; ellerin yaklaşık omuz genişliğinde olsun.', 'Ayaklarını omuz genişliğinden biraz daha açık şekilde yere düz bas. Bu senin başlangıç pozisyonun.', 'Parmaklarını açarak barı inebildiği kadar indir. Barın ellerinden aşağı yuvarlanmasına izin ver ve onu parmaklarının son boğumunda yakala.', 'Şimdi nefes verirken ellerini kapatarak barı çıkabildiği kadar yukarı kıvır. Tepede kasılmayı tut.']::text[]),
  ('Flat_Bench_Cable_Flyes', 'tr', array['Düz bir sehpayı iki alçak makaranın arasına yerleştir; üstüne uzandığında göğsün makaralarla aynı hizada olsun.', 'Sehpaya sırtüstü uzan, ayakların yerde kalsın.', 'Birinden tutamakları iki eline vermesini iste. Her tekli tutamağı avuç için yukarı bakacak şekilde kavra.', 'Kollarını yanlara aç, dirseklerin hafif bükük olsun. İpucu: Bu bükülmeyi hareketin tamamında aynı tut. Kolların yere paralel olsun. Bu senin başlangıç pozisyonun.', 'Kabloları birbirine doğru çekerek kollarını önünde yarım daire çizecek şekilde kaldır; iki elin tepede buluşsun. Bu sırada göğsünü sık ve nefes ver. Tepede kasılmayı bir saniye tut. İpucu: Doğru yapıldığında tepe noktasında kolların gövdene ve yere dik olur, ellerin göğsünün üstünde birbirine değer.', 'Yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Flat_Bench_Leg_Pull-In', 'tr', array['Düz bir sehpaya ya da egzersiz matına, bacakların uçtan dışarı taşacak şekilde uzan.', 'Ellerini avuç içleri aşağı bakacak şekilde kalçanın altına koy ya da yanlardan sehpayı tut (matta avuçlarını yanında yere yasla). Bacaklarını dümdüz uzat. Bu senin başlangıç pozisyonun.', 'Nefes verirken dizlerini bük ve üst bacaklarını karnına doğru çek. Dizlerin göğsüne yaklaşana kadar devam et, kasılmış halde bir saniye bekle.', 'Nefes alırken bacaklarını yavaşça uzatıp başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Flat_Bench_Lying_Leg_Raise', 'tr', array['Sırtın düz olacak şekilde bir sehpaya uzan, bacakların uçtan dışarı doğru uzansın.', 'Ellerini avuç içleri aşağı bakacak şekilde kalçanın altına koy ya da yanlardan sehpayı tut. Bu senin başlangıç pozisyonun.', 'Bacaklarını olabildiğince düz tut, dizlerin hafif bükük ve bu açıda sabit kalsın; bacaklarını yerle 90 derecelik açı yapana kadar kaldır. Kaldırırken nefes ver ve yukarıda kasılmayı bir saniye koru.', 'Sonra nefes alırken bacaklarını yavaşça başlangıç pozisyonuna indir.']::text[]),
  ('Flexor_Incline_Dumbbell_Curls', 'tr', array['Her dambılı senden uzak olan ucuna yakın tut; böylece ağırlığın çoğu sana yakın tarafta kalır. (Bu, dambılla yapılan bütün biseps hareketlerinde işe yarar.) Sonra normal bir eğimli sehpa dambıl curl yap, ama bileklerini olabildiğince geriye yatık tut ki üzerlerindeki yük kalksın.', 'Her eline bir dambıl al ve 45 dereceye ayarlanmış eğimli sehpaya otur.', 'Kollarını yanlarında sarkıt, dirseklerin gövdene yakın olsun. Avuç içlerini öne çevir, başparmakların vücudundan dışarıyı göstersin. İpucu: Bu el pozisyonunu hareket boyunca koru; eller yukarı çıkarken dönmemeli. Bu senin başlangıç pozisyonun.', 'Nefes verirken iki dambılı aynı anda, bisepsin tam kasılana kadar yukarı bük. İpucu: Kollarını sallama, hız almaktan kaçın; hareket her an kontrollü olsun. Yukarıda bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Floor_Glute-Ham_Raise', 'tr', array['Bu hareketi bir partnerle yap ya da ayaklarını sağlam bir şeyin altına sıkıştır.', 'Dizlerinin üzerinde başla; üst bacakların ve gövden dik olsun. Partnerin varsa, yerinde kalman için ayaklarını sıkıca tutar. Bu senin başlangıç pozisyonun.', 'Dizlerinden açılarak kendini öne doğru indir. İnerken kalçanı BÜKMEMEYE dikkat et.', 'Yere ulaşırken ellerini önüne koy. Bu hareket çok zordur, yardımsız yapamayabilirsin. Başlangıç pozisyonuna dönmeyi kolaylaştırmak için kollarınla yerden hafifçe itil.']::text[]),
  ('Floor_Press', 'tr', array['J kancalarını, barı rahatça alıp geri koyabileceğin yüksekliğe ayarla. Başın power rack''in ucuna yakın olacak şekilde yere uzan. Kürek kemiklerini birbirine çek, öyle tut ve barı kancalardan al.', 'Barı göğsünün alt kısmına ya da karnının üst kısmına doğru indir. İnerken barı sıkıca kavra ve iki yana çekip ayırmaya çalış. Hareket boyunca dirseklerini gövdene yakın tut. Üst kolların yere değene kadar in ve orada dur; ağırlık yere çarpmasın, sekmesin.', 'Barı olabildiğince hızlı yukarı it. İterken bar, bileklerin ve dirseklerin aynı hizada kalsın.']::text[]),
  ('Floor_Press_with_Chains', 'tr', array['J kancalarını, barı rahatça alıp geri koyabileceğin yüksekliğe ayarla. Zincirleri doğrudan barın uçlarına as; zincirlerin uçlarını plakalardan uzak tutmaya çalış.', 'Başın power rack''in ucuna yakın olacak şekilde yere uzan. Kürek kemiklerini birbirine çek, öyle tut ve barı kancalardan al.', 'Barı göğsünün alt kısmına ya da karnının üst kısmına doğru indir. İnerken barı sıkıca kavra ve iki yana çekip ayırmaya çalış. Hareket boyunca dirseklerini gövdene yakın tut. Üst kolların yere değene kadar in ve orada dur; ağırlık yere çarpmasın, sekmesin.', 'Barı olabildiğince hızlı yukarı it. İterken bar, bileklerin ve dirseklerin aynı hizada kalsın.']::text[]),
  ('Flutter_Kicks', 'tr', array['Düz bir sehpaya yüzüstü uzan, kalçan sehpanın kenarına gelsin. Bacakların düz, ayak parmakların yerden iyice yüksekte olsun; kollarını sehpanın üzerine koyup ön kenarını tut.', 'Kalça ve arka bacak kaslarını sık, bacaklarını düz tutarak kalça hizasına kaldır. Bu senin başlangıç pozisyonun.', 'Harekete sol bacağını sağ bacağından yükseğe kaldırarak başla.', 'Ardından sol bacağını indirirken sağ bacağını kaldır.', 'Suda ayak çırpar gibi, her bacak için önerilen tekrar sayısını tamamlayana kadar böyle değiştirerek devam et. Hareketi her an kontrollü yap. İpucu: Bu hareket sırasında normal nefes al.']::text[]),
  ('Foot-SMR', 'tr', array['Bu hareket ayak kaslarının fasyasını esnetir. Otur ve ayakkabılarını çıkar. Bir ayak rulosu ya da benzer bir nesne, örneğin kısa bir PVC boru parçası al ve ayak kemerini üzerine yerleştir. Bu senin başlangıç pozisyonun.', 'Sıkıca bastır ve ayak kemerin boyunca yuvarla. 10-30 saniye sürdür, sonra diğer ayağa geç.']::text[]),
  ('Forward_Drag_with_Press', 'tr', array['Kızağa iki tutamaklı bir zincir ya da halat bağla. Sırtını kızağa dön ve her eline bir tutamak al.', 'Harekete öne bir adım atarak başla. Öne eğil, ilerlemek için bacaklarını ve kalçanı aç. Her adımda dur, dirseklerini açarak ellerini öne doğru it. Sonra yeniden itmeye hazır olduğun başlangıç pozisyonuna gelene kadar adımla.']::text[]),
  ('Frankenstein_Squat', 'tr', array['Bu çalışma, clean ve front squat sırasında barın ve vücudunun nerede durması gerektiğini öğretir.', 'Halteri omuzlarının ön kısmına yerleştir, tutuşu bırak ve kollarını öne doğru uzat. Omuzlarını öne iterek bir raf oluştur; bar boğazına değmeli. Yalnızca kürek kemiklerin öne gitsin: sırt omurganı yuvarlama.', 'Dizlerini ve kalçanı bükerek bacaklarının arasına otur. Gövden dik, kolların yukarıda, omuzların önde olsun; böylece bar yerinde kalır. Arka bacakların baldırlarına değene kadar, en dibe in.', 'Topuğun ön kısmından iterek, dizlerini ve kalçanı açarak yeniden doğrul.']::text[]),
  ('Freehand_Jump_Squat', 'tr', array['Kollarını göğsünün üzerinde çaprazla.', 'Başın yukarıda, sırtın düz olsun; ayaklarını omuz genişliğinde aç.', 'Nefes alırken çömel; üst bacakların yere paralel ya da daha aşağıda olana kadar in. Sırtın düz, göğsün yukarıda kalsın.', 'Şimdi ağırlıklı olarak ayaklarının ön tabanıyla iterek olabildiğince yükseğe, dümdüz yukarı sıçra; üst bacaklarını yay gibi kullan. Sıçrarken nefes ver.', 'Yere değer değmez hemen yeniden çömel ve tekrar sıçra.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Frog_Hops', 'tr', array['Ayakta dur, ellerini başının arkasına koy ve çömel; gövden dik, başın yukarıda olsun. Bu senin başlangıç pozisyonun.', 'Gereğinden yükseğe çıkmadan birkaç fit ileri sıçra. Ayakların yere değince darbeyi bacaklarınla karşıla ve yeniden sıçra. Bunu 5-10 kez yap.']::text[]),
  ('Frog_Sit-Ups', 'tr', array['Sırtın düz olacak şekilde yere ya da egzersiz matına uzan, bacaklarını uzat.', 'Dizlerini bük ve yanlara aç; üst bacaklarının dış yüzü yere ya da mata yakın dursun, ayak tabanların birbirine değsin.', 'İki tabanını birbirine bastır ve olabildiğince kendine doğru çek. Üst bacaklarının dış yüzü yerde kalsın ya da en azından yere neredeyse değsin. İpucu: Bu durumda bacakların bir baklava şekli oluşturmalı.', 'Kollarını önünde çaprazla, her elin karşı omzuna değsin. Bu senin başlangıç pozisyonun.', 'Nefes verirken belini yere bastırıp düzleştir ve gövdeni yukarı doğru kıvır. İpucu: Bu, bir mekiğin ilk çeyreğini yapmak gibidir. Yukarıda bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Front_Barbell_Squat', 'tr', array['Güvenlik için bu hareketi squat sehpasının içinde yap. Önce barı boyuna en uygun yükseklikte sehpaya yerleştir. Yükseklik doğruysa ve bar yüklendiyse kollarını alttan bara getir; dirseklerin yukarıda, üst kolların yere paralelin biraz üstünde olsun. Barı deltoid kaslarının üstüne oturt, kollarını çaprazla ve tam kontrol için barı kavra.', 'Barı sehpadan kaldır: önce bacaklarınla it, aynı anda gövdeni doğrult.', 'Sehpadan uzaklaş. Orta genişlikte dur: ayakların omuz genişliğinde, parmak uçların hafifçe dışa dönük. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Bu senin başlangıç pozisyonun. Not: Burada anlatılan orta duruş bacağı genel olarak çalıştırır; istersen üç duruş genişliğinden herhangi birini seçebilirsin.', 'Dizlerini bükerek barı yavaşça indirmeye başla; duruşun dik, başın yukarıda olsun. Üst bacakla baldır arasındaki açı 90 derecenin biraz altına inene kadar devam et; bu noktada üst bacakların yere paralelin altındadır. İnerken nefes al. İpucu: Hareket doğru yapıldıysa dizlerinin ön yüzü ayak parmaklarınla aynı hayali dik çizgi üzerindedir. Dizlerin bu çizgiyi, yani ayak parmaklarını geçiyorsa dize gereksiz yük bindiriyorsun ve hareket yanlış yapılmış demektir.', 'Nefes verirken barı kaldır: ağırlıklı olarak ayağının ortasıyla yeri it, bacaklarını yeniden düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Front_Barbell_Squat_To_A_Bench', 'tr', array['Güvenlik için bu hareketi squat sehpasının içinde yap. Önce arkana düz bir sehpa koy ve barı boyuna en uygun yükseklikte askıya yerleştir. Yükseklik doğruysa ve bar yüklendiyse kollarını alttan bara getir; dirseklerin yukarıda, üst kolların yere paralelin biraz üstünde olsun. Barı deltoid kaslarının üstüne oturt, kollarını çaprazla ve tam kontrol için barı kavra.', 'Barı askıdan kaldır: önce bacaklarınla it, aynı anda gövdeni doğrult.', 'Askıdan uzaklaş. Orta genişlikte dur: ayakların omuz genişliğinde, parmak uçların hafifçe dışa dönük. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Bu senin başlangıç pozisyonun. Not: Burada anlatılan orta duruş bacağı genel olarak çalıştırır; istersen üç duruş genişliğinden herhangi birini seçebilirsin.', 'Dizlerini bükerek barı yavaşça indirmeye başla; duruşun dik, başın yukarıda olsun. Kalçan sehpaya değene kadar in. İnerken nefes al. İpucu: Hareket doğru yapıldıysa dizlerinin ön yüzü ayak parmaklarınla aynı hayali dik çizgi üzerindedir. Dizlerin bu çizgiyi, yani ayak parmaklarını geçiyorsa dize gereksiz yük bindiriyorsun ve hareket yanlış yapılmış demektir.', 'Nefes verirken barı kaldır: ağırlıklı olarak topuklarınla yeri it, bacaklarını yeniden düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Front_Box_Jump', 'tr', array['Uygun yükseklikte bir kasayı 1-2 fit önüne koy. Ayaklarını omuz genişliğinde açarak dur. Bu senin başlangıç pozisyonun.', 'Sıçramaya hazırlanmak için hafifçe çömel ve kollarını geriye savur.', 'Bu pozisyondan yaylanarak çık: kalçanı, dizlerini ve ayak bileklerini açıp olabildiğince yükseğe sıçra. Kollarını öne ve yukarı savur.', 'Kasanın üzerine dizlerin bükük in, darbeyi bacaklarınla karşıla. Kasadan yere geri atlayabilirsin, ama bacaklarını sırayla indirerek adımla inmek daha iyidir.']::text[]),
  ('Front_Cable_Raise', 'tr', array['Alt makaralı bir kablo istasyonunda ağırlığı seç. Alt makaraya bağlı tek el tutamağını sol elinle kavra.', 'Sırtını makaraya dön. Kolunu dümdüz aşağı sarkıt; tutamak üst bacağının önünde, avuç için üst bacağına dönük olsun. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut, sallanma; sol kolunu öne doğru kaldır. Dirseğin hafif bükük, avuç için hep aşağı baksın. Kolun yere paralelin biraz üstüne çıkana kadar devam et. Kaldırırken nefes ver ve yukarıda bir saniye dur.', 'Nefes alırken kolunu yavaşça başlangıç pozisyonuna indir.', 'Bu kolla önerilen tekrar sayısını tamamlayınca kol değiştir ve hareketi sağ kolunla yap.']::text[]),
  ('Front_Cone_Hops_or_hurdle_hops', 'tr', array['Konileri ya da başka alçak engelleri, aralarında birkaç fit bırakarak sıra halinde diz.', 'İlk koninin önünde, ayakların omuz genişliğinde açık dur. Bu senin başlangıç pozisyonun.', 'İki ayağınla birden ilk koninin üzerinden atla; atlarken iki kolunu da savur.', 'Dizlerini bükerek inişin darbesini yumuşat ve hiç beklemeden yaylanıp sonraki koninin üzerinden atla.', 'Bütün konilerin üzerinden atlayana kadar devam et.']::text[]),
  ('Front_Dumbbell_Raise', 'tr', array['İki dambıl al ve gövden dik olacak şekilde ayakta dur. Dambılları kolların uzanmış halde üst bacaklarının önünde tut; avuç içlerin üst bacaklarına baksın. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut, sallanma; sol dambılı öne doğru kaldır. Dirseğin hafif bükük, avuç için hep aşağı baksın. Kolun yere paralelin biraz üstüne çıkana kadar devam et. Kaldırırken nefes ver ve yukarıda bir saniye dur. Bu duruştan sonra nefes al.', 'Şimdi bu dambılı yavaşça başlangıç pozisyonuna indirirken aynı anda sağ dambılı kaldır.', 'Her kol önerilen tekrar sayısını tamamlayana kadar böyle sırayla devam et.']::text[]),
  ('Front_Incline_Dumbbell_Raise', 'tr', array['Her eline bir dambıl al ve 30 ile 60 derece arasında bir açıya ayarlanmış eğimli sehpaya otur. İpucu: Kası her seferinde biraz farklı çalıştırmak için açıyı değiştirebilirsin.', 'Kollarını dümdüz öne uzat; avuç içlerin aşağı baksın, dambıllar üst bacaklarının yaklaşık 1 inç üzerinde dursun. Bu senin başlangıç pozisyonun.', 'Dirseklerin kilitli halde dambılları yavaşça, dümdüz yukarı kaldır; omuzlarının biraz üstüne gelsinler. Yukarıda bir saniye sık ve kaldırırken nefes verdiğinden emin ol. İpucu: Başın hep sehpaya yaslı, ayakların hep yerde kalsın.', 'Nefes alırken kollarını başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Front_Leg_Raises', 'tr', array['Bir sandalyenin ya da başka bir desteğin yanında dur ve tek elinle tutun.', 'Bacağını düz tutarak öne doğru savur. Sonra aşağı ve geriye savur; esnekliğin elverdiği kadar geriye götür. 5-10 kez tekrarla, sonra bacak değiştir.']::text[]),
  ('Front_Plate_Raise', 'tr', array['Dik dur ve bir ağırlık plakasını iki elinle saat 3 ve 9 konumlarından tut. Avuç içlerin birbirine baksın. Kolların uzanmış ve sabit, dirseklerin hafif bükük olsun; plaka önünde, bel hizana yakın, inebildiği kadar aşağıda dursun. İpucu: Kollar hareket boyunca bu pozisyonda kalır. Bu senin başlangıç pozisyonun.', 'Nefes verirken plakayı yavaşça, omuz hizasının biraz üstüne kadar kaldır. Kasılmayı bir saniye koru. İpucu: Ağırlığı sallama, dirseklerini de bükme. Gövden de hareket boyunca sabit kalmalı.', 'Nefes alırken plakayı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Front_Raise_And_Pullover', 'tr', array['Düz bir sehpaya uzan ve halteri avuç içlerin aşağı bakacak şekilde, ellerin arasında yaklaşık 15 inç bırakarak tut.', 'Barı üst bacaklarının üzerine koy. Kollarını uzat ve dirseklerin hafif bükük halde sabitle. Bu senin başlangıç pozisyonun.', 'Nefes alırken ağırlığı, kolların düz kalacak şekilde yarım daire çizerek kaldır. Bar öbür tarafta, başının üzerinde olana kadar aynı hareketi sürdür. (İpucu: Bar yaklaşık 180 derece yol alır.) Bu noktada kolların yere paralel, avuç içlerin tavana dönük olmalı.', 'Nefes verirken hareketi tersine çevirerek halteri başlangıç pozisyonuna getir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Front_Squat_Clean_Grip', 'tr', array['Önce barı omuz hizasının biraz altında bir sehpaya yerleştir. Barı deltoid kaslarının üstüne oturt; köprücük kemiklerine bastırsın ve boğazına hafifçe değsin. Ellerin clean tutuşunda olsun: bara yalnızca parmakların değsin ve yerinde kalmasına yardım etsin.', 'Barı sehpadan kaldır: önce bacaklarınla it, aynı anda gövdeni doğrult. Sehpadan uzaklaş ve orta genişlikte dur; ayakların omuz genişliğinde, parmak uçların hafifçe dışa dönük. Başın ve dirseklerin hep yukarıda kalsın. Bu senin başlangıç pozisyonun.', 'Dizlerini bük ve bacaklarının arasına otur. Arka bacakların baldırlarına yaslanana kadar in. Dizlerini ayaklarınla aynı hizada tut: çömelirken abdüktörlerini bilinçli kullanarak dizlerini dışa it.', 'Nefes verirken barı kaldır: ağırlıklı olarak topuğunla ya da ayağının ortasıyla yeri it, bacaklarını yeniden düzelt ve başlangıç pozisyonuna dön.']::text[]),
  ('Front_Squats_With_Two_Kettlebells', 'tr', array['İki kettlebell''i clean ile omuzlarına al: bacaklarını ve kalçanı açarken kettlebell''leri omuzlarına doğru çek ve bu sırada bileklerini çevir.', 'Hep dümdüz karşıya bak. Olabildiğince derine çömel ve dipte dur. İnerken dizlerini dışa it. Bacaklarının arasına otur; gövden dik, başın ve göğsün yukarıda olsun.', 'Topuklarından iterek yeniden yüksel ve tekrarla.']::text[]),
  ('Front_Two-Dumbbell_Raise', 'tr', array['İki dambıl al ve gövden dik olacak şekilde ayakta dur. Dambılları kolların uzanmış halde üst bacaklarının önünde tut; avuç içlerin üst bacaklarına baksın. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut, sallanma; iki dambılı birden öne doğru kaldır. Dirseklerin hafif bükük, avuç içlerin hep aşağı baksın. Kolların yere paralelin biraz üstüne çıkana kadar devam et. Kaldırırken nefes ver ve yukarıda bir saniye dur.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Full_Range-Of-Motion_Lat_Pulldown', 'tr', array['Ayakta dur ya da yüksek bir sehpaya otur ve üst makaralara bağlı iki üzengi tutamağını kavra. Her birini karşı elinle tut; böylece kolların üstünde çaprazlanır, avuç içlerin öne bakar.', 'Göğsün yukarıda, belinde hafif bir çukur olsun; tutamakları normal bir lat pulldown yapar gibi aşağı çek. Buradaki hareket yolu daha çok bir yay çizer. Çekerken ellerini çevir; en altta avuç içlerin öne değil, birbirine baksın. Yavaşça başlangıç pozisyonuna dön ve tekrarla.']::text[]),
  ('Gironda_Sternum_Chins', 'tr', array['Barfiks barını omuz genişliğinde, alttan tutuşla kavra.', 'Kolların tam uzanmış halde asıl, göğsünü öne çıkar ve geriye yaslan. İpucu: Hareketin tamamında geriye yaslanmış kalırsın. Bu senin başlangıç pozisyonun.', 'Kendini bara doğru çekmeye başla. Omurgan hareket boyunca kavisli, başın geriye yatık ve bardan olabildiğince uzakta olsun. Çekerken nefes ver. İpucu: Hareketin üst kısmında kalçan ve bacakların yerle yaklaşık 45 derecelik açı yapar.', 'Köprücük kemiğin barı geçene ve göğsünün alt kısmı, yani göğüs kemiği bölgen bara değene kadar çekmeyi sürdür. Bu kasılmayı bir saniye koru. İpucu: Bu bölümü bitirdiğinde başın yere paralel olur.', 'Nefes alırken yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Glute_Ham_Raise', 'tr', array['Önce makineyi vücuduna göre ayarla. Yüzüstü uzan; ayakların ruloların arasında, ayak plakasına dayalı olsun. Dizlerin yastığın hemen arkasında durmalı.', 'Hareketin en alt noktasından başla. Sırtını kavisli tut ve dizlerini bükerek hareketi başlat. Bunu yaparken ayak parmaklarını plakaya bastır. Üst gövden düz kalsın; vücudun dik duruma gelene kadar devam et.', 'İnişini kontrol altında tutarak başlangıç pozisyonuna dön.']::text[]),
  ('Glute_Kickback', 'tr', array['Yere ya da egzersiz matına diz çök ve belden öne eğil. Kollarını gövdene dik olacak şekilde önüne uzat; böylece dizler üzerinde şınav pozisyonuna gelirsin, ellerin omuz genişliğinde açık. Başın öne baksın. Dizlerin, arka bacakla baldır arasında 90 derecelik açı oluşacak şekilde bükülü olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken sağ bacağını, arka bacağın sırtınla aynı hizaya gelene kadar kaldır; dizdeki 90 derecelik açıyı koru. Hareket boyunca kalça kaslarını sık ve yukarıda bir saniye bekle. İpucu: Hareketin sonunda üst bacak yere paralel, baldır ise yere dik olmalı.', 'Nefes alırken ilk pozisyona dön ve aynısını sol bacağınla yap.', 'Önerilen bütün tekrarlar bitene kadar bacak değiştirerek devam et.']::text[]),
  ('Goblet_Squat', 'tr', array['Ayakta dur ve hafif bir kettlebell''i boynuzlarından tutup göğsüne yakın taşı. Bu senin başlangıç pozisyonun.', 'Bacaklarının arasına çömel; arka bacakların baldırlarına yaslanana kadar in. Göğsün ve başın yukarıda, sırtın düz kalsın.', 'En altta dur ve dirseklerinle dizlerini dışa it. Başlangıç pozisyonuna dön ve 10-20 tekrar yap.']::text[]),
  ('Good_Morning', 'tr', array['Barı omuz yüksekliğindeki sehpaya koyarak başla. Barı omuzlarının tepesine değil, power squat''ta olduğu gibi omuzlarının arka kısmına al. Sırtını sıkı, kürek kemiklerini birbirine çekili ve dizlerini hafif bükük tut. Sehpadan geriye adımla.', 'Kalçadan bükülerek başla: kalçanı geriye it ve gövden yere neredeyse paralel olana kadar öne eğil. Sırtın kavisli, boyun omurların doğru hizada kalsın.', 'Hareketi tersine çevir: kalça ve arka bacak kaslarınla kalçanı aç. Başlangıç pozisyonuna dönene kadar devam et.']::text[]),
  ('Good_Morning_off_Pins', 'tr', array['Barı yaklaşık karın yüksekliğindeki sehpaya koyarak başla. Barın altına eğil ve barı omuzlarının tepesine değil, power squat''ta olduğu gibi omuzlarının arka kısmına al. Yükseklik doğruysa, eğildiğinde gövden yere neredeyse paralel olur. Sırtını sıkı, kürek kemiklerini birbirine çekili ve dizlerini hafif bükük tut. Sırtın kavisli, boyun omurların doğru hizada kalsın.', 'Harekete kalça ve arka bacak kaslarınla kalçanı açarak başla; ağırlıkla birlikte dik duruma gel. Ağırlığı yavaşça yeniden pimlerin üzerine indirip başlangıç pozisyonuna dön.']::text[]),
  ('Gorilla_Chin_Crunch', 'tr', array['Barfiks barına alttan tutuşla, avuç içlerin sana bakacak şekilde ve omuz genişliğinden biraz geniş asıl.', 'Dizlerini 90 derece bük: baldırların yere paralel, üst bacakların yere dik kalsın. Bu senin başlangıç pozisyonun.', 'Nefes verirken kendini yukarı çek ve aynı anda dizlerini crunch yaparak göğüs hizasına kadar topla. Burnun barla aynı hizaya gelir gelmez yükselmeyi bırak. İpucu: Bu noktaya vardığında crunch da aynı anda bitmiş olmalı.', 'Yavaşça nefes almaya başla ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Groin_and_Back_Stretch', 'tr', array['Yere otur; dizlerin bükük, ayakların bitişik olsun.', 'Parmaklarını başının arkasında kenetle. Bu senin başlangıç pozisyonun.', 'Gövdeni aşağı doğru kıvır ve dirseklerini üst bacaklarının iç yüzüne getir. Kısa bir duraklamadan sonra başın yukarıda, sırtın düz halde başlangıç pozisyonuna dön. 10-20 tekrar yap.']::text[]),
  ('Groiners', 'tr', array['Yerde şınav pozisyonu al. Bu senin başlangıç pozisyonun.', 'İki bacağınla birden öne sıçra; ayakların ellerinin yanına insin. Sıçrarken başını yukarıda tut.', 'Başlangıç pozisyonuna dön ve hareketi hemen tekrarla; 10-20 tekrar boyunca sürdür.']::text[]),
  ('Hack_Squat', 'tr', array['Sırtını makinenin sırt yastığına yasla ve omuzlarını omuz yastıklarının altına yerleştir.', 'Ayaklarını platforma omuz genişliğinde, yani orta genişlikte bir duruşla koy; ayak uçların hafifçe dışa baksın. İpucu: Başını hep dik tut, sırtını da yastıktan hiç ayırma.', 'Yandaki tutamakları kavra ve emniyet kollarını aç (çoğu makinede bunun için tutamakları öne bakan konumdan çapraz konuma çevirirsin).', 'Dizlerini kilitlemeden bacaklarını düzelt. Bu senin başlangıç pozisyonun. Not: Burada, bacakları genel olarak geliştiren ve yukarıda anlatılan orta duruş kullanılıyor; ama üç ayak duruşundan istediğini seçebilirsin.', 'Dizlerini bükerek kızağı yavaşça indir; gövden dik, başın yukarıda, sırtın hep yastıkta kalsın. Üst bacakla baldır arasındaki açı 90 derecenin biraz altına düşene kadar in; bu noktada üst bacakların yere paralel çizginin altına iner. Hareketin bu kısmında nefes al. İpucu: Hareketi doğru yaptıysan dizlerinin önü ile ayak parmakların, öne dik duran hayali bir düz çizgi üzerinde olur. Dizlerin bu çizgiyi, yani ayak parmaklarını geçiyorsa dizine gereksiz yük bindiriyorsun ve hareketi yanlış yapmış oluyorsun.', 'Nefes verirken ağırlıklı olarak topuklarınla iterek kızağı kaldır; bacakların yeniden düzelsin ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Hammer_Curls', 'tr', array['Gövden dik şekilde ayakta dur, iki elinde birer dambıl olsun ve kolların aşağıya uzansın. Dirseklerini gövdene yakın tut.', 'Avuç içlerini gövdene doğru çevir. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve bisepsini kasarak ağırlıkları öne doğru kaldır. Biseps tam kasılana ve dambıllar omuz hizasına gelene kadar devam et. Tepede kısa bir an bekle ve bisepsini sık. İpucu: Dirseği yerinden oynatmamaya, yalnızca ön kolu hareket ettirmeye odaklan.', 'Kısa beklemeden sonra nefes al ve dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Hammer_Grip_Incline_DB_Bench_Press', 'tr', array['Eğimli sehpaya sırtüstü yaslan; iki elinde birer dambıl olsun ve dambıllar uyluklarının üstünde dursun. Avuç içlerin birbirine baksın.', 'Uyluklarından destek alarak dambılları sırayla, her seferinde tek kolla yukarı al ve omuz genişliğinde tut.', 'Dambıllar omuz genişliğindeyken nötr tutuşu koru, avuç içlerin birbirine baksın. Dirseklerini yana aç; üst kolların omuzlarınla aynı hizada (gövdeye dik) olsun ve dirseklerini üst kolla ön kol arasında 90 derecelik açı oluşacak kadar bük. Bu senin başlangıç pozisyonun.', 'Nefes alırken ağırlıkları yavaşça yanlarına doğru indir. Dambılları her an tam kontrol altında tut.', 'Nefes verirken dambılları göğüs kaslarınla yukarı it. Tepede kollarını kilitle, bir saniye bekle, sonra yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Belirlenen tekrar sayısı kadar tekrarla.', 'Bitirince dambılları önce yeniden uyluklarına, sonra yere koy. Dambılları bırakmanın en güvenli yolu budur.']::text[]),
  ('Hamstring-SMR', 'tr', array['Yere otur ve bacaklarını foam roller''ın üzerine uzat; roller üst bacaklarının arkasında dursun. Ağırlığını taşımaya yardım etmesi için ellerini yanına ya da arkana koy. Bu senin başlangıç pozisyonun.', 'Ellerinden güç alarak kalçanı yerden kaldır ve ağırlığını roller üzerinde tek bacağa ver. Esnettiğin bacağın arka bacak kaslarını gevşet.', 'Kalçanın hemen altından diz arkasının hemen üstüne kadar yuvarlan, gergin noktalarda 10-30 saniye bekle. Diğer bacakla tekrarla.']::text[]),
  ('Hamstring_Stretch', 'tr', array['Sırtüstü yat ve bir bacağını, kalça eklemi doksan derece olacak şekilde yukarı uzat. Diğer bacağın yerde düz kalsın.', 'Kaldırdığın ayağın tarağına bir kemer, bant ya da ip geçir. Bu senin başlangıç pozisyonun.', 'Baldır ve arka bacakta gerginlik hissedene kadar kemeri çek. Esnemeyi 10-30 saniye tut, sonra diğer bacakla tekrarla.']::text[]),
  ('Handstand_Push-Ups', 'tr', array['Sırtını duvara ver, belden eğil ve iki elini omuz genişliğinde yere koy.', 'Kolların düz şekilde ayaklarını savurarak duvara doğru amuda kalk. Baş aşağı durmalısın; kolların ve bacakların tam uzanmış, bütün vücudun olabildiğince düz olsun. İpucu: İlk kez deniyorsan birinden yardım iste. Ayrıca aşağı bakma, başın duvara dönük kalsın.', 'Nefes alırken başın neredeyse yere değene kadar kendini yavaşça indir. İpucu: Başını yaralamamak için yavaş inmek son derece önemli.', 'Nefes verirken dirseklerin neredeyse kilitlenene kadar kendini yavaşça yukarı it.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Hang_Clean', 'tr', array['Barı omuz genişliğinde, çift üstten tutuşla ya da kanca tutuşla kavra; bar uyluğunun ortası hizasında asılı dursun. Sırtın düz ve hafifçe öne eğik olsun.', 'Kalça, diz ve ayak bileklerini patlayıcı şekilde açarak ağırlığı yukarı sür. Bunu yaparken omuzlarını kulaklarına doğru silk.', 'Hemen toparlan: topuklarından it, gövden dik, dirseklerin yukarıda kalsın. Ayağa tam kalkana kadar devam et.']::text[]),
  ('Hang_Clean_-_Below_the_Knees', 'tr', array['Barı omuz genişliğinde, çift üstten tutuşla ya da kanca tutuşla kavra; bar dizlerinin hemen altında asılı dursun. Sırtın düz ve hafifçe öne eğik olsun.', 'Kalça, diz ve ayak bileklerini patlayıcı şekilde açarak ağırlığı yukarı sür, bu sırada omuzlarını kulaklarına doğru silk. Tam açılmaya ulaşınca üçüncü çekişe geç: omuzlarını sertçe silk ve kollarını bük, dirseklerin yukarı ve dışa gitsin.', 'Açılmanın en üst noktasında kendini sertçe aşağı çek ve dirseklerini barın altına döndür. Barı ön squat pozisyonunda karşıla; ne kadar derine ineceğin, üçüncü çekişin sonunda barın ulaştığı yüksekliğe bağlıdır. Bar öne itilmiş omuzlarına otursun, boğazına hafifçe değsin ve ellerin gevşek kalsın. Squatın en alt noktasına kadar inmeye devam et; bu, toparlanmayı kolaylaştırır.', 'Hemen toparlan: topuklarından it, gövden dik, dirseklerin yukarıda kalsın. Ayağa tam kalkana kadar devam et.']::text[]),
  ('Hang_Snatch', 'tr', array['Barı geniş tut; üstten tutuş ya da kanca tutuş kullan. Ayakların tam kalçanın altında, ayak uçların dışa dönük olsun. Dizlerini hafifçe bük ve gövdeni öne eğ. Omurgan tam düz, başın öne dönük olsun. Bar kalça hizasında dursun. Bu senin başlangıç pozisyonun.', 'Bacaklarını ve kalçanı patlayıcı şekilde aç. Açılmanın en üst noktasında omuzlarını silk ve dirseklerinin yana doğru bükülmesine izin ver.', 'Ayaklarını karşılama pozisyonuna alırken kendini güçlü şekilde barın altına çek ve barı başının üstüne kaldır. Barı vücudun olabildiğince alçakta, kolların başının üstünde tam uzanmış halde karşıla.', 'Ağırlık başının üstündeyken ayağa kalk. Ardından ağırlığı kontrollü şekilde yere indir.']::text[]),
  ('Hang_Snatch_-_Below_Knees', 'tr', array['Barı geniş tut; üstten tutuş ya da kanca tutuş kullan. Ayakların tam kalçanın altında, ayak uçların dışa dönük olsun. Dizlerini hafifçe bük ve gövdeni öne eğ. Omurgan tam düz, başın öne dönük olsun. Bar dizlerinin hemen altında dursun. Bu senin başlangıç pozisyonun.', 'Bacaklarını ve kalçanı patlayıcı şekilde aç. Açılmanın en üst noktasında omuzlarını silk ve dirseklerinin yana doğru bükülmesine izin ver.', 'Ayaklarını karşılama pozisyonuna alırken kendini güçlü şekilde barın altına çek ve barı başının üstüne kaldır. Barı vücudun olabildiğince alçakta, kolların başının üstünde tam uzanmış halde karşıla.', 'Ağırlık başının üstündeyken ayağa kalk, sonra ağırlığı kontrollü şekilde yere indir.']::text[]),
  ('Hanging_Bar_Good_Morning', 'tr', array['Barı zincirlerle ya da askı kayışlarıyla bir rack''e, yaklaşık karın hizasında as.', 'Barın altına eğil ve barı trapezin üstüne değil, power squat''taki gibi omuzlarının arkasına yerleştir. Yükseklik doğruysa eğildiğinde gövden yere neredeyse paralel olur. Sırtını sıkı tut, kürek kemiklerini birbirine yaklaştır ve dizlerini hafifçe bük. Sırtındaki kavisi koru, boyun omurlarını da doğru hizada tut.', 'Harekete, kalça ve arka bacak kaslarınla kalçanı açarak başla; ağırlıkla birlikte ayağa kalk.', 'Ağırlığı yavaşça başlangıç pozisyonuna indir; burada ağırlığı yeniden zincirler taşır.']::text[]),
  ('Hanging_Leg_Raise', 'tr', array['Geniş ya da orta tutuşla barfiks barına asıl, iki kolun da yukarıda tam uzanmış olsun. Bacakların dümdüz aşağı sarksın, leğen kemiğin hafifçe geriye dönük olsun. Bu senin başlangıç pozisyonun.', 'Bacaklarını, gövdenle 90 derecelik açı yapana kadar kaldır. Kaldırırken nefes ver ve kasılmayı bir saniye kadar tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Hanging_Pike', 'tr', array['Bacakların ve ayakların bitişik şekilde barfiks barına asıl; omuz genişliğinden biraz daha geniş bir üstten tutuş (avuç içleri senden uzağa bakar) kullan. İpucu: Bara tutunmayı kolaylaştırmak için bilek sargısı kullanabilirsin.', 'Dizlerini 90 derece bük ve üst bacaklarını öne getir; baldırların yere dik, uylukların yere paralel olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken bacaklarını, kaval kemiklerin üstündeki bara neredeyse değene kadar yukarı çek. İpucu: Tepedeyken bacaklarını olabildiğince düzeltmeye çalış.', 'Bacaklarını olabildiğince yavaş şekilde başlangıç pozisyonuna indir. İpucu: Sallanmaktan ve hız almaktan her zaman kaçın.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Heaving_Snatch_Balance', 'tr', array['Bu çalışma koparma hareketini öğrenmene yardım eder. Hafif bir ağırlığı omuzlarının arkasına yerleştirerek başla. Ayakların kalça genişliğinden biraz daha açık, ayak uçların dışa dönük olsun; squat yaparken durduğun pozisyonun aynısı.', 'Dizlerini hafifçe bükerek çök ve yukarı fırlayarak barın yükünü kısa bir an hafiflet. Kendini barın altına it; tam squata inerken barı başının üstüne kaldır.', 'Yeniden ayağa kalk.']::text[]),
  ('Heavy_Bag_Thrust', 'tr', array['Bu egzersiz için ağır bir kum torbası kullan. Torbanın yanında dik dur; ayakların biri önde biri arkada, oldukça açık olsun. Elini torbaya yaklaşık göğüs hizasında koy. Bu senin başlangıç pozisyonun.', 'Belinden dönerek torbayı olabildiğince sert şekilde öne it. Hareketi hızlı yap ve torbayı vücudundan uzağa gönder.', 'Torba geri sallanınca bu adımları tersine çevirerek onu karşıla.']::text[]),
  ('High_Cable_Curls', 'tr', array['İki yüksek makaranın arasında dur ve her eline bir tutamak al. Üst kollarını yere paralel konuma getir, avuç içlerin sana baksın. Bu senin başlangıç pozisyonun.', 'Tutamakları kulaklarının yanına gelene kadar kendine doğru çek; bunu yaparken bisepsini kas ve nefes ver. Üst kolların sabit kalsın, yalnızca ön kolların hareket etsin. Kasılı pozisyonda bir saniye bekle ve bisepsini sık.', 'Kollarını yavaşça başlangıç pozisyonuna geri götür.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Hip_Circles_prone', 'tr', array['Yerde ellerinin ve dizlerinin üzerine gel. Duruşunu bozmadan bükülü bir dizini yerden kaldır. Bu senin başlangıç pozisyonun.', 'Dizini bükülü tut ve uyluk kemiğini bir yay çizecek şekilde döndür; dizinle büyük bir daire çizmeye çalış.', 'Bunu yavaşça birkaç tekrar yap, sonra diğer tarafla tekrarla.']::text[]),
  ('Hip_Extension_with_Bands', 'tr', array['Lastik bandın bir ucunu bir direğin alt kısmına, diğer ucunu bir ayak bileğine bağla.', 'Yüzünü bandın bağlı olduğu noktaya dön ve dengeni sağlamak için direğe tutun.', 'Başın ve göğsün dik dururken bantlı bacağını, dizini bükmeden gidebildiği kadar geriye götür.', 'Bacağını başlangıç pozisyonuna geri getir.']::text[]),
  ('Hip_Flexion_with_Band', 'tr', array['Lastik bandın bir ucunu bir direğin alt kısmına, diğer ucunu bir ayak bileğine bağla.', 'Sırtını bandın bağlı olduğu noktaya dön.', 'Başın ve göğsün dik dururken dizini 90 dereceye kadar kaldır ve bekle.', 'Bacağını başlangıç pozisyonuna geri getir.']::text[]),
  ('Hip_Lift_with_Band', 'tr', array['Uygun bir lastik bant seç, bandı iki yanında sabitle ve rack''in ortasına uzan. Rack''inde pim yoksa bandı ağır dambıllarla ya da benzer cisimlerle sabitleyebilirsin; yeter ki yerlerinden oynamasınlar.', 'Bant tam kalçanın üzerinden geçecek şekilde yerini ayarla. Dizlerini bük ve ayak tabanlarını yere bas. Ellerin yerde durabilir ya da bandı yerinde tutabilir.', 'Omuzların yerde kalsın; topuklarından iterek kalçanı banda karşı kaldırabildiğin kadar yukarı kaldır.', 'Hareketin tepesinde bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Hug_A_Ball', 'tr', array['Yere otur.', 'Pilates topunu iki bacağının arasına al ve kalçanı yere doğru indir.', 'Vücudunu desteklemek için kollarınla topa sarıl. Bacaklarını, ayak tabanların yere basacak ve dizlerin ayak bileklerinin üstüne gelecek şekilde ayarla. Top senden uzağa yuvarlanıp seni kalçanın üstüne geri düşürmesin diye onu sıkı tut.']::text[]),
  ('Hug_Knees_To_Chest', 'tr', array['Sırtüstü yat ve iki dizini göğsüne çek.', 'Kollarınla dizlerinin üstünden değil altından tut (üstten tutmak diz eklemlerine fazla baskı yapar).', 'Dizlerini yavaşça omuzlarına doğru çek. Bu hareket kalça kaslarını da esnetir.']::text[]),
  ('Hurdle_Hops', 'tr', array['Engelleri ya da başka küçük bariyerleri aralarında birkaç fit bırakarak sıra halinde diz.', 'İlk engelin önünde ayakların omuz genişliğinde açık dur. Bu senin başlangıç pozisyonun.', 'İki ayağınla birden ilk engelin üzerinden atla; atlarken iki kolunu da savur.', 'Yere inişin darbesini dizlerini bükerek karşıla ve ilk sıçramadan yaylanarak sonraki engelin üzerinden atla. Bütün engelleri atlayana kadar devam et.']::text[]),
  ('Hyperextensions_Back_Extensions', 'tr', array['Hiperekstansiyon sehpasına yüzüstü uzan ve ayak bileklerini ayak yastıklarının altına sağlamca yerleştir.', 'Ayarlanabiliyorsa üst yastığı, uyluklarının üst kısmı geniş yastığa düz yaslanacak ve belden rahatça eğilebileceğin kadar boşluk kalacak şekilde ayarla.', 'Vücudun düzken kollarını önünde çaprazla (tercih edilen yol) ya da başının arkasına al. Bu senin başlangıç pozisyonun. İpucu: Ek direnç için çaprazladığın kollarının altında, önünde bir ağırlık plakası da tutabilirsin.', 'Sırtını düz tutarak belden yavaşça, gidebildiğin kadar öne eğil. Bu sırada nefes al. Arka bacağında iyi bir gerilme hissedene ve sırtını yuvarlamadan daha fazla ilerleyemeyecek hale gelene kadar devam et. İpucu: Bu egzersizde sırtını asla yuvarlama. Ayrıca bazıları diğerlerinden daha aşağı inebilir; önemli olan, sırtını yuvarlamadan vücudunun izin verdiği kadar inmen.', 'Nefes alırken gövdeni yavaşça ilk pozisyona kaldır. İpucu: Sırtını düz çizginin ötesine kavislendirme isteğine kapılma. Ayrıca sırtını sakatlanmadan korumak için gövdeni hiçbir zaman savurma.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Hyperextensions_With_No_Hyperextension_Bench', 'tr', array['Biri bacaklarını bastırırken düz bir sehpada, kalçan sehpanın ucundan sarkana kadar öne kay. İpucu: Bütün üst gövden yere doğru sarkmalı. Ayrıca hiperekstansiyon sehpasındakiyle aynı pozisyonda olursun, ama düz sehpa daha alçak olduğu için hareket açıklığı daha kısa kalır.', 'Vücudun düzken kollarını önünde çaprazla (tercih edilen yol) ya da başının arkasına al. Bu senin başlangıç pozisyonun. İpucu: Ek direnç için çaprazladığın kollarının altında, önünde bir ağırlık plakası da tutabilirsin.', 'Sırtını düz tutarak belden yavaşça, gidebildiğin kadar öne eğil. Bu sırada nefes al. Neredeyse yere değene ya da arka bacağında iyi bir gerilme hissedene kadar devam et (hangisi önce olursa). İpucu: Bu egzersizde sırtını asla yuvarlama.', 'Nefes verirken gövdeni yavaşça ilk pozisyona kaldır. İpucu: Sırtını düz çizginin ötesine kavislendirme isteğine kapılma. Ayrıca sırtını sakatlanmadan korumak için gövdeni hiçbir zaman savurma.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('IT_Band_and_Glute_Stretch', 'tr', array['Yerde yatarken bir ayağına kemer, ip ya da bant geçir ve o bacağı düz tutarak gövdenin üzerinden karşı tarafa götür. Bu başlangıç pozisyonun.', 'Ayağını yere değdirmeden kemeri çek; gerilimi kullanarak ayak parmaklarını kendine doğru çek. 10-20 saniye tut, sonra diğer tarafta tekrarla.']::text[]),
  ('Iliotibial_Tract-SMR', 'tr', array['Yan yat; alttaki bacağın, kalça ile diz arasındaki bölgeden foam roller''ın üzerinde dursun. Diğer bacağını önünde çaprazlayabilirsin.', 'Alttaki bacağına dayanabildiğin kadar ağırlık ver; bu bacağın yere değmesi gerekmez. Esnettiğin bacağın kaslarını mutlaka gevşet.', 'Bacağını roller üzerinde kalçadan dize kadar yuvarla, gergin noktalarda 10-30 saniye bekle. Diğer bacakla tekrarla.']::text[]),
  ('Inchworm', 'tr', array['Ayakların birbirine yakın şekilde ayakta dur. Bacaklarını düz tutarak aşağı uzan ve ellerini hemen önünde yere koy. Bu senin başlangıç pozisyonun.', 'Ellerinle yavaşça, sol ve sağ sırayla öne doğru yürü. Bunu yaparken yalnızca kalçadan bükül, bacakların düz kalsın.', 'Vücudun şınav pozisyonunda yere paralel olana kadar devam et.', 'Şimdi ellerini yerinde tut ve ayaklarınla yavaşça, her seferinde yalnızca birkaç inç ilerleyen kısa adımlar at.', 'Bacaklarını düz tutarak ayakların ellerinin yanına gelene kadar yürümeye devam et.']::text[]),
  ('Incline_Barbell_Triceps_Extension', 'tr', array['Halteri omuz genişliğinden biraz dar, üstten tutuşla (avuç içleri aşağı bakar) kavra.', '45-75 derece arasında herhangi bir açıya ayarlanmış eğimli sehpaya sırtüstü yaslan.', 'Barı kolların düz, dirseklerin içeride olacak şekilde başının üstüne kaldır. Kolların başının üstünde, gövdenle aynı hizada olsun. Bu senin başlangıç pozisyonun.', 'Barı yarım daire çizerek başının arkasına, ön kolların bisepsine değene kadar indir. Bu sırada nefes al. İpucu: Üst kollarını hep sabit ve başına yakın tut. Yalnızca ön kollar hareket etmeli.', 'Nefes verirken trisepsini kasarak başlangıç pozisyonuna dön. Kasılmayı bir saniye tut.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Incline_Bench_Pull', 'tr', array['İki eline birer dambıl al ve yaklaşık 30 derecelik eğime ayarlanmış sehpaya yüzüstü uzan.', 'Kollarını yanlarında tam uzanmış halde, yeri gösterecek şekilde sarkıt.', 'Bileklerini, ellerin pronasyon tutuşuna (avuç içleri aşağı bakar) gelene kadar çevir.', 'Şimdi dirseklerini dışa aç. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılları ters bench press yapıyormuş gibi yukarı çek: dirseklerini bük ve üst kollarını kaldır, ön kolların aşağı sarksın. Üst kolların sırtınla aynı seviyeye gelene kadar devam et. İpucu: Dirseklerin yana açılır; hareketin tepesinde üst kolların ve gövden "T" harfini oluşturmalı. Tepede kasılmayı bir saniye tut.', 'Nefes alırken yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Incline_Cable_Chest_Press', 'tr', array['Ağırlığı uygun bir seviyeye ayarla, otur ve tutamakları kavra. Üst kolların gövdenle yaklaşık 45 derece yapsın, başın ve göğsün dik olsun. Dirseklerin yaklaşık 90 derece bükülü olsun. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak tutamakları tam önünde birbirine doğru it. Hareket boyunca kürek kemiklerini geride tut.', 'Kolların tam açıkken bekle, sonra kablolardaki gerilimi bırakmadan başlangıç pozisyonuna dön.']::text[]),
  ('Incline_Cable_Flye', 'tr', array['Başlangıç pozisyonuna geçmek için makaraları yer seviyesine (makinede gövdenin altında kalan en alçak ayara) getir.', '45 dereceye ayarlanmış eğimli bir sehpayı makaraların arasına koy, iki tarafta da ağırlığı seç ve her eline bir tutamak al.', 'İki elinde birer tutamakla eğimli sehpaya uzan ve kolların açıkken ellerini yüzünün önünde birleştir. Bu senin başlangıç pozisyonun.', 'Biseps tendonuna yük binmesin diye dirseklerini hafifçe bük ve göğsünde gerilme hissedene kadar kollarını geniş bir yay çizerek iki yana indir. Hareketin bu kısmında nefes al. İpucu: Hareket boyunca kolların kendisi sabit kalır; hareket yalnızca omuz ekleminde olmalı.', 'Göğüs kaslarını sıkıp nefes verirken kollarını başlangıç pozisyonuna geri getir. Kasılı pozisyonu bir saniye tut. İpucu: Ağırlıkları indirirken izlediğin yayın aynısını izle.', 'Belirlenen tekrar sayısı kadar tekrarla.']::text[]),
  ('Incline_Dumbbell_Bench_With_Palms_Facing_In', 'tr', array['Eğimli sehpaya sırtüstü yaslan; iki elinde birer dambıl olsun ve dambıllar uyluklarının üstünde dursun. Avuç içlerin birbirine baksın.', 'Uyluklarından destek alarak dambılları sırayla, her seferinde tek kolla yukarı al ve omuz genişliğinde tut.', 'Dambıllar omuz genişliğindeyken nötr tutuşu koru, avuç içlerin birbirine baksın. Dirseklerini yana aç; üst kolların omuzlarınla aynı hizada (gövdeye dik) olsun ve dirseklerini üst kolla ön kol arasında 90 derecelik açı oluşacak kadar bük. Bu senin başlangıç pozisyonun.', 'Nefes alırken ağırlıkları yavaşça yanlarına doğru indir. Dambılları her an tam kontrol altında tut.', 'Nefes verirken dambılları göğüs kaslarınla yukarı it. Tepede kollarını kilitle, bir saniye bekle, sonra yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Belirlenen tekrar sayısı kadar tekrarla.', 'Bitirince dambılları önce yeniden uyluklarına, sonra yere koy. Dambılları bırakmanın en güvenli yolu budur.']::text[]),
  ('Incline_Dumbbell_Curl', 'tr', array['Eğimli sehpaya yaslanarak otur; iki elinde birer dambıl olsun ve kolların aşağıya uzansın. Dirseklerini gövdene yakın tut ve avuç içlerini öne bakana kadar çevir. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes verirken bisepsini kasarak ağırlıkları öne doğru kaldır. Yalnızca ön kollar hareket etmeli. Biseps tam kasılana ve dambıllar omuz hizasına gelene kadar devam et. Kasılı pozisyonu bir saniye tut.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Incline_Dumbbell_Flyes', 'tr', array['İki eline birer dambıl al ve eğimi 30 dereceyi geçmeyecek şekilde ayarlanmış sehpaya uzan.', 'Kollarını, dirseklerin hafifçe bükülü şekilde yukarı uzat.', 'Şimdi bileklerini avuç içlerin sana bakacak şekilde çevir. İpucu: Serçe parmakların yan yana olmalı. Bu senin başlangıç pozisyonun.', 'Nefes alırken kollarını yavaşça yana indir; kolların uzanmış kalsın ve avuç içlerin birbirine bakana kadar bileklerini çevir. İpucu: Hareketin sonunda kolların yanlarında, avuç içlerin tavana dönük olur.', 'Nefes verirken hareketi tersine çevirerek dambılları başlangıç pozisyonuna kaldır; ellerini, serçe parmakların yeniden yan yana gelecek şekilde çevir. İpucu: Hareket yalnızca omuz ekleminde ve bilekte olur. Dirsek ekleminde hiçbir hareket yoktur.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Incline_Dumbbell_Flyes_-_With_A_Twist', 'tr', array['İki eline birer dambıl al ve eğimi 30 dereceyi geçmeyecek şekilde ayarlanmış sehpaya uzan.', 'Kollarını, dirseklerin hafifçe bükülü şekilde yukarı uzat.', 'Şimdi bileklerini avuç içlerin sana bakacak şekilde çevir. İpucu: Serçe parmakların yan yana olmalı. Bu senin başlangıç pozisyonun.', 'Nefes alırken kollarını yavaşça yana indir; kolların uzanmış kalsın ve avuç içlerin birbirine bakana kadar bileklerini çevir. İpucu: Hareketin sonunda kolların yanlarında, avuç içlerin tavana dönük olur.', 'Nefes verirken hareketi tersine çevirerek dambılları başlangıç pozisyonuna kaldır; ellerini, serçe parmakların yeniden yan yana gelecek şekilde çevir. İpucu: Hareket yalnızca omuz ekleminde ve bilekte olur. Dirsek ekleminde hiçbir hareket yoktur.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Incline_Dumbbell_Press', 'tr', array['Eğimli sehpaya sırtüstü yaslan; iki elinde birer dambıl olsun ve dambıllar uyluklarının üstünde dursun. Avuç içlerin birbirine baksın.', 'Sonra uyluklarınla iterek destek ver ve dambılları birer birer kaldır, omuz genişliğinde tut.', 'Dambılları omuz genişliğine kaldırınca bileklerini öne çevir; avuç içlerin senden uzağa baksın. Bu senin başlangıç pozisyonun.', 'Dambılları her an tam kontrol altında tut. Sonra nefes ver ve dambılları göğsünle yukarı it.', 'Tepede kollarını kilitle, bir saniye bekle, sonra ağırlığı yavaşça indirmeye başla. İpucu: İdeal olan, ağırlıkları indirmenin kaldırmanın yaklaşık iki katı kadar sürmesidir.', 'Belirlenen tekrar sayısı kadar tekrarla.', 'Bitirince dambılları önce yeniden uyluklarına, sonra yere koy. Dambılları elden çıkarmanın en güvenli yolu budur.']::text[]),
  ('Incline_Hammer_Curls', 'tr', array['İki elinde birer dambılla eğimli sehpaya otur. Sırtını sırtlığa sıkıca yasla, ayaklarını bitiştir. Dambılları nötr tutuşla yanlarında dümdüz aşağı sarkıt. Bu senin başlangıç pozisyonun.', 'Harekete dirseklerini bükerek başla; üst kollarını sabit tutmaya çalış.', 'Hareketin tepesine kadar devam et ve bekle, sonra yavaşça başlangıç pozisyonuna dön.']::text[]),
  ('Incline_Inner_Biceps_Curl', 'tr', array['İki eline birer dambıl al ve eğimli sehpaya sırtüstü yaslan.', 'Kollarını yanlarında düz sarkıt, avuç içlerin dışarı baksın. Bu başlangıç pozisyonun.', 'Nefes verirken dambılları dışa ve yukarı doğru kıvır. Ön kolların yan omuz kaslarınla aynı hizada kalsın. Dambıllar omuz yüksekliğine, omuzlarının yanına gelene kadar devam et. İpucu: Hareketin sonu çift biseps pozuna benzemeli.', 'Tepede bir saniye sık. Sonra nefes alarak ağırlıkları yukarı çıkardığın yoldan yavaşça başlangıç pozisyonuna indir.', 'Planındaki tekrar sayısı kadar yap.']::text[]),
  ('Incline_Push-Up', 'tr', array['Yüzün bir sehpaya ya da sağlam bir yükseltiye dönük dur. Ellerini kenarına, omuz genişliğinden biraz açık yerleştir.', 'Ayaklarını geriye al, parmak uçlarına bas; kolların ve gövden düz olsun. Kollar gövdeye dik dursun. Gövdeni düz tutarak kollarını bük ve göğsünü sehpanın ya da yükseltinin kenarına indir.', 'Kolların düzleşene kadar kendini yukarı it. Tekrarla.']::text[]),
  ('Incline_Push-Up_Close-Grip', 'tr', array['Sana uygun yüksekliğe ayarlanmış bir Smith makinesi barının ya da sağlam bir yükseltinin karşısında dur.', 'Ellerini bara yan yana, bitişik koy.', 'Kolların ve gövden düz olacak şekilde ayaklarını geriye al. Bu başlangıç pozisyonun.', 'Gövdeni düz tut, kollarını bükerek göğsünü bara indir.', 'Dirseklerini açıp kendini yukarı iterek başlangıç pozisyonuna dön.']::text[]),
  ('Incline_Push-Up_Depth_Jump', 'tr', array['Bu çalışma için yaklaşık 12 inç yüksekliğinde bir kasa ve iki kalın minder ya da aerobik step tahtası gerekir.', 'Step tahtalarını omuzlarının hemen dışına yerleştir. Ayaklarını kasanın üstüne koy, ellerini tahtaların hemen iç tarafında yere bas; böylece ayakların yüksekte bir şınav pozisyonu alırsın. Bu başlangıç pozisyonun.', 'Dirseklerini büküp gövdeni indir, hemen yön değiştir ve kendini yerden it. Ellerin yerden kesilince onları tahtaların üstüne taşı, inişi yumuşatmak için dirseklerini bük.', 'Başlangıç pozisyonuna dönmek için aynı hareketi tekrarla.']::text[]),
  ('Incline_Push-Up_Medium', 'tr', array['Sana uygun yüksekliğe ayarlanmış bir Smith makinesi barının ya da sağlam bir yükseltinin karşısında dur.', 'Ellerini bara yaklaşık omuz genişliğinde koy.', 'Kolların ve gövden düz olacak şekilde ayaklarını geriye al. Bu başlangıç pozisyonun.', 'Gövdeni düz tut, kollarını bükerek göğsünü bara indir.', 'Dirseklerini açıp kendini yukarı iterek başlangıç pozisyonuna dön.']::text[]),
  ('Incline_Push-Up_Reverse_Grip', 'tr', array['Sana uygun yüksekliğe ayarlanmış bir Smith makinesi barının ya da sağlam bir yükseltinin karşısında dur.', 'Ellerini bara avuç içlerin yukarı bakacak şekilde, yaklaşık omuz genişliğinde koy.', 'Kolların ve gövden düz olacak şekilde ayaklarını geriye al. Bu başlangıç pozisyonun.', 'Gövdeni düz tut, kollarını bükerek göğsünü bara indir.', 'Dirseklerini açıp kendini yukarı iterek başlangıç pozisyonuna dön.']::text[]),
  ('Incline_Push-Up_Wide', 'tr', array['Sana uygun yüksekliğe ayarlanmış bir Smith makinesi barının ya da sağlam bir yükseltinin karşısında dur.', 'Ellerini bara omuz genişliğinden açık koy.', 'Kolların ve gövden düz olacak şekilde ayaklarını geriye al. Kolların gövdene dik dursun. Bu başlangıç pozisyonun.', 'Gövdeni düz tut, kollarını bükerek göğsünü bara indir.', 'Dirseklerini açıp kendini yukarı iterek başlangıç pozisyonuna dön.']::text[]),
  ('Intermediate_Groin_Stretch', 'tr', array['Bacakların uzatılmış halde sırtüstü yat. Bir ayağına kemer, ip ya da bant geçir ve o bacağı yana doğru gidebildiği kadar aç. Bu başlangıç pozisyonun.', 'Kemeri hafifçe çek; kasığında ve arka bacağında gerginlik oluşsun. 10-20 saniye tut, sonra diğer tarafta tekrarla.']::text[]),
  ('Intermediate_Hip_Flexor_and_Quad_Stretch', 'tr', array['Bir ayağına ip, kemer ya da bant geçirilmiş halde yere yüzüstü yat.', 'Esneteceğin bacağın dizini bük ve kalçasını geriye aç; bu sırada kemeri iki elinle çek. Dizin ve kalçan yerden kalkmalı, kalça fleksörlerinde ve ön bacakta gerginlik oluşmalı. Esnemeyi 10-20 saniye tut, sonra diğer bacakta tekrarla.']::text[]),
  ('Internal_Rotation_with_Band', 'tr', array['Bandı bir direğe boğarak bağla; bant dirseğinle aynı yükseklikte olsun. Sağ yanın banda dönük, birkaç fit uzakta dur.', 'Bandın ucunu sağ elinle tut ve dirseğini gövdenin yanına sıkıca bastır. Dirseğin yerinden oynamasın diye dirseğinle bir ped ya da foam roller sıkıştırman önerilir.', 'Üst kolun yerindeyken dirseğin 90 derece bükülü olsun, elin gövdenden uzağa uzansın. Bu başlangıç pozisyonun.', 'Dirseğini yerinden oynatmadan kolunu forehand vuruşu gibi içe doğru döndür.', 'Gidebildiğin kadar git, kısa bir an bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Inverted_Row', 'tr', array['Bir barı kafese yaklaşık bel yüksekliğinde yerleştir. Smith makinesi de kullanabilirsin.', 'Barı omuz genişliğinden açık tut ve barın altına asıl. Gövden düz, topukların yerde, kolların tam açık olsun. Bu başlangıç pozisyonun.', 'Dirseklerini bükerek göğsünü bara çek. Çekerken kürek kemiklerini birbirine yaklaştır.', 'Tepede kısa bir an bekle ve kendini başlangıç pozisyonuna indir.', 'İstediğin tekrar sayısı kadar devam et.']::text[]),
  ('Inverted_Row_with_Straps', 'tr', array['Bir kafese ya da başka sağlam bir yere ip veya askı kayışları as. Uçlarından tut ve sırtüstü, iplere asılı bir pozisyon al. Gövden düz, topukların yerde, kolların tam açık olsun. Bu başlangıç pozisyonun.', 'Dirseklerini bükerek göğsünü ellerine çek. Çekerken kürek kemiklerini birbirine yaklaştır.', 'Tepede kısa bir an bekle ve kendini başlangıç pozisyonuna indir.', 'İstediğin tekrar sayısı kadar devam et.']::text[]),
  ('Iron_Cross', 'tr', array['Ayakların yaklaşık omuz genişliğinde, iki elinde birer dambılla ayakta dur. Kollarını düz tutarak yanlara, omuz yüksekliğine kaldır; avuç içlerin öne baksın. Bu başlangıç pozisyonun.', 'Dizlerini ve kalçanı bükerek çömel. İnerken düz kollarını göğsünün önünde birleştir.', 'Uylukların yere yaklaşık paralel olunca dur. Sırtın düz, göğsün yukarıda kalsın.', 'Topuklarından iterek ayağa kalk ve kollarını yeniden yanlara aç. Tekrarla.']::text[]),
  ('Iron_Crosses_stretch', 'tr', array['Yere yüzüstü yat, kollarını yanlara aç, avuç içlerini yere bastır. Bu başlangıç pozisyonun.', 'Bir dizini bük ve o bacağı gövdenin arkasından karşı tarafa götür; karşı elinin yakınında yere değdirmeye çalış.', 'Bacağını hemen başlangıç pozisyonuna getir ve hızlıca diğer bacakla tekrarla. 10-20 tekrar boyunca sırayla devam et.']::text[]),
  ('Isometric_Chest_Squeezes', 'tr', array['Otururken ya da ayakta, kollarını 90 derece bük ve avuç içlerini göğsünün önünde birleştir. İpucu: Ellerin açık, avuçların birbirine yapışık olsun; parmakların öne (gövdene dik) baksın.', 'Göğsünü kasarken iki elini birbirine doğru it. Hafif bir gerilimle başla ve yavaş yavaş artır. Kasılma boyunca normal nefes almayı sürdür.', 'Önerilen saniye kadar tut.', 'Şimdi gerilimi yavaşça bırak.', 'Önerilen süre kadar dinlen ve tekrarla.']::text[]),
  ('Isometric_Neck_Exercise_-_Front_And_Back', 'tr', array['Başın ve boynun nötr pozisyondayken (baş dik, yüz öne dönük normal duruş) iki elini başının ön tarafına koy.', 'Boyun kaslarını kasarak başını hafifçe öne it, ama başının hareket etmesine izin verme. Hafif bir gerilimle başla ve yavaş yavaş artır. Kasılma boyunca normal nefes almayı sürdür.', 'Önerilen saniye kadar tut.', 'Şimdi gerilimi yavaşça bırak.', 'Önerilen süre kadar dinlen ve ellerini başının arka tarafına koyarak tekrarla.']::text[]),
  ('Isometric_Neck_Exercise_-_Sides', 'tr', array['Başın ve boynun nötr pozisyondayken (baş dik, yüz öne dönük normal duruş) sol elini başının sol yanına koy.', 'Sol boyun kaslarını kasarak başını hafifçe sola it, ama başının hareket etmesine izin verme. Hafif bir gerilimle başla ve yavaş yavaş artır. Kasılma boyunca normal nefes almayı sürdür.', 'Önerilen saniye kadar tut.', 'Şimdi gerilimi yavaşça bırak.', 'Önerilen süre kadar dinlen ve sağ elini başının sağ yanına koyarak tekrarla.']::text[]),
  ('Isometric_Wipers', 'tr', array['Şınav pozisyonu al: ağırlığın ellerinde ve ayak parmaklarında, gövden düz olsun. Ellerin omuz genişliğinin hemen dışında dursun. Bu başlangıç pozisyonun.', 'Vücut ağırlığını olabildiğince bir yana kaydır; gövden inerken o taraftaki dirseğin bükülsün.', 'Bükülü kolunu açarak kendini yukarı it, ardından diğer yana in.', 'İstediğin tekrar sayısı kadar devam et.']::text[]),
  ('JM_Press', 'tr', array['Harekete dar tutuş bench press gibi başla: düz sehpaya yat, halteri kolların tam açık halde yukarıda tut, dirseklerin içte olsun. Ancak kolların gövdeye dik durmasın; bar üst göğsünün tam üzerinde, aynı hatta olsun. Bu başlangıç pozisyonun.', 'Kolların tam açıkken barı yatarak triseps açma hareketindeki gibi indir. İnerken nefes al. Yolun yarısına gelince barın yaklaşık bir inç geriye yuvarlanmasına izin ver: üst kollarını gövdeye dik olana kadar bacaklarına doğru götür. İpucu: Üst kollarını öne getirirken dirseklerindeki açıyı sabit tut.', 'Nefes verirken barı triseps gücüyle, dar tutuş bench press yapar gibi yukarı it.', 'Şimdi başlangıç pozisyonuna dön ve yeniden başla.', 'Planındaki tekrar sayısı kadar yap.']::text[]),
  ('Jackknife_Sit-Up', 'tr', array['Yere (ya da egzersiz minderine) sırtüstü, dümdüz yat. Kolların başının gerisine doğru düz uzansın, bacakların da uzatılmış olsun. Bu başlangıç pozisyonun.', 'Nefes verirken belinden katlan; bacaklarını ve kollarını aynı anda kaldırıp çakı pozisyonunda buluştur. İpucu: Bacaklar düz olmalı ve yerden yaklaşık 35-45 derece kalkmalı; kollar düz ve bacaklara paralel olmalı. Üst gövden yerden kalkmalı.', 'Nefes alırken kollarını ve bacaklarını başlangıç pozisyonuna indir.', 'Planındaki tekrar sayısı kadar yap.']::text[]),
  ('Janda_Sit-Up', 'tr', array['Yerde temel mekik pozisyonunu al: dizler doksan derece bükülü, ayak tabanları yerde, kollar göğsünde çapraz ya da yanlarda. Bu başlangıç pozisyonun.', 'Kalça kaslarını ve arka bacağını güçlü biçimde sık, ciğerlerini havayla doldur ve yavaşça (üçten altıya kadar sayarak) yükselirken nefesini yavaş yavaş ver. İpucu: Kalça kaslarını ve arka bacağı sıkmak önemlidir; çünkü bu, resiprokal inhibisyon denen süreçle kalça fleksörlerini devre dışı bırakır. Yani kasılan kasların karşıtı olan kaslar gevşer.', 'Nefes alırken yavaşça ve kontrollü biçimde başlangıç pozisyonuna dön.', 'Planındaki tekrar sayısı kadar yap.']::text[]),
  ('Jefferson_Squats', 'tr', array['Yere bir halter koy.', 'Barın üzerinden geç ve uzunluğunun tam ortasında dur.', 'Sırtını düz tutup dizlerini bükerek eğil ve barı ön tarafından sağ elinle kavra. Tutuş nötr olsun, avuç için sola baksın.', 'Barı arka tarafından sol elinle kavra. Bu el de nötr tutuşta olsun (avuç içi sağa bakar). İpucu: Barı dengeli tuttuğundan emin ol. Gövden barın tam ortasında durmalı; öndeki sağ elinle gövden arasındaki mesafe, arkadaki sol elinle gövden arasındaki mesafeye eşit olmalı.', 'Şimdi ağırlıkla birlikte dimdik ayağa kalk. İpucu: Ayakların omuz genişliğinde, ayak parmakların hafifçe dışa dönük olsun.', 'Sırtını düz tutup dizlerini bükerek, uylukların yere paralel olana kadar çömel. İpucu: Sırtını olabildiğince dik, başını yukarıda tut. Dizlerinin ayak parmaklarını geçmesine izin verme. Hareketin bu bölümünde nefes al.', 'Şimdi ayaklarınla iterek başlangıç pozisyonuna yüksel. İpucu: Bar kol boyu aşağıda asılı kalsın, dirseklerin hafif bükülü halde kilitli olsun. Kollar yalnızca kanca görevi görür, onlarla kaldırma. Kaldırmayı kollarınla değil uyluklarınla yap.']::text[]),
  ('Jerk_Balance', 'tr', array['Bu çalışma, jerk sırasında yeterince alçağa inmeyi öğretir ve hareket boyunca geriye kayanları düzeltir. Bar jerk pozisyonunda omuzlarındayken başla: omuzlar önde, gövde dik, ayaklar hafifçe öne arkaya açık.', 'Harekete normal bir jerk gibi başla: gövdeni dik tutarak dizlerinden hafifçe çök ve güçlü biçimde yukarı it. Ağırlığı kolların değil, momentum kaldırsın.', 'Arka ayağını yerinde tut; ağırlığı yukarı iterken bu ayaktan güç alarak gövdeni öne, tam makas pozisyonuna sür. Ağırlık başının üstündeyken ayağa kalkarak toparlan.']::text[]),
  ('Jerk_Dip_Squat', 'tr', array['Bu hareket jerk''in çökme bölümünü güçlendirir. Bar jerk pozisyonunda omuzlarındayken başla: omuzlar raf oluşturacak şekilde önde, bar boğazına hafifçe değiyor. Ayakların tam kalçalarının altında dursun ve rahat ettiğin kadar dışa dönük olsun.', 'Gövdeni dik tut ve dizlerini bükerek çök; dizlerin öne gitsin, kalçan geriye gitmesin. Çökme aşırı olmamalı. Ayaklarından güçlü biçimde iterek ağırlığı başlangıç pozisyonuna getir.']::text[]),
  ('Jogging_Treadmill', 'tr', array['Koşu bandına çık ve menüden istediğin seçeneği belirle. Çoğu koşu bandında manuel ayar bulunur ya da bir program seçebilirsin. Genellikle yaşını ve kilonu girerek egzersizde yaktığın kaloriyi tahmin ettirebilirsin. Eğimi ayarlayarak antrenmanın yoğunluğunu değiştirebilirsin.', 'Koşu bantları pratiktir, kalp ve damar sağlığına yararlıdır ve genellikle dışarıda koşmaya göre vücuda daha az darbe bindirir. 150 lb ağırlığındaki biri 30 dakika hafif tempo koşuda yaklaşık 250 kalori, hızlı koşuda ise 450 kaloriden fazla yakar. Koşarken duruşunu düzgün tut ve tutamaklara yalnızca gerektiğinde, örneğin inerken ya da nabzına bakarken tutun.']::text[]),
  ('Keg_Load', 'tr', array['Fıçı yükleme için istediğin sayıda fıçıyı yükleme platformundan belli bir uzaklığa, genellikle 30-50 fit öteye diz.', 'İlk fıçının sana yakın tutamağını kavra ve fıçıyı yan yatırarak tabanının karşı kenarını tut. Fıçıyı göğsüne kaldır.', 'Fıçıyı ne kadar yukarıda taşırsan platforma o kadar hızlı gidebilirsin. Omuza almak genellikle yasaktır. Fıçıyı sıkıca tuttuğundan emin ol. Platforma olabildiğince hızlı git ve fıçıyı yükle; olabildiğince yükseğe çıkarmak için kalçanı, dizlerini ve ayak bileklerini aç.', 'Sıradaki fıçıyı almak için başlangıç noktasına dön ve yarış bitene kadar tekrarla.']::text[]),
  ('Kettlebell_Arnold_Press', 'tr', array['Bir kettlebell''i clean hareketiyle omzuna al: kettlebell''i omzuna doğru kaldırırken bacaklarını ve kalçanı aç. Avuç için içe baksın.', 'Tam karşıya bak ve kettlebell''i dışa ve başının üstüne doğru it. Bileğini döndür; tepede avuç için öne baksın.', 'Kettlebell''i avuç için yeniden içe bakacak şekilde başlangıç pozisyonuna indir.']::text[]),
  ('Kettlebell_Dead_Clean', 'tr', array['Kettlebell''i ayaklarının arasına koy. Başlangıç pozisyonu için kalçanı geriye it ve tam karşıya bak.', 'Kettlebell''i clean hareketiyle omzuna al: yukarı kaldırırken bacaklarını ve kalçanı aç. Bu sırada bileğin dönsün.', 'Kettlebell''i indir. Sırtını düz, kalçanı geride tut; böylece arka bacağın yük altında kalır.']::text[]),
  ('Kettlebell_Figure_8', 'tr', array['Bir kettlebell''i bacaklarının arasına koy ve ayaklarını omuz genişliğinden açık yerleştir. Kalçanı geriye iterek ve sırtını düz tutarak öne eğil.', 'Kettlebell''i al ve bacaklarının arasından diğer eline geçir. Alan el bacağın arkasından uzansın. Birkaç tekrar boyunca bir o yana bir bu yana geçir.']::text[]),
  ('Kettlebell_Halo', 'tr', array['Ayakların kalça genişliğinde, dik dur. Kettlebell''i ters çevirip boynuzlarından tut; gülle ellerinin üstünde ve göğsüne yakın olsun. Karın ve kalça kaslarını sık ki göğüs kafesin aşağıda kalsın. Bu başlangıç pozisyonun.', 'Dirseklerini başına yakın tut; kettlebell''i bir kulağının yanından yukarı çıkarıp başının arkasına dolandır.', 'Çembere diğer kulağının yanından devam et ve göğsünün önündeki başlangıç pozisyonuna in. Gülle hareket boyunca gövdene yakın geçsin.', 'Belirlenen sayıda çemberi bir yöne tamamla, sonra aynı sayıda çemberi ters yöne yap.', 'Yavaş hareket et; başını, kalçanı ve belini sabit tut. Belin çukurlaşıyorsa ya da gülle başından çok uzaklaşıyorsa daha hafif bir ağırlık kullan.']::text[]),
  ('Kettlebell_Halo_With_Overhead_Extension', 'tr', array['Ayakların kalça genişliğinde, dik dur. Kettlebell''i ters çevirip boynuzlarından tut; gülle ellerinin üstünde ve göğsüne yakın olsun. Karın ve kalça kaslarını sık ki göğüs kafesin aşağıda kalsın. Bu başlangıç pozisyonun.', 'Dirseklerini başına yakın tut; kettlebell''i bir kulağının yanından yukarı çıkarıp başının arkasına gelene kadar dolandır. Burada dur.', 'Bu pozisyondan dirseklerini açarak kettlebell''i kolların düzleşene kadar başının üstüne it. Üst kolların başının yanında kalsın.', 'Dirseklerini büküp kettlebell''i kontrollü biçimde başının arkasındaki bekleme pozisyonuna indir.', 'Çembere diğer kulağının yanından devam et ve göğsünün önündeki başlangıç pozisyonuna in. Böylece bir tekrar tamamlanır.', 'Her tekrarda çemberin yönünü değiştir. Hareket boyunca başını, kalçanı ve belini sabit tut. Belin çukurlaşıyorsa ya da geriye yaslanmadan baş üstü pozisyona çıkamıyorsan daha hafif bir ağırlık kullan veya halo ile açmayı ayrı egzersizler olarak yap.']::text[]),
  ('Kettlebell_Hang_Clean', 'tr', array['Kettlebell''i ayaklarının arasına koy. Başlangıç pozisyonu için kalçanı geriye it ve tam karşıya bak.', 'Kettlebell''i clean hareketiyle omzuna al: yukarı kaldırırken bacaklarını ve kalçanı aç. Bu sırada bileğin dönsün.', 'Kettlebell''i bacaklarının arasında asılı kalacağı pozisyona indir; arka bacağın yük altında kalsın. Başını her zaman yukarıda tut.']::text[]),
  ('Kettlebell_One-Legged_Deadlift', 'tr', array['Bir kettlebell''i tek elinle sapından tut. Kettlebell''i tuttuğun taraftaki bacağının üzerinde, tek ayakla dur.', 'O dizini hafif bükülü tut ve düz bacak deadlift yap: kalçandan öne eğil, boştaki bacağını denge için arkana uzat.', 'Gövden yere paralel olana kadar kettlebell''i indirmeye devam et, sonra dik pozisyona dön.']::text[]),
  ('Kettlebell_Overhead_Triceps_Extension', 'tr', array['Ayakların kalça genişliğinde dur ve bir kettlebell''i iki elinle boynuzlarından tut. Kolların düzleşene kadar başının üstüne it; gülle ellerinin arkasında sarksın.', 'Karın kaslarını sık, üst kollarını dik ve başına yakın tut. Bu başlangıç pozisyonun.', 'Dirseklerini bükerek kettlebell''i başının arkasına indir. Dirseklerin dışa açılmadan, omuz hareketliliğinin izin verdiği kadar in.', 'Dirseklerini açarak kettlebell''i başlangıç pozisyonuna it. Üst kolların hareket boyunca sabit kalsın.', 'Göğüs kafesini aşağıda tut ve kollarını açarken belini çukurlaştırma.']::text[]),
  ('Kettlebell_Pass_Between_The_Legs', 'tr', array['Bir kettlebell''i bacaklarının arasına koy ve rahat bir duruş al. Kalçanı geriye iterek ve sırtını düz tutarak öne eğil.', 'Kettlebell''i al ve bacaklarının arasından, "W" çizer gibi diğer eline geçir. Birkaç tekrar boyunca bir o yana bir bu yana geçir.']::text[]),
  ('Kettlebell_Pirate_Ships', 'tr', array['Ayakların geniş açık, bir kettlebell''i iki elinle tut. Kolların düzken bel hizasında sarksın. Bu başlangıç pozisyonun.', 'Bir yana dönerek kettlebell''i baş yüksekliğine savur. Tepede kısa bir an bekle.', 'Karşı yana dönerken güllenin düşmesine izin ver ve kettlebell''i yeniden baş yüksekliğine çıkar.', 'İstediğin tekrar sayısı kadar devam et.']::text[]),
  ('Kettlebell_Pistol_Squat', 'tr', array['Bir kettlebell''i iki elinle al ve boynuzlarından tut. Bir bacağını yerden kaldır, diğerinin üzerinde çömeleceksin.', 'Dizini büküp kalçanı geriye oturtarak çömel; kettlebell''i önünde, yukarıda tut.', 'En altta bir saniye bekle, sonra hareketi tersine çevir: topuğundan it, başın ve göğsün yukarıda kalsın.', 'Yeniden in ve tekrarla.']::text[]),
  ('Kettlebell_Seated_Press', 'tr', array['Yere otur ve bacaklarını rahat edeceğin kadar aç.', 'Bir kettlebell''i clean hareketiyle omzuna al.', 'Kettlebell''i, kolun başının üstünde kilitlenene kadar yukarı ve dışa doğru it. Başlangıç pozisyonuna dön.']::text[]),
  ('Kettlebell_Seesaw_Press', 'tr', array['İki kettlebell''i clean hareketiyle omuzlarına al.', 'Kettlebell''lerden birini yukarı it.', 'Onu indir ve hemen diğerini yukarı it. İki tarafta da aynı sayıda tekrar yaptığından emin ol.']::text[]),
  ('Kettlebell_Sumo_High_Pull', 'tr', array['Bir kettlebell''i yere, ayaklarının arasına koy. Ayaklarını geniş aç ve kettlebell''i iki elinle kavra. Dizlerin bükülü, kalçanı olabildiğince geriye al. Göğsünü ve başını yukarıda tut. Bu başlangıç pozisyonun.', 'Kalçanı ve dizlerini açarken aynı anda kettlebell''i omuzlarına doğru çek; çekerken dirseklerini yukarı kaldır. Hareketi tersine çevirerek başlangıç pozisyonuna dön.']::text[]),
  ('Kettlebell_Thruster', 'tr', array['İki kettlebell''i clean hareketiyle omuzlarına al: kettlebell''leri omuzlarına doğru çekerken bacaklarını ve kalçanı aç, bu sırada bileklerini döndür. Bu başlangıç pozisyonun.', 'Kalçanı ve dizlerini bükerek çömelmeye başla, kalçan bacaklarının arasına insin. Sırtını dik ve düz tutarak inebildiğin kadar in.', 'En altta yön değiştir; dizlerini ve kalçanı açıp topuklarından iterek kalk. Kalkarken kollarını dümdüz yukarı uzatarak iki kettlebell''i başının üstüne it; çömelmeden gelen momentum ağırlıkları yukarı sürmene yardım etsin.', 'Sonraki tekrara başlarken ağırlıkları omuzlarına indir.']::text[]),
  ('Kettlebell_Turkish_Get-Up_Lunge_style', 'tr', array['Yere sırtüstü yat ve dirseğini açarak bir kettlebell''i en üst pozisyona it. Kettlebell''in olduğu taraftaki dizini bük.', 'Kettlebell''i tutan kolun hep kilitli kalsın. Karşı yana dön ve çalışmayan kolundan destek alarak lunge pozisyonuna doğru öne çık. Boştaki elinle kendini oturma pozisyonuna it, ardından tek dizinin üstüne geç.', 'Kettlebell''e bakarak yavaşça ayağa kalk. Hareketi tersine çevirip başlangıç pozisyonuna dön ve tekrarla.']::text[]),
  ('Kettlebell_Turkish_Get-Up_Squat_style', 'tr', array['Yere sırtüstü yat ve dirseğini açarak bir kettlebell''i en üst pozisyona it. Kettlebell''in olduğu taraftaki dizini bük.', 'Kettlebell''i tutan kolun hep kilitli kalsın. Karşı yana dön ve çalışmayan kolundan destek alarak lunge pozisyonuna doğru öne çık.', 'Boştaki elinle kendini oturma pozisyonuna it, ardından ayaklarının üstüne geç. Kettlebell''e bakarak yavaşça ayağa kalk. Hareketi tersine çevirip başlangıç pozisyonuna dön ve tekrarla.']::text[]),
  ('Kettlebell_Windmill', 'tr', array['Bir kettlebell''i öndeki ayağının önüne koy; karşı kolunla clean yapıp başının üstüne it. Clean için kettlebell''i omzuna doğru çekerken bacaklarını ve kalçanı aç. Bu sırada bileğini döndür ki avuç için öne baksın. Sonra dirseğini açarak başının üstüne it.', 'Kettlebell''i tutan kolun hep kilitli kalsın. Kalçanı, kilitli tuttuğun kettlebell''in olduğu yöne doğru dışarı it. Ayaklarını, kettlebell''i tutan kola göre kırk beş derecelik açıyla dışa çevir. Kalçanı dışarı çıkararak kalçandan bir yana bükül ve boştaki elin yere değene kadar yavaşça eğil. Gözünü başının üstünde tuttuğun kettlebell''den hiç ayırma.', 'Yere ulaşınca bir saniye bekle, sonra hareketi tersine çevirip başlangıç pozisyonuna dön.']::text[]),
  ('Kipping_Muscle_Up', 'tr', array['Halkaları false grip ile kavra: avuç içinin tabanı halkanın üstüne otursun.', 'Bacaklarını hafifçe geriye savurarak başla.', 'Bu hareketi karşıla: bacaklarını öne ve yukarı savur, çeneni ve göğsünü sertçe geriye al, aynı anda iki kolunla kendini yukarı çek. Barfiksin en üst noktasına varınca halkaları koltuk altlarına çek ve omuzlarını öne yuvarla; dirseklerin dümdüz arkana gitsin. Böylece hareketin dips bölümüne geçmek için doğru pozisyona gelirsin.', 'Kontrolü ve dengeni koruyarak dirseklerini aç ve hareketi tamamla.', 'Kendini yere indirirken dikkatli ol.']::text[]),
  ('Knee_Across_The_Body', 'tr', array['Sağ bacağın düz olacak şekilde yere yat. Sol bacağını bük ve gövdenin üzerinden karşı tarafa indir; sağ elinle dizini yere doğru tut. (Esnekliğin azsa dizinin yere değmesi gerekmez.)', 'Sol kolunu rahatça yanına koy ve başını sola çevir. Kuyruk sokumuna bir ağırlık bağlı olduğunu düşün: göğsün ters yöne uzanırken kuyruk sokumun yere doğru geriye düşsün; böylece belin esner. Taraf değiştir.']::text[]),
  ('Knee_Circles', 'tr', array['Bacakların bitişik, ellerin belinde ayakta dur.', 'Normal nefes alarak dizlerinle daireler çiz.', 'Planındaki tekrar sayısı kadar yap.']::text[]),
  ('Knee_Hip_Raise_On_Parallel_Bars', 'tr', array['Dikey bacak kaldırma istasyonuna yerleş: ön kollarını gövdenin yanındaki pedlere koy ve tutacakları kavra. Dirseklerin 90 derece bükülü olsun.', 'Gövdeni dik tut, belini sırt pedine bastır ve gergin bacaklarını yere doğru sarkıt. Bu senin başlangıç pozisyonun.', 'Nefes verirken bacaklarını bükmeden yukarı kaldır. Bacakların yere aşağı yukarı paralel olunca dur ve kasılmayı bir saniye tut. İpucu: Hareketin hiçbir anında sallanma, hız alarak yapma.', 'Nefes alırken bacaklarını yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Knee_Tuck_Jump', 'tr', array['Dizlerin hafif bükülü, rahat bir şekilde ayakta dur. Ellerini göğüs hizasında önünde tut; avuçların yere baksın, parmak uçların birbirine değsin. Bu senin başlangıç pozisyonun.', 'Hızla çeyrek squat''a in ve hiç beklemeden patlayıcı şekilde yukarı fırla. Dizlerini göğsüne doğru çek ve avuçlarına değdirmeye çalış.', 'Dizlerini yukarı çekerek sıçrayabildiğin kadar yükseğe sıçra. Sağlam bir iniş için bacaklarını yeniden uzat, darbeyi de dizlerinin tekrar bükülmesine izin vererek emdir.']::text[]),
  ('Kneeling_Arm_Drill', 'tr', array['Bu çalışma koşuda kollarını daha verimli kullanmanı sağlar. Sol ayağın önde, sağ dizin yerde olacak şekilde diz çök. Kalça kasların ve arka bacakların devrede kalsın diye öndeki topuğunla yere bastır.', 'Kollarını sarkaç gibi uzun salınımlarla sallayarak başla. Sonra kol açısını daralt ve kollarını hafif tempo koşudaki gibi kullan; ardından koşu temposuna, en sonunda sprint temposuna çık.', 'Sprint hareketinde ellerin kalçanı geçer geçmez onları öne doğru hızlandır ki olabildiğince hızlı hareket etsinler.', 'Diz değiştir ve tekrarla.']::text[]),
  ('Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'tr', array['Üst makaraya bir halat aparatı tak ve önüne, yere bir mat ser.', 'Halatı iki elinle tut ve kuleden yaklaşık two feet geride diz çök.', 'Halatı başının arkasına getir; ellerin kulaklarının yanında dursun.', 'Ellerinin yerini değiştirmeden karnını kas ve dirseklerin dizlerine ulaşana kadar halatı aşağı çekerek crunch yap.', 'Altta kısa bir an bekle, sonra yavaş ve kontrollü şekilde başlangıç pozisyonuna doğrul.', 'Aynı şekilde yeniden aşağı in. Yolun yarısına geldiğinde bir dirseğini karşı dizine doğru çevirmeye başla.', 'Altta yine kısa bir an bekle, sonra yavaş ve kontrollü şekilde başlangıç pozisyonuna doğrul.', 'Aynı hareketi bir kez daha yap, bu sefer öbür dirseğini karşı dizine doğru çevir.', 'Bu hareket dizisini tükenene kadar sürdür.']::text[]),
  ('Kneeling_Cable_Triceps_Extension', 'tr', array['Üst makaralı bir kablo istasyonunun önüne bir sehpayı yan gelecek şekilde koy.', 'Düz bar aparatını başının üstünde tut; avuçların aşağı baksın, ellerinin arası yaklaşık 6 inches olsun.', 'Makineye sırtını dön ve diz çök.', 'Başını ve üst kollarının arka yüzünü sehpaya yasla. Dirseklerini bük; ön kolların üst makarayı göstersin. Bu senin başlangıç pozisyonun.', 'Nefes verirken barı yarım daire çizerek ileri it; dirseklerin kilitlenene ve kolların yere paralel olana kadar devam et. Üst kolların hep başına yakın, dirseklerin içeride kalsın. Triseps kasını iyice sık ve bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Kneeling_Forearm_Stretch', 'tr', array['Bir matın üstünde diz çök ve avuçlarını yere düz koy; parmakların geriye, dizlerine doğru baksın.', 'Avuçlarını yerden kaldırmadan yavaşça geriye yaslan; bileklerinde ve ön kollarında gerilme hissedince dur. 20-30 saniye bekle.']::text[]),
  ('Kneeling_High_Pulley_Row', 'tr', array['Makarası baş hizanın üstünde olan bir kablo istasyonunda uygun ağırlığı seç. Kabloya halat tak, a couple of feet uzakta diz çök ve halatı iki kolun da gergin şekilde önünde tut. Bu senin başlangıç pozisyonun.', 'Harekete dirseklerini bükerek ve omuzlarını tamamen geriye çekerek başla. Dirseklerin dışa açık şekilde halatı üst göğsüne çek.', 'Kısa bir an bekle, sonra yavaşça başlangıç pozisyonuna dön.']::text[]),
  ('Kneeling_Hip_Flexor', 'tr', array['Bir matın üstünde diz çök. Sağ ayağını öne al, tabanı yere tam bassın; sol bacağını arkana uzat, ayağının üstü yere değsin.', 'Kalçanda gerilme hissedene kadar ağırlığını öne ver. 15 saniye bekle, sonra öbür taraf için tekrarla.']::text[]),
  ('Kneeling_Jump_Squat', 'tr', array['Omuzlarının arkasına yerleştirdiğin bir halterle yere diz çök; bu hareketi yalnızca vücut ağırlığınla da yapabilirsin. Power rack içinde yaparsan halteri yerinden almak kolaylaşır.', 'Kalça kasların ayaklarına değene kadar kalçanı geriye götürerek otur. Başın ve göğsün yukarıda kalsın.', 'Kalçanı patlayıcı şekilde yukarı it; ayak tabanların yere tam basarak inebileceğin kadar güç üret.', 'Squat''ı tamamla: topuklarından güç al ve dizlerini uzatarak ayağa kalk.']::text[]),
  ('Kneeling_Single-Arm_High_Pulley_Row', 'tr', array['Üst makaraya tekli bir tutacak tak ve ağırlığını seç.', 'Kablo kulesinin önünde diz çök ve tutacağı tek elinle, kolun gergin şekilde tut. Bu senin başlangıç pozisyonun.', 'Başta avucun öne baksın. Dirseğini bükerek ve kürek kemiğini geriye çekerek ağırlığı gövdene doğru indir. Çekerken bileğini çevir; hareketin sonunda avucun sana bakıyor olsun.', 'Kısa bir an bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Kneeling_Squat', 'tr', array['Power rack''te barı doğru yüksekliğe ayarla. Barın arkasında diz çök; dizlerin için yere bir mat sermek iyi olabilir. Barın altına gir ve onu omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine yaklaştır, bar sırtına sıkıca otursun. Ağırlığı askıdan al.', 'Karşıya bakarak kalçanı geriye götür ve kalçan baldırlarına değene kadar otur.', 'Hareketi tersine çevir ve gövdeni yeniden dik konuma getir.']::text[]),
  ('Landmine_180s', 'tr', array['Barın bir ucunu landmine aparatına yerleştir ya da bir köşeye sağlamca sabitle. Bara uygun ağırlığı tak.', 'Barı yerden kaldır ve iki elinle, kolların önünde gergin şekilde omuz hizasına getir. Ayaklarını genişçe aç. Bu senin başlangıç pozisyonun.', 'Gövdeni ve kalçanı döndürerek ağırlığı bir yana, sonuna kadar aşağı savur. Kolların egzersiz boyunca gergin kalsın.', 'Hareketi tersine çevir ve ağırlığı karşı tarafa sonuna kadar savur.', 'Set bitene kadar bir sağa bir sola devam et.']::text[]),
  ('Landmine_Linear_Jammer', 'tr', array['Barı landmine aparatına yerleştir, yoksa bir köşeye sağlamca sabitle. Bara uygun ağırlığı tak ve tutacak aparatını barın ucuna yerleştir.', 'Barı yerden kaldır ve tutacakları omuzlarına getir. Bu senin başlangıç pozisyonun.', 'Atletik bir duruştan, kalçanı büküp geriye götürerek squat''a in. Kolların bükülü kalsın.', 'Hareketi tersine çevir: kalçanı, dizlerini ve ayak bileklerini güçlü şekilde uzatırken dirseklerini de açıp kollarını düzelt. Bunu patlayıcı şekilde yap; squat''tan tam uzanmaya olabildiğince güçlü çık.', 'Başlangıç pozisyonuna dön.']::text[]),
  ('Lateral_Bound', 'tr', array['Gideceğin yöne 90 derece dönük şekilde yarım squat pozisyonu al. Bu senin başlangıç pozisyonun.', 'Ağırlığını dıştaki bacağına aktarırken öndeki bacağının içe doğru bir karşı hareket yapmasına izin ver.', 'Hemen yeri it, uzan ve yana doğru olabildiğince uzağa sıçramaya çalış.', 'Yere iner inmez ters yöne doğru it ve ilk başladığın noktaya dön.', 'Birkaç tekrar boyunca bu şekilde gidip gel.']::text[]),
  ('Lateral_Box_Jump', 'tr', array['Yanında alçak bir kasa olacak şekilde rahatça ayakta dur. Bu senin başlangıç pozisyonun.', 'Gerilme refleksini tetiklemek için hızla çeyrek squat''a in, hemen yön değiştir ve yukarı ve yana doğru sıçra.', 'Dizlerini, ayakların kasanın üstünden rahatça geçecek kadar yukarı çek.', 'Kasanın ortasına in ve darbeyi bacaklarınla emdir.', 'Kasanın öbür tarafına dikkatlice atla. Birkaç tekrar boyunca gidip gelmeye devam et.']::text[]),
  ('Lateral_Cone_Hops', 'tr', array['Birkaç huniyi aralarında several feet olacak şekilde tek sıra diz.', 'Sıranın ucundaki huninin yanında, gidiş yönüne 90 derece dönük dur. Bu senin başlangıç pozisyonun.', 'Sıçramaya, gerilme refleksini tetiklemek için dizlerini kırarak başla. Hemen yön değiştir, yeri it ve huninin üstünden yukarı ve yana doğru atla.', 'İnişte darbeyi bacaklarınla emdir ve yaylanarak bir sonraki sıçrayışa geç. Huni sırası boyunca böyle ilerle.']::text[]),
  ('Lateral_Raise_-_With_Bands', 'tr', array['Bir egzersiz bandının üstüne, kolların aşağı uzanmışken bant gerilmeye başlayacak şekilde bas. Tutacakları pronasyon tutuşuyla (avuçların uyluklarına bakacak şekilde), omuz genişliğinden biraz dar tut. Tutacaklar uyluklarının yanında dursun. Kolların uzanmış, dirseklerin hafifçe bükülü, sırtın düz olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken yan omuz kaslarınla tutacakları yanlara kaldır. Tutacaklar yere paralel çizginin biraz üstüne çıkana kadar devam et. İpucu: Kaldırırken ellerini su döker gibi hafifçe eğ ve kollarını uzanmış tut. Ayrıca gövdeni sabit tut ve hareketin tepesinde bir saniye bekle.', 'Tutacakları yavaşça başlangıç pozisyonuna indir; bu sırada nefes al.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Latissimus_Dorsi-SMR', 'tr', array['Yere uzan ve foam roller''ı sırtının altına, bir yana, koltuk altının hemen arkasına yerleştir. Bu senin başlangıç pozisyonun.', 'Çalıştırdığın taraftaki kolunu arkanda ve yanında tut. Ağırlığını kanat kasına ver, üst gövden yere değmesin. 10-30 saniye bekle ve taraf değiştir.']::text[]),
  ('Leg-Over_Floor_Press', 'tr', array['Yere uzan ve bir kettlebell''i sapından tutarak göğsünün üstüne yerleştir. Çalışan taraftaki bacağını öbür bacağının üstünden aşır. Boştaki kolunu destek için yana uzatabilirsin.', 'Kettlebell''i kolun kilitlenene kadar yukarı it.', 'Ağırlığı dirseğin yere değene kadar indir; kettlebell hep dirseğin üstünde kalsın. İstediğin tekrar sayısı kadar yap.']::text[]),
  ('Leg-Up_Hamstring_Stretch', 'tr', array['Sırtüstü dümdüz yat. Bir dizini bük ve omurgan sabit kalsın diye o ayağını yere tam bastır.', 'Öbür bacağını havaya uzat. Kasların gerginse bacağını düzeltemezsin, sorun değil. Dizini, kaldırdığın ayağın tabanı tavana bakana kadar ya da buna yaklaşabildiğin kadar uzat.', 'Bacaklarını yavaşça olabildiğince düzelt, sonra havadaki bacağını burnuna doğru çek. Taraf değiştir.']::text[]),
  ('Leg_Extensions', 'tr', array['Bu egzersiz için bir leg extension makinesi gerekir. Ağırlığını seç, bacakların pedin altında (ayakların öne bakacak şekilde) makineye otur ve yan tutacakları kavra. Bu senin başlangıç pozisyonun. İpucu: Pedi alt bacağının üstüne, ayaklarının hemen yukarısına gelecek şekilde ayarla. Üst ve alt bacağın arasında 90 derecelik açı olsun. Açı 90 dereceden küçükse diz ayak parmaklarının önüne geçer, bu da diz eklemine gereksiz yük bindirir. Makine böyle tasarlanmışsa başka bir makine bul ya da hareketi yaparken 90 derecelik açıya gelince inmeyi bırak.', 'Nefes verirken ön bacak kaslarınla bacaklarını sonuna kadar uzat. Vücudunun geri kalanı koltukta sabit kalsın. Kasılı pozisyonda bir saniye bekle.', 'Nefes alırken ağırlığı yavaşça ilk konumuna indir; 90 derecelik sınırı aşma.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Leg_Lift', 'tr', array['Ayakların yan yana ve yaklaşık omuz genişliğinde, dik dur. Destek almak ve dengeni korumak için squat rack''in kenarları ya da bir sandalyenin üstü gibi sağlam bir yere tutun.', 'Ayak bileği ağırlığıyla ya da ağırlıksız, bir bacağını ayakta leg curl yapar gibi arkana kaldır; öbür bacağın düz kalsın. Bu hareketi yaparken nefes ver.', 'Nefes alırken kaldırdığın bacağı yavaşça yere indir.', 'Önerilen tekrar sayısı kadar yap.', 'Hareketi öbür bacağınla da yap.']::text[]),
  ('Leg_Press', 'tr', array['Leg press makinesine otur ve ayaklarını tam karşındaki platforma orta genişlikte, yani omuz genişliğinde yerleştir. Not: Orta duruş bacakları genel olarak çalıştırır; istersen öbür ayak duruşlarından birini de seçebilirsin.', 'Ağırlıklı platformu tutan emniyet kollarını aç ve bacakların önünde tamamen uzanana kadar platformu yukarı it. İpucu: Dizlerini kilitleme. Gövdenle bacakların arasında tam 90 derecelik açı olsun. Bu senin başlangıç pozisyonun.', 'Nefes alırken platformu yavaşça indir; üst ve alt bacağın arasında 90 derecelik açı oluşunca dur.', 'Nefes verirken ağırlıklı olarak topuklarınla iterek ve ön bacak kaslarını kullanarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap ve bitirdiğinde emniyet pimlerini düzgünce kilitle. Tam yüklü platformun üstüne düşmesini istemezsin.']::text[]),
  ('Leg_Pull-In', 'tr', array['Bir egzersiz matına bacakların uzanmış şekilde yat. Ellerini avuçların yere bakacak şekilde yanına ya da kalça kaslarının altına koy. İpucu: Ellerin vücudun yanında durması tercih edilen şekildir. Bu senin başlangıç pozisyonun.', 'Nefes verirken dizlerini bük ve uyluklarını karnına doğru çek. Dizlerin yaklaşık göğüs hizasına gelene kadar devam et. Hareket boyunca karnını kas ve tepe noktasında bir saniye bekle. İpucu: Hareket sırasında alt bacakların (baldırların) hep yere paralel kalsın.', 'Nefes alırken başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Leverage_Chest_Press', 'tr', array['Pimlere uygun ağırlığı tak ve koltuğu boyuna göre ayarla. Hareketin başında tutacaklar göğüs kaslarının alt ya da orta kısmının hizasında olsun.', 'Göğsünü ve başını yukarıda tut, kürek kemiklerini birbirine yaklaştır. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak tutacakları ileri it.', 'Uçta kısa bir an bekle, sonra ağırlığı başlangıç konumunun hemen üstüne kadar geri getir. Kaslar gergin kalsın: set bitmeden ağırlığı dayanaklara bırakma.']::text[]),
  ('Leverage_Deadlift', 'tr', array['Pimlere uygun ağırlığı tak. Tutacakların tam ortasında dur. Alttaki tutacakları rahat ettiğin bir tutuşla kavra, sonra nefes alırken kalçanı indir. Karşıya bak ve göğsünü yukarıda tut. Bu senin başlangıç pozisyonun.', 'Ağırlığı başlangıç pozisyonuna geri getir.']::text[]),
  ('Leverage_Decline_Chest_Press', 'tr', array['Pimlere uygun ağırlığı tak ve koltuğu boyuna göre ayarla. Hareketin başında tutacaklar göğüs kaslarının alt kısmının hizasında olsun. Göğsünü ve başını yukarıda tut, kürek kemiklerini birbirine yaklaştır. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak tutacakları ileri it.', 'Uçta kısa bir an bekle, sonra ağırlığı başlangıç konumunun hemen üstüne kadar geri getir. Kaslar gergin kalsın: set bitmeden ağırlığı dayanaklara bırakma.']::text[]),
  ('Leverage_High_Row', 'tr', array['Pimlere uygun ağırlığı tak ve koltuk yüksekliğini üstündeki tutacaklara ancak yetişebileceğin şekilde ayarla. Diz pedini seni aşağıda tutacak şekilde ayarla. Tutacakları pronasyon tutuşuyla kavra. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükerken kürek kemiklerini birbirine yaklaştır ve tutacakları gövdene doğru çek.', 'Hareketin alt noktasında bekle, sonra tutacakları yavaşça başlangıç pozisyonuna geri götür.', 'Birden çok tekrar yaparken ağırlığı dayanaklara tamamen bırakma ki çalışan kaslar gergin kalsın.']::text[]),
  ('Leverage_Incline_Chest_Press', 'tr', array['Pimlere uygun ağırlığı tak ve koltuğu boyuna göre ayarla. Hareketin başında tutacaklar göğüs kaslarının üst kısmının hizasında olsun. Göğsünü ve başını yukarıda tut, kürek kemiklerini birbirine yaklaştır. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak tutacakları ileri it.', 'Uçta kısa bir an bekle, sonra ağırlığı başlangıç konumunun hemen üstüne kadar geri getir. Kaslar gergin kalsın: set bitmeden ağırlığı dayanaklara bırakma.']::text[]),
  ('Leverage_Iso_Row', 'tr', array['Pimlere uygun ağırlığı tak ve koltuk yüksekliğini tutacaklar göğüs hizana gelecek şekilde ayarla. Tutacakları nötr ya da pronasyon tutuşuyla kavra. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükerken kürek kemiklerini birbirine yaklaştır ve tutacakları gövdene doğru çek.', 'Hareketin son noktasında bekle, sonra tutacakları yavaşça başlangıç pozisyonuna geri götür. Birden çok tekrar yaparken ağırlığı dayanaklara tamamen bırakma ki çalışan kaslar gergin kalsın.']::text[]),
  ('Leverage_Shoulder_Press', 'tr', array['Pimlere uygun ağırlığı tak ve koltuğu boyuna göre ayarla. Hareketin başında tutacaklar omuzlarının üst kısmının hizasında olsun. Göğsünü ve başını yukarıda tut, tutacakları pronasyon tutuşuyla kavra. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak tutacakları yukarı it.', 'Tepede kısa bir an bekle, sonra ağırlığı başlangıç konumunun hemen üstüne kadar geri getir. Kaslar gergin kalsın: set bitmeden ağırlığı dayanaklara bırakma.']::text[]),
  ('Leverage_Shrug', 'tr', array['Pimlere uygun ağırlığı tak. Tutacakların tam ortasında dur.', 'Üstteki tutacakları rahat ettiğin bir tutuşla kavra, sonra nefes alırken kalçanı indir. Karşıya bak ve göğsünü yukarıda tut.', 'Topuklarınla yeri it, kalçanı ve dizlerini uzatarak ayağa kalk. Kolların hareket boyunca düz kalsın, sonunda omuzların geride olsun. Bu senin başlangıç pozisyonun.', 'Omuzlarını kulaklarına doğru silkerek ağırlığı kaldır; dümdüz yukarı ve aşağı hareket et.', 'Tepe noktasında bekle, sonra ağırlığı başlangıç pozisyonuna indir.']::text[]),
  ('Linear_3-Part_Start_Technique', 'tr', array['Bu çalışma, durduğun yerden olabildiğince hızlı şekilde sprinte çıkmanı sağlar. Başlamak için bir çizgi kullanmak işe yarar. İki ayağın çizginin üstünde dur. Sol ayağını, parmak ucu sağ ayak bileğinin yanına gelecek şekilde yerleştir. Sağ ayağını solun 4-6 inches gerisine koy.', 'Sağ elini çizgiye koy, sonra burnunu sol dizine yaklaştır.', 'Öne eğilirken çömel; başın kalçandan aşağıda, ağırlığın sol bacağında olsun. Bu senin başlangıç pozisyonun.', 'Sol elini arkana doğru kaldır; kolun yere paralel olsun ve geriyi göstersin. Hazır olduğunda patlayıcı şekilde çık.']::text[]),
  ('Linear_Acceleration_Wall_Drill', 'tr', array['Bir duvara yaklaşık 45 derecelik açıyla yaslan. Ayakların bitişik, kalça kasların sıkı olsun.', 'Sağ dizini hızla kaldır, bekle, sonra ayağını dümdüz aşağı, yere vur.', 'Bacak değiştir: öbür dizini kaldır, sonra yere dümdüz aşağı doğru saldır.', 'Sağ bacağınla bir kez daha tekrarla. Sağ ayağın yere değer değmez adımları seri şekilde ardı ardına vur; sağ ve sol arasında yapabildiğin kadar hızlı geçiş yap.']::text[]),
  ('Linear_Depth_Jump', 'tr', array['Birbirinden a few feet uzakta duran iki kasa ya da sehpa gerekir. Kasalardan birinin üstünde, yüzün öbür platforma dönük dur.', 'Harekete, platformların arasındaki zemine yumuşakça inerek başla; dizlerinin ve kalçanın bükülmesine izin ver.', 'Hareketi patlayıcı şekilde tersine çevir: kalçanı, dizlerini ve ayak bileklerini uzatarak öbür platforma sıçra.', 'Yumuşak in ve darbeyi bacaklarınla emdir.']::text[]),
  ('Log_Lift', 'tr', array['Kütük önünde olacak şekilde ayakta dur. Tutacakları kavra ve kütüğü clean ile kaldırmaya başla. Clean''in başında öne eğikken kütüğü olabildiğince yukarı almaya çalış ve göğsüne doğru çek. Kütüğü yukarı getirip clean''i tamamlamak için kalçanı ve dizlerini uzat.', 'Başını geriye it ve yukarı bak; böylece göğsün kütüğün oturacağı bir raf olur. Press''e hafifçe çökerek başla: dizlerini biraz bük ve hareketi tersine çevir. Bu push press, kütüğü dikey yönde harekete geçirecek ivmeyi üretir. Ardından dirseklerini açarak kütüğü başının üstüne it. Form konusunda katı kurallar yok, bu yüzden en verimli olduğun tekniği kullan. Kütük yukarı çıkarken her tekrarda başını öne, kolların arasından geçir ve karşıya bak.', 'Yapabildiğin kadar tekrar yap. Kütüğü yere geri indirirken inişi kontrol etmeye çalış.']::text[]),
  ('London_Bridges', 'tr', array['Bir tırmanma halatını yüksek bir kirişe ya da enine bir direğe bağla. Altında, Smith makinesinin barının emniyetlerle kilitli olduğundan ve oynamadığından emin ol. Bunun yerine sağlam bir kasa da kullanabilirsin.', 'Barın üstüne çık ve halatla dengeni sağla. Bu senin başlangıç pozisyonun.', 'Vücudunu düz tutarak geriye yaslan ve halatta ellerini sırayla aşağı alarak yavaşça alçal. Yere dik açıda olana kadar devam et.', 'Vücudunu düz tutarak hareketi tersine çevir ve ellerini sırayla yukarı alarak başlangıç pozisyonuna dön.']::text[]),
  ('Looking_At_Ceiling', 'tr', array['Yere diz çök ve iki elinle topuklarını tut.', 'Kalçanı yukarı ve öne doğru kaldırırken başını geriye götürüp tavana bak; böylece sırtın kavis yapsın.']::text[]),
  ('Low_Cable_Crossover', 'tr', array['Hazırlık için makaraları alt konuma getir, kullanacağın direnci seç ve her eline bir tutacak al.', 'Öne doğru adım at ki kablolar gerilsin. Avuçların öne baksın, ellerin bel hizasının altında, kolların düz olsun. Bu senin başlangıç pozisyonun.', 'Kollarını hafifçe bükerek ellerini yukarı ve vücudunun orta hattına doğru çek. Ellerin göğsünün önünde, avuçların yukarı bakacak şekilde buluşsun.', 'Kısa bir an bekle, sonra kollarını başlangıç pozisyonuna geri götür.']::text[]),
  ('Low_Cable_Triceps_Extension', 'tr', array['İstediğin ağırlığı seç ve halat takılı bir oturarak çekiş makinesinin sehpasına sırtüstü uzan. Başın aparatın olduğu tarafa baksın.', 'Halatın uçlarını dıştan, avuçların birbirine bakacak şekilde tut (nötr tutuş).', 'Dirseklerini 90 derece bük ve üst kollarını gövdene dik (90 derece) konuma getir. İpucu: Dirseklerini içeride tut. Üst kolların tavanı, ön kolların başının üstündeki makarayı göstersin. Bu senin başlangıç pozisyonun.', 'Nefes verirken ön kollarını düz ve dikey olana kadar uzat. Üst kolların ve dirseklerin hareket boyunca sabit kalsın; yalnızca ön kolların hareket etsin. Triseps kasını bir saniye iyice sık.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Low_Pulley_Row_To_Neck', 'tr', array['Halat aparatı takılı, alt makaralı bir çekiş makinesine otur.', 'Halatın uçlarını avuçların aşağı bakacak şekilde tut. Sırtın düz, dizlerin hafif bükülü otur. İpucu: Sırtın neredeyse tam dik, kolların önünde tamamen uzanmış olsun. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tutarak dirseklerini kaldır ve bük; nefes verirken halatı boynuna doğru çek. Üst kolların hareket boyunca yere paralel kalsın. İpucu: Ellerin neredeyse kulaklarının yanına gelene ve dirseklerin gövdenden uzakta, dışa açık olana kadar çek. Hareketin sonunda ön kolların yere paralel olmaz, biraz yukarı doğru açılı durur.', 'Kasılı pozisyonda bir saniye kadar bekle, sonra nefes alırken yavaşça başlangıç pozisyonuna dön. İpucu: Yine, hareketin hiçbir anında gövden oynamasın.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Lower_Back-SMR', 'tr', array['Otur ve belinin altına bir foam roller yerleştir. Kollarını önünde çaprazla ve omuzlarını öne doğru getir. Bu senin başlangıç pozisyonun.', 'Kalçanı yerden kaldır ve geriye yaslan; ağırlığın belinde olsun. Sonra ağırlığını hafifçe bir yana kaydır: yük omurgada değil, yanındaki kaslarda olsun. Belinin üstünde yuvarlan ve gergin noktalarda 10-30 saniye bekle. Öbür tarafta tekrarla.']::text[]),
  ('Lower_Back_Curl', 'tr', array['Kolların yanlara açık şekilde yüzüstü yat. Bu senin başlangıç pozisyonun.', 'Bel kaslarını kullanarak omurganı geriye doğru uzat ve göğsünü yerden kaldır. Kendini kollarınla yukarı itme. Hareket boyunca başın yukarıda kalsın. 10-20 tekrar yap.']::text[]),
  ('Lunge_Pass_Through', 'tr', array['Gövden dik, sağ elinde bir kettlebell ile ayakta dur. Bu senin başlangıç pozisyonun.', 'Sol ayağınla öne adım at. Kalçanı ve dizini bükerek üst gövdeni alçalt, gövden dik kalsın. Arkadaki dizin neredeyse yere değene kadar in.', 'Lunge sırasında kettlebell''i öndeki bacağının altından öbür eline geçir.', 'Topuğunla yere bastırarak başlangıç pozisyonuna dön.', 'Bacak değiştirerek hareketi önerilen tekrar sayısı kadar yap.']::text[]),
  ('Lunge_Sprint', 'tr', array['Smith makinesinin barını uygun yüksekliğe ayarla. Barın altına gir ve onu omuzlarının arkasına yerleştir. Barı askıdan al, sonra bir ayağını öne, bir ayağını geriye alarak ayaklarını ayır. Bu senin başlangıç pozisyonun.', 'Dizlerini bükerek ve kalçanı indirerek arkadaki dizini neredeyse yere kadar alçalt.', 'İnişin en alt noktasında hemen yön değiştir. Öndeki ayağının topuğundan patlayıcı şekilde güç al, arkadaki ayağınla hafifçe bastır. Yukarı sıçra ve bacaklarının yerini değiştir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Lying_Bent_Leg_Groin', 'tr', array['Dizlerin bükülü, ayak tabanların birbirine bastırılmış şekilde sırtüstü yat. Partnerin dizlerini tutsun. Bu senin başlangıç pozisyonun.', 'Dizlerini birbirine doğru sıkıştırmaya çalış; partnerin ise herhangi bir hareket olmasını engellesin.', '10-20 saniye sonra kaslarını gevşet, partnerin de dizlerini nazikçe yere doğru itsin. Sakatlanmamak ve aşırı esnememek için esneme yeterli olduğunda yardımcına mutlaka haber ver.']::text[]),
  ('Lying_Cable_Curl', 'tr', array['Alt makaraya düz bar ya da EZ bar tak. Barı iki elinle, omuz genişliğinde ve avuçların yukarı bakacak şekilde (alttan tutuş) kavra.', 'Ağırlık bloğunun önüne bir mat ser ve sırtüstü uzan. Bacakların düz olsun, ayak tabanlarını makinenin gövdesine daya.', 'Kollarını uzat, dirseklerini gövdene yakın tut ve kollarını çok hafif bük. Başlangıç pozisyonun bu.', 'Nefes ver ve barı yavaşça göğsüne doğru çek, bisepsini sık. Üst kolların kıpırdamasın, dirseklerin gövdene yakın kalsın.', 'Tepede bir saniye sık, sonra yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Cambered_Barbell_Row', 'tr', array['Kavisli bir barı egzersiz sehpasının altına koy.', 'Sehpaya yüzüstü uzan. Barı omuz genişliğinden daha açık, avuçların aşağı bakacak şekilde (üstten tutuş) kavra. Başlangıç pozisyonun bu.', 'Nefes ver ve dirseklerini gövdene yakın tutarak barı yukarı çek. Orta sırtın üst kısmını çalıştırmak için göğsüne, kanatları çalıştırmak istiyorsan karnına doğru çek.', 'Tepede bir saniye bekle, sonra nefes alarak barı yavaşça başlangıç pozisyonuna indir.']::text[]),
  ('Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'tr', array['Düz bir sehpayı yüksek makaranın ya da lat pulldown makinesinin önüne yerleştir.', 'Düz barı yaklaşık omuz genişliğinde, avuçların yukarı bakacak şekilde (alttan tutuş) kavra.', 'Sırtüstü uzan, başın sehpanın ucunun üzerinde olsun.', 'Kollarını omuzlarının üzerinde dümdüz yukarı uzat. Kolların ile gövden arasında 90 derecelik açı olsun, dirseklerin içe baksın. Başlangıç pozisyonun bu.', 'Nefes ver ve barı yarım daire çizerek çenene değene kadar aşağı çek. Bu kasılı konumda bisepsini bir saniye sık. İpucu: Bu harekette yalnızca ön kolların oynar. Üst kolların hiçbir anda kıpırdamaz, hareket boyunca dik kalır.', 'Yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'tr', array['Bir halteri ya da EZ barı üstten tutuşla (avuçlar ileri bakar) kavra ve düz bir sehpaya sırtüstü uzan, başın sehpanın ucuna yakın olsun. İpucu: Halteri omuz genişliğinde, EZ barı ise iç tutma yerlerinden kavra.', 'Kollarını önünde uzat. Sonra kollarını bükmeden barı yarım daire çizerek yavaşça geriye, başının üzerine götür. Kolların artık başının üstünde ve yere paralel. Başlangıç pozisyonun bu. İpucu: Dirseklerin hep içeride kalsın.', 'Nefes al ve dirseklerini bükerek barı indir. Üst kolların kıpırdamasın. Ön kolların yere dik olana kadar inmeye devam et.', 'Nefes ver ve barı yarım daire çizerek yeniden başlangıç pozisyonuna it, ön kolların da yere paralel olsun. Tepede trisepsini bir saniye güçlüce sık. İpucu: Yine yalnızca ön kolların oynar. Üst kolların her an sabit kalır.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'tr', array['Bir halteri ya da EZ barı üstten tutuşla (avuçlar ileri bakar) kavra ve düz bir sehpaya sırtüstü uzan, başın sehpanın ucundan dışarı taşsın. İpucu: Halteri omuz genişliğinde, EZ barı ise iç tutma yerlerinden kavra.', 'Kollarını uzat ve barı göğsünün üzerinde tut. Kolların gövdene dik, yani 90 derecelik açıda olsun. Başlangıç pozisyonun bu.', 'Nefes al ve dirseklerini bükerek barı yarım daire çizerek indir. Üst kolların kıpırdamasın, dirseklerin içeride kalsın. Bar çenene hafifçe değene kadar in.', 'Nefes ver ve barı yarım daire çizerek yeniden başlangıç pozisyonuna it. Tepede trisepsini bir saniye güçlüce sık. İpucu: Yine yalnızca ön kolların oynar. Üst kolların her an sabit kalır.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Crossover', 'tr', array['Sırtüstü uzan ve bacaklarını uzat.', 'Bir dizini bük ve o bacağı gövdenin üzerinden karşıya geçir, dizini yere değdirmeye çalış. Partnerin yanında diz çöker, bir eliyle omzunu yerde tutar, diğeriyle çapraz bacağı yönlendirir. Başlangıç pozisyonun bu.', 'Bükülü dizini yerden kaldırmaya çalış, partnerin ise dizin gerçekten oynamasına izin vermesin.', '10-20 saniye sonra bacağını gevşet, partnerin dizini nazikçe yere doğru bastırsın. Aynısını diğer tarafta yap.']::text[]),
  ('Lying_Dumbbell_Tricep_Extension', 'tr', array['Düz bir sehpaya uzan ve iki dambılı tam üzerinde tut. Kolların tamamen düz, gövdene ve yere 90 derecelik açıda olsun. Avuçların birbirine baksın, dirseklerin içeride dursun. Başlangıç pozisyonu bu.', 'Nefes al ve dambılları kulaklarının yanına gelene kadar yavaşça indir. Üst kolların kıpırdamasın, dirseklerin içeride kalsın.', 'Oradan nefes vererek dambılları trisepsinle başlangıç pozisyonuna kaldır. Dirseklerin yine içeride, üst kolların sabit kalsın.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Face_Down_Plate_Neck_Resistance', 'tr', array['Düz bir sehpaya vücudun dümdüz olacak şekilde yüzüstü uzan ve başının arkasında bir ağırlık plakası tut. İpucu: Omuzların sehpanın ucundan biraz dışarıda olacak şekilde yerleş; böylece göğsünün üst kısmı, boynun ve yüzün sehpanın dışında kalır. Başlangıç pozisyonun bu.', 'Plakayı başının arkasında sağlam tut. Nefes al ve "evet" der gibi başını yavaşça indir.', 'Nefes ver ve başını yarım daire çizerek başlangıç pozisyonuna kaldır. Kasılmayı bir saniye tut.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Face_Up_Plate_Neck_Resistance', 'tr', array['Düz bir sehpaya vücudun dümdüz olacak şekilde sırtüstü uzan ve alnının üzerinde bir ağırlık plakası tut. İpucu: Omuzların sehpanın ucundan biraz dışarıda olacak şekilde yerleş; böylece trapezin, boynun ve başın sehpanın dışında kalır. Başlangıç pozisyonun bu.', 'Plakayı alnında sağlam tut. Nefes al ve başını yarım daire çizerek yavaşça geriye bırak.', 'Nefes ver ve başını yarım daire çizerek başlangıç pozisyonuna kaldır. Kasılmayı bir saniye tut.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Glute', 'tr', array['Sırtüstü uzan. Partnerin yanında diz çöksün.', 'Bir bacağını kalça ekleminden bük ve yerden kaldır. Bacağını, ayağın karşı kalçanın üzerine gelecek ve alt bacağın gövdene dik duracak şekilde çevir. Partnerin dizini ve ayak bileğini bu konumda tutsun. Başlangıç pozisyonun bu.', 'Bacağını partnerine doğru itmeye çalış; partnerin bacağın gerçekten oynamasını engellesin.', '10-20 saniye sonra tamamen gevşe, partnerin ayak bileğini ve dizini nazikçe göğsüne doğru itsin. Sakatlanmamak ya da fazla esnememek için esneme yeterli olduğunda yardımcına mutlaka söyle.']::text[]),
  ('Lying_Hamstring', 'tr', array['Sırtüstü uzan ve bacaklarını uzat. Partnerin yanında diz çöksün. Bir bacağını tavana doğru kaldır, partnerin ayak bileğinden tutsun. Gerekirse partnerin bacağını omzuyla destekleyebilir. Başlangıç pozisyonun bu.', 'Partnerin bacağını yerinde tutarken dizini bükmeye çalış ve arka bacak kaslarını 10-20 saniye kas.', 'Sonra bacağını gevşet, partnerin bacağı nazikçe başına doğru itsin. Sakatlanmamak ya da fazla esnememek için esneme yeterli olduğunda yardımcına mutlaka söyle. Bitince taraf değiştir.']::text[]),
  ('Lying_High_Bench_Barbell_Curl', 'tr', array['Yüksek, düz bir sehpaya yüzüstü uzan ve halteri alttan tutuşla (avuçlar yukarı bakar) tut. İpucu: Halteri omuz genişliğinde, EZ barı ise iç tutma yerlerinden kavra. Göğsünün üst kısmı sehpanın ucunun üzerinde olsun, bar önünde sarksın, kolların düz ve yere dik dursun. Başlangıç pozisyonun bu.', 'Nefes ver, bisepsini kas ve ağırlığı yarım daire çizerek yukarı kaldır. Dirseklerin içeride kalsın, üst kolların kıpırdamasın. Tepede bir saniye bekle.', 'Nefes al ve yavaşça başlangıç pozisyonuna dön. İpucu: Ağırlık her an tam kontrolünde olsun, sallanarak hız alma. Unutma, hareket boyunca yalnızca ön kolların oynar.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Leg_Curls', 'tr', array['Leg curl makinesinin kolunu boyuna göre ayarla. Makineye yüzüstü uzan; kolun yastığı bacaklarının arkasında, baldırların birkaç inç altında dursun. İpucu: Mümkünse düz değil, açılı bir makine seç; açılı konum arka bacak kaslarını daha iyi çalıştırır.', 'Gövden sehpada düz kalsın, bacaklarını tamamen uzat ve makinenin yan tutacaklarını kavra. Ayak parmakların düz baksın. Başlangıç pozisyonun bu.', 'Nefes ver ve bacaklarını gidebildiği kadar yukarı bük. Üst bacakların yastıktan kalkmasın. Kasların tam kasıldığında bir saniye bekle.', 'Nefes al ve bacaklarını ilk konumuna indir. Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Machine_Squat', 'tr', array['Bacak makinesini, dizlerin bükülü ve üst bacakların paralelin biraz altında olacak şekilde içine girebileceğin yüksekliğe ayarla.', 'Ağırlığı seç, sonra makineye sırtüstü yerleş; dizlerin bükülü, üst bacakların platforma paralelin biraz altında olsun. Dizlerin ayak parmaklarını geçmesin. Arka bacak ile baldır arasındaki açı 90 dereceden biraz az olsun, çünkü paralelin biraz altından başlıyorsun. Sırtın ve başın makineye yaslansın, omuzların omuz yastıklarının altına bassın.', 'Ellerini tutacaklara koy. Ayaklarını omuz genişliğinde, uçları hafifçe dışa dönük yerleştir. Başlangıç pozisyonun bu.', 'Nefes ver, ayaklarının ön tabanıyla it ve ön bacak kaslarını sıkarak bütün vücudunu doğrult. Bu kasılı konumda bir saniye bekle. İpucu: Paralelin altından başladığın için, yalnızca ilk tekrarda ellerinle üst bacaklarına bastırarak kendine yardım edebilirsin.', 'Nefes al ve yavaşça çömel. Başlangıç pozisyonuna kadar inme, üst bacakların platforma paralel olunca dur. Arka bacak ile baldır arasında 90 derecelik açı olsun.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_One-Arm_Lateral_Raise', 'tr', array['Bir eline dambıl al ve göğsün aşağıda olacak şekilde düz bir sehpaya uzan. Denge için boştaki elinle sehpanın ayağını tutabilirsin.', 'Dambılı tutan elini nötr konuma getir, avucun gövdene baksın. Kolun uzanmış, dirseğin hafif bükülü olsun. Başlangıç pozisyonun bu.', 'Nefes ver ve dambıllı kolunu yana doğru kaldır; dirseğin omuz hizasına gelsin, kolun aşağı yukarı yere paralel olsun. İpucu: Kolun hareket boyunca uzanmış ve gövdene dik kalsın. Ayrıca tepede kasılmayı bir saniye tut.', 'Nefes al ve dambılı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Prone_Quadriceps', 'tr', array['Yere yüzüstü uzan. Partnerin yanında diz çöksün. Bir dizini bük ve o bacağı yerden kaldır, ayağını kalçana değdirmeye çalış. Partnerin dizini ve ayak bileğini tutsun. Başlangıç pozisyonun bu.', 'Dizini düzeltmeye çalış, partnerin ise dizin gerçekten oynamasına izin vermesin.', '10-20 saniye sonra kaslarını gevşet, partnerin ayağını nazikçe kalçana doğru itsin. Böylece ön bacak kasları ve kalça bükücüler daha da esner.', '10-20 saniye sonra taraf değiştir.']::text[]),
  ('Lying_Rear_Delt_Raise', 'tr', array['İki eline birer dambıl al ve göğsün aşağıda olacak şekilde düz bir sehpaya uzan.', 'Ellerini nötr konuma getir, avuçların gövdene baksın. Kolların uzanmış, dirseklerin hafif bükülü olsun. Başlangıç pozisyonun bu.', 'Nefes ver ve kollarını yanlara doğru kaldır; dirseklerin omuz hizasına gelsin, kolların aşağı yukarı yere paralel olsun. İpucu: Kolların hareket boyunca uzanmış ve gövdene dik kalsın. Ayrıca tepede kasılmayı bir saniye tut.', 'Nefes al ve dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla, sonra diğer kola geç.']::text[]),
  ('Lying_Supine_Dumbbell_Curl', 'tr', array['Düz bir sehpaya sırtüstü uzan; iki elinde birer dambıl, üst bacaklarının üzerinde dursun.', 'Dambılları yanlarına al. Kolların düz, avuçların üst bacaklarına baksın (nötr tutuş).', 'Kollarını yavaşça, inebildiği kadar yere doğru bırak. Kolların gövdene yakın, dirseklerin içeride olsun; kolların uzanmış, dirseklerin yalnızca hafif bükülü kalsın. Daha fazla inemediğinde üst kollarını o konumda sabitle. Başlangıç pozisyonun bu.', 'Nefes ver ve dambılları yavaşça yukarı bük; aynı anda bileklerini avuçların yukarı bakana kadar çevir. Bisepsin tam kasılana kadar devam et ve tepede bir saniye güçlüce sık. İpucu: Yalnızca ön kolların oynar. Hareket boyunca üst kolların sabit, dirseklerin içeride kalır.', 'Çok yavaş bir şekilde başlangıç pozisyonuna dön.']::text[]),
  ('Lying_T-Bar_Row', 'tr', array['T-bar row makinesine istediğin ağırlığı tak. Bacak yüksekliğini, göğsünün üst kısmı yastığın tepesine gelecek şekilde ayarla. İpucu: Bazı makinelerde yapabileceğin tek şey, göğsünün üst kısmını yastığın tepesine getiren basamağa basmaktır.', 'Yastığa yüzüstü uzan ve tutacakları kavra. Avuçların aşağı, yukarı ya da içe bakabilir; sırtının hangi bölümünü öne çıkarmak istediğine göre seç.', 'Barı askıdan kaldır ve kollarını önünde uzat. Başlangıç pozisyonun bu.', 'Nefes ver, ağırlığı yavaşça yukarı çek ve tepede sırtını sık. İpucu: Sırt kaslarını daha iyi çalıştırmak için üst kollarını hareket boyunca gövdene olabildiğince yakın tut. Ayrıca vücudunu hiçbir an yastıktan kaldırma ve ağırlığı bisepsinle çekme.', 'Tepede kasılmayı bir saniye tut, sonra nefes alarak yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Lying_Triceps_Press', 'tr', array['Düz bir sehpaya uzan, ayakların yerde olsun. Başının arkasında, yerde bir EZ bar (tercihen) ya da düz bar dursun.', 'Arkana uzan ve barı orta genişlikte, üstten tutuşla kavra. Barı kolların düzleşene kadar üzerine kaldır. İpucu: Kolların gövdene ve yere dik, dirseklerin içeride olsun. Başlangıç pozisyonu bu.', 'Nefes al ve barı alnına hafifçe değene kadar yavaşça indir. Üst kolların ve dirseklerin kıpırdamasın.', 'Oradan nefes vererek barı trisepsinle başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Machine_Bench_Press', 'tr', array['Chest press makinesine otur ve ağırlığı seç.', 'Makinenin ayak koluna bas. Bu kol tutacakları öne getirir; böylece onları kavrayıp kollarını tamamen uzatabilirsin.', 'Tutacakları avuçların aşağı bakacak şekilde kavra. Dirseklerini kaldır; üst kolların gövdenin yanlarında, yere paralel olsun. İpucu: Tutacakları tuttuğun için ön kolların ileriyi gösterir. Tutacaklar önde ve kolların düzken başlangıç pozisyonundasın.', 'Nefes al ve tutacakları kendine doğru getir.', 'Nefes ver ve göğüs kaslarını sıkarak tutacakları kendinden uzağa it. Kasılmayı bir saniye tut, sonra başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.', 'Bitirince yine ayak koluna bas ve tutacakları yavaşça eski yerine götür.']::text[]),
  ('Machine_Bicep_Curl', 'tr', array['Oturağı uygun yüksekliğe ayarla ve ağırlığını seç. Üst kollarını yastıklara yasla ve tutacakları kavra. Başlangıç pozisyonun bu.', 'Dirseklerini bük ve ön kollarını üst kollarına doğru çek.', 'Tepede kısa bir an dur, sonra ağırlığı yavaşça başlangıç pozisyonuna indir.', 'Set bitene kadar ağırlığı durduruculara kadar indirme. Böylece çalışan kaslar gerilim altında kalır.']::text[]),
  ('Machine_Preacher_Curls', 'tr', array['Preacher curl makinesine otur ve ağırlığı seç.', 'Üst kollarının arkasını (trisepsini) yastığa yasla ve tutacakları avuçların yukarı bakacak şekilde (alttan tutuş) kavra. İpucu: Kollarını yastığa koyarken dirseklerini içeride tut. Başlangıç pozisyonun bu.', 'Nefes ver, bisepsini kas ve tutacakları kaldır. Tepede kasılmayı bir saniye tut. İpucu: Yalnızca ön kolların oynar. Üst kolların her an sabit ve yastığın üzerinde kalır.', 'Nefes al ve tutacakları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Machine_Shoulder_Military_Press', 'tr', array['Shoulder press makinesine otur ve ağırlığı seç.', 'Yanlarındaki tutacakları kavra. Dirseklerin bükülü ve gövdenle aynı hizada olsun. Başlangıç pozisyonun bu.', 'Nefes ver ve tutacakları kolların tamamen düzleşene kadar yukarı it. Tepede kasılmayı bir saniye tut.', 'Nefes al ve tutacakları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Machine_Triceps_Extension', 'tr', array['Oturağı uygun yüksekliğe ayarla ve ağırlığını seç. Üst kollarını yastıklara yasla ve tutacakları kavra. Başlangıç pozisyonun bu.', 'Dirseklerini düzelt ve ön kollarını üst kollarından uzaklaştır.', 'Hareketin sonunda kısa bir an dur, sonra ağırlığı yavaşça başlangıç pozisyonuna bırak.', 'Set bitene kadar ağırlığı durduruculara kadar indirme. Böylece çalışan kaslar gerilim altında kalır.']::text[]),
  ('Medicine_Ball_Chest_Pass', 'tr', array['Bu egzersiz için bir partner gerekir. Partnerin yoksa topu duvara at.', 'Partnerinle yüz yüze dur ve sağlık topunu iki elinle gövdenin önünde tut.', 'Topu göğsüne çek, sonra hareketi tersine çevir ve dirseklerini düzelterek at. Spora yönelik çalışıyorsan atarken bir adım atabilirsin.', 'Partnerin topu yakalar ve sana geri atar.', 'Topu iki elinle göğüs hizasında karşıla.']::text[]),
  ('Medicine_Ball_Full_Twist', 'tr', array['Bir sağlık topu ve bir partner gerekir. Partnerinle sırt sırta, aranızda 2-3 fit olacak şekilde durun. Başlangıç pozisyonun bu.', 'Topu gövdenin önünde tut. Partnerinle aynı anda kalçanı aç ve omuzlarını çevir.', 'Tam dönüş için ikiniz de aynı yöne, örneğin saat yönünün tersine dönün.', 'Topu partnerine ver. Sonra ikiniz de ters yöne dönün ve aynısını tekrarlayın.']::text[]),
  ('Medicine_Ball_Scoop_Throw', 'tr', array['Ellerinde bir sağlık topuyla yarım çömelme duruşuna geç. Kolların sarksın, top ayaklarının yakınında olsun.', 'Kalçanı güçlüce öne it, bacaklarını düzelt ve yukarı sıçra.', 'Sıçrarken düz kollarını yukarı ve başının üzerinden geriye savur, topu hareketin en yüksek noktasında bırak. Amaç topu arkana olabildiğince uzağa atmak.']::text[]),
  ('Middle_Back_Shrug', 'tr', array['İki elinde birer dambılla eğimli bir sehpaya yüzüstü uzan. Kolların tamamen düz sarksın ve yeri göstersin. Avuçların birbirine baksın. Başlangıç pozisyonun bu.', 'Nefes ver, kürek kemiklerini birbirine yaklaştır ve tam bir saniye tut. İpucu: Bu hareket sarılmanın tam tersidir; kolların yokmuş gibi arka omuz açışı yapmaya da benzer.', 'Nefes al ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Middle_Back_Stretch', 'tr', array['Ayaklarını omuz genişliğinde aç ve ellerini beline koy.', 'Bir esneme hissedene kadar belinden dön. 10 ila 15 saniye tut, sonra diğer tarafa dön.']::text[]),
  ('Mixed_Grip_Chin', 'tr', array['Barfiks barını omuz genişliğinden yaklaşık 1 inç açık tut. Bir avucun ileri, diğeri sana baksın. Başlangıç pozisyonun bu.', 'Nefes ver ve kendini yukarı çekmeye başla. İpucu: Avucu yukarı bakan kolda hareketi sırt kaslarınla yapmaya odaklan ve o dirseği gövdene yakın tut. Avucu ileri bakan kolda dirsek gövdeden uzakta ama gövdeyle aynı hizada durur; orada vücudunu kanat kaslarınla çekmeye odaklan.', 'Tepede bir saniye kasılı kal, sonra nefes alarak yavaşça in.', 'Önerilen tekrar sayısını tamamla.', 'Sonraki sette tutuşu değiştir. Sağ avucun sana, sol avucun ileri bakıyorduysa, bu kez sağ avucun ileri, sol avucun sana baksın.']::text[]),
  ('Monster_Walk', 'tr', array['Bir lastik bandı iki ayak bileğine, bir diğerini iki dizine geçir. Ayakların omuz genişliğindeyken bantlar gergin olmalı.', 'Önce sol ve sağ ayağını sırayla atarak kısa adımlarla ileri yürü.', 'Birkaç adımdan sonra tersini yap ve geri geri başladığın yere yürü.']::text[]),
  ('Mountain_Climbers', 'tr', array['Şınav pozisyonunda başla, ağırlığın ellerinde ve ayak parmaklarında olsun. Bir bacağını dizinden ve kalçandan bükerek öne çek; diz aşağı yukarı kalçanın altına gelsin. Başlangıç pozisyonun bu.', 'Bacaklarının yerini patlayıcı bir hareketle değiştir: bükülü bacağı düzleşip ayak parmaklarına basana kadar geriye uzat, diğer ayağını kalçan ve dizin bükülü şekilde öne çek. 20-30 saniye boyunca sırayla tekrarla.']::text[]),
  ('Moving_Claw_Series', 'tr', array['Bu çalışma koşu formunu hazırlar ve sprintte daha iyi olmana yardım eder. Koşarken dizini bük ve kalçan açılırken topuğunla kalçana vurmayı hedefle.', 'Bacağın yeniden öne gelirken ön bacak kasını tekrar yükle ve bir sonraki adımda yere saldır.', 'Koşarken kollarınla blok yap ve onları hızlı bir 1-2 hareketiyle ileri savur.']::text[]),
  ('Muscle_Snatch', 'tr', array['Ağırlık takılı halteri geniş tutuşla üst bacağının ortası hizasında tut. Ayakların tam kalçalarının altında, gerektiği kadar dışa dönük olsun. Kalçanı indir, göğsün yukarıda olsun, ileri bak. Omuzların barın hemen önünde dursun. Başlangıç pozisyonu bu.', 'Çekişe topuklarının ön kısmından iterek başla ve barı kaldır. İkinci çekişe geç: kalçanı, dizlerini ve ayak bileklerini aç, barı olabildiğince hızlı yukarı sür. Bar gövdene yakın kalsın.', 'Dizlerini yeniden bükmeden barı baş üstü konuma kadar kaldırmaya devam et.']::text[]),
  ('Muscle_Up', 'tr', array['Halkaları sahte tutuşla kavra: avuç içinin dip kısmı halkanın üstünde dursun. Dirseklerini bükerek ve yanlarına doğru aşağı çekerek barfiks hareketine başla.', 'Barfiksin tepe noktasına gelince halkaları koltuk altlarına çek ve omuzlarını öne yuvarla; dirseklerin dümdüz arkana gitsin. Bu konum, hareketin dips bölümüne geçmen için doğru konumdur.', 'Kontrolü ve dengeni koru, dirseklerini düzelterek hareketi tamamla.', 'Kendini yere indirirken dikkatli ol.']::text[]),
  ('Narrow_Stance_Hack_Squats', 'tr', array['Sırtını makinenin sırt yastığına yasla ve omuzlarını omuz yastıklarının altına yerleştir.', 'Ayaklarını platforma dar duruşla, omuz genişliğinden dar ve uçları hafifçe dışa dönük koy. Ayaklarının arası yaklaşık 3 inç ya da daha az olsun. İpucu: Başını hep yukarıda, sırtını hep yastıkta tut.', 'Ellerini makinenin yan tutacaklarına koy ve emniyet kollarını aç. Çoğu makinede bunun için yan tutacakları öne bakan konumdan çapraz konuma çevirirsin.', 'Bacaklarını dizlerini kilitlemeden düzelt. Başlangıç pozisyonun bu.', 'Nefes al ve dizlerini bükerek kızağı yavaşça indir. Dik dur, başın yukarıda, sırtın hep yastıkta olsun. Üst bacak ile baldır arasındaki açı 90 dereceden biraz az olana kadar in; bu noktada üst bacakların yere paralelin altındadır.', 'Nefes ver ve kızağı kaldır: en çok topuklarınla it, bacaklarını düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Narrow_Stance_Leg_Press', 'tr', array['Leg press makinesine otur ve ayaklarını tam önündeki platforma dar duruşla, omuz genişliğinden dar ve uçları hafifçe dışa dönük koy. Ayaklarının arası yaklaşık 3 inç ya da daha az olsun. İpucu: Başını hep yukarıda, sırtını hep yastıkta tut.', 'Ağırlıklı platformu tutan emniyet kollarını aç ve bacakların önünde tamamen düzleşene kadar platformu yukarı it. İpucu: Dizlerini kilitleme. Gövden ile bacakların arasında tam 90 derecelik açı olsun. Başlangıç pozisyonun bu.', 'Nefes al ve üst bacakların ile alt bacakların arasında 90 derecelik açı oluşana kadar platformu yavaşça indir.', 'Nefes ver ve başlangıç pozisyonuna dön; en çok topuklarınla it ve ön bacak kaslarını kullan.', 'Önerilen tekrar sayısını tamamla ve bitirince emniyet pimlerini düzgünce kilitle. Tam yüklü platformun üzerine düşmesini istemezsin.']::text[]),
  ('Narrow_Stance_Squats', 'tr', array['Güvenlik için bu hareketi squat rack içinde yap. Barı boyuna uygun yükseklikte sehpaya yerleştir ve ağırlıkları tak. Sonra barın altına gir ve barı omuzlarının arkasına, boynunun biraz altına oturt.', 'Barı iki yanından iki elinle tut. Bacaklarınla iterek ve aynı anda gövdeni doğrultarak barı sehpadan kaldır.', 'Sehpadan bir adım uzaklaş. Ayaklarını omuz genişliğinden dar, aralarında yaklaşık 3-6 inç olacak şekilde yerleştir; parmak uçların hafifçe dışa baksın. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtın da düz kalsın. Bu senin başlangıç pozisyonun. Not: Burada anlatılan duruş genel gelişimi hedefler, ama başka bir duruş genişliği de seçebilirsin.', 'Dizlerini bükerek barı yavaşça indir; gövden dik, başın yukarıda kalsın. Üst bacağın ile baldırın arasındaki açı 90 dereceden biraz küçük olana kadar in; bu noktada üst bacakların yere paralel çizginin altına iner. İnerken nefes al. İpucu: Hareket doğruysa dizlerinin önü ayak parmaklarınla öne dik, hayali bir düz çizgi oluşturur. Dizlerin ayak parmaklarını geçiyorsa dizine gereksiz yük bindiriyorsun ve hareket yanlış yapılmış demektir.', 'Nefes verirken barı yeniden yukarı çıkar: ağırlıklı olarak topuklarınla yeri it, bacaklarını düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Natural_Glute_Ham_Raise', 'tr', array['Lat pulldown makinesinin bacak yastığını ya da bir preacher sehpasını kullan. Sırtın makineye dönük olacak şekilde dizlerini oturağa koy ve ayak bileklerini yastıkların altına sabitle. Dik dur ve duruşunu bozma.', 'Bu senin başlangıç pozisyonun. Dizlerin neredeyse tamamen düzelene kadar kendini kontrollü biçimde aşağı bırak.', 'Kontrolü kaybetmeden kendini tekrar başlangıç pozisyonuna çek.', 'Bir tekrarı tamamlayamıyorsan lastik banttan ya da bir partnerden destek al veya kendini bir kasadan iterek yardım et.']::text[]),
  ('Neck-SMR', 'tr', array['Bir masaj rulosu ya da oklava al ve başının arkasında boynuna yasla. Ruloyu doğrudan omurgaya bastırma: hafifçe çevir ki omurganın yanındaki kaslara otursun. Bu senin başlangıç pozisyonun.', 'Boynunun en üstünden başla ve boyun kasların boyunca yavaşça aşağı doğru yuvarla. Gergin noktalarda 10-30 saniye bekle.']::text[]),
  ('Neck_Press', 'tr', array['Düz bir sehpaya sırtüstü uzan. Barı orta genişlikte tut; bu tutuşta hareketin ortasında ön kolların ile üst kolların arasında 90 derecelik açı oluşur. Barı sehpadan al ve kolların kilitli halde tam boynunun üzerinde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı boynunda hissedene kadar yavaşça indir.', 'Bir saniye bekle, sonra nefes verirken göğüs kaslarınla barı başlangıç pozisyonuna it. Kollarını kilitle, yukarıda göğsünü sık, bir saniye tut ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Belirlenen tekrar sayısı kadar yap.', 'Bitirdiğinde barı sehpaya geri koy.']::text[]),
  ('Oblique_Crunches', 'tr', array['Yere sırtüstü uzan ve belini zemine bastır. Bir elini başının yanına koy, diğerini yana açıp yere yasla.', 'Ayaklarını yükselt ve düz bir yüzeye yerleştir.', 'Şimdi elin başının yanında olan taraftaki omzunu kaldır.', 'Omzunu ve gövdeni dizine ulaşana kadar yukarı kaldır. Örneğin sağ elin başının yanındaysa sağ dirseğin sol dizine değene kadar yüksel. Aynısını ters yönde de yapabilirsin; o zaman sol dirseğini sağ dizine götürürsün.', 'Dirseğin dizine değdikten sonra gövdeni başlangıç pozisyonuna indir.', 'Hareketin eksantrik (iniş) kısmında nefes al, konsantrik (yükseliş) kısmında nefes ver.', 'Her iki taraf için önerilen tekrarların hepsi bitene kadar bu şekilde sırayla devam et.']::text[]),
  ('Oblique_Crunches_-_On_The_Floor', 'tr', array['Sağ yanına uzan, bacakların üst üste dursun. Dizlerini biraz bük.', 'Sol elini başının arkasına koy.', 'Bu pozisyondan sol dirseğini normal bir mekikteki gibi yukarı götür; ancak bu kez asıl yük yan karın kaslarında olsun.', 'Çıkabildiğin kadar yüksel, kasılmayı bir saniye tut, sonra yavaşça başlangıç pozisyonuna in.', 'Hareketin eksantrik (iniş) kısmında nefes al, konsantrik (kalkış) kısmında nefes ver.']::text[]),
  ('Olympic_Squat', 'tr', array['Halteri trapezinin üstüne yerleştir. Göğsün yukarıda olsun, başın öne baksın. Ayaklarını kalça genişliğinde aç ve gerektiği kadar dışa çevir.', 'Dizlerini bükerek in ve kalçanı elinden geldiğince geriye götürme. Bunun için dizlerin öne gitmesi gerekir; ayaklarınla aynı hizada kalmalarına dikkat et. Amaç gövdeyi olabildiğince dik tutmak. Ağırlığı topuğunun ön kısmında tutarak en aşağıya kadar in.', 'Üst bacakların alt bacaklarına değdiği anda hareketi tersine çevir ve ağırlığı yukarı it.']::text[]),
  ('On-Your-Back_Quad_Stretch', 'tr', array['Düz bir sehpaya ya da step tahtasına uzan; bir bacağını ve bir kolunu kenardan aşağı sarkıt.', 'Dizini bük ve ayağının üstünü tut. Bunu yaparken belini çukurlaştırmamaya dikkat et.', 'Nötr pozisyonda kalmak için göbeğini omurgana doğru çek. Ayağını aşağıya ve eline doğru bastır. Kalça esnetmesini de eklemek istersen tuttuğun bacağın kalçasını tavana doğru kaldır.', 'Taraf değiştir.']::text[]),
  ('On_Your_Side_Quad_Stretch', 'tr', array['Sağ yanına uzan. Sağ dizini 90 derece bük ve önünde yere koy; bu gövdeni sabitler.', 'Sol dizini arkana doğru bük ve sol ayağını sol elinle tut. Kalça fleksörünü esnetmek için sol kalçanı öne iterken ayağını geriye, eline doğru bastır. Taraf değiştir.']::text[]),
  ('One-Arm_Dumbbell_Row', 'tr', array['Düz bir sehpa seç ve iki yanına birer dambıl koy.', 'Sağ bacağını sehpanın bir ucuna yerleştir. Gövdeni belden öne eğ, üst gövden yere paralel olsun; sağ elini destek için sehpanın öbür ucuna koy.', 'Yerdeki dambılı sol elinle al ve belini düz tutarak taşı. Avuç için gövdene baksın. Bu senin başlangıç pozisyonun.', 'Ağırlığı dümdüz yukarı, göğsünün yanına çek; üst kolun gövdene yakın, gövden sabit kalsın. Çekerken nefes ver. İpucu: En üst noktada sırt kaslarını sıkmaya odaklan. Kuvvet kollardan değil, sırt kaslarından gelmeli. Üst gövden sabit kalır, yalnızca kol hareket eder. Ön kolun dambılı tutmaktan başka iş yapmaz; bu yüzden dambılı ön kolunla çekmeye çalışma.', 'Ağırlığı dümdüz aşağı, başlangıç pozisyonuna indir. İndirirken nefes al.', 'Belirtilen tekrar sayısı kadar yap.', 'Taraf değiştir ve diğer kolunla tekrarla.']::text[]),
  ('One-Arm_Flat_Bench_Dumbbell_Flye', 'tr', array['Düz bir sehpaya uzan; tek elindeki dambıl uyluğunun üstünde dursun. Dambılı nötr tutuşla tut.', 'Uyluğunla destek vererek dambılı kaldır ve çalışan kolun tamamen açıkken önünde tut. Bu harekette nötr tutuşu bozma. Boştaki elin daha iyi destek için yandan sehpayı tutsun. Bu senin başlangıç pozisyonun.', 'Biseps tendonuna yük binmemesi için ağırlığı tutan kolunun dirseği hafif bükülü olsun. Kolunu geniş bir yay çizerek yana doğru indir; göğsünde gerilme hissedince dur. Bu sırada nefes al. İpucu: Hareket boyunca kolun kendisi sabit kalır; hareket yalnızca omuz ekleminde olur.', 'Göğüs kaslarını sıkıp nefes verirken kolunu başlangıç pozisyonuna geri getir. İpucu: İnerken çizdiğin yayın aynısını izle.', 'Kasılı pozisyonda bir saniye bekle ve belirlenen tekrar sayısı kadar yap.', 'Kol değiştir ve egzersizi tekrarla.']::text[]),
  ('One-Arm_High-Pulley_Cable_Side_Bends', 'tr', array['Kablo kulesine standart bir tutamak tak ve makarayı en yüksek konuma getir.', 'Yan tarafın kabloya dönük dur. Bir elinle yukarı uzan ve tutamağı alttan tutuşla kavra.', 'Kabloyu dirseğin yanına değene ve tutamak omzunun yanına gelene kadar aşağı çek.', 'Ayaklarını kalça genişliğinde aç. Dönme noktasını hissetmek için boştaki elini kalçana koy.', 'Kolunu sabit tut. Yan karın kasını kasarak ağırlığı yana doğru bir mekik hareketiyle aşağı getir.', 'En yüksek kasılmaya ulaşınca ağırlığı yavaşça başlangıç pozisyonuna bırak. Ağırlık plakaları hiçbir zaman yerine oturup boşa çıkmamalı; amaç set boyunca kesintisiz gerilim.', 'Tükenene kadar tekrarla.', 'Sonra yer değiştir ve aynı hareket dizisini diğer tarafta yap.']::text[]),
  ('One-Arm_Incline_Lateral_Raise', 'tr', array['Elinde bir dambılla eğimli sehpaya yan uzan. Omzun sehpaya bastırsın, kolun gövdenin önünden çapraz geçsin, avuç için göbeğinin yakınında olsun.', 'Dambılı üstte kalan kolunda tut; kolun önünde uzanmış ve yere paralel olsun. Bu senin başlangıç pozisyonun.', 'Dambılı hep yere paralel tutarak yana açış yap. Kolun tavanı gösterene kadar dümdüz yukarı çıksın. İpucu: Bu hareketi yaparken nefes ver. Dambılı o noktada bir saniye tut ve omzundaki kasılmayı hisset.', 'Nefes alırken ağırlığı gövdenin önünden çapraz geçirerek başlangıç pozisyonuna indir.', 'Belirlenen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One-Arm_Kettlebell_Clean', 'tr', array['Kettlebell''i ayaklarının arasına koy. Tutmak için eğilirken kalçanı geriye it ve gözlerin ileriye baksın.', 'Kettlebell''i omzuna al: bacaklarını ve kalçanı açarken ağırlığı omzuna doğru kaldır. Bu sırada bileğin dönsün.', 'Ağırlığı başlangıç pozisyonuna geri götür.']::text[]),
  ('One-Arm_Kettlebell_Clean_and_Jerk', 'tr', array['Kettlebell''i sapından tut.', 'Onu omzuna al: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek. Bu sırada bileğini çevir; avuç için öne baksın.', 'Dizlerini bükerek kısa bir çöküş yap, gövden dik kalsın.', 'Hemen yön değiştir ve topuklarından it; ivme kazanmak için adeta zıplarsın. Bu ivmeyi kullanarak kolunu aç ve kettlebell''i başının üzerinde kilitlenene kadar it.', 'Ağırlığın altında yeniden squat pozisyonuna inerek onu baş üstünde karşıla.', 'Ağırlık baş üstündeyken ayağa kalk. Sonraki tekrar için ağırlığı yere indir.']::text[]),
  ('One-Arm_Kettlebell_Floor_Press', 'tr', array['Tek elinde bir kettlebell ile yere uzan; üst kolun yere dayansın. Avuç için içe baksın.', 'Kettlebell''i bileğini döndürerek dümdüz tavana doğru it.', 'Kettlebell''i başlangıç pozisyonuna indir ve tekrarla.']::text[]),
  ('One-Arm_Kettlebell_Jerk', 'tr', array['Kettlebell''i sapından tut. Onu omzuna al: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek. Bu sırada bileğini çevir; avuç için öne baksın. Bu senin başlangıç pozisyonun.', 'Dizlerini bükerek kısa bir çöküş yap, gövden dik kalsın.', 'Hemen yön değiştir ve topuklarından it; ivme kazanmak için adeta zıplarsın. Bu ivmeyi kullanarak kolunu aç ve kettlebell''i başının üzerinde kilitlenene kadar it. Ağırlığın altında yeniden squat pozisyonuna inerek onu baş üstünde karşıla. Ağırlık baş üstündeyken ayağa kalk.', 'Sonraki tekrar için ağırlığı indir.']::text[]),
  ('One-Arm_Kettlebell_Military_Press_To_The_Side', 'tr', array['Kettlebell''i omzuna al: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek. Bu sırada bileğini çevir; avuç için içe baksın. Bu senin başlangıç pozisyonun.', 'Kettlebell''e bak ve kolun baş üstünde kilitlenene kadar onu yukarı ve dışa doğru it.', 'Kettlebell''i kontrollü biçimde omzuna indir ve tekrarla. Daha fazla denge ve güç için kanat, kalça ve karın kaslarını kuvvetle sık.']::text[]),
  ('One-Arm_Kettlebell_Para_Press', 'tr', array['Kettlebell''i omzuna al: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek. Bu sırada bileğini çevir; avuç için öne baksın. Bu senin başlangıç pozisyonun.', 'Kettlebell''i dirseğin yana açıkken tut ve kolun baş üstünde kilitlenene kadar onu yukarı ve dışa doğru it.', 'Kettlebell''i kontrollü biçimde omzuna indir ve tekrarla. Daha fazla denge ve güç için kanat, kalça ve karın kaslarını kuvvetle sık.']::text[]),
  ('One-Arm_Kettlebell_Push_Press', 'tr', array['Kettlebell''i sapından tut. Onu omzuna al: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek. Bu sırada bileğini çevir; avuç için öne baksın. Bu senin başlangıç pozisyonun.', 'Dizlerini bükerek kısa bir çöküş yap, gövden dik kalsın.', 'Hemen yön değiştir ve topuklarından it; ivme kazanmak için adeta zıplarsın. Bu ivmeyi kullanarak kolunu aç ve kettlebell''i başının üzerinde kilitlenene kadar it. Sonraki tekrar için ağırlığı indir.']::text[]),
  ('One-Arm_Kettlebell_Row', 'tr', array['Kettlebell''i ayaklarının önüne koy. Dizlerini hafifçe bük, sonra başlangıç pozisyonuna geçmek için öne eğilirken kalçanı olabildiğince geriye çıkar. Kettlebell''i tut ve karnına doğru çek; kürek kemiğini geriye al, dirseğini bük. Sırtın düz kalsın. İndir ve tekrarla.']::text[]),
  ('One-Arm_Kettlebell_Snatch', 'tr', array['Kettlebell''i ayaklarının arasına koy. Doğru başlangıç pozisyonuna geçmek için dizlerini bük ve kalçanı geriye it.', 'Dümdüz ileri bak ve kettlebell''i bacaklarının arasından geriye savur.', 'Hemen yön değiştir, kalçanı ve dizlerini güçlüce açarak kettlebell''i yukarı doğru hızlandır. Kettlebell omzuna yükselirken elini çevir ve dümdüz yukarı yumruk at; ivme ağırlığı baş üstünde kilitli konuma taşısın.']::text[]),
  ('One-Arm_Kettlebell_Split_Jerk', 'tr', array['Kettlebell''i sapından tut. Onu omzuna al: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek. Bu sırada bileğini çevir; avuç için öne baksın. Bu senin başlangıç pozisyonun.', 'Dizlerini bükerek kısa bir çöküş yap, gövden dik kalsın.', 'Hemen yön değiştir ve topuklarından it; ivme kazanmak için adeta zıplarsın. Bu ivmeyi kullanarak kolunu aç ve kettlebell''i başının üzerinde kilitlenene kadar it.', 'Ağırlığın altında squat pozisyonuna inerek onu baş üstünde karşıla; bir bacağın önde, diğeri arkada olsun.', 'Ağırlık baş üstündeyken ayağa kalk ve ayaklarını birleştir. Sonraki tekrar için ağırlığı indir.']::text[]),
  ('One-Arm_Kettlebell_Split_Snatch', 'tr', array['Kettlebell''i tek elinle sapından tut.', 'Yere doğru çömel, sonra hareketi tersine çevir: önce kalçanı, sonra dizlerini, en son ayak bileklerini açarak kettlebell''i başının üzerine kaldır.', 'Vücudun tamamen açıldıktan sonra ağırlığı baş üstünde karşılamak için lunge pozisyonuna in; bir bacak önde, bir bacak arkada. Kalçanı güçlüce ileri sür ve kettlebell''i tek, kesintisiz bir hareketle baş üstünde kilitle.', 'Ağırlığı baş üstünde tutarak ayağa kalk ve ayaklarını birleştir. Başlangıç pozisyonuna dönmek için ağırlığı indir.']::text[]),
  ('One-Arm_Kettlebell_Swings', 'tr', array['Ayaklarını omuz genişliğinden biraz fazla aç; kettlebell hemen önünde yerde dursun. Kalçanı geriye it, sırtını düz tut ve sapı tek elinle kavra.', 'Kettlebell''i bacaklarının arasından geriye savur. Çalışan kolun düz kalsın, boştaki kolunu denge için yana aç.', 'Kalçanı güçlüce öne it ve dizlerini düzelt; kettlebell yaklaşık göğüs hizasına kadar savrulsun. Kettlebell yükselirken nefes ver.', 'Kettlebell''in kontrollü biçimde bacaklarının arasına geri düşmesine izin ver ve doğrudan sonraki tekrara geç. Tekrarların bitince kol değiştir.']::text[]),
  ('One-Arm_Long_Bar_Row', 'tr', array['Barın bir ucunu landmine aparatına tak ya da kaymaması için bir köşeye sıkıştır. Serbest uca uygun bir ağırlık yükle.', 'Barın yanında dur ve tek elinle bileziğe yakın yerden kavra. Kalça ve bacak gücünle doğrul.', 'Dizlerin bükülü, kalçan geride, göğsün yukarıda olacak şekilde dur. Kolun düz olsun. Bu senin başlangıç pozisyonun.', 'Omzunu geriye alıp dirseğini bükerek ağırlığı yanına çek. Ağırlığı silkeleme ve harekette hile yapma.', 'Kısa bir duraklamadan sonra başlangıç pozisyonuna dön.']::text[]),
  ('One-Arm_Medicine_Ball_Slam', 'tr', array['Ayakta, bir ayağın önde olacak şekilde atletik bir duruş al. Sağlık topunu arkadaki bacağınla aynı taraftaki elinde tut. Bu senin başlangıç pozisyonun.', 'Kolunu gererek sağlık topunu başının üzerine kaldır. Bu sırada kalçanı, dizlerini ve ayak bileklerini açarak vuruş için güç topla.', 'En açık noktada omuzlarını, omurganı ve kalçanı bükerek topu tam önünde yere sertçe çarp.', 'Top sekince yakala ve istenen tekrar sayısı kadar devam et.']::text[]),
  ('One-Arm_Open_Palm_Kettlebell_Clean', 'tr', array['Bir kettlebell''i ayaklarının arasına koy.', 'Sapı tek elinle tut ve kettlebell''i hızla kaldır. Dönmesine izin ver; gövdesi açık avucuna otursun.', 'Kettlebell''i önüne doğru fırlat ve sapından tek elinle yakala.', 'Kettlebell''i yere indir ve tekrarla. İki kolunu da çalıştır.']::text[]),
  ('One-Arm_Overhead_Kettlebell_Squats', 'tr', array['Kettlebell''i tek kolunla omzuna alıp yukarı it: bacaklarını ve kalçanı aç, kettlebell''i omzuna doğru çek ve bu sırada bileğini çevir. Sonra dirseğini açarak ağırlığı başının üzerine it. Bu senin başlangıç pozisyonun.', 'Dümdüz ileri bak ve kettlebell''i üzerinde kilitli tut. Dizlerini ve kalçanı bük, gövdeni bacaklarının arasına indir; başın ve göğsün yukarıda kalsın.', 'En altta bir saniye bekle, sonra topuklarından iterek yeniden yukarı çık.']::text[]),
  ('One-Arm_Side_Deadlift', 'tr', array['Halterin yanında, ortasının hizasında dur. Dizlerini bük ve bara uzanabilecek kadar alçal.', 'Barı bir evrak çantasını tutar gibi kavra (bar yan durduğu için avuç için sana bakar). Ağırlık fazlaysa bilek sargısı gerekebilir. Bu, başlangıç pozisyonun.', 'Nefes verirken bacaklarından güç alarak halteri kaldır. Bar yükselirken kolun tamamen uzasın ve dik duruşa gel.', 'Nefes alırken halteri yavaşça indir. İpucu: Sakatlanmamak için ağırlığı indirirken dizlerini bük.', 'Önerilen tekrar sayısını tamamla.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One-Arm_Side_Laterals', 'tr', array['Bir eline bir dambıl al. Boştaki elinle eğimli sehpa gibi sağlam bir yere tutun. Kaldıran koluna doğru, sehpayı tutan elinden uzağa yaslan; böylece dengeni korursun.', 'Gövden dik dursun. Dambılı kolun uzanmış halde yanında tut, avuç için sana baksın. Bu, başlangıç pozisyonun.', 'Gövdeni sabit tutarak (sallanma yok) dambılı yana doğru kaldır. Dirseğin hafif bükülü, elin bardağa su döker gibi biraz öne eğik olsun. Kolun yere paralel olana kadar devam et. Kaldırırken nefes ver ve tepede bir saniye bekle.', 'Nefes alırken dambılı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamla.', 'Kol değiştir ve egzersizi tekrarla.']::text[]),
  ('One-Legged_Cable_Kickback', 'tr', array['Deri bir ayak bileği bantını alçak kablo makarasına tak, sonra bantı ayak bileğine bağla.', 'Yüzün ağırlık bloğuna dönük, yaklaşık iki fit uzakta dur ve destek için çelik kasayı tut.', 'Dizlerin ve kalçan hafif bükülü, karnın sıkı olsun. Kalça kaslarını sıkarak çalışan bacağını nefes verirken yavaşça, yarım daire çizerek, rahatça çıkabildiği kadar yükseğe geriye doğru "tekmele". İpucu: Bacak tamamen uzandığında en yüksek kasılmaya ulaşmak için kalçanı bir saniye sık.', 'Şimdi çalışan bacağını kablonun çekişine direnerek yavaşça öne getir ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısını tamamla.', 'Bacak değiştir ve hareketi diğer tarafta tekrarla.']::text[]),
  ('One_Arm_Against_Wall', 'tr', array['Ayakta dur ve bükülü bir kolunu duvara ya da kapı kasasına yasla.', 'Kanat kaslarında gerilme hissedene kadar yavaşça o koluna doğru eğil.']::text[]),
  ('One_Arm_Chin-Up', 'tr', array['Önce barfiks demirinin üzerinden bir havlu geçir.', 'Barı avuç için sana bakacak şekilde kavra. Bir elin barı, diğer elin havluyu tutar.', 'Gövdeni yaklaşık 30 derece geriye yatır, belini hafifçe çukurlaştır ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun.', 'Omuzlarını ve üst kollarını aşağı ve geriye çekerek bar üst göğsüne değene kadar yüksel. Bu sırada nefes ver. İpucu: En üst noktada sırt kaslarını sıkmaya odaklan. Gövden yükselirken sabit kalır, yalnızca kolların hareket eder. Ön kolların barı tutmaktan başka bir iş yapmaz.', 'Yukarıda bir saniye bekle, sonra nefes alarak kendini yavaşça başlangıç pozisyonuna indir; kolların tamamen açılsın, kanat kasların tam gerilsin.', 'Belirlenen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One_Arm_Dumbbell_Bench_Press', 'tr', array['Düz bir sehpaya uzan; tek elinde tuttuğun dambıl uyluğunun üstünde dursun.', 'Uyluğunla destek vererek dambılı kaldır ve omuz genişliğinde önüne getir. Boştaki elinle dambılı üzerinde doğru konuma yerleştir.', 'Dambıl omuz genişliğine gelince bileğini öne çevir; avuç için senden uzağa baksın. Bu senin başlangıç pozisyonun.', 'Nefes alırken ağırlığı yavaşça yanına indir. Dambılı her an tam kontrol altında tut. İpucu: Başta dengeyi kurmak zor olabilir; o zaman boştaki elinle dambılı destekle. Bunu yalnızca gerekiyorsa yap; gerekmiyorsa o elin yanında dursun.', 'Nefes verirken dambılı göğüs kaslarınla yukarı it. Yukarıda kolunu kilitle, göğsünü sık, bir saniye tut ve yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Antrenman programının belirttiği tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One_Arm_Dumbbell_Preacher_Curl', 'tr', array['Sağ elinle bir dambıl al ve üst kolunu preacher sehpasının ya da eğimli sehpanın yastığına yerleştir. Dambılı omuz hizasında tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken dambılı yavaşça indir; kolun açılsın ve bisepsin tam gerilsin.', 'Nefes verirken biseps gücüyle ağırlığı yukarı kıvır; biseps tam kasılana ve dambıl omuz yüksekliğine gelene kadar devam et. Tam kasılma için serçe parmağını başparmağından yukarıya getir.', 'Yukarıda bisepsini bir saniye güçlüce sık ve önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One_Arm_Floor_Press', 'tr', array['Yere ya da bir egzersiz matına uzan; sırtın zemine yaslansın. Dizlerini bük.', 'Bir partner barı tek eline versin. Başlangıçta kolun neredeyse tamamen açıktır; halterle bench press''in başlangıcına benzer. Ancak bu kez nötr tutuş kullanırsın, yani avuç için gövdene bakar.', 'Ağırlığı kaldırmayan elin yanında dursun.', 'Harekete halteri dirseğin yere değene kadar indirerek başla. Burada nefes al, çünkü bu hareketin eksantrik (iniş) kısmı.', 'Sonra halteri ilk başlangıç pozisyonuna geri it. Konsantrik (kaldırma) kısmında nefes ver.', 'Önerilen tekrarlarını tamamlayana kadar devam et.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One_Arm_Lat_Pulldown', 'tr', array['Uygun bir ağırlık seç ve diz yastığını seni aşağıda tutacak şekilde ayarla. Tutamağı üstten (pronasyon) tutuşla kavra. Bu senin başlangıç pozisyonun.', 'Tutamağı aşağı çek: dirseğini bük ve yanına doğru sıkıştır.', 'Hareketin en altında bekle, sonra tutamağı yavaşça başlangıç pozisyonuna geri götür.', 'Birden fazla tekrar yapıyorsan ağırlığı tamamen geri bırakma; böylece çalışan kaslar gergin kalır.']::text[]),
  ('One_Arm_Pronated_Dumbbell_Triceps_Extension', 'tr', array['Bir sehpaya sırtüstü uzan ve dambılı kolun tam açıkken tut; kolun vücuduna dik olsun. Bu hareket üstten (pronasyon) tutuş ister, yani avuç için ayaklarına bakar.', 'Destek için boştaki elini çalışan kolunun bisepsine koy.', 'Nefes alırken dambılı yavaşça indir.', 'Sonra trisepsini kasarak dambılı yukarı kaldır. Konsantrik (kaldırma) kısmında nefes ver.', 'Setindeki tekrarları tamamlayana kadar devam et.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('One_Arm_Supinated_Dumbbell_Triceps_Extension', 'tr', array['Bir sehpaya sırtüstü uzan ve dambılı kolun tam açıkken tut; kolun vücuduna dik olsun. Bu hareket alttan (supinasyon) tutuş ister, yani avuç için yüzüne bakar.', 'Destek için boştaki elini çalışan kolunun bisepsine koy.', 'Nefes alırken dambılı yavaşça indir.', 'Sonra trisepsini kasarak dambılı yukarı kaldır. Konsantrik (kaldırma) kısmında nefes ver.', 'Setindeki tekrarları tamamlayana kadar devam et.', 'Kol değiştir ve hareketi tekrarla.', 'Bir kez daha kol değiştir ve hareketi tekrarla.']::text[]),
  ('One_Half_Locust', 'tr', array['Yere yüzüstü uzan.', 'Kalçanı ve kasık kemiğini korumak için sol elini sol kalça kemiğinin altına yerleştir.', 'Sağ dizini bük ve ayağını sağ elinle tut.', 'Ayağını havaya kaldır ve aynı anda omuzlarını yerden kes. Bu, sağ kalça fleksörünü, göğsü ve omuzları da esnetir. Taraf değiştir. Belini rahatsız etmiyorsa iki kol ve iki bacakla aynı anda deneyebilirsin.']::text[]),
  ('One_Handed_Hang', 'tr', array['Barfiks demirini tek elinle, üstten (pronasyon) tutuşla kavra. Ayakların yerde ya da bir basamakta kalsın. Ayakların yerdeyken ağırlığının büyük kısmını o eline bırak. 10-20 saniye tut ve taraf değiştir.']::text[]),
  ('One_Knee_To_Chest', 'tr', array['Yere uzan.', 'Bir bacağını dümdüz uzat, diğer dizini göğsüne çek. Diz kapağını korumak için diz ekleminin altından tut.', 'O dizini nazikçe burnuna doğru çek.', 'Taraf değiştir. Bu hareket bükülü bacak tarafında kalçayı ve beli, düz bacakta ise kalça fleksörünü esnetir.']::text[]),
  ('One_Leg_Barbell_Squat', 'tr', array['Düz bir sehpanın yaklaşık 2-3 feet önünde, sırtın sehpaya dönük dur. Halter önünde yerde dursun. İpucu: Ayakların omuz genişliğinde açık olsun.', 'Dizlerini bük, halteri omuz genişliğinden geniş bir üstten (pronasyon) tutuşla kavra ve göğsüne yaslayabileceğin yere kadar kaldır.', 'Sonra halteri başının üzerinden geçir ve ense köküne yerleştir. Bir ayağını geriye al, parmak uçların sehpaya dayansın. Diğer ayağın önünde sabit kalsın. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtın da düz kalsın. İpucu: Hareket boyunca sırtının düz, göğsünün dışarıda olduğundan emin ol.', 'Nefes alırken öndeki bacağının üzerinde yavaşça alçal; uyluğun yere paralel olana kadar in. Bu noktada dizin ayak parmaklarının üzerinde, göğsün de tam uyluğunun ortasının üstünde olmalı.', 'Nefes verirken göğsün ve kalçan önde, ön bacak kaslarını kasarak başlangıç pozisyonuna yüksel.', 'Önerilen tekrar sayısı kadar yap.', 'Bacak değiştir ve hareketi tekrarla.']::text[]),
  ('Open_Palm_Kettlebell_Clean', 'tr', array['Bir kettlebell''i ayaklarının arasına koy. Bacaklarını ve kalçanı açarak kettlebell''i omuzlarına doğru yükselt.', 'Kettlebell yükselirken bırak ve dönmesine izin ver; topu avuçlarının içine otursun.', 'Kettlebell''i önünde bırak ve sapını iki elinle yakala. Başlangıç pozisyonuna indir ve tekrarla.']::text[]),
  ('Otis-Up', 'tr', array['Ayaklarını sabitle ve dizlerin bükülü halde sırtüstü yere uzan. İki elinle bir ağırlığı göğsünde tut. Bu, başlangıç pozisyonun.', 'Harekete kalçanı ve omurganı bükerek başla; gövden yerden kalksın.', 'Yükselirken ağırlığı yukarı it; hareketin tepesinde ağırlık başının üstünde olsun.', 'Mekik hareketini tersine çevirirken ağırlığı göğsüne geri getir. Yere kadar tam inme.']::text[]),
  ('Overhead_Cable_Curl', 'tr', array['Önce kablo makinesinin iki tarafında da rahat kaldırabileceğin bir ağırlık seç. Not: İki taraftaki ağırlık aynı olmalı.', 'Sonra iki taraftaki makaraları omuzlarından daha yüksek bir seviyeye ayarla.', 'İki tarafın ortasında dur ve tutamakları alttan tutuşla (avuç içleri tavana dönük) kavra. Kolların tamamen uzanmış ve yere paralel, ayakların omuz genişliğinde açık olsun. Vücudun tutamaklarla aynı hizada dursun. Bu, başlangıç pozisyonu.', 'Nefes verirken iki taraftaki bisepsi yavaşça sık; ön kolların bisepse değene kadar devam et.', 'Nefes alırken ön kollarını başlangıç pozisyonuna geri götür. Not: Bu egzersizde ön kollar dışında bütün vücut sabit kalır.', 'Programında yazan tekrar sayısını tamamla.']::text[]),
  ('Overhead_Lat', 'tr', array['Yere dik otur, partnerin arkanda dursun. Bir kolunu dümdüz yukarı kaldır ve dirseğini bükerek elinle sırtına dokunmaya çalış. Partnerin triseps kasını ve bileğini tutsun. Bu, başlangıç pozisyonun.', 'Üst kolunu yanına doğru çekmeye çalış; partnerin bunu gerçekten yapmana engel olsun.', '10-20 saniye sonra kolunu gevşet. Partnerin trisepse hafifçe bastırarak kanat kasını daha da esnetsin. 10-20 saniye tut, sonra taraf değiştir.']::text[]),
  ('Overhead_Slam', 'tr', array['Ayakların omuz genişliğinde açık dur ve sağlık topunu iki elinle tut. Bu, başlangıç pozisyonun.', 'Hazırlık hareketine başla: topu başının üstüne kaldır ve vücudunu tamamen uzat.', 'Hareketi tersine çevir ve topu tam önünde, bütün gücünle yere çarp.', 'Seken topu iki elinle yakala ve hareketi tekrarla.']::text[]),
  ('Overhead_Squat', 'tr', array['Halter önünde, yerde dursun. Ayaklarını omuz genişliğinden daha fazla aç.', 'Dizlerini bük ve halteri üstten tutuşla (avuç içleri sana dönük) kavra. Kaldırmadan önce ellerin omuz genişliğinden daha açık olsun. Yerini aldığında halteri göğsüne yaslayabilecek kadar kaldır.', 'Halteri başının üstüne, biraz da arkasına götür; kolların tamamen uzanmış olsun. Başını hep dik, sırtını düz tut. Kürek kemiklerini geriye çek. Bu, başlangıç pozisyonun.', 'Nefes alırken dizlerini bükerek ağırlığı yavaşça indir; uylukların yere paralel olana kadar in. İpucu: Sakatlanmamak için egzersiz boyunca sırtını düz tut; kolların da hep uzanmış ve başının üstünde kalsın.', 'Şimdi nefes verirken ayaklarından ve bacaklarından güç alarak ağırlığı başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Overhead_Stretch', 'tr', array['Dimdik ayakta dur, parmaklarını birbirine kenetle ve avuç içlerini tavana çevir. Kollarını yukarı uzatırken omuzlarını aşağıda tut.', 'Bütün gövdeyi esnetmek için kuyruk sokumunu aşağı çek ve bunu yaparken gövdeni sabitle. Gövdenin hem ön hem arka tarafındaki kasları esnet.']::text[]),
  ('Overhead_Triceps', 'tr', array['Yere dik otur, partnerin arkanda dursun. Bir kolunu dümdüz yukarı kaldır ve dirseğini bükerek elinle sırtına dokunmaya çalış. Partnerin dirseğini ve bileğini tutsun. Bu, başlangıç pozisyonun.', 'Kolunu havaya doğru dümdüz uzatmaya çalış; partnerin bunu gerçekten yapmana engel olsun.', '10-20 saniye sonra kolunu gevşet. Partnerin bileğe hafifçe bastırarak trisepsi daha da esnetsin. 10-20 saniye tut, sonra taraf değiştir.']::text[]),
  ('Pallof_Press', 'tr', array['Kablo kulesine standart bir tutamak tak ve mümkünse kabloyu omuz hizasına ayarla. Olmuyorsa alçak makara da yeter.', 'Yan tarafın kabloya dönük dur, tutamağı iki elinle kavra ve kuleden uzaklaş. Makaradan yaklaşık bir kol boyu uzakta ol; ağırlık kabloyu gergin tutsun.', 'Ayakların kalça genişliğinde açık, dizlerin hafif bükülü olsun. Kabloyu göğsünün ortasında tut. Bu, başlangıç pozisyonun.', 'Kabloyu göğsünden uzağa it ve iki kolunu da tamamen uzat. Merkez bölgen sıkı ve devrede olsun.', 'Tekrarı birkaç saniye tut, sonra başlangıç pozisyonuna dön.', 'Set bitince diğer yöne dönerek tekrarla.']::text[]),
  ('Pallof_Press_With_Rotation', 'tr', array['Kablo kulesine standart bir tutamak tak ve kabloyu omuz hizasına ayarla.', 'Yan tarafın kabloya dönük dur, tutamağı tek elinle kavra ve kuleden uzaklaş. Makaradan yaklaşık bir kol boyu uzakta ol; ağırlık kabloyu gergin tutsun. Uzattığın kolu kabloyla aynı hizaya getir.', 'Ayakların kalça genişliğinde açıkken kabloyu göğsüne çek ve tutamağı diğer elinle de kavra. Artık iki elin de tutamakta.', 'Öne bakarak kabloyu göğsünden uzağa it. Merkez bölgen sıkı ve devrede olsun.', 'Kalçanı düz tutarak gövdeni makaradan uzağa doğru çevir; tam bir çeyrek dönüş yap.', 'Sağlam duruşunu ve düz kollarını koru. Yavaş ve kontrollü biçimde nötr pozisyona dön. Kolların önünde uzanmış olsun.', 'Yandan gelen gerilim merkez bölgeni çalıştırmayı sürdürürken ellerini göğsüne getir ve hemen kolların tamamen uzanana kadar ileri it. Bu bir tekrar eder.', 'Tükenene kadar tekrarla.', 'Sonra yerini yeniden al ve aynı hareket dizisini diğer tarafta tekrarla.']::text[]),
  ('Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'tr', array['Önce iki dambılı düz sehpanın bir yanına koy.', 'Vücudun düz sehpaya dönük olacak şekilde iki dizinin üstüne çök.', 'İki dambılı da üstten tutuşla (avuç içleri aşağı dönük) kavra ve ön kolların düz sehpaya yaslanacak şekilde kaldır. Bileklerin sehpanın kenarından sarksın.', 'Nefes vererek bileklerini yukarı doğru bükmeye başla.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir.', 'Ön kolların sabit kalsın; bu egzersizde yalnızca bilek hareket eder.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Palms-Down_Wrist_Curl_Over_A_Bench', 'tr', array['Önce halteri düz sehpanın bir yanına koy.', 'Vücudun düz sehpaya dönük olacak şekilde iki dizinin üstüne çök.', 'Halteri üstten tutuşla (avuç içleri aşağı dönük) kavra ve ön kolların düz sehpaya yaslanacak şekilde kaldır. Bileklerin sehpanın kenarından sarksın.', 'Nefes vererek bileklerini yukarı doğru bükmeye başla.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir.', 'Ön kolların sabit kalsın; bu egzersizde yalnızca bilek hareket eder.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'tr', array['Önce halteri düz sehpanın bir yanına koy.', 'Vücudun düz sehpaya dönük olacak şekilde iki dizinin üstüne çök.', 'Halteri alttan tutuşla (avuç içleri yukarı dönük) kavra ve ön kolların düz sehpaya yaslanacak şekilde kaldır. Bileklerin sehpanın kenarından sarksın.', 'Nefes vererek bileklerini yukarı doğru bükmeye başla.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir.', 'Ön kolların sabit kalsın; bu egzersizde yalnızca bilek hareket eder.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'tr', array['Önce iki dambılı düz sehpanın bir yanına koy.', 'Vücudun düz sehpaya dönük olacak şekilde iki dizinin üstüne çök.', 'İki dambılı da alttan tutuşla (avuç içleri yukarı dönük) kavra ve ön kolların düz sehpaya yaslanacak şekilde kaldır. Bileklerin sehpanın kenarından sarksın.', 'Nefes vererek bileklerini yukarı doğru bükmeye başla.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir. Egzersizin bu bölümünde nefes almaya dikkat et.', 'Ön kolların sabit kalsın; bu egzersizde yalnızca bilek hareket eder.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Parallel_Bar_Dip', 'tr', array['Paralel barların arasında dur. Her bara bir elini koy ve hafifçe zıplayarak kolların kilitli halde başlangıç pozisyonuna geç.', 'Dirseklerini bükerek başla ve kolların 90 dereceyi geçene kadar vücudunu indir. Sallanma ve iniş boyunca düzgün duruşunu koru.', 'Hareketi tersine çevir: dirseklerini açarak kendini başlangıç pozisyonuna geri it.', 'İstediğin tekrar sayısını tamamla.']::text[]),
  ('Pelvic_Tilt_Into_Bridge', 'tr', array['Yere uzan; ayakların yerde, topukların tam dizlerinin altında olsun.', 'Belini esnetmek için yalnızca kuyruk sokumunu tavana doğru kaldır. (Omurganın tamamını henüz kaldırma.) Karnını içeri çek.', 'Köprüye geçmek için boyun dışında omurganın tamamını kaldır.']::text[]),
  ('Peroneals-SMR', 'tr', array['Yan yat. Ağırlığını ön koluna ve alt bacağının dış yanına yerleştirdiğin foam roller''a ver. Üstteki bacağın alttaki bacağın üstünde durabilir ya da onu önünde çaprazlayabilirsin. Bu, başlangıç pozisyonun.', 'Kalçanı yerden kaldır ve bacağının yan tarafında dizin altından ayak bileğinin üstüne kadar yuvarlan. Gergin noktalarda 10-30 saniye bekle. Diğer bacakta tekrarla.']::text[]),
  ('Peroneals_Stretch', 'tr', array['Otur ve bir ayağına kemer, ip ya da bant dola. Bu, başlangıç pozisyonun.', 'Bacağın uzanmış, topuğun yerden kalkmış olsun. Kemeri öyle çek ki ayak içe dönsün ve ayağın iç kenarı sana doğru gelsin. 10-20 saniye tut, sonra taraf değiştir.']::text[]),
  ('Physioball_Hip_Bridge', 'tr', array['Pilates topuna sırtının üst kısmı topta, kalçan boşta kalacak şekilde uzan. İki ayağın da yere tam bassın; kalça genişliğinde ya da daha açık olsun. Bu, başlangıç pozisyonun.', 'Kalça ve arka bacak kaslarını kullanarak kalçanı aç ve köprü kurarken yukarı kaldır.', 'Hareketin tepesinde kısa bir an bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Pin_Presses', 'tr', array['Pin press, bench press''in eksantrik evresini ortadan kaldırır ve böylece çıkış kuvvetini geliştirir. Ayrıca istediğin bir hareket aralığını çalışmana olanak verir.', 'Sehpayı bir power rack''in içine kur. Pimleri hareket aralığında istediğin noktaya ayarla; bu yalnızca kilitleme kısmı da olabilir, göğsünün bir inç üstü de. Barı pimlerin üstüne al ve kaldırmaya hazırla.', 'Sehpaya uzan; bar, normal bench press''te sana değdiği noktanın tam üstünde olsun. Ayaklarını altına doğru çek ve sırtını kavislendir. Ağırlığını taşımak için bardan destek alarak omuzlarını sehpadan kaldır ve geriye çek, kürek kemiklerini birbirine sıkıştır. Ayaklarınla iterek trapez kaslarını sehpaya bastır. Bu sıkı vücut pozisyonunu hareket boyunca koru.', 'Standart bench press tutuşunu ya da trisepse odaklanmak için omuz genişliğinde bir tutuş kullanabilirsin. Bar, bilek ve dirsek her zaman aynı hizada kalsın. Barı sıkmaya ve iki yana ayırmaya çalışmaya odaklan.', 'Barı olabildiğince güçlü biçimde yukarı it. Dirseklerin kilitlemeye kadar gövdeye yakın kalsın.', 'Barı pimlere geri indir ve bir sonraki tekrara başlamadan önce bekle.']::text[]),
  ('Piriformis-SMR', 'tr', array['Kalçan foam roller''ın üstünde olacak şekilde otur. Dizlerini bük ve bir bacağını, ayak bileği dizin üstüne gelecek şekilde çaprazla. Bu, başlangıç pozisyonun.', 'Ağırlığını çaprazladığın bacağın tarafına ver ve kalçanın üst kısmında gerginlik hissedene kadar kalçanın üstünde yuvarlan. Bükülü dizini bir elinle göğsüne doğru çekerek esnemeye yardım edebilirsin. Bu pozisyonda 10-30 saniye kal, sonra taraf değiştir.']::text[]),
  ('Plank', 'tr', array['Yere yüzüstü uzan ve ağırlığını ayak parmaklarınla ön kollarına ver. Kolların bükülü ve tam omuzlarının altında olsun.', 'Vücudunu hep düz tut ve bu pozisyonda olabildiğince uzun kal. Zorlaştırmak için bir kolunu ya da bir bacağını kaldırabilirsin.']::text[]),
  ('Plate_Pinch', 'tr', array['Geniş kenarlı iki ağırlık plakası al ve düz yüzleri dışa bakacak şekilde birleştir.', 'Parmaklarınla bir plakanın dış yüzünü, baş parmağınla diğer tarafı kavrayarak iki plakayı bir arada tut. Bu, başlangıç pozisyonu.', 'Plakaları parmaklarınla ve baş parmağınla sık. Bu pozisyonu tutabildiğin kadar uzun tut.', 'Programında yazan set sayısını tamamla.', 'Kol değiştir ve hareketleri tekrarla.']::text[]),
  ('Plate_Twist', 'tr', array['Yere ya da bir egzersiz matına geç; bacakların tamamen uzanmış, gövden dik olsun. Plakayı iki elinle yanlarından kavra ve kolların hafif bükülü halde karnının önünde tut.', 'Bacaklarını ayak bileklerine yakın yerden yavaşça çaprazla ve yerden kaldır. Dizlerin de hafif bükülü olsun. Not: Egzersiz sırasında dengeni korumak için gövdeni biraz geriye al. Bu, başlangıç pozisyonu.', 'Plakayı sol yana götür ve yere değdir. Bunu yaparken nefes ver.', 'Nefes alırken başlangıç pozisyonuna dön, sonra hareketi bu kez vücudunun sağ yanına doğru tekrarla. İpucu: Her zaman yavaş ve kontrollü hareket et. Ani hareketler sırtı sakatlayabilir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Platform_Hamstring_Slides', 'tr', array['Bu hareket için ahşap ya da benzeri bir zemin gerekir. Bacakların uzanmış halde sırtüstü yat. Topuğunun altına bir spor havlusu ya da hafif bir ağırlık koy. Bu, başlangıç pozisyonun.', 'Harekete dizini bükerek başla; diğer bacağın düz kalsın.', 'Topuğunu yerde kaydırarak kendine doğru çekmeye devam et.', 'Diz tamamen bükülünce hareketi tersine çevir ve başlangıç pozisyonuna dön.']::text[]),
  ('Plie_Dumbbell_Squat', 'tr', array['Dimdik dur ve bir dambılı iki elinle alt ucundan tut. Bacaklarını omuz genişliğinden daha fazla aç, dizlerin hafif bükülü olsun.', 'Ayak parmakların dışa baksın. Not: Egzersiz boyunca kolların sabit kalır. Bu, başlangıç pozisyonu.', 'Dizlerini yavaşça bük ve uylukların yere paralel olana kadar alçal. Burada nefes al, çünkü bu egzersizin eksantrik bölümü.', 'Nefes verirken ağırlıklı olarak topuklarından iterek vücudunu başlangıç pozisyonuna getir.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Plyo_Kettlebell_Pushups', 'tr', array['Bir kettlebell''i yere koy. Ayak parmaklarının üstünde şınav pozisyonu al; bir elin yerde, diğeri kettlebell''de, dirseklerin açık olsun. Bu, başlangıç pozisyonun.', 'Sırtını düz tutarak inebildiğin kadar alçalmakla başla.', 'Yönü hızlı ve güçlü biçimde tersine çevir; kendini kettlebell''in diğer tarafına doğru it ve bu sırada el değiştir. Yeniden alçal ve hareketi bir o yana bir bu yana tekrarlayarak sürdür.']::text[]),
  ('Plyo_Push-up', 'tr', array['Yere yüzüstü geç ve ağırlığını ellerinle ayak parmaklarına ver.', 'Kolların tamamen uzanmış, ellerin yaklaşık omuz genişliğinde olsun. Hareket boyunca vücudunu düz tut. Bu, başlangıç pozisyonun.', 'Dirseklerini bükerek alçal ve göğsünü yere doğru indir.', 'En altta hareketi tersine çevir ve dirseklerini açarak kendini olabildiğince hızlı yukarı it. Gövdeni, ellerin yerden kesilecek kadar yukarı itmeye çalış.', 'Başlangıç pozisyonuna dön ve egzersizi tekrarla.', 'Daha da zorlaştırmak için havadayken ellerini çırp.']::text[]),
  ('Posterior_Tibialis_Stretch', 'tr', array['Otur ve bir ayağına kemer, ip ya da bant dola. Bu, başlangıç pozisyonun.', 'Bacağın uzanmış, topuğun yerden kalkmış olsun. Kemeri öyle çek ki ayak dışa dönsün ve ayağın dış kenarı sana doğru gelsin. 10-20 saniye tut, sonra taraf değiştir.']::text[]),
  ('Power_Clean', 'tr', array['Ayaklarını omuz genişliğinden biraz daha açık, parmak uçların hafifçe dışa bakacak şekilde yerleştir.', 'Çömel ve barı kapalı, üstten tutuşla kavra. Ellerin omuz genişliğinden biraz daha açık, dizlerinin dışında, dirseklerin tamamen açık olsun.', 'Bar kaval kemiklerinin yaklaşık 1 inç önünde, ayak tarağının üstünde dursun.', 'Sırtın düz ya da hafif kavisli, göğsün yukarıda ve dışarıda, kürek kemiklerin geriye çekilmiş olsun.', 'Başını nötr tut (omurgayla aynı hizada, eğik ya da dönük değil) ve dümdüz ileri bak. Bu evrede nefes al.', 'Nefes verirken kalçanı ve dizlerini güçlü biçimde açarak barı yerden kaldır. İpucu: Gövdenin üst kısmı aynı açıyı korur. Henüz belden bükülme ve kalçanın omuzlardan önce yükselmesine izin verme (bu, kalçayı havaya iter ve arka bacak kaslarını gerer).', 'Dirseklerin tamamen açık, başın nötr, omuzların barın üstünde kalsın.', 'Bar yükselirken onu kaval kemiklerine olabildiğince yakın tut.', 'Bar dizleri geçerken kalçanı öne it ve dizlerini kilitlememek için hafifçe bük. İpucu: Bu noktada uylukların bara dayanmış olmalı.', 'Sırtın düz ya da hafif kavisli, dirseklerin tamamen açık, başın nötr kalsın. İpucu: Bir sonraki evreye kadar nefesini tut.', 'Nefes al, sonra kalçanı ve dizlerini güçlü ve hızlı biçimde aç ve parmak uçlarında yüksel.', 'Barı vücuduna olabildiğince yakın tut. İpucu: Sırtın düz, dirseklerin yanlara dönük, başın nötr olsun. Ayrıca omuzlarını barın üstünde, kollarını da olabildiğince uzun süre düz tut.', 'Alt vücudunun eklemleri tamamen açıldığında, dirseklerini henüz bükmeden omuzlarını hızla yukarı silk. Hareketin bu bölümünde nefes ver.', 'Omuzlar en yüksek noktaya vardığında dirseklerini bük ve vücudunu barın altına çekmeye başla.', 'Kollarınla olabildiğince yükseğe ve olabildiğince uzun süre çekmeye devam et. İpucu: Bu evre patlayıcı olduğu için gövden dik ya da sırtın kavisli, başın hafifçe geriye eğik olur ve ayakların yerden kesilebilir.', 'Alt vücut tamamen açılıp bar en yüksek noktasına yaklaşınca vücudunu barın altına çek ve kollarını barın çevresinden dolandırıp altına getir.', 'Aynı anda kalçanı ve dizlerini bükerek çeyrek squat pozisyonuna in.', 'Kolların barın altına geçince nefes al, sonra dirseklerini kaldırarak üst kollarını yere paralel hale getir. Barı köprücük kemiklerinin ve ön omuz kaslarının üstüne oturt.', 'Barı dik ve sıkı bir gövdeyle, nötr bir baş pozisyonuyla ve tabanların yere tam basarken karşıla. Bu hareket sırasında nefes ver.', 'Kalçanı ve dizlerini açarak tamamen dik duruşa gelene kadar ayağa kalk.', 'Barı indirmek için kol kaslarındaki gerilimi yavaş yavaş azalt; bar kontrollü biçimde uyluklarına insin. Bu hareket sırasında nefes al.', 'Aynı anda kalçanı ve dizlerini bükerek barın uyluklara çarpmasını yumuşat.', 'Dirseklerin tamamen açıkken bar yere değene kadar çömel.', '1. evreden yeniden başla ve önerilen tekrar sayısını tamamla.']::text[]),
  ('Power_Clean_from_Blocks', 'tr', array['Halter istediğin yükseklikteki kasaların üstünde dursun. Barı bacaklarının hemen dışından kavra. Kalçanı indir; ağırlığın topuklarında, sırtın düz, başın öne dönük, göğsün yukarıda, omuzların barın hemen önünde olsun. Bu, başlangıç pozisyonun.', 'İlk çekişe topuklarından iterek ve dizlerini açarak başla. Sırt açın aynı, kolların düz kalsın. Bar uyluğun ortasına yaklaşırken kalçanı açmaya başla.', 'Zıplar gibi hızlan: kalçanı, dizlerini ve ayak bileklerini aç ve barı hızdan yararlanarak yukarı taşı. Ağırlığı hızlandırmak için kollarınla ayrıca çekmen gerekmemeli. İkinci çekişin sonunda vücudun tamamen açılmış ve hafifçe geriye yatmış, kolların hâlâ düz olsun.', 'Tam açılmaya varınca üçüncü çekişe geç: omuzlarını sertçe silk ve kollarını bük, dirseklerin yukarıda ve dışarıda olsun. Açılmanın en üst noktasında kendini barın altına, barı omuzlarına oturtabilecek kadar çek ve bu sırada dirseklerini barın altına döndür. Bar öne itilmiş omuzlara otursun, boğaza hafifçe değsin, ellerin gevşek olsun.', 'Hemen topuklarından iterek toparlan; gövden dik, dirseklerin yukarıda kalsın. Ayağa kalkana kadar devam et ve ağırlığı kasalara geri koyarak tekrarı bitir.']::text[]),
  ('Power_Jerk', 'tr', array['Ağırlık omuzlarının ön tarafında otururken ayakta dur ve dip hareketiyle başla. Ayakların tam kalçanın altında olsun; kalçanı geriye götürmeden dizlerini bük. Yalnızca biraz alçal ve yönü olabildiğince güçlü biçimde tersine çevir.', 'Topuklarından iterek olabildiğince çok hız ve kuvvet üret. Bar omuzlarından ayrılırken başını yolundan çekmeyi unutma.', 'Ayakların yerden kesildiği anda onları olabildiğince çabuk karşılama pozisyonuna getir. Ayakların platforma etkin biçimde basmadığı o kısa anda barı yukarı itme çaban seni aşağı iter. Ayaklarını biraz daha açık bir duruşa al, dizlerin kısmen bükülü olsun.', 'Barı kolların baş üstünde kilitli halde karşıla.', 'Ayakta duruşa dön.']::text[]),
  ('Power_Partials', 'tr', array['Gövden dik halde ayakta dur; her elinde bir dambıl olsun, kolların aşağı doğru uzansın. Dirseklerini gövdene yakın tut.', 'Avuç içlerin gövdene baksın, ayakların yaklaşık omuz genişliğinde açık olsun. Bu, başlangıç pozisyonun.', 'Kollarını düz, gövdeni sabit tut. Nefes verirken ağırlıkları yaklaşık omuz hizasına gelene kadar yanlara kaldır.', 'Kasılmayı bir saniye hisset, sonra nefes alırken ağırlıkları başlangıç pozisyonuna indir. İpucu: Ağırlıkları kaldırırken ve indirirken avuç içlerin aşağı baksın, serçe parmağın biraz daha yukarıda olsun; böylece yük ağırlıklı olarak omuzlarına biner.', 'Önerilen tekrar sayısını tamamla.']::text[]),
  ('Power_Snatch', 'tr', array['Yerde duran yüklü bir halterle başla. Bar kaval kemiklerine yakın olsun ya da onlara değsin; barı geniş tut. Ayakların tam kalçanın altında dursun, gerektiği kadar dışa dönük olsun. Kalçanı indir; göğsün yukarıda, bakışın ileride olsun. Omuzların barın hemen önünde dursun. Bu, başlangıç pozisyonu.', 'İlk çekişe topuklarının ön kısmından iterek başla ve barı yerden kaldır. Bar dizleri geçene kadar sırt açın aynı kalsın.', 'İkinci çekişe geç: kalçanı, dizlerini ve ayak bileklerini aç ve barı olabildiğince hızlı yukarı sür. Bar vücuduna yakın kalsın. Açılmanın en üst noktasında omuzlarını silk ve dirseklerinin yanlara doğru bükülmesine izin ver.', 'Ayaklarını biraz daha açık olan karşılama pozisyonuna alırken kendini barın altına çek ve barı başının üstüne yükselt. Barı yarım çömelmiş halde karşıla. Barı kaldırmayı sürdür ve baş üstünde kolların kilitli halde tut.', 'Ağırlık başının üstündeyken ayakta duruşa dön.']::text[]),
  ('Power_Snatch_from_Blocks', 'tr', array['Yüklü halteri istediğin yükseklikteki kasaların ya da sehpaların üzerine koy. Barı geniş tut. Ayaklarını tam kalçanın altına yerleştir, gerektiği kadar dışa çevir. Kalçanı indir, göğsün yukarıda olsun, karşıya bak. Omuzların barın biraz önünde, dirseklerin dışa dönük dursun. Bu başlangıç pozisyonu.', 'İlk çekişe başla: topuklarının ön kısmından yeri it ve barı kasalardan kaldır.', 'Kalçanı, dizlerini ve ayak bileklerini açarak ikinci çekişe geç, barı olabildiğince hızlı yukarı gönder. Bar vücuduna yakın kalsın. Tam uzadığın anda omuzlarını silk ve dirseklerinin yana doğru bükülmesine izin ver.', 'Ayaklarını karşılama pozisyonuna taşırken kendini sertçe barın altına çek ve barı başının üstüne çıkar. Ayakların kalçanın hemen dışına gelsin, gerektiği kadar dışa dönsün. Barı tam squat seviyesinin üstünde, kolların baş üstünde tamamen açıkken karşıla.', 'Barı topuklarının ön kısmının üzerinde tut, başın ve göğsün yukarıda kalsın, topuklarından iterek ayağa kalk. Ağırlığı dikkatle kasalara geri bırak.']::text[]),
  ('Power_Stairs', 'tr', array['Power stairs''te ağırlıklar bir merdivenden yukarı taşınır. Antrenmanda bunun için lastik ya da kasa kullanabilirsin.', 'Ağırlığı iki elinle kavra. Ayaklarını geniş aç, başın ve göğsün yukarıda olsun. Topuklarınla yeri it, dizlerini ve kalçanı açarak ağırlığı yerden kaldır.', 'Geriye yaslan ve ağırlığı savurarak basamağa çıkarmaya çalış; basamaklar genellikle 16-18" yüksekliğindedir. Ağırlığı basamağa itmek için bacaklarından yardım alabilirsin.', '3-5 tekrar yap, sonra daha ağır bir ağırlıkla devam et ve olabildiğince hızlı hareket et.']::text[]),
  ('Preacher_Curl', 'tr', array['Bu hareket için bir Scott sehpası ve bir EZ bar gerekir. Barı içteki dar tutuş yerlerinden kavra; en iyisi birinin barı sana vermesi, yoksa çoğu Scott sehpasının önündeki bar askısından al. Avuçların öne baksın; barın şekli yüzünden hafifçe içe eğik durur.', 'Üst kollarını ve göğsünü sehpanın yastığına daya, barı omuz hizasında tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı yavaşça indir; kolların açılana ve biseps tamamen gerilene kadar devam et.', 'Nefes verirken ağırlığı bisepsle yukarı bük; kas tamamen kasılana ve bar omuz hizasına gelene kadar çık. Bisepsi iyice sık ve bir saniye bekle.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Preacher_Hammer_Dumbbell_Curl', 'tr', array['Her eline bir dambıl al, avuçların birbirine baksın (nötr tutuş) ve iki üst kolunu Scott sehpasının yastığına yerleştir.', 'Nefes alırken dambılları yavaşça indir; kolların açılana ve biseps tamamen gerilene kadar devam et.', 'Nefes verirken ağırlığı bisepsle yukarı bük; kas tamamen kasılana ve dambıllar omuz hizasına gelene kadar çık.', 'Yukarıda bisepsi bir saniye iyice sık, sonra hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Press_Sit-Up', 'tr', array['Bir mekik sehpasına uzan ve halteri göğsünün üzerine koy. Bacaklarını sehpanın ayak desteğine sağlamca yerleştir. Bu başlangıç pozisyonu.', 'Nefes alırken karın ve kalça kaslarını sık. Ardından nefes vererek gövdeni mekik çeker gibi yukarı kıvır ve aynı anda halteri başının üstüne it. İpucu: Hareket sırasında halteri kollarınla yukarı it ama dikkatin karın kaslarında kalsın.', 'Gövdeni yeniden başlangıç pozisyonuna indir, halteri de gövdene geri getir. İnerken nefes almayı unutma.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Prone_Manual_Hamstring', 'tr', array['Bu egzersiz için bir partnere ihtiyacın var. Bacakların düz, yüzüstü uzan. Partnerin elini topuğuna koyar.', 'Dizini bükerek bacağını yukarı kıvır. Partnerin karşı koysun; önce hafif, hareket ilerledikçe daha güçlü bastırsın. Direncin uygun seviyede kalması için partnerinle konuş.', 'Yukarıda kısa bir süre dur, sonra bacağını başlangıç pozisyonuna indir; bu sırada partnerin ters yönde direnç uygular.']::text[]),
  ('Prowler_Sprint', 'tr', array['Kızağı uygun bir zemine koy ve uygun ağırlıkla yükle. Kızak seni zorlayacak kadar ağır olsun ama hızını belirgin biçimde düşürecek kadar ağır olmasın.', 'Dik ya da alçak tutamakları kullanabilirsin. Kolların düz, tutamakları kavra ve kızağa doğru yaslan.', 'Duruşunu bozmadan kısa, sırayla attığın adımlarla yeri it. Kısa bir mesafede olabildiğince hızlı git.']::text[]),
  ('Pull_Through', 'tr', array['Alt makaraya bir halat ya da tutamak tak ve makinenin birkaç adım önünde dur. Sırtını makineye dön, ayaklarını geniş aç; kablo bacaklarının arasından geçsin.', 'Harekete kalçadan eğilerek başla ve bacaklarının arasından olabildiğince geriye uzan. Dizlerin hafif bükük kalsın. Kollarını düz tutarak kalçanı aç ve dimdik ayağa kalk. Omuzlarınla yukarı çekme; hareketin tamamı kalçadan gelmeli.']::text[]),
  ('Pullups', 'tr', array['Barfiks barını avuçların öne bakacak şekilde, belirlenen tutuşla kavra. Not: Geniş tutuşta ellerin omuz genişliğinden daha açık durur. Orta tutuşta eller omuz genişliğinde, dar tutuşta ise omuz genişliğinden daha yakındır.', 'Seçtiğin tutuş genişliğinde, kolların düz, bara asıl; gövdeni yaklaşık 30 derece geriye yatır, belini çukurlaştır ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun.', 'Omuzlarını ve üst kollarını aşağı ve geriye çekerek gövdeni yukarı kaldır; bar üst göğsüne değene kadar çık. Hareketin bu bölümünde nefes ver. İpucu: En üstte sırt kaslarını sıkmaya odaklan. Üst gövden yukarı çıkarken sabit kalsın, yalnızca kolların hareket etsin. Ön kolların barı tutmaktan başka bir iş yapmasın.', 'Yukarıda bir saniye kal, sonra nefes almaya başla ve gövdeni yavaşça başlangıç pozisyonuna indir; orada kolların tamamen açık, kanat kasların tamamen gergin olur.', 'Hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Push-Up_Wide', 'tr', array['Ellerini birbirinden uzağa koy ve plank pozisyonunda ellerin ile ayak parmaklarının üzerinde dur. Dirseklerin açık, vücudun düz olsun. Kalçanın sarkmasına izin verme. Bu senin başlangıç pozisyonun.', 'Nefes alırken dirseklerini bük ve göğsünü yere doğru indir.', 'Dirseklerini açarak gövdeni göğüs kaslarınla yeniden başlangıç pozisyonuna it. Bunu yaparken nefes ver.', 'Yukarıda kasılı pozisyonda kısa bir süre dur, sonra hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Push-Ups_-_Close_Triceps_Position', 'tr', array['Yüzüstü yere uzan ve ellerini omuz genişliğinden dar koyarak dar el pozisyonu al. Gövdeni kolların düz olacak şekilde yukarıda tut.', 'Nefes alırken göğsün neredeyse yere değene kadar in.', 'Triseps ve bir miktar da göğüs kaslarınla gövdeni yeniden başlangıç pozisyonuna it, göğsünü sık. Bunu yaparken nefes ver.', 'Yukarıda kasılı pozisyonda bir saniye dur, sonra hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Push-Ups_With_Feet_Elevated', 'tr', array['Yüzüstü yere uzan, ellerini aralarında yaklaşık 36 inç olacak şekilde koy ve gövdeni kolların düz, yukarıda tut.', 'Ayak parmaklarını düz bir sehpanın üzerine koy; böylece vücudun yükselir. Not: Sehpa ne kadar yüksekse egzersiz o kadar zorlaşır.', 'Nefes alırken göğsün neredeyse yere değene kadar in.', 'Göğüs kaslarınla gövdeni yeniden başlangıç pozisyonuna it ve göğsünü sık. Bunu yaparken nefes ver.', 'Yukarıda kasılı pozisyonda bir saniye dur, sonra hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Push-Ups_With_Feet_On_An_Exercise_Ball', 'tr', array['Yüzüstü yere uzan, ellerini aralarında yaklaşık 36 inç olacak şekilde koy ve gövdeni kolların düz, yukarıda tut.', 'Ayak parmaklarını bir pilates topunun üzerine koy; böylece vücudun yükselir.', 'Nefes alırken göğsün neredeyse yere değene kadar in.', 'Göğüs kaslarınla gövdeni yeniden başlangıç pozisyonuna it ve göğsünü sık. Bunu yaparken nefes ver.', 'Yukarıda kasılı pozisyonda bir saniye dur, sonra hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Push_Press', 'tr', array['Ayakların yaklaşık kalça genişliğinde dur ve halteri omuzlarının ön kısmında tut; ellerin omuz genişliğinden biraz açık, dirseklerin barın hafifçe önünde olsun.', 'Dizlerini biraz bükerek kısa bir çöküş yap; gövden dik, topukların yerde kalsın.', 'Bacaklarınla sertçe yukarı it ve bu ivmeyle barı baş üstüne, kolların tamamen açılana kadar bas.', 'Barı kontrollü şekilde omuzlarına indir, dizlerinle yumuşat ve tekrarla.']::text[]),
  ('Push_Press_-_Behind_the_Neck', 'tr', array['Bar omuzlarının arkasında dururken ayakta çöküşle başla. Ayakların tam kalçanın altında; kalçanı geriye götürmeden dizlerini bük. Yalnızca biraz in, sonra hareketi olabildiğince güçlü biçimde tersine çevir. Topuklarından iterek olabildiğince çok hız ve kuvvet üret, barı dikey bir çizgide yukarı taşı.', 'Oluşan ivmeyi kullan ve kollarını açarak ağırlığı baş üstüne itmeyi tamamla.', 'Başlangıç pozisyonuna dön ve darbeyi bacaklarınla karşıla.']::text[]),
  ('Push_Up_to_Side_Plank', 'tr', array['Ayak parmaklarının üzerinde şınav pozisyonu al; ellerin omuz genişliğinin biraz dışında olsun.', 'Dirseklerini bükerek bir şınav çek. İnerken vücudun düz kalsın.', 'Bir şınav çek ve yukarı çıkarken ağırlığını vücudunun sol tarafına aktar; yana dönüp sağ kolunu tavana doğru kaldırarak yan plank pozisyonuna geç.', 'Kolunu yeniden yere indir, bir şınav daha çek ve bu kez diğer tarafa dön.', 'Seriyi her seferinde taraf değiştirerek 10 ya da daha fazla tekrar yap.']::text[]),
  ('Pushups', 'tr', array['Yüzüstü yere yat, ellerini yaklaşık 36 inç arayla yerleştir ve kolların düzken gövdeni yukarıda tut.', 'Ardından nefes alarak alçal; göğsün yere değmek üzereyken dur.', 'Şimdi nefes ver ve göğsünü sıkarak gövdeni yeniden başlangıç pozisyonuna it.', 'En üstte göğsün kasılıyken kısa bir an bekle, sonra gerektiği kadar tekrar için yeniden alçalmaya başla.']::text[]),
  ('Pushups_Close_and_Wide_Hand_Positions', 'tr', array['Yüzüstü, vücudun düz ve ayak parmakların yerde olacak şekilde uzan. Geniş el pozisyonu için ellerini omuz genişliğinden açık, dar el pozisyonu için omuz genişliğinden dar koy. Gövdeni kolların düz olacak şekilde yukarıda tut.', 'Nefes alırken göğsün neredeyse yere değene kadar in.', 'Göğüs kaslarınla gövdeni yeniden başlangıç pozisyonuna it ve göğsünü sık. Bunu yaparken nefes ver.', 'Yukarıda kasılı pozisyonda bir saniye dur, sonra hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Pyramid', 'tr', array['Gövdenle topun üzerinden öne doğru yuvarlan; kalçan topun tepesine otursun ve vücudunun en yüksek noktası olsun.', 'Ellerini ve ayaklarını yere koy. Topun boyutuna, esnekliğine ve kol ile bacaklarının uzunluğuna göre kolların ve bacakların düz ya da hafif bükük olabilir. Bu duruş gövdende ve omuzlarında dengeleyici kuvveti de geliştirir.']::text[]),
  ('Quad_Stretch', 'tr', array['Yan yat. Üstteki ayağına bir kemer, ip ya da bant geçir. Dizini bük, kalça eklemini aç ve ayağını kalça kaslarına değdirmeye çalış; kemeri ellerinle tut. Bu senin başlangıç pozisyonun.', 'Kemeri omzunun ya da başının üzerinden tutarak yavaşça çek ve ön bacaktaki esnemeyi artır. 10-20 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Quadriceps-SMR', 'tr', array['Yüzüstü yere uzan, ağırlığını ellerine ya da ön kollarına ver. Foam roller''ı bir bacağının ön bacak kasının altına koy ve o ayağı yerden kaldır. Bacağını olabildiğince gevşet. Bu senin başlangıç pozisyonun.', 'Dayanabildiğin kadar ağırlığı o bacağa ver ve dizin üstünden kalçanın altına kadar roller üzerinde yuvarlan; gergin noktalarda 10-30 saniye bekle. Taraf değiştir.']::text[]),
  ('Quick_Leap', 'tr', array['Bu egzersiz için bir kutuya ihtiyacın var.', 'Yüzün kutuya dönük, kenarından 1-2 feet uzakta dur.', 'Kalçandan güç alarak kutunun üzerine sıçra ve iki bacağının üzerine in. İnerken bacaklarının bükük, ayak tabanlarının tam yerde olmasına dikkat et.', 'İner inmez bütün vücudunu aç ve kollarını başının üstüne savurarak kutudan patlayıcı biçimde sıçra. Yere inişin darbesini bacaklarınla karşıla.']::text[]),
  ('Rack_Delivery', 'tr', array['Bu çalışma halteri omuzlardaki rack pozisyonuna getirmeyi öğretir. Barı korkuluk pozisyonunda tut: üst kolların yere paralel, ön kolların aşağı sarkık. Kanca tutuş kullan, parmakların başparmaklarının üzerini sarsın.', 'Dirseklerini barın çevresinde döndürerek barı omuzlarına getir. Dirseklerin öne gelirken tutuşunu gevşet. Omuzlarını öne çıkar ki bar için bir raf oluştursun; bar boğazına hafifçe değmeli.', 'Barın her an vücuda yakın kalması önemli, çünkü ağır yükte en küçük mesafe bile istenmeyen bir çarpmaya yol açar. Hareket akıcılaştıkça, bir sonraki aşamaya geçmeden önce hızı ve yükü artırabilirsin.']::text[]),
  ('Rack_Pull_with_Bands', 'tr', array['Power rack içinde barı pimlerin üzerine koy. Pimleri istediğin noktaya ayarla: dizlerin hemen altı, hemen üstü ya da uyluğun ortası. Lastik bantları rack''in tabanına bağla ya da dambıllarla sabitle, diğer ucunu bara tak. Gerginlik sağlamak için bantları kendi içinden geçirip boğman gerekebilir.', 'Barın önünde doğru deadlift pozisyonunu al: ayakların kalçanın altında, tutuşun omuz genişliğinde, sırtın kavisli, kalçan arka bacak kaslarını devreye sokacak şekilde geride olsun. Ağırlık genellikle fazla olduğundan karışık tutuş, kanca tutuş ya da kayış kullanarak ağırlığı daha rahat tutabilirsin.', 'Karşıya bak, kalçanı ve dizlerini aç, ağırlığı tam kilitlenene kadar yukarı ve geriye çek. Hareketi bitirirken omuzlarını geriye al. Ağırlığı pimlere geri koy ve tekrarla.']::text[]),
  ('Rack_Pulls', 'tr', array['Power rack içinde barı pimlerin üzerine koy. Pimleri istediğin noktaya ayarla: dizlerin hemen altı, hemen üstü ya da uyluğun ortası. Barın önünde doğru deadlift pozisyonunu al: ayakların kalçanın altında, tutuşun omuz genişliğinde, sırtın kavisli, kalçan arka bacak kaslarını devreye sokacak şekilde geride olsun. Ağırlık genellikle fazla olduğundan karışık tutuş, kanca tutuş ya da kayış kullanarak ağırlığı daha rahat tutabilirsin.', 'Karşıya bak, kalçanı ve dizlerini aç, ağırlığı tam kilitlenene kadar yukarı ve geriye çek. Hareketi bitirirken omuzlarını geriye al.', 'Ağırlığı pimlere geri koy ve tekrarla.']::text[]),
  ('Rear_Leg_Raises', 'tr', array['Egzersiz matının üzerinde ellerinin ve dizlerinin üstüne gel. Karşıya bak; dizlerini, arka bacak ile baldır arasında 90 derecelik açı oluşacak şekilde bük. Bu senin başlangıç pozisyonun.', 'Bir bacağını yukarı ve arkaya doğru uzat; hem diz hem kalça açılsın. 5-10 tekrar yap, sonra taraf değiştir.']::text[]),
  ('Recumbent_Bike', 'tr', array['Bisiklete otur ve koltuğu boyuna göre ayarla.', 'Menüden istediğin seçeneği seç. Cihazın açılması için pedal çevirmeye başlaman gerekebilir. Manuel ayarı kullanabilir ya da bir program seçebilirsin. Çoğunlukla yaşını ve kilonu girerek egzersizde yakılan kaloriyi tahmin ettirebilirsin. Direnç seviyesini antrenman boyunca değiştirebilirsin. Tutamaklar nabzını ölçmeye yarar, böylece uygun yoğunlukta kalırsın.', 'Yatar bisikletler kullanışlıdır, kalp ve dolaşım için faydalıdır ve diğer aktivitelere göre daha az darbe yaratır. 150 lb ağırlığındaki biri 30 dakika orta tempoda pedal çevirerek yaklaşık 230 kalori yakar; koşuda bu 450 kalori ya da daha fazladır.']::text[]),
  ('Return_Push_from_Stance', 'tr', array['Bu çalışma için bir partnere ihtiyacın var.', 'Atletik bir 2 ya da 3 nokta duruşunda başla.', 'İşaret gelince partnerinin pasını karşılayacağın pozisyona geç.', 'Sağlık topunu iki elinle yakala ve hemen partnerine geri at.', 'Farklı rotalar koşarak bu çalışmayı çeşitlendirebilirsin.']::text[]),
  ('Reverse_Band_Bench_Press', 'tr', array['Power rack''in içine bir sehpa yerleştir ve barı doğru yüksekliğe ayarla. Lastik bantları bant pimlerine ya da rack''in tepesine bağla; bantların altında doğru konumda yatacağından emin ol. Diğer ucu haltere tak.', 'Sehpaya uzan, ayaklarını altına doğru çek ve sırtını kavislendir. Ağırlığını bara vererek omuzlarını sehpadan kaldır ve geriye çek, kürek kemiklerini birbirine sıkıştır. Ayaklarınla iterek trapez kaslarını sehpaya bastır. Bu sıkı duruşu hareket boyunca koru. Tutuşun ne kadar geniş olursa olsun, elin bardaki halka işaretini kapatmalı.', 'Omuzlarını öne çıkarmadan barı rack''ten al. Barı sıkmaya ve iki yana ayırmaya çalışır gibi tut. Barı alt göğsüne ya da üst karnına indir. Bar, bilek ve dirsek her an aynı hizada kalmalı.', 'Halter gövdene değdiğinde dur, sonra barı olabildiğince güçlü biçimde yukarı it. Dirseklerin tam kilitlenene kadar içeride kalsın.']::text[]),
  ('Reverse_Band_Box_Squat', 'tr', array['Power rack''te, arkanda uygun yükseklikte bir kutu olacak şekilde başla. Lastik bantları bant pimlerine ya da rack''in tepesine as; squat sırasında tam barın üzerinde olmalılar. Diğer ucu bara tak.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sıkıştır, dirseklerini öne çevir; barı omuzlarının üzerinde bükmeye çalışır gibi yap. Belinde sıkı bir kavis oluşturarak barı rack''ten al ve geri adım atıp yerini al. Ayaklarını geniş açarsan sırt, kalça, addüktörler ve arka bacak daha çok çalışır; dar tutarsan ön bacak daha çok gelişir. Başın öne baksın.', 'Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışa iterek inmeye başla. Kutuya oturana kadar kalçanla geriye otur. İdeal olarak kaval kemiklerin yere dik durmalı. Kutuya ulaşınca dur ve kalça fleksörlerini gevşet. Kutudan asla sekme.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve hareketi başınla yönlendirerek kutudan yukarı kalk. Baştan ayağa sıkı kalarak yükselmeye devam et. Halteri dikkatle rack''e geri koy.']::text[]),
  ('Reverse_Band_Deadlift', 'tr', array['Barı bir power rack''in içine yerleştir. Lastik bantları rack''in tepesine, bant pimlerine ya da doğrudan iskelete bağla. Bantların diğer ucunu bara tak.', 'Bara, ayaklarının tam üzerinde ortalanacak şekilde yaklaş. Ayakların yaklaşık kalça genişliğinde dursun. Kalçadan eğil ve barı omuz genişliğinde kavra; kürek kemiklerinin öne açılmasına izin ver. Genellikle üstten tutuş, ağır setlerde ise bir üstten bir alttan tutuş kullanılır.', 'Ayakların ve tutuşun hazır olunca derin bir nefes al, sonra kalçanı indir ve kaval kemiklerin bara değene kadar dizlerini bük. Karşıya bak, göğsün yukarıda ve sırtın kavisli kalsın; topuklarından iterek ağırlığı yukarı taşımaya başla.', 'Bar dizlerini geçtikten sonra barı sertçe geriye çek; kalçanı öne, bara doğru iterken kürek kemiklerini birbirine yaklaştır.', 'Kalçadan eğilerek barı indir ve yere kadar yönlendir.']::text[]),
  ('Reverse_Band_Power_Squat', 'tr', array['Pimlerin ve barın uygun yüksekliğe ayarlandığı bir power rack''te başla. Barı yükledikten sonra lastik bantları rack''in tepesine, pimlere ya da doğrudan iskelete bağla. Bantların diğer ucunu bara tak.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sıkıştır, dirseklerini öne çevir; barı omuzlarının üzerinde bükmeye çalışır gibi yap. Belinde sıkı bir kavis oluşturarak barı rack''ten al ve geri adım atıp yerini al. Sırt, kalça, addüktörler ve arka bacağı daha çok çalıştırmak için ayaklarını geniş aç.', 'Başın öne baksın. Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışa iterek inmeye başla. Kalçanla olabildiğince geriye otur. İdeal olarak kaval kemiklerin yere dik durmalı. Bar daha aşağıda durduğunda, topukların üzerinde kalması için gövdeni daha fazla öne eğmen gerekir. Paralelin altına inene kadar devam et; bu, kalça kıvrımının dizin üst noktasıyla aynı hizaya gelmesi demektir.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve hareketi başınla yönlendirerek yukarı kalk. Baştan ayağa sıkı kalarak başlangıç pozisyonuna dönene kadar yüksel.']::text[]),
  ('Reverse_Band_Sumo_Deadlift', 'tr', array['Power rack''in içinde, yerde duran yüklü bir barla başla. Lastik bantları rack''in tepesine, pimlere ya da doğrudan iskelete bağla. Diğer ucu haltere tak.', 'Bara, ayaklarının ortasından geçecek şekilde yaklaş. Ayaklarını çok geniş, bar bileziklerine yakın yerleştir. Kalçadan eğilerek barı kavra. Kolların tam omuzlarının altında ve bacaklarının iç tarafında olsun; üstten (pronasyon) tutuş, karışık tutuş ya da kanca tutuş kullanabilirsin. Omuzlarını gevşet; bu, kollarını fiilen uzatır.', 'Nefes al, sonra kalçanı indir; karşıya bak, göğsün yukarıda olsun. Ayaklarını iki yana açar gibi yeri it, ağırlığın ayaklarının arka yarısında dursun. Kalçanı ve dizlerini aç.', 'Bar dizlerini geçerken geriye yaslan ve kalçanı bara doğru it, kürek kemiklerini birbirine yaklaştır.', 'Kalçadan eğilerek ve iniş boyunca ağırlığı kontrol ederek barı yere geri indir.']::text[]),
  ('Reverse_Barbell_Curl', 'tr', array['Gövden dik, ayakta dur ve halteri omuz genişliğinde tut; dirseklerin gövdene yakın olsun. Avuçların aşağı baksın (pronasyon tutuş). Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut ve nefes verirken bisepsini kasarak ağırlığı yukarı bük. Yalnızca ön kolların hareket etsin. Biseps tamamen kasılana ve bar omuz hizasına gelene kadar devam et. Orada bir saniye kal ve kası sık.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Barbell_Preacher_Curls', 'tr', array['EZ barı omuz genişliğinde, avuçların aşağı bakacak şekilde (pronasyon) kavra.', 'Şimdi iki üst kolunu Scott sehpasının yastığına yerleştir, kolların açık olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken ağırlığı bisepsle yukarı bük; biseps tamamen kasılana ve bar omuz hizasına gelene kadar çık. Yukarıda bisepsi bir saniye iyice sık.', 'Nefes alırken barı yavaşça indir; üst kolların açılana ve biseps tamamen gerilene kadar devam et.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Cable_Curl', 'tr', array['Alt makaraya bir bar aparatı tak. Gövden dik, ayakta dur ve barı omuz genişliğinde, pronasyon (avuçlar aşağı) tutuşla kavra. Dirseklerinin gövdene yakın kalmasına da dikkat et. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut ve nefes verirken bisepsini kasarak ağırlığı yukarı bük. Yalnızca ön kolların hareket etsin. Biseps tamamen kasılana ve bar omuz hizasına gelene kadar devam et. Orada bir saniye kal ve kası sık.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Crunch', 'tr', array['Bacakların tamamen uzanmış, kolların gövdenin yanında ve avuçların yerde olacak şekilde yere uzan. Kolların egzersiz boyunca sabit kalsın.', 'Bacaklarını kaldır; uylukların yere dik, ayakların bitişik ve yere paralel olsun. Bu başlangıç pozisyonu.', 'Nefes alırken bacaklarını gövdene doğru çek; leğen kemiğini geriye yuvarla ve kalçanı yerden kaldır. Hareketin sonunda dizlerin göğsüne değer.', 'Kasılmayı bir saniye tut, sonra nefes vererek bacaklarını başlangıç pozisyonuna götür.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Flyes', 'tr', array['Eğimli bir sehpaya yüzüstü uzan; göğsün ve karnın yastığa bastırsın. Her elinde bir dambıl tut, avuçların birbirine baksın (nötr tutuş).', 'Kollarını önünde, sehpanın eğimine dik olacak şekilde uzat. Bacakların sabit kalsın, ayak parmaklarının kökleriyle yere bastır. Bu başlangıç pozisyonu.', 'Dirseklerindeki hafif bükülmeyi koru ve nefes verirken ağırlıkları yay çizerek yana, birbirinden uzağa aç. İpucu: Bu egzersizden en iyi sonucu almak için kürek kemiklerini birbirine sıkıştırmaya çalış.', 'Kollarını yere paralel olana kadar kaldır.', 'Kasılmayı hisset ve nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indir.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Flyes_With_External_Rotation', 'tr', array['Eğimli sehpayı 30 derecelik açıya ayarla ve yüzüstü uzan; göğsün ve karnın yastığa bastırsın.', 'Her elinde bir dambıl tut, avuçların yere baksın. Kolların önünde, sehpanın eğimine dik dursun. İpucu: Dirseklerin hafif bükük olsun. Bacakların sabit kalsın, ayak parmaklarının kökleriyle yere bastır (topukların yere değmemeli). Bu başlangıç pozisyonu.', 'Dirseklerindeki hafif bükülmeyi koru ve nefes verirken ağırlıkları yay çizerek dışa, birbirinden uzağa aç.', 'Ağırlığı kaldırırken bileklerini 90 derece dışa döndür; böylece avuçların aşağı baktığı (pronasyon) tutuştan avuçların birbirine baktığı (nötr) tutuşa geçersin. İpucu: Bu egzersizden en iyi sonucu almak için kürek kemiklerini birbirine sıkıştırmaya çalış.', 'Kollarını başınla aynı hizaya gelene kadar kaldır.', 'Kasılmayı hisset ve nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indir.', 'Hareketi planlanan tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Grip_Bent-Over_Rows', 'tr', array['Halteri alttan tutuşla, avuçların yukarı bakacak şekilde kavra ve dik dur.', 'Dizlerini hafifçe bük ve belden eğilerek gövdeni öne getir; gövden yere neredeyse paralel olana kadar in, sırtın düz kalsın. İpucu: Başını yukarıda tut. Halter tam önünde asılı dursun; kolların hem yere hem gövdene dik olsun. Bu, başlangıç pozisyonun.', 'Nefes verirken gövdeni oynatmadan halteri yukarı çek. Dirseklerin vücuduna yakın kalsın; ön kolların ağırlığı tutmaktan başka iş yapmasın. En üstte sırt kaslarını sık ve bir saniye bekle.', 'Nefes alırken ağırlığı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Grip_Triceps_Pushdown', 'tr', array['Yüksek makaraya düz ya da EZ bir bar aparatı tak.', 'Yüzünü bara dön ve barı omuz genişliğinde, alttan tutuşla, avuçların yukarı bakacak şekilde kavra. Kanat kaslarını kullanarak barı, kolların yanlarında tam açılana kadar indir. İpucu: Dirseklerin gövdenin yanında, ayakların omuz genişliğinde açık olsun. Bu, başlangıç pozisyonu.', 'Nefes alırken barın yavaşça göğüs hizana kadar yükselmesine izin ver. Yalnızca ön kolların hareket etsin; dirseklerin ve üst kolların hep yanında sabit kalsın.', 'Sonra nefes verirken trisepsini iyice sıkarak barı yeniden başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Hyperextension', 'tr', array['Uygun ağırlığı yükle, sonra ayaklarını pedlerin arasına yerleştir. Üst pede uzan; kalçan arka kenardan sarksın. Yerinde kalmak için tutamakları kavra.', 'Harekete kalçanı bükerek, bacaklarını öne çekerek başla.', 'Ardından kalçanı açıp bacaklarını geriye savur. Bu harekette kalçayı aşırı açmamak çok önemli: Tam hareket açıklığının sonuna varmadan dur.', 'Kalçanı yeniden bükerek geri dön ve taşıyıcıyı öne doğru çekebildiğin kadar çek.', 'İstediğin tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Machine_Flyes', 'tr', array['Tutamakları en arkaya ayarla. Uygun ağırlığı seç ve oturak yüksekliğini tutamaklar omuz hizana gelecek şekilde ayarla. Tutamakları avuçların içe bakacak şekilde kavra. Bu, başlangıç pozisyonun.', 'Ellerini yarım daire çizerek yanlara ve geriye çek; bu sırada arka omuz kaslarını sık.', 'Hareket boyunca kollarını hafif bükük tut; hareketin tamamı omuz ekleminden gelsin.', 'Hareketin arka noktasında kısa bir an bekle, sonra ağırlığı yavaşça başlangıç pozisyonuna döndür.']::text[]),
  ('Reverse_Plate_Curls', 'tr', array['Dik dur ve bir ağırlık plakasını iki elinle, kolların tam açık şekilde tut. Üstten tutuşla, avuçların aşağı bakacak şekilde kavra: Parmakların plakanın pürüzlü yüzünde, başparmakların düz yüzünde olsun. Not: En iyi sonuç için plakayı saat 11:00 ve 1:00 konumlarından tut.', 'Ayaklarını omuz genişliğinde aç ve plakayı kasık bölgene yakın tut. Bu, başlangıç pozisyonu.', 'Nefes verirken plakayı, biseps ve ön kolların birbirine değene kadar yavaşça kaldır; dirseklerin içeride, üst kolların sabit kalsın. Bu noktada plaka gövdenle düzgün biçimde aynı hizada olmalı.', 'Kasılmayı bir saniye hisset, sonra nefes alırken ağırlığı başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Reverse_Triceps_Bench_Press', 'tr', array['Düz bir sehpaya sırtüstü uzan. Barı dar ve alttan tutuşla, yaklaşık omuz genişliğinde kavrayıp askıdan al ve tam üstünde tut; kolların kilitli, önünde uzanmış ve yere dik olsun. Bu, başlangıç pozisyonun.', 'Nefes alırken barı, göğsünün ortasında hissedene kadar yavaşça indir. İpucu: Normal bench press''ten farklı olarak dirseklerini hep gövdene yakın tut; böylece triseps olabildiğince çok çalışır.', 'Bir saniye bekle, sonra nefes verirken barı triseps kaslarınla iterek başlangıç pozisyonuna getir. Kollarını üstte kilitle, bir saniye bekle ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Bitirince barı askıya geri koy.']::text[]),
  ('Rhomboids-SMR', 'tr', array['Yere sırtüstü uzan. Üst sırtının altına bir foam roller koy ve kollarını önünde çaprazla; omuzların öne gelsin. Bu, başlangıç pozisyonun.', 'Kalçanı yerden kaldır ve ağırlığını foam roller''a ver. Ağırlığını her seferinde bir yana aktararak orta ve üst sırtının üzerinde yuvarlan. Gergin noktalarda 10-30 saniye bekle.']::text[]),
  ('Rickshaw_Carry', 'tr', array['Çerçeveyi başlangıç noktasına yerleştir ve uygun ağırlıkla yükle. Çerçevenin ortasında dur, tutamakları kavra ve topuklarından güç alarak çerçeveyi kaldır. Göğsün ve başın yukarıda, sırtın düz olsun.', 'Hemen hızlı ve kontrollü adımlarla tempolu yürümeye başla. Göğsünü yukarıda, başını ileride tut ve nefes almayı sürdür. Bitiş noktasına varınca çerçeveyi yere indir.']::text[]),
  ('Rickshaw_Deadlift', 'tr', array['Çerçeveyi istediğin ağırlıkla yükle. Tutamakların tam ortasında dur; ayakların yaklaşık kalça genişliğinde açık olsun. Kalçadan eğilerek tutamakları kavra ve kürek kemiklerinin öne açılmasına izin ver.', 'Ayakların ve tutuşun yerine oturunca derin bir nefes al, sonra kalçanı indir ve dizlerini bük. İleri bak, göğsünü yukarıda ve sırtını kavisli tut, topuklarından iterek ağırlığı yukarı kaldırmaya başla. Ağırlık yükselirken kürek kemiklerini birbirine yaklaştır ve kalçanı öne sür.', 'Ağırlığı indirmek için kalçadan eğil ve onu yere kadar yönlendir.']::text[]),
  ('Ring_Dips', 'tr', array['Her eline bir halka al, sonra küçük bir sıçrayışla kolların kilitli olacak şekilde başlangıç pozisyonuna geç.', 'Dirseklerini bükerek vücudunu, kolların 90 dereceyi geçene kadar indir. Sallanma ve iniş boyunca düzgün duruşunu koru.', 'Sonra dirseklerini açarak kendini yeniden başlangıç pozisyonuna it.', 'İstediğin tekrar sayısı kadar yap.']::text[]),
  ('Rocket_Jump', 'tr', array['Rahat bir duruşla başla: Ayakların omuz genişliğinde açık, kolların vücuduna yakın olsun.', 'Harekete geçmek için yarım squat''a in ve patlayıcı bir şekilde olabildiğince yükseğe sıçra.', 'Bütün vücudunu tam olarak uzat ve başının üstünde olabildiğince yukarı uzan. Yere inerken darbeyi bacaklarınla karşıla.']::text[]),
  ('Rocking_Standing_Calf_Raise', 'tr', array['Güvenlik için bu egzersizi squat kafesinin içinde yapmak en iyisi. Önce barı boyuna en uygun askı yüksekliğine yerleştir. Yükseklik ayarlanıp bar yüklenince barın altına gir ve onu omuzlarının arkasına, boynunun biraz altına yerleştir.', 'Barı iki elinle, iki yandan tut ve bacaklarınla iterken aynı anda gövdeni doğrultarak askıdan kaldır.', 'Askıdan uzaklaş ve omuz genişliğinde, orta açıklıkta bir duruş al; parmak uçların hafifçe dışa baksın. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar. Sırtın da düz kalsın, dizlerin hafif bükük olsun, asla kilitlenmesin. Bu, başlangıç pozisyonun.', 'Nefes verirken ayak bileklerini olabildiğince açarak topuklarını kaldır ve baldırını sık. Dizin hep sabit kalsın: Duruşu alırken verdiğin hafif büküklük dışında hiçbir anda bükülmesin. Yeniden inmeye başlamadan önce kasılmış pozisyonda bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön: Ayak bileklerini bükerek topuklarını baldırların gerilene kadar indir.', 'Şimdi nefes verirken, alt bacağın ön tarafındaki kaval kemiği kaslarını sıkarak parmak uçlarını kaldır.', 'Bir saniye bekle ve nefes alırken onları yeniden indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Rocky_Pull-Ups_Pulldowns', 'tr', array['Barfiks barını geniş tutuşla, avuçların ileri bakacak şekilde kavra.', 'Seçtiğin tutuş genişliğinde, iki kolun da uzanmış halde bara asılıyken gövdeni yaklaşık 30 derece geriye yatır, belini kavislendir ve göğsünü öne çıkar. Bu, başlangıç pozisyonun.', 'Omuzlarını ve üst kollarını aşağı ve geriye çekerek gövdeni, bar üst göğsüne değene kadar yukarı çek. Hareketin bu bölümünde nefes ver. İpucu: Tam kasılma noktasına varınca sırt kaslarını sıkmaya odaklan. Üst gövden yol boyunca kendi içinde sabit kalsın, yalnızca kolların hareket etsin. Ön kolların barı tutmaktan başka iş yapmasın.', 'Kasılmış pozisyonda bir saniye kaldıktan sonra nefes almaya başla ve gövdeni yavaşça başlangıç pozisyonuna indir; kolların tam açılsın, kanat kasların tam gerilsin.', 'Şimdi aynı hareketi yeniden yap; ama bu kez yukarı çıkarken gövden dik kalsın ve bar üst göğsüne değil ensene değsin. İpucu: Başını hafifçe öne eğ; bu, hareketin bu bölümünü doğru yapmana yardım eder.', 'Yeniden başlangıç pozisyonuna inince egzersizi programında belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Romanian_Deadlift', 'tr', array['Bir halteri önüne, yere koy ve üstten tutuşla, avuçların aşağı bakacak şekilde, omuz genişliğinden biraz geniş kavra. İpucu: Kullandığın ağırlığa göre bilek sargısına, ayrıca hareket açıklığını artırmak için yükseltilmiş bir platforma ihtiyacın olabilir.', 'Dizlerini hafifçe bük; kaval kemiklerin dik, kalçan geride, sırtın düz olsun. Bu, başlangıç pozisyonun.', 'Nefes verirken barı kalçanı kullanarak kaldır; sırtın ve kolların hep tamamen düz kalsın. İpucu: Hareket hızlı değil, dengeli ve kontrollü olmalı.', 'Tamamen dik duruşa gelince kalçanı geriye iterek barı indir; squat''tan farklı olarak dizlerini yalnızca hafifçe bük. İpucu: Hareketin başında derin bir nefes al ve göğsünü yukarıda tut. İnerken nefesini tut, hareketi tamamlarken ver.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Romanian_Deadlift_from_Deficit', 'tr', array['Ayakta, barı kolların uzanmış halde önünde tutarak başla. Hareket açıklığını artırmak için yükseltilmiş bir platformun üzerinde durabilirsin.', 'Önce dizlerini hafifçe bük, sonra kalçadan eğil: Kalçanı olabildiğince geriye it ve gövdeni esnekliğinin izin verdiği kadar indir. Sırtın hep tamamen düz ve gergin kalsın, bar bacaklarına temas etsin. Doğru yaparsan arka bacak kaslarında güçlü bir gerginlik hissedersin.', 'Hareketi tersine çevirerek başlangıç pozisyonuna dön.']::text[]),
  ('Rope_Climb', 'tr', array['Halatı iki elinle başının üstünden kavra. Halatı aşağı çekerken küçük bir sıçrayış yap.', 'Halatı bir bacağına dola ve ayaklarınla sıkıştır. Kollarınla olabildiğince yukarı uzan ve halatı sıkıca kavra.', 'Ayaklarını halattan gevşet, kollarınla kendini yukarı çek ve dizlerini göğsüne doğru getir.', 'Ayaklarını halata yeniden sabitle, sonra doğrulup halatı bir kez daha yukarıdan tut. Halatın tepesine varana kadar böyle devam et.', 'İnmek için ayaklarının halattaki tutuşunu gevşet ve ellerini sırayla birbirinin altına alarak aşağı kay.']::text[]),
  ('Rope_Crunch', 'tr', array['Halat aparatı takılı bir kablo istasyonunun 1-2 feet önünde diz çök.', 'Uygun ağırlığı seç, başının üstüne uzanıp halatı iki elinle kavra. Başlangıç pozisyonunda gövden dik olsun.', 'Başlamak için omurganı bük ve kabloyu aşağı çekerken göğüs kafesini bacaklarına yaklaştırmaya çalış.', 'Hareketin en alt noktasında kısa bir an bekle, sonra yavaşça başlangıç pozisyonuna dön.', 'Yan karın kaslarını çalıştırmak için bu hareketi dönüşlü ya da yana doğru da yapabilirsin.']::text[]),
  ('Rope_Jumping', 'tr', array['İpin birer ucunu iki eline al. İp arkanda, yerde dursun. Kollarını kaldır ve ipi başının üstünden çevirerek önüne indir. Yere vardığında üzerinden atla. Sürdürebileceğin bir çevirme temposu bul. Çeşitlilik için farklı hızlar ve teknikler kullanabilirsin.', 'İp atlamak heyecan verir, koordinasyonunu zorlar ve çok enerji ister. 150 lb ağırlığında biri 30 dakika ip atlayarak yaklaşık 350 kalori yakar; koşuda ise bu 450 kalorinin üzerindedir.']::text[]),
  ('Rope_Straight-Arm_Pulldown', 'tr', array['Yüksek makaraya bir halat tak ve ağırlığını seç. Makaradan birkaç feet geride, ayakların biri önde biri arkada dur ve halatı iki elinle tut. Sırtın düz kalacak şekilde kalçadan öne eğil; kolların önünde yukarı doğru uzanmış olsun. Bu, başlangıç pozisyonun.', 'Kollarını düz tutarak, omuzlarından hareketle halatı uyluklarına kadar aşağı çek.', 'Hareketin en alt noktasında kısa bir an bekle ve kanat kaslarını sık.', 'Ağırlığın ağırlık bloğuna tam oturmasına izin vermeden başlangıç pozisyonuna dön.']::text[]),
  ('Round_The_World_Shoulder_Stretch', 'tr', array['Bacakların bitişik, dik dur ve bir egzersiz çubuğu ya da süpürge sapı tut.', 'Çubuğu kalçanın arkasında, omuz genişliğinden geniş bir tutuşla tut. Avuçların aşağı, başparmakların dışa baksın.', 'Kollarını yavaşça başının arkasından yukarı kaldır. Daha fazla kaldırmak zorlaşırsa zorlama.']::text[]),
  ('Rowing_Stationary', 'tr', array['Kürek makinesine otur. Topuklarının ayak pedallarının tabanına rahatça yaslandığından ve kayışların sıkıldığından emin ol. Varsa kullanmak istediğin programı seç. Dik otur ve kalçadan öne eğil.', 'Kürek çekerken hareketin üç evresi vardır. İlk evrede makinede öne gelirsin: Dizlerin bükülü ve göğsüne yakındır, üst gövden düzgün duruşunu koruyarak hafifçe öne eğiktir. Ardından ayak pedallarına bastırıp bacaklarını uzat; bu sırada ellerini üst karın bölgene çek ve omuzlarını geriye sık. Sırtını zorlamamak için en çok bacak ve kalça kaslarını kullan.', 'Toparlanma evresinde yalnızca kollarını uzatır, dizlerini büker ve vücudunu yeniden öne getirirsin; böylece ilk evreye geri geçersin.']::text[]),
  ('Runners_Stretch', 'tr', array['Bu esnetmeye en kolay ayakta başlayarak girersin: Bir bacağını arkana at ve gövdeni yavaşça yere doğru indir.', 'Öndeki topuğun yerde kalsın; kalkıyorsa diğer bacağını daha geriye kaydır.', 'Ellerini öndeki bacağının iki yanına koy. Esnetmeden daha fazla yararlanmak için kalçanı tavana doğru it, sonra azar azar yeniden yere doğru indir. Böylece arkadaki bacağın kalça fleksörü ile öndeki bacağın arka bacak ve kalça kasları esner.']::text[]),
  ('Running_Treadmill', 'tr', array['Koşu bandına çık ve menüden istediğin seçeneği seç. Çoğu koşu bandında manuel ayar bulunur ya da hazır bir program seçebilirsin. Genellikle yaşını ve kilonu girerek egzersizde yakılan kalorinin tahmin edilmesini sağlarsın. Antrenmanın yoğunluğunu değiştirmek için eğimi ayarlayabilirsin.', 'Koşu bantları kullanışlıdır, kalp ve dolaşım sistemine iyi gelir ve çoğunlukla dışarıda koşmaktan daha az darbe yaratır. 150 lb ağırlığında biri saatte 8 mil hızla 30 dakika koşarak 450''den fazla kalori yakar. Koşarken doğru duruşunu koru ve tutamaklara yalnızca gerektiğinde, örneğin inerken ya da nabzına bakarken tutun.']::text[]),
  ('Russian_Twist', 'tr', array['Yere uzan; dizlerin bükülü olsun. Ayaklarını yerinden oynamayacak bir şeyin altına sok ya da bir partnere tuttur.', 'Üst gövdeni, uyluklarınla hayali bir V oluşturacak kadar kaldır. Kollarını önünde, gövdene dik olacak şekilde tam uzat ve ellerini kenetle. Bu, başlangıç pozisyonu.', 'Nefes verirken gövdeni, kolların yere paralel olana kadar sağa çevir.', 'Kasılmayı bir saniye tut ve nefes verirken başlangıç pozisyonuna dön. Şimdi sağ tarafta yaptığının aynısını karşı tarafa yap.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Sandbag_Load', 'tr', array['Kum torbalarını ya da başka cisimleri yüklemek için önce onları yükleme platformundan belli bir uzaklığa, genellikle 50 feet öteye yerleştir.', 'Kum torbasını kaldırarak başla. Kum torbaları son derece hantaldır ve nasıl kaldırılacağı kullanılan torbaya göre değişir. Torbayı olabildiğince geniş sar, kalçanı ve dizlerini açarak yukarıya, yükseğe çek. Omza almaya genellikle izin verilmez.', 'Olabildiğince hızlı şekilde platforma git ve torbayı yükle: Kalçanı, dizlerini ve ayak bileklerini açarak onu olabildiğince yükseğe çıkar. Platforma koy ve düşmediğinden emin ol.', 'Sıradaki kum torbasını almak için başlangıç noktasına dön ve yarış bitene kadar tekrarla.']::text[]),
  ('Scapular_Pull-Up', 'tr', array['Barfiks barını üstten tutuşla kavra.', 'Asılı pozisyondan, kollarını kullanmadan kendini birkaç inç yukarı kaldır. Bunu, omuz kuşağını ters bir omuz silkme hareketiyle aşağı bastırarak yap.', 'Hareketin sonunda kısa bir an bekle, sonra yavaşça başlangıç pozisyonuna dön ve diğer tekrarlara öyle geç.']::text[]),
  ('Scissor_Kick', 'tr', array['Sırtın yere ya da istersen bir egzersiz matına bastırılmış halde uzan. Kollarını yanlara tam uzat, avuçların aşağı baksın. Not: Kolların baştan sona sabit kalsın.', 'Dizlerin hafif bükük halde bacaklarını, topukların yerden yaklaşık 6 inç yukarıda olacak şekilde kaldır. Bu, başlangıç pozisyonu.', 'Şimdi sol bacağını yaklaşık 45 derecelik bir açıya kaldırırken sağ bacağını, topuğu yerden yaklaşık 2-3 inç yukarıda kalana kadar indir.', 'Bacakları değiştir: Sağ bacağını kaldır, sol bacağını indir. Bu egzersizi yaparken nefes almayı unutma.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Scissors_Jump', 'tr', array['Lunge duruşuna geç: Bir ayağın önde ve dizi bükülü, arkadaki dizin neredeyse yere değiyor olsun.', 'Öndeki dizinin ayağın orta hattının üzerinde olduğundan emin ol. İki bacağını da açarak olabildiğince yükseğe sıçra; yükselmek için kollarını savur.', 'Sıçrayışın en yüksek noktasında bacaklarının yerini değiştir: Öndeki bacak arkaya, arkadaki bacak öne gelsin.', 'Yere inerken lunge pozisyonuna geçerek darbeyi bacaklarınla karşıla ve tekrarla.']::text[]),
  ('Seated_Band_Hamstring_Curl', 'tr', array['Bir lastik bandı yere yakın bir noktaya sabitle ve birkaç feet ötesine bir sehpa koy.', 'Sehpaya otur ve bandı ayak bileklerinin arkasına tak; bacakların düz olarak başla. Bu, başlangıç pozisyonun.', 'Dizlerini bükerek ayaklarını sehpaya doğru çek. Ayakların yere çarpmasın diye hafifçe geriye yaslanman gerekebilir.', 'Hareketin sonunda kısa bir an bekle, sonra yavaşça başlangıç pozisyonuna dön.']::text[]),
  ('Seated_Barbell_Military_Press', 'tr', array['Bar başının arkasında olacak şekilde bir military press sehpasına otur. Barı ya bir yardımcı sana versin, ki bu rotator manşet için daha iyidir, ya da üstten tutuşla, avuçların ileri bakacak şekilde kendin dikkatlice al. İpucu: Tutuşun omuz genişliğinden geniş olsun; halter inerken ön kolunla üst kolun arasında 90 derecelik bir açı oluşmalı.', 'Halteri doğru tutuş genişliğinde aldıktan sonra kollarını kilitleyerek barı başının üstüne kaldır. Yaklaşık omuz hizasında ve başının biraz önünde tut. Bu, başlangıç pozisyonun.', 'Nefes alırken barı yavaşça köprücük kemiğine indir.', 'Nefes verirken barı yeniden başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Barbell_Twist', 'tr', array['Düz bir sehpanın ucuna otur ve halteri uyluklarının üstüne koy. Ayakların omuz genişliğinde açık olsun.', 'Barı avuçların aşağı bakacak şekilde, ellerin omuz genişliğinden daha açık olarak kavra. Halteri, kolların tam açılana kadar başının üstüne kaldır.', 'Şimdi halteri başının arkasına, ense köküne yaslanana kadar indir. Bu, başlangıç pozisyonu.', 'Ayaklarını ve başını sabit tutarak belini bir yandan öbür yana çevir; yan karın kaslarında kasılmayı hisset. Yanlara ancak belinin izin verdiği kadar dön. Fazla esnemek ya da fazla dönmek sakatlığa yol açabilir. İpucu: Yavaş ve kontrollü hareket et.', 'Gövdeni yana çevirirken nefes vermeyi, başlangıç pozisyonuna dönerken nefes almayı unutma.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'tr', array['Düz bir sehpanın ucuna otur ve bir elinde dambılı nötr tutuşla, avucun sana bakacak şekilde tut.', 'Dizlerini hafifçe bük ve sırtın düz kalacak şekilde belden eğilerek gövdeni, yere neredeyse paralel olana kadar öne getir. Başını yukarıda tut.', 'Dambılı tutan üst kolun gövdene yakın ve onunla aynı hizada olsun: Yere paralel olana kadar kaldırılmış, ön kol yere doğru bakıyor, el ağırlığı tutuyor. İpucu: Ön kolunla üst kolun arasında 90 derecelik bir açı olmalı. Bu, başlangıç pozisyonun.', 'Nefes verirken üst kolunu oynatmadan ağırlığı trisepsinle, ön kolun yere paralel olup kolun tamamen açılana kadar kaldır. Pek çok kol egzersizinde olduğu gibi yalnızca ön kol hareket eder.', 'Üstte bir saniye kasılı kal, sonra nefes alırken dambılı yavaşça başlangıç pozisyonuna indir.', 'Hareketi belirlenen tekrar sayısı kadar yap.', 'Kol değiştir ve egzersizi tekrarla.']::text[]),
  ('Seated_Bent-Over_Rear_Delt_Raise', 'tr', array['Bir çift dambılı, ileri bakacak şekilde düz bir sehpanın önüne koy.', 'Sehpanın ucuna bacakların bitişik otur; dambıllar baldırlarının arkasında kalsın.', 'Sırtını düz tutarak belden eğil ve dambılları al. Alırken avuçların birbirine baksın. Bu, başlangıç pozisyonun.', 'Gövden öne eğik ve sabit, kolların dirseklerden hafif bükük halde dambılları, iki kolun da yere paralel olana kadar dümdüz yanlara kaldır. Kaldırırken nefes ver. Not: Gövdeni sallama ve kollarını yanlara değil de geriye götürme.', 'Üstte bir saniye kasılı kal, sonra dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'tr', array['Düz bir sehpanın ucuna otur ve iki elinde birer dambılı nötr tutuşla, avuçların sana bakacak şekilde tut.', 'Dizlerini biraz bük, sırtını düz tut ve belden eğilerek gövdeni yere neredeyse paralel olana kadar öne getir. Başını yukarıda tut.', 'Dambılları tutan üst kolların gövdene yakın ve onunla aynı hizada olsun: Yere paralel olana kadar kaldırılmış, ön kollar yere doğru bakıyor, eller ağırlıkları tutuyor. İpucu: Ön kollarınla üst kolların arasında 90 derecelik bir açı olmalı. Bu, başlangıç pozisyonun.', 'Nefes verirken üst kollarını sabit tutarak ağırlıkları trisepsinle, ön kolların yere paralel olup kolların tamamen açılana kadar kaldır. Pek çok kol egzersizinde olduğu gibi yalnızca ön kollar hareket eder.', 'Üstte bir saniye kasılı kal, sonra nefes alırken dambılları yavaşça başlangıç pozisyonuna indir.', 'Hareketi belirlenen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Biceps', 'tr', array['Dizlerin bükülü halde yere otur; partnerin arkanda ayakta dursun. Kollarını, avuçların birbirine bakacak şekilde dümdüz arkana uzat. Partnerin bileklerinden tutsun. Bu, başlangıç pozisyonu.', 'Partnerin gerçek bir harekete izin vermezken dirseklerini bükmeye çalış.', '10-20 saniye sonra kollarını gevşet; partnerin bisepsini esnetmek için bileklerini nazikçe yukarı çeksin. Sakatlanmamak ve aşırı esnememek için esnemenin yeterli olduğu anı partnerine mutlaka söyle.']::text[]),
  ('Seated_Cable_Rows', 'tr', array['Bu egzersiz için V bar takılı, alçak makaralı bir kürek çekme makinesi gerekir. Not: V bar, avuçların birbirine baktığı nötr tutuşu sağlar. Başlangıç pozisyonuna geçmek için önce makineye otur ve ayaklarını öndeki platforma ya da çapraz çubuğa yerleştir; dizlerin hafif bükük olsun, kilitlenmesin.', 'Sırtının doğal hizasını koruyarak öne eğil ve V barın tutamaklarını kavra.', 'Kolların uzanmış halde, gövden bacaklarınla 90 derecelik açı yapana kadar geriye çekil. Sırtın hafif kavisli, göğsün dışarıda olsun. Barı önünde tutarken kanat kaslarında güzel bir esneme hissetmelisin. Bu, egzersizin başlangıç pozisyonu.', 'Gövdeni sabit tutarak tutamakları, karın kaslarına değene kadar kendine doğru çek; kolların gövdene yakın kalsın. Bu hareketi yaparken nefes ver. O noktada sırt kaslarını iyice sık. Kasılmayı bir saniye tut ve nefes alırken yavaşça ilk pozisyona dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Cable_Shoulder_Press', 'tr', array['Ağırlığı uygun bir düzeye ayarla, otur ve tutamakları kavra. Üst kolların vücuduna yaklaşık 90 derece açıda, başın ve göğsün yukarıda olsun. Dirseklerin de yaklaşık 90 derece bükülü olsun. Bu, başlangıç pozisyonun.', 'Dirseklerini açarak başla ve tutamakları başının üstünde birbirine doğru it.', 'Üstte kısa bir an bekledikten sonra tutamakları başlangıç pozisyonuna döndür. Kablolardaki gerginliği koruduğundan emin ol.', 'Bu hareketi sırtını yastıktan ayırarak ve ellerini sırayla kullanarak da yapabilirsin.']::text[]),
  ('Seated_Calf_Raise', 'tr', array['Makineye otur ve parmak uçlarını platformun alt kısmına yerleştir; topukların dışarıda kalsın. Parmak uçlarını istediğin yöne çevir: ileri, içe ya da dışa.', 'Uyluklarının alt kısmını kol pedinin altına yerleştir; pedin uyluklarının yüksekliğine göre ayarlanması gerekir. Şimdi öne kaymasın diye ellerini pedin üstüne koy.', 'Topuklarını yukarı iterek kolu hafifçe kaldır ve emniyet çubuğunu serbest bırak. Bu, başlangıç pozisyonun.', 'Nefes alırken ayak bileklerini bükerek topuklarını, baldırların tam gerilene kadar yavaşça indir.', 'Nefes verirken ayak bileklerini açarak topuklarını olabildiğince yükseğe kaldır ve baldırlarını sık. Üstte kasılmayı bir saniye tut.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Calf_Stretch', 'tr', array['Bir egzersiz matının üzerine dik otur.', 'Gövdeni sabitlemek için bir dizini bük ve o ayağını yere bas.', 'Diğer bacağını uzat ve ayak bileğini bük.', 'Bir bant, havlu ya da yetişiyorsan elinle ayak parmaklarını kendine doğru çek. 10 ila 20 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Seated_Close-Grip_Concentration_Barbell_Curl', 'tr', array['Düz bir sehpaya otur; halter ya da EZ bar önünde, bacaklarının arasında dursun. Bacakların açık, dizlerin bükülü, ayakların yerde olsun.', 'Barı kollarınla kaldır ve üst kollarının arka yüzünü iç uyluklarına yerleştir (dizin ön kısmından yaklaşık üç buçuk inç geride). Bu hareket için omuz genişliğinden dar, avuçların yukarı baktığı (supine) bir tutuş gerekir. İpucu: Kolların tam boy uzamış, bar da yerden kalkmış olmalı. Bu senin başlangıç pozisyonun.', 'Nefes verirken bisepsini sıkarak ağırlığı öne doğru kıvır; üst kolların sabit kalsın. Yalnızca ön kolların hareket etmeli. Biseps tamamen kasılana ve ağırlık omuz hizasına gelene kadar devam et. Tepe noktada bisepsini sıkarak bir saniye bekle.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir. İpucu: Hiçbir anda sallanarak hız alma.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Dumbbell_Curl', 'tr', array['Düz bir sehpaya otur; iki elinde birer dambıl olsun ve kolların aşağı doğru tam uzasın. Dirseklerin gövdene yakın dursun.', 'Avuç içlerini gövdene bakacak şekilde çevir. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tutarak ağırlıkları kıvır; dambıllar uyluklarını geçer geçmez bileklerini döndürmeye başla ki hareketin sonunda avuçların öne baksın. Kaldırırken nefes ver, bisepsini kas ve yalnızca ön kollarını oynat. Biseps tamamen kasılana ve dambıllar omuz hizasına gelene kadar devam et. Tepe noktada bisepsini sıkarak bir saniye bekle.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir; inerken bileklerini yeniden nötr tutuşa çevir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Dumbbell_Inner_Biceps_Curl', 'tr', array['Düz bir sehpanın ucuna otur; iki elinde birer dambıl olsun ve kolların aşağı doğru tam uzasın. Dirseklerin gövdene yakın dursun.', 'Avuç içlerini içe bakacak şekilde nötr konuma çevir. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tutarak dambılları dışa ve yukarı doğru kıvır. Kaldırırken avuçlarını dışa çevir ve ön kollarını dış deltoidlerinle aynı hizada tut.', 'İpucu: Yalnızca ön kolların hareket etmeli. Biseps tamamen kasılana ve dambıllar omuz hizasına gelene kadar devam et. Tepe noktada bisepsini sıkarak bir saniye bekle.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir. İndirirken kollarını döndürmeyi unutma; böylece yeniden nötr tutuşa geçersin.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Dumbbell_Palms-Down_Wrist_Curl', 'tr', array['Önce iki dambılı düz bir sehpanın önüne, yere koy.', 'Sehpanın kenarına otur; bacakların yaklaşık omuz genişliğinde açık olsun. Ayakların yerden kalkmasın.', 'İki dambılı da al ve ön kolların uyluklarına yaslanacak, avuç içlerin aşağı bakacak şekilde kaldır. Bileklerin uyluklarının kenarından sarkmalı.', 'Nefes vererek bileklerini yukarı doğru bükmekle başla.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes almaya dikkat et. İpucu: Ön kolların sabit kalsın; bu hareket için oynaması gereken tek yer bileklerin.', 'Önerilen tekrar sayısı kadar yap.', 'Bitirince dambılları yere bırakman yeterli.']::text[]),
  ('Seated_Dumbbell_Palms-Up_Wrist_Curl', 'tr', array['Önce iki dambılı düz bir sehpanın önüne, yere koy.', 'Sehpanın kenarına otur; bacakların yaklaşık omuz genişliğinde açık olsun. Ayakların yerden kalkmasın.', 'İki dambılı da al ve ön kolların uyluklarına yaslanacak, avuç içlerin yukarı bakacak şekilde kaldır. Bileklerin uyluklarının kenarından sarkmalı.', 'Nefes vererek bileklerini yukarı doğru bükmekle başla.', 'Nefes alırken bileklerini yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes almaya dikkat et. İpucu: Ön kolların sabit kalsın; bu hareket için oynaması gereken tek yer bileklerin.', 'Önerilen tekrar sayısı kadar yap.', 'Bitirince dambılları yere bırakman yeterli.']::text[]),
  ('Seated_Dumbbell_Press', 'tr', array['İki dambıl al ve bir military press sehpasına ya da sırt desteği olan çok amaçlı bir sehpaya otur; dambılları uyluklarının üzerine dik koy.', 'Dambılları birer birer yukarı al: her birini uyluğunla iterek yanında omuz hizasına getir.', 'Bileklerini çevir, avuç içlerin öne baksın. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılları tepede birbirine değene kadar yukarı it.', 'Bir saniye bekle, ardından nefes alarak yavaşça başlangıç pozisyonuna in.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Flat_Bench_Leg_Pull-In', 'tr', array['Bir sehpaya otur ve ellerinle sehpanın kenarlarından tutun. Bacaklarını önünde, paralelin biraz altında uzat; gövdeni sehpaya göre yaklaşık 45 derece geriye yatır. Bu senin başlangıç pozisyonun.', 'Dizlerini kendine doğru çek, aynı anda gövdeni de dizlerine yaklaştır. Bu hareketi yaparken nefes ver.', 'Bir saniye bekle, ardından nefes alarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Floor_Hamstring_Stretch', 'tr', array['Bir mata otur ve sağ bacağını önünde uzat. Sol bacağını bük, ayağını sağ uyluğunun iç yüzüne daya.', 'Kalçandan öne eğil ve arka bacağında gerilme hissedene kadar ayak bileğine doğru uzan. 15 saniye bekle, sonra diğer tarafla tekrarla.']::text[]),
  ('Seated_Front_Deltoid', 'tr', array['Bacakların bükülü halde yere dik otur; partnerin arkanda ayakta dursun. Kollarını yanlara dümdüz aç, avuç içlerin yere baksın. Partnerin bileklerini tutarken kollarını olabildiğince geriye götürmeye çalış. Bu senin başlangıç pozisyonun.', 'Dirseklerini düz tutarak 10-20 saniye boyunca kollarını öne getirmeye çalış; partnerin seni nazikçe tutarak gerçek bir hareket olmasını engellesin.', 'Şimdi kaslarını gevşet ve partnerinin omuzlarındaki ve göğsündeki gerilmeyi nazikçe artırmasına izin ver. 10 ila 20 saniye bekle.']::text[]),
  ('Seated_Glute', 'tr', array['Dizlerin bükülü halde otur ve bir ayak bileğini karşı dizinin üzerine at. Partnerin arkanda dursun. Partnerin elleriyle omuzlarını desteklerken öne eğil. Bu senin başlangıç pozisyonun.', '10-20 saniye boyunca gövdeni geriye itmeye çalış; partnerin gövdenin gerçekten hareket etmesini engellesin.', 'Şimdi kaslarını gevşet; partnerin 10-20 saniye boyunca gövdeni nazikçe öne iterek gerilmeyi artırsın.']::text[]),
  ('Seated_Good_Mornings', 'tr', array['Power rack''in içine bir kutu yerleştir ve emniyet pimlerini uygun bir yüksekliğe ayarla. Barın altına gir ve barı trapezinin üstüne değil, omuzlarının arka kısmına oturt. Kürek kemiklerini birbirine yaklaştır ve dirseklerini öne çevir; barı omuzlarının üzerinde bükmeye çalışıyormuş gibi yap.', 'Belinde sıkı bir kavis oluşturarak barı sehpadan al. Başın öne baksın. Sırtın, omuzların ve gövde merkezin sıkıyken dizlerini ve kalçanı dışarı iterek inmeye başla. Kutuya oturana kadar kalçanla geriye otur. Bu senin başlangıç pozisyonun.', 'Barı sıkı tutarak kalçandan olabildiğince öne eğil. Pimleri paralele denk gelen yüksekliğe ayarladıysan hem kaldıramadığında güvencen olur hem de nerede duracağını bilirsin.', 'Pimlerin hemen üstünde kısa bir an dur ve gövden dikleşene kadar hareketi tersine çevir.']::text[]),
  ('Seated_Hamstring', 'tr', array['Bacakların uzatılmış halde otur; partnerin arkanda ayakta dursun. Partnerin elleriyle omuzlarını desteklerken öne eğil. Bu senin başlangıç pozisyonun.', '10-20 saniye boyunca gövdeni geriye itmeye çalış; partnerin gövdenin gerçekten hareket etmesini engellesin.', 'Şimdi kaslarını gevşet; partnerin 10-20 saniye boyunca gövdeni nazikçe öne iterek gerilmeyi artırsın.']::text[]),
  ('Seated_Hamstring_and_Calf_Stretch', 'tr', array['Bir kemeri, ipi ya da bandı bir ayağına halka yaparak geçir. İki bacağın da uzatılmış halde otur. Bu senin başlangıç pozisyonun.', 'Hafifçe öne eğil ve kemeri çekerek o ayağının parmaklarını kendine doğru getir. Bu pozisyonda 10-20 saniye kal, sonra diğer bacakla tekrarla.']::text[]),
  ('Seated_Head_Harness_Neck_Resistance', 'tr', array['Bir boyun kayışını düz bir sehpanın ucunda, yere koy. Ağırlıkları seçtikten sonra sehpanın ucuna otur; ayakların omuz genişliğinden daha açık olsun. Ayak parmakların dışa baksın.', 'Gövdeni yere neredeyse paralel olana kadar yavaşça öne eğ. İki elinle boyun kayışını başına sağlam biçimde yerleştir. İpucu: Boynun zorlanmasın diye ağırlıklar bu sırada yerde durmaya devam etsin. Şimdi ağırlığı iki elinle tut ve gövdeni yere neredeyse dik olana kadar kaldır. Not: Bu hareketi yapmak için başın ve gövden hafifçe öne eğik olmalı.', 'Şimdi iki elini dizlerinin üzerine koy. Bu başlangıç pozisyonu.', 'Nefes alırken başını, çenen göğsünün üst kısmına değene kadar yavaşça indir.', 'Nefes verirken boynunu başlangıç pozisyonuna geri getir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Leg_Curl', 'tr', array['Makinenin kolunu boyuna göre ayarla ve sırtını sırt desteğine yaslayarak makineye otur.', 'Alt bacaklarının arka yüzünü yastıklı kolun üzerine koy (baldırların yalnızca birkaç inç altı) ve kucak yastığını uyluklarına, dizlerinin hemen üstüne sabitle. Sonra makinenin yan tutamaklarını kavra, ayak parmaklarını düz tut (diğer iki ayak duruşundan birini de kullanabilirsin) ve bacaklarının önünde tamamen düz olduğundan emin ol. Bu senin başlangıç pozisyonun.', 'Nefes verirken dizlerini bükerek kolu uyluklarının arkasına doğru gidebildiği kadar çek. Gövden hep sabit kalsın. Kasılı pozisyonda bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Leg_Tucks', 'tr', array['Bir sehpaya otur ve sehpanın yanlarını kavra. Bacakların önünde, paralelin biraz altında uzansın; gövden sehpaya göre yaklaşık 45 derece geriye yatık olsun. Bu senin başlangıç pozisyonun.', 'Dizlerini içeri çekerken gövdeni de aynı anda onlara doğru getir. Bunu yaparken nefes ver.', 'Bir saniye durduktan sonra nefes alarak başlangıç pozisyonuna geri git.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'tr', array['Sağ elinde bir dambılla düz bir sehpaya otur.', 'Ayaklarını omuz genişliğinden biraz daha açık olacak şekilde yere düz bas.', 'Öne eğil ve sağ ön kolunu, avucun aşağı bakacak şekilde sağ uyluğunun üst kısmına koy. İpucu: Bileğinin arka yüzü dizinin üzerine gelmeli. Bu senin başlangıç pozisyonun.', 'Nefes alırken dambılı sıkıca kavramayı sürdürerek inebildiği kadar aşağı indir.', 'Şimdi nefes verirken ön kolunu kasarak dambılı olabildiğince yukarı kıvır. Yeniden indirmeden önce kasılmayı bir saniye koru. İpucu: Hareket yalnızca bilekten gelmeli.', 'Önerilen tekrar sayısı kadar yap, kol değiştir ve hareketi tekrarla.']::text[]),
  ('Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'tr', array['Sağ elinde bir dambılla düz bir sehpaya otur.', 'Ayaklarını omuz genişliğinden biraz daha açık olacak şekilde yere düz bas.', 'Öne eğil ve sağ ön kolunu, avucun yukarı bakacak şekilde sağ uyluğunun üst kısmına koy. İpucu: Bileğinin ön yüzü dizinin üzerine gelmeli. Bu senin başlangıç pozisyonun.', 'Nefes alırken dambılı sıkıca kavramayı sürdürerek inebildiği kadar aşağı indir.', 'Şimdi nefes verirken ön kolunu kasarak dambılı olabildiğince yukarı kıvır. Yeniden indirmeden önce kasılmayı bir saniye koru. İpucu: Hareket yalnızca bilekten gelmeli.', 'Önerilen tekrar sayısı kadar yap, kol değiştir ve hareketi tekrarla.']::text[]),
  ('Seated_One-arm_Cable_Pulley_Rows', 'tr', array['Başlangıç pozisyonuna geçmek için önce makineye otur ve ayaklarını öndeki platforma ya da çubuğa bas; dizlerin kilitli değil, hafif bükülü olsun.', 'Sırtının doğal duruşunu bozmadan öne eğil ve tekli tutamağı sol elinle, avucun aşağı bakacak şekilde kavra.', 'Kolun uzatılmış halde, gövden bacaklarınla 90 derecelik açı yapana kadar geriye çekil. Sırtın hafif kavisli, göğsün dışarıda olsun. Tutamağı önünde tutarken kanadında iyi bir gerilme hissetmelisin. Sağ kolun belinin yanında durabilir. Bu, hareketin başlangıç pozisyonu.', 'Gövdeni sabit tutarak tutamağı gövdene doğru çek; kolun gövdene yakın kalsın. Çekerken bileğini çevir ki elin karnının yanına geldiğinde nötr konumda olsun (avuç gövdeye bakar). Bu hareketi yaparken nefes ver. Bu noktada sırt kaslarını kuvvetlice sık.', 'Kasılmayı bir saniye koru ve nefes alarak yavaşça ilk konuma dön. İpucu: Dönerken de bileğini çevirmeyi unutma; başlangıçta avucun yeniden aşağı bakmalı.', 'Önerilen tekrar sayısı kadar yap, ardından aynı hareketi sağ elinle uygula.']::text[]),
  ('Seated_Overhead_Stretch', 'tr', array['Bir egzersiz matında sırtın dik olacak şekilde otur.', 'Ayak tabanlarını birleştir; ayakların kalçanın altı ila sekiz inç önünde dursun.', 'Bir elini yanında yere koy, diğer elini başının arkasına yerleştir.', 'Dirseğini tavana doğru kaldırırken gövdeni diğer tarafa eğ. 10 ila 20 saniye bekle, sonra taraf değiştir.']::text[]),
  ('Seated_Palm-Up_Barbell_Wrist_Curl', 'tr', array['Bir halteri iki elinle, avuçların yukarı bakacak şekilde tut; ellerin arası yaklaşık omuz genişliğinde olsun.', 'Ayaklarını omuz genişliğinden biraz daha açık olacak şekilde yere düz bas.', 'Öne eğil ve ön kollarını, avuçların yukarı bakacak şekilde uyluklarının üst kısmına koy. İpucu: Bileklerinin ön yüzü dizlerinin üzerine gelmeli. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı sıkıca kavramayı sürdürerek inebildiği kadar aşağı indir.', 'Şimdi nefes verirken ön kollarını kasarak barı olabildiğince yukarı kıvır. Tepe noktada kasılmayı bir saniye koru. İpucu: Yalnızca bileklerin hareket etmeli.']::text[]),
  ('Seated_Palms-Down_Barbell_Wrist_Curl', 'tr', array['Bir halteri iki elinle, avuçların aşağı bakacak şekilde tut; ellerin arası yaklaşık omuz genişliğinde olsun.', 'Ayaklarını omuz genişliğinden biraz daha açık olacak şekilde yere düz bas.', 'Öne eğil ve ön kollarını, avuçların aşağı bakacak şekilde uyluklarının üst kısmına koy. İpucu: Bileklerinin arka yüzü dizlerinin üzerine gelmeli. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı sıkıca kavramayı sürdürerek inebildiği kadar aşağı indir.', 'Şimdi nefes verirken ön kollarını kasarak barı olabildiğince yukarı kıvır. Tepe noktada kasılmayı bir saniye koru. İpucu: Yalnızca bileklerin hareket etmeli.']::text[]),
  ('Seated_Side_Lateral_Raise', 'tr', array['İki dambıl al ve düz bir sehpanın ucuna otur; ayakların yere sağlam bassın. Kolların iki yanında aşağı doğru tam uzasın, avuç içlerin içe baksın. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut (sallanma yok) ve dambılları yanlara doğru kaldır. Dirseklerin hafif bükülü, ellerin de bardağa su döküyormuş gibi biraz öne eğik olsun. Kolların yere paralel olana kadar kaldırmaya devam et. Kaldırırken nefes ver ve tepede bir saniye bekle.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Triceps_Press', 'tr', array['Sırt desteği olan bir sehpaya otur, bir dambılı iki elinle kavra ve kolların tam uzamış halde başının üzerinde tut. İpucu: Özellikle çok ağırsa dambılı birinin sana vermesi daha iyidir. Ağırlık avuçlarının içinde durmalı, başparmakların onu sarmalı. Avuç içlerin içe bakmalı. Bu senin başlangıç pozisyonun.', 'Üst kollarını başına yakın (dirsekler içeride) ve yere dik tut. Ağırlığı yarım daire çizerek, ön kolların bisepsine değene kadar başının arkasına indir. İpucu: Üst kollar sabit kalmalı, yalnızca ön kollar hareket etmeli. Bu adımda nefes al.', 'Trisepsinin gücüyle dambılı kaldırarak başlangıç pozisyonuna dön. Bu adımda nefes ver.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'tr', array['Düz bar ya da EZ bar aparatı takılı alçak makaralı bir kablo istasyonunun önüne bir sehpa koy.', 'Sehpayı yeterince uzağa çek; tutamağı uyluklarının üstüne getirdiğinde ağırlık bloğu yukarı kalkmalı ve kablo gergin olmalı.', 'Şimdi tutamağı iki elinle, avuçların yukarı bakacak şekilde omuz genişliğinde kavra.', 'Geri adım at ve sehpaya otur; ayakların yaklaşık omuz genişliğinde açık, yere sağlam basıyor olsun.', 'Öne eğil ve ön kollarını uyluklarına yerleştir; bileklerinin arka yüzü dizlerinin üzerinde dursun. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı sıkıca kavramayı sürdürerek inebildiği kadar aşağı indir.', 'Şimdi ön kollarını kasarak barı olabildiğince yukarı kıvır. İpucu: Hareket ön kollardan değil, yalnızca bileklerden gelmeli.', 'Tepede kasılmayı bir saniye koru, ardından nefes alarak başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('See-Saw_Press_Alternating_Side_Press', 'tr', array['İki eline birer dambıl al ve dimdik ayakta dur.', 'Dambılları clean hareketiyle (kaldırarak) göğüs ya da omuz hizasına getir, sonra bileklerini avuçların sana bakacak şekilde çevir; Arnold press yapmaya hazırlanıyormuş gibi. Bu senin başlangıç pozisyonun.', 'Şimdi sol kolunu başının üzerine uzatmaya başla; yukarı çıkarken bileğini çevir ki avucun öne baksın. Ağırlığı kaldırırken dirseklerin de dışa açılmalı. Aynı anda kalçandan karşı tarafa doğru eğil. İpucu: Hareketi doğru yaparsan, sol kolunla vücudunun sağ tarafında yukarıdaki bir şeye uzanmaya çalışıyormuşsun gibi görünür. Bu hareketi yaparken nefes ver.', 'Tepe noktaya ulaşınca nefes al. Ardından, ağırlık başının üzerinde tam uzamış ve sen sağ tarafına eğilmişken hareketi sol tarafa doğru başlat.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Shotgun_Row', 'tr', array['Alçak kabloya tekli bir tutamak tak.', 'Doğru ağırlığı seçtikten sonra birkaç feet geride, bacakların öne arkaya geniş açık halde dur. Kolun uzamış, omzun öne gitmiş olsun. Bu senin başlangıç pozisyonun.', 'Omzunu geriye çekip dirseğini bükerek hareketi yap. Çekerken bileğini supinasyona getir; avucun yol boyunca yukarı dönsün.', 'Kısa bir an dur, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Shoulder_Circles', 'tr', array['Omuzların gevşek, kolların iki yanında serbestçe sarkarken (oturuyorsan kucağında dururken) omuzlarını nazikçe öne, yukarı, geriye ve aşağı yuvarla.', 'Yönü tersine çevir. Bu hareketi omuzlarını sırayla ya da ikisini birden çevirerek yapabilirsin.']::text[]),
  ('Shoulder_Press_-_With_Bands', 'tr', array['Başlamak için bir lastik bandın üzerine, kolların tam uzadığında bant gerilmeye başlayacak şekilde bas. Tutamakları kavra ve ellerin iki yanında omuz hizasına gelene kadar kaldır.', 'Bileklerini çevir, avuç içlerin öne baksın. Dirseklerin bükülü, üst kolların ve ön kolların gövdenle aynı hizada olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken tutamakları, kolların başının üzerinde tamamen uzayana kadar yukarı kaldır.']::text[]),
  ('Shoulder_Raise', 'tr', array['Kollarını iki yanında gevşek bırak, omuzlarını kulaklarına doğru kaldır ve yeniden indir.']::text[]),
  ('Shoulder_Stretch', 'tr', array['Sol kolunu vücudunun önünden karşı tarafa uzat ve düz tut.']::text[]),
  ('Side-Lying_Floor_Stretch', 'tr', array['Önce sol yanına yat ve gövdeni sabitlemek için sol dizini önünde bük (dik kalmak için karın kaslarını da kullan).', 'Sağ bacağını düzleştir ve sağ ayağını sol ayağının arkasında yere koy. Sağ kolunu başının üzerine uzat ve vücudunun tüm sağ yanını esnetmek için sağ bileğini nazikçe çek. Taraf değiştir.']::text[]),
  ('Side_Bridge', 'tr', array['Yan yat; bacakların düz ve üst üste olsun. Alttaki ön kolunun üzerine dayan, dirseğin tam omzunun altında dursun.', 'Karnını sık ve kalçanı yerden kaldır; vücudun baştan ayağa düz bir çizgi oluştursun.', 'Düzenli nefes alarak bu pozisyonda kal. Kalçan aşağı düşmesin ve dönmesin.', 'Kalçanı yere indir, sonra diğer tarafta tekrarla.']::text[]),
  ('Side_Hop-Sprint', 'tr', array['Bir huninin ya da engelin yanında dur.', 'Çalışmaya engelin üzerinden yana sıçrayarak başla; yere iner inmez yaylanıp başladığın yere geri sıçra.', 'Belirlenen tekrar sayısı kadar, olabildiğince hızlı sıçra. Son sıçrayıştan yere inince kısa bir mesafe sprint atarak çalışmayı bitir.']::text[]),
  ('Side_Jackknife', 'tr', array['Yan yat; bacakların düz ve üst üste olsun. Alttaki kolunu önünde yere koy, üstteki elini başının arkasına yerleştir.', 'Nefes verirken üstteki bacağını tavana doğru kaldır; aynı anda gövdeni yana doğru kaldırıp dirseğini bacağına yaklaştır.', 'Yan karnındaki kasılmayı kısa bir an koru, sonra nefes alarak bacağını ve gövdeni kontrollü biçimde indir.', 'Önerilen tekrar sayısı kadar yap, sonra diğer tarafa geç.']::text[]),
  ('Side_Lateral_Raise', 'tr', array['İki dambıl al ve gövden dik olacak şekilde ayakta dur. Dambıllar, kolların tam uzamış halde iki yanında dursun; avuç içlerin sana baksın. Bu senin başlangıç pozisyonun.', 'Gövdeni hiç sallamadan sabit tut ve dambılları yanlara kaldır. Dirseklerini hafifçe bük, ellerini de bardağa su döküyormuş gibi biraz öne eğ. Kolların yere paralel olana kadar çıkmayı sürdür. Kaldırırken nefes ver ve tepede bir saniye bekle.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Side_Laterals_to_Front_Raise', 'tr', array['Ayakta dur ve bir çift dambılı iki yanında tut. Bu senin başlangıç pozisyonun.', 'Dirseklerin hafif bükülü kalsın ve ağırlıkları tam önünde omuz hizasına kaldır; sallanma ya da hile yapma.', 'Hareketin tepesinde, kollarını uzatılmış tutarak ağırlıkları önünde dışa doğru götür.', 'Ağırlıkları kontrollü bir hareketle indir.', 'Sonraki tekrarda ağırlıkları önce önünde omuz hizasına kaldır, sonra yana, iki tarafa doğru aç.', 'Ağırlıkları başlangıç pozisyonuna indir.']::text[]),
  ('Side_Leg_Raises', 'tr', array['Destek için tutunabileceğin bir sandalyenin yanında dur. Tek bacağının üzerinde dur. Bu senin başlangıç pozisyonun.', 'Diğer bacağını düz tutarak olabildiğince yana kaldır, sonra aşağı doğru savur ve yerdeki bacağının önünden çapraza geçmesine izin ver.', 'Bu savurma hareketini 5-10 kez tekrarla; tekrarladıkça hareket açıklığını artır.']::text[]),
  ('Side_Lying_Groin_Stretch', 'tr', array['Sağ yanına yatarak başla ve gövdeni sabitlemek için sağ dizini önünde bük.', 'Başını sağ eline ya da omzuna yasla. Sol bacağını yukarı kaldır ve dizinin arkasından (daha kolay) ya da ayağından (daha zor) tut.', 'Sol dizini sol omzuna doğru çek, aynı anda ayağını ya da dizini yere doğru bastır. Gerilmeyi artırmak için sol bacağını düzleştir. Taraf değiştir.']::text[]),
  ('Side_Neck_Stretch', 'tr', array['Omuzların gevşekken başını nazikçe omzuna doğru eğ.', 'Başının yanından hafifçe çekerek gerilmeye yardımcı ol.']::text[]),
  ('Side_Standing_Long_Jump', 'tr', array['Ayakların kalça genişliğinde açık, atletik bir duruşla başla. Başın ve göğsün yukarıda, dizlerin ve kalçan hafif bükülü olsun. Bu senin başlangıç pozisyonun.', 'Sağına doğru eğil; kalçanı, dizlerini ve ayak bileklerini açarak havaya sıçra. Kollarınla blok yaparak harekete öncülük et ve sağına doğru gidebildiğin kadar uzağa atla.', 'Aynı yöne bakarak, ayakların kalça genişliğinde açık halde yere in ve darbeyi alt vücudunla karşıla.']::text[]),
  ('Side_To_Side_Chins', 'tr', array['Barfiks barını avuçların öne bakacak şekilde geniş tutuşla kavra.', 'İki kolun da uzamış halde barı geniş tutarken gövdeni yaklaşık 30 derece geriye yatır, belinde kavis oluştur ve göğsünü dışarı çıkar. Bu senin başlangıç pozisyonun.', 'Sol tarafa yatarak gövdeni, bar göğsünün üst kısmına neredeyse değene kadar yukarı çek; bunun için omuzlarını ve üst kollarını aşağı ve geriye indir. Hareketin bu bölümünde nefes ver. İpucu: Tam kasılı pozisyona ulaştığında sırt kaslarını sıkmaya odaklan. Üst gövden yukarı çıkarken kendi içinde sabit kalmalı (sallanma yok), yalnızca kolların çalışmalı. Ön kolların barı tutmaktan başka bir iş yapmamalı.', 'Kasılmayı bir saniye koruduktan sonra nefes alarak başlangıç pozisyonuna dön.', 'Şimdi sağ tarafa yatarak gövdeni, bar göğsünün üst kısmına neredeyse değene kadar yukarı çek; bunun için omuzlarını ve üst kollarını aşağı ve geriye indir. Hareketin bu bölümünde nefes ver. İpucu: Tam kasılı pozisyona ulaştığında sırt kaslarını sıkmaya odaklan. Üst gövden yukarı çıkarken kendi içinde sabit kalmalı, yalnızca kolların çalışmalı. Ön kolların barı tutmaktan başka bir iş yapmamalı.', 'Kasılmayı bir saniye koruduktan sonra nefes alarak başlangıç pozisyonuna dön.', 'Her taraf için belirlenen tekrar sayısını tamamlayana kadar 3-6. adımları tekrarla.']::text[]),
  ('Side_Wrist_Pull', 'tr', array['Bu esneme en iyi ayakta yapılır. Sol kolunu vücudunun orta çizgisinin öbür yanına geçir ve sol bileğini sağ elinle, aşağıda kalça hizasında tut. Esnemeye sol kolun bükülü halde başla.', 'Kolunu yavaşça düzleştir, çek ve omuz hizasına kaldır. Gerilmenin omuzlarından değil sırtından başladığını hisset; omuz eklemini fazla sert çekme. Taraf değiştir.']::text[]),
  ('Side_to_Side_Box_Shuffle', 'tr', array['Kutunun bir yanında dur; sol ayağın kutunun ortasına basıyor olsun.', 'Başlamak için yukarı sıçrayıp kutunun öbür yanına geç; sağ ayağın kutunun üstüne, sol ayağın yere insin. Harekete yardımcı olması için kollarını savur.', 'Kutunun üzerinden bir o yana bir bu yana geçmeyi sürdür.']::text[]),
  ('Single-Arm_Cable_Crossover', 'tr', array['Makaraları yukarı konuma al, direnci seç ve her eline bir tutamak al.', 'İki makaranın önüne doğru bir adım at; kolların önünde düz, ellerin bir arada olsun. Öne eğilirken başını ve göğsünü dik tut, ayaklarını biri önde biri arkada yerleştir. Bu senin başlangıç pozisyonun.', 'Sol kolunu yerinde tut, sağ kolunu dirseğin hafif bükülü kalacak şekilde yana aç. Sağ kolun yaklaşık omuz hizasında, gövdene dik olmalı.', 'Elini gövdenin orta hattına çekerek kolunu başlangıç pozisyonuna geri getir.', 'Başlangıç pozisyonunda bir saniye bekle ve hareketi diğer kolunla tekrarla. Belirlenen tekrar sayısına ulaşana kadar kolları sırayla değiştir.']::text[]),
  ('Single-Arm_Linear_Jammer', 'tr', array['Bir barı landmine aparatına tak ya da bir köşeye sağlamca sabitle. Bara uygun ağırlığı yükle.', 'Barı yerden kaldır ve tek ya da iki elinle omuzlarına getir. Ayaklarını geniş aç. Bu senin başlangıç pozisyonun.', 'Dirseğini açarak ağırlığı yukarı it. Patlayıcı hareket et; en yüksek kuvveti üretmek için kalçanı ve dizlerini tam aç.', 'Başlangıç pozisyonuna dön.']::text[]),
  ('Single-Arm_Push-Up', 'tr', array['Yüzüstü yere uzan. Ağırlığını ayak parmaklarınla tek kolunun taşıdığı bir pozisyona geç. Çalışan kolun tam düz, elin omzunun tam altında olsun. Bacaklarını düz tut; bu harekette daha geniş bir tabana ihtiyacın olabilir, ayaklarını normal şınava göre daha açık yerleştir.', 'Duruşunu bozma ve boştaki elini sırtına koy. Bu senin başlangıç pozisyonun.', 'Dirseğini bükerek yere değene kadar alçal.', 'Yavaşça in, sonra kolunu düzleştirip başlangıç pozisyonuna dön.']::text[]),
  ('Single-Cone_Sprint_Drill', 'tr', array['Bu çalışma ayakları hızlı kullanmayı öğretir. Tek bir koni yeter. Koninin yanında bir kolun önde, bir kolun arkada olacak şekilde dur.', 'Ayaklarını olabildiğince hızlı, kısa adımlarla çalıştır ve kollarınla harekete eşlik et. Dizlerini yukarıda tutarak, sert ayak hareketleriyle koninin etrafında dön.', 'Koninin etrafında üç tur attıktan sonra dinlen.']::text[]),
  ('Single-Leg_High_Box_Squat', 'tr', array['Bir kasayı rack''in içine yerleştir. Kasanın üstüne bir lastik bant ya da ip sabitle.', 'Kasanın önünde dur ve üzerine çıkıp tam dik pozisyona gel; diğer bacağın boşta kalsın. Dengen için banda tutun.', 'Aynı bacakla inip çıkmaya devam et, ardından diğer tarafa geç.']::text[]),
  ('Single-Leg_Hop_Progression', 'tr', array['Önüne konileri tek sıra halinde diz. Tek ayak üzerinde dengede, rahat bir duruş al. Diğer bacağının dizini kaldır. Bu senin başlangıç pozisyonun.', 'Öne doğru zıpla; koninin üzerinden aynı bacakla sıçrayıp aynı bacağa in.', 'Her zıplamadan önce hafifçe çöküp hız alarak koniden koniye ilerle.', 'Sıranın sonunda geri dön ve diğer bacağınla aynı yolu tamamla.']::text[]),
  ('Single-Leg_Lateral_Hop', 'tr', array['Bir koninin ya da engelin yanında dur. Başlangıç pozisyonu için dizin hafif bükülü, tek ayak üzerinde dur.', 'Hafifçe çöküp hız al ve koninin üzerinden yana doğru zıpla.', 'Sıçradığın bacağa in ve hiç beklemeden geri zıplayarak başlangıç pozisyonuna dön.', 'İleri geri zıplamaya devam et.']::text[]),
  ('Single-Leg_Leg_Extension', 'tr', array['Makineye otur ve kendine göre ayarla. Ped kaval kemiğinin alt kısmına yaslanmalı ama ayak bileğine değmemeli. Koltuğu, makinenin dönme noktası dizinle aynı hizaya gelecek şekilde ayarla. Seviyene uygun bir ağırlık seç.', 'Dik otur, tek bacağını tam aç ve hareketin en üstünde kısa bir süre bekle.', 'Ağırlığı yerine bırakmadan başlangıç pozisyonuna dön; kas gergin kalsın.', 'İstediğin tekrar sayısı kadar yap.']::text[]),
  ('Single-Leg_Stride_Jump', 'tr', array['Bir kasanın yanında dur ve kasaya yakın ayağını üzerine, kenara yakın koy.', 'Kollarını yukarı savur, kasanın üzerindeki bacağınla kendini it ve olabildiğince yükseğe sıçra. Diğer dizini yukarı çekmeye çalış.', 'Başladığın pozisyona in ve inişin etkisini kasaya yakın bacağınla yumuşat.']::text[]),
  ('Single_Dumbbell_Raise', 'tr', array['Ayakların geniş açık dururken bir dambılı iki elinle tut; sapından değil, başından kavra. Kolların uzamış halde bel hizasında sarksın. Bu senin başlangıç pozisyonun.', 'Kollarını uzatılmış tutarak ağırlığı omuz hizasının üstüne çıkana kadar kaldır. Gövden ve kalçan hareket boyunca sabit kalsın.', 'Başlangıç pozisyonuna dön ve önerilen tekrar sayısı kadar yap.']::text[]),
  ('Single_Leg_Butt_Kick', 'tr', array['Tek ayak üzerinde dur, diğer dizini bükerek yukarı kaldır. Bu senin başlangıç pozisyonun.', 'Hafifçe çöküp hız al ve yerdeki bacağının kalça, diz ve ayak bileğini açarak yukarı sıçra.', 'Hemen dizini bük ve sıçradığın bacağın topuğunu kalçana değdirmeye çalış.', 'Bacağını hafif bükülü halde kalçanın altına geri getir ve yere in. Diğer bacağın hareket boyunca aşağı yukarı aynı konumda kalsın.']::text[]),
  ('Single_Leg_Glute_Bridge', 'tr', array['Sırtüstü yere uzan; dizlerin bükülü, ayak tabanların yerde olsun.', 'Bir bacağını yerden kaldır ve dizini göğsüne çek. Bu senin başlangıç pozisyonun.', 'Yerdeki ayağının topuğundan güç al, kalçanı yukarı it ve yerden kaldır.', 'Kalçanı açabildiğin kadar aç, kısa bir süre bekle ve başlangıç pozisyonuna dön.']::text[]),
  ('Single_Leg_Push-off', 'tr', array['Yerde dur ve bir ayağını kasanın üzerine koy; topuğun kenara yakın olsun.', 'Kasanın üzerindeki ayağınla kendini it, kalçanı ve dizini açarak olabildiğince yükseğe çık.', 'Aynı ayağınla kasanın üzerine in, diğer ayağını da başlangıçtaki yerine geri koy.']::text[]),
  ('Sit-Up', 'tr', array['Yere uzan ve dizlerini bük. Ayaklarını kıpırdamayan bir şeyin altına sok ya da bir arkadaşından tutmasını iste.', 'Ellerini başının arkasına koy ve parmaklarını birbirine kenetle. Bu başlangıç pozisyonu.', 'Üst gövdeni, uyluklarınla hayali bir V şekli oluşturana kadar kaldır. Bunu yaparken nefes ver.', 'Kasılmayı bir saniye hisset, sonra nefes alarak üst gövdeni başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Sit_Squats', 'tr', array['Ayaklarını omuz genişliğinde aç. Bu senin başlangıç pozisyonun.', 'Dizlerini ve kalçanı bük, kalçanı oturur gibi geriye it.', 'Paralelin üstünde kalacak şekilde bir miktar çök, sonra hızla hareketi tersine çevirip başlangıç pozisyonuna dön. 5-10 tekrar yap.']::text[]),
  ('Skating', 'tr', array['Patenle kaymak eğlencelidir; kalp-solunum kondisyonunu ve kas dayanıklılığını geliştirebilir. Epey iyi denge ve koordinasyon ister. Önce temel teknikleri, bu arada dönmeyi ve durmayı öğren; sakatlanmamak için koruyucu ekipman giy.', 'Rahat bir tempoda 30 dakika aralıksız kay. Kardiyoda kendini zorlamak istersen aralıklı kay: her beş dakikanın iki dakikasında hızlan, kalan üç dakikada toparlan. 150 lb ağırlığındaki bir kişi rahat tempoda 30 dakikada yaklaşık 175 kalori yakar; bu, tempolu yürüyüşe yakındır.']::text[]),
  ('Sled_Drag_-_Harness', 'tr', array['Kızağa istediğin ağırlığı yükle ve çekme kayışını tak. Tutamaklardan çekebilir, koşum takabilir ya da kayışı bir ağırlık kemerine bağlayabilirsin.', 'İster ileri ister geri çek: gittiğin yöne doğru eğil, kalçanı ve dizlerini açarak ilerle.']::text[]),
  ('Sled_Overhead_Backward_Walk', 'tr', array['İp ya da zincirle kızağa iki tutamak bağla. Kızağa hafif bir ağırlık yükle.', 'Yüzünü kızağa dön ve ip hafifçe gerilene kadar geri git. Ellerini dirseklerin düz olacak şekilde başının tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Kollarını başının üstünde tutarak geri geri yürü. Ani, sarsıntılı hareketlerden kaçın.']::text[]),
  ('Sled_Overhead_Triceps_Extension', 'tr', array['Zincir ya da iple kızağa iki tutamak bağla. Kızağa uygun bir ağırlık yükle.', 'Sırtını kızağa dön ve ip gerilene kadar uzaklaş. Ellerini bir arada, avuç içlerin birbirine bakacak şekilde başının üstüne kaldır. Dirseklerin bükülü olsun ve yukarıyı göstersin. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak kollarını düzleştir. Üst kolların yerinde kalsın ki yalnızca triseps çalışsın.', 'Kolların tam açılınca ipin boşluğunu almak için öne adım at. Daha sağlam durmak için ayaklarını biri önde biri arkada tutabilirsin.']::text[]),
  ('Sled_Push', 'tr', array['İtme kızağına istediğin ağırlığı yükle.', 'Atletik bir duruş al, tutamakları kavra ve kolların tam düzken kızağa doğru yaslan. Kızağı olabildiğince hızlı it; kalçanı ve dizlerini açmaya odaklan, böylece arka zincirini güçlendirirsin.']::text[]),
  ('Sled_Reverse_Flye', 'tr', array['İp ya da zincirle kızağa iki tutamak bağla. Kızağa hafif bir ağırlık yükle.', 'Yüzünü kızağa dön ve ip hafifçe gerilene kadar geri git. İki tutamağı kolların düzken yaklaşık bel hizasında tut. Dizlerini hafifçe bük, göğsünü ve başını dik tut. Bu senin başlangıç pozisyonun.', 'Dirseklerini bükmeden tutamakları yukarı ve yanlara çek; kolları hafifçe dışa döndürerek ters açış yap. Bunu yaparken avuç içlerin öne baksın.', 'Başlangıç pozisyonuna dön ve ipin boşluğunu almak için birkaç adım geri git.']::text[]),
  ('Sled_Row', 'tr', array['İp ya da zincirle kızağa iki tutamak bağla. Kızağa uygun bir ağırlık yükle. Yüzünü kızağa dön ve ip hafifçe gerilene kadar geri git.', 'Her eline bir tutamak al, dizlerini hafifçe bük, başını ve göğsünü dik tut ve kolların düz halde başla.', 'Dirseklerini bük, kürek kemiklerini birbirine yaklaştır ve kızağı kendine doğru çek.', 'İp yeniden gerilsin diye bir iki adım geri git ve tekrarla.']::text[]),
  ('Sledgehammer_Swings', 'tr', array['Bu egzersiz için bir lastik ve bir balyoz gerekir. Lastiğin önünde, ondan yaklaşık iki feet uzakta, ayakların biri önde biri arkada dur. Balyozu kavra.', 'Sağ elini kullanıyorsan sol elin sapın ucunda, sağ elin daha yukarıda, balyozun başına yakın olsun.', 'Balyozu kaldırırken sağ elin başa doğru kayar; aşağı savururken sapın ucuna inip sol elinle buluşur. Balyozu lastiğe vurabildiğin kadar sert vur. Lastikten geri sekmesini kontrol et.', 'Diğer tarafta tekrarla.']::text[]),
  ('Smith_Incline_Shoulder_Raise', 'tr', array['Smith makinesinin altına eğimli bir sehpa koy. Barı, uzandığında kolların neredeyse tam düzken yetişebileceğin yüksekliğe ayarla. Ağırlığını seçtikten sonra sehpaya uzan ve omuzlarının tam barın altında olduğundan emin ol.', 'Barı omuz genişliğinde, üstten (avuç içleri öne bakan) tutuşla kavra, askıdan kaldır ve dirseklerin hafif bükülü halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes verirken barı kolların tam düzleşene kadar yukarı it. Not: Kasılmayı omuzlarının çevresinde hissetmelisin.', 'Bir saniye bekle, sonra nefes alarak barı başlangıç pozisyonuna indir.', 'Belirlenen tekrar sayısı kadar yap.', 'Bitirince barı yeniden askıya yerleştir.']::text[]),
  ('Smith_Machine_Behind_the_Back_Shrug', 'tr', array['Barı uyluk hizasına ayarla ve uygun ağırlığı yükle.', 'Bar arkanda kalacak şekilde dur, omuz genişliğinde üstten tutuşla kavra ve kancalardan çıkar. Dik dur; başın ve göğsün yukarıda, kolların düz olsun. Bu senin başlangıç pozisyonun.', 'Omuzlarını dümdüz yukarı çek. Hareket sırasında kollarını ve bileklerini bükme.', 'Kısa bir süre bekle ve ağırlığı başlangıç pozisyonuna indir.', 'İstediğin tekrar sayısını tamamla, sonra kancaları takıp ağırlığı yerine bırak.']::text[]),
  ('Smith_Machine_Bench_Press', 'tr', array['Smith makinesinin altına düz bir sehpa koy. Barı, uzandığında kolların neredeyse tam düzken yetişebileceğin yüksekliğe ayarla. Ağırlığını seçtikten sonra sehpaya uzan. Barı omuz genişliğinden geniş, üstten tutuşla kavra, kilidini aç ve kolların kilitli halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı göğsünün ortasında hissedene kadar yavaşça indir.', 'Bir saniye bekle, sonra nefes verirken göğüs kaslarınla barı başlangıç pozisyonuna it. Yukarıda kollarını kilitle, bir saniye bekle ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Belirlenen tekrar sayısı kadar yap.', 'Bitirince barı yeniden askıya kilitle.']::text[]),
  ('Smith_Machine_Bent_Over_Row', 'tr', array['Smith makinesinin barını dizlerinin yaklaşık 2 inç altına ayarla.', 'Dizlerini hafifçe bük, sırtını düz tutarak belden öne eğil; gövden yere neredeyse paralel olsun. İpucu: Başını yukarıda tut.', 'Barı üstten (pronasyon) tutuşla kavra ve makinenin askısından kurtar. Barı tam önünde sarkıt; düz kolların yere ve gövdene dik olsun. Bu senin başlangıç pozisyonun.', 'Gövdeni sabit tut, nefes verirken barı yukarı çek; dirseklerin gövdene yakın kalsın, ön kolların ağırlığı tutmaktan başka bir iş yapmasın. En üstte sırt kaslarını sık ve bir saniye bekle.', 'Nefes alırken ağırlığı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Calf_Raise', 'tr', array['Smith makinesinde barın altına bir blok ya da ağırlık plakası koy. Barı boyuna en uygun konuma ayarla. Yükseklik ayarlanıp bar yüklendikten sonra ayaklarının ön tabanıyla plakaların üzerine çık ve barı omuzlarının arkasına yerleştir.', 'Barı iki elinle, avuç içlerin öne bakacak şekilde tut. Barı çevirerek askıdan çıkar. Bu senin başlangıç pozisyonun.', 'Ayaklarının ön tabanından iterek topuklarını olabildiğince yükselt ve en üstte baldırını sık. Dizlerin düz kalsın. İnmeye başlamadan önce bu pozisyonda bir saniye bekle.', 'Nefes alırken topuklarını indirerek yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Close-Grip_Bench_Press', 'tr', array['Smith makinesinin altına düz bir sehpa koy. Barı, uzandığında kolların neredeyse tam düzken yetişebileceğin yüksekliğe ayarla. Ağırlığını seçtikten sonra sehpaya uzan. Barı yaklaşık omuz genişliğinde, dar ve üstten tutuşla (avuç içleri öne bakar) kavra, kilidini aç ve kolların kilitli halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı göğsünün ortasında hissedene kadar yavaşça indir. İpucu: Normal bench press''ten farklı olarak dirseklerini hep gövdene yakın tut; böylece triseps en fazla şekilde çalışır.', 'Bir saniye bekle, sonra nefes verirken triseps kaslarınla barı başlangıç pozisyonuna it. Yukarıda kollarını kilitle, bir saniye bekle ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Belirlenen tekrar sayısı kadar yap.', 'Bitirince barı yeniden askıya kilitle.']::text[]),
  ('Smith_Machine_Decline_Press', 'tr', array['Ters eğimli bir sehpayı, bar göğsünün üstüne gelecek şekilde rack''in içine yerleştir. Uygun ağırlığı yükle ve sehpaya uzan.', 'Barı çevirerek askıdan kurtar ve kollarını tam aç. Sırtın hafif kavisli, kürek kemiklerin geriye çekilmiş olsun. Bu senin başlangıç pozisyonun.', 'Kollarını bükerek barı göğsüne indir.', 'Kısa bir süre bekle, sonra kollarını açarak ağırlığı başlangıç pozisyonuna it.', 'İstediğin tekrar sayısını tamamlayınca barı çevirip askıya bırak.']::text[]),
  ('Smith_Machine_Hang_Power_Clean', 'tr', array['Barı diz hizasına ayarla ve uygun ağırlığı yükle.', 'Barı omuz genişliğinden geniş, üstten tutuşla kavra ve makineden çıkar. Kolların tam düz, başın ve göğsün yukarıda olsun. Dirseklerin dışa baksın, omuzların geride ve aşağıda dursun. Kalçanı geriye it; gerilim arka bacak kaslarına binsin. Bu senin başlangıç pozisyonun.', 'Kalçanı ve dizlerini güçlü bir şekilde açarak barı hızlandır. Hareketin bu bölümünde kollarını düz tut.', 'Tam açıldığında kalçanı ve dizlerini yeniden bükerek barı karşılayacağın pozisyonu alçalt.', 'Bu noktada kollarının bükülmesine izin ver; dirseklerini barın etrafında döndürüp barı omuzlarına al.', 'Kalçanı ve dizlerini açarak bar omuzlarında dururken ayağa kalk ve hareketi tamamla.']::text[]),
  ('Smith_Machine_Hip_Raise', 'tr', array['Rack''in içine bir sehpa yerleştir ve bara uygun ağırlığı yükle. Sehpaya uzan ve ayak tabanlarını bara daya. Barın kilidini aç ve bacaklarını uzat; gerekirse ellerinle yardım et. Daha sağlam durmak için Smith makinesinin yanlarından tutun. Bu senin başlangıç pozisyonun.', 'Leğen kemiğini döndür ve omurganı bükerek kalçanı sehpadan kaldır. Hareket boyunca dizlerin hafif bükülü kalsın.', 'Kısa bir süre bekle ve kalçanı sehpaya geri indir.', 'İstediğin tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Incline_Bench_Press', 'tr', array['Smith makinesinin altına eğimli bir sehpa koy. Barı, uzandığında kolların neredeyse tam düzken yetişebileceğin yüksekliğe ayarla. Ağırlığını seçtikten sonra sehpaya uzan ve üst göğsünün barla aynı hizada olduğundan emin ol. Barı omuz genişliğinden geniş, üstten tutuşla (avuç içleri öne bakar) kavra, kilidini aç ve kolların kilitli halde tam üstünde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı üst göğsünde hissedene kadar yavaşça indir.', 'Bir saniye bekle, sonra nefes verirken göğüs kaslarınla barı başlangıç pozisyonuna it. Yukarıda kollarını kilitle, bir saniye bekle ve yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Belirlenen tekrar sayısı kadar yap.', 'Bitirince barı yeniden askıya yerleştir.']::text[]),
  ('Smith_Machine_Leg_Press', 'tr', array['Smith makinesinin barını yerden birkaç feet yükseğe ayarla. Barın emniyet durdurucularına oturduğundan emin ol. Uygun ağırlığı yükledikten sonra barın altına uzan. Ayaklarının ortasını bara yerleştir ve dizlerini göğsüne çek. Bu senin başlangıç pozisyonun.', 'Ayaklarınla iterek barı yukarı taşı; kalçanı ve dizlerini aç. Dizlerini kilitleme.', 'Hareketin en üstünde kısa bir süre bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Smith_Machine_One-Arm_Upright_Row', 'tr', array['Barı uyluk hizasına ayarla ve uygun ağırlığı yükle.', 'Barı geniş tutuşla kavra, ağırlığı kancalardan çıkar ve çalışmayan elini bardan çek. Dik dur; kolun düz, başın ve göğsün yukarıda olsun. Bu senin başlangıç pozisyonun.', 'Dirseğini bük ve dirseğin dışa bakacak şekilde üst kolunu kaldır. Üst kolun yere paralel olana kadar devam et.', 'Kısa bir süre bekle ve ağırlığı başlangıç pozisyonuna indir.', 'İstediğin tekrar sayısını tamamla, sonra kancaları takıp ağırlığı yerine bırak.']::text[]),
  ('Smith_Machine_Overhead_Shoulder_Press', 'tr', array['Smith makinesinin altına düz bir sehpa, tercihen sırt destekli bir sehpa koy. Barı öyle bir yüksekliğe ayarla ki sehpada otururken ona yetişmek için kollarını neredeyse tam uzatman gereksin.', 'Yükseklik doğru olunca barın biraz gerisine otur; burnunun ucundan bara hayali düz bir çizgi uzansın. Ayakların sabit dursun. Barı avuç içlerin öne bakacak şekilde kavra, kilidini aç ve kolların tam düzleşene kadar yukarı kaldır. Bu başlangıç pozisyonu.', 'Nefes alırken barı çene hizasına gelene kadar yavaşça indir.', 'Sonra nefes verirken omuzlarınla barı başlangıç pozisyonuna it.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Pistol_Squat', 'tr', array['Önce barı boyuna en uygun konuma ayarla. Altına gir ve barı omuzlarının arkasına yerleştir.', 'Barı avuç içlerin öne bakacak şekilde tut, kilidini aç ve bacaklarını düzleştirerek askıdan kaldır.', 'Bir ayağını barın yaklaşık 12 inç önüne koy. Diğer bacağını öne uzat ve yerden yukarıda tut. Hep ileri bak, omurganı nötr ya da hafif kavisli tut. Bu senin başlangıç pozisyonun.', 'Duruşunu bozmadan dizini ve kalçanı bükerek alçal; esnekliğinin izin verdiği kadar in.', 'En altta kısa bir süre bekle, sonra topuğundan iterek dizini ve kalçanı aç ve başlangıç pozisyonuna dön.']::text[]),
  ('Smith_Machine_Reverse_Calf_Raises', 'tr', array['Smith makinesinin barını boyuna göre ayarla ve barın tam altına yükseltilmiş bir platform yerleştir.', 'Platforma çık; topukların üzerinde sağlamca dursun, ayaklarının ön tabanı platformdan dışarı taşsın. Ayak parmakların öne baksın, ayakların omuz genişliğinde olsun.', 'Ayaklarını bu konumda tutarak omuzlarını barın altına yerleştir, kalçanı ve dizlerini açarak gövden dikleşene kadar barı yukarı it. Dizlerin hafif bükülü kalsın, asla kilitlenmesin. Bu senin başlangıç pozisyonun. İpucu: Sırtındaki bar yalnızca denge içindir.', 'Nefes verirken ayaklarının ön tabanını kaldır; ayak parmaklarını olabildiğince yukarı çek ve baldırını sık. Dizlerin hep sabit kalsın, hiçbir an bükülmesin. İnmeye başlamadan önce bu pozisyonda bir saniye bekle.', 'Nefes alırken ayaklarının ön tabanını ve parmaklarını indirerek yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Squat', 'tr', array['Önce barı boyuna en uygun yüksekliğe ayarla. Yükseklik ayarlanıp bar yüklendikten sonra barın altına gir ve omuzlarının arkasını, boynunun biraz altını bara yasla.', 'Barı iki yanından, avuç içlerin öne bakacak şekilde tut, kilidini aç ve bacaklarınla iterken gövdeni de doğrultarak askıdan kaldır.', 'Ayaklarını omuz genişliğinde, orta açıklıkta yerleştir; ayak parmakların hafifçe dışa baksın. Başını hep yukarıda, sırtını düz tut. Bu senin başlangıç pozisyonun. Not: Burada bacakları bütün olarak geliştiren orta duruş anlatılıyor; ancak üç duruştan istediğini seçebilirsin.', 'Dizlerini bükerek barı yavaşça indir; duruşun dik, başın yukarıda kalsın. Uylukların ile baldırların arasındaki açı 90 derecenin biraz altına inene kadar devam et; bu noktada uyluklar yere paralelin altındadır. Hareketin bu bölümünde nefes al. İpucu: Hareketi doğru yaptıysan dizlerinin önü, ayak parmaklarınla öne dik, hayali bir düz çizgi oluşturur. Dizlerin bu çizgiyi, yani ayak parmaklarını geçiyorsa dizine gereksiz yük bindiriyorsun ve hareket yanlış yapılmış demektir.', 'Nefes verirken topuklarınla yeri iterek barı kaldır; bacaklarını yeniden düzleştir ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Stiff-Legged_Deadlift', 'tr', array['Smith makinesinin barını uyluklarının ortası hizasına ayarla. Yükseklik ayarlanıp bar yüklendikten sonra barı omuz genişliğinde, pronasyon tutuşuyla (avuç içleri öne) kavra. Ağırlık fazlaysa bilek bandına ihtiyacın olabilir.', 'Sırtını düz tutarak kollarını tam aç ve barı kaldır. Gövden dik, ayakların omuz genişliğinde ya da daha dar dursun. Dizlerin hafif bükülü olsun. Bu senin başlangıç pozisyonun.', 'Dizlerini sabit tut, sırtın düzken belden eğilerek barı ayaklarının üstüne doğru indir. Yerden bir şey alacakmış gibi, arka bacak kaslarında gerilme hissedene kadar eğilmeye devam et. Bunu yaparken nefes ver.', 'Arka bacak kaslarında gerilmeyi hisseder hissetmez kalçanı ve belini açarak gövdeni doğrult ve başlangıç pozisyonuna dön. Bunu yaparken nefes al.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Machine_Upright_Row', 'tr', array['Smith makinesinin barını uyluklarının ortası hizasına ayarla. Yükseklik ayarlanıp bar yüklendikten sonra barı omuz genişliğinde, pronasyon tutuşuyla (avuç içleri öne) kavra. Ağırlık fazlaysa bilek bandına ihtiyacın olabilir.', 'Barı kaldır ve sırtın düzken kollarını tam aç. Dirseklerin hafif bükülü olsun. Bu başlangıç pozisyonu.', 'Nefes verirken yan omuz kaslarınla barı kaldır. Bar yukarı çıkarken gövdene yakın olsun; neredeyse çenene değene kadar devam et. İpucu: Hareketi dirseklerin yönetsin; barı kaldırırken dirseklerin hep ön kollarından yüksekte olsun. Ayrıca gövdeni sabit tut ve hareketin en üstünde bir saniye bekle.', 'Barı yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes al.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Smith_Single-Leg_Split_Squat', 'tr', array['Smith makinesinin 2-3 feet arkasına düz bir sehpa koy. Barı boyuna en uygun yüksekliğe ayarla. Yükseklik ayarlanıp bara ağırlık takıldıktan sonra barın altına gir ve barı omuzlarının arkasına, ensenin biraz altına yerleştir.', 'Barı iki yanından, avuç içlerin öne bakacak şekilde tut, kilidini aç ve önce bacaklarınla iterek, aynı anda gövdeni doğrultarak askılıktan kaldır.', 'Bir ayağını barın altında hafifçe öne al, diğer bacağını geriye uzat ve ayağının üst kısmını sehpaya koy. Bu senin başlangıç pozisyonun.', 'Dizini bükerek barı yavaşça indir; gövden dik, başın yukarıda kalsın. Üst bacak ile baldır arasındaki açı 90 derecenin biraz altına düşene kadar in; bu noktada üst bacak yere paralel çizginin altındadır. Hareketin bu bölümünde nefes al. İpucu: Hareketi doğru yaptıysan dizinin ön yüzü ayak parmaklarınla, öne dik duran hayali bir düz çizgi oluşturur. Dizin bu çizgiyi geçiyorsa, yani ayak parmaklarının önüne çıkıyorsa, dizine gereksiz yük bindiriyorsun ve hareket yanlış yapılmış demektir.', 'Nefes verirken barı kaldırmaya başla: ağırlıklı olarak topuğunla yeri it, bacağını yeniden düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.', 'Bacak değiştir ve hareketi tekrarla.']::text[]),
  ('Snatch', 'tr', array['Ayaklarını omuz genişliğinde aç; halter, parmakların ayağın geri kalanıyla birleştiği yerin hemen üstünde dursun.', 'Dizlerini bük, sırtını düz tut ve barı avuç içlerin aşağı bakacak şekilde, omuz genişliğinden daha açık tut. Kalçanı indir ve gövdeni bir sandalyeye oturacakmış gibi alçalt. Bu senin başlangıç pozisyonun.', 'Zemin hareketli bir platformmuş gibi ayaklarınla yeri itmeye başla ve aynı anda halteri bacaklarına yakın tutarak kaldır.', 'Bar üst bacaklarının ortasına geldiğinde bacaklarınla yeri it ve patlayıcı bir hareketle vücudunu tamamen uzat.', 'Bar yükselirken omuzlarını silker gibi geriye ve yukarı çek; dirseklerini yanlara doğru kaldır ve olabildiğince uzun süre barın üstünde tut.', 'Halter kontrol edilebilecek kadar yükseldiğinde çok hızlı ama güçlü bir hareketle vücudunu onun altına sok: kollarını kilitleyip halteri başının üstünde tutarken squat pozisyonuna düş.', 'Squat pozisyonundan ayağa kalkarak kaldırışı tamamla. Sonunda iki ayak aynı hizada, kollar tamamen düz ve halter başının üstünde olmalı.']::text[]),
  ('Snatch_Balance', 'tr', array['Ayakların çekiş pozisyonunda, bar omuzlarının arkasında ve ellerin geniş koparma tutuşunda olacak şekilde başla.', 'Dizlerini aniden kısaca büküp iterek bara yukarı doğru bir ivme ver ve sert bir şekilde barın altına gir; bu sırada ayaklarını karşılama pozisyonuna geçir.', 'Barı squatın en alt noktasına yakın bir yerde, kolların başının üstünde kilitli olarak karşıla. Gövden dik kalsın, kalçan bacaklarının arasına insin.', 'Tam derinliğe kadar inmeye devam et, sonra ayağa kalk. Ağırlığı dikkatlice indir.']::text[]),
  ('Snatch_Deadlift', 'tr', array['Bu hareket koparmanın ilk çekişini güçlendirir. Halter platformda dururken geniş koparma tutuşuyla tut. Ayakların tam kalçanın altında, parmak uçların dışa dönük olsun. Sırtını tamamen düz, başını öne bakar halde tutarak bara doğru çömel.', 'Topuklarından iterek ve kalçanı yükselterek harekete başla. Bar dizlerini geçene kadar sırt açın aynı kalsın.', 'Bu noktada kalçanı bara doğru öne it ve geriye yaslan. Hareketi tersine çevirerek barı platforma geri bırak.']::text[]),
  ('Snatch_Pull', 'tr', array['Halter yerde, kaval kemiklerine yakın dururken geniş koparma tutuşuyla tut. Kalçanı indir; ağırlığın topuklarında, sırtın düz, başın öne bakar, göğsün yukarıda ve omuzların barın hemen önünde olsun. Bu senin başlangıç pozisyonun.', 'Topuklarından iterek ve dizlerini açarak ilk çekişe başla. Sırt açın aynı kalsın, kolların düz dursun. Ağırlığı kontrollü şekilde dizlerinin üstüne kadar taşı.', 'Sırada ikinci çekiş var; çekişteki ivmenin asıl kaynağı budur. Bar üst bacağın ortasına yaklaşırken kalçanı açmaya başla. Zıplar gibi bir hareketle kalça, diz ve ayak bileklerini açarak hızlan ve barı hızın yardımıyla yukarı gönder.', 'Ağırlığı hızlandırmak için kollarınla ayrıca çekmene gerek olmamalı; ikinci çekişin sonunda vücut tamamen uzamış ve hafifçe geriye yaslanmış olur. Tam uzanma sert ve ani olmalı; onu gereğinden uzun tutma.']::text[]),
  ('Snatch_Shrug', 'tr', array['Barı geniş tut ve üst bacağın ortası hizasında sarkıt. Kanca tutuş ya da üstten tutuş kullanabilirsin. Sırtın düz ve hafifçe öne eğik olsun.', 'Omuzlarını kulaklarına doğru silk. Bu harekete genellikle koparmadan daha fazla ağırlık takılabilir, ama hareketi yavaşlatacak kadar fazla yükleme.']::text[]),
  ('Snatch_from_Blocks', 'tr', array['Ağırlık takılı halteri istediğin yükseklikteki kasaların ya da sehpaların üzerine koy. Barı geniş tut. Ayakların tam kalçanın altında, parmak uçların gerektiği kadar dışa dönük olsun. Kalçanı indir, göğsünü kaldır ve ileri bak. Omuzların barın hemen önünde, dirseklerin dışa dönük dursun. Bu başlangıç pozisyonu.', 'Topuklarının ön kısmından iterek ilk çekişe başla ve barı kasalardan kaldır.', 'Kalça, diz ve ayak bileklerini açarak ikinci çekişe geç ve barı olabildiğince hızlı yukarı sür. Bar vücuduna yakın kalsın. Uzanmanın en üst noktasında omuzlarını silk ve dirseklerinin yanlara doğru bükülmesine izin ver.', 'Ayaklarını karşılama pozisyonuna alırken kendini güçlü bir şekilde barın altına çek ve barı başının üstüne çıkar. Ayakların kalçanın hemen dışına, gerektiği kadar dışa dönük şekilde gelsin. Barı vücudun olabildiğince alçakta, kolların başının üstünde tamamen düz olarak karşıla.', 'Barı topuklarının ön kısmının hizasında, başını ve göğsünü yukarıda tut; topuklarından iterek ayağa kalk. Ağırlığı dikkatlice kasalara geri koy.']::text[]),
  ('Speed_Band_Overhead_Triceps', 'tr', array['Bu hareket için bir lastik bandı yere sabitle. Örneğin bandı eğimli bir sehpanın tabanına bağlayıp sehpanın üzerinde ayakta durabilirsin. Bunun yerine bandın üstüne basarak da yapabilirsin.', 'Başlamak için bandı başının arkasına çek; üstten tutuşla tut ve dirseklerin yukarı baksın. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak kollarını düzelt; bunu yaparken üst kolların yerinden oynamasın.', 'Kısa bir an bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Speed_Box_Squat', 'tr', array['Yere yakın bir noktaya sağlamca sabitlenmiş lastik bantları bara tak. Yeterli gerginlik için bantları boğarak bağlaman gerekebilir.', 'Bu hareket için uygun yükseklikte bir kasa kullan. Bara, hâlâ çaba gerektiren ama hızını düşürmeyecek kadar ağırlık tak. Bu genellikle tek tekrar maksimumunun %50-70''i arasındadır.', 'Barı sırtının üst kısmına yerleştir, kürek kemiklerini birbirine yaklaştır, sırtını kavislendir ve baştan ayağa her yerini sık. Bu başlangıç pozisyonu.', 'Barı askılıktan al ve kasanın önünde yerini al. Kasaya oturana kadar kalçanı geriye götür; kontrollü in ve kasanın üstüne çökme.', 'Kısa bir an bekle, sonra kalça ve dizlerini açarak kasadan patlayıcı şekilde kalk.']::text[]),
  ('Speed_Squats', 'tr', array['Güvenlik için bu hareketi squat kafesinin içinde yapmak en iyisidir. Önce barı boyuna en uygun askılığa yerleştir. Yükseklik ayarlanıp bara ağırlık takıldıktan sonra barın altına gir ve barı omuzlarının arkasına, ensenin biraz altına yerleştir.', 'Barı iki yanından tut ve önce bacaklarınla iterek, aynı anda gövdeni doğrultarak askılıktan kaldır.', 'Askılıktan uzaklaş ve ayaklarını omuz genişliğinde, orta açıklıkta yerleştir; parmak uçların hafifçe dışa baksın. Başını her zaman yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Bu senin başlangıç pozisyonun. Not: Burada genel gelişimi hedefleyen orta duruş kullanılıyor; ama üç duruştan istediğini seçebilirsin.', 'Dizlerini bükerek barı indir; gövden dik, başın yukarıda kalsın. Üst bacaklar ile baldırlar arasındaki açı 90 derecenin biraz altına düşene kadar in; bu noktada üst bacaklar yere paralel çizginin altındadır. Hareketin bu bölümünde nefes al. İpucu: Hareketi doğru yaptıysan dizlerinin ön yüzü ayak parmaklarınla, öne dik duran hayali bir düz çizgi oluşturur. Dizlerin bu çizgiyi geçiyorsa, yani ayak parmaklarının önüne çıkıyorsa, dizine gereksiz yük bindiriyorsun ve hareket yanlış yapılmış demektir.', 'Nefes verirken barı ivmeden yararlanmadan olabildiğince hızlı kaldır: ağırlıklı olarak topuklarınla yeri it, bacaklarını yeniden düzelt ve başlangıç pozisyonuna dön. Not: Bu hareketi olabildiğince hızlı yap, ama kusursuz formu bozmadan ve ivme kullanmadan.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Spell_Caster', 'tr', array['Her eline üstten tutuşla birer dambıl al. Ayakların geniş açık, kalça ve dizlerin düz olsun. Bu senin başlangıç pozisyonun.', 'Harekete, gövdeni döndürerek iki dambılı da bir yana, kalçanın yanına çekerek başla.', 'Kollarını düz, dambılları yere paralel tut; gövdeni döndürerek ağırlıkları karşı yana savur.', 'Set bitene kadar bir yandan öbür yana dönerek sırayla devam et.']::text[]),
  ('Spider_Crawl', 'tr', array['Yerde yüzüstü pozisyonda başla. Ağırlığını ellerinle ayak parmaklarına ver; ayakların bitişik, vücudun düz olsun. Kolların 90 derece bükülü dursun. Bu senin başlangıç pozisyonun.', 'Bir ayağını yerden kaldırarak harekete başla. Bacağını dışa döndür ve dizini olabildiğince ileriye, dirseğine doğru getir.', 'Bu bacağı başlangıç pozisyonuna geri al ve aynısını karşı tarafta yap.']::text[]),
  ('Spider_Curl', 'tr', array['Önce barı Scott sehpasının normalde oturduğun kısmına koy. Barı dengede duracak ve düşmeyecek şekilde düzgün hizala.', 'Scott sehpasının ön tarafına, yani kolların normalde yaslandığı kısma geç ve 45 derece eğimle uzan; gövden ve karnın sehpanın ön yüzüne yaslansın.', 'Ayaklarının, özellikle de parmak uçlarının yere sağlam bastığından emin ol ve üst kollarını Scott sehpasının iç tarafındaki yastığın üstüne koy.', 'Barı alttan tutuşla, avuç içlerin yukarı bakacak şekilde, ellerin yaklaşık omuz genişliğinde ya da biraz daha dar olacak biçimde kavra.', 'Nefes vererek barı yavaşça yukarı kaldır. Bisepsini sıkarak kasılı pozisyonda bir saniye bekle.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Spinal_Stretch', 'tr', array['Bir sandalyeye sırtın dik, ayakların yere sağlam basacak şekilde otur.', 'Parmaklarını başının arkasında kenetle; dirseklerin dışa baksın, çenen aşağıda olsun.', 'Üst gövdeni gidebildiğin kadar bir yana doğru yaklaşık 3 kez çevir. Sonra öne eğil ve gövdeni döndürerek dirseğini dizinin iç tarafından yere doğru uzat.', 'Dik pozisyona dön ve aynısını diğer taraf için yap.']::text[]),
  ('Split_Clean', 'tr', array['Halter yerde, kaval kemiklerine yakın dururken barı bacaklarının hemen dışından üstten tutuşla kavra. Kalçanı indir; ağırlığın topuklarında, sırtın düz, başın öne bakar, göğsün yukarıda ve omuzların barın hemen önünde olsun. Bu senin başlangıç pozisyonun.', 'Topuklarından iterek ve dizlerini açarak ilk çekişe başla. Sırt açın aynı kalsın, kolların düz dursun. Ağırlığı kontrollü şekilde dizlerinin üstüne kadar taşı.', 'Sırada ikinci çekiş var; omuzlamadaki ivmenin asıl kaynağı budur. Bar üst bacağın ortasına yaklaşırken kalçanı açmaya başla. Zıplar gibi bir hareketle kalça, diz ve ayak bileklerini açarak hızlan ve barı hızın yardımıyla yukarı gönder. Ağırlığı hızlandırmak için kollarınla ayrıca çekmene gerek olmamalı; ikinci çekişin sonunda vücut tamamen uzamış, hafifçe geriye yaslanmış ve kollar hâlâ düz olur.', 'Tam uzanmaya ulaşınca üçüncü çekişe geç: omuzlarını sertçe silk ve dirseklerin yukarı ve dışa bakacak şekilde kollarını bük. Uzanmanın en üst noktasında kendini sertçe aşağı çek ve bunu yaparken dirseklerini barın altına döndür.', 'Barı ayakların öne arkaya açılmış halde karşıla; bir ayağını sertçe öne, diğerini geriye at. Bar öne doğru itilmiş omuzlarına otursun, boğazına hafifçe değsin; ellerin gevşek kalsın. En alt pozisyona kadar inmeye devam et; bu, kalkışa yardımcı olur.', 'Hemen topuklarından iterek kalk; gövden dik, dirseklerin yukarıda kalsın. Ayağa kalkarken ayaklarını birleştir.']::text[]),
  ('Split_Jerk', 'tr', array['Ağırlık omuzlarının ön kısmında dururken ayakta başla ve ilk iş hafifçe çök. Ayakların tam kalçanın altındayken dizlerini kalçanı geriye götürmeden bük.', 'Yalnızca biraz in ve yönü olabildiğince güçlü şekilde tersine çevir. Olabildiğince fazla hız ve kuvvet üretmek için topuklarından it; bar omuzlarından ayrılırken başını yolundan çekmeyi unutma. Ayaklar yerden kesildiği anda olabildiğince çabuk karşılama pozisyonuna yerleştirilmeli.', 'Ayakların platforma aktif olarak basmadığı o kısa anda, barı yukarı itme çaban seni aşağı iter. Ayaklarını öne arkaya açık duruşa getir: biri önde, biri arkada, dizler kısmen bükülü. Barı kolların başının üstünde kilitli olarak karşıla.', 'Ayaklarını birleştirerek ayakta duruşa dön.']::text[]),
  ('Split_Jump', 'tr', array['Lunge duruşuna geç: bir ayağın önde ve dizi bükülü, arka dizin neredeyse yere değiyor olsun.', 'Öndeki dizinin ayağın orta çizgisinin üzerinde olduğundan emin ol.', 'İki bacağını da açarak olabildiğince yükseğe zıpla; yükselmek için kollarını savur.', 'Zıplarken ayaklarını birleştir, yere inerken de onları ilk konumlarına geri götür.', 'Başlangıç pozisyonuna geri inerek darbeyi yumuşat.']::text[]),
  ('Split_Snatch', 'tr', array['Ağırlık takılı halter yerdeyken başla. Bar kaval kemiklerine yakın ya da değiyor olsun; barı geniş tut. Ayakların tam kalçanın altında, parmak uçların gerektiği kadar dışa dönük olsun. Kalçanı indir, göğsünü kaldır ve ileri bak. Omuzların barın hemen önünde dursun. Bu başlangıç pozisyonu.', 'Topuklarının ön kısmından iterek ilk çekişe başla ve barı yerden kaldır. Bar dizlerini geçene kadar sırt açın aynı kalsın.', 'Kalça, diz ve ayak bileklerini açarak ikinci çekişe geç ve barı olabildiğince hızlı yukarı sür. Bar vücuduna yakın kalsın. Uzanmanın en üst noktasında omuzlarını silk ve dirseklerinin yanlara doğru bükülmesine izin ver.', 'Ayaklarını karşılama pozisyonuna alırken kendini güçlü bir şekilde barın altına çek ve barı başının üstüne çıkar. Ayaklarını sertçe öne arkaya aç: biri önde, biri arkada. Barı vücudun olabildiğince alçakta, kolların başının üstünde tamamen düz olarak karşıla.', 'Barı topuklarının ön kısmının hizasında, başını ve göğsünü yukarıda tut; topuklarından iterek ayağa kalk ve ayaklarını birleştir.', 'Ağırlığı dikkatlice yere geri bırak.']::text[]),
  ('Split_Squat_with_Dumbbells', 'tr', array['Arka ayağın yükseltilmiş, ön ayağın ileride olacak şekilde öne arkaya açık bir duruş al.', 'Her eline birer dambıl al ve yanlarında sarkıt. Bu senin başlangıç pozisyonun.', 'Diz ve kalçanı bükerek vücudunu indirmeye başla. Hareket boyunca düzgün duruşunu koru. Hareketi yaparken öndeki dizin ayağınla aynı hizada kalsın.', 'Hareketin en altında topuğundan it, diz ve kalçanı açarak başlangıç pozisyonuna dön.']::text[]),
  ('Split_Squats', 'tr', array['Ayakta başla. Bir bacak önde, bir bacak arkada olacak şekilde zıplayarak bacaklarını aç; bunu yaparken dizlerini bük ve kalçanı hafifçe indir.', 'İnerken hemen yön değiştir: yeniden doğrul, zıpla ve bacaklarının yerini değiştir. Her bacakta 5-10 kez tekrarla.']::text[]),
  ('Squat_Jerk', 'tr', array['Ağırlık omuzlarının ön kısmında dururken ayakta başla ve ilk iş hafifçe çök. Ayakların tam kalçanın altındayken dizlerini kalçanı geriye götürmeden bük. Yalnızca biraz in ve yönü olabildiğince güçlü şekilde tersine çevir. Olabildiğince fazla hız ve kuvvet üretmek için topuklarından it; bar omuzlarından ayrılırken başını yolundan çekmeyi unutma.', 'Ayaklar yerden kesildiği anda olabildiğince çabuk karşılama pozisyonuna yerleştirilmeli. Ayakların platforma aktif olarak basmadığı o kısa anda, barı yukarı itme çaban seni aşağı iter. Ayaklarını sertçe kalçanın hemen dışına, gerektiği kadar dışa dönük şekilde götür. Barı tam squat pozisyonunda, kolların başının üstünde tamamen düz olarak karşıla.', 'Barı topuklarının ön kısmının hizasında, başını ve göğsünü yukarıda tut; topuklarından iterek ayağa kalk. Ağırlığı dikkatlice yere geri bırak.']::text[]),
  ('Squat_with_Bands', 'tr', array['Lastik bantları barın plaka takılan uçlarına geçir ve uygun gerginlik oluşacak şekilde bant pimlerine, kafese ya da dambıllara sabitle.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sık ve barı omuzlarının üzerinde bükmeye çalışır gibi dirseklerini öne döndür. Belinde sıkı bir kavis oluşturarak barı askılıktan al ve geri adım atıp yerini al. Sırt, kalça, addüktörler ve arka bacağa daha fazla yük vermek için ayaklarını geniş aç. Başın öne baksın.', 'Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışarı iterek inmeye başla. Kalçanla olabildiğince geriye otur. İdeal olarak kaval kemiklerin yere dik durmalı. Bar sırtta ne kadar aşağıda durursa, barı topukların üstünde tutmak için gövdenin o kadar öne eğilmesi gerekir. Paralelin altına inene kadar devam et; yani kalça kıvrımı dizin üst kısmıyla aynı hizaya gelene kadar.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve hareketi başınla yönlendirerek yukarı doğru it. Baştan ayağa sıkı kalarak başlangıç pozisyonuna dönene kadar yükselmeye devam et.']::text[]),
  ('Squat_with_Chains', 'tr', array['Zincirleri kurmak için önce taşıyıcı zinciri barın plaka takılan uçlarına halka yaparak geçir. Ağır zinciri bir karabinayla tak. Taşıyıcı zincirin boyunu, hareketin en üst noktasında birkaç halka hâlâ yerde kalacak şekilde ayarla.', 'Barın altına gir ve barı omuzlarının arkasına yerleştir. Kürek kemiklerini birbirine sık ve barı omuzlarının üzerinde bükmeye çalışır gibi dirseklerini öne döndür. Belinde sıkı bir kavis oluşturarak barı askılıktan al ve geri adım atıp yerini al. Sırt, kalça, addüktörler ve arka bacağa daha fazla yük vermek için ayaklarını geniş aç. Başın öne baksın.', 'Sırtın, omuzların ve gövden sıkıyken dizlerini ve kalçanı dışarı iterek inmeye başla. Kalçanla olabildiğince geriye otur. İdeal olarak kaval kemiklerin yere dik durmalı. Bar sırtta ne kadar aşağıda durursa, barı topukların üstünde tutmak için gövdenin o kadar öne eğilmesi gerekir. Paralelin altına inene kadar devam et; yani kalça kıvrımı dizin üst kısmıyla aynı hizaya gelene kadar.', 'Ağırlığı topuklarında tut, ayaklarını ve dizlerini dışa it ve hareketi başınla yönlendirerek yukarı doğru it. Baştan ayağa sıkı kalarak başlangıç pozisyonuna dönene kadar yükselmeye devam et.']::text[]),
  ('Squat_with_Plate_Movers', 'tr', array['Önce barı askılıkta omuz hizasının hemen altına yerleştir. Askılığın birkaç feet gerisine, yere bir ağırlık plakası koy. Bara ağırlık takıldıktan sonra altına gir ve barı omuzlarının arkasına yerleştir.', 'Barı iki elinle tut ve önce bacaklarınla iterek, aynı anda gövdeni doğrultarak askılıktan kaldır.', 'Askılıktan uzaklaş ve geniş bir duruş al; parmak uçların hafifçe dışa baksın, bir ayağın ağırlık plakasının üstünde olsun. Başını her zaman yukarıda tut. Bu senin başlangıç pozisyonun.', 'Dizlerini ve kalçanı bükerek barı yavaşça indir. Üst bacaklar ile baldırlar arasındaki açı 90 derecenin biraz altına düşene kadar in.', 'Nefes verirken topuklarınla yeri iterek, kalça ve dizlerini açarak barı kaldır.', 'Hareketin en üstünde yana adım at ve ayaklarını plakanın öbür tarafında birleştir.', 'İçte kalan ayağınla ağırlık plakasını it ve az önce durduğun yere doğru zeminde kaydır.', 'İçte kalan ayağını plakanın üstüne koy ve bir sonraki tekrar için geniş duruş al.']::text[]),
  ('Squats_-_With_Bands', 'tr', array['Başlarken lastik bandın vücudunun sol ve sağ tarafına eşit dağıldığından emin ol. Bunun için bandın iki ucunu ellerinle tut ve iki ayağınla bandın ortasına bas. Ayakların omuz genişliğinde açık olsun.', 'Bandı tutarken iki taraf da aynı yükseklikte olsun. Üstten tutuş kullan, avuç içlerin öne baksın ve bandın tutamakları yüzünün yanında dursun. Bu başlangıç pozisyonu.', 'Nefes verirken dizlerini yavaşça bük ve üst bacakların yere paralel olana kadar alçal.', 'Nefes verirken topuklarınla iterek vücudunu başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Stairmaster', 'tr', array['Başlamak için merdiven makinesine çık ve menüden istediğin seçeneği seç. Elle ayar yapabilir ya da bir program çalıştırabilirsin. Genellikle egzersizde yakılan kalorinin tahmin edilmesi için yaşını ve kilonu girebilirsin.', 'Bacaklarını düzenli bir ritimle aşağı yukarı çalıştır; pedalları aşağı bastır ama yere kadar indirme. Düşmemek için tutamakları bırakmaman önerilir. Tutamaklar nabzını izlemek için de kullanılabilir; bu, uygun yoğunlukta kalmana yardımcı olur.', 'Merdiven makineleri pratiktir, kalp ve dolaşım sistemine faydalıdır ve genellikle dışarıda koşmaktan daha az darbe yaratır. Çoğunlukla diğer kardiyo aletlerinden çok daha zorludur. 150 lb ağırlığındaki bir kişi 30 dakikada genellikle 300 kaloriden fazla yakar; yürürken bu yaklaşık 175 kaloridir.']::text[]),
  ('Standing_Alternating_Dumbbell_Press', 'tr', array['Her elinde birer dambılla ayakta dur. Dambılları omuzlarına kaldır; avuç içlerin öne, dirseklerin dışa baksın. Bu senin başlangıç pozisyonun.', 'Bir kolunu açarak dambılı dümdüz yukarı it; diğer elin yerinde kalsın. Hareket sırasında yana eğilme ve ağırlığı silkeleyerek kaldırma.', 'Kısa bir an bekledikten sonra ağırlığı başlangıç pozisyonuna indir.', 'Aynısını karşı tarafta yap ve kolları sırayla değiştirerek devam et.']::text[]),
  ('Standing_Barbell_Calf_Raise', 'tr', array['Güvenlik için bu hareketi squat kafesinin içinde yapmak en iyisidir. Önce barı boyuna en uygun askılığa yerleştir. Yükseklik ayarlanıp bara ağırlık takıldıktan sonra barın altına gir ve barı omuzlarının arkasına, ensenin biraz altına koy.', 'Barı iki yanından tut ve önce bacaklarınla iterek, aynı anda gövdeni doğrultarak askılıktan kaldır.', 'Askılıktan uzaklaş ve ayaklarını omuz genişliğinde, orta açıklıkta yerleştir; parmak uçların hafifçe dışa baksın. Başını her zaman yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Dizlerin hafifçe bükülü kalsın, asla kilitlenmesin. Bu senin başlangıç pozisyonun. İpucu: Daha geniş bir hareket açıklığı için ayaklarının ön tabanını tahta bir bloğun üstüne de koyabilirsin; ama dikkatli ol, çünkü bu seçenek daha fazla denge ve sağlam bir blok gerektirir.', 'Nefes verirken ayak bileklerini olabildiğince yukarı doğru açıp baldırını kasarak topuklarını kaldır. Dizin her zaman sabit kalsın; hiçbir anda bükülmesin. Aşağı inmeye başlamadan önce kasılı pozisyonda bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön: topuklarını indir ve baldırların gerilene kadar ayak bileklerini bük.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Barbell_Press_Behind_Neck', 'tr', array['Barı daha kolay almak için bu hareketi squat kafesinin içinde yapmak en iyisidir. Önce barı boyuna en uygun askılığa yerleştir. Yükseklik ayarlanıp bara ağırlık takıldıktan sonra barın altına gir ve barı omuzlarının arkasına, ensenin biraz altına yerleştir.', 'Barı iki yanından tut ve önce bacaklarınla iterek, aynı anda gövdeni doğrultarak askılıktan kaldır.', 'Askılıktan uzaklaş ve ayaklarını omuz genişliğinde, orta açıklıkta yerleştir; parmak uçların hafifçe dışa baksın. Bu hareketi yaparken sırtın düz kalsın. Bu senin başlangıç pozisyonun.', 'Nefes verirken kollarını tamamen açarak halteri başının üstüne kaldır.', 'Kasılmayı bir saniye tut, sonra nefes alarak halteri başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'tr', array['Bir eline dambıl al, avuç için gövdene baksın. Dizlerini hafifçe bük ve belden öne eğil; sırtın düz kalsın, gövden yere neredeyse paralel olsun. Başını yukarıda tut.', 'Üst kolunu gövdene yakın ve yere paralel tut. Ön kolun, elindeki ağırlıkla birlikte yere doğru sarksın. İpucu: Ön kol ile üst kol arasında 90 derecelik açı olmalı. Bu senin başlangıç pozisyonun.', 'Üst kolunu sabit tut ve nefes verirken ağırlığı triseps kasınla kaldır; ön kolun yere paralel olana ve kolun tamamen uzayana kadar devam et. Birçok kol hareketinde olduğu gibi yalnızca ön kol hareket eder.', 'Tepede bir saniye kasılı kal, sonra nefes alarak dambılı yavaşça başlangıç pozisyonuna indir.', 'Programındaki tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'tr', array['İki eline birer dambıl al, avuç içlerin gövdene baksın. Dizlerini hafifçe bük ve belden öne eğil; sırtın düz kalsın, gövden yere neredeyse paralel olsun. Başını yukarıda tut. Üst kollarını gövdene yakın ve yere paralel tut. Ön kolların, ellerindeki ağırlıklarla birlikte yere doğru sarksın. İpucu: Ön kollar ile üst kollar arasında 90 derecelik açı olmalı. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut ve nefes verirken ağırlıkları triseps kaslarınla kaldır; ön kolların yere paralel olana ve kolların tamamen uzayana kadar devam et. Birçok kol hareketinde olduğu gibi yalnızca ön kollar hareket eder.', 'Tepede bir saniye kasılı kal, sonra nefes alarak dambılları yavaşça başlangıç pozisyonuna indir.', 'Programındaki tekrar sayısı kadar yap.']::text[]),
  ('Standing_Biceps_Cable_Curl', 'tr', array['Alt makaraya bir curl barı tak ve gövden dik olacak şekilde ayakta dur. Barı omuz genişliğinde tut, dirseklerini gövdene yakın tut, avuç içlerin yukarı baksın (supine tutuş). Bu senin başlangıç pozisyonun.', 'Nefes verirken biseps kaslarını sıkarak barı yukarı bük; üst kolların sabit kalsın, yalnızca ön kolların hareket etsin. Biseps tamamen kasılana ve bar omuz hizasına gelene kadar devam et. Orada bir saniye dur ve kası iyice sık.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna geri getir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Biceps_Stretch', 'tr', array['Ellerini sırtının arkasında, avuçların birbirine değecek şekilde kenetle. Kollarını düzleştir, sonra avuç içlerin aşağı bakacak şekilde çevir.', 'Kollarını yukarı kaldır ve biseps kaslarında gerilme hissedince orada bekle.']::text[]),
  ('Standing_Bradford_Press', 'tr', array['Ağırlık takılı barı sehpaya omuz hizasında yerleştir. Barı omuz genişliğinde, üstten (prone) tutuşla kavra ve omuzlarının ön kısmına yasla. Bu senin başlangıç pozisyonun.', 'Dirseklerini açarak barı başının üstüne it ve harekete başla. Ağırlığı başının arkasına geçirirken dirseklerini kilitleme.', 'Barı başının arkasından, dirseklerin dik açı yapana kadar indir.', 'Dirseklerini açarak barı yeniden başının üstüne kaldır.', 'Barı önden başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısını tamamlayana kadar bu şekilde ön ve arka arasında değiş.']::text[]),
  ('Standing_Cable_Chest_Press', 'tr', array['İki makarayı göğüs hizasına ayarla ve uygun bir ağırlık seç. Her eline bir tutamak al ve kabloların bir iki fit önünde dur. Daha sağlam durmak için bir ayağını öne alabilirsin.', 'Üst kollarını 90 derecelik açıya getir ve kürek kemiklerini birbirine yaklaştır. Bu senin başlangıç pozisyonun.', 'Vücudunun geri kalanını sabit tut, dirseklerini açarak tutamakları öne it ve önünde birleştir.', 'Hareketin sonunda kısa bir an dur ve başlangıç pozisyonuna dön.']::text[]),
  ('Standing_Cable_Lift', 'tr', array['Kablo kulesine standart bir tutamak tak ve makarayı en alt konuma getir.', 'Kabloya yan dön, tutamağı tek elinle kavra ve kuleden uzaklaş. Makaradan yaklaşık bir kol boyu uzakta dur; ağırlık kabloyu germiş olsun. Uzattığın kol kabloyla aynı hizada olmalı.', 'Ayaklarını omuz genişliğinde aç, çömel ve tutamağı iki elinle kavra. Kolların hâlâ tamamen düz olsun.', 'Tutamağı tek bir hareketle yukarı ve gövdenin çaprazına doğru çek; kolların başının üstünde tamamen uzayana kadar devam et.', 'Sırtını düz, kollarını vücuduna yakın tut. Tam hareket açıklığı için arka ayağının üzerinde dön ve bacaklarını düzleştir.', 'Önce kollarını, sonra gövdeni geri al. Nötr pozisyona yavaş ve kontrollü dön.', 'Tükenene kadar tekrarla.', 'Sonra yerini değiştir ve aynı hareket dizisini diğer tarafta yap.']::text[]),
  ('Standing_Cable_Wood_Chop', 'tr', array['Kablo kulesine standart bir tutamak tak ve makarayı en üst konuma getir.', 'Kabloya yan dön, tutamağı tek elinle kavra ve kuleden uzaklaş. Makaradan yaklaşık bir kol boyu uzakta dur; ağırlık kabloyu germiş olsun. Uzattığın kol kabloyla aynı hizada olmalı.', 'Ayaklarını omuz genişliğinde aç, diğer elinle yukarı uzan ve tutamağı iki elinle kavra. Kolların hâlâ tamamen düz olsun.', 'Tutamağı tek bir hareketle aşağı ve gövdenin çaprazına, öndeki dizine doğru çek; bu sırada gövdeni döndür.', 'Sırtını ve kollarını düz, karın bölgeni sıkı tut. Tam hareket açıklığı için arka ayağının üzerinde dön ve dizlerini bük.', 'Duruşunu bozma, kolların düz kalsın. Nötr pozisyona yavaş ve kontrollü dön.', 'Tükenene kadar tekrarla.', 'Sonra yerini değiştir ve aynı hareket dizisini diğer tarafta yap.']::text[]),
  ('Standing_Calf_Raises', 'tr', array['Baldır makinesinin yastıklı kolunu boyuna göre ayarla.', 'Omuzlarını yastıkların altına yerleştir ve ayak parmaklarını öne çevir (ya da diğer iki ayak pozisyonundan birini seç). Ayaklarının ön tabanı baldır basamağının üstünde sağlam dursun, topukların dışarı taşsın. Kalçanı ve dizlerini açarak kolu yukarı it ve gövdeni dik konuma getir. Dizlerin hafif bükük kalsın, asla kilitlenmesin. Ayak parmakların öne, dışa ya da içe bakabilir. Bu senin başlangıç pozisyonun.', 'Nefes verirken ayak bileklerini açıp baldırlarını sıkarak topuklarını olabildiğince yükselt. Dizlerin hep sabit kalsın, hiçbir anda bükülmesin. İnmeye başlamadan önce tepede bir saniye bekle.', 'Nefes alırken yavaşça başlangıç pozisyonuna dön: ayak bileklerini bükerek topuklarını baldırların gerilene kadar indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Concentration_Curl', 'tr', array['Çalışacak eline bir dambıl al ve öne eğil. Çalışan kolun yere dik sarksın, dirseğin dışarı baksın. Bu senin başlangıç pozisyonun.', 'Üst kolunu sabit tutarak dirseğini bük ve ağırlığı yukarı kaldır. Tekrarın tepesinde bisepsini sık ve kısa bir an bekle.', 'Dambılı başlangıç pozisyonuna geri indir.', 'Programındaki tekrar sayısı kadar yap.']::text[]),
  ('Standing_Dumbbell_Calf_Raise', 'tr', array['Gövden dik dur, iki dambılı yanlarında tut. Ayaklarının ön tabanını sağlam ve sabit bir tahta bloğun (yaklaşık 2-3 inç yüksekliğinde) üstüne koy; topukların dışarıda kalsın ve yere değsin. Bu senin başlangıç pozisyonun.', 'Ayak parmakların düz (tüm bölümleri eşit çalıştırmak için), içe (dış başı vurgulamak için) ya da dışa (iç başı vurgulamak için) baksın. Nefes verirken baldırlarını kasarak topuklarını yerden kaldır. Tepedeki kasılmayı bir saniye tut.', 'Nefes alırken topuklarını yavaşça indirerek başlangıç pozisyonuna dön.', 'Önerilen sayıda tekrarla.']::text[]),
  ('Standing_Dumbbell_Press', 'tr', array['Ayaklarını omuz genişliğinde açarak ayakta dur ve her eline bir dambıl al. Dambılları baş hizasına kaldır; dirseklerin yana açık ve yaklaşık 90 derece bükülü olsun. Bu senin başlangıç pozisyonun.', 'Tekniği bozma: bacaklardan güç alma, geriye yaslanma. Dirseklerini açarak ağırlıkları yukarı it ve tam başının üstünde birleştir.', 'Kısa bir an dur ve ağırlıkları yavaşça başlangıç pozisyonuna indir.']::text[]),
  ('Standing_Dumbbell_Reverse_Curl', 'tr', array['Dik dur ve her eline bir dambılı prone tutuşla (avuç içleri aşağı bakacak şekilde) al. Kolların tamamen düz, ayakların omuz genişliğinde açık olsun. Bu başlangıç pozisyonu.', 'Nefes verirken biseps kaslarını sıkarak ağırlıkları yukarı bük; üst kolların sabit kalsın, yalnızca ön kolların hareket etsin. Biseps tamamen kasılana ve dambıllar omuz hizasına gelene kadar devam et. Orada bir saniye dur ve kası iyice sık.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna geri getir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'tr', array['Dambılları uyluklarının önünde tut, avuç içlerin uyluklarına baksın.', 'Kollarını düz tut, dirseklerinde hafif bir büküklük olsun ve bu açıyı sabitle. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılları yarım daire çizerek kaldır; kolların başının üstünde tam uzayana kadar devam et.', 'Nefes alırken aynı yolu izleyerek yavaşça başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Dumbbell_Triceps_Extension', 'tr', array['Ayakta dur ve tek bir dambılı iki elinle tut; ayakların yaklaşık omuz genişliğinde açık olsun. Dambılı iki elinle kavra ve iki kolun da tamamen uzayana kadar yavaşça başının üstüne kaldır.', 'Ağırlık avuçlarının içinde dursun, başparmakların onu sarsın. Avuç içlerin yukarı, tavana baksın. Bu senin başlangıç pozisyonun.', 'Üst kollarını başına yakın, dirseklerini içeride ve yere dik tut. Ağırlığı yarım daire çizerek başının arkasına indir; ön kolların bisepslerine değene kadar devam et. İpucu: Üst kollar sabit kalır, yalnızca ön kollar hareket eder. Bu adımda nefes al.', 'Triseps kaslarınla dambılı kaldırarak başlangıç pozisyonuna dön. Bu adımda nefes ver.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Dumbbell_Upright_Row', 'tr', array['Her eline bir dambılı prone tutuşla (avuç içleri öne) al; ellerin omuz genişliğinden biraz dar olsun. Dambıllar uyluklarının üstünde dursun. Kolların uzun, dirseklerin hafif bükük, sırtın düz olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken dambılları yan omuz kaslarınla kaldır. Yukarı çıkarken vücuduna yakın tut ve hareketi dirseklerinle yönlendir. Neredeyse çenene değene kadar çek. İpucu: Hareketi dirsekler yönlendirir. Dambılları kaldırırken dirseklerin her zaman ön kollarından yüksekte olsun. Ayrıca gövdeni sabit tut ve tepede bir saniye bekle.', 'Dambılları yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes al.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Elevated_Quad_Stretch', 'tr', array['Sırtın bir sehpaya ya da basamağa dönük olsun; ondan iki üç fit kadar önde dur.', 'Bir bacağını arkana kaldır ve ayağını basamağa koy; ayağının üstüne ya da ön tabanına, hangisi daha rahatsa ona yasla.', 'Yerdeki bacağının dizini hafif bükük tut ve bu dizin ayak parmaklarını geçmesine izin verme. Taraf değiştir.']::text[]),
  ('Standing_Front_Barbell_Raise_Over_Head', 'tr', array['Dik dur ve eline bir halter al. Barı avuç içlerin aşağı bakacak şekilde, omuz genişliğinden dar tut.', 'Ayaklarını omuz genişliğinde aç, dirseklerini hafifçe bük. Bu başlangıç pozisyonu.', 'Nefes verirken halteri tam başının üstüne gelene kadar kaldır. Her tekrarda dirseklerini hafif bükük tutmaya dikkat et.', 'Kasılmayı hissedince nefes alarak halteri başlangıç pozisyonuna indirmeye başla.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Gastrocnemius_Calf_Stretch', 'tr', array['Sağ topuğunu, dizin düzken bir basamağa koy; öne eğil ve sağ elinle sağ ayak parmaklarını tut. Sol dizin hafif bükük, sırtın düz olsun.', 'Ağırlığını sol bacağına ver ve sol elini sol uyluğuna koy.', 'Sağ ayak parmaklarını dizine doğru çek; baldırında gerilme hissedene kadar devam et.']::text[]),
  ('Standing_Hamstring_and_Calf_Stretch', 'tr', array['Bir ayağına kemer, bant ya da ip dola. Ayakta dur ve o ayağını öne koy.', 'Arkadaki bacağını bük, öndeki düz kalsın. Şimdi öndeki ayağının parmaklarını yerden kaldır ve öne eğil.', 'Baldırdaki gerilmeyi artırmak için kemerle ayağının ön kısmını kendine çek. 10-20 saniye bekle ve diğer ayakla tekrarla.']::text[]),
  ('Standing_Hip_Circles', 'tr', array['Tek bacağının üstünde dur ve dikey bir desteğe tutun.', 'Boştaki dizini 90 dereceye kaldır. Bu senin başlangıç pozisyonun.', 'Kalçanı olabildiğince dışa aç ve dizinle büyük bir daire çizmeye çalış.', 'Bu hareketi yavaşça birkaç tekrar yap, sonra diğer tarafta tekrarla.']::text[]),
  ('Standing_Hip_Flexors', 'tr', array['Omurgan dik olacak şekilde dümdüz dur; sol ayağın sağ ayağının biraz önünde olsun.', 'İki dizini bük, arkadaki topuğunu yerden kaldır ve sağ kalçanı öne it. Yine de bu duruşta tam ve derin bir esneme elde edemezsin, çünkü kalça fleksörünü hem gevşetmek hem de üstünde durmak zordur. Taraf değiştir.']::text[]),
  ('Standing_Inner-Biceps_Curl', 'tr', array['Ayakta dur, her elinde bir dambıl olsun ve kolların aşağı uzansın. Dirseklerin gövdene yakın dursun. Bacaklarını yaklaşık omuz genişliğinde aç.', 'Avuç içlerini içe, nötr konuma çevir. Bu senin başlangıç pozisyonun.', 'Nefes verirken biseps kaslarını sıkarak ağırlıkları dışa doğru yukarı bük; üst kolların sabit kalsın. Bileklerini öyle çevir ki ağırlıklar tepeye vardığında supine tutuşta ol (avuç içleri yukarı).', 'Yalnızca ön kolların hareket etsin. Biseps tamamen kasılana ve dambıllar omuz hizasına gelene kadar devam et. İpucu: Ön kollarını deltoidlerinin dış kısmıyla aynı hizada tut.', 'Kasılı pozisyonda bir saniye bekle ve bisepsini iyice sık.', 'Nefes alırken dambılları yavaşça başlangıç pozisyonuna geri getir. Nötr tutuşa dönmek için ağırlığı indirirken bileklerini geri çevirmeyi unutma.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Lateral_Stretch', 'tr', array['Ayaklarını kalça genişliğinden biraz fazla aç, dizlerini hafifçe bük.', 'Omurganı desteklemek için sağ elini sağ kalçana koy.', 'Sol kolunu dümdüz yukarı kaldır ve sol elini başının arkasına koy. Gövdeni sağa eğerken elin orada kalsın.', 'Ağırlığını iki bacağına eşit dağıt (sol kalçana yüklenme). Taraf değiştir.']::text[]),
  ('Standing_Leg_Curl', 'tr', array['Makinenin kolunu boyuna göre ayarla. Yüzün öne dönük şekilde makineye yaslan, gövden belden yaklaşık 30-45 derece öne eğik olsun (eğik duruş arka bacak kaslarını daha iyi çalıştırır). Kolun yastığı sağ bacağının arkasında, baldırın birkaç inç altında dursun; sağ bacağının ön yüzü makinenin yastığına yaslansın.', 'Gövdeni öne eğik tut, bacağının tamamen uzadığından emin ol ve makinenin yan tutamaklarını kavra. Ayak parmakların düz baksın. Bu senin başlangıç pozisyonun.', 'Nefes verirken sağ bacağını, uyluğunu yastıktan ayırmadan olabildiğince yukarı bük. Tam kasılı pozisyona gelince bir saniye bekle.', 'Nefes alırken bacağını ilk konumuna geri getir. Önerilen tekrar sayısı kadar yap.', 'Şimdi aynı hareketi sol bacağınla yap.']::text[]),
  ('Standing_Long_Jump', 'tr', array['Bu çalışma en iyi kumda ya da yumuşak başka bir iniş zemininde yapılır. Mesafeyi ölçebileceğinden emin ol. Ayakların omuz genişliğinde, yarım çömelmiş durumda dur.', 'Kollarını güçlü biçimde savur, bacaklarınla kısa bir yaylanma yap ve olabildiğince uzağa, öne doğru sıçra.', 'Ayakların önünde olacak şekilde inmeye çalış; bacaklarınla uzanabildiğin kadar ileri uzan.', 'İndiğin nokta ile başlangıç noktası arasındaki mesafeyi ölç ve sonuçlarını kaydet.']::text[]),
  ('Standing_Low-Pulley_Deltoid_Raise', 'tr', array['Alt makaranın sağ yanında dur. Sol elini gövdenin önünden çaprazlayarak alt makaraya takılı tek tutamağı prone tutuşla (avuç içi aşağı) kavra. Kolun önünde dursun. Daha iyi destek ve denge için sağ elinle makineyi tut.', 'Sırtının dik, ayaklarının omuz genişliğinde açık olduğundan emin ol. Bu başlangıç pozisyonu.', 'Nefes verirken sol elini gövdenin önünden çaprazlayarak dışa doğru kaldır; omuz hizasına gelene kadar devam et.', 'Tepede kasılmayı bir saniye hisset, sonra nefes alarak tutamağı yavaşça ilk başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('Standing_Low-Pulley_One-Arm_Triceps_Extension', 'tr', array['Alt makaralı makinenin yanında dur ve tek tutamağı sol elinle kavra. Makineye arkanı dön; tutamak yanında, kolun tamamen düz olsun. Şimdi tutamağı iki elinle tam başının üstüne kaldır, avuç için öne baksın. Üst kolunu tam dikey (yere dik) tut ve sabit kalması için sağ elini sol dirseğine koy. Bu başlangıç pozisyonu.', 'Üst kolunu başına yakın (dirsek içeride) ve yere dik tut. Ağırlığı yarım daire çizerek başının arkasına indir; ön kolun bisepsine değene kadar devam et. İpucu: Üst kol sabit kalır, yalnızca ön kol hareket eder. Bu adımda nefes al.', 'Triseps kasınla tutamağı kaldırarak başlangıç pozisyonuna dön. Bu adımda nefes ver.', 'Önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('Standing_Military_Press', 'tr', array['Bir halteri squat sehpasına yaklaşık göğüs hizasında yerleştir. Ağırlıkları seçtikten sonra barı prone tutuşla (avuç içleri öne) kavra. Ellerin omuz genişliğinden daha açık olsun.', 'Dizlerini hafifçe bük ve halteri köprücük kemiğine yerleştir. Halteri göğsünün üstünde duracak şekilde sehpadan kaldır. Bir adım geri at ve ayaklarını omuz genişliğinde aç.', 'Halteri doğru tutuş genişliğiyle aldıktan sonra kollarını kilitleyerek başının üstüne kaldır. Yaklaşık omuz hizasında ve başının biraz önünde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken barı yavaşça köprücük kemiğine indir.', 'Nefes verirken barı yeniden başlangıç pozisyonuna kaldır.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Olympic_Plate_Hand_Squeeze', 'tr', array['Dik dur ve her elinde bir ağırlık plakasını kenarından, kolların aşağı uzanmış halde, nötr tutuşla (avuç içleri içe) tut. Ayakların omuz genişliğinde açık olsun. Bu senin başlangıç pozisyonun.', 'Plakaları, parmakların neredeyse açılana ama ağırlığı hâlâ tutabilecek kadar indir. İndirirken nefes al.', 'Şimdi nefes verirken ellerini kapatarak plakaları başlangıç pozisyonuna geri kaldır.', 'Programında yazan tekrar sayısı kadar yap.']::text[]),
  ('Standing_One-Arm_Cable_Curl', 'tr', array['Alt makaralı makinenin yanında dur ve tek tutamağı kavra. Ağırlığı kolun taşıyacak kadar makineden uzaklaş.', 'Üst kolun sabit ve yere dik, dirseğin içeride, avuç için öne dönük olsun. Çalışmayan kolunun elini beline koy. Böylece dengeni korursun.', 'Nefes verirken, üst kolunu sabit tutarak tutamağı yavaşça yukarı bük; ön kolun bisepsine değene kadar devam et. İpucu: Yalnızca ön kol hareket eder.', 'Kasılı pozisyonda bisepsini sıkarak bekle, sonra nefes alırken tutamağı başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi diğer kolunla yap.']::text[]),
  ('Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'tr', array['Eğimli sehpanın arka tarafında, birine yardımcılık edecekmiş gibi dur. Bir eline dambıl al ve kolunu supine tutuşla (avuç içi yukarı) eğimli sehpanın üstüne yasla.', 'Boştaki elini sehpanın köşesine ya da kenarına koy. Göğsün eğimin üst kısmına yaslansın, ayakların geniş açık ve yere sağlam bassın. Bu başlangıç pozisyonu.', 'Nefes verirken biseps kasını sıkarak dambılı yukarı bük; üst kolun sabit kalsın, yalnızca ön kolun hareket etsin. Biseps tamamen kasılana ve dambıl omuz hizasına gelene kadar devam et. Kasılı pozisyonda bir saniye bekle.', 'Nefes alırken dambılı yavaşça başlangıç pozisyonuna geri getir.', 'Önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi diğer kolunla yap.']::text[]),
  ('Standing_One-Arm_Dumbbell_Triceps_Extension', 'tr', array['Ayakta dur ve bir eline dambıl al; ayakların yaklaşık omuz genişliğinde açık olsun. Dambılı tuttuğun kolu başının üstünde tamamen uzat. İpucu: Serçe parmağın tavana, avuç için öne baksın. Dambıl başının üstünde olsun.', 'Bu senin başlangıç pozisyonun.', 'Üst kolunu başına yakın (dirsek içeride) ve yere dik tut. Ağırlığı yarım daire çizerek başının arkasına indir; ön kolun bisepsine değene kadar devam et. İpucu: Üst kol sabit kalır, yalnızca ön kol hareket eder. Bu adımda nefes al.', 'Triseps kasınla dambılı kaldırarak başlangıç pozisyonuna dön. Bu adımda nefes ver.', 'Önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('Standing_Overhead_Barbell_Triceps_Extension', 'tr', array['Ayakta dur ve bir halteri ya da EZ barı prone tutuşla (avuç içleri öne) tut; ellerin omuz genişliğinden dar olsun. Ayaklarını yaklaşık omuz genişliğinde aç.', 'Şimdi barı kolların tamamen uzayana kadar başının üstüne kaldır. Dirseklerini içeride tut. Bu senin başlangıç pozisyonun.', 'Üst kollarını başına yakın, dirseklerini içeride ve yere dik tut. Ağırlığı yarım daire çizerek başının arkasına indir; ön kolların bisepslerine değene kadar devam et. İpucu: Üst kollar sabit kalır, yalnızca ön kollar hareket eder. Bu adımda nefes al.', 'Triseps kaslarınla barı kaldırarak başlangıç pozisyonuna dön. Bu adımda nefes ver.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Palm-In_One-Arm_Dumbbell_Press', 'tr', array['Bir elinde dambılı nötr tutuşla tut; kolun yanında tamamen düz sarksın. Dengeni korumak için diğer kolunla eğimli bir sehpaya tutun.', 'Ayaklarını omuz genişliğinde aç. Şimdi dambılı, kolun 90 derecelik açı yapana kadar yavaşça kaldır. Not: Ön kolun yere dik olmalı. Hareket boyunca nötr tutuşu koru.', 'Dambılı, kolun tamamen uzayana kadar yavaşça yukarı it. Bu başlangıç pozisyonu.', 'Nefes alırken ağırlığı, kolun yeniden 90 derecelik açıya gelene kadar indir.', 'Kasılmayı bir saniye hisset, sonra nefes verirken ağırlığı yeniden başlangıç pozisyonuna doğru kaldır. Hareket sırasında dengede kalmak için eğimli sehpaya tutunmayı ve ayaklarını yerinde tutmayı unutma.', 'Önerilen tekrar sayısı kadar yap.', 'Kol değiştir ve hareketi tekrarla.']::text[]),
  ('Standing_Palms-In_Dumbbell_Press', 'tr', array['Her elinde bir dambılı nötr tutuşla tut; kolların yanlarında tamamen düz sarksın. Ayaklarını omuz genişliğinde aç. Şimdi dambılları, kolların 90 derecelik açı yapana kadar yavaşça kaldır. Not: Ön kolların yere dik olmalı. Bu başlangıç pozisyonu.', 'Hareket boyunca nötr tutuşu koru. Dambılları, kolların tamamen uzayana kadar yavaşça yukarı it.', 'Nefes alırken ağırlıkları, kolların yeniden 90 derecelik açıya gelene kadar indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'tr', array['Dik dur ve bir halteri kalçanın arkasında, kolların aşağı uzanmış halde prone tutuşla tut (avuç içlerin arkaya, kalçandan uzağa bakar); ellerin omuz genişliğinde açık olsun.', 'Dümdüz karşıya bak, ayakların omuz genişliğinde açık olsun. Bu başlangıç pozisyonu.', 'Nefes verirken bileklerini yarım daire çizerek tavana doğru bük ve halteri yavaşça yükselt. Not: Bu harekette vücudunda yalnızca bileklerin hareket etmeli.', 'Kasılmayı bir saniye tut, sonra nefes alırken halteri başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.', 'Bitirince dizlerini bükerek halteri squat sehpasına ya da yere bırak. İpucu: En kolayı halteri squat sehpasından almak ya da bir partnerin sana uzatmasıdır.']::text[]),
  ('Standing_Pelvic_Tilt', 'tr', array['Ayaklarını kalça genişliğinde açarak başla.', 'Dizlerini hafifçe bük; yumuşak ve esnek kalsınlar.', 'İstersen bu esnemede kuyruk sokumunu önde tutmadan önce leğen kemiğini birkaç kez öne ve arkaya hareket ettir.']::text[]),
  ('Standing_Rope_Crunch', 'tr', array['Üst makaraya bir halat tak ve uygun bir ağırlık seç.', 'Sırtını kablo kulesine dön. Halatı iki elinle omuzlarının üstünden al ve göğsünün üst kısmında tut. Bu senin başlangıç pozisyonun.', 'Omurganı bükerek ağırlığı gidebildiğin kadar aşağı çek ve mekik hareketini yap.', 'En kasılı noktada bir an bekle, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Standing_Soleus_And_Achilles_Stretch', 'tr', array['Ayaklarını kalça genişliğinde aç, bir ayağın diğerinin biraz önünde olsun.', 'İki dizini bük, arkadaki topuğun yerde kalsın. Taraf değiştir.']::text[]),
  ('Standing_Toe_Touches', 'tr', array['Önünde ve arkanda biraz boşluk olacak şekilde dur.', 'Bacakların düzken belden öne eğil; gevşeyip üst gövdeni önünde aşağı sarkıtabildiğin noktaya kadar in. Kolların ve ellerin doğal biçimde sarksın. 10 ila 20 saniye bekle.']::text[]),
  ('Standing_Towel_Triceps_Extension', 'tr', array['Ayaklarını omuz genişliğinde aç, bir havlunun bir ucunu iki elinle tut ve kollarını başının üzerinde tamamen uzat. Dirseklerin içeride, kolların yere dik, avuçların birbirine dönük olsun. Bu, başlangıç pozisyonun.', 'Partnerine haber ver, havlunun öbür ucunu tutup direnç uygulasın. Üst kollarını başına yakın (dirsekler içeride) ve yere dik tut; havluyu başının arkasına doğru yarım daire çizerek, ön kolların bisepsine değene kadar indir. İpucu: Üst kolların sabit kalsın, yalnızca ön kolların hareket etsin. Bu sırada nefes al.', 'Triseps gücünle havluyu yukarı çekerek başlangıç pozisyonuna dön. Bu sırada nefes ver.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Standing_Two-Arm_Overhead_Throw', 'tr', array['Ayaklarını omuz genişliğinde aç ve sağlık topunu iki elinle tut. Başlarken dizlerini hafifçe kır, geriye yaslan ve topu başının iyice arkasına götür.', 'Topu bütün gücünle ileri fırlat. Kalçadan bükül ve hareketi tüm vücudunla tamamla.', 'Topu bir partnere atabilir ya da duvara atıp geri sektiğinde yakalayabilirsin.']::text[]),
  ('Star_Jump', 'tr', array['Rahat bir duruşla başla: ayakların omuz genişliğinde, kolların vücuduna yakın olsun.', 'Harekete yarım squat''a inerek başla, sonra patlayıcı bir şekilde olabildiğince yükseğe sıçra. Tüm vücudunu tam uzat, kollarını ve bacaklarını yana aç.', 'Yere inerken kollarını ve bacaklarını tekrar topla, darbeyi bacaklarınla karşıla.']::text[]),
  ('Step-up_with_Knee_Raise', 'tr', array['Uygun yükseklikte bir kutunun ya da sehpanın karşısında ayakların bitişik dur. Bu, başlangıç pozisyonun.', 'Sol ayağını sehpanın üstüne koyarak başla. Öndeki bacağının kalçasını ve dizini açarak kutunun üstünde doğrul. Sol bacağının üzerinde dururken sağ dizini ve kalçanı bük, dizini çekebildiğin kadar yukarı çek.', 'Aynı yolu tersinden izleyerek kutudan in, sonra aynı sırayı diğer bacağınla yap.']::text[]),
  ('Step_Mill', 'tr', array['Merdiven makinesine çık ve menüden istediğin seçeneği belirle: elle ayar yapabilir ya da hazır bir program seçebilirsin. Çoğu makinede yaşını ve kilonu girerek yaktığın kaloriyi tahmini olarak görebilirsin. Basamakları çıkarken ayağın takılmasın, dikkat et. Düşmemek için tutamakları bırakmaman önerilir.', 'Merdiven makinesi pratiktir, kalp ve dolaşım sistemine iyi gelir; dışarıda koşmaya yakın kalori yaktırırken eklemlere çoğunlukla daha az yük bindirir. Genelde diğer kardiyo aletlerinden çok daha zordur. 150 lb ağırlığındaki biri 30 dakikada çoğunlukla 300 kaloriden fazla yakar; yürürken bu yaklaşık 175 kaloridir.']::text[]),
  ('Stiff-Legged_Barbell_Deadlift', 'tr', array['Barı üstten tutuşla, avuçların aşağı bakacak şekilde kavra. Ağırlık fazlaysa bilek sargısına ihtiyacın olabilir.', 'Gövden dik, ayakların omuz genişliğinde ya da daha dar dur. Dizlerin hafifçe bükülü olsun. Bu, başlangıç pozisyonun.', 'Dizlerini sabit, sırtını düz tut ve kalçadan bükülerek halteri ayaklarının hemen üstüne kadar indir. Yerden bir şey alacakmış gibi öne uzanmaya devam et, arka bacaklarında gerilme hissedene kadar. Bu sırada nefes al.', 'Kalçanı açarak gövdeni tekrar doğrult ve başlangıç pozisyonuna dön. Bu sırada nefes ver.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Stiff-Legged_Dumbbell_Deadlift', 'tr', array['İki dambıl al ve kolların uzanmış halde yanlarında tut.', 'Gövden dik, ayakların omuz genişliğinde ya da daha dar dur. Dizlerin hafifçe bükülü olsun. Bu, başlangıç pozisyonun.', 'Dizlerini sabit, sırtını düz tut ve belden bükülerek dambılları ayaklarının hemen üstüne kadar indir. Yerden bir şey alacakmış gibi öne uzanmaya devam et, arka bacaklarında gerilme hissedene kadar. Bu sırada nefes ver.', 'Kalçanı ve belini açarak gövdeni tekrar doğrult ve başlangıç pozisyonuna dön. Bu sırada nefes al.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Stiff_Leg_Barbell_Good_Morning', 'tr', array['Güvenlik için bu hareketi squat rack içinde yapman en iyisi. Önce barı boyuna en uygun yükseklikteki askıya yerleştir. Yükseklik doğruysa ve bar yüklendiyse barın altına gir ve barı omuzlarının arkasına, boynun biraz altına yerleştir.', 'Barı iki yanından birer elinle tut. Bacaklarınla iterken aynı anda gövdeni doğrultarak barı askıdan kaldır.', 'Rack''ten uzaklaş ve ayaklarını omuz genişliğinde, orta bir duruşla yerleştir. Başını hep yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Bu, başlangıç pozisyonun.', 'Bacaklarını sabit tut, nefes alırken kalçadan bükülerek gövdeni öne eğ. Gövden yere paralel olana kadar in.', 'Nefes verirken gövdeni başlangıç pozisyonuna doğrultarak barı yukarı kaldır.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Stomach_Vacuum', 'tr', array['Dik dur, ayaklarını omuz genişliğinde aç ve ellerini kalçalarına koy. Bu, başlangıç pozisyonun.', 'Yavaşça alabildiğin kadar nefes al. Sonra verebildiğin kadar nefes ver, bu sırada karnını olabildiğince içeri çek ve öyle kal. Göbek deliğinin omurgana değdiğini hayal et.', 'Bir izometrik kasılma yaklaşık 20 saniye sürer. Bu 20 saniye boyunca normal nefes almaya çalış. Sonra nefes al ve karnını başlangıç pozisyonuna bırak.', 'Hareketi biraz çalıştıktan sonra 20 saniyeden uzun tutmayı dene. İpucu: Zamanla 40-60 saniyeye kadar çıkabilirsin.', 'Önerilen set sayısı kadar tekrarla.']::text[]),
  ('Straight-Arm_Dumbbell_Pullover', 'tr', array['Bir dambılı düz sehpanın üzerine dik olarak koy.', 'Dambılın sehpanın üstünde sağlam durduğundan emin ol. Sonra sehpaya çapraz uzan: gövden sehpayla artı işareti oluştursun ve yalnızca omuzların yüzeye değsin. Kalçan sehpadan aşağıda, bacakların bükülü, ayakların yere sağlam bassın. Başın da sehpanın dışında kalır.', 'Dambılı iki elinle kavra ve kolların düz halde tam göğsünün üzerinde tut. İki avucun da dambılın bir ucunun alt yüzüne bastırsın. Bu, başlangıç pozisyonun. Dikkat: Bu harekette kullandığın dambılın sağlam olduğundan her zaman emin ol. Plakaları gevşek bir dambıl dağılıp yüzüne düşebilir.', 'Kollarını düz tut, nefes alırken ağırlığı yavaşça bir yay çizerek başının arkasına indir, göğsünde gerilme hissedene kadar.', 'O noktadan, indirdiğin yayı izleyerek dambılı başlangıç pozisyonuna geri getir ve bu sırada nefes ver.', 'Ağırlığı başlangıç pozisyonunda bir saniye tut ve hareketi belirlenen tekrar sayısı kadar tekrarla.']::text[]),
  ('Straight-Arm_Pulldown', 'tr', array['Lat pulldown makinesinin üst makarasındaki geniş barı, omuz genişliğinden daha geniş ve üstten tutuşla (avuçlar aşağıda) kavra. Sonra aşağı yukarı two feet geri çekil.', 'Gövdeni belden yaklaşık 30 derece öne eğ. Kolların önünde tamamen uzanmış, dirseklerin hafifçe bükülü olsun. Kolların tam uzanmıyorsa, uzanana kadar biraz daha geri çekil. Kolların tam uzanmış ve gövden belden hafifçe eğikken kanat kaslarını sık; artık başlamaya hazırsın.', 'Kollarını düz tut ve kanat kaslarını kasarak barı aşağı çek, ellerin uyluklarının yanına gelene kadar. Bu sırada nefes ver.', 'Kollarını yine düz tutarak, nefes alırken başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Straight_Bar_Bench_Mid_Rows', 'tr', array['Yüklü bir halteri bir sehpanın ucuna koy. Sehpanın üstünde, barın arkasında dur ve barı orta genişlikte, üstten tutuşla kavra. Kalçanı geriye it, göğsünü kaldır ve omurganı nötr tut. Bu, başlangıç pozisyonun.', 'Kürek kemiklerini geriye çekip dirseklerini bükerek barı gövdene doğru çek. Hareketi kontrollü yap, silkeleme.', 'Kısa bir duraklamadan sonra barı yavaşça başlangıç pozisyonuna indir; en alta kadar indiğinden emin ol.']::text[]),
  ('Straight_Raises_on_Incline_Bench', 'tr', array['Bir barı eğimli sehpanın baş tarafının arkasına, yere koy.', 'Sehpaya yüzüstü uzan. Halteri üstten tutuşla, kolların düz halde yerden al ve dümdüz aşağı sarkmasına izin ver. Bu, başlangıç pozisyonun.', 'Kollarını uzatılmış tutarak halteri başının önüne doğru, ileri kaldır.', 'Başlangıç pozisyonuna dön.']::text[]),
  ('Stride_Jump_Crossover', 'tr', array['Bir kutunun yanında dur ve kutuya yakın olan ayağını üstüne, kenara yakın koy.', 'Kollarını yukarı savur, üstteki bacağınla iterek olabildiğince yükseğe sıçra. Diğer dizini yukarı çekmeye çalış.', 'Kutunun öbür tarafına, başladığın duruşun tersiyle in: başta kutunun üstünde olan ayağın artık yerde, diğer ayağın kutunun üstünde olur.', 'Hareketi tekrarla ve ilk tarafa geri geç.']::text[]),
  ('Sumo_Deadlift', 'tr', array['Yüklü bar yerde dursun. Bara, ayaklarının ortasından geçecek kadar yaklaş. Ayaklarını çok geniş aç, bar kilitlerine yakın olsun. Kalçadan bükülerek barı kavra. Kolların omuzlarının tam altında, bacaklarının arasında dursun; üstten tutuş, karışık tutuş ya da kanca tutuşu kullanabilirsin. Omuzlarını gevşet; bu, kollarını fiilen uzatır.', 'Nefes al, sonra kalçanı indir; ileri bak, göğsün yukarıda olsun. Yeri it ve ayaklarını iki yana doğru bastır, ağırlığın ayaklarının arka yarısında olsun. Kalçanı ve dizlerini aç.', 'Bar dizlerini geçerken geriye yaslan, kalçanı bara doğru it ve kürek kemiklerini birbirine yaklaştır.', 'Kalçadan bükülerek ağırlığı yere indir ve inerken ağırlığı kontrol et.']::text[]),
  ('Sumo_Deadlift_with_Bands', 'tr', array['Kısa lastik bantlarla deadlift yapmak için bantları başlamadan önce bara geçir ve pozisyon alırken içlerine bas. Bantlar ayağının arka yarısının altında, tam yeri ittiğin noktada olsun.', 'Yüklü bar yerde dursun. Bara, ayaklarının ortasından geçecek kadar yaklaş. Ayaklarını çok geniş aç, bar kilitlerine yakın olsun. Kalçadan bükülerek barı kavra. Kolların omuzlarının tam altında, bacaklarının arasında dursun; üstten tutuş, karışık tutuş ya da kanca tutuşu kullanabilirsin.', 'Nefes al, sonra kalçanı indir; ileri bak, göğsün yukarıda olsun. Yeri it ve ayaklarını iki yana doğru bastır, ağırlığın ayaklarının arka yarısında olsun. Kalçanı ve dizlerini aç.', 'Bar dizlerini geçerken geriye yaslan, kalçanı bara doğru it ve kürek kemiklerini birbirine yaklaştır.', 'Kalçadan bükülerek ağırlığı yere indir ve inerken ağırlığı kontrol et.']::text[]),
  ('Sumo_Deadlift_with_Chains', 'tr', array['Zincirleri barın kollarına bağlayabilir ya da kaldırdıkça ağırlık daha çok artsın diye ortalarından barın üstüne atabilirsin. Zincirlerin uçlarını plakalardan uzak tutmaya çalış ki ağırlığı indirirken onlara çarpmayasın.', 'Yüklü bar yerde dursun. Bara, ayaklarının ortasından geçecek kadar yaklaş. Ayaklarını çok geniş aç, bar kilitlerine yakın olsun. Kalçadan bükülerek barı kavra. Kolların omuzlarının tam altında, bacaklarının arasında dursun; üstten tutuş, karışık tutuş ya da kanca tutuşu kullanabilirsin. Omuzlarını gevşet; bu, kollarını fiilen uzatır.', 'Nefes al, sonra kalçanı indir; ileri bak, göğsün yukarıda olsun. Yeri it ve ayaklarını iki yana doğru bastır, ağırlığın ayaklarının arka yarısında olsun. Kalçanı ve dizlerini aç.', 'Bar dizlerini geçerken geriye yaslan, kalçanı bara doğru it ve kürek kemiklerini birbirine yaklaştır.', 'Kalçadan bükülerek ağırlığı yere indir ve inerken ağırlığı kontrol et.']::text[]),
  ('Superman', 'tr', array['Yere ya da bir mata yüzüstü, dümdüz uzan. Kollarını önünde tamamen uzat. Bu, başlangıç pozisyonun.', 'Kollarını, bacaklarını ve göğsünü aynı anda yerden kaldır ve bu kasılmayı 2 saniye tut. İpucu: En iyi sonuç için belini sık. Kaldırırken nefes vermeyi unutma. Not: Kasılı pozisyonda dururken uçan Superman''e benzemelisin.', 'Nefes alırken kollarını, bacaklarını ve göğsünü yavaşça başlangıç pozisyonuna indir.', 'Programında belirtilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Supine_Chest_Throw', 'tr', array['Partnerin ya da yeterince sağlam bir duvarın yoksa bu çalışma göğüs pasları için çok uygundur. Yere sırtüstü uzan ve dizlerini bük.', 'Top göğsünün üzerinde, iki elin topu alttan tutarken başla.', 'Patlayıcı bir şekilde yukarı it; dirseklerini açarak topu tam üstüne, olabildiğince yükseğe fırlat.', 'Top aşağı inerken iki elinle yakala.']::text[]),
  ('Supine_One-Arm_Overhead_Throw', 'tr', array['Yere sırtüstü uzan ve dizlerini bük. Topu tek elinle tut ve kolunu başının arkasına tamamen uzat. Bu, başlangıç pozisyonun.', 'Hareketi omuzdan başlat: doğrulup otururken topu dümdüz ileri, olabildiğince uzağa fırlat.', 'Topu bir partnere atabilir ya da duvardan sektirebilirsin.']::text[]),
  ('Supine_Two-Arm_Overhead_Throw', 'tr', array['Yere sırtüstü uzan ve dizlerini bük.', 'Topu iki elinle tut ve kollarını başının arkasına tamamen uzat. Bu, başlangıç pozisyonun.', 'Hareketi omuzlardan başlat: doğrulup otururken topu dümdüz ileri, olabildiğince uzağa fırlat.', 'Topu bir partnere atabilir ya da duvardan sektirebilirsin.']::text[]),
  ('Suspended_Fallout', 'tr', array['Askıları, tutamaklar uygun yükseklikte, bel hizasının altında kalacak şekilde ayarla.', 'Ayakta, tutamakları kavrayarak başla. Askılara doğru eğil ve eğimli şınav pozisyonuna geç. Bu, başlangıç pozisyonun.', 'Kollarını düz tutarak askılara daha da yaslan ve vücudunu yere yaklaştır. Omuzlarının açılmasına izin ver; kolların yukarı, başının üzerine doğru yükselsin.', 'Omurganı nötr, vücudunun geri kalanını düz tut; hareket eden tek eklem omuzların olsun.', 'Kasılmanın en yoğun olduğu noktada duraklat, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Suspended_Push-Up', 'tr', array['Askı kayışlarını bir rack''in tepesine ya da başka bir nesneye sağlamca bağla.', 'Askılara yaslan, her eline bir tutamak al ve şınav plank pozisyonuna geç. Kolların tamamen uzanmış ve duruşun düzgünken vücudun yere olabildiğince paralel olsun.', 'Gövdeni düz ve sıkı tut, dirseklerini bükerek yavaşça alçal.', 'Dirseklerin 90 dereceyi geçene kadar devam et. Duraklat, sonra kollarını açarak başlangıç pozisyonuna dön.']::text[]),
  ('Suspended_Reverse_Crunch', 'tr', array['Bir çift askı kayışını, tutamaklar yerden aşağı yukarı a foot yukarıda sarkacak şekilde sabitle. Sırtın rack''e dönük, şınav plank pozisyonuna geç.', 'Ayaklarını tutamaklara yerleştir. Vücudunu düz tut, kalçanın sarkmasına izin verme. Bu, başlangıç pozisyonun.', 'Dizlerini ve kalçanı bükerek başla, dizlerini gövdene doğru çek. Bunu yaparken leğen kemiğini öne doğru eğ ve omurganın yuvarlanmasına izin ver.', 'Kontrollü hareketin en üst noktasında başlangıç pozisyonuna dön.']::text[]),
  ('Suspended_Row', 'tr', array['Askıları yaklaşık göğüs hizasına as. Her eline bir tutamak al ve geriye yaslan. Vücudun dik, başın ve göğsün yukarıda, kolların tamamen uzanmış olsun. Bu, başlangıç pozisyonun.', 'Harekete dirseklerini bükerek başla. Bunu yaparken kürek kemiklerini öne doğru aç (protraksiyon).', 'Hareket tamamlandığında duraklat, sonra başlangıç pozisyonuna dön.']::text[]),
  ('Suspended_Split_Squat', 'tr', array['Askıları, tutamaklar yerden 18-30 inches yukarıda olacak şekilde as.', 'Sırtını düzeneğe dön ve arkadaki ayağını arkandaki tutamağa yerleştir. İleri bak, göğsünü kaldır, dizin hafifçe bükülü olsun. Bu, başlangıç pozisyonun.', 'Dizini ve kalçanı bükerek yere doğru alçal. Ağırlığını topuğunda tut ve duruşunu hareket boyunca koru.', 'En alt noktada hareketi tersine çevir: kalçanı ve dizini açarak başlangıç pozisyonuna dön.']::text[]),
  ('Svend_Press', 'tr', array['Ayakta başla.', 'İki hafif plakayı ellerinle birbirine bastır. Plakaları bitişik halde göğsüne yakın tut ki göğüs kaslarında izometrik bir kasılma oluşsun. Parmakların ileri baksın. Bu, başlangıç pozisyonun.', 'Plakaları avuçlarının arasında sıkmaya devam et ve kollarını kontrollü bir şekilde dümdüz öne uzat.', 'Hareketin sonunda duraklat, sonra yavaşça başlangıç pozisyonuna dön.']::text[]),
  ('T-Bar_Row_with_Handle', 'tr', array['Bir barı oynamaması için landmine aparatına ya da bir köşeye yerleştir. Sana bakan ucuna uygun bir ağırlık tak.', 'Barı bacaklarının arasına al ve çift D kürek tutamağını barın çevresine, kilidin hemen yanına yerleştir. Kalçanı ve bacaklarını kullanarak ayağa kalk.', 'Geniş bir duruş al; kalçan geride, göğsün yukarıda, kolların uzanmış olsun. Bu, başlangıç pozisyonun.', 'Kürek kemiklerini geriye çekip dirseklerini bükerek ağırlığı üst karnına doğru çek. Ağırlığı silkeleme, hareket sırasında hile yapma.', 'Kısa bir duraklamadan sonra başlangıç pozisyonuna dön.']::text[]),
  ('Tate_Press', 'tr', array['Düz sehpaya uzan; her elinde bir dambıl, uyluklarının üzerinde dursun. Avuçların birbirine baksın.', 'Uyluklarından destek alarak dambılları tek tek, her seferinde bir kolla yukarı al ve önünde omuz genişliğinde tut. Not: Dambılları önünde tutarken kolların omuz genişliğinden daha açık ve üstten tutuşla (avuçlar ileri) olmalı. Dirseklerin dışa baksın. Bu, başlangıç pozisyonun.', 'Üst kollarını sabit tut; nefes alırken dambılları yavaşça, yarım daire çizerek içe ve aşağı, üst göğsüne değene kadar getir. Dambılları her an tam kontrol altında tut; üst kollarını oynatma, dambılları göğsünde dinlendirme.', 'Nefes verirken dambılları triseps gücünle, aynı yarım daireyi tersinden izleyerek yukarı it. Yukarı çıkarken dambılları bir arada tutmaya çalış. Kasılı pozisyonda kollarını kilitle, bir saniye tut ve tekrar yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmeli.', 'Hareketi antrenman programında belirtilen tekrar sayısı kadar tekrarla.']::text[]),
  ('The_Straddle', 'tr', array['Dik oturarak başla. Bacaklarını önünde V şeklinde uzat.', 'Ellerin yerdeyken olabildiğince öne eğil. 10 ila 20 saniye tut.']::text[]),
  ('Thigh_Abductor', 'tr', array['Abdüktör makinesine otur ve rahat ettiğin bir ağırlık seç. Bacakların doğru yerleşince iki yandaki tutamakları kavra. Belden yukarısı, bütün üst gövden sabit kalsın. Bu, başlangıç pozisyonun.', 'Nefes verirken bacaklarınla makineye yavaşça bastır ve bacaklarını birbirinden uzaklaştır.', 'Kasılmayı bir saniye hisset, sonra nefes alırken bacaklarını başlangıç pozisyonuna getir. Not: Sakatlanmamak için üst gövdeni sabit tutmayı unutma.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Thigh_Adductor', 'tr', array['Addüktör makinesine otur ve rahat ettiğin bir ağırlık seç. Bacakların makinenin bacak pedlerine doğru yerleşince iki yandaki tutamakları kavra. Belden yukarısı, bütün üst gövden sabit kalsın. Bu, başlangıç pozisyonun.', 'Nefes verirken bacaklarınla makineye yavaşça bastır ve bacaklarını birbirine yaklaştır.', 'Kasılmayı bir saniye hisset, sonra nefes alırken bacaklarını başlangıç pozisyonuna getir. Not: Sakatlanmamak için üst gövdeni sabit tutmayı ve hızlı, sarsıntılı hareketlerden kaçınmayı unutma.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Tire_Flip', 'tr', array['Lastiği alttan, dişli yüzeyinden kavra ve ayaklarını biraz geriye al. Göğsün lastiğe bastırsın.', 'Lastiği kaldırmak için kalçanı, dizlerini ve ayak bileklerini aç; lastiğin içine ve yukarı doğru it.', 'Lastik 45 derecelik açıya gelince öne adım at ve bir dizini lastiğe vur. Bu sırada ellerini lastiğin üst kısmına al ve dönüşü tamamlamak için lastiği bütün gücünle ileri it. Gerektiği kadar tekrarla.']::text[]),
  ('Toe_Touchers', 'tr', array['Yere ya da bir mata uzan, sırtın yere bastırılmış olsun. Kolların yanlarında, avuçların aşağı bakacak şekilde dursun.', 'Bacakların birbirine değsin. Onları yavaşça havaya kaldır; dizlerin hafifçe bükülü, bacakların yere neredeyse dik olsun. Ayak tabanların yere paralel dursun.', 'Kollarını yerle 45 derecelik açı yapacak şekilde tamamen uzat. Bu, başlangıç pozisyonun.', 'Belini yere bastırılmış tutarak gövdeni yavaşça kaldır ve ellerinle ayak parmaklarına değmeye çalış. Hareketin bu kısmında nefes vermeyi unutma.', 'Nefes alırken gövdeni ve kollarını yavaşça başlangıç pozisyonuna indir. Kollarını düz ve ayak parmaklarına dönük tutmayı unutma.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Torso_Rotation', 'tr', array['Dik dur ve pilates topunu iki elinle tut. Kollarını uzat, top tam önünde olsun. Bu, başlangıç pozisyonun.', 'Gövdeni bir yana çevir, hareket ederken gözünü toptan ayırma. Sonra ters yöne dön. 10-20 tekrar yap.']::text[]),
  ('Trail_Running_Walking', 'tr', array['Patikada koşmak ya da yürümek kan dolaşımını ve kalbi neredeyse anında hızlandırır. Ayakkabıların iyi olsun. Yokuş çıkarken seni yukarı baldır ve kalça kasların çeker; inerken darbenin büyük kısmını dizlerin, eklemlerin ve ayak bileklerin karşılar. Yokuş aşağı daha küçük adımlar at, darbeyi azaltmak için dizlerini bükülü tut ve düşmemek için yavaşla.', '150 lb ağırlığındaki biri 30 dakika yokuş yukarı yürüyerek 200 kaloriden fazla yakabilir; düz zeminde bu 175''tir. Patikada koşarsa 150 lb ağırlığındaki biri 30 dakikada 500 kalorinin hayli üzerinde yakabilir.']::text[]),
  ('Trap_Bar_Deadlift', 'tr', array['Hex bar olarak da bilinen trap barı yerde dururken uygun ağırlıkla yükle. Aletin ortasında dur ve iki tutamağı kavra.', 'Kalçanı indir, ileri bak ve göğsünü yukarıda tut.', 'Harekete topuklarından iterek başla, kalçanı ve dizlerini aç. Sırtını hiçbir an yuvarlama.', 'Hareket tamamlanınca ağırlığı kontrollü şekilde yere indir.']::text[]),
  ('Tricep_Dumbbell_Kickback', 'tr', array['Her eline bir dambıl al, avuçların gövdene baksın. Sırtın düz, dizlerin hafifçe bükülü, belden öne eğil; gövden yere neredeyse paralel olsun. Başını yukarıda tut. Üst kolların gövdene yakın ve yere paralel dursun, ön kolların ağırlıklarla birlikte yere doğru baksın. Ön kolunla üst kolun arasında 90 derecelik açı oluşsun. Bu, başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve triseps gücünle ağırlıkları kolların tamamen açılana kadar kaldır. Ön kolu hareket ettirmeye odaklan.', 'Üstteki kasılmada kısa bir duraklamadan sonra nefes al ve dambılları yavaşça başlangıç pozisyonuna indir.', 'Hareketi belirlenen tekrar sayısı kadar tekrarla.']::text[]),
  ('Tricep_Side_Stretch', 'tr', array['Sağ kolunu vücudunun önünden geçirip sol omzunun üzerine götür. Sol elinle dirseğini tut, trisepsinde gerilme hissedene kadar. Sonra aynısını diğer kolunla yap.']::text[]),
  ('Triceps_Overhead_Extension_with_Rope', 'tr', array['Alt makaraya bir halat tak. Uygun ağırlığı seç, halatı iki elinle kavra ve sırtını kabloya dön.', 'Ellerini başının arkasına getir, dirseklerin dümdüz yukarı baksın. Başlangıçta dirseklerin bükülü olsun. Daha dengeli durmak için bir ayağını öne alabilir ve makineden hafifçe uzağa eğilebilirsin. Bu, başlangıç pozisyonun.', 'Üst kolunu yerinde tutarak dirseklerini aç ve ellerini başının üzerine kaldır.', 'Hareketin tepesinde trisepsini sık, sonra ağırlığı yavaşça başlangıç pozisyonuna indir.']::text[]),
  ('Triceps_Pushdown', 'tr', array['Üst makaraya düz ya da açılı bir bar tak ve barı omuz genişliğinde, üstten tutuşla (avuçlar aşağıda) kavra.', 'Dik dur; gövden düz, yalnızca çok hafif öne eğik olsun. Üst kollarını vücuduna yaklaştır ve yere dik tut. Ön kolların barı tutarken yukarı, makaraya doğru baksın. Bu, başlangıç pozisyonun.', 'Triseps gücünle barı aşağı it; bar uyluklarının önüne değsin, kolların tamamen açılıp yere dik olsun. Üst kolların hep gövdenin yanında sabit kalsın, yalnızca ön kolların hareket etsin. Bu sırada nefes ver.', 'Kasılı pozisyonda bir saniye tuttuktan sonra barı yavaşça başlangıç noktasına çıkar. Bu sırada nefes al.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Triceps_Pushdown_-_Rope_Attachment', 'tr', array['Üst makaraya bir halat aparatı tak ve nötr tutuşla, avuçların birbirine bakacak şekilde kavra.', 'Dik dur; gövden düz, yalnızca çok hafif öne eğik olsun. Üst kollarını vücuduna yaklaştır ve yere dik tut. Ön kolların halatı tutarken yukarı, makaraya doğru baksın, avuçların birbirine dönük olsun. Bu, başlangıç pozisyonun.', 'Triseps gücünle halatı aşağı it ve halatın her ucunu uyluklarının yanına getir. Hareketin sonunda kolların tamamen açılmış ve yere dik olur. Üst kolların hep gövdenin yanında sabit kalsın, yalnızca ön kolların hareket etsin. Bu sırada nefes ver.', 'Kasılı pozisyonda bir saniye tuttuktan sonra halatı yavaşça başlangıç noktasına çıkar. Bu sırada nefes al.', 'Önerilen tekrar sayısı kadar tekrarla.']::text[]),
  ('Triceps_Pushdown_-_V-Bar_Attachment', 'tr', array['Kablo istasyonunun üst makarasına bir V-bar tak. Barı omuz genişliğinde, avuç içlerin yere bakacak şekilde üstten tut.', 'Dik dur; gövden düz olsun ve çok hafifçe öne eğilsin. Üst kollarını gövdene yaklaştır, yere dik dursunlar. Barı tutan ön kolların yukarıya, makaraya doğru baksın. Başparmakların serçe parmaklarından yüksekte olsun. Bu senin başlangıç pozisyonun.', 'Triseps kaslarını kullanarak barı aşağı it; bar uyluklarının ön yüzüne değsin ve kolların tamamen açılıp yere dik gelsin. Üst kolların hep gövdenin yanında sabit kalsın, yalnızca ön kolların hareket etsin. Bu hareketi yaparken nefes ver.', 'Kasılı pozisyonda bir saniye bekle, sonra V-barı yavaşça başlangıç noktasına yükselt. Bu adımda nefes al.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Triceps_Stretch', 'tr', array['Bir elini başının arkasına götür, diğer elinle dirseğini kavra ve nazikçe çek. 10 ila 20 saniye tut, sonra taraf değiştir.']::text[]),
  ('Tuck_Crunch', 'tr', array['Yere ya da bir egzersiz matına uzan ve sırtını zemine bastır. Kolların gövdenin iki yanında, avuç içlerin yere bakacak şekilde dursun.', 'Bir ayak bileğini diğerine dolayarak bacaklarını çaprazla. Bacaklarını yavaşça havaya kaldır; uylukların yere dik gelsin, dizlerin hafif bükülü olsun. Not: Yere paralel olması gereken uylukların değil, dizlerin ve ayak parmakların.', 'Kollarını yerden kaldır ve göğsünün üzerinde duracak şekilde çaprazla. Bu başlangıç pozisyonu.', 'Belini yere bastırılmış tutarken gövdeni yavaşça kaldır. Egzersizin bu bölümünde nefes vermeyi unutma.', 'Nefes alırken gövdeni yavaşça başlangıç pozisyonuna indir.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Two-Arm_Dumbbell_Preacher_Curl', 'tr', array['İki eline birer dambıl al ve üst kollarını Scott sehpasının ya da eğimli sehpanın üst yüzüne yerleştir. Dambılları omuz genişliğinde tut. Bu senin başlangıç pozisyonun.', 'Nefes alırken dambılları yavaşça indir; üst kolların açılsın ve biseps tamamen gerilsin.', 'Nefes verirken biseps gücüyle ağırlıkları yukarı bük; biseps tamamen kasılsın ve dambıllar omuz hizasına gelsin.', 'Kasılı pozisyonda bisepsi bir saniye boyunca güçlüce sık ve programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Two-Arm_Kettlebell_Clean', 'tr', array['İki kettlebell''i ayaklarının arasına koy. Başlangıç pozisyonuna geçmek için kalçanı geriye it ve dümdüz karşıya bak.', 'Kettlebell''leri clean hareketiyle omuzlarına al: Onları omuzlarına doğru kaldırırken bacaklarını ve kalçanı aç. Bunu yaparken bileklerini döndür.', 'Kettlebell''leri yeniden başlangıç pozisyonuna indir ve tekrarla.']::text[]),
  ('Two-Arm_Kettlebell_Jerk', 'tr', array['İki kettlebell''i clean hareketiyle omuzlarına al: Kettlebell''leri omuzlarına doğru savururken bacaklarını ve kalçanı aç, bu sırada bileklerini avuç içlerin öne bakacak şekilde döndür. Birkaç inç çömel ve hareketi hızla tersine çevirerek iki kettlebell''i de başının üstüne it. Bu ilk itişin hemen ardından yeniden çömel ve kettlebell''lerin altına gir. Kolların kilitlenince dikleşerek egzersizi tamamla.']::text[]),
  ('Two-Arm_Kettlebell_Military_Press', 'tr', array['İki kettlebell''i clean hareketiyle omuzlarına al: Kettlebell''leri omuzlarına doğru savururken bacaklarını ve kalçanı aç, bu sırada bileklerini avuç içlerin öne bakacak şekilde döndür.', 'Kettlebell''leri yukarı ve dışa doğru it. Başının hizasını geçtiklerinde ağırlıklara doğru yaslan; böylece kettlebell''ler başının arkasında dursun. Daha dengeli durmak için kanat, kalça ve karın kaslarını sık.']::text[]),
  ('Two-Arm_Kettlebell_Row', 'tr', array['İki kettlebell''i ayaklarının önüne koy. Dizlerini hafifçe bük, ardından öne eğilip başlangıç pozisyonuna geçerken kalçanı olabildiğince geriye çıkar.', 'İki kettlebell''i de kavra ve karnına doğru çek; bu sırada kürek kemiklerini geriye topla ve dirseklerini bük. Sırtın düz kalsın. İndir ve tekrarla.']::text[]),
  ('Underhand_Cable_Pulldowns', 'tr', array['Üst makarasına geniş bar takılı bir lat pulldown makinesine otur. Makinenin diz yastığını boyuna göre ayarla. Bu yastıklar, bardaki direncin vücudunu yukarı kaldırmasını önler.', 'Barı avuç içlerin gövdene bakacak şekilde tut (supine tutuş). Ellerinin omuz genişliğinden daha dar durduğundan emin ol.', 'İki kolun önünde uzanmış, barı bu tutuş genişliğinde tutarken gövdeni yaklaşık 30 derece geriye yatır; belinde bir kavis oluştur ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun.', 'Nefes verirken omuzlarını ve üst kollarını aşağı ve geriye çekerek barı üst göğsüne değene kadar indir. İpucu: Tam kasılı pozisyona vardığında sırt kaslarını sıkmaya odaklan ve dirseklerini gövdene yakın tut. Barı kendine çekerken üst gövden sabit kalsın, yalnızca kolların hareket etsin. Ön kolların barı tutmaktan başka bir iş yapmasın.', 'Kasılı pozisyonda bir saniye kaldıktan sonra nefes alarak barı yavaşça başlangıç pozisyonuna götür; orada kolların tamamen açık, kanat kasların tamamen gerilmiş olsun.', 'Bu hareketi programında yazan tekrar sayısı kadar yap.']::text[]),
  ('Upper_Back-Leg_Grab', 'tr', array['Otururken öne eğil ve iki kolunla uyluklarını alttan sar.', 'Dizlerin bitişik, bacakların ileri uzanmış kalsın; göğsünü dizlerine doğru indir. Orta sırtını da esnetebilirsin: Dizlerine sarılırken sırtını dizlerinden uzağa doğru çek.']::text[]),
  ('Upper_Back_Stretch', 'tr', array['Başparmakların aşağıyı gösterecek şekilde parmaklarını birbirine kenetle. Ellerini öne uzatırken omuzlarını yuvarla.']::text[]),
  ('Upright_Barbell_Row', 'tr', array['Halteri omuz genişliğinden biraz dar, üstten tutuşla kavra. Bar uyluklarının üst kısmında dursun; kolların uzanmış, dirseklerin hafif bükülü olsun. Sırtın da düz olsun. Bu senin başlangıç pozisyonun.', 'Şimdi nefes ver ve omuzlarının yan kısmını kullanarak barı kaldır; dirseklerin yukarı ve yana doğru çıksın. Kaldırırken barı gövdene yakın tut. Bar neredeyse çenene değene kadar kaldırmayı sürdür. İpucu: Hareketi dirseklerin yönlendirsin ve hep ön kollarından yüksekte olsunlar. Gövdeni sabit tutmayı unutma ve hareketin tepesinde bir saniye bekle.', 'Barı yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes al.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Upright_Cable_Row', 'tr', array['Alt makaraya takılı düz kablo barını, omuz genişliğinden biraz dar, pronasyon tutuşuyla (avuç içleri uyluklarına bakar) kavra. Bar uyluklarının üst kısmında dursun. Kolların uzanmış, dirseklerin hafif bükülü, sırtın düz olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken omuzlarının yan kısmıyla barı kaldır. Yukarı çıkarken bar gövdene yakın olsun. Neredeyse çenene değene kadar kaldırmayı sürdür. İpucu: Hareketi dirseklerin yönlendirsin. Barı kaldırırken dirseklerin hep ön kollarından yüksekte olsun. Ayrıca gövdeni sabit tut ve hareketin tepesinde bir saniye bekle.', 'Barı yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes al.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Upright_Row_-_With_Bands', 'tr', array['Lastik bandın üzerine, gerginlik kolların tam uzanmışken başlayacak şekilde bas. Tutamakları omuz genişliğinden biraz dar, pronasyon tutuşuyla (avuç içleri uyluklarına bakar) kavra. Tutamaklar uyluklarının üst kısmında dursun. Kolların uzanmış, dirseklerin hafif bükülü, sırtın düz olsun. Bu senin başlangıç pozisyonun.', 'Nefes verirken omuzlarının yan kısmıyla tutamakları kaldır. Yukarı çıkarken tutamaklar gövdene yakın olsun. Neredeyse çenene değene kadar kaldırmayı sürdür. İpucu: Hareketi dirseklerin yönlendirsin. Tutamakları kaldırırken dirseklerin hep ön kollarından yüksekte olsun. Ayrıca gövdeni sabit tut ve hareketin tepesinde bir saniye bekle.', 'Tutamakları yavaşça başlangıç pozisyonuna indir. Hareketin bu bölümünde nefes al.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Upward_Stretch', 'tr', array['İki elini de başının üzerine dümdüz uzat, avuç içlerin birbirine değsin.', 'Sırtını düz tutarak ellerini yavaşça yukarı ve geriye doğru it.']::text[]),
  ('V-Bar_Pulldown', 'tr', array['Üst makarasına V-bar takılı bir lat pulldown makinesine otur.', 'Makinenin diz yastığını boyuna göre ayarla. Bu yastıklar, bardaki direncin vücudunu yukarı kaldırmasını önler.', 'V-barı avuç içlerin birbirine bakacak şekilde tut (nötr tutuş). Kanat kaslarını daha iyi çalıştırmak için göğsünü öne çıkar ve hafifçe (yaklaşık 30 derece) geriye yaslan. Bu senin başlangıç pozisyonun.', 'Kanat kaslarını kullanarak barı aşağı çek ve bu sırada kürek kemiklerini sık. Göğsün neredeyse V-bara değene kadar devam et. Bu hareketi yaparken nefes ver. İpucu: Hareket boyunca gövdeni sabit tut.', 'Kasılı pozisyonda bir saniye bekledikten sonra nefes alarak barı yavaşça başlangıç pozisyonuna götür.', 'Programında yazan tekrar sayısı kadar tekrarla.']::text[]),
  ('V-Bar_Pullup', 'tr', array['Önce V-barın ortasını barfiks demirinin ortasına yerleştir (kullandığın barfiks istasyonunda nötr tutuş tutamakları olmadığını varsayarsak). V-barın tutamakları aşağı baksın; böylece tutamaklar sayesinde barfiks demirine asılabilirsin.', 'V-barı sağlamca yerleştirdikten sonra iki yanından tut ve asıl. Kanat kaslarını daha iyi çalıştırmak için göğsünü öne çıkar ve hafifçe geriye yaslan. Bu senin başlangıç pozisyonun.', 'Kanat kaslarını kullanarak gövdeni yukarı çek; barfiks demirine çarpmamak için başını hafifçe geriye yatır. Göğsün neredeyse V-bara değene kadar devam et. Bu hareketi yaparken nefes ver.', 'Kasılı pozisyonda bir saniye bekledikten sonra nefes alarak vücudunu yavaşça başlangıç pozisyonuna indir.', 'Programında yazan tekrar sayısı kadar tekrarla.']::text[]),
  ('Vertical_Swing', 'tr', array['Dambılı iki elinle tut ve kolların uzanmış halde bacaklarının arasında sarkmasına izin ver. Sırtın düz, başın yukarıda olsun.', 'Kalçadan katlanıp dizlerini hafifçe bükerek dambılı bacaklarının arasında savur.', 'Hareketi güçlü bir şekilde tersine çevir: Kalçanı, dizlerini ve ayak bileklerini açarak kendini yukarı fırlat ve dambılı başının üzerine savur.', 'Yere inerken darbeyi bacaklarınla karşıla ve bir sonraki tekrardan önce dambılı gövdene çek.']::text[]),
  ('Walking_Treadmill', 'tr', array['Başlamak için koşu bandına çık ve menüden istediğin seçeneği seç. Çoğu koşu bandında manuel bir ayar vardır, istersen çalıştırılacak bir program da seçebilirsin. Genellikle yaşını ve kilonu girerek egzersiz sırasında yakılan kalori miktarını tahmin ettirebilirsin. Antrenmanın yoğunluğunu değiştirmek için eğimi ayarlayabilirsin.', 'Koşu bantları kolaylık sağlar, kalp ve dolaşım sistemine fayda verir ve çoğunlukla dışarıda yürümeye göre daha az darbe oluşturur. Yürürken ağır aksak değil, orta ile hızlı arası bir tempoda ilerle. Düşük yoğunluklu bir aktivite olduğu için yürüyüş bazı başka aktiviteler kadar kalori yakmaz, ama yine de büyük fayda sağlar. 150 lb ağırlığındaki bir kişi saatte 4 mil hızla 30 dakika yürüyerek yaklaşık 175 kalori yakar; iki kat hızla koşarak ise 450 kalori. Yürürken duruşunu düzgün tut ve tutamaklara yalnızca gerektiğinde tutun; örneğin banttan inerken ya da nabzını kontrol ederken.']::text[]),
  ('Weighted_Ball_Hyperextension', 'tr', array['Başlamak için bir pilates topunun üzerine yüzüstü uzan; gövden topa bastırsın ve yere paralel olsun. Dengeni korumaya yardımcı olması için ayaklarının parmak uçlarındaki tabanı yere bastır. Çenenin altına ya da ensenin arkasına bir ağırlık plakası yerleştir. Bu başlangıç pozisyonu.', 'Belinden bükülerek gövdeni yavaşça yukarı kaldır. Bu hareket sırasında nefes vermeyi unutma.', 'Belindeki kasılmayı bir saniye tut, sonra nefes alarak gövdeni başlangıç pozisyonuna indir.', 'Programında yazan tekrar sayısı kadar tekrarla.']::text[]),
  ('Weighted_Ball_Side_Bend', 'tr', array['Başlamak için gövdenin sol yanı (bel, kalça ve omuz) topa bastıracak şekilde bir pilates topuna uzan.', 'Ayakların yerde olsun; bacakların çapraz dursun ve toptan sarksın. Sağ elinle bir ağırlık plakasını başının hemen sağ yanında tut. İpucu: Plakanın düz yüzünün başına dayandığından emin ol.', 'Sol kolunu gövdenin üzerinden geçir, avuç için yan karın kaslarının üzerinde dursun. Sol ön kolunla üst kolun arasında dik açı olsun. Bu başlangıç pozisyonu.', 'Nefes verirken belinden yana doğru bükülerek gövdenin yanını yukarı kaldır.', 'Kasılmayı bir saniye tut, sonra nefes alarak kendini yavaşça başlangıç pozisyonuna indir.', 'Programındaki tekrar sayısı kadar tekrarla.', 'Taraf değiştir ve egzersizi tekrarla.']::text[]),
  ('Weighted_Bench_Dip', 'tr', array['Bu egzersiz için bir sehpayı arkana, bir başkasını da önüne koyman gerekir. Sehpalar vücuduna dik dururken arkadaki sehpanın kenarına tutun; ellerin gövdene yakın ve omuz genişliğinde açık olsun. Kolların tamamen açık olsun.', 'Bacaklarını öne uzatıp diğer sehpanın üzerine koy. Bacakların yere paralel, gövden ise yere dik olsun. Partnerin dambılı kucağına yerleştirsin. Not: Bu egzersizi bir partnerle yapmak en iyisidir; çünkü ağırlığı yardım almadan kucağa yerleştirmek zor olabilir ve sakatlığa yol açabilir. Bu senin başlangıç pozisyonun.', 'Nefes alırken dirseklerini bükerek vücudunu yavaşça indir; üst kolunla ön kolun arasındaki açı 90 dereceden biraz küçük olana kadar in. İpucu: Hareket boyunca dirseklerini olabildiğince yakın tut. Ön kolların hep aşağıyı göstersin.', 'Nefes verirken triseps kaslarınla gövdeni yukarı iterek başlangıç pozisyonuna dön.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Weighted_Crunches', 'tr', array['Sırtüstü dümdüz uzan; ayak tabanların yerde olsun ya da ayaklarını bir sehpaya koy, dizlerin 90 derecelik açıyla bükülü olsun.', 'Bir ağırlığı göğsüne bastırarak tut ya da kollarını uzatıp gövdenin üzerinde tut. Bu senin başlangıç pozisyonun.', 'Şimdi nefes ver ve omuzlarını yavaşça yerden yuvarlayarak kaldırmaya başla. Omuzların yerden yaklaşık 4 inç yükselsin, belin ise yerde kalsın.', 'Hareketin tepesinde karın kaslarını sık ve kısa bir an bekle.', 'Sonra nefes al ve kendini yavaşça başlangıç pozisyonuna indir.']::text[]),
  ('Weighted_Jump_Squat', 'tr', array['Hafif yüklenmiş bir halteri omuzlarının arka kısmına yerleştir. Bu egzersizde ağırlık yeleği, kum torbası ya da başka türden bir direnç de kullanabilirsin.', 'Ağırlık, seni belirgin biçimde yavaşlatmayacak kadar hafif olsun. Ayakların omuz genişliğinin biraz dışında, başın ve göğsün yukarıda olsun. Bu senin başlangıç pozisyonun.', 'Bir karşı hareketle yarıya kadar çömel ve hemen yön değiştirerek yerden patlayıcı biçimde sıçra; kalçanı, dizlerini ve ayak bileklerini aç. Sıçrayış boyunca duruşunu düzgün tut.', 'Yere dönerken darbeyi bacaklarınla karşıla.']::text[]),
  ('Weighted_Pull_Ups', 'tr', array['Bir dip kemerine ağırlık tak ve kemeri beline sabitle. Barfiks demirini avuç içlerin öne bakacak şekilde tut. Orta genişlikte tutuş için ellerin omuz genişliğinde açık olsun. İki kolun da önünde uzanmış, barı seçtiğin tutuşla tutuyor olsun.', 'Gövdeni yaklaşık 30 derece geriye yatır, belinde bir kavis oluştur ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun.', 'Şimdi nefes ver ve başın ellerinin üstüne çıkana kadar gövdeni yukarı çek. Tepedeki kasılı pozisyona varırken kürek kemiklerini geriye ve aşağıya doğru sıkmaya odaklan.', 'Tepedeki kasılı pozisyonda kısa bir an kaldıktan sonra nefes al ve gövdeni yavaşça başlangıç pozisyonuna indir; kolların açık, kanat kasların tamamen gerilmiş olsun.']::text[]),
  ('Weighted_Sissy_Squat', 'tr', array['Dik dur; ayakların omuz genişliğinde, ayak parmakların yukarı kalkık olsun. Bir elinle squat sehpasının direğine tutun, diğer kolunla göğsünün üst kısmında bir plaka tut. Bu senin başlangıç pozisyonun.', 'Bir kolunla kendini tutarken dizlerini bük; leğen kemiğini ve dizlerini öne götürerek gövdeni yavaşça yere doğru indir. İnerken nefes al ve üst bacağınla alt bacağın neredeyse 90 derecelik açı oluşturduğunda dur. Gerilmiş pozisyonda bir saniye kal.', 'Bir saniyelik bekleyişin ardından uyluk kaslarını kullanarak gövdeni başlangıç pozisyonuna geri getir. Yukarı çıkarken nefes ver.', 'Programındaki sayı kadar tekrarla.']::text[]),
  ('Weighted_Sit-Ups_-_With_Bands', 'tr', array['Önce bantları negatif eğimli sehpanın tabanına bağla. Tutamakları sehpanın iç tarafına doğru koy; böylece uzandığında ikisine de yetişebilirsin.', 'Bacaklarını sehpanın desteklerinden geçirip sabitlenene kadar yerleştir. Şimdi iki elinle lastik bantlara uzan. Tutamakları pronasyon tutuşuyla (avuç içleri öne bakar) kavra. Onları köprücük kemiğinin yakınına getir ve bileğini nötr tutuşa (avuç içleri gövdeye bakar) çevir. Not: Kolların egzersiz boyunca sabit kalsın. Bu başlangıç pozisyonu.', 'Nefes verirken gövdeni yukarı kaldır; üst gövden yere dik gelsin. Kasılmayı bir saniye tut ve nefes alarak üst gövdeni başlangıç pozisyonuna indir.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Weighted_Squat', 'tr', array['Önce iki düz sehpayı aralarında omuz genişliği kadar mesafe bırakarak yerleştir. Üzerlerine çık ve ağırlık kemerini, rahat ettiğin ağırlıkla beline sar. Ayak parmaklarının dışa baktığından emin ol.', 'Dimdik durup ağırlık bacaklarının arasında sarkarken kollarını gövdenin yanında tamamen uzanmış halde tut. Bu başlangıç pozisyonu.', 'Başın yukarıda, duruşun dik kalacak şekilde dizlerini bükmeye başla. Üst bacakla baldırlar arasındaki açı 90 dereceden biraz küçük olana kadar in (bu, üst bacakların yere paralelin altına indiği noktadır). Hareketin bu bölümünde nefes al. İpucu: Egzersizi doğru yaptıysan dizlerinin önü, ayak parmaklarınla birlikte öne dik, hayali bir düz çizgi oluşturur. Dizlerin bu hayali çizgiyi geçiyorsa (ayak parmaklarını aşıyorsa) dizine gereksiz yük bindiriyorsun ve egzersiz yanlış yapılmış demektir.', 'Ağırlıklı olarak ayak tabanının ön kısmıyla sehpanın yüzeyini iterek vücudunu yeniden yukarı kaldır; bacaklarını düzelt ve başlangıç pozisyonuna dön. Egzersizin bu bölümünde nefes ver.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Wide-Grip_Barbell_Bench_Press', 'tr', array['Düz bir sehpaya sırtüstü uzan, ayakların yere sağlam bassın. Barı geniş, pronasyon tutuşuyla (avuç içleri öne bakar), her elin omuz genişliğinden yaklaşık 3 inç dışarıda olacak şekilde kavra. Barı askıdan kaldır ve kolların kilitli halde tam üzerinde tut. Bar gövdene ve yere dik olur. Bu senin başlangıç pozisyonun.', 'Nefes alırken yavaşça in; barı orta göğsünde hissedene kadar devam et.', 'Bir saniye durakladıktan sonra nefes vererek ve göğüs kaslarınla iterek barı başlangıç pozisyonuna geri getir. Kollarını kilitle ve kasılı pozisyonda göğsünü sık, bir saniye tut ve sonra yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmelidir.', 'Hareketi programında yazan tekrar sayısı kadar yap.']::text[]),
  ('Wide-Grip_Decline_Barbell_Bench_Press', 'tr', array['Negatif eğimli bir sehpaya sırtüstü uzan, ayakların sehpanın ön kısmında sağlamca sabitlenmiş olsun. Barı geniş, pronasyon tutuşuyla (avuç içleri öne bakar), her elin omuz genişliğinden yaklaşık 3 inç dışarıda olacak şekilde kavra. Barı askıdan kaldır ve kolların kilitli halde tam üzerinde tut. Bar gövdene ve yere dik olur. Bu senin başlangıç pozisyonun.', 'Nefes alırken yavaşça in; barı alt göğsünde hissedene kadar devam et.', 'Bir saniye durakladıktan sonra nefes vererek ve göğüs kaslarınla iterek barı başlangıç pozisyonuna geri getir. Kollarını kilitle ve kasılı pozisyonda göğsünü sık, bir saniye tut ve sonra yeniden yavaşça inmeye başla. İpucu: İniş, çıkışın en az iki katı kadar sürmelidir.', 'Hareketi programında yazan tekrar sayısı kadar yap.']::text[]),
  ('Wide-Grip_Decline_Barbell_Pullover', 'tr', array['Negatif eğimli bir sehpaya uzan, iki bacağın da yerine sağlamca sabitlenmiş olsun. Başının arkasındaki haltere uzan ve onu pronasyon tutuşuyla (avuç içleri dışa bakar) kavra. Bu egzersizde halteri omuz genişliğinden daha geniş tuttuğundan emin ol. Kollarını kullanarak halteri yavaşça yerden kaldır.', 'Doğru konumdayken kolların tamamen açık ve yere dik olur. Bu başlangıç pozisyonu.', 'Halteri yere koyacakmış gibi yarım daire çizerek yeniden aşağı götürmeye başla; ama yere koymak yerine kolların yere paralel olduğunda dur. İpucu: Kollarını her an tamamen açık tut. Hareket yalnızca omuz ekleminde gerçekleşmeli. Hareketin bu bölümünde nefes al.', 'Şimdi nefes vererek halteri yukarı getir ve başlangıç pozisyonuna dön. Halteri her an tam kontrol altında tutmayı unutma.', 'Hareketi antrenman programında yazan tekrar sayısı kadar yap.', 'Setini bitirdiğinde halteri başınla aynı hizaya gelene kadar yavaşça indir ve bırak.']::text[]),
  ('Wide-Grip_Lat_Pulldown', 'tr', array['Üst makarasına geniş bar takılı bir lat pulldown makinesine otur. Makinenin diz yastığını boyuna göre ayarlamayı unutma. Bu yastıklar, bardaki direncin vücudunu yukarı kaldırmasını önler.', 'Barı avuç içlerin öne bakacak şekilde, sana verilen tutuşla kavra. Tutuşlar hakkında not: Geniş tutuşta ellerin arasındaki mesafe omuz genişliğinden fazla olmalı. Orta tutuşta bu mesafe omuz genişliğine eşit, dar tutuşta ise omuz genişliğinden küçük olmalı.', 'İki kolun önünde uzanmış, barı seçtiğin tutuş genişliğinde tutarken gövdeni yaklaşık 30 derece geriye yatır; belinde bir kavis oluştur ve göğsünü öne çıkar. Bu senin başlangıç pozisyonun.', 'Nefes verirken omuzlarını ve üst kollarını aşağı ve geriye çekerek barı üst göğsüne değene kadar indir. İpucu: Tam kasılı pozisyona vardığında sırt kaslarını sıkmaya odaklan. Üst gövden sabit kalsın, yalnızca kolların hareket etsin. Ön kolların barı tutmaktan başka bir iş yapmasın; bu yüzden barı ön kollarınla aşağı çekmeye çalışma.', 'Kasılı pozisyonda kürek kemiklerini birbirine doğru sıkarak bir saniye kaldıktan sonra barı yavaşça başlangıç pozisyonuna yükselt; orada kolların tamamen açık, kanat kasların tamamen gerilmiş olsun. Hareketin bu bölümünde nefes al.', 'Bu hareketi programında yazan tekrar sayısı kadar yap.']::text[]),
  ('Wide-Grip_Pulldown_Behind_The_Neck', 'tr', array['Lat pulldown istasyonunun üst makarasına geniş bir bar tak ve otur. Diz yastığını boyuna göre ayarla. Bu yastık, bardaki ağırlığın seni oturaktan kaldırmasını engeller.', 'Barı sana verilen tutuş genişliğinde, avuçların öne bakacak şekilde tut. Not: Geniş tutuşta eller omuzlardan daha açık durur. Orta tutuşta eller omuz genişliğindedir, dar tutuşta ise omuz genişliğinden daha yakındır.', 'İki kolun düz, ellerin seçtiğin genişlikte bardayken gövdeni ve başını öne eğ. Barın ortasından ensene inen bir çizgi hayal et. Bu senin başlangıç pozisyonun.', 'Nefes ver ve barı ensene değene kadar indir. Bunu omuzlarını ve üst kollarını aşağı ve geriye çekerek yap. İpucu: Bar en alta geldiğinde sırt kaslarını sıkmaya odaklan. Üst gövden sabit kalsın, yalnızca kolların hareket etsin. Ön kolların tek işi barı tutmak, bu yüzden barı ön kollarınla çekmeye çalışma.', 'Kürek kemiklerini birbirine sıkarak bir saniye altta kal. Sonra nefes alırken barı yavaşça yukarı bırak. Kolların tam düz, kanat kasların tam gergin olduğunda başlangıç pozisyonundasın.', 'Hareketi sana verilen tekrar sayısı kadar yinele.']::text[]),
  ('Wide-Grip_Rear_Pull-Up', 'tr', array['Barfiks barını geniş tutuşla, avuçların öne bakacak şekilde kavra.', 'Kolların düz şekilde bara asıl. Gövdeni ve başını öne getir, öyle ki bardan ensene inen bir çizgi hayal edebilesin. Bu senin başlangıç pozisyonun.', 'Bar ensene yaklaşana kadar kendini yukarı çek. Bunun için omuzlarını ve üst kollarını aşağı ve geriye çek, başını da hafifçe öne eğ. Hareketin bu kısmında nefes ver. İpucu: En üste vardığında sırt kaslarını sıkmaya odaklan. Üst gövden yukarı çıkarken dik ve sabit kalsın, yalnızca kolların çalışsın. Ön kolların barı tutmaktan başka bir iş yapmasın.', 'Üstte bir saniye kal. Sonra nefes almaya başla ve kendini yavaşça indir. Kolların tam düz, kanat kasların tam gergin olduğunda başlangıç pozisyonundasın.', 'Hareketi sana verilen tekrar sayısı kadar yinele.']::text[]),
  ('Wide-Grip_Standing_Barbell_Curl', 'tr', array['Gövden dik şekilde ayakta dur ve halteri dış taraftaki geniş tutuş yerinden kavra. Avuçların öne baksın. Dirseklerin gövdene yakın dursun. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve bisepsini kasarak barı öne ve yukarı doğru kaldır. İpucu: Yalnızca ön kolların hareket etsin.', 'Bar omuz hizasına gelene ve bisepsin tam kasılana kadar devam et. Bu noktada bir saniye bekle ve bisepsini iyice sık.', 'Nefes alırken barı yavaşça başlangıç pozisyonuna indir.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Wide_Stance_Barbell_Squat', 'tr', array['Güvenlik açısından bu egzersizi squat kafesinin içinde yapmak en iyisidir. Başlarken barı, boyuna en uygun yükseklikteki askıya yerleştir. Doğru yüksekliği seçip barı yükledikten sonra barın altına gir ve onu omuzlarının arka kısmına (ensenin biraz altına) yerleştir.', 'Barı iki yanından iki elinle tut; önce bacaklarınla iterek ve aynı anda gövdeni dikleştirerek barı askıdan kaldır.', 'Askıdan uzaklaş ve bacaklarını omuz genişliğinden daha açık, ayak parmakların hafifçe dışa dönük olacak şekilde yerleştir. Başını her zaman yukarıda tut, çünkü aşağı bakmak dengeni bozar; sırtını da düz tut. Bu senin başlangıç pozisyonun.', 'Başın yukarıda, duruşun dik kalacak şekilde dizlerini bükerek barı yavaşça indirmeye başla. Üst bacakla baldırlar arasındaki açı 90 dereceden biraz küçük olana kadar in (bu, üst bacakların yere paralelin altına indiği noktadır). Hareketin bu bölümünde nefes al. İpucu: Egzersizi doğru yaptıysan dizlerinin önü, ayak parmaklarınla birlikte öne dik, hayali bir düz çizgi oluşturur. Dizlerin bu hayali çizgiyi geçiyorsa (ayak parmaklarını aşıyorsa) dizine gereksiz yük bindiriyorsun ve egzersiz yanlış yapılmış demektir.', 'Nefes verirken topuklarınla yeri iterek barı kaldırmaya başla; bacaklarını düzelt ve başlangıç pozisyonuna dön.', 'Programındaki tekrar sayısı kadar tekrarla.']::text[]),
  ('Wide_Stance_Stiff_Legs', 'tr', array['Yüklü bir halter yerde dururken başla. Ayaklarını geniş aç, ardından kalçadan eğilerek barı kavra. Kalçan olabildiğince geride, bacakların neredeyse düz olsun. Sırtını düz, başını ve göğsünü yukarıda tut. Bu senin başlangıç pozisyonun.', 'Hareketi kalçanı devreye sokarak başlat: Kollarının dümdüz sarkmasına izin verirken kalçanı öne it. Dimdik ayakta durana kadar devam et, sonra ağırlığı yavaşça başlangıç pozisyonuna döndür. Sonraki tekrarlarda ağırlığın yere değmesi gerekmez.']::text[]),
  ('Wind_Sprints', 'tr', array['Barfiks barına üstten tutuşla asıl. Kolların ve bacakların düz olsun. Bu senin başlangıç pozisyonun.', 'İlk olarak bir dizini hızla, çıkabildiği kadar yukarı çek. Gövdeni ya da bacaklarını sallama.', 'Hiç beklemeden o bacağı başlangıç pozisyonuna geri indir. Aynı anda diğer dizini olabildiğince yukarı çek.', 'Set bitene kadar bacak değiştirerek devam et.']::text[]),
  ('Windmills', 'tr', array['Sırtüstü uzan, bacakların düz, kolların iki yana açık olsun. Bu senin başlangıç pozisyonun.', 'Bir bacağını kaldır ve hızla gövdenin üzerinden karşı tarafa geçir. Ayağınla karşı elinin yakınında yere dokunmaya çalış.', 'Başlangıç pozisyonuna dön ve aynısını diğer bacağınla yap. 10-20 tekrar boyunca bacak değiştirerek devam et.']::text[]),
  ('Worlds_Greatest_Stretch', 'tr', array['Bu esneme üç bölümden oluşur. Önce öne doğru bir hamle adımı at: öndeki ayağın tabanı tamamen yerde, arkadaki ayağın parmak ucunda olsun. İki dizini bük ve arka dizin yere neredeyse değene kadar alçal. Gövdeni dik tut ve bu pozisyonda 10-20 saniye kal.', 'Şimdi öndeki bacağınla aynı taraftaki kolunu yere indir, dirseğin ayağının yanında olsun. Diğer elini öndeki bacağına paralel şekilde yere koy. Bu el, esnemenin bu bölümünde sana destek olur.', '10-20 saniye sonra ellerini öndeki ayağının iki yanına koy. Bu ayağın parmaklarını yerden kaldır ve bacağını düzelt. Bunun için arka bacağının yerini değiştirmen gerekebilir. 10-20 saniye bekle, sonra bütün sırayı diğer taraf için yinele.']::text[]),
  ('Wrist_Circles', 'tr', array['Ayakların omuz genişliğinde açık, dik dur. Kollarını yanlara doğru kaldır: tam düz, omuz hizasında ve yere paralel olsunlar. İpucu: Gövden ve kolların birlikte "T" harfini oluşturmalı. Avuçların aşağı baksın. Bu senin başlangıç pozisyonun.', 'Bileklerin dışında bütün vücudunu sabit tut ve iki bileğini öne doğru daireler çizerek çevir. İpucu: Ellerin fırçaymış da daire çiziyormuşsun gibi düşün. Egzersiz boyunca normal nefes al.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Wrist_Roller', 'tr', array['Dik dur ve bilek silindirini üstten tutuşla, avuçların aşağı bakacak şekilde kavra. Ayakların omuz genişliğinde açık olsun.', 'İki kolunu yavaşça önüne kaldır. Kolların tam düz ve yere paralel olsun. Not: İpin silindire sarılı olmadığından emin ol. Ön kolların dışında bütün vücudun sabit kalsın. Bu senin başlangıç pozisyonun.', 'Bileklerini sırayla yukarı doğru çevir. Böylece ip silindire sarılır ve ağırlık bara kadar yükselir.', 'Ağırlık bara ulaşınca bileklerini aşağı doğru çevir ve ağırlığı başlangıç pozisyonuna gelene kadar yavaşça indir.', 'Programında yazan tekrar sayısı kadar yap.']::text[]),
  ('Wrist_Rotations_with_Straight_Bar', 'tr', array['Halteri iki elinle, avuçların aşağı bakacak şekilde tut. Ellerin aşağı yukarı omuz genişliğinde açık olsun. Bu senin başlangıç pozisyonun.', 'Gazete rulo yapar gibi, bir bileğini sonra diğerini geriye doğru bük. Tükenene kadar elden ele geçerek devam et.', 'Şimdi hareketi tersine çevir: bileklerini içe doğru bük ve barı ters yöne çevir. Yine tükenene kadar el değiştirerek devam et.']::text[]),
  ('Yoke_Walk', 'tr', array['Bu egzersiz çoğunlukla yoke adı verilen bir taşıma çerçevesiyle yapılır. Bazen buzdolabı ya da başka ağır eşyalarla yapıldığı da görülür.', 'Önce çerçeveyi omuzlarının arka kısmına yerleştir. Karşıya bak, sırtını çukurlaştır ve topuklarından güç alarak çerçeveyi kaldır.', 'Kısa ve seri adımlarla olabildiğince hızlı yürümeye başla. Çerçeveyi dengede ve yerinde tutmak için yan direklerinden tutabilirsin. Belirlenen mesafeyi, çoğunlukla 75-100 feet, elinden geldiğince hızlı tamamla.']::text[]),
  ('Zercher_Squats', 'tr', array['Güvenlik için bu egzersizi squat sehpasının içinde yapman en iyisidir. Önce barı sehpada boyuna en uygun yüksekliğe yerleştir: belinin üstünde, göğsünün altında bir yer doğru yüksekliktir. Yükseklik ayarlanıp bara ağırlık takıldıktan sonra ellerini kenetle ve barı dirseğinin iç kısmına, ön kolunla üst kolunun arasına al.', 'Barı kaldır, ağırlığı ön kollarının üstünde dursun. Doğru tutuyorsan, kollarını kavuşturmuşsun da üzerlerinden bir bar geçiyormuş gibi görünür.', 'Sehpadan uzaklaş ve ayaklarını omuz genişliğinde, orta açıklıkta bir duruşa getir. Ayak uçların hafifçe dışa baksın. Başını her zaman yukarıda tut, çünkü aşağı bakmak dengeni bozar. Sırtını da düz tut. Bu senin başlangıç pozisyonun. Not: Burada anlatılan orta duruş bacakları genel olarak geliştirir, ama üç duruştan istediğini seçebilirsin.', 'Dizlerini bükerek barı indirmeye başla. Bu sırada dik dur ve başını yukarıda tut. Üst bacağınla baldırın arasındaki açı 90 dereceden biraz küçük olana kadar in. Bu, üst bacaklarının yere paralel çizginin altına indiği noktadır. Hareketin bu kısmında nefes al. İpucu: Egzersizi doğru yaptıysan dizlerinin ön yüzü ile ayak parmakların, öne dik duran hayali bir düz çizgi üzerinde olur. Dizlerin bu çizgiyi, yani ayak parmaklarını geçerse dizine gereksiz yük bindirirsin ve egzersizi yanlış yapmış olursun.', 'Nefes verirken barı yeniden kaldır: yeri en çok ayak tabanının ön kısmıyla it, bacaklarını düzelt ve başlangıç pozisyonuna dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Zottman_Curl', 'tr', array['Gövden dik şekilde ayakta dur. İki elinde birer dambıl olsun, kolların düz şekilde aşağı sarksın. Dirseklerin gövdene yakın dursun.', 'Avuçlarının birbirine baktığından emin ol. Bu senin başlangıç pozisyonun.', 'Üst kollarını sabit tut, nefes ver ve bisepsini kasarak dambılları kaldır. Yalnızca ön kolların hareket etsin. Kaldırırken bileklerini çevir ve supine tutuşa, yani avuçların yukarı bakacak şekle geç. Dambıllar omuz hizasına gelene ve bisepsin tam kasılana kadar devam et.', 'Bu noktada bir saniye bekle ve bisepsini sık.', 'Hâlâ üstteyken bileklerini çevir ve prone tutuşa, yani avuçların aşağı bakacak şekle geç. Başparmağın serçe parmağından daha yukarıda olsun.', 'Dambılları bu prone tutuşla yavaşça indir.', 'Dambıllar uyluklarına yaklaşınca bileklerini çevirmeye başla ve nötr tutuşa, yani avuçların vücuduna bakacak şekle dön.', 'Önerilen tekrar sayısı kadar yap.']::text[]),
  ('Zottman_Preacher_Curl', 'tr', array['İki eline birer dambıl al ve üst kollarını Scott sehpasının ya da eğimli sehpanın yastığına yerleştir. Dirseklerin bükülü, dambıllar omuz hizasında olsun. Avuçların aşağı baksın. Bu senin başlangıç pozisyonun.', 'Nefes alırken dambılları avuçların aşağı bakar hâlde yavaşça indir. Kolların düzelene ve bisepsin tam gerilene kadar devam et.', 'Hareketin en alt noktasında bileklerini çevir, avuçların yukarı baksın.', 'Nefes verirken bisepsinin gücüyle dambılları kaldır. Kasın tam kasılana ve dambıllar omuz hizasına gelene kadar devam et. Yine unutma: tam kasılma için serçe parmağın başparmağından daha yukarıda olmalı.', 'Üstte bisepsini bir saniye iyice sık, sonra bileklerini çevirerek avuçlarını yeniden aşağı baktır.', 'Önerilen tekrar sayısı kadar yap.']::text[])
